function tokenSummaryPreviewRecord(record, keys) {
  if (!record || typeof record !== "object" || Array.isArray(record)) {
    return record;
  }
  const preview = {};
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(record, key)) {
      preview[key] = record[key];
    }
  }
  return preview;
}

function tokenSummaryMarketPreviewRecord(
  record,
  { includeNestedListings = false } = {},
) {
  const preview = tokenSummaryPreviewRecord(
    record,
    TOKEN_SUMMARY_MARKET_PREVIEW_KEYS,
  );
  if (!includeNestedListings || !preview || typeof preview !== "object") {
    return preview;
  }
  for (const key of ["closedListing", "listing"]) {
    if (Object.prototype.hasOwnProperty.call(record, key)) {
      preview[key] = tokenSummaryPreviewRecord(
        record[key],
        TOKEN_SUMMARY_NESTED_LISTING_PREVIEW_KEYS,
      );
    }
  }
  return preview;
}

function recentClosedTokenListings(items, limit = SUMMARY_MARKET_LIMIT) {
  const eventTime = (item) => {
    const parsed = Date.parse(String(item?.closedAt ?? item?.createdAt ?? ""));
    return Number.isFinite(parsed) ? parsed : 0;
  };
  return (Array.isArray(items) ? items : [])
    .slice()
    .sort(
      (left, right) =>
        eventTime(right) - eventTime(left) ||
        Number(Boolean(right?.closedConfirmed)) -
          Number(Boolean(left?.closedConfirmed)) ||
        compareCanonicalUtf8(
          right?.closedTxid ?? right?.listingId,
          left?.closedTxid ?? left?.listingId,
        ),
    )
    .slice(0, Math.max(0, limit));
}

const WORK_Q16_SUMMARY_UNIT_PRICE_MODEL =
  "exact-work-q16-sats-per-unit-ratio-v1";

function tokenSummaryWorkAmountStorageModel(payload) {
  const workDefinitions = (Array.isArray(payload?.tokens)
    ? payload.tokens
    : []
  ).filter((token) => isWorkTokenId(token?.tokenId));
  if (workDefinitions.length === 0) {
    return "";
  }

  const exactModel = exactWorkAmountStorageModelFromState(payload);
  if (exactModel) {
    return exactModel;
  }

  const claimsQ16 =
    payload?.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL ||
    payload?.precisionModel === WORK_PRECISION_V2_MODEL ||
    workDefinitions.some((token) => workRecordUsesSubatoms(token));
  if (claimsQ16) {
    throw new Error(
      "WORK token summary has incomplete or conflicting Q16 precision metadata.",
    );
  }

  // Historical token snapshots can predate explicit Q8 metadata. They remain
  // legacy atomic state until an exact Q16 precision declaration is present.
  return WORK_ATOMIC_PROJECTION_MODEL;
}

function canonicalUnsignedDecimalText(value, maximumFractionDigits) {
  const text = String(value ?? "");
  const match = /^(0|[1-9][0-9]*)(?:\.([0-9]+))?$/u.exec(text);
  if (
    !match ||
    !Number.isSafeInteger(maximumFractionDigits) ||
    maximumFractionDigits < 0 ||
    String(match[2] ?? "").length > maximumFractionDigits
  ) {
    return "";
  }
  const fraction = String(match[2] ?? "").replace(/0+$/u, "");
  return `${match[1]}${fraction ? `.${fraction}` : ""}`;
}

function roundedUnsignedRatioDecimalText(
  numerator,
  denominator,
  maximumFractionDigits,
) {
  if (
    typeof numerator !== "bigint" ||
    typeof denominator !== "bigint" ||
    numerator < 0n ||
    denominator <= 0n ||
    !Number.isSafeInteger(maximumFractionDigits) ||
    maximumFractionDigits < 0
  ) {
    return "";
  }
  const decimalScale = 10n ** BigInt(maximumFractionDigits);
  const rounded =
    (numerator * decimalScale + denominator / 2n) / denominator;
  const whole = rounded / decimalScale;
  const fraction = String(rounded % decimalScale)
    .padStart(maximumFractionDigits, "0")
    .replace(/0+$/u, "");
  return `${whole}${fraction ? `.${fraction}` : ""}`;
}

function workQ16SummaryUnitPriceDescriptor(priceSats, amountSubatoms) {
  const priceText = canonicalNonNegativeIntegerText(priceSats, {
    allowZero: false,
  });
  const amountText = canonicalWorkSubatomsText(amountSubatoms);
  if (!priceText || !amountText) {
    return null;
  }
  const numerator = BigInt(priceText) * WORK_SUBATOM_UNIT_SCALE;
  const denominator = BigInt(amountText);
  const decimal = roundedUnsignedRatioDecimalText(
    numerator,
    denominator,
    WORK_SUBATOM_DECIMALS,
  );
  if (!decimal) {
    return null;
  }
  return {
    amountSubatoms: amountText,
    decimal,
    denominator: amountText,
    model: WORK_Q16_SUMMARY_UNIT_PRICE_MODEL,
    numerator: numerator.toString(),
    priceSats: priceText,
    unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
  };
}

function canonicalWorkQ16SummaryUnitPriceDescriptor(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null;
  }
  const canonical = workQ16SummaryUnitPriceDescriptor(
    value.priceSats,
    value.amountSubatoms,
  );
  return canonical &&
      value.decimal === canonical.decimal &&
      value.denominator === canonical.denominator &&
      value.model === canonical.model &&
      value.numerator === canonical.numerator &&
      value.unitScale === canonical.unitScale
    ? canonical
    : null;
}

function workQ16PayloadWithoutOrphanPriceAliases(payload, tokenScope = "") {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return payload;
  }
  const payloadWorkQ16 =
    normalizeTokenScope(tokenScope) === WORK_TOKEN_ID &&
    (payload.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL ||
      payload.precisionModel === WORK_PRECISION_V2_MODEL ||
      payload.workDefaults?.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL);
  const tokens = Array.isArray(payload.tokens) ? payload.tokens : [];
  if (tokens.length === 0) {
    return payload;
  }
  let changed = false;
  const normalizedTokens = tokens.map((token) => {
    if (!isWorkTokenId(token?.tokenId)) {
      return token;
    }
    const tokenWorkQ16 =
      payloadWorkQ16 ||
      token?.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL ||
      token?.precisionModel === WORK_PRECISION_V2_MODEL ||
      String(token?.unitScale ?? "") === WORK_SUBATOM_UNIT_SCALE_TEXT;
    if (!tokenWorkQ16) {
      return token;
    }
    let next = token;
    const normalizePriceAlias = (aliasKey, exactKey) => {
      const exact = canonicalWorkQ16SummaryUnitPriceDescriptor(
        token?.[exactKey],
      );
      if (exact) {
        if (
          token?.[aliasKey] === exact.decimal &&
          token?.[exactKey] === exact
        ) {
          return;
        }
        if (next === token) {
          next = { ...token };
        }
        next[aliasKey] = exact.decimal;
        next[exactKey] = exact;
        return;
      }
      if (
        Object.prototype.hasOwnProperty.call(token, aliasKey) ||
        Object.prototype.hasOwnProperty.call(token, exactKey)
      ) {
        if (next === token) {
          next = { ...token };
        }
        delete next[aliasKey];
        delete next[exactKey];
      }
    };
    normalizePriceAlias("lastSalePricePerToken", "lastSalePricePerTokenExact");
    normalizePriceAlias(
      "lowestAskPricePerToken",
      "lowestAskPricePerTokenExact",
    );
    if (next !== token) {
      changed = true;
    }
    return next;
  });
  return changed ? { ...payload, tokens: normalizedTokens } : payload;
}

function compareWorkQ16SummaryUnitPrices(left, right) {
  const leftCanonical = canonicalWorkQ16SummaryUnitPriceDescriptor(left);
  const rightCanonical = canonicalWorkQ16SummaryUnitPriceDescriptor(right);
  if (!leftCanonical || !rightCanonical) {
    throw new TypeError("WORK Q16 summary price ratio is noncanonical.");
  }
  const leftCross =
    BigInt(leftCanonical.numerator) * BigInt(rightCanonical.denominator);
  const rightCross =
    BigInt(rightCanonical.numerator) * BigInt(leftCanonical.denominator);
  return leftCross < rightCross ? -1 : leftCross > rightCross ? 1 : 0;
}

function tokenAggregateSummaries(payload) {
  const tokens = Array.isArray(payload.tokens) ? payload.tokens : [];
  const workAmountStorageModel =
    tokenSummaryWorkAmountStorageModel(payload);
  const summaries = new Map(
    tokens.map((token) => {
      const supplyZero = tokenLedgerZero(token.tokenId);
      return [token.tokenId, {
        balances: new Map(),
        confirmedMints: 0,
        confirmedOpenListings: 0,
        confirmedSales: 0,
        confirmedSalesVolumeSats: 0,
        confirmedSupply: supplyZero,
        holderCount: 0,
        lastSalePricePerToken: 0,
        lowestAskPricePerToken: 0,
        openListings: 0,
        pendingMints: 0,
        pendingOpenListings: 0,
        pendingSales: 0,
        pendingSalesVolumeSats: 0,
        pendingSupply: supplyZero,
        transferCount: 0,
      }];
    }),
  );
  const addBalance = (tokenId, address, amount) => {
    if (
      !tokenId ||
      !address ||
      amount === null ||
      (typeof amount === "number" && !Number.isFinite(amount)) ||
      amount === tokenLedgerZero(tokenId)
    ) {
      return;
    }

    const current = summaries.get(tokenId);
    if (!current) {
      return;
    }

    current.balances.set(
      address,
      (current.balances.get(address) ?? tokenLedgerZero(tokenId)) + amount,
    );
  };

  for (const mint of Array.isArray(payload.mints) ? payload.mints : []) {
    const current = summaries.get(mint.tokenId);
    if (!current) {
      continue;
    }
    const amount = tokenLedgerAmountFromRecord(mint.tokenId, mint, {
      ...(isWorkTokenId(mint.tokenId)
        ? { workAmountStorageModel }
        : {}),
    });
    if (amount === null) {
      continue;
    }
    if (mint.confirmed) {
      current.confirmedMints += 1;
      current.confirmedSupply += amount;
      addBalance(mint.tokenId, mint.minterAddress, amount);
    } else {
      current.pendingMints += 1;
      current.pendingSupply += amount;
    }
  }

  for (const transfer of Array.isArray(payload.transfers) ? payload.transfers : []) {
    const current = summaries.get(transfer.tokenId);
    if (!current) {
      continue;
    }

    current.transferCount += 1;
    if (!transfer.confirmed) {
      continue;
    }
    const amount = tokenLedgerAmountFromRecord(
      transfer.tokenId,
      transfer,
      {
        ...(isWorkTokenId(transfer.tokenId)
          ? { workAmountStorageModel }
          : {}),
      },
    );
    if (amount === null) {
      continue;
    }

    addBalance(transfer.tokenId, transfer.senderAddress, -amount);
    addBalance(transfer.tokenId, transfer.recipientAddress, amount);
  }

  for (const sale of Array.isArray(payload.sales) ? payload.sales : []) {
    const current = summaries.get(sale.tokenId);
    if (!current) {
      continue;
    }
    if (sale.confirmed) {
      current.confirmedSales += 1;
      current.confirmedSalesVolumeSats += numericValue(sale.priceSats);
    } else {
      current.pendingSales += 1;
      current.pendingSalesVolumeSats += numericValue(sale.priceSats);
      continue;
    }
    const amount = canonicalTokenSaleLedgerAmount(sale.tokenId, sale, {
      ...(isWorkTokenId(sale.tokenId)
        ? { workAmountStorageModel }
        : {}),
    });
    if (amount === null) {
      continue;
    }

    addBalance(sale.tokenId, sale.sellerAddress, -amount);
    addBalance(sale.tokenId, sale.buyerAddress, amount);
    if (
      isWorkTokenId(sale.tokenId) &&
      workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
    ) {
      if (!current.lastSalePricePerTokenExact) {
        const exactPrice = workQ16SummaryUnitPriceDescriptor(
          sale.priceSats,
          amount,
        );
        if (exactPrice) {
          current.lastSalePricePerToken = exactPrice.decimal;
          current.lastSalePricePerTokenExact = exactPrice;
        }
      }
    } else {
      const displayAmount = tokenLedgerApproximateNumber(
        sale.tokenId,
        amount,
        {
          ...(isWorkTokenId(sale.tokenId)
            ? { workAmountStorageModel }
            : {}),
        },
      );
      if (current.lastSalePricePerToken === 0 && displayAmount > 0) {
        current.lastSalePricePerToken = sale.priceSats / displayAmount;
      }
    }
  }

  for (const listing of Array.isArray(payload.listings) ? payload.listings : []) {
    const current = summaries.get(listing.tokenId);
    if (!current) {
      continue;
    }

    current.openListings += 1;
    if (listing.confirmed) {
      current.confirmedOpenListings += 1;
    } else {
      current.pendingOpenListings += 1;
    }
    if (!tokenListingHasConfirmedSaleTicketSeal(listing)) {
      continue;
    }

    const amount = tokenLedgerAmountFromRecord(
      listing.tokenId,
      listing,
      {
        ...(isWorkTokenId(listing.tokenId)
          ? { workAmountStorageModel }
          : {}),
      },
    );
    if (
      isWorkTokenId(listing.tokenId) &&
      workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
    ) {
      if (amount === null) {
        continue;
      }
      const exactAsk = workQ16SummaryUnitPriceDescriptor(
        listing.priceSats,
        amount,
      );
      if (
        exactAsk &&
        (!current.lowestAskPricePerTokenExact ||
          compareWorkQ16SummaryUnitPrices(
            exactAsk,
            current.lowestAskPricePerTokenExact,
          ) < 0)
      ) {
        current.lowestAskPricePerToken = exactAsk.decimal;
        current.lowestAskPricePerTokenExact = exactAsk;
      }
    } else {
      const displayAmount =
        amount === null
          ? 0
          : tokenLedgerApproximateNumber(listing.tokenId, amount, {
              ...(isWorkTokenId(listing.tokenId)
                ? { workAmountStorageModel }
                : {}),
            });
      const ask = displayAmount > 0 ? listing.priceSats / displayAmount : 0;
      if (ask > 0) {
        current.lowestAskPricePerToken =
          current.lowestAskPricePerToken > 0
            ? Math.min(current.lowestAskPricePerToken, ask)
            : ask;
      }
    }
  }

  for (const [tokenId, summary] of summaries) {
    summary.holderCount = [...summary.balances.values()].filter(
      (balance) => balance > 0,
    ).length;
    const confirmedSupplyUnits = summary.confirmedSupply;
    const pendingSupplyUnits = summary.pendingSupply;
    summary.confirmedSupply = tokenLedgerSupplyValue(
      tokenId,
      confirmedSupplyUnits,
      {
        ...(isWorkTokenId(tokenId)
          ? { workAmountStorageModel }
          : {}),
      },
    );
    summary.pendingSupply = tokenLedgerSupplyValue(
      tokenId,
      pendingSupplyUnits,
      {
        ...(isWorkTokenId(tokenId)
          ? { workAmountStorageModel }
          : {}),
      },
    );
    if (
      isWorkTokenId(tokenId) &&
      workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
    ) {
      summary.amountStorageModel = WORK_SUBATOM_PROJECTION_MODEL;
      summary.confirmedSupplySubatoms = confirmedSupplyUnits.toString();
      summary.decimals = WORK_SUBATOM_DECIMALS;
      summary.pendingSupplySubatoms = pendingSupplyUnits.toString();
      summary.precisionModel = WORK_PRECISION_V2_MODEL;
      summary.unitScale = WORK_SUBATOM_UNIT_SCALE_TEXT;
    }
    delete summary.balances;
  }

  return summaries;
}

function tokenSummaryMetricValue(value) {
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : undefined;
}

function tokenSummarySupplyMetricValue(
  tokenId,
  value,
  { workAmountStorageModel = "" } = {},
) {
  if (
    isWorkTokenId(tokenId) &&
    workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
  ) {
    try {
      const subatoms = parseWorkAmountToSubatoms(value, {
        allowZero: true,
        maxSubatoms: WORK_TOKEN_MAX_SUPPLY_SUBATOMS,
      });
      return formatWorkSubatoms(subatoms);
    } catch {
      return undefined;
    }
  }
  if (!isBondTokenId(tokenId)) {
    return tokenSummaryMetricValue(value);
  }
  try {
    return canonicalIntegerText(value, { allowZero: true }) || undefined;
  } catch {
    return undefined;
  }
}

function mergedTokenSummaryMetric(
  token,
  summary,
  key,
  preserveExisting,
  { workAmountStorageModel = "" } = {},
) {
  const isSupply = key === "confirmedSupply" || key === "pendingSupply";
  const q16WorkPrice =
    isWorkTokenId(token?.tokenId) &&
    workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL &&
    (key === "lastSalePricePerToken" ||
      key === "lowestAskPricePerToken");
  const metric = isSupply
    ? (tokenId, value) =>
        tokenSummarySupplyMetricValue(tokenId, value, {
          workAmountStorageModel,
        })
    : q16WorkPrice
      ? (_, value) =>
          canonicalUnsignedDecimalText(value, WORK_SUBATOM_DECIMALS) ||
          undefined
      : (_, value) => tokenSummaryMetricValue(value);
  const tokenValue = metric(token?.tokenId, token?.[key]);
  if (preserveExisting && tokenValue !== undefined) {
    return tokenValue;
  }

  const summaryValue = metric(token?.tokenId, summary?.[key]);
  if (isSupply && isBondTokenId(token?.tokenId)) {
    if (summaryValue === undefined) {
      return tokenValue;
    }
    if (tokenValue === undefined) {
      return summaryValue;
    }
    return maxIntegerTexts(summaryValue, tokenValue);
  }
  return summaryValue ?? tokenValue;
}

function tokenPayloadWithScopedHolderIdentity(payload, scope) {
  if (!payload) {
    return payload;
  }
  const normalizedScope = normalizeTokenScope(scope);
  const tokens = Array.isArray(payload.tokens) ? payload.tokens : [];
  const matchingTokens = tokens.filter(
    (token) => tokenMatchesScope(token, normalizedScope),
  );
  if (!normalizedScope || tokens.length !== 1 || matchingTokens.length !== 1) {
    return payload;
  }
  const token = matchingTokens[0];
  return {
    ...payload,
    holders: (Array.isArray(payload.holders) ? payload.holders : []).map(
      (holder) => ({
        ...holder,
        ticker: token.ticker,
        tokenId: token.tokenId,
      }),
    ),
  };
}

function scopedTokenPayloadFromState(tokenState, scope) {
  const normalizedScope = normalizeTokenScope(scope);
  if (!normalizedScope) {
    return tokenState;
  }

  const sourceTokens = (tokenState.tokens ?? []).filter((token) =>
    tokenMatchesScope(token, normalizedScope),
  );
  const workScoped =
    sourceTokens.length === 1 &&
    isWorkTokenId(sourceTokens[0]?.tokenId);
  const workAmountStorageModel =
    workScoped &&
    (
      tokenState?.amountStorageModel ===
        WORK_SUBATOM_PROJECTION_MODEL ||
      tokenState?.precisionModel === WORK_PRECISION_V2_MODEL ||
      workRecordUsesSubatoms(sourceTokens[0])
    )
      ? WORK_SUBATOM_PROJECTION_MODEL
      : WORK_ATOMIC_PROJECTION_MODEL;
  const tokens = sourceTokens.map((token) => {
    if (!workScoped) {
      return token;
    }
    const {
      amountStorageModel: _amountStorageModel,
      decimals: _decimals,
      maxSupplyAtoms: _maxSupplyAtoms,
      maxSupplySubatoms: _maxSupplySubatoms,
      mintAmountAtoms: _mintAmountAtoms,
      mintAmountSubatoms: _mintAmountSubatoms,
      precisionModel: _precisionModel,
      unitScale: _unitScale,
      ...definition
    } = token;
    return {
      ...definition,
      ...canonicalWorkTokenDefinition(
        tokenState?.network ?? token?.network ?? "livenet",
        workAmountStorageModel,
      ),
    };
  });
  const scopedTokenIds = new Set(tokens.map((token) => token.tokenId));
  const matchesScopedToken = (item) => scopedTokenIds.has(item?.tokenId);
  const closedListings = (tokenState.closedListings ?? []).filter(
    matchesScopedToken,
  );
  const listings = (tokenState.listings ?? []).filter(matchesScopedToken);
  const invalidEvents = (tokenState.invalidEvents ?? []).filter(matchesScopedToken);
  const mints = (tokenState.mints ?? []).filter(matchesScopedToken);
  const sales = (tokenState.sales ?? []).filter(matchesScopedToken);
  const transfers = (tokenState.transfers ?? []).filter(matchesScopedToken);
  const summaries = workScoped
    ? new Map()
    : tokenAggregateSummaries({
        listings,
        mints,
        sales,
        tokens,
        transfers,
      });
  const ledgerAmountFromRecord = (tokenId, record, options = {}) =>
    tokenLedgerAmountFromRecord(tokenId, record, {
      ...options,
      ...(isWorkTokenId(tokenId)
        ? { workAmountStorageModel }
        : {}),
    });
  const balances = new Map();
  const addBalance = (tokenId, address, amount) => {
    if (
      !address ||
      amount === null ||
      (typeof amount === "number" && !Number.isFinite(amount)) ||
      amount === tokenLedgerZero(tokenId)
    ) {
      return;
    }

    balances.set(
      address,
      (balances.get(address) ?? tokenLedgerZero(tokenId)) + amount,
    );
  };
  for (const mint of mints) {
    if (mint.confirmed) {
      const amount = ledgerAmountFromRecord(mint.tokenId, mint);
      if (workScoped && amount === null) {
        throw new Error(
          "Scoped WORK state contains a noncanonical confirmed mint.",
        );
      }
      addBalance(mint.tokenId, mint.minterAddress, amount);
    }
  }
  for (const transfer of transfers) {
    if (transfer.confirmed) {
      const amount = ledgerAmountFromRecord(
        transfer.tokenId,
        transfer,
      );
      if (workScoped && amount === null) {
        throw new Error(
          "Scoped WORK state contains a noncanonical confirmed transfer.",
        );
      }
      if (amount !== null) {
        addBalance(transfer.tokenId, transfer.senderAddress, -amount);
        addBalance(transfer.tokenId, transfer.recipientAddress, amount);
      }
    }
  }
  for (const sale of sales) {
    if (sale.confirmed) {
      const amount = canonicalTokenSaleLedgerAmount(
        sale.tokenId,
        sale,
        {
          ...(isWorkTokenId(sale.tokenId)
            ? { workAmountStorageModel }
            : {}),
        },
      );
      if (workScoped && amount === null) {
        throw new Error(
          "Scoped WORK state contains a noncanonical confirmed sale.",
        );
      }
      if (amount !== null) {
        addBalance(sale.tokenId, sale.sellerAddress, -amount);
        addBalance(sale.tokenId, sale.buyerAddress, amount);
      }
    }
  }

  const scopedTokenId = tokens.length === 1 ? tokens[0].tokenId : "";
  const aggregateSupply = (key) => {
    // Supply units belong to a specific credit definition. Adding WORK,
    // generic credits, and synthetic bonds together is dimensionally invalid,
    // and coercing a large bond balance to Number is inexact. Mixed scopes
    // therefore expose exact per-token totals only.
    if (tokens.length !== 1) {
      return null;
    }
    if (isBondTokenId(scopedTokenId)) {
      return tokens.reduce((total, token) => {
        const summary = summaries.get(token.tokenId);
        const summaryValue =
          tokenSummarySupplyMetricValue(token.tokenId, summary?.[key]) || "0";
        const tokenValue =
          tokenSummarySupplyMetricValue(token.tokenId, token?.[key]) || "0";
        return addIntegerTexts(total, maxIntegerTexts(summaryValue, tokenValue));
      }, "0");
    }
    return tokens.reduce((total, token) => {
      const summary = summaries.get(token.tokenId);
      return total + Math.max(
        summary?.[key] ?? 0,
        Number.isFinite(Number(token?.[key])) ? Number(token[key]) : 0,
      );
    }, 0);
  };
  const confirmedWorkSupply = workScoped
    ? mints
        .filter((mint) => mint.confirmed)
        .reduce((total, mint) => {
          const amount = ledgerAmountFromRecord(
            WORK_TOKEN_ID,
            mint,
          );
          if (amount === null) {
            throw new Error(
              "Scoped WORK state contains a noncanonical confirmed mint amount.",
            );
          }
          return total + amount;
        }, 0n)
    : null;
  const pendingWorkSupply = confirmedWorkSupply === null
    ? null
    : mints
        .filter((mint) => !mint.confirmed)
        .reduce((total, mint) => {
          const amount = ledgerAmountFromRecord(
            WORK_TOKEN_ID,
            mint,
          );
          if (amount === null) {
            throw new Error(
              "Scoped WORK state contains a noncanonical pending mint amount.",
            );
          }
          return total + amount;
        }, 0n);
  const confirmedSupply = workScoped
    ? tokenLedgerSupplyValue(
        WORK_TOKEN_ID,
        confirmedWorkSupply,
        { workAmountStorageModel },
      )
    : aggregateSupply("confirmedSupply");
  const pendingSupply = workScoped
    ? tokenLedgerSupplyValue(
        WORK_TOKEN_ID,
        pendingWorkSupply,
        { workAmountStorageModel },
      )
    : aggregateSupply("pendingSupply");
  const holders = [...balances.entries()]
    .filter(([, balance]) => balance > 0)
    .map(([address, balance]) => ({
      address,
      ledgerBalance: balance,
      ...tokenLedgerBalanceFields(
        scopedTokenId,
        balance,
        workScoped ? { workAmountStorageModel } : {},
      ),
    }))
    .sort(
      (left, right) =>
        (right.ledgerBalance > left.ledgerBalance
          ? 1
          : right.ledgerBalance < left.ledgerBalance
            ? -1
            : 0) ||
        compareCanonicalUtf8(left.address, right.address),
    )
    .map(({ ledgerBalance, ...holder }) => holder);

  const creationSats = tokens.reduce(
    (total, token) => total + (Number(token.creationFeeSats) || 0),
    0,
  );
  const scopedBaseState = workScoped
    ? (() => {
        const {
          amountStorageModel: _amountStorageModel,
          confirmedSupplyAtoms: _confirmedSupplyAtoms,
          confirmedSupplySubatoms: _confirmedSupplySubatoms,
          decimals: _decimals,
          pendingSupplyAtoms: _pendingSupplyAtoms,
          pendingSupplySubatoms: _pendingSupplySubatoms,
          precisionModel: _precisionModel,
          unitScale: _unitScale,
          ...state
        } = tokenState;
        return state;
      })()
    : tokenState;

  return tokenPayloadWithScopedHolderIdentity({
    ...scopedBaseState,
    closedListings,
    creationSats,
    confirmedSupply,
    ...(confirmedWorkSupply === null
      ? {}
      : workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
        ? {
            amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
            confirmedSupplySubatoms: confirmedWorkSupply.toString(),
            decimals: WORK_SUBATOM_DECIMALS,
            pendingSupplySubatoms: pendingWorkSupply.toString(),
            precisionModel: WORK_PRECISION_V2_MODEL,
            unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
          }
        : {
            amountStorageModel: WORK_ATOMIC_PROJECTION_MODEL,
            confirmedSupplyAtoms: confirmedWorkSupply.toString(),
            decimals: WORK_DECIMALS,
            pendingSupplyAtoms: pendingWorkSupply.toString(),
            unitScale: WORK_UNIT_SCALE_TEXT,
          }),
    holders,
    invalidEvents,
    listings,
    mints,
    pendingSupply,
    sales,
    tokens,
    transfers,
    stats: {
      ...(tokenState.stats ?? {}),
      confirmedMints: mints.filter((mint) => mint.confirmed).length,
      confirmedSales: sales.filter((sale) => sale.confirmed).length,
      confirmedSalesVolumeSats: sales
        .filter((sale) => sale.confirmed)
        .reduce((total, sale) => total + numericValue(sale.priceSats), 0),
      confirmedTransfers: transfers.filter((transfer) => transfer.confirmed)
        .length,
      confirmedTokens: tokens.filter((token) => token.confirmed).length,
      creationSats,
      holders: holders.length,
      invalidEvents: invalidEvents.filter((event) => event.confirmed).length,
      pendingMints: mints.filter((mint) => !mint.confirmed).length,
      pendingSales: sales.filter((sale) => !sale.confirmed).length,
      pendingTransfers: transfers.filter((transfer) => !transfer.confirmed)
        .length,
      pendingTokens: tokens.filter((token) => !token.confirmed).length,
      registries: new Set(
        tokens.map((token) => token.registryAddress).filter(Boolean),
      ).size,
    },
  }, normalizedScope);
}

async function fastTokenPayloadSnapshot(network, tokenScope = "", options = {}) {
  const scope = normalizeTokenScope(tokenScope);
  const reconcileSpendable = options.reconcileSpendable !== false;
  const payloadKey = `payload:token:${network}:${scope}`;
  const now = Date.now();
  let cachedPayloadEntry = RESPONSE_CACHE.get(payloadKey);
  if (
    cachedPayloadEntry?.payload &&
    !tokenPayloadCanPopulateFullStateCache(
      cachedPayloadEntry.payload,
      network,
    )
  ) {
    RESPONSE_CACHE.delete(payloadKey);
    cachedPayloadEntry = null;
  }
  if (cachedPayloadEntry?.payload && now < cachedPayloadEntry.expiresAt) {
    const payload = tokenStateWithoutDroppedPendingTransactions(
      cachedPayloadEntry.payload,
      network,
    );
    return reconcileSpendable
      ? await tokenPayloadWithSpendableListings(payload, network)
      : payload;
  }
  if (cachedPayloadEntry?.payload && now < cachedPayloadEntry.staleUntil) {
    if (shouldAutoRefreshTokenScope(scope)) {
      refreshTokenPayloadCacheInBackground(network, scope);
    }
    const payload = tokenStateWithoutDroppedPendingTransactions(
      cachedPayloadEntry.payload,
      network,
    );
    return reconcileSpendable
      ? await tokenPayloadWithSpendableListings(payload, network)
      : payload;
  }

  const jsonKey = `json:token:${network}:${scope}`;
  await hydratePersistedJsonCache(jsonKey, TOKEN_CACHE_STALE_MS);
  const cachedJsonEntry = RESPONSE_CACHE.get(jsonKey);
  if (
    cachedJsonEntry?.body &&
    cachedJsonEntry.tokenFullStateRejected !== true
  ) {
    try {
      const rawPayload = JSON.parse(cachedJsonEntry.body);
      if (!tokenPayloadCanPopulateFullStateCache(rawPayload, network)) {
        quarantineTokenJsonFullStateCache(jsonKey, TOKEN_CACHE_STALE_MS);
        throw new Error("Compact token summary rejected as full-state cache.");
      }
      const filteredPayload = tokenStateWithoutDroppedPendingTransactions(
        rawPayload,
        network,
      );
      const payload = reconcileSpendable
        ? await tokenPayloadWithSpendableListings(filteredPayload, network)
        : filteredPayload;
      RESPONSE_CACHE.set(payloadKey, {
        expiresAt: Date.now() + TOKEN_CACHE_TTL_MS,
        payload,
        staleUntil: Date.now() + TOKEN_CACHE_STALE_MS,
      });
      if (shouldAutoRefreshTokenScope(scope)) {
        refreshTokenPayloadCacheInBackground(network, scope);
      }
      return payload;
    } catch {
      if (RESPONSE_CACHE.get(jsonKey)?.tokenFullStateRejected !== true) {
        RESPONSE_CACHE.delete(jsonKey);
      }
    }
  }

  if (shouldAutoRefreshTokenScope(scope)) {
    refreshTokenPayloadCacheInBackground(network, scope);
  }
  return tokenStateWithoutDroppedPendingTransactions({
    ...emptyTokenState(),
    creationPriceSats: TOKEN_CREATION_PRICE_SATS,
    indexedAt: new Date().toISOString(),
    indexAddress: tokenIndexAddressForNetwork(network) ?? "",
    indexId: TOKEN_INDEX_ID,
    indexTxid: TOKEN_INDEX_TXID,
    minMutationPriceSats: TOKEN_MIN_MUTATION_PRICE_SATS,
    network,
    source: mempoolBase(network),
    stats: {
      confirmedMints: 0,
      confirmedTransfers: 0,
      confirmedTokens: 0,
      holders: 0,
      invalidEvents: 0,
      pendingMints: 0,
      pendingTransfers: 0,
      pendingTokens: 0,
      registries: 0,
      transactions: 0,
    },
    workDefaults: canonicalWorkDefaults(),
  }, network);
}

function compactTokenSummaryPayload(payload, tokenScope = "", options = {}) {
  const holders = Array.isArray(payload.holders) ? payload.holders : [];
  const rawListings = Array.isArray(payload.listings) ? payload.listings : [];
  const mints = Array.isArray(payload.mints) ? payload.mints : [];
  const sales = Array.isArray(payload.sales) ? payload.sales : [];
  const transfers = Array.isArray(payload.transfers) ? payload.transfers : [];
  const invalidEvents = Array.isArray(payload.invalidEvents)
    ? payload.invalidEvents
    : [];
  const tokenDefinitions = Array.isArray(payload.tokens) ? payload.tokens : [];
  const sealedActiveListingsByKey = new Map(
    rawListings
      .filter(tokenListingHasConfirmedSaleTicketSeal)
      .map((listing) => [
        listing?.listingId
          ? `${listing.network ?? ""}:${String(listing.listingId).toLowerCase()}`
          : "",
        listing,
      ])
      .filter(([key]) => Boolean(key)),
  );
  const closedListings = (Array.isArray(payload.closedListings)
    ? payload.closedListings
    : []
  ).filter((listing) => {
    const key = listing?.listingId
      ? `${listing.network ?? ""}:${String(listing.listingId).toLowerCase()}`
      : "";
    const activeListing = sealedActiveListingsByKey.get(key);
    return !(
      activeListing &&
      listing?.closedBySpendableOutspend !== true &&
      String(listing?.closedTxid ?? listing?.txid ?? "").toLowerCase() ===
        String(activeListing.sealTxid ?? "").toLowerCase()
    );
  });
  const closedListingKeys = new Set(
    closedListings
      .map((listing) =>
        listing?.listingId
          ? `${listing.network ?? ""}:${String(listing.listingId).toLowerCase()}`
          : "",
      )
      .filter(Boolean),
  );
  const closedListingsByKey = new Map();
  for (const listing of closedListings) {
    const key = listing?.listingId
      ? `${listing.network ?? ""}:${String(listing.listingId).toLowerCase()}`
      : "";
    if (!key) {
      continue;
    }
    const current = closedListingsByKey.get(key) ?? [];
    current.push(listing);
    closedListingsByKey.set(key, current);
  }
  const listings = rawListings.filter((listing) => {
    if (
      listing?.closedConfirmed === true &&
      /^[0-9a-f]{64}$/u.test(
        String(listing.closedTxid ?? listing.closeTxid ?? "").toLowerCase(),
      )
    ) {
      return false;
    }

    if (!listing?.listingId || closedListingKeys.size === 0) {
      return true;
    }

    const key = `${listing.network ?? ""}:${String(listing.listingId).toLowerCase()}`;
    if (!closedListingKeys.has(key)) {
      return true;
    }
    if (!tokenListingHasConfirmedSaleTicketSeal(listing)) {
      return false;
    }

    const closedForListing = closedListingsByKey.get(key) ?? [];
    return closedForListing.every(
      (closedListing) =>
        closedListing?.closedConfirmed !== true ||
        String(closedListing.closedTxid ?? closedListing.txid ?? "").toLowerCase() ===
          String(listing.sealTxid ?? "").toLowerCase(),
    );
  });
  const stats =
    payload.stats && typeof payload.stats === "object" ? payload.stats : {};
  const walletScopedSummary =
    payload.walletScoped === true || stats.walletScoped === true;
  const scope = normalizeTokenScope(tokenScope);
  const includeAllScopedListings =
    options.includeAllScopedListings !== false;
  const compactMarketRecords = options.compactMarketRecords === true;
  const includeAllActiveListings =
    walletScopedSummary || (Boolean(scope) && includeAllScopedListings);
  const closedListingLimit = walletScopedSummary
    ? Math.max(closedListings.length, SUMMARY_MARKET_LIMIT)
    : SUMMARY_MARKET_LIMIT;
  const holderLimit = walletScopedSummary
    ? Math.max(holders.length, SUMMARY_MARKET_LIMIT)
    : SUMMARY_MARKET_LIMIT;
  const listingLimit = includeAllActiveListings
    ? Math.max(listings.length, SUMMARY_MARKET_LIMIT)
    : SUMMARY_MARKET_LIMIT;
  const saleLimit = walletScopedSummary
    ? Math.max(
        Array.isArray(payload.sales) ? payload.sales.length : 0,
        SUMMARY_MARKET_LIMIT,
      )
    : SUMMARY_MARKET_LIMIT;
  const rawTokens = tokenDefinitions;
  const workAmountStorageModel =
    tokenSummaryWorkAmountStorageModel(payload);
  const tokenSummaries = tokenAggregateSummaries({ ...payload, listings });
  const preserveExistingTokenMetrics = payload.summaryOnly === true;
  const explicitCount = (value) => {
    if (value === undefined || value === null || value === "") {
      return undefined;
    }
    const number = Number(value);
    return Number.isFinite(number) && number >= 0 ? number : undefined;
  };
  const summaryCollectionIsTruncated = (key, visible) => {
    if (!preserveExistingTokenMetrics) {
      return false;
    }
    const total = explicitCount(payload.totalCounts?.[key]);
    return (
      payload.collectionHasMore?.[key] === true ||
      (total !== undefined && total > visible)
    );
  };
  const salesSummaryIsTruncated = summaryCollectionIsTruncated(
    "sales",
    sales.length,
  );
  const listingsSummaryIsTruncated = summaryCollectionIsTruncated(
    "listings",
    listings.length,
  );
  const mergedTokenMarketMetric = (
    token,
    summary,
    key,
    truncated,
  ) => {
    const tokenValue = tokenSummaryMetricValue(token?.[key]);
    if (preserveExistingTokenMetrics && tokenValue !== undefined) {
      return tokenValue;
    }
    if (preserveExistingTokenMetrics && truncated) {
      return undefined;
    }
    return tokenSummaryMetricValue(summary?.[key]) ?? tokenValue;
  };
  const authoritativeStat = (key, computed) => {
    const existing = explicitCount(stats[key]);
    return preserveExistingTokenMetrics && existing !== undefined
      ? existing
      : computed;
  };
  const totalCountFrom = (key, computed, statKeys = []) => {
    const existing = explicitCount(payload.totalCounts?.[key]);
    if (existing !== undefined) {
      return existing;
    }
    if (!preserveExistingTokenMetrics) {
      return computed;
    }
    for (const statKey of statKeys) {
      const stat = explicitCount(stats[statKey]);
      if (stat !== undefined) {
        return stat;
      }
    }
    return null;
  };
  const combinedStats = (...keys) => {
    const values = keys.map((key) => explicitCount(stats[key]));
    return values.every((value) => value !== undefined)
      ? values.reduce((total, value) => total + value, 0)
      : undefined;
  };
  const scopedTokenId =
    scope && rawTokens.length === 1 && tokenMatchesScope(rawTokens[0], scope)
      ? rawTokens[0].tokenId
      : "";
  const scopedWorkQ16 =
    isWorkTokenId(scopedTokenId) &&
    workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL;
  const scopedConfirmedSupply = isBondTokenId(scopedTokenId)
    ? tokenSummarySupplyMetricValue(scopedTokenId, payload.confirmedSupply)
    : scopedWorkQ16
      ? tokenSummarySupplyMetricValue(scopedTokenId, payload.confirmedSupply, {
          workAmountStorageModel,
        })
      : Number.isFinite(Number(payload.confirmedSupply))
      ? Math.max(0, Number(payload.confirmedSupply))
      : undefined;
  const scopedPendingSupply = isBondTokenId(scopedTokenId)
    ? tokenSummarySupplyMetricValue(scopedTokenId, payload.pendingSupply)
    : scopedWorkQ16
      ? tokenSummarySupplyMetricValue(scopedTokenId, payload.pendingSupply, {
          workAmountStorageModel,
        })
      : Number.isFinite(Number(payload.pendingSupply))
      ? Math.max(0, Number(payload.pendingSupply))
      : undefined;
  const tokens = rawTokens.map((token) => {
    const summary = tokenSummaries.get(token.tokenId) ?? {};
    const tokenWorkQ16 =
      isWorkTokenId(token.tokenId) &&
      workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL;
    const summaryMetricOptions = tokenWorkQ16
      ? { workAmountStorageModel }
      : {};
    const canonicalPriceDescriptor = (key) => {
      if (!tokenWorkQ16) {
        return null;
      }
      const existing = canonicalWorkQ16SummaryUnitPriceDescriptor(
        token?.[key],
      );
      const computed = canonicalWorkQ16SummaryUnitPriceDescriptor(
        summary?.[key],
      );
      return preserveExistingTokenMetrics && existing
        ? existing
        : computed ?? existing;
    };
    const lastSalePricePerTokenExact = canonicalPriceDescriptor(
      "lastSalePricePerTokenExact",
    );
    const lowestAskPricePerTokenExact = canonicalPriceDescriptor(
      "lowestAskPricePerTokenExact",
    );
    const next = {
      ...token,
      confirmedMints: mergedTokenSummaryMetric(
        token,
        summary,
        "confirmedMints",
        preserveExistingTokenMetrics,
      ),
      confirmedOpenListings: mergedTokenMarketMetric(
        token,
        summary,
        "confirmedOpenListings",
        listingsSummaryIsTruncated,
      ),
      confirmedSales: mergedTokenMarketMetric(
        token,
        summary,
        "confirmedSales",
        salesSummaryIsTruncated,
      ),
      confirmedSalesVolumeSats: mergedTokenMarketMetric(
        token,
        summary,
        "confirmedSalesVolumeSats",
        salesSummaryIsTruncated,
      ),
      confirmedSupply: mergedTokenSummaryMetric(
        token,
        summary,
        "confirmedSupply",
        preserveExistingTokenMetrics,
        summaryMetricOptions,
      ),
      holderCount: mergedTokenSummaryMetric(
        token,
        summary,
        "holderCount",
        preserveExistingTokenMetrics,
      ),
      lastSalePricePerToken: mergedTokenSummaryMetric(
        token,
        summary,
        "lastSalePricePerToken",
        preserveExistingTokenMetrics,
        summaryMetricOptions,
      ),
      lowestAskPricePerToken: mergedTokenSummaryMetric(
        token,
        summary,
        "lowestAskPricePerToken",
        preserveExistingTokenMetrics,
        summaryMetricOptions,
      ),
      openListings: mergedTokenSummaryMetric(
        token,
        summary,
        "openListings",
        preserveExistingTokenMetrics,
      ),
      pendingMints: mergedTokenSummaryMetric(
        token,
        summary,
        "pendingMints",
        preserveExistingTokenMetrics,
      ),
      pendingOpenListings: mergedTokenMarketMetric(
        token,
        summary,
        "pendingOpenListings",
        listingsSummaryIsTruncated,
      ),
      pendingSales: mergedTokenMarketMetric(
        token,
        summary,
        "pendingSales",
        salesSummaryIsTruncated,
      ),
      pendingSalesVolumeSats: mergedTokenMarketMetric(
        token,
        summary,
        "pendingSalesVolumeSats",
        salesSummaryIsTruncated,
      ),
      pendingSupply: mergedTokenSummaryMetric(
        token,
        summary,
        "pendingSupply",
        preserveExistingTokenMetrics,
        summaryMetricOptions,
      ),
      transferCount: mergedTokenSummaryMetric(
        token,
        summary,
        "transferCount",
        preserveExistingTokenMetrics,
      ),
    };
    if (tokenWorkQ16) {
      const canonicalSupplySubatoms = (field) => {
        const existing = canonicalWorkSubatomsText(token?.[field], {
          allowZero: true,
        });
        const computed = canonicalWorkSubatomsText(summary?.[field], {
          allowZero: true,
        });
        if (preserveExistingTokenMetrics && existing) {
          return existing;
        }
        if (computed) {
          return computed;
        }
        const displayField = field.startsWith("confirmed")
          ? "confirmedSupply"
          : "pendingSupply";
        try {
          return parseWorkAmountToSubatoms(
            next[displayField],
            {
              allowZero: true,
              maxSubatoms: WORK_TOKEN_MAX_SUPPLY_SUBATOMS,
            },
          ).toString();
        } catch {
          return "";
        }
      };
      const confirmedSupplySubatoms = canonicalSupplySubatoms(
        "confirmedSupplySubatoms",
      );
      const pendingSupplySubatoms = canonicalSupplySubatoms(
        "pendingSupplySubatoms",
      );
      if (!confirmedSupplySubatoms || !pendingSupplySubatoms) {
        throw new Error(
          "WORK Q16 token summary has no exact subatom supply projection.",
        );
      }
      next.amountStorageModel = WORK_SUBATOM_PROJECTION_MODEL;
      next.confirmedSupply = formatWorkSubatoms(confirmedSupplySubatoms);
      next.confirmedSupplySubatoms = confirmedSupplySubatoms;
      next.decimals = WORK_SUBATOM_DECIMALS;
      next.pendingSupply = formatWorkSubatoms(pendingSupplySubatoms);
      next.pendingSupplySubatoms = pendingSupplySubatoms;
      next.precisionModel = WORK_PRECISION_V2_MODEL;
      next.unitScale = WORK_SUBATOM_UNIT_SCALE_TEXT;
      if (lastSalePricePerTokenExact) {
        next.lastSalePricePerToken = lastSalePricePerTokenExact.decimal;
        next.lastSalePricePerTokenExact = lastSalePricePerTokenExact;
      } else {
        delete next.lastSalePricePerToken;
        delete next.lastSalePricePerTokenExact;
      }
      if (lowestAskPricePerTokenExact) {
        next.lowestAskPricePerToken = lowestAskPricePerTokenExact.decimal;
        next.lowestAskPricePerTokenExact = lowestAskPricePerTokenExact;
      } else {
        delete next.lowestAskPricePerToken;
        delete next.lowestAskPricePerTokenExact;
      }
    }
    if (scopedTokenId && token.tokenId === scopedTokenId) {
      if (scopedConfirmedSupply !== undefined) {
        const nextConfirmedSupply = tokenSummarySupplyMetricValue(
          token.tokenId,
          next.confirmedSupply,
          summaryMetricOptions,
        );
        if (tokenWorkQ16) {
          const scopedConfirmedSupplySubatoms = parseWorkAmountToSubatoms(
            scopedConfirmedSupply,
            {
              allowZero: true,
              maxSubatoms: WORK_TOKEN_MAX_SUPPLY_SUBATOMS,
            },
          );
          next.confirmedSupply = formatWorkSubatoms(
            scopedConfirmedSupplySubatoms,
          );
          next.confirmedSupplySubatoms =
            scopedConfirmedSupplySubatoms.toString();
        } else {
          next.confirmedSupply = isBondTokenId(token.tokenId)
            ? preserveExistingTokenMetrics && nextConfirmedSupply !== undefined
              ? maxIntegerTexts(nextConfirmedSupply, scopedConfirmedSupply)
              : scopedConfirmedSupply
            : preserveExistingTokenMetrics &&
                nextConfirmedSupply !== undefined &&
                nextConfirmedSupply > scopedConfirmedSupply
              ? nextConfirmedSupply
              : scopedConfirmedSupply;
        }
      }
      if (scopedPendingSupply !== undefined) {
        const nextPendingSupply = tokenSummarySupplyMetricValue(
          token.tokenId,
          next.pendingSupply,
          summaryMetricOptions,
        );
        if (tokenWorkQ16) {
          const scopedPendingSupplySubatoms = parseWorkAmountToSubatoms(
            scopedPendingSupply,
            {
              allowZero: true,
              maxSubatoms: WORK_TOKEN_MAX_SUPPLY_SUBATOMS,
            },
          );
          next.pendingSupply = formatWorkSubatoms(
            scopedPendingSupplySubatoms,
          );
          next.pendingSupplySubatoms = scopedPendingSupplySubatoms.toString();
        } else {
          next.pendingSupply = isBondTokenId(token.tokenId)
            ? preserveExistingTokenMetrics && nextPendingSupply !== undefined
              ? maxIntegerTexts(nextPendingSupply, scopedPendingSupply)
              : scopedPendingSupply
            : preserveExistingTokenMetrics &&
                nextPendingSupply !== undefined &&
                nextPendingSupply > scopedPendingSupply
              ? nextPendingSupply
              : scopedPendingSupply;
        }
      }
    }
    return next;
  });

  const compactMarketRecord = (record) =>
    compactMarketRecords
      ? tokenSummaryMarketPreviewRecord(record)
      : record;
  const compactClosedMarketRecord = (record) =>
    compactMarketRecords
      ? tokenSummaryMarketPreviewRecord(record, {
          includeNestedListings: true,
        })
      : record;
  const compactClosedListings = recentClosedTokenListings(
    closedListings,
    closedListingLimit,
  ).map(compactClosedMarketRecord);
  const compactHolders = holders.slice(0, holderLimit);
  const compactListings = tokenSummaryListings(listings, listingLimit).map(
    compactMarketRecord,
  );
  const compactInvalidEvents = compactMarketRecords
    ? recentByCreatedAt(invalidEvents, SUMMARY_MARKET_LIMIT).map((event) =>
        tokenSummaryPreviewRecord(
          event,
          TOKEN_SUMMARY_INVALID_EVENT_PREVIEW_KEYS,
        ),
      )
    : invalidEvents;
  const compactSales = recentByCreatedAt(payload.sales, saleLimit).map(
    compactMarketRecord,
  );
  const summarizedOpenListings = (() => {
    const counts = tokens.map((token) => explicitCount(token?.openListings));
    return counts.length > 0 && counts.every((value) => value !== undefined)
      ? counts.reduce((total, value) => total + value, 0)
      : undefined;
  })();
  const totalCounts = {
    ...(payload.totalCounts ?? {}),
    closedListings: totalCountFrom(
      "closedListings",
      closedListings.length,
      ["totalClosedListings", "closedListings"],
    ),
    holders: totalCountFrom("holders", holders.length, ["holders"]),
    listings:
      totalCountFrom("listings", listings.length, [
        "totalListings",
        "openListings",
        "listings",
      ]) ?? summarizedOpenListings ?? null,
    mints:
      totalCountFrom("mints", mints.length, ["totalMints"]) ??
      combinedStats("confirmedMints", "pendingMints") ??
      null,
    sales:
      totalCountFrom("sales", sales.length, ["totalSales"]) ??
      combinedStats("confirmedSales", "pendingSales") ??
      null,
    tokens:
      totalCountFrom("tokens", tokenDefinitions.length, ["totalTokens"]) ??
      combinedStats("confirmedTokens", "pendingTokens") ??
      null,
    transfers:
      totalCountFrom("transfers", transfers.length, ["totalTransfers"]) ??
      combinedStats("confirmedTransfers", "pendingTransfers") ??
      null,
  };
  const collectionHasMoreValue = (key, total, visible) =>
    Number.isFinite(total)
      ? total > visible
      : payload.collectionHasMore?.[key] === true;
  const collectionHasMore = {
    closedListings: collectionHasMoreValue(
      "closedListings",
      totalCounts.closedListings,
      compactClosedListings.length,
    ),
    holders: collectionHasMoreValue(
      "holders",
      totalCounts.holders,
      compactHolders.length,
    ),
    listings: collectionHasMoreValue(
      "listings",
      totalCounts.listings,
      compactListings.length,
    ),
    mints: collectionHasMoreValue("mints", totalCounts.mints, 0),
    sales: collectionHasMoreValue(
      "sales",
      totalCounts.sales,
      compactSales.length,
    ),
    tokens: collectionHasMoreValue("tokens", totalCounts.tokens, tokens.length),
    transfers: collectionHasMoreValue("transfers", totalCounts.transfers, 0),
  };

  return tokenPayloadWithScopedHolderCountFloor(
    tokenPayloadWithScopedHolderIdentity({
      ...payload,
      closedListings: compactClosedListings,
      collectionHasMore,
      hasMore: Object.values(collectionHasMore).some(Boolean),
      holders: compactHolders,
      invalidEvents: compactInvalidEvents,
      ...(payload.listingAuthority &&
      typeof payload.listingAuthority === "object" &&
      !Array.isArray(payload.listingAuthority)
        ? { listingAuthority: payload.listingAuthority }
        : {}),
      listings: compactListings,
      mints: [],
      sales: compactSales,
      summaryOnly: true,
      totalCount:
        explicitCount(payload.totalCount) ??
        explicitCount(stats.transactions) ??
        (Object.values(totalCounts).every(Number.isFinite)
          ? totalCounts.tokens +
            totalCounts.mints +
            totalCounts.transfers +
            totalCounts.listings +
            totalCounts.sales
          : null),
      totalCounts,
      tokens,
      transfers: [],
      stats: {
        ...stats,
        confirmedMints: authoritativeStat(
          "confirmedMints",
          mints.filter((mint) => mint?.confirmed).length,
        ),
        confirmedSales: authoritativeStat(
          "confirmedSales",
          sales.filter((sale) => sale?.confirmed).length,
        ),
        confirmedSalesVolumeSats: authoritativeStat(
          "confirmedSalesVolumeSats",
          sales
            .filter((sale) => sale?.confirmed)
            .reduce((total, sale) => total + numericValue(sale.priceSats), 0),
        ),
        confirmedTransfers: authoritativeStat(
          "confirmedTransfers",
          transfers.filter((transfer) => transfer?.confirmed).length,
        ),
        confirmedTokens: authoritativeStat(
          "confirmedTokens",
          tokenDefinitions.filter((token) => token?.confirmed).length,
        ),
        holders: authoritativeStat("holders", holders.length),
        pendingMints: authoritativeStat(
          "pendingMints",
          mints.filter((mint) => !mint?.confirmed).length,
        ),
        pendingSales: authoritativeStat(
          "pendingSales",
          sales.filter((sale) => !sale?.confirmed).length,
        ),
        pendingSalesVolumeSats: authoritativeStat(
          "pendingSalesVolumeSats",
          sales
            .filter((sale) => !sale?.confirmed)
            .reduce((total, sale) => total + numericValue(sale.priceSats), 0),
        ),
        pendingTransfers: authoritativeStat(
          "pendingTransfers",
          transfers.filter((transfer) => !transfer?.confirmed).length,
        ),
        pendingTokens: authoritativeStat(
          "pendingTokens",
          tokenDefinitions.filter((token) => !token?.confirmed).length,
        ),
      },
    }, scope),
    scope,
  );
}

function workTokenLiveSeenTxids(network) {
  const key = String(network || "livenet");
  let seen = WORK_TOKEN_LIVE_SEEN_TXIDS.get(key);
  if (!seen) {
    seen = new Set();
    WORK_TOKEN_LIVE_SEEN_TXIDS.set(key, seen);
  }
  return seen;
}

function addTokenStateTxids(txids, state) {
  const add = (value) => {
    if (typeof value === "string" && /^[0-9a-fA-F]{64}$/u.test(value)) {
      txids.add(value.toLowerCase());
    }
  };

  for (const key of [
    "mints",
    "transfers",
    "sales",
    "listings",
    "closedListings",
  ]) {
    for (const item of Array.isArray(state?.[key]) ? state[key] : []) {
      add(item.txid);
      add(item.listingId);
      add(item.sealTxid);
      add(item.closedTxid);
    }
  }
}

function unconfirmedTokenStateTxids(state) {
  const txids = new Set();
  const add = (value) => {
    if (typeof value === "string" && /^[0-9a-fA-F]{64}$/u.test(value)) {
      txids.add(value.toLowerCase());
    }
  };

  // Listings and seals directly gate seller actions, so check them before
  // high-volume pending mint rows consume the bounded confirmation window.
  for (const item of Array.isArray(state?.listings) ? state.listings : []) {
    if (item?.confirmed === false) {
      add(item.txid);
      add(item.listingId);
    }
    if (item?.sealConfirmed === false) {
      add(item.sealTxid);
    }
  }

  for (const item of Array.isArray(state?.closedListings)
    ? state.closedListings
    : []) {
    if (item?.confirmed === false) {
      add(item.txid);
      add(item.listingId);
    }
    if (item?.closedConfirmed === false) {
      add(item.closedTxid);
    }
  }

  for (const item of Array.isArray(state?.sales) ? state.sales : []) {
    if (item?.confirmed === false) {
      add(item.txid);
    }
  }

  for (const item of Array.isArray(state?.transfers) ? state.transfers : []) {
    if (item?.confirmed === false) {
      add(item.txid);
    }
  }

  for (const item of Array.isArray(state?.mints) ? state.mints : []) {
    if (item?.confirmed === false) {
      add(item.txid);
    }
  }

  return [...txids];
}

function tokenStateWithPendingStats(state) {
  const tokens = Array.isArray(state?.tokens) ? state.tokens : [];
  const mints = Array.isArray(state?.mints) ? state.mints : [];
  const transfers = Array.isArray(state?.transfers) ? state.transfers : [];
  const sales = Array.isArray(state?.sales) ? state.sales : [];
  const holders = Array.isArray(state?.holders) ? state.holders : [];
  const scopedBondTokenId =
    tokens.length === 1 && isBondTokenId(tokens[0]?.tokenId)
      ? tokens[0].tokenId
      : "";
  const pendingSupply = scopedBondTokenId
    ? mints
        .filter(
          (mint) =>
            !mint.confirmed && mint.tokenId === scopedBondTokenId,
        )
        .reduce((total, mint) => {
          const amount = tokenLedgerAmountFromRecord(scopedBondTokenId, mint);
          return amount === null ? total : total + amount;
        }, 0n)
        .toString()
    : mints
        .filter((mint) => !mint.confirmed)
        .reduce((total, mint) => total + Number(mint.amount || 0), 0);
  const confirmedSales = sales.filter((sale) => sale.confirmed);

  return {
    ...state,
    pendingSupply,
    stats: {
      ...(state?.stats ?? {}),
      confirmedMints: mints.filter((mint) => mint.confirmed).length,
      confirmedSales: confirmedSales.length,
      confirmedSalesVolumeSats: confirmedSales.reduce(
        (total, sale) => total + numericValue(sale.priceSats),
        0,
      ),
      confirmedTransfers: transfers.filter((transfer) => transfer.confirmed)
        .length,
      confirmedTokens: tokens.filter((token) => token.confirmed).length,
      holders: holders.length,
      pendingMints: mints.filter((mint) => !mint.confirmed).length,
      pendingSales: sales.filter((sale) => !sale.confirmed).length,
      pendingTransfers: transfers.filter((transfer) => !transfer.confirmed)
        .length,
      pendingTokens: tokens.filter((token) => !token.confirmed).length,
    },
  };
}

function tokenStateWithoutDroppedPendingTransactions(state, network) {
  const droppedTxids = droppedPendingTokenTransactionTxids(network);
  if (droppedTxids.size === 0 || !state) {
    return state;
  }

  const isDropped = (...values) =>
    values.some(
      (value) =>
        typeof value === "string" && droppedTxids.has(value.toLowerCase()),
    );
  const keepPendingItem = (item, ...txidValues) =>
    item?.confirmed !== false || !isDropped(...txidValues);
  const stripDroppedSeal = (listing) => {
    if (listing?.sealConfirmed !== false || !isDropped(listing.sealTxid)) {
      return listing;
    }

    const {
      sealAt,
      sealConfirmed,
      sealDataBytes,
      sealTxid,
      ...withoutDroppedSeal
    } = listing;
    return withoutDroppedSeal;
  };
  const activeListingsById = new Map();
  const addActiveListing = (listing) => {
    const listingId = String(
      listing?.listingId ?? listing?.txid ?? "",
    ).toLowerCase();
    if (!/^[0-9a-f]{64}$/u.test(listingId)) {
      return;
    }
    activeListingsById.set(
      listingId,
      mergeTokenListingRecord(activeListingsById.get(listingId), listing),
    );
  };

  let changed = false;
  const filterPendingItems = (items, txidForItem) =>
    (Array.isArray(items) ? items : []).filter((item) => {
      const keep = keepPendingItem(item, ...txidForItem(item));
      if (!keep) {
        changed = true;
      }
      return keep;
    });

  const tokens = filterPendingItems(state.tokens, (item) => [item?.txid]);
  const mints = filterPendingItems(state.mints, (item) => [item?.txid]);
  const transfers = filterPendingItems(state.transfers, (item) => [item?.txid]);
  const sales = filterPendingItems(state.sales, (item) => [item?.txid]);
  const invalidEvents = filterPendingItems(state.invalidEvents, (item) => [
    item?.txid,
  ]);

  for (const listing of Array.isArray(state.listings) ? state.listings : []) {
    if (
      listing?.confirmed === false &&
      isDropped(listing.txid, listing.listingId)
    ) {
      changed = true;
      continue;
    }
    const nextListing = stripDroppedSeal(listing);
    if (nextListing !== listing) {
      changed = true;
    }
    addActiveListing(nextListing);
  }

  const closedListings = [];
  for (const listing of Array.isArray(state.closedListings)
    ? state.closedListings
    : []) {
    if (
      listing?.confirmed === false &&
      isDropped(listing.txid, listing.listingId)
    ) {
      changed = true;
      continue;
    }

    if (
      listing?.closedConfirmed === false &&
      isDropped(listing.closedTxid)
    ) {
      const {
        closedAt,
        closedConfirmed,
        closedTxid,
        ...reopenedListing
      } = stripDroppedSeal(listing);
      changed = true;
      addActiveListing(reopenedListing);
      continue;
    }

    const nextListing = stripDroppedSeal(listing);
    if (nextListing !== listing) {
      changed = true;
    }
    closedListings.push(nextListing);
  }

  const listings = [...activeListingsById.values()];
  if (
    !changed &&
    tokens.length === (Array.isArray(state.tokens) ? state.tokens.length : 0) &&
    mints.length === (Array.isArray(state.mints) ? state.mints.length : 0) &&
    transfers.length ===
      (Array.isArray(state.transfers) ? state.transfers.length : 0) &&
    sales.length === (Array.isArray(state.sales) ? state.sales.length : 0) &&
    invalidEvents.length ===
      (Array.isArray(state.invalidEvents) ? state.invalidEvents.length : 0) &&
    listings.length ===
      (Array.isArray(state.listings) ? state.listings.length : 0) &&
    closedListings.length ===
      (Array.isArray(state.closedListings) ? state.closedListings.length : 0)
  ) {
    return state;
  }

  return tokenStateWithPendingStats({
    ...state,
    closedListings,
    invalidEvents,
    listings,
    mints,
    sales,
    tokens,
    transfers,
  });
}

async function tokenStateWithLivePendingTransactionCheck(state, network) {
  const txids = unconfirmedTokenStateTxids(state).slice(
    0,
    Math.max(0, PENDING_TOKEN_LIVENESS_CHECK_MAX_TXS),
  );
  if (txids.length === 0) {
    return tokenStateWithoutDroppedPendingTransactions(state, network);
  }

  await mapWithConcurrency(
    txids,
    Math.max(1, PENDING_TOKEN_LIVENESS_CHECK_CONCURRENCY),
    async (txid) => {
      if (droppedPendingTokenTransactionTxids(network).has(txid)) {
        return;
      }

      if (network === "livenet") {
        const status = await bitcoinCoreTxStatusPayload(txid, network).catch(
          (error) => {
            console.error(
              `Pending token liveness proof deferred for ${txid}: ${errorSummary(error)}`,
            );
            return null;
          },
        );
        if (status?.status === "dropped" && status.absenceProven === true) {
          markDroppedPendingTokenTransaction(
            txid,
            network,
            "pending-liveness-core-proof",
          );
        }
        return;
      }

      const tx = await fetchTransactionWithPendingFallback(txid, network).catch(
        () => null,
      );
      if (tx) {
        cachePendingTokenTransaction(tx, network, "pending-liveness");
      }
    },
  );

  return tokenStateWithoutDroppedPendingTransactions(state, network);
}

function syncWorkTokenLiveSeenTxids(network, state) {
  const knownTxids = workTokenLiveSeenTxids(network);
  knownTxids.clear();
  addTokenStateTxids(knownTxids, state);
  for (const txid of unconfirmedTokenStateTxids(state)) {
    knownTxids.delete(txid);
  }
  return knownTxids;
}

function workTokenClosedListingsMissingSales(state, network) {
  const saleTxids = new Set(
    (Array.isArray(state?.sales) ? state.sales : [])
      .map((sale) => String(sale?.txid ?? "").toLowerCase())
      .filter((txid) => /^[0-9a-f]{64}$/u.test(txid)),
  );
  const confirmedInvalidBuyTxids = confirmedInvalidWorkBuyTxids(state);
  return (Array.isArray(state?.closedListings) ? state.closedListings : []).filter(
    (listing) => {
      const closedTxid = String(listing?.closedTxid ?? "").toLowerCase();
      return (
        listing?.tokenId === WORK_TOKEN_ID &&
        (listing?.closedConfirmed === true ||
          confirmedInvalidBuyTxids.has(closedTxid)) &&
        /^[0-9a-f]{64}$/u.test(closedTxid) &&
        !saleTxids.has(closedTxid)
      );
    },
  );
}

function confirmedInvalidWorkBuyTxids(state) {
  return new Set(
    (Array.isArray(state?.invalidEvents) ? state.invalidEvents : [])
      .filter(
        (event) =>
          event?.confirmed === true &&
          event?.kind === "buy" &&
          event?.reason === "no-valid-work-token-event",
      )
      .map((event) => String(event?.txid ?? "").toLowerCase())
      .filter((txid) => /^[0-9a-f]{64}$/u.test(txid)),
  );
}

function prioritizedWorkSaleRecoveryCandidates(state, candidates) {
  const invalidBuyTxids = confirmedInvalidWorkBuyTxids(state);
  const ordered = [...candidates].sort((left, right) => {
    const leftPriority = invalidBuyTxids.has(
      String(left?.closedTxid ?? "").toLowerCase(),
    )
      ? 1
      : 0;
    const rightPriority = invalidBuyTxids.has(
      String(right?.closedTxid ?? "").toLowerCase(),
    )
      ? 1
      : 0;
    return (
      rightPriority - leftPriority ||
      Date.parse(right?.closedAt ?? right?.createdAt ?? "") -
        Date.parse(left?.closedAt ?? left?.createdAt ?? "") ||
      compareCanonicalUtf8(left?.listingId, right?.listingId)
    );
  });

  const priorityCount = ordered.filter((listing) =>
    invalidBuyTxids.has(String(listing?.closedTxid ?? "").toLowerCase()),
  ).length;
  // User-facing reads should repair invalid confirmed buys before sweeping older
  // generic closures, otherwise wallet refreshes can block on unrelated delists.
  return priorityCount > 0 ? ordered.slice(0, priorityCount) : ordered;
}

function confirmedWorkSaleFromClosedListingTransaction(tx, listing, network) {
  if (network === "livenet") {
    return null;
  }
  const txid = transactionTxid(tx);
  if (!txid || !transactionConfirmed(tx)) {
    return null;
  }

  const vin = Array.isArray(tx.vin) ? tx.vin : [];
  const vout = Array.isArray(tx.vout) ? tx.vout : [];
  const txInputAddresses = inputAddresses(vin);
  const messages = decodedProtocolMessages(vout, TOKEN_PROTOCOL_PREFIX);
  if (messages.length === 0) {
    return null;
  }

  const registryAddress =
    listing.registryAddress || WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS;
  let remainingRegistrySats = tokenPaymentAmountBeforeProtocol(
    vout,
    registryAddress,
  );
  const paymentOutputs = paymentOutputsBeforeTokenProtocol(vout);
  const eventSpentOutpoints = spentOutpoints(vin);
  const createdAt = new Date(tokenTransactionTime(tx)).toISOString();

  for (const message of messages) {
    const parsed = parseTokenPayload(message, network);
    if (
      !parsed ||
      parsed.kind !== "buy" ||
      parsed.listingId !== listing.listingId
    ) {
      continue;
    }

    const listingHasValidSaleTicketSpend =
      tokenSaleAuthorizationUsesSaleTicketAnchor(listing.saleAuthorization) ||
      tokenListingAnchorSpendMatchesAuthorization(vin, listing);
    const buyerAddressIsLinked =
      txInputAddresses.includes(parsed.buyerAddress) ||
      paymentAmountFromSnapshots(paymentOutputs, parsed.buyerAddress) > 0;
    if (
      !buyerAddressIsLinked ||
      remainingRegistrySats < TOKEN_MIN_MUTATION_PRICE_SATS ||
      !listingHasValidSaleTicketSpend ||
      (listing.saleAuthorization.buyerAddress &&
        listing.saleAuthorization.buyerAddress !== parsed.buyerAddress) ||
      tokenListingIsExpired(listing, Date.parse(createdAt)) ||
      !spendsTokenListingAnchor(eventSpentOutpoints, listing) ||
      paymentAmountFromSnapshots(paymentOutputs, listing.sellerAddress) <
        tokenSellerPaymentRequiredSats(listing)
    ) {
      continue;
    }

    remainingRegistrySats -= TOKEN_MIN_MUTATION_PRICE_SATS;
    const workAmountStorageModel =
      isWorkTokenId(listing.tokenId) &&
      workRecordUsesSubatoms(listing)
        ? WORK_SUBATOM_PROJECTION_MODEL
        : WORK_ATOMIC_PROJECTION_MODEL;
    const listingAmount = tokenLedgerAmountFromRecord(
      listing.tokenId,
      listing,
      { workAmountStorageModel },
    );
    if (listingAmount === null) {
      continue;
    }
    return {
      ...tokenLedgerAmountFields(
        listing.tokenId,
        listingAmount,
        { workAmountStorageModel },
      ),
      buyerAddress: parsed.buyerAddress,
      confirmed: true,
      createdAt,
      listingId: listing.listingId,
      network,
      paidSats:
        tokenSellerPaymentRequiredSats(listing) +
        TOKEN_MIN_MUTATION_PRICE_SATS,
      priceSats: listing.priceSats,
      registryAddress,
      sellerAddress: listing.sellerAddress,
      ticker: listing.ticker,
      tokenId: listing.tokenId,
      txid,
    };
  }

  return null;
}

async function recoverWorkSalesFromClosedListings(state, network) {
  if (network === "livenet") {
    return [];
  }
  const candidates = prioritizedWorkSaleRecoveryCandidates(
    state,
    workTokenClosedListingsMissingSales(state, network),
  );
  const recovered = await mapWithConcurrency(
    candidates,
    TX_FETCH_CONCURRENCY,
    async (listing) => {
      const closedTxid = String(listing.closedTxid ?? "").toLowerCase();
      try {
        const tx = await fetchTransactionWithSourceFallback(closedTxid, network);
        const sale = confirmedWorkSaleFromClosedListingTransaction(
          tx,
          listing,
          network,
        );
        if (sale) {
          return sale;
        }
      } catch (error) {
        console.error(
          `WORK closed sale repair lookup failed for ${closedTxid}: ${errorSummary(error)}`,
        );
      }
      return null;
    },
  );

  return recovered.filter(Boolean);
}

function workTokenStateWithRecoveredSales(state, recoveredSales) {
  const newSales = recoveredSales.filter(
    (sale) =>
      sale?.txid &&
      !(Array.isArray(state.sales) ? state.sales : []).some(
        (existing) => existing?.txid === sale.txid,
      ),
  );
  if (newSales.length === 0) {
    return state;
  }

  const recoveredSaleTxids = new Set(
    newSales
      .map((sale) => String(sale?.txid ?? "").toLowerCase())
      .filter((txid) => /^[0-9a-f]{64}$/u.test(txid)),
  );
  const workTokenDefinition = (Array.isArray(state?.tokens)
    ? state.tokens
    : []
  ).find((token) => isWorkTokenId(token?.tokenId));
  const workAmountStorageModel =
    state?.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL ||
    state?.precisionModel === WORK_PRECISION_V2_MODEL ||
    workRecordUsesSubatoms(workTokenDefinition)
      ? WORK_SUBATOM_PROJECTION_MODEL
      : WORK_ATOMIC_PROJECTION_MODEL;
  const holders = new Map(
    (Array.isArray(state.holders) ? state.holders : [])
      .map((holder) => [
        holder?.address,
        tokenLedgerAmountFromRecord(
          WORK_TOKEN_ID,
          {
            amount: holder?.balance,
            amountAtoms: holder?.balanceAtoms,
            amountStorageModel: holder?.amountStorageModel,
            amountSubatoms: holder?.balanceSubatoms,
            precisionModel: holder?.precisionModel,
          },
          { allowZero: true, workAmountStorageModel },
        ),
      ])
      .filter(([address, balance]) => address && balance !== null && balance > 0n),
  );

  for (const sale of newSales) {
    const saleAmount = tokenLedgerAmountFromRecord(
      WORK_TOKEN_ID,
      sale,
      { workAmountStorageModel },
    );
    if (saleAmount === null) {
      continue;
    }
    holders.set(
      sale.sellerAddress,
      (holders.get(sale.sellerAddress) ?? 0n) - saleAmount,
    );
    holders.set(
      sale.buyerAddress,
      (holders.get(sale.buyerAddress) ?? 0n) + saleAmount,
    );
  }

  const nextHolders = [...holders.entries()]
    .filter(([, balance]) => balance > 0)
    .map(([address, balance]) => ({
      address,
      ledgerBalance: balance,
      ...tokenLedgerBalanceFields(WORK_TOKEN_ID, balance, {
        workAmountStorageModel,
      }),
    }))
    .sort(
      (left, right) =>
        (right.ledgerBalance > left.ledgerBalance
          ? 1
          : right.ledgerBalance < left.ledgerBalance
            ? -1
            : 0) ||
        compareCanonicalUtf8(left.address, right.address),
    )
    .map(({ ledgerBalance, ...holder }) => holder);

  const nextSales = [...(Array.isArray(state.sales) ? state.sales : []), ...newSales]
    .sort(
      (left, right) =>
        Number(right.confirmed) - Number(left.confirmed) ||
        Date.parse(right.createdAt) - Date.parse(left.createdAt) ||
        compareCanonicalUtf8(left.txid, right.txid),
    );

  const nextInvalidEvents = (Array.isArray(state.invalidEvents)
    ? state.invalidEvents
    : []
  )
    .filter(
      (event) =>
        !recoveredSaleTxids.has(String(event?.txid ?? "").toLowerCase()),
    )
    .sort(
      (left, right) =>
        Date.parse(right.createdAt) - Date.parse(left.createdAt) ||
        compareCanonicalUtf8(left.txid, right.txid),
    );
  const salesByTxid = new Map(
    newSales.map((sale) => [String(sale.txid ?? "").toLowerCase(), sale]),
  );
  const closedListings = (Array.isArray(state.closedListings)
    ? state.closedListings
    : []
  ).map((listing) => {
    const sale = salesByTxid.get(String(listing?.closedTxid ?? "").toLowerCase());
    return sale
      ? {
          ...listing,
          closedAt: sale.createdAt,
          closedConfirmed: true,
        }
      : listing;
  });

  return tokenStateWithPendingStats({
    ...state,
    closedListings,
    holders: nextHolders,
    indexedAt: new Date().toISOString(),
    invalidEvents: nextInvalidEvents,
    sales: nextSales,
    stats: {
      ...(state.stats ?? {}),
      holders: nextHolders.length,
    },
  });
}

async function workTokenStateWithRecoveredListingCloseSales(state, network) {
  if (network === "livenet") {
    return state;
  }
  const recoveredSales = await recoverWorkSalesFromClosedListings(state, network);
  return recoveredSales.length > 0
    ? workTokenStateWithRecoveredSales(state, recoveredSales)
    : state;
}

function confirmedWorkMintEventsFromTransaction(tx, network) {
  const txid = transactionTxid(tx);
  if (!txid || !transactionConfirmed(tx)) {
    return [];
  }

  const vin = Array.isArray(tx.vin) ? tx.vin : [];
  const vout = Array.isArray(tx.vout) ? tx.vout : [];
  const minterAddress = transactionInputAddresses(vin)[0] ?? "";
  if (!isValidBitcoinAddress(minterAddress, network)) {
    return [];
  }

  const messages = decodedProtocolMessages(vout, TOKEN_PROTOCOL_PREFIX);
  if (messages.length === 0) {
    return [];
  }

  let remainingRegistrySats = tokenPaymentAmountBeforeProtocol(
    vout,
    WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
  );
  const createdAt = new Date(tokenTransactionTime(tx)).toISOString();
  const events = [];

  for (const message of messages) {
    const parsed = parseTokenPayload(message, network);
    if (
      !parsed ||
      parsed.kind !== "mint" ||
      parsed.tokenId !== WORK_TOKEN_ID ||
      parsed.amount !== WORK_TOKEN_MINT_AMOUNT ||
      remainingRegistrySats < WORK_TOKEN_MINT_PRICE_SATS
    ) {
      continue;
    }

    remainingRegistrySats -= WORK_TOKEN_MINT_PRICE_SATS;
    events.push({
      amount: WORK_TOKEN_MINT_AMOUNT,
      confirmed: true,
      createdAt,
      dataBytes: proofProtocolDataBytesForVout(vout),
      minterAddress,
      network,
      paidSats: WORK_TOKEN_MINT_PRICE_SATS,
      registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
      ticker: WORK_TOKEN_TICKER,
      tokenId: WORK_TOKEN_ID,
      txid,
    });
  }

  return events;
}

function workTokenDeltaHasNonMintActions(txs, network) {
  return (Array.isArray(txs) ? txs : []).some((tx) => {
    const vout = Array.isArray(tx?.vout) ? tx.vout : [];
    return decodedProtocolMessages(vout, TOKEN_PROTOCOL_PREFIX).some(
      (message) => {
        const parsed = parseTokenPayload(message, network);
        return parsed && parsed.kind !== "mint";
      },
    );
  });
}

async function recentWorkTokenMarketCloseTransactions(
  network,
  maxCloseTxs,
  maxScanTxids,
) {
  const closeLimit = Math.max(0, Number(maxCloseTxs) || 0);
  const scanLimit = Math.max(0, Number(maxScanTxids) || 0);
  const cacheKey = `close:${network}:${closeLimit}:${scanLimit}`;
  const cached = WORK_TOKEN_NON_MINT_HISTORY_CACHE.get(cacheKey);
  if (cached && Date.now() < cached.expiresAt) {
    return cached.txs;
  }
  if (closeLimit === 0 || scanLimit === 0) {
    return [];
  }

  let historyTxids = [];
  try {
    historyTxids = await fetchAddressHistoryTxidsFromElectrum(
      WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
      network,
    );
  } catch (error) {
    console.error(
      `WORK close history lookup failed for ${network}: ${errorSummary(error)}`,
    );
    return [];
  }

  const candidateTxids = [...historyTxids]
    .reverse()
    .filter((txid) => /^[0-9a-f]{64}$/u.test(txid))
    .slice(0, scanLimit);
  const closeTxs = [];
  const batchSize = Math.max(1, TX_FETCH_CONCURRENCY * 4);
  let failedFetches = 0;
  let scanned = 0;

  for (let start = 0; start < candidateTxids.length; start += batchSize) {
    const batch = candidateTxids.slice(start, start + batchSize);
    scanned += batch.length;
    const txs = await mapWithConcurrency(
      batch,
      TX_FETCH_CONCURRENCY,
      async (txid) => {
        const tx = await fetchTransactionFromElectrum(txid, network, {
          includePrevouts: false,
        }).catch(() => null);
        if (!tx) {
          failedFetches += 1;
        }
        return tx;
      },
    );

    for (const tx of txs.filter(Boolean)) {
      const kinds = workTokenNonMintActionKindsFromTransaction(tx, network);
      if (!kinds.has("delist") && !kinds.has("buy")) {
        continue;
      }
      closeTxs.push(tx);
      if (closeTxs.length >= closeLimit) {
        break;
      }
    }

    if (closeTxs.length >= closeLimit) {
      break;
    }
  }

  if (failedFetches > 0) {
    console.error(
      `WORK close history hydration was partial for ${network}: ${failedFetches} transaction lookup(s) failed while scanning ${scanned}.`,
    );
  }

  const fullCloseTxs = await mapWithConcurrency(
    closeTxs,
    TX_FETCH_CONCURRENCY,
    async (tx) =>
      (await fetchTransactionFromElectrum(transactionTxid(tx), network).catch(
        () => null,
      )) ?? tx,
  );
  const annotated = await annotateBlockOrder(
    dedupeTransactions(fullCloseTxs.filter(Boolean)),
    network,
  );
  cacheWorkTokenRecoveryTransactions(
    WORK_TOKEN_NON_MINT_HISTORY_CACHE,
    cacheKey,
    annotated,
  );
  return annotated;
}

function workTokenStateWithRecoveredListingClosesFromTransactions(
  state,
  txs,
  network,
) {
  if (network === "livenet") {
    return state;
  }
  const listings = new Map();
  for (const listing of Array.isArray(state?.listings) ? state.listings : []) {
    if (listing?.listingId) {
      listings.set(String(listing.listingId).toLowerCase(), listing);
    }
  }
  if (listings.size === 0) {
    return state;
  }

  const closedListings = Array.isArray(state?.closedListings)
    ? [...state.closedListings]
    : [];
  const closedKeys = new Set(
    closedListings.map(
      (listing) =>
        `${String(listing?.listingId ?? "").toLowerCase()}:${String(
          listing?.closedTxid ?? "",
        ).toLowerCase()}`,
    ),
  );
  let changed = false;

  for (const tx of tokenProtocolSortedTransactions(
    (Array.isArray(txs) ? txs : []).filter(Boolean),
  )) {
    const txid = transactionTxid(tx);
    if (!txid) {
      continue;
    }

    const vin = Array.isArray(tx.vin) ? tx.vin : [];
    const vout = Array.isArray(tx.vout) ? tx.vout : [];
    const actorAddress = inputAddresses(vin)[0] ?? "";
    const hasActorAddress = isValidBitcoinAddress(actorAddress, network);
    const eventSpentOutpoints = spentOutpoints(vin);
    let remainingRegistrySats = tokenPaymentAmountBeforeProtocol(
      vout,
      WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
    );
    const confirmed = transactionConfirmed(tx);
    const createdAt = new Date(tokenTransactionTime(tx)).toISOString();

    for (const message of decodedProtocolMessages(vout, TOKEN_PROTOCOL_PREFIX)) {
      const parsed = parseTokenPayload(message, network);
      const listingId = String(parsed?.listingId ?? "").toLowerCase();
      const listing = listings.get(listingId);
      if (
        !listing ||
        (parsed?.kind !== "delist" && parsed?.kind !== "buy") ||
        remainingRegistrySats < TOKEN_MIN_MUTATION_PRICE_SATS ||
        !spendsTokenListingAnchor(eventSpentOutpoints, listing) ||
        (parsed.kind === "delist" &&
          hasActorAddress &&
          listing.sellerAddress !== actorAddress)
      ) {
        continue;
      }

      remainingRegistrySats -= TOKEN_MIN_MUTATION_PRICE_SATS;
      const key = `${listing.listingId}:${txid}`;
      if (!closedKeys.has(key)) {
        closedListings.push({
          ...listing,
          closedAt: createdAt,
          closedConfirmed: confirmed,
          closedTxid: txid,
          closedVin: transactionOutpointSpendIndex(
            tx,
            listing.listingId,
            listing.saleAuthorization.anchorVout,
          ),
        });
        closedKeys.add(key);
      }
      listings.delete(listingId);
      changed = true;
    }
  }

  if (!changed) {
    return state;
  }

  return {
    ...state,
    closedListings: sortClosedTokenListings(closedListings),
    indexedAt: new Date().toISOString(),
    listings: [...listings.values()].sort(
      (left, right) =>
        Number(right.confirmed) - Number(left.confirmed) ||
        Date.parse(right.createdAt) - Date.parse(left.createdAt) ||
        compareCanonicalUtf8(left.listingId, right.listingId),
    ),
  };
}

function workTokenNonMintActionKindsFromTransaction(tx, network) {
  const vout = Array.isArray(tx?.vout) ? tx.vout : [];
  const registryMutationSats = tokenPaymentAmountBeforeProtocol(
    vout,
    WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
  );
  const kinds = new Set();
  for (const message of decodedProtocolMessages(vout, TOKEN_PROTOCOL_PREFIX)) {
    const parsed = parseTokenPayload(message, network);
    const tokenId = parsed?.tokenId ?? parsed?.saleAuthorization?.tokenId ?? "";
    const isListingScopedWorkCandidate =
      (parsed?.kind === "delist" || parsed?.kind === "buy") &&
      /^[0-9a-f]{64}$/u.test(String(parsed?.listingId ?? "")) &&
      registryMutationSats >= TOKEN_MIN_MUTATION_PRICE_SATS;
    if (
      !parsed ||
      parsed.kind === "mint" ||
      (tokenId !== WORK_TOKEN_ID && !isListingScopedWorkCandidate)
    ) {
      continue;
    }

    kinds.add(parsed.kind);
  }
  return kinds;
}

function workTokenTransactionHasNonMintAction(tx, network) {
  return workTokenNonMintActionKindsFromTransaction(tx, network).size > 0;
}

function cacheWorkTokenRecoveryTransactions(cache, cacheKey, txs) {
  const now = Date.now();
  for (const [entryKey, entry] of cache) {
    if (now >= Number(entry?.expiresAt ?? 0)) {
      cache.delete(entryKey);
    }
  }
  while (cache.size >= WORK_TOKEN_RECOVERY_CACHE_MAX_ENTRIES) {
    const oldestKey = cache.keys().next().value;
    if (!oldestKey) {
      break;
    }
    cache.delete(oldestKey);
  }
  cache.set(cacheKey, {
    expiresAt: now + WORK_TOKEN_RECOVERY_CACHE_TTL_MS,
    txs,
  });
}

function explicitWorkTokenCloseRecoveryTxs(network) {
  const entry = WORK_TOKEN_EXPLICIT_CLOSE_RECOVERY_CACHE.get(
    String(network || "livenet"),
  );
  if (!entry || Date.now() >= Number(entry.expiresAt ?? 0)) {
    return [];
  }
  return Array.isArray(entry.txs) ? entry.txs : [];
}

function cacheExplicitWorkTokenCloseRecoveryTxs(network, txs) {
  const confirmedCloseTxs = (Array.isArray(txs) ? txs : []).filter((tx) => {
    if (!transactionConfirmed(tx)) {
      return false;
    }
    const kinds = workTokenNonMintActionKindsFromTransaction(tx, network);
    return kinds.has("delist") || kinds.has("buy");
  });
  if (confirmedCloseTxs.length === 0) {
    return;
  }

  const key = String(network || "livenet");
  const merged = dedupeTransactions([
    ...explicitWorkTokenCloseRecoveryTxs(network),
    ...confirmedCloseTxs,
  ]).slice(-Math.max(1, WORK_TOKEN_LIVE_CLOSE_MAX_TXS));
  WORK_TOKEN_EXPLICIT_CLOSE_RECOVERY_CACHE.set(key, {
    expiresAt:
      Date.now() + Math.max(WORK_TOKEN_RECOVERY_CACHE_TTL_MS, 10 * 60_000),
    txs: merged,
  });
}

async function recentUnknownWorkTokenNonMintTransactions(
  network,
  knownTxids,
  maxActionTxs,
  maxScanTxids,
) {
  const cacheKey = `${network}:${maxActionTxs}:${maxScanTxids}`;
  const cached = WORK_TOKEN_NON_MINT_HISTORY_CACHE.get(cacheKey);
  if (cached && Date.now() < cached.expiresAt) {
    return cached.txs;
  }

  let historyTxids = [];
  try {
    historyTxids = await fetchAddressHistoryTxidsFromElectrum(
      WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
      network,
    );
  } catch (error) {
    console.error(
      `WORK live non-mint history lookup failed for ${network}: ${errorSummary(error)}`,
    );
    return [];
  }

  const candidateTxids = [...historyTxids]
    .reverse()
    .filter((txid) => /^[0-9a-f]{64}$/u.test(txid))
    .slice(0, Math.max(0, maxScanTxids));
  if (candidateTxids.length === 0) {
    return [];
  }

  const maxActions = Math.max(0, maxActionTxs);
  if (maxActions === 0) {
    return [];
  }

  const recovered = [];
  const batchSize = Math.max(1, TX_FETCH_CONCURRENCY * 4);
  let failedFetches = 0;
  let scanned = 0;

  for (let start = 0; start < candidateTxids.length; start += batchSize) {
    const batch = candidateTxids.slice(start, start + batchSize);
    scanned += batch.length;
    const txs = await mapWithConcurrency(
      batch,
      TX_FETCH_CONCURRENCY,
      async (txid) => {
        try {
          return await fetchTransactionWithSourceFallback(txid, network);
        } catch {
          failedFetches += 1;
          return null;
        }
      },
    );

    for (const tx of txs.filter(Boolean)) {
      if (!workTokenTransactionHasNonMintAction(tx, network)) {
        continue;
      }

      recovered.push(tx);
      if (recovered.length >= maxActions) {
        break;
      }
    }

    if (recovered.length >= maxActions) {
      break;
    }
  }

  if (failedFetches > 0) {
    console.error(
      `WORK live non-mint hydration was partial for ${network}: ${failedFetches} transaction lookup(s) failed while scanning ${scanned}.`,
    );
  }
  if (recovered.length > 0) {
    console.log(
      `Recovered ${recovered.length} WORK non-mint registry transaction(s) while scanning ${scanned} recent unknown txid(s) for ${network}.`,
    );
  }

  const annotated = await annotateBlockOrder(dedupeTransactions(recovered), network);
  cacheWorkTokenRecoveryTransactions(
    WORK_TOKEN_NON_MINT_HISTORY_CACHE,
    cacheKey,
    annotated,
  );
  return annotated;
}

function workTokenParticipantRecoveryAddresses(state, network, extraAddresses = []) {
  const addresses = new Set();
  const addAddress = (address) => {
    if (isValidBitcoinAddress(address, network)) {
      addresses.add(address);
    }
  };

  for (const address of Array.isArray(extraAddresses) ? extraAddresses : []) {
    addAddress(address);
  }
  if (addresses.size > 0) {
    return [...addresses].slice(
      0,
      Math.max(0, WORK_TOKEN_LIVE_PARTICIPANT_ADDRESS_MAX),
    );
  }

  for (const listing of Array.isArray(state?.listings) ? state.listings : []) {
    addAddress(listing?.sellerAddress);
  }
  for (const holder of Array.isArray(state?.holders) ? state.holders : []) {
    if (Number(holder?.balance) > 0) {
      addAddress(holder.address);
    }
  }
  for (const listing of Array.isArray(state?.closedListings)
    ? state.closedListings
    : []) {
    addAddress(listing?.sellerAddress);
  }
  for (const transfer of Array.isArray(state?.transfers) ? state.transfers : []) {
    addAddress(transfer?.senderAddress);
    addAddress(transfer?.recipientAddress);
  }
  for (const sale of Array.isArray(state?.sales) ? state.sales : []) {
    addAddress(sale?.sellerAddress);
    addAddress(sale?.buyerAddress);
  }

  return [...addresses].slice(
    0,
    Math.max(0, WORK_TOKEN_LIVE_PARTICIPANT_ADDRESS_MAX),
  );
}

async function recentUnknownWorkTokenParticipantTransactions(
  state,
  network,
  knownTxids,
  maxTxsPerAddress,
  extraAddresses = [],
) {
  const normalizedKnown = knownTxids instanceof Set ? knownTxids : new Set();
  if (normalizedKnown.size === 0) {
    return [];
  }

  const addresses = workTokenParticipantRecoveryAddresses(
    state,
    network,
    extraAddresses,
  );
  if (addresses.length === 0) {
    return [];
  }
  const cacheKey = `${network}:${maxTxsPerAddress}:${addresses.join(",")}`;
  const cached = WORK_TOKEN_PARTICIPANT_RECOVERY_CACHE.get(cacheKey);
  if (cached && Date.now() < cached.expiresAt) {
    return cached.txs;
  }

  const hasExplicitRecoveryAddresses =
    Array.isArray(extraAddresses) && extraAddresses.length > 0;
  let failedAddresses = 0;
  const groups = await mapWithConcurrency(
    addresses,
    Math.min(TX_FETCH_CONCURRENCY, 6),
    async (address) => {
      try {
        if (hasExplicitRecoveryAddresses) {
          return await fetchRecentUnknownAddressHistoryTransactions(
            address,
            network,
            normalizedKnown,
            Math.max(1, maxTxsPerAddress),
          );
        }

        const pageTxs = await fetchRecentUnknownAddressTransactions(
          address,
          network,
          normalizedKnown,
          Math.max(1, maxTxsPerAddress),
        );
        if (pageTxs.length > 0) {
          return pageTxs;
        }

        return await fetchRecentUnknownAddressHistoryTransactions(
          address,
          network,
          normalizedKnown,
          Math.max(1, maxTxsPerAddress),
        );
      } catch (error) {
        failedAddresses += 1;
        console.error(
          `WORK participant recovery lookup failed for ${address}: ${errorSummary(error)}`,
        );
        return [];
      }
    },
  );
  if (failedAddresses > 0) {
    console.error(
      `WORK participant recovery had ${failedAddresses} address lookup failure(s) for ${network}.`,
    );
  }

  const recovered = dedupeTransactions(groups.flat()).filter((tx) =>
    workTokenTransactionHasNonMintAction(tx, network),
  );
  if (recovered.length > 0) {
    console.log(
      `Recovered ${recovered.length} WORK non-mint participant transaction(s) from ${addresses.length} address scan(s) for ${network}.`,
    );
  }

  const annotated = await annotateBlockOrder(recovered, network);
  cacheWorkTokenRecoveryTransactions(
    WORK_TOKEN_PARTICIPANT_RECOVERY_CACHE,
    cacheKey,
    annotated,
  );
  return annotated;
}

function workMintSupplyTotals(mints) {
  const rows = workMintRowsWithinPendingCap(mints);
  return {
    confirmedMints: rows.filter((mint) => mint.confirmed).length,
    confirmedSupply: rows
      .filter((mint) => mint.confirmed)
      .reduce((total, mint) => total + Number(mint.amount || 0), 0),
    pendingMints: rows.filter((mint) => !mint.confirmed).length,
    pendingSupply: rows
      .filter((mint) => !mint.confirmed)
      .reduce((total, mint) => total + Number(mint.amount || 0), 0),
  };
}

function sortWorkMintsForDisplay(mints) {
  return [...(Array.isArray(mints) ? mints : [])].sort(
    (left, right) =>
      Number(right.confirmed) - Number(left.confirmed) ||
      Date.parse(right.createdAt) - Date.parse(left.createdAt) ||
      compareCanonicalUtf8(left.txid, right.txid),
  );
}

function sortWorkMintsForPendingCap(mints) {
  return [...(Array.isArray(mints) ? mints : [])].sort(
    (left, right) =>
      compareCanonicalUtf8(left.txid, right.txid) ||
      Date.parse(left.createdAt) - Date.parse(right.createdAt),
  );
}

function workMintRowsWithinPendingCap(mints) {
  const rows = (Array.isArray(mints) ? mints : []).filter(
    (mint) => Number(mint?.amount) > 0,
  );
  const confirmed = rows.filter((mint) => mint.confirmed);
  const confirmedSupply = confirmed.reduce(
    (total, mint) => total + Number(mint.amount || 0),
    0,
  );
  const acceptedPending = [];
  let pendingSupply = 0;

  for (const mint of sortWorkMintsForPendingCap(
    rows.filter((item) => !item.confirmed),
  )) {
    const amount = Number(mint.amount || 0);
    if (confirmedSupply + pendingSupply + amount > WORK_TOKEN_MAX_SUPPLY) {
      continue;
    }

    pendingSupply += amount;
    acceptedPending.push(mint);
  }

  return [...confirmed, ...acceptedPending];
}

function workTokenStateWithMintSupplyCounters(state) {
  const workTokenDefinition = (Array.isArray(state?.tokens)
    ? state.tokens
    : []
  ).find((token) => isWorkTokenId(token?.tokenId));
  const workAmountStorageModel =
    state?.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL ||
    state?.precisionModel === WORK_PRECISION_V2_MODEL ||
    workRecordUsesSubatoms(workTokenDefinition)
      ? WORK_SUBATOM_PROJECTION_MODEL
      : WORK_ATOMIC_PROJECTION_MODEL;
  const cappedMints = workMintRowsWithinPendingCap(state?.mints);
  const totals = workMintSupplyTotals(cappedMints);
  const exactSupply = (confirmed) =>
    cappedMints
      .filter((mint) => mint?.confirmed === confirmed)
      .reduce((total, mint) => {
        const amount = tokenLedgerAmountFromRecord(
          WORK_TOKEN_ID,
          mint,
          { workAmountStorageModel },
        );
        if (amount === null) {
          throw new Error(
            "WORK mint counters contain a noncanonical mint amount.",
          );
        }
        return total + amount;
      }, 0n);
  const confirmedSupplyUnits = exactSupply(true);
  const pendingSupplyUnits = exactSupply(false);
  const storedSupplyUnits = (confirmed) =>
    tokenLedgerAmountFromRecord(
      WORK_TOKEN_ID,
      {
        amount: confirmed
          ? state?.confirmedSupply
          : state?.pendingSupply,
        amountAtoms: confirmed
          ? state?.confirmedSupplyAtoms
          : state?.pendingSupplyAtoms,
        amountStorageModel: workAmountStorageModel,
        amountSubatoms: confirmed
          ? state?.confirmedSupplySubatoms
          : state?.pendingSupplySubatoms,
        precisionModel: state?.precisionModel,
      },
      { allowZero: true, workAmountStorageModel },
    );
  const stats = state?.stats && typeof state.stats === "object" ? state.stats : {};
  const changed =
    (Array.isArray(state?.mints) ? state.mints.length : 0) !==
      cappedMints.length ||
    storedSupplyUnits(true) !== confirmedSupplyUnits ||
    storedSupplyUnits(false) !== pendingSupplyUnits ||
    Number(stats.confirmedMints ?? 0) !== totals.confirmedMints ||
    Number(stats.pendingMints ?? 0) !== totals.pendingMints;
  if (!changed) {
    return state;
  }

  const precisionState =
    workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
      ? (() => {
          const {
            confirmedSupplyAtoms: _confirmedSupplyAtoms,
            pendingSupplyAtoms: _pendingSupplyAtoms,
            ...current
          } = state;
          return current;
        })()
      : (() => {
          const {
            confirmedSupplySubatoms: _confirmedSupplySubatoms,
            pendingSupplySubatoms: _pendingSupplySubatoms,
            precisionModel: _precisionModel,
            ...current
          } = state;
          return current;
        })();
  const tokens = (Array.isArray(state?.tokens) ? state.tokens : []).map(
    (token) =>
      isWorkTokenId(token?.tokenId)
        ? canonicalWorkTokenDefinition(
            token?.network ?? state?.network ?? "livenet",
            workAmountStorageModel,
          )
        : token,
  );
  return {
    ...precisionState,
    amountStorageModel: workAmountStorageModel,
    confirmedSupply:
      workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
        ? formatWorkSubatoms(confirmedSupplyUnits)
        : formatWorkAtoms(confirmedSupplyUnits),
    ...(workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
      ? {
          confirmedSupplySubatoms: confirmedSupplyUnits.toString(),
          decimals: WORK_SUBATOM_DECIMALS,
          pendingSupplySubatoms: pendingSupplyUnits.toString(),
          precisionModel: WORK_PRECISION_V2_MODEL,
          unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
        }
      : {
          confirmedSupplyAtoms: confirmedSupplyUnits.toString(),
          decimals: WORK_DECIMALS,
          pendingSupplyAtoms: pendingSupplyUnits.toString(),
          unitScale: WORK_UNIT_SCALE_TEXT,
        }),
    mints: sortWorkMintsForDisplay(cappedMints),
    pendingSupply:
      workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
        ? formatWorkSubatoms(pendingSupplyUnits)
        : formatWorkAtoms(pendingSupplyUnits),
    stats: {
      ...stats,
      confirmedMints: totals.confirmedMints,
      pendingMints: totals.pendingMints,
    },
    tokens,
  };
}

function workTokenDeltaTransactionsWithoutUnverifiedMarketMutations(
  txs,
  network,
) {
  const source = Array.isArray(txs) ? txs : [];
  if (network !== "livenet") {
    return source;
  }
  return source.filter(
    (tx) =>
      ![...workTokenNonMintActionKindsFromTransaction(tx, network)].some(
        (kind) => ["list", "seal", "delist", "buy"].includes(kind),
      ),
  );
}

function workTokenStateWithDeltaTransactions(
  state,
  txs,
  network,
  privateReplayCapability = null,
) {
  // Passing this exact private capability selects the ordered, copy-on-write
  // pending ledger used only by the atomic WORK staging route.
  const exactPendingStageReplay =
    privateReplayCapability === workTokenStateWithDeltaTransactions;
  txs =
    exactPendingStageReplay
      ? Array.isArray(txs)
        ? txs
        : []
      : workTokenDeltaTransactionsWithoutUnverifiedMarketMutations(
          txs,
          network,
        );
  if (txs.length === 0) {
    return state;
  }
  const workTokenDefinition = (Array.isArray(state?.tokens)
    ? state.tokens
    : []
  ).find((token) => isWorkTokenId(token?.tokenId));
  const workAmountStorageModel =
    state?.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL ||
    state?.precisionModel === WORK_PRECISION_V2_MODEL ||
    workRecordUsesSubatoms(workTokenDefinition)
      ? WORK_SUBATOM_PROJECTION_MODEL
      : WORK_ATOMIC_PROJECTION_MODEL;
  const ledgerAmountFromRecord = (record, options = {}) =>
    tokenLedgerAmountFromRecord(WORK_TOKEN_ID, record, {
      ...options,
      workAmountStorageModel,
    });
  const ledgerAmountFields = (amount, options = {}) =>
    tokenLedgerAmountFields(WORK_TOKEN_ID, amount, {
      ...options,
      workAmountStorageModel,
    });
  const ledgerBalanceFields = (balance) =>
    tokenLedgerBalanceFields(WORK_TOKEN_ID, balance, {
      workAmountStorageModel,
    });
  const incomingConfirmedTxids = new Set(
    (Array.isArray(txs) ? txs : [])
      .filter(transactionConfirmed)
      .map(transactionTxid)
      .filter(Boolean)
      .map((txid) => txid.toLowerCase()),
  );
  const matchesIncomingConfirmedTxid = (...values) => {
    if (incomingConfirmedTxids.size === 0) {
      return false;
    }
    return values.some((value) =>
      typeof value === "string" &&
      incomingConfirmedTxids.has(value.toLowerCase()),
    );
  };
  const confirmedPendingSealTxids = new Set();
  for (const item of [
    ...(Array.isArray(state?.listings) ? state.listings : []),
    ...(Array.isArray(state?.closedListings) ? state.closedListings : []),
  ]) {
    if (
      item?.sealConfirmed === false &&
      matchesIncomingConfirmedTxid(item.sealTxid)
    ) {
      confirmedPendingSealTxids.add(String(item.sealTxid).toLowerCase());
    }
  }
  const shouldDropConfirmedDeltaMatch = (item) => {
    return (
      (item?.confirmed === false &&
        matchesIncomingConfirmedTxid(item.txid, item.listingId)) ||
      (item?.closedConfirmed === false &&
        matchesIncomingConfirmedTxid(item.closedTxid))
    );
  };
  const stateMints = workMintRowsWithinPendingCap(
    (Array.isArray(state?.mints) ? state.mints : []).filter(
      (item) => !shouldDropConfirmedDeltaMatch(item),
    ),
  );
  const stateTransfers = (Array.isArray(state?.transfers)
    ? state.transfers
    : []).filter((item) => !shouldDropConfirmedDeltaMatch(item));
  const stateListings = (Array.isArray(state?.listings)
    ? state.listings
    : []).filter((item) => !shouldDropConfirmedDeltaMatch(item));
  const stateClosedListings = (Array.isArray(state?.closedListings)
    ? state.closedListings
    : []).filter((item) => !shouldDropConfirmedDeltaMatch(item));
  const stateSales = (Array.isArray(state?.sales) ? state.sales : []).filter(
    (item) => !shouldDropConfirmedDeltaMatch(item),
  );
  const existingTxids = new Set();
  addTokenStateTxids(existingTxids, {
    closedListings: stateClosedListings,
    listings: stateListings,
    mints: stateMints,
    sales: stateSales,
    transfers: stateTransfers,
  });
  for (const txid of confirmedPendingSealTxids) {
    existingTxids.delete(txid);
  }

  const holderBalances = new Map(
    (Array.isArray(state?.holders) ? state.holders : [])
      .map((holder) => [
        holder?.address,
        ledgerAmountFromRecord(
          {
            amount: holder?.balance,
            amountAtoms: holder?.balanceAtoms,
            amountStorageModel: holder?.amountStorageModel,
            amountSubatoms: holder?.balanceSubatoms,
            precisionModel: holder?.precisionModel,
          },
          { allowZero: true },
        ),
      ])
      .filter(([address, balance]) => address && balance !== null),
  );
  const listings = new Map();
  for (const listing of stateListings) {
    if (!listing?.listingId) {
      continue;
    }
    listings.set(
      listing.listingId,
      mergeTokenListingRecord(listings.get(listing.listingId), listing),
    );
  }
  const closedListings = [...stateClosedListings];
  let invalidEvents = Array.isArray(state?.invalidEvents)
    ? [...state.invalidEvents]
    : [];
  const mints = [...stateMints];
  const sales = [...stateSales];
  const transfers = [...stateTransfers];
  const initialSupplyTotals = workMintSupplyTotals(mints);
  let confirmedSupply = initialSupplyTotals.confirmedSupply;
  let pendingSupply = initialSupplyTotals.pendingSupply;
  let changed =
    Number(state?.confirmedSupply ?? 0) !== confirmedSupply ||
    Number(state?.pendingSupply ?? 0) !== pendingSupply;

  const reservedBalanceFor = (ownerAddress) => {
    let reserved = 0n;
    for (const listing of listings.values()) {
      if (
        listing.tokenId === WORK_TOKEN_ID &&
        listing.sellerAddress === ownerAddress &&
        !tokenListingIsExpired(listing)
      ) {
        const listedAmount = ledgerAmountFromRecord(listing);
        if (listedAmount !== null) {
          reserved += listedAmount;
        }
      }
    }
    return reserved;
  };
  const spendableBalanceFor = (ownerAddress) =>
    (holderBalances.get(ownerAddress) ?? 0n) - reservedBalanceFor(ownerAddress);
  const closeListing = (listing, event) => {
    if (
      closedListings.some(
        (closed) =>
          closed.listingId === listing.listingId &&
          closed.closedTxid === event.txid,
      )
    ) {
      return;
    }
    closedListings.push({
      ...listing,
      closedAt: event.createdAt,
      closedBlockHash: event.blockHash,
      closedBlockHeight: event.blockHeight,
      closedBlockIndex: event.blockIndex,
      closedConfirmed: event.confirmed,
      closedMinerFeeSats: numericValue(event.minerFeeSats),
      closedProtocolVout: event.protocolVout,
      closedRecordOrdinal: event.recordOrdinal,
      closedTxid: event.txid,
    });
    changed = true;
  };

  for (const tx of tokenProtocolSortedTransactions(
    (Array.isArray(txs) ? txs : []).filter(Boolean),
  )) {
    const txid = transactionTxid(tx);
    if (!txid || existingTxids.has(txid)) {
      continue;
    }

    const vin = Array.isArray(tx.vin) ? tx.vin : [];
    const vout = Array.isArray(tx.vout) ? tx.vout : [];
    const txInputAddresses = inputAddresses(vin);
    const actorAddress = txInputAddresses[0] ?? "";
    const hasActorAddress = isValidBitcoinAddress(actorAddress, network);

    const messageEntries = vout.flatMap((output, protocolVout) =>
      decodedProtocolMessages([output], TOKEN_PROTOCOL_PREFIX).map(
        (message, recordOrdinal) => ({
          message,
          protocolVout,
          recordOrdinal,
        }),
      ),
    );
    if (messageEntries.length === 0) {
      continue;
    }

    let remainingRegistrySats = tokenPaymentAmountBeforeProtocol(
      vout,
      WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
    );
    const originalRegistrySats = remainingRegistrySats;
    const paymentOutputs = paymentOutputsBeforeTokenProtocol(vout);
    const eventSpentOutpoints = spentOutpoints(vin);
    const confirmed = transactionConfirmed(tx);
    const createdAt = new Date(tokenTransactionTime(tx)).toISOString();
    const minerFeeSats = transactionMinerFeeSats(tx);
    const blockHash = transactionBlockHash(tx);
    const blockHeight = transactionBlockHeight(tx);
    const blockIndex = transactionBlockIndex(tx);
    let acceptedTxMessage = false;
    let parsedTxMessage = false;
    let parsedTxKind = "";
    let parsedTxProtocolVout;
    let parsedTxRecordOrdinal;
    let parsedTxTokenId = "";
    let rejectedTxMessage = null;
    const rejectedTxMessages = [];

    for (const { message, protocolVout, recordOrdinal } of messageEntries) {
      const parsed = parseTokenPayload(message, network);
      if (!parsed) {
        continue;
      }
      parsedTxMessage = true;
      parsedTxKind = parsed.kind ?? parsedTxKind;
      parsedTxProtocolVout = protocolVout;
      parsedTxRecordOrdinal = recordOrdinal;
      parsedTxTokenId =
        parsed.tokenId ?? parsed.saleAuthorization?.tokenId ?? parsedTxTokenId;

      if (parsed.kind === "mint") {
        const mintAmountUnits = ledgerAmountFromRecord(parsed);
        const expectedMintAmount =
          workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
            ? WORK_TOKEN_MINT_AMOUNT_SUBATOMS
            : WORK_TOKEN_MINT_AMOUNT_ATOMS;
        const projectedSupply = confirmed
          ? confirmedSupply + parsed.amount
          : confirmedSupply + pendingSupply + parsed.amount;
        if (
          parsed.tokenId !== WORK_TOKEN_ID ||
          parsed.amount !== WORK_TOKEN_MINT_AMOUNT ||
          mintAmountUnits !== expectedMintAmount ||
          !hasActorAddress ||
          remainingRegistrySats < WORK_TOKEN_MINT_PRICE_SATS ||
          projectedSupply > WORK_TOKEN_MAX_SUPPLY
        ) {
          continue;
        }

        remainingRegistrySats -= WORK_TOKEN_MINT_PRICE_SATS;
        if (confirmed) {
          confirmedSupply += parsed.amount;
        } else {
          pendingSupply += parsed.amount;
        }
        if (confirmed || exactPendingStageReplay) {
          holderBalances.set(
            actorAddress,
            (holderBalances.get(actorAddress) ?? 0n) + mintAmountUnits,
          );
        }
        mints.push({
          ...ledgerAmountFields(mintAmountUnits),
          blockHash,
          blockHeight,
          blockIndex,
          confirmed,
          createdAt,
          dataBytes: proofProtocolDataBytesForVout(vout),
          minterAddress: actorAddress,
          minerFeeSats,
          network,
          paidSats: WORK_TOKEN_MINT_PRICE_SATS,
          protocolVout,
          recordOrdinal,
          registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
          ticker: WORK_TOKEN_TICKER,
          tokenId: WORK_TOKEN_ID,
          txid,
        });
        acceptedTxMessage = true;
        changed = true;
        continue;
      }

      if (parsed.kind === "send") {
        const parsedAmount = ledgerAmountFromRecord(parsed);
        const confirmedBalance = holderBalances.get(actorAddress) ?? 0n;
        const spendableBalance = spendableBalanceFor(actorAddress);
        if (
          parsed.tokenId !== WORK_TOKEN_ID ||
          parsedAmount === null ||
          !hasActorAddress ||
          remainingRegistrySats < TOKEN_MIN_MUTATION_PRICE_SATS
        ) {
          continue;
        }
        if (
          (confirmed || exactPendingStageReplay) &&
          spendableBalance < parsedAmount
        ) {
          const reservedBalance = reservedBalanceFor(actorAddress);
          rejectedTxMessage = insufficientTokenBalanceInvalidEvent({
            actorAddress,
            amount: parsedAmount,
            confirmedBalance,
            recipientAddress: parsed.recipientAddress,
            reservedBalance,
            ticker: WORK_TOKEN_TICKER,
            tokenId: WORK_TOKEN_ID,
            workAmountStorageModel,
          });
          rejectedTxMessage.protocolVout = protocolVout;
          rejectedTxMessage.recordOrdinal = recordOrdinal;
          rejectedTxMessages.push(rejectedTxMessage);
          continue;
        }

        remainingRegistrySats -= TOKEN_MIN_MUTATION_PRICE_SATS;
        if (confirmed || exactPendingStageReplay) {
          holderBalances.set(
            actorAddress,
            (holderBalances.get(actorAddress) ?? 0n) - parsedAmount,
          );
          holderBalances.set(
            parsed.recipientAddress,
            (holderBalances.get(parsed.recipientAddress) ?? 0n) + parsedAmount,
          );
        }
        transfers.push({
          ...ledgerAmountFields(parsedAmount),
          amountVersion: parsed.amountVersion ?? "legacy-whole",
          blockHash,
          blockHeight,
          blockIndex,
          confirmed,
          createdAt,
          dataBytes: proofProtocolDataBytesForVout(vout),
          minerFeeSats,
          network,
          paidSats: TOKEN_MIN_MUTATION_PRICE_SATS,
          protocolVout,
          recipientAddress: parsed.recipientAddress,
          recordOrdinal,
          registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
          senderAddress: actorAddress,
          ticker: WORK_TOKEN_TICKER,
          tokenId: WORK_TOKEN_ID,
          txid,
        });
        acceptedTxMessage = true;
        changed = true;
        continue;
      }

      if (parsed.kind === "list") {
        const authorization = parsed.saleAuthorization;
        const listedAmount = ledgerAmountFromRecord(authorization);
        if (
          authorization.tokenId !== WORK_TOKEN_ID ||
          listedAmount === null ||
          authorization.registryAddress !== WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS ||
          authorization.ticker !== WORK_TOKEN_TICKER ||
          !hasActorAddress ||
          authorization.sellerAddress !== actorAddress ||
          remainingRegistrySats < TOKEN_MIN_MUTATION_PRICE_SATS ||
          spendableBalanceFor(actorAddress) < listedAmount ||
          !tokenListingAnchorIsPresent(vout, authorization) ||
          listings.has(txid)
        ) {
          continue;
        }

        remainingRegistrySats -= TOKEN_MIN_MUTATION_PRICE_SATS;
        listings.set(txid, {
          ...ledgerAmountFields(listedAmount),
          blockHash,
          blockHeight,
          blockIndex,
          confirmed,
          createdAt,
          dataBytes: proofProtocolDataBytesForVout(vout),
          listingId: txid,
          minerFeeSats,
          network,
          priceSats: authorization.priceSats,
          protocolVout,
          recordOrdinal,
          registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
          saleAuthorization: authorization,
          sellerAddress: actorAddress,
          ticker: WORK_TOKEN_TICKER,
          tokenId: WORK_TOKEN_ID,
        });
        acceptedTxMessage = true;
        changed = true;
        continue;
      }

      if (parsed.kind === "seal") {
        const listing = listings.get(parsed.listingId);
        const authorization = parsed.saleAuthorization;
        if (
          !listing ||
          !hasActorAddress ||
          listing.sellerAddress !== actorAddress ||
          remainingRegistrySats < TOKEN_MIN_MUTATION_PRICE_SATS ||
          !tokenSaleAuthorizationTermsMatch(
            listing.saleAuthorization,
            authorization,
          ) ||
          authorization.anchorTxid !== listing.listingId ||
          !tokenSaleAuthorizationUsesSaleTicketAnchor(authorization)
        ) {
          continue;
        }

        remainingRegistrySats -= TOKEN_MIN_MUTATION_PRICE_SATS;
        listings.set(listing.listingId, {
          ...listing,
          saleAuthorization: authorization,
          sealAt: createdAt,
          sealBlockHash: blockHash,
          sealBlockHeight: blockHeight,
          sealTransactionBlockHeight: blockHeight,
          sealBlockIndex: blockIndex,
          sealConfirmed: confirmed,
          sealDataBytes: proofProtocolDataBytesForVout(vout),
          sealMinerFeeSats: minerFeeSats,
          sealProtocolVout: protocolVout,
          sealRecordOrdinal: recordOrdinal,
          sealTxid: txid,
        });
        acceptedTxMessage = true;
        changed = true;
        continue;
      }

      if (parsed.kind === "delist") {
        const listing = listings.get(parsed.listingId);
        if (
          !listing ||
          (hasActorAddress && listing.sellerAddress !== actorAddress) ||
          remainingRegistrySats < TOKEN_MIN_MUTATION_PRICE_SATS ||
          !spendsTokenListingAnchor(eventSpentOutpoints, listing)
        ) {
          continue;
        }

        remainingRegistrySats -= TOKEN_MIN_MUTATION_PRICE_SATS;
        closeListing(listing, {
          blockHash,
          blockHeight,
          blockIndex,
          confirmed,
          createdAt,
          minerFeeSats,
          protocolVout,
          recordOrdinal,
          txid,
        });
        listings.delete(listing.listingId);
        acceptedTxMessage = true;
        changed = true;
        continue;
      }

      if (parsed.kind === "buy") {
        const listing = listings.get(parsed.listingId);
        const listingAmount = listing
          ? ledgerAmountFromRecord(listing)
          : null;
        const listingHasValidSaleTicketSpend = listing
          ? tokenSaleAuthorizationUsesSaleTicketAnchor(
              listing.saleAuthorization,
            ) || tokenListingAnchorSpendMatchesAuthorization(vin, listing)
          : false;
        if (
          !listing ||
          listingAmount === null ||
          !txInputAddresses.includes(parsed.buyerAddress) ||
          remainingRegistrySats < TOKEN_MIN_MUTATION_PRICE_SATS ||
          !listingHasValidSaleTicketSpend ||
          (listing.saleAuthorization.buyerAddress &&
            listing.saleAuthorization.buyerAddress !== parsed.buyerAddress) ||
          tokenListingIsExpired(listing) ||
          !spendsTokenListingAnchor(eventSpentOutpoints, listing) ||
          paymentAmountFromSnapshots(paymentOutputs, listing.sellerAddress) <
            tokenSellerPaymentRequiredSats(listing) ||
          ((confirmed || exactPendingStageReplay) &&
            (holderBalances.get(listing.sellerAddress) ?? 0n) < listingAmount)
        ) {
          continue;
        }

        remainingRegistrySats -= TOKEN_MIN_MUTATION_PRICE_SATS;
        closeListing(listing, {
          blockHash,
          blockHeight,
          blockIndex,
          confirmed,
          createdAt,
          minerFeeSats,
          protocolVout,
          recordOrdinal,
          txid,
        });
        listings.delete(listing.listingId);
        if (confirmed || exactPendingStageReplay) {
          holderBalances.set(
            listing.sellerAddress,
            (holderBalances.get(listing.sellerAddress) ?? 0n) - listingAmount,
          );
          holderBalances.set(
            parsed.buyerAddress,
            (holderBalances.get(parsed.buyerAddress) ?? 0n) + listingAmount,
          );
        }
        sales.push({
          ...ledgerAmountFields(listingAmount),
          blockHash,
          blockHeight,
          blockIndex,
          buyerAddress: parsed.buyerAddress,
          confirmed,
          createdAt,
          listingId: listing.listingId,
          minerFeeSats,
          network,
          paidSats:
            tokenSellerPaymentRequiredSats(listing) +
            TOKEN_MIN_MUTATION_PRICE_SATS,
          priceSats: listing.priceSats,
          protocolVout,
          recordOrdinal,
          registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
          sellerAddress: listing.sellerAddress,
          ticker: WORK_TOKEN_TICKER,
          tokenId: WORK_TOKEN_ID,
          txid,
        });
        acceptedTxMessage = true;
        changed = true;
      }
    }

    if (exactPendingStageReplay && rejectedTxMessages.length > 0) {
      invalidEvents = invalidEvents.filter((event) => event.txid !== txid);
      for (const rejectedMessage of rejectedTxMessages) {
        invalidEvents.push({
          ...rejectedMessage,
          attemptedKind: "send",
          auditMinerFeeSats: minerFeeSats,
          auditRegistryPaymentSats: originalRegistrySats,
          auditTotalCostSats: minerFeeSats + originalRegistrySats,
          blockHash,
          blockHeight,
          blockIndex,
          confirmed: false,
          createdAt,
          kind: "send",
          network,
          registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
          tokenId: WORK_TOKEN_ID,
          txid,
        });
      }
      changed = true;
    }

    if (acceptedTxMessage) {
      if (!exactPendingStageReplay || rejectedTxMessages.length === 0) {
        invalidEvents = invalidEvents.filter((event) => event.txid !== txid);
      }
      existingTxids.add(txid);
      continue;
    }

    if (
      confirmed &&
      parsedTxMessage &&
      originalRegistrySats >= TOKEN_MIN_MUTATION_PRICE_SATS
    ) {
      const invalidEvent = {
        ...(rejectedTxMessage ?? {}),
        amount: rejectedTxMessage?.amount ?? 0,
        auditMinerFeeSats: minerFeeSats,
        auditRegistryPaymentSats: originalRegistrySats,
        auditTotalCostSats: minerFeeSats + originalRegistrySats,
        blockHeight,
        blockIndex,
        blockHash,
        confirmed,
        createdAt,
        kind: parsedTxKind || "unknown",
        network,
        protocolVout: parsedTxProtocolVout,
        recordOrdinal: parsedTxRecordOrdinal,
        reason:
          rejectedTxMessage?.reason ?? "no-valid-work-token-event",
        registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
        tokenId: parsedTxTokenId,
        txid,
      };
      const existingInvalidIndex = invalidEvents.findIndex(
        (event) => event.txid === txid,
      );
      if (existingInvalidIndex < 0) {
        invalidEvents.push(invalidEvent);
        changed = true;
      } else if (rejectedTxMessage) {
        invalidEvents[existingInvalidIndex] = invalidEvent;
        changed = true;
      }
    }
  }

  if (!changed) {
    return state;
  }

  const holders = [...holderBalances.entries()]
    .filter(([, balance]) => balance > 0)
    .map(([address, balance]) => ({
      address,
      ledgerBalance: balance,
      ...ledgerBalanceFields(balance),
    }))
    .sort(
      (left, right) =>
        (right.ledgerBalance > left.ledgerBalance
          ? 1
          : right.ledgerBalance < left.ledgerBalance
            ? -1
            : 0) ||
        compareCanonicalUtf8(left.address, right.address),
    )
    .map(({ ledgerBalance, ...holder }) => holder);
  const activeListings = [...listings.values()].sort(
    (left, right) =>
      Number(right.confirmed) - Number(left.confirmed) ||
      Date.parse(right.createdAt) - Date.parse(left.createdAt) ||
      compareCanonicalUtf8(left.listingId, right.listingId),
  );
  const sortedMints = sortWorkMintsForDisplay(workMintRowsWithinPendingCap(mints));
  const mintSupplyTotals = workMintSupplyTotals(sortedMints);
  const sortedSales = sales.sort(
    (left, right) =>
      Number(right.confirmed) - Number(left.confirmed) ||
      Date.parse(right.createdAt) - Date.parse(left.createdAt) ||
      compareCanonicalUtf8(left.txid, right.txid),
  );
  const sortedTransfers = transfers.sort(
    (left, right) =>
      Number(right.confirmed) - Number(left.confirmed) ||
      Date.parse(right.createdAt) - Date.parse(left.createdAt) ||
      compareCanonicalUtf8(left.txid, right.txid),
  );
  const exactMintSupply = (confirmed) =>
    sortedMints
      .filter((mint) => mint.confirmed === confirmed)
      .reduce((total, mint) => {
        const amount = ledgerAmountFromRecord(mint);
        if (amount === null) {
          throw new Error(
            "WORK delta state contains a noncanonical mint amount.",
          );
        }
        return total + amount;
      }, 0n);
  const confirmedSupplyUnits = exactMintSupply(true);
  const pendingSupplyUnits = exactMintSupply(false);
  const precisionState =
    workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
      ? (() => {
          const {
            confirmedSupplyAtoms: _confirmedSupplyAtoms,
            pendingSupplyAtoms: _pendingSupplyAtoms,
            ...current
          } = state;
          return current;
        })()
      : state;
  const tokens = (Array.isArray(state?.tokens) ? state.tokens : []).map(
    (token) => {
      if (
        !isWorkTokenId(token?.tokenId) ||
        workAmountStorageModel !== WORK_SUBATOM_PROJECTION_MODEL
      ) {
        return token;
      }
      const {
        amountStorageModel: _amountStorageModel,
        decimals: _decimals,
        maxSupplyAtoms: _maxSupplyAtoms,
        maxSupplySubatoms: _maxSupplySubatoms,
        mintAmountAtoms: _mintAmountAtoms,
        mintAmountSubatoms: _mintAmountSubatoms,
        precisionModel: _precisionModel,
        unitScale: _unitScale,
        ...definition
      } = token;
      return {
        ...definition,
        ...canonicalWorkTokenDefinition(
          network,
          WORK_SUBATOM_PROJECTION_MODEL,
        ),
      };
    },
  );

  return {
    ...precisionState,
    closedListings: sortClosedTokenListings(closedListings),
    confirmedSupply:
      workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
        ? formatWorkSubatoms(confirmedSupplyUnits)
        : mintSupplyTotals.confirmedSupply,
    ...(workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
      ? {
          amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
          confirmedSupplySubatoms: confirmedSupplyUnits.toString(),
          decimals: WORK_SUBATOM_DECIMALS,
          pendingSupplySubatoms: pendingSupplyUnits.toString(),
          precisionModel: WORK_PRECISION_V2_MODEL,
          unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
        }
      : {
          amountStorageModel: WORK_ATOMIC_PROJECTION_MODEL,
          confirmedSupplyAtoms: workSupplyAtomsText(
            mintSupplyTotals.confirmedSupply,
          ),
          decimals: WORK_DECIMALS,
          pendingSupplyAtoms: workSupplyAtomsText(
            mintSupplyTotals.pendingSupply,
          ),
          unitScale: WORK_UNIT_SCALE_TEXT,
        }),
    holders,
    indexedAt: new Date().toISOString(),
    invalidEvents: invalidEvents.sort(
      (left, right) =>
        Date.parse(right.createdAt) - Date.parse(left.createdAt) ||
        compareCanonicalUtf8(left.txid, right.txid),
    ),
    listings: activeListings,
    mints: sortedMints,
    pendingSupply:
      workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
        ? formatWorkSubatoms(pendingSupplyUnits)
        : mintSupplyTotals.pendingSupply,
    sales: sortedSales,
    stats: {
      ...(state.stats ?? {}),
      confirmedMints: mintSupplyTotals.confirmedMints,
      confirmedTransfers: sortedTransfers.filter((transfer) => transfer.confirmed)
        .length,
      confirmedTokens: (Array.isArray(state.tokens) ? state.tokens : []).filter(
        (token) => token.confirmed,
      ).length,
      holders: holders.length,
      invalidEvents: invalidEvents.filter((event) => event.confirmed).length,
      pendingMints: mintSupplyTotals.pendingMints,
      pendingTransfers: sortedTransfers.filter((transfer) => !transfer.confirmed)
        .length,
      pendingTokens: (Array.isArray(state.tokens) ? state.tokens : []).filter(
        (token) => !token.confirmed,
      ).length,
    },
    tokens,
    transfers: sortedTransfers,
  };
}

function workTokenListingsNeedingSealRecovery(state) {
  const listings = new Map();
  for (const listing of [
    ...(Array.isArray(state?.listings) ? state.listings : []),
    ...(Array.isArray(state?.closedListings) ? state.closedListings : []),
  ]) {
    const listingId = String(listing?.listingId ?? "").toLowerCase();
    if (
      !/^[0-9a-f]{64}$/u.test(listingId) ||
      listing?.tokenId !== WORK_TOKEN_ID ||
      listing?.registryAddress !== WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS ||
      !isValidBitcoinAddress(
        listing?.sellerAddress,
        state?.network ?? "livenet",
      ) ||
      tokenListingSealRank(listing) >= 2
    ) {
      continue;
    }
    listings.set(listingId, listing);
  }
  return listings;
}

function workTokenStateWithRecoveredListingSeals(state, txs, network) {
  if (network === "livenet") {
    return state;
  }
  const candidates = workTokenListingsNeedingSealRecovery(state);
  if (candidates.size === 0) {
    return state;
  }

  const recoveredById = new Map();
  const currentListingFor = (listingId) =>
    recoveredById.get(listingId) ?? candidates.get(listingId);

  for (const tx of tokenProtocolSortedTransactions(
    (Array.isArray(txs) ? txs : []).filter(Boolean),
  )) {
    const txid = transactionTxid(tx);
    if (!txid) {
      continue;
    }

    const vin = Array.isArray(tx.vin) ? tx.vin : [];
    const vout = Array.isArray(tx.vout) ? tx.vout : [];
    const actorAddress = inputAddresses(vin)[0] ?? "";
    if (!isValidBitcoinAddress(actorAddress, network)) {
      continue;
    }

    let remainingRegistrySats = tokenPaymentAmountBeforeProtocol(
      vout,
      WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
    );
    const confirmed = transactionConfirmed(tx);
    const createdAt = new Date(tokenTransactionTime(tx)).toISOString();

    for (const message of decodedProtocolMessages(vout, TOKEN_PROTOCOL_PREFIX)) {
      const parsed = parseTokenPayload(message, network);
      const listingId = String(parsed?.listingId ?? "").toLowerCase();
      const listing = currentListingFor(listingId);
      const authorization = parsed?.saleAuthorization;
      if (
        parsed?.kind !== "seal" ||
        !listing ||
        listing.sellerAddress !== actorAddress ||
        remainingRegistrySats < TOKEN_MIN_MUTATION_PRICE_SATS ||
        authorization?.tokenId !== WORK_TOKEN_ID ||
        authorization.registryAddress !== WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS ||
        authorization.ticker !== WORK_TOKEN_TICKER ||
        !tokenSaleAuthorizationTermsMatch(
          listing.saleAuthorization,
          authorization,
        ) ||
        authorization.anchorTxid !== listing.listingId ||
        !tokenSaleAuthorizationUsesSaleTicketAnchor(authorization)
      ) {
        continue;
      }

      remainingRegistrySats -= TOKEN_MIN_MUTATION_PRICE_SATS;
      const recoveredListing = tokenListingWithSealFrom(listing, {
        saleAuthorization: authorization,
        sealAt: createdAt,
        sealConfirmed: confirmed,
        sealDataBytes: proofProtocolDataBytesForVout(vout),
        sealTxid: txid,
      });
      if (tokenListingSealRank(recoveredListing) > tokenListingSealRank(listing)) {
        recoveredById.set(listingId, recoveredListing);
      }
    }
  }

  if (recoveredById.size === 0) {
    return state;
  }

  const recoverListing = (listing) => {
    const listingId = String(listing?.listingId ?? "").toLowerCase();
    const recovered = recoveredById.get(listingId);
    return recovered ? mergeTokenListingRecord(listing, recovered) : listing;
  };

  return {
    ...state,
    closedListings: (Array.isArray(state?.closedListings)
      ? state.closedListings
      : []
    ).map(recoverListing),
    indexedAt: new Date().toISOString(),
    listings: (Array.isArray(state?.listings) ? state.listings : []).map(
      recoverListing,
    ),
  };
}

function workTokenStateWithRecoveredListingsFromTransactions(state, txs, network) {
  if (network === "livenet") {
    return state;
  }
  const activeListings = new Map();
  const knownListingIds = new Set();
  for (const listing of Array.isArray(state?.listings) ? state.listings : []) {
    const listingId = String(listing?.listingId ?? "").toLowerCase();
    if (!/^[0-9a-f]{64}$/u.test(listingId)) {
      continue;
    }
    knownListingIds.add(listingId);
    activeListings.set(
      listingId,
      mergeTokenListingRecord(activeListings.get(listingId), listing),
    );
  }
  for (const listing of Array.isArray(state?.closedListings)
    ? state.closedListings
    : []) {
    const listingId = String(listing?.listingId ?? "").toLowerCase();
    if (/^[0-9a-f]{64}$/u.test(listingId)) {
      knownListingIds.add(listingId);
    }
  }

  let changed = false;
  let invalidEvents = Array.isArray(state?.invalidEvents)
    ? [...state.invalidEvents]
    : [];
  for (const tx of tokenProtocolSortedTransactions(
    (Array.isArray(txs) ? txs : []).filter(Boolean),
  )) {
    const txid = transactionTxid(tx);
    if (!txid || knownListingIds.has(txid) || !transactionConfirmed(tx)) {
      continue;
    }

    const vin = Array.isArray(tx.vin) ? tx.vin : [];
    const vout = Array.isArray(tx.vout) ? tx.vout : [];
    const txInputAddresses = inputAddresses(vin);
    let remainingRegistrySats = tokenPaymentAmountBeforeProtocol(
      vout,
      WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
    );
    const createdAt = new Date(tokenTransactionTime(tx)).toISOString();

    for (const message of decodedProtocolMessages(vout, TOKEN_PROTOCOL_PREFIX)) {
      const parsed = parseTokenPayload(message, network);
      const authorization = parsed?.saleAuthorization;
      if (
        parsed?.kind !== "list" ||
        authorization?.tokenId !== WORK_TOKEN_ID ||
        authorization.registryAddress !== WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS ||
        authorization.ticker !== WORK_TOKEN_TICKER ||
        !txInputAddresses.includes(authorization.sellerAddress) ||
        remainingRegistrySats < TOKEN_MIN_MUTATION_PRICE_SATS ||
        !tokenListingAnchorIsPresent(vout, authorization)
      ) {
        continue;
      }

      remainingRegistrySats -= TOKEN_MIN_MUTATION_PRICE_SATS;
      const listedAmount = tokenSaleAuthorizationLedgerAmount(authorization);
      if (listedAmount === null) {
        continue;
      }
      activeListings.set(txid, {
        ...tokenLedgerAmountFields(WORK_TOKEN_ID, listedAmount),
        confirmed: true,
        createdAt,
        dataBytes: proofProtocolDataBytesForVout(vout),
        listingId: txid,
        network,
        priceSats: authorization.priceSats,
        registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
        saleAuthorization: authorization,
        sellerAddress: authorization.sellerAddress,
        ticker: WORK_TOKEN_TICKER,
        tokenId: WORK_TOKEN_ID,
      });
      invalidEvents = invalidEvents.filter((event) => event.txid !== txid);
      knownListingIds.add(txid);
      changed = true;
    }
  }

  if (!changed) {
    return state;
  }

  return {
    ...state,
    indexedAt: new Date().toISOString(),
    invalidEvents,
    listings: [...activeListings.values()].sort(
      (left, right) =>
        Number(right.confirmed) - Number(left.confirmed) ||
        Date.parse(right.createdAt) - Date.parse(left.createdAt) ||
        compareCanonicalUtf8(left.listingId, right.listingId),
    ),
  };
}

async function recentWorkTokenSealRecoveryTransactions(network, maxTxs) {
  const cacheKey = `${network}:${maxTxs}`;
  const cached = WORK_TOKEN_SEAL_RECOVERY_CACHE.get(cacheKey);
  if (cached && Date.now() < cached.expiresAt) {
    return cached.txs;
  }

  let historyTxids = [];
  try {
    historyTxids = await fetchAddressHistoryTxidsFromElectrum(
      WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
      network,
    );
  } catch (error) {
    console.error(
      `WORK listing seal recovery history lookup failed for ${network}: ${errorSummary(error)}`,
    );
    return [];
  }

  const txids = historyTxids.slice(-Math.max(0, maxTxs));
  if (txids.length === 0) {
    return [];
  }

  let failedFetches = 0;
  const txs = await mapWithConcurrency(
    txids,
    TX_FETCH_CONCURRENCY,
    async (txid) => {
      try {
        return await fetchTransactionWithSourceFallback(txid, network);
      } catch {
        failedFetches += 1;
        return null;
      }
    },
  );
  if (failedFetches > 0) {
    console.error(
      `WORK listing seal recovery hydration was partial for ${network}: ${failedFetches} of ${txids.length} transaction lookups failed.`,
    );
  }

  const recoveredTxs = await annotateBlockOrder(
    dedupeTransactions(txs.filter(Boolean)),
    network,
  );
  WORK_TOKEN_SEAL_RECOVERY_CACHE.set(cacheKey, {
    expiresAt: Date.now() + WORK_TOKEN_SEAL_RECOVERY_CACHE_TTL_MS,
    txs: recoveredTxs,
  });
  return recoveredTxs;
}

async function recoverWorkListingSealsFromRecentHistory(state, network, maxTxs) {
  if (
    network !== "livenet" ||
    workTokenListingsNeedingSealRecovery(state).size === 0
  ) {
    return state;
  }

  const txs = await recentWorkTokenSealRecoveryTransactions(network, maxTxs);
  return workTokenStateWithRecoveredListingSeals(state, txs, network);
}

function cacheLiveWorkTokenState(network, state) {
  if (state?.summaryOnly) {
    return;
  }
  const scope = WORK_TOKEN_ID;
  cacheTokenPayload(network, scope, state);
}

async function confirmedTransactionsForTxids(txids, network, maxTxs) {
  const uniqueTxids = [...new Set(txids)]
    .filter((txid) => /^[0-9a-f]{64}$/u.test(txid))
    .slice(0, Math.max(0, maxTxs));
  if (uniqueTxids.length === 0) {
    return [];
  }

  const txs = await mapWithConcurrency(
    uniqueTxids,
    TX_FETCH_CONCURRENCY,
    async (txid) => {
      try {
        const tx =
          (await fetchTransaction(txid, network).catch(() => null)) ??
          (await fetchTransactionWithSourceFallback(txid, network));
        return transactionConfirmed(tx) ? tx : null;
      } catch {
        return null;
      }
    },
  );
  return txs.filter(Boolean);
}

async function quickConfirmedTransactionsForTxids(
  txids,
  network,
  maxTxs,
  timeoutMs = Math.max(5_000, TOKEN_ADDRESS_HINT_LIVE_WAIT_MS),
) {
  const uniqueTxids = [...new Set(txids)]
    .filter((txid) => /^[0-9a-f]{64}$/u.test(txid))
    .slice(0, Math.max(0, maxTxs));
  if (uniqueTxids.length === 0) {
    return [];
  }

  const txs = await mapWithConcurrency(
    uniqueTxids,
    TX_FETCH_CONCURRENCY,
    async (txid) => {
      const normalizeLookupTx = (payload) =>
        payload?.tx && typeof payload.tx === "object" ? payload.tx : payload;
      const hasRawTxBody = (tx) =>
        tx &&
        Array.isArray(tx.vin) &&
        Array.isArray(tx.vout) &&
        tx.vout.length > 0;

      const directTx = normalizeLookupTx(
        await payloadWithFallbackAfterMs(
          fetchTransaction(txid, network).catch(() => null),
          null,
          timeoutMs,
        ),
      );
      if (transactionConfirmed(directTx) && hasRawTxBody(directTx)) {
        return directTx;
      }

      const fallbackTx = normalizeLookupTx(
        await payloadWithFallbackAfterMs(
          fetchTransactionWithSourceFallback(txid, network).catch(() => null),
          null,
          timeoutMs,
        ),
      );
      const tx = transactionConfirmed(fallbackTx) ? fallbackTx : directTx;
      return transactionConfirmed(tx) && hasRawTxBody(tx) ? tx : null;
    },
  );
  return txs.filter(Boolean);
}

async function recentUnknownHistoryTransactions(
  address,
  network,
  knownTxids,
  maxTxs,
) {
  let historyTxids = [];
  try {
    historyTxids = await fetchAddressHistoryTxidsFromElectrum(address, network);
  } catch (error) {
    console.error(
      `WORK live registry history lookup failed for ${network}: ${errorSummary(error)}`,
    );
    return [];
  }

  const unknownTxids = historyTxids
    .filter((txid) => !knownTxids.has(txid))
    .slice(-Math.max(0, maxTxs));
  if (unknownTxids.length === 0) {
    return [];
  }

  let failedFetches = 0;
  const txs = await mapWithConcurrency(
    unknownTxids,
    TX_FETCH_CONCURRENCY,
    async (txid) => {
      try {
        return await fetchTransactionWithSourceFallback(txid, network);
      } catch {
        failedFetches += 1;
        return null;
      }
    },
  );

  if (failedFetches > 0) {
    console.error(
      `WORK live history hydration was partial for ${network}: ${failedFetches} of ${unknownTxids.length} transaction lookups failed.`,
    );
  }

  return annotateBlockOrder(dedupeTransactions(txs.filter(Boolean)), network);
}

async function replayLiveWorkTokenState(network, state, reason) {
  try {
    const replayedState = await workTokenPayload(network, state);
    if (!tokenPayloadLooksWorse(replayedState, state)) {
      cacheLiveWorkTokenState(network, replayedState);
      syncWorkTokenLiveSeenTxids(network, replayedState);
      console.log(`Replayed full WORK registry ${reason} for ${network}.`);
      return replayedState;
    }

    const nextMetrics = JSON.stringify(tokenPayloadMetrics(replayedState));
    const previousMetrics = JSON.stringify(tokenPayloadMetrics(state));
    console.error(
      `Rejected WORK ${reason} replay regression for ${network}: ${nextMetrics} < ${previousMetrics}.`,
    );
  } catch (error) {
    console.error(
      `WORK ${reason} replay failed for ${network}: ${errorSummary(error)}`,
    );
  }

  return null;
}

async function liveWorkTokenState(network, cachedWorkTokenState, options = {}) {
  const recoveryAddresses = Array.isArray(options.recoveryAddresses)
    ? options.recoveryAddresses
    : [];
  const recoveryTxids = Array.isArray(options.recoveryTxids)
    ? options.recoveryTxids
    : [];
  let state =
    cachedWorkTokenState && typeof cachedWorkTokenState === "object"
      ? cachedWorkTokenState
      : {
          ...emptyTokenState(),
          indexedAt: new Date().toISOString(),
          network,
          tokens: [
            {
              confirmed: true,
              createdAt: new Date(GROWTH_MODEL_START_MS).toISOString(),
              creationFeeSats: TOKEN_CREATION_PRICE_SATS,
              creatorAddress: "",
              dataBytes: 0,
              maxSupply: WORK_TOKEN_MAX_SUPPLY,
              mintAmount: WORK_TOKEN_MINT_AMOUNT,
              mintPriceSats: WORK_TOKEN_MINT_PRICE_SATS,
              network,
              registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
              ticker: WORK_TOKEN_TICKER,
              tokenId: WORK_TOKEN_ID,
              txid: WORK_TOKEN_ID,
            },
          ],
        };

  if (network !== "livenet") {
    return state;
  }

  const cachedScopedWorkState = await existingTokenPayload(
    network,
    WORK_TOKEN_ID,
  ).catch(() => null);
  if (
    cachedScopedWorkState &&
    cachedScopedWorkState !== state &&
    !tokenPayloadLooksWorse(cachedScopedWorkState, state)
  ) {
    state = cachedScopedWorkState;
  } else {
    const sealMergedState = tokenStateWithMergedListingSeals(
      state,
      cachedScopedWorkState,
    );
    if (sealMergedState !== state) {
      state = sealMergedState;
      cacheLiveWorkTokenState(network, state);
      syncWorkTokenLiveSeenTxids(network, state);
    }
  }

  const counterNormalizedState = workTokenStateWithMintSupplyCounters(state);
  if (counterNormalizedState !== state) {
    state = counterNormalizedState;
    cacheLiveWorkTokenState(network, state);
    syncWorkTokenLiveSeenTxids(network, state);
  }

  if (options.recoverClosedSales !== false) {
    const recoveredSales = await recoverWorkSalesFromClosedListings(
      state,
      network,
    );
    if (recoveredSales.length > 0) {
      state = workTokenStateWithRecoveredSales(state, recoveredSales);
      cacheLiveWorkTokenState(network, state);
      syncWorkTokenLiveSeenTxids(network, state);
      console.log(
        `Recovered ${recoveredSales.length} WORK closed sale(s) for ${network}.`,
      );
    }
  }

  const maxDeltaTxs = Math.max(1, WORK_TOKEN_LIVE_DELTA_MAX_TXS);
  const maxPendingConfirmationTxs = Math.max(
    0,
    Math.min(maxDeltaTxs, WORK_TOKEN_LIVE_PENDING_CONFIRMATION_MAX_TXS),
  );
  const maxRecentTxs = Math.max(
    1,
    Math.min(maxDeltaTxs, WORK_TOKEN_LIVE_RECENT_MAX_TXS),
  );
  const maxHistoryTxs = Math.max(
    1,
    Math.min(maxDeltaTxs, WORK_TOKEN_LIVE_HISTORY_MAX_TXS),
  );
  const hasRecoveryAddresses = recoveryAddresses.length > 0;
  const hasRecoveryTxids = recoveryTxids.length > 0;
  const hasRecoveryInputs = hasRecoveryAddresses || hasRecoveryTxids;
  if (options.recoverClosedSalesOnly === true && !hasRecoveryInputs) {
    return state;
  }
  const maxNonMintTxs = Math.max(
    0,
    hasRecoveryInputs
      ? 0
      : Math.min(maxDeltaTxs, WORK_TOKEN_LIVE_NON_MINT_MAX_TXS),
  );
  const maxNonMintScanTxs = Math.max(
    maxNonMintTxs,
    maxNonMintTxs > 0 ? WORK_TOKEN_LIVE_NON_MINT_SCAN_MAX_TXS : 0,
  );
  const pendingTxids = unconfirmedTokenStateTxids(state);
  const [confirmedPendingTxs, recoveredTxidTxs] = await Promise.all([
    confirmedTransactionsForTxids(
      pendingTxids,
      network,
      maxPendingConfirmationTxs,
    ),
    confirmedTransactionsForTxids(
      recoveryTxids,
      network,
      Math.max(0, recoveryTxids.length),
    ),
  ]);

  const knownTxids = syncWorkTokenLiveSeenTxids(network, state);
  const cachedPendingTokenTxs = cachedPendingTokenTransactionsForRegistry(
    network,
    WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
  );
  const [recentTxs, historyTxs, nonMintHistoryTxs, participantTxs] =
    await Promise.all([
      fetchRecentUnknownAddressTransactions(
        WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
        network,
        knownTxids,
        maxRecentTxs,
      ).catch((error) => {
        console.error(
          `WORK live recent page lookup failed for ${network}: ${errorSummary(error)}`,
        );
        return [];
      }),
      recentUnknownHistoryTransactions(
        WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
        network,
        knownTxids,
        maxHistoryTxs,
      ),
      recentUnknownWorkTokenNonMintTransactions(
        network,
        knownTxids,
        maxNonMintTxs,
        maxNonMintScanTxs,
      ),
      recentUnknownWorkTokenParticipantTransactions(
        state,
        network,
        knownTxids,
        hasRecoveryAddresses
          ? WORK_TOKEN_LIVE_RECOVERY_TXS_PER_ADDRESS
          : WORK_TOKEN_LIVE_PARTICIPANT_TXS_PER_ADDRESS,
        recoveryAddresses,
      ),
    ]);

  const txs = dedupeTransactions([
    ...confirmedPendingTxs,
    ...recoveredTxidTxs,
    ...recentTxs.filter(Boolean),
    ...historyTxs,
    ...nonMintHistoryTxs,
    ...participantTxs,
    ...cachedPendingTokenTxs,
    ...explicitWorkTokenCloseRecoveryTxs(network),
  ]);
  let closeRecoveredFromDeltaState =
    workTokenStateWithRecoveredListingClosesFromTransactions(
      state,
      txs,
      network,
    );
  if (closeRecoveredFromDeltaState !== state) {
    closeRecoveredFromDeltaState =
      await workTokenStateWithRecoveredListingCloseSales(
        closeRecoveredFromDeltaState,
        network,
      );
    state = closeRecoveredFromDeltaState;
    cacheLiveWorkTokenState(network, state);
    syncWorkTokenLiveSeenTxids(network, state);
    console.log(`Recovered WORK listing close(s) from live delta for ${network}.`);
  }
  const listingRecoveredFromDeltaState =
    workTokenStateWithRecoveredListingsFromTransactions(state, txs, network);
  if (listingRecoveredFromDeltaState !== state) {
    state = listingRecoveredFromDeltaState;
    cacheLiveWorkTokenState(network, state);
    syncWorkTokenLiveSeenTxids(network, state);
    console.log(`Recovered WORK listing(s) from live delta for ${network}.`);
  }
  const sealRecoveredFromDeltaState = workTokenStateWithRecoveredListingSeals(
    state,
    txs,
    network,
  );
  if (sealRecoveredFromDeltaState !== state) {
    state = sealRecoveredFromDeltaState;
    cacheLiveWorkTokenState(network, state);
    syncWorkTokenLiveSeenTxids(network, state);
    console.log(`Recovered WORK listing seal(s) from live delta for ${network}.`);
  }
  const sealRecoveredFromHistoryState =
    await recoverWorkListingSealsFromRecentHistory(state, network, maxHistoryTxs);
  if (sealRecoveredFromHistoryState !== state) {
    state = sealRecoveredFromHistoryState;
    cacheLiveWorkTokenState(network, state);
    syncWorkTokenLiveSeenTxids(network, state);
    console.log(
      `Recovered WORK listing seal(s) from recent registry history for ${network}.`,
    );
  }
  const confirmedDeltaTxids = new Set(
    txs.filter(transactionConfirmed).map(transactionTxid).filter(Boolean),
  );
  if (workTokenDeltaHasNonMintActions(txs, network)) {
    const deltaState = workTokenStateWithDeltaTransactions(state, txs, network);
    const preservedDeltaState = tokenStateWithPreservedListingRecords(
      deltaState,
      state,
    );
    const sealMergedDeltaState = tokenStateWithMergedListingSeals(
      preservedDeltaState,
      state,
    );
    if (
      sealMergedDeltaState !== state &&
      !tokenPayloadLooksWorse(sealMergedDeltaState, state)
    ) {
      cacheLiveWorkTokenState(network, sealMergedDeltaState);
      syncWorkTokenLiveSeenTxids(network, sealMergedDeltaState);
      console.log(
        `Applied incremental WORK non-mint delta for ${network}.`,
      );
      return sealMergedDeltaState;
    }

    const replayedState = await replayLiveWorkTokenState(
      network,
      state,
      "after non-mint delta",
    );
    if (replayedState) {
      return replayedState;
    }

    return state;
  }

  const workTokenDefinition = (Array.isArray(state?.tokens)
    ? state.tokens
    : []
  ).find((token) => isWorkTokenId(token?.tokenId));
  const workAmountStorageModel =
    state?.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL ||
    state?.precisionModel === WORK_PRECISION_V2_MODEL ||
    workRecordUsesSubatoms(workTokenDefinition)
      ? WORK_SUBATOM_PROJECTION_MODEL
      : WORK_ATOMIC_PROJECTION_MODEL;
  for (const tx of txs) {
    const txid = transactionTxid(tx);
    if (txid) {
      knownTxids.add(txid);
    }
  }

  const existingMints = workMintRowsWithinPendingCap(
    (Array.isArray(state.mints) ? state.mints : []).filter(
      (mint) =>
        !(
          mint?.confirmed === false &&
          confirmedDeltaTxids.has(String(mint.txid ?? "").toLowerCase())
        ),
    ),
  );
  const acceptedMintCountsByTxid = new Map();
  for (const mint of existingMints) {
    const txid = String(mint.txid ?? "").toLowerCase();
    if (/^[0-9a-f]{64}$/u.test(txid)) {
      acceptedMintCountsByTxid.set(
        txid,
        (acceptedMintCountsByTxid.get(txid) ?? 0) + 1,
      );
    }
  }
  let confirmedSupply = existingMints
    .filter((mint) => mint.confirmed)
    .reduce((total, mint) => total + Number(mint.amount || 0), 0);
  const seenMintCountsByTxid = new Map();
  const newMints = [];

  for (const tx of tokenProtocolSortedTransactions(txs.filter(Boolean))) {
    for (const mint of confirmedWorkMintEventsFromTransaction(tx, network)) {
      const seenCountInTx = seenMintCountsByTxid.get(mint.txid) ?? 0;
      seenMintCountsByTxid.set(mint.txid, seenCountInTx + 1);
      const acceptedCount = acceptedMintCountsByTxid.get(mint.txid) ?? 0;
      if (
        seenCountInTx < acceptedCount ||
        confirmedSupply + mint.amount > WORK_TOKEN_MAX_SUPPLY
      ) {
        continue;
      }

      acceptedMintCountsByTxid.set(mint.txid, acceptedCount + 1);
      confirmedSupply += mint.amount;
      const mintAmount = tokenLedgerAmountFromRecord(
        WORK_TOKEN_ID,
        mint,
        { workAmountStorageModel },
      );
      if (mintAmount === null) {
        throw new Error(
          "Live WORK mint recovery encountered an inexact amount.",
        );
      }
      newMints.push({
        ...mint,
        ...tokenLedgerAmountFields(WORK_TOKEN_ID, mintAmount, {
          workAmountStorageModel,
        }),
      });
    }
  }

  if (newMints.length === 0) {
    return state;
  }

  const holders = new Map(
    (Array.isArray(state.holders) ? state.holders : [])
      .map((holder) => [
        holder?.address,
        tokenLedgerAmountFromRecord(
          WORK_TOKEN_ID,
          {
            amount: holder?.balance,
            amountAtoms: holder?.balanceAtoms,
            amountStorageModel: holder?.amountStorageModel,
            amountSubatoms: holder?.balanceSubatoms,
            precisionModel: holder?.precisionModel,
          },
          { allowZero: true, workAmountStorageModel },
        ),
      ])
      .filter(([address, balance]) => address && balance !== null && balance > 0n),
  );
  for (const mint of newMints) {
    const mintAmount = tokenLedgerAmountFromRecord(
      WORK_TOKEN_ID,
      mint,
      { workAmountStorageModel },
    );
    if (mintAmount === null) {
      continue;
    }
    holders.set(
      mint.minterAddress,
      (holders.get(mint.minterAddress) ?? 0n) + mintAmount,
    );
  }

  const mergedMints = sortWorkMintsForDisplay(
    workMintRowsWithinPendingCap([...existingMints, ...newMints]),
  );
  const mintSupplyTotals = workMintSupplyTotals(mergedMints);
  const exactMintSupply = (confirmed) =>
    mergedMints
      .filter((mint) => mint.confirmed === confirmed)
      .reduce((total, mint) => {
        const amount = tokenLedgerAmountFromRecord(
          WORK_TOKEN_ID,
          mint,
          { workAmountStorageModel },
        );
        if (amount === null) {
          throw new Error(
            "Live WORK mint recovery produced an inexact supply.",
          );
        }
        return total + amount;
      }, 0n);
  const confirmedSupplyUnits = exactMintSupply(true);
  const pendingSupplyUnits = exactMintSupply(false);
  const precisionState =
    workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
      ? (() => {
          const {
            confirmedSupplyAtoms: _confirmedSupplyAtoms,
            pendingSupplyAtoms: _pendingSupplyAtoms,
            ...current
          } = state;
          return current;
        })()
      : state;
  const nextState = {
    ...precisionState,
    amountStorageModel: workAmountStorageModel,
    confirmedSupply:
      workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
        ? formatWorkSubatoms(confirmedSupplyUnits)
        : mintSupplyTotals.confirmedSupply,
    ...(workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
      ? {
          confirmedSupplySubatoms: confirmedSupplyUnits.toString(),
          decimals: WORK_SUBATOM_DECIMALS,
          pendingSupplySubatoms: pendingSupplyUnits.toString(),
          precisionModel: WORK_PRECISION_V2_MODEL,
          unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
        }
      : {
          confirmedSupplyAtoms: workSupplyAtomsText(
            mintSupplyTotals.confirmedSupply,
          ),
          decimals: WORK_DECIMALS,
          pendingSupplyAtoms: workSupplyAtomsText(
            mintSupplyTotals.pendingSupply,
          ),
          unitScale: WORK_UNIT_SCALE_TEXT,
        }),
    holders: [...holders.entries()]
      .map(([address, balance]) => ({
        address,
        ledgerBalance: balance,
        ...tokenLedgerBalanceFields(WORK_TOKEN_ID, balance, {
          workAmountStorageModel,
        }),
      }))
      .sort(
        (left, right) =>
          (right.ledgerBalance > left.ledgerBalance
            ? 1
            : right.ledgerBalance < left.ledgerBalance
              ? -1
              : 0) ||
          compareCanonicalUtf8(left.address, right.address),
      )
      .map(({ ledgerBalance, ...holder }) => holder),
    indexedAt: new Date().toISOString(),
    mints: mergedMints,
    pendingSupply:
      workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
        ? formatWorkSubatoms(pendingSupplyUnits)
        : mintSupplyTotals.pendingSupply,
    stats: {
      ...(state.stats ?? {}),
      confirmedMints: mintSupplyTotals.confirmedMints,
      holders: holders.size,
      pendingMints: mintSupplyTotals.pendingMints,
    },
    tokens: (Array.isArray(state?.tokens) ? state.tokens : []).map(
      (token) =>
        isWorkTokenId(token?.tokenId)
          ? canonicalWorkTokenDefinition(
              token?.network ?? network,
              workAmountStorageModel,
            )
          : token,
    ),
  };
  cacheLiveWorkTokenState(network, nextState);
  syncWorkTokenLiveSeenTxids(network, nextState);
  console.log(
    `Applied ${newMints.length} live WORK registry mint(s) for ${network}.`,
  );
  return nextState;
}

async function liveWorkTokenStateWithFallbackAfterMs(
  network,
  cachedWorkTokenState,
  timeoutMs = WORK_TOKEN_LIVE_WAIT_MS,
  options = {},
) {
  const fallback = workTokenStateWithMintSupplyCounters(cachedWorkTokenState);
  return payloadWithFallbackAfterMs(
    liveWorkTokenState(network, fallback, options),
    fallback,
    timeoutMs,
  );
}

function liveWorkReadWaitMs(options = {}) {
  if (Number.isFinite(options.liveWorkWaitMs)) {
    return options.liveWorkWaitMs;
  }

  return (Array.isArray(options.recoveryAddresses) &&
    options.recoveryAddresses.length > 0) ||
    (Array.isArray(options.recoveryTxids) && options.recoveryTxids.length > 0)
    ? WORK_TOKEN_LIVE_RECOVERY_WAIT_MS
    : WORK_TOKEN_LIVE_WAIT_MS;
}

function canonicalWorkMarketV2TokenSummary(payload, network) {
  if (network !== "livenet") {
    return payload;
  }
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return null;
  }
  const indexedThroughBlock = proofIndexPayloadIndexedThroughBlock(payload);
  if (!Number.isSafeInteger(indexedThroughBlock) || indexedThroughBlock < 1) {
    return null;
  }
  if (indexedThroughBlock < WORK_MARKET_V2_ACTIVATION_HEIGHT) {
    return payload;
  }
  if (
    payload.workMarketV2Activation?.activationHeight !==
      WORK_MARKET_V2_ACTIVATION_HEIGHT ||
    payload.workMarketV2Activation?.declarationHeight !==
      WORK_MARKET_V2_DECLARATION_HEIGHT ||
    payload.workMarketV2Activation?.declarationTxid !==
      WORK_MARKET_V2_DECLARATION_TXID
  ) {
    return null;
  }
  // The activation marker is written only after the full canonical state has
  // been cut over. Summary payloads intentionally carry a bounded listing
  // preview, so transforming them again would replace exact aggregate counts
  // with the preview count.
  return payload;
}

async function tokenPayloadReadResult(payload, network, fresh, options = {}) {
  const cutoverPayload = applyWorkMarketV2CutoverToTokenState(payload);
  const listingReconciledPayload =
    options.reconcileListingStatus === false
      ? cutoverPayload
      : await tokenStateWithReconciledListingSeals(cutoverPayload, network);
  const reconciledPayload = fresh
    ? await tokenStateWithLivePendingTransactionCheck(
        listingReconciledPayload,
        network,
      )
    : tokenStateWithoutDroppedPendingTransactions(
        listingReconciledPayload,
        network,
      );
  const currentListingPayload = tokenPayloadWithCurrentWorkActiveListingPolicy(
    reconciledPayload,
    network,
  );
  const spendablePayload = options.reconcileSpendable === false
    ? currentListingPayload
    : await tokenPayloadWithSpendableListings(currentListingPayload, network);
  return tokenPayloadWithCurrentWorkActiveListingPolicy(spendablePayload, network);
}

function tokenPayloadFreshnessRank(payload) {
  const tokens = Array.isArray(payload?.tokens) ? payload.tokens : [];
  const mints = Array.isArray(payload?.mints) ? payload.mints : [];
  const transfers = Array.isArray(payload?.transfers) ? payload.transfers : [];
  const listings = Array.isArray(payload?.listings) ? payload.listings : [];
  const sales = Array.isArray(payload?.sales) ? payload.sales : [];
  const holders = Array.isArray(payload?.holders) ? payload.holders : [];
  const stats = payload?.stats && typeof payload.stats === "object"
    ? payload.stats
    : {};
  const bondTokenId =
    tokens.length === 1 && isBondTokenId(tokens[0]?.tokenId)
      ? tokens[0].tokenId
      : "";
  const indexedAtMs = Date.parse(
    String(
      payload?.indexedAt ??
        payload?.ledgerGeneratedAt ??
        payload?.generatedAt ??
        "",
    ),
  );
  return {
    confirmedMints: Math.max(
      numericValue(stats.confirmedMints),
      mints.filter((mint) => mint?.confirmed).length,
    ),
    bondTokenId,
    confirmedSupply: bondTokenId
      ? canonicalIntegerText(payload?.confirmedSupply, { allowZero: true }) ||
        "0"
      : numericValue(payload?.confirmedSupply),
    confirmedTokens: Math.max(
      numericValue(stats.confirmedTokens),
      tokens.filter((token) => token?.confirmed).length,
    ),
    holders: holders.length,
    indexedAtMs: Number.isFinite(indexedAtMs) ? indexedAtMs : 0,
    listings: listings.length,
    mints: mints.length,
    pendingSupply: bondTokenId
      ? canonicalIntegerText(payload?.pendingSupply, { allowZero: true }) || "0"
      : numericValue(payload?.pendingSupply),
    sales: sales.length,
    tokens: tokens.length,
    transfers: transfers.length,
  };
}

function tokenFreshnessSupplyCompare(leftRank, rightRank, field) {
  if (
    leftRank?.bondTokenId &&
    leftRank.bondTokenId === rightRank?.bondTokenId
  ) {
    const left = integerBigInt(leftRank[field], { allowZero: true }) ?? 0n;
    const right = integerBigInt(rightRank[field], { allowZero: true }) ?? 0n;
    return left > right ? 1 : left < right ? -1 : 0;
  }
  return numericValue(leftRank?.[field]) - numericValue(rightRank?.[field]);
}

function maxTokenPayloadSupply(...payloads) {
  const scopedBondTokenIds = payloads
    .map((payload) => tokenPayloadFreshnessRank(payload).bondTokenId)
    .filter(Boolean);
  if (
    scopedBondTokenIds.length === payloads.length &&
    new Set(scopedBondTokenIds).size === 1
  ) {
    return payloads.reduce(
      (maximum, payload) =>
        maxIntegerTexts(maximum, payload?.confirmedSupply ?? "0"),
      "0",
    );
  }
  return Math.max(...payloads.map((payload) => numericValue(payload?.confirmedSupply)));
}

function tokenPayloadShouldReplaceForFreshness(candidate, current) {
  if (!candidate) {
    return false;
  }
  if (!current) {
    return true;
  }

  const candidateRank = tokenPayloadFreshnessRank(candidate);
  const currentRank = tokenPayloadFreshnessRank(current);
  if (candidateRank.tokens > 0 && currentRank.tokens === 0) {
    return true;
  }
  if (candidateRank.tokens > currentRank.tokens) {
    return true;
  }

  const nonRegressing =
    candidateRank.confirmedTokens >= currentRank.confirmedTokens &&
    candidateRank.confirmedMints >= currentRank.confirmedMints &&
    tokenFreshnessSupplyCompare(
      candidateRank,
      currentRank,
      "confirmedSupply",
    ) >= 0;
  if (!nonRegressing) {
    return false;
  }

  return (
    candidateRank.indexedAtMs > currentRank.indexedAtMs ||
    candidateRank.mints > currentRank.mints ||
    candidateRank.transfers > currentRank.transfers ||
    candidateRank.listings > currentRank.listings ||
    candidateRank.sales > currentRank.sales ||
    candidateRank.holders > currentRank.holders ||
    tokenFreshnessSupplyCompare(candidateRank, currentRank, "pendingSupply") > 0
  );
}

function ledgerPayloadForFreshnessCompare(ledger, scope) {
  if (!ledger) {
    return null;
  }
  return attachLedgerMetadata(
    {
      ...ledgerTokenStateForScope(ledger, scope),
      indexedAt: ledger.generatedAt,
    },
    ledger,
  );
}

function tokenPayloadRegressesCanonical(candidate, canonical) {
  if (!candidate || !canonical) {
    return false;
  }
  const candidateRank = tokenPayloadFreshnessRank(candidate);
  const canonicalRank = tokenPayloadFreshnessRank(canonical);
  return (
    tokenFreshnessSupplyCompare(
      candidateRank,
      canonicalRank,
      "confirmedSupply",
    ) < 0 ||
    candidateRank.confirmedMints < canonicalRank.confirmedMints ||
    candidateRank.confirmedTokens < canonicalRank.confirmedTokens ||
    (tokenFreshnessSupplyCompare(
      canonicalRank,
      { ...canonicalRank, confirmedSupply: canonicalRank.bondTokenId ? "0" : 0 },
      "confirmedSupply",
    ) > 0 &&
      canonicalRank.holders > 0 &&
      candidateRank.holders === 0)
  );
}

function tokenMintHistoryItemKey(item) {
  const blockHeight =
    item?.blockHeight !== undefined &&
    item?.blockHeight !== null &&
    item?.blockHeight !== "" &&
    Number.isSafeInteger(Number(item.blockHeight)) &&
    Number(item.blockHeight) >= 1
      ? Number(item.blockHeight)
      : null;
  const legacyPositionExempt =
    item?.relic === true || item?.canonicalSynthetic === true;
  if (
    item?.confirmed === true &&
    blockHeight === null &&
    !legacyPositionExempt
  ) {
    throw new Error("Confirmed token mint position is incomplete.");
  }
  if (
    item?.confirmed === true &&
    blockHeight !== null &&
    blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT
  ) {
    const position = canonicalTokenReplayPosition(item);
    return [
      String(item?.network ?? "").trim().toLowerCase(),
      String(item?.txid ?? "").trim().toLowerCase(),
      "v5",
      position.blockHeight,
      position.blockIndex,
      position.protocolVout,
      position.recordOrdinal,
    ].join(":");
  }
  const identity = [
    item?._powEventIndex,
    item?.eventKeyVout,
    item?.protocolVout,
    item?.eventId,
  ]
    .filter((value) => value !== undefined && value !== null && value !== "")
    .map((value) => Number(value))
    .find((value) => Number.isSafeInteger(value) && value >= 0);
  const fallback = [
    isBondTokenId(item?.tokenId)
      ? canonicalIntegerText(item?.amount, { allowZero: true })
      : numericValue(item?.amount),
    String(item?.minterAddress ?? "").trim().toLowerCase(),
  ].join(":");
  return [
    String(item?.tokenId ?? "").trim().toLowerCase(),
    String(item?.txid ?? "").trim().toLowerCase(),
    identity === undefined ? `mint:${fallback}` : `event:${identity}`,
  ].join(":");
}

function tokenTransferHistoryItemKey(item) {
  const blockHeight =
    item?.blockHeight !== undefined &&
    item?.blockHeight !== null &&
    item?.blockHeight !== "" &&
    Number.isSafeInteger(Number(item.blockHeight)) &&
    Number(item.blockHeight) >= 1
      ? Number(item.blockHeight)
      : null;
  const legacyPositionExempt =
    item?.relic === true || item?.canonicalSynthetic === true;
  if (
    item?.confirmed === true &&
    blockHeight === null &&
    !legacyPositionExempt
  ) {
    throw new Error("Confirmed token transfer position is incomplete.");
  }
  if (
    item?.confirmed === true &&
    blockHeight !== null &&
    blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT
  ) {
    const position = canonicalTokenReplayPosition(item);
    return [
      String(item?.network ?? "").trim().toLowerCase(),
      String(item?.txid ?? "").trim().toLowerCase(),
      "v5",
      position.blockHeight,
      position.blockIndex,
      position.protocolVout,
      position.recordOrdinal,
    ].join(":");
  }
  const identity = [
    item?.protocolVout,
    item?.eventKeyVout,
    item?._powEventIndex,
    item?.eventId,
  ]
    .filter((value) => value !== undefined && value !== null && value !== "")
    .map((value) => Number(value))
    .find((value) => Number.isSafeInteger(value) && value >= 0);
  const fallback = [
    isBondTokenId(item?.tokenId)
      ? canonicalIntegerText(item?.amount, { allowZero: true })
      : numericValue(item?.amount),
    String(item?.senderAddress ?? "").trim().toLowerCase(),
    String(item?.recipientAddress ?? "").trim().toLowerCase(),
  ].join(":");
  return [
    String(item?.tokenId ?? "").trim().toLowerCase(),
    String(item?.txid ?? "").trim().toLowerCase(),
    identity === undefined ? `movement:${fallback}` : `event:${identity}`,
  ].join(":");
}

function mergeCanonicalHistoryItems(
  canonicalItems,
  payloadItems,
  keyForItem,
  mergeItem = (current, incoming) => current ?? incoming,
) {
  return mergeTokenStateItemsByKey(
    canonicalItems,
    payloadItems,
    keyForItem,
    mergeItem,
  );
}

function tokenPayloadWithCanonicalHistoryFloor(canonicalPayload, payload) {
  if (!canonicalPayload || !payload) {
    return payload;
  }

  const candidateRank = tokenPayloadFreshnessRank(payload);
  const canonicalRank = tokenPayloadFreshnessRank(canonicalPayload);
  const confirmedSupplyRegressed =
    tokenFreshnessSupplyCompare(
      candidateRank,
      canonicalRank,
      "confirmedSupply",
    ) < 0;
  const confirmedMintsRegressed =
    candidateRank.confirmedMints < canonicalRank.confirmedMints;
  const confirmedTokensRegressed =
    candidateRank.confirmedTokens < canonicalRank.confirmedTokens;
  const holdersRegressed =
    canonicalRank.holders > 0 && candidateRank.holders < canonicalRank.holders;
  const salesRegressed = candidateRank.sales < canonicalRank.sales;
  const transfersRegressed =
    candidateRank.transfers < canonicalRank.transfers;
  const listingsRegressed =
    candidateRank.listings < canonicalRank.listings;

  if (
    !confirmedSupplyRegressed &&
    !confirmedMintsRegressed &&
    !confirmedTokensRegressed &&
    !holdersRegressed &&
    !salesRegressed &&
    !transfersRegressed &&
    !listingsRegressed
  ) {
    return tokenStateWithPendingStats({
      ...payload,
      closedListings: mergeCanonicalHistoryItems(
        canonicalPayload.closedListings,
        payload.closedListings,
        tokenClosedListingItemKey,
        mergeTokenListingRecord,
      ),
      listings: mergeCanonicalHistoryItems(
        canonicalPayload.listings,
        payload.listings,
        tokenListingItemKey,
        mergeTokenListingRecord,
      ),
      mints: mergeCanonicalHistoryItems(
        canonicalPayload.mints,
        payload.mints,
        tokenMintHistoryItemKey,
        mergeCreditNetworkValueRecord,
      ),
      sales: mergeCanonicalHistoryItems(
        canonicalPayload.sales,
        payload.sales,
        tokenSaleItemKey,
        mergeTokenSaleRecord,
      ),
      source: mergedSourceLabel(canonicalPayload?.source, payload?.source),
      transfers: mergeCanonicalHistoryItems(
        canonicalPayload.transfers,
        payload.transfers,
        tokenTransferHistoryItemKey,
        mergeTokenTransferRecord,
      ),
    });
  }

  const next = {
    ...payload,
    confirmedSupply: maxTokenPayloadSupply(payload, canonicalPayload),
    indexedAt: newerIso(canonicalPayload?.indexedAt, payload?.indexedAt),
    indexedThroughBlock: Math.max(
      numericValue(canonicalPayload?.indexedThroughBlock),
      numericValue(payload?.indexedThroughBlock),
    ),
    pendingSupply:
      candidateRank.bondTokenId &&
      candidateRank.bondTokenId === canonicalRank.bondTokenId
        ? maxIntegerTexts(
            payload?.pendingSupply ?? "0",
            canonicalPayload?.pendingSupply ?? "0",
          )
        : Math.max(
            numericValue(payload?.pendingSupply),
            numericValue(canonicalPayload?.pendingSupply),
          ),
    source: mergedSourceLabel(canonicalPayload?.source, payload?.source),
    stats: {
      ...(payload?.stats ?? {}),
      confirmedMints: Math.max(
        candidateRank.confirmedMints,
        canonicalRank.confirmedMints,
      ),
      confirmedTokens: Math.max(
        candidateRank.confirmedTokens,
        canonicalRank.confirmedTokens,
      ),
      holders: Math.max(candidateRank.holders, canonicalRank.holders),
    },
  };

  if (
    confirmedTokensRegressed ||
    confirmedMintsRegressed ||
    confirmedSupplyRegressed ||
    holdersRegressed
  ) {
    next.tokens = Array.isArray(canonicalPayload.tokens)
      ? canonicalPayload.tokens
      : payload.tokens;
  }
  if (confirmedMintsRegressed || confirmedSupplyRegressed || holdersRegressed) {
    next.mints = mergeCanonicalHistoryItems(
      canonicalPayload.mints,
      payload.mints,
      tokenMintHistoryItemKey,
      mergeCreditNetworkValueRecord,
    );
    next.holders = Array.isArray(canonicalPayload.holders)
      ? canonicalPayload.holders
      : payload.holders;
  }
  if (transfersRegressed || holdersRegressed) {
    next.transfers = mergeCanonicalHistoryItems(
      canonicalPayload.transfers,
      payload.transfers,
      tokenTransferHistoryItemKey,
      mergeTokenTransferRecord,
    );
  }
  if (salesRegressed || holdersRegressed) {
    next.sales = mergeCanonicalHistoryItems(
      canonicalPayload.sales,
      payload.sales,
      tokenSaleItemKey,
      mergeTokenSaleRecord,
    );
  }
  if (listingsRegressed) {
    next.listings = mergeCanonicalHistoryItems(
      canonicalPayload.listings,
      payload.listings,
      tokenListingItemKey,
      mergeTokenListingRecord,
    );
    next.closedListings = mergeCanonicalHistoryItems(
      canonicalPayload.closedListings,
      payload.closedListings,
      tokenClosedListingItemKey,
      mergeTokenListingRecord,
    );
  }

  return tokenStateWithPendingStats(next);
}

function mergeTokenPayloadWithCanonicalFloor(canonicalPayload, payload, scope) {
  if (!canonicalPayload) {
    return payload;
  }
  if (!payload) {
    return canonicalPayload;
  }

  const normalizedScope = normalizeTokenScope(scope);
  let merged = canonicalPayload;
  if (normalizedScope) {
    const canonicalScopedPayload = scopedTokenPayloadFromState(
      canonicalPayload,
      normalizedScope,
    );
    const payloadScopedState = scopedTokenPayloadFromState(
      payload,
      normalizedScope,
    );
    const scopedState = tokenPayloadWithCanonicalHistoryFloor(
      canonicalScopedPayload,
      payloadScopedState,
    );
    merged = tokenStateWithScopedTokenOverride(
      canonicalPayload,
      scopedState,
      normalizedScope,
    );
    merged = scopedTokenPayloadFromState(merged, normalizedScope);
  } else {
    const tokenIds = new Set(
      (Array.isArray(payload.tokens) ? payload.tokens : [])
        .map((token) => String(token?.tokenId ?? "").trim())
        .filter(Boolean),
    );
    for (const tokenId of tokenIds) {
      const canonicalScopedPayload = scopedTokenPayloadFromState(
        canonicalPayload,
        tokenId,
      );
      const payloadScopedState = scopedTokenPayloadFromState(payload, tokenId);
      const scopedState = tokenPayloadWithCanonicalHistoryFloor(
        canonicalScopedPayload,
        payloadScopedState,
      );
      merged = tokenStateWithScopedTokenOverride(
        merged,
        scopedState,
        tokenId,
      );
    }
  }

  return applyWorkMarketV2CutoverToTokenState(tokenStateWithPendingStats({
    ...merged,
    confirmedSupply: maxTokenPayloadSupply(
      merged,
      canonicalPayload,
      payload,
    ),
    indexedAt: newerIso(canonicalPayload?.indexedAt, payload?.indexedAt),
    indexedThroughBlock: Math.max(
      numericValue(canonicalPayload?.indexedThroughBlock),
      numericValue(payload?.indexedThroughBlock),
    ),
    source: mergedSourceLabel(canonicalPayload?.source, payload?.source),
    ...((payload?.workMarketV4Activation ??
      canonicalPayload?.workMarketV4Activation ??
      merged?.workMarketV4Activation)
      ? {
          workMarketV4Activation:
            payload?.workMarketV4Activation ??
            canonicalPayload?.workMarketV4Activation ??
            merged?.workMarketV4Activation,
        }
      : {}),
  }));
}

function tokenStateWithAuthoritativeCurrentListings(tokenState, currentState) {
  if (
    !tokenState ||
    !currentState ||
    !Array.isArray(currentState.tokens) ||
    !Array.isArray(currentState.listings) ||
    !Array.isArray(currentState.closedListings)
  ) {
    return tokenState;
  }

  const currentTokenIds = new Set(
    currentState.tokens
      .map((token) => normalizeTokenScope(token?.tokenId))
      .filter(Boolean),
  );
  if (currentTokenIds.size === 0) {
    return tokenState;
  }

  const existingListingsByKey = new Map(
    (Array.isArray(tokenState.listings) ? tokenState.listings : []).map(
      (listing) => [tokenListingItemKey(listing), listing],
    ),
  );
  const authoritativeListings = currentState.listings
    .filter((listing) =>
      currentTokenIds.has(normalizeTokenScope(listing?.tokenId)),
    )
    .map((listing) =>
      mergeTokenListingRecord(
        existingListingsByKey.get(tokenListingItemKey(listing)),
        listing,
      ),
    );
  const unscopedListings = (
    Array.isArray(tokenState.listings) ? tokenState.listings : []
  ).filter(
    (listing) =>
      !currentTokenIds.has(normalizeTokenScope(listing?.tokenId)),
  );
  const closedListings = mergeTokenStateItemsByKey(
    tokenState.closedListings,
    currentState.closedListings,
    tokenClosedListingItemKey,
    mergeTokenListingRecord,
  );

  return applyWorkMarketV2CutoverToTokenState(tokenStateWithPendingStats({
    ...tokenState,
    closedListings,
    listings: [...unscopedListings, ...authoritativeListings],
    ...((currentState.workMarketV4Activation ??
      tokenState.workMarketV4Activation)
      ? {
          workMarketV4Activation:
            currentState.workMarketV4Activation ??
            tokenState.workMarketV4Activation,
        }
      : {}),
  }));
}

async function tokenPayloadWithCanonicalLedgerFloor(
  network,
  payload,
  scope,
  label,
  timeoutMs = SUMMARY_PROOF_INDEX_READ_WAIT_MS,
) {
  if (network !== "livenet" || !payload) {
    return payload;
  }

  let ledger = await existingCurrentCanonicalLedgerPayloadWithinMs(
    network,
    `token canonical floor:${label}:${scope || "all"}`,
    Math.min(2_500, Math.max(1_000, timeoutMs)),
  );
  if (!ledger) {
    ledger = await existingCanonicalLedgerPayload(network).catch(() => null);
    if (ledger) {
      refreshCanonicalLedgerPayloadInBackground(network, true);
    }
  }
  const canonicalPayload = ledgerPayloadForFreshnessCompare(ledger, scope);
  if (!canonicalPayload) {
    return payload;
  }

  if (tokenPayloadRegressesCanonical(payload, canonicalPayload)) {
    console.error(
      `Merged ${label} token read with canonical ledger floor for ${scope || "all"} because the direct token read regressed confirmed history.`,
    );
  }
  return mergeTokenPayloadWithCanonicalFloor(canonicalPayload, payload, scope);
}

function canonicalWorkTransferValueSummaryMatchesPayload(
  summary,
  payload,
  gate,
) {
  if (
    !summary ||
    !canonicalWorkTransferValueProjectionIsUsable(
      summary.workTransferValueProjection,
    ) ||
    !String(summary.snapshotId ?? "").trim() ||
    gate?.ready !== true ||
    gate?.summarySnapshotOk !== true
  ) {
    return false;
  }
  const summaryHeight = proofIndexPayloadIndexedThroughBlock(summary);
  const payloadHeight = proofIndexPayloadIndexedThroughBlock(payload);
  const summaryHash = String(summary.indexedThroughBlockHash ?? "")
    .trim()
    .toLowerCase();
  const summarySnapshotId = String(summary.snapshotId ?? "").trim();
  const gateSnapshotId = String(
    gate?.summarySnapshot?.snapshotId ?? "",
  ).trim();
  const canonicalHash = String(gate?.canonicalHash ?? "")
    .trim()
    .toLowerCase();
  const storedHash = String(gate?.storedHash ?? "")
    .trim()
    .toLowerCase();
  return (
    Number.isSafeInteger(summaryHeight) &&
    summaryHeight > 0 &&
    summaryHeight === payloadHeight &&
    summaryHeight === Number(gate?.indexedThroughBlock) &&
    summaryHeight === Number(gate?.tipHeight) &&
    gateSnapshotId.length > 0 &&
    summarySnapshotId === gateSnapshotId &&
    /^[0-9a-f]{64}$/u.test(summaryHash) &&
    summaryHash === canonicalHash &&
    summaryHash === storedHash
  );
}

async function currentCanonicalWorkTransferValueSummary(
  network,
  payload,
  label,
  timeoutMs = SUMMARY_PROOF_INDEX_READ_WAIT_MS,
) {
  if (network !== "livenet" || !payload) {
    return null;
  }
  const [summary, gate] = await Promise.all([
    payloadWithFallbackAfterMs(
      currentProofIndexSummarySnapshotPayload(
        network,
        "workSummary",
        `${label} WORK transfer-value projection`,
        { allowWithoutCanonicalLedger: true },
      ),
      null,
      timeoutMs,
    ).catch((error) => {
      console.error(
        `Canonical WORK transfer-value projection failed for ${label}: ${errorSummary(error)}`,
      );
      return null;
    }),
    payloadWithFallbackAfterMs(
      canonicalPublicReadGate(network),
      null,
      Math.min(timeoutMs, CANONICAL_PUBLIC_READ_GATE_TIMEOUT_MS),
    ).catch(() => null),
  ]);
  return canonicalWorkTransferValueSummaryMatchesPayload(
    summary,
    payload,
    gate,
  )
    ? summary
    : null;
}

async function tokenPayloadWithCanonicalWorkTransferValues(
  network,
  payload,
  fallbackPayload,
  scope,
  label,
  timeoutMs = SUMMARY_PROOF_INDEX_READ_WAIT_MS,
) {
  const normalizedScope = normalizeTokenScope(scope);
  if (
    network !== "livenet" ||
    !payload ||
    (normalizedScope && normalizedScope !== WORK_TOKEN_ID)
  ) {
    return payload;
  }
  const summary = await currentCanonicalWorkTransferValueSummary(
    network,
    payload,
    label,
    timeoutMs,
  );
  if (!summary) {
    return normalizedScope === WORK_TOKEN_ID ? fallbackPayload : payload;
  }
  const projected = tokenStateWithCanonicalWorkTransferValues(
    payload,
    summary.workTransferValueProjection,
  );
  return {
    ...projected,
    indexedThroughBlockHash: summary.indexedThroughBlockHash,
    snapshotId: summary.snapshotId,
    source: mergedSourceLabel(
      projected?.source,
      "canonical-work-transfer-value-projection",
    ),
    workTransferValueProjection: {
      indexedAt: summary.indexedAt,
      indexedThroughBlock: proofIndexPayloadIndexedThroughBlock(summary),
      indexedThroughBlockHash: summary.indexedThroughBlockHash,
      itemCount: summary.workTransferValueProjection.items.length,
      model: summary.workTransferValueProjection.model,
      snapshotId: summary.snapshotId,
    },
  };
}

async function currentProofIndexTokenPayloadForRead(
  network,
  tokenScope = "",
  label = "token-state",
  timeoutMs = 5_000,
) {
  const scope = normalizeTokenScope(tokenScope);
  if (
    network !== "livenet" ||
    !proofIndexReadFeatureEnabled("token-state,token-default,token")
  ) {
    return null;
  }

  const params = new URLSearchParams();
  if (scope) {
    params.set("asset", scope);
  }
  if (!proofIndexTokenReadEligibility(scope, params).eligible) {
    return null;
  }

  const payload = await payloadWithFallbackAfterMs(
    proofIndexTokenPayload(network, scope, params).catch((error) => {
      console.error(
        `Proof index ${label} read failed for ${scope || "all"}: ${errorSummary(error)}`,
      );
      return null;
    }),
    null,
    timeoutMs,
  );
  if (
    payload &&
    tokenPayloadCanPopulateFullStateCache(payload, network) &&
    !rejectEmptyMainnetTokenPayload(network, payload, scope, label) &&
    (await payloadWithFallbackAfterMs(
      proofIndexPayloadCoversConfirmedTip(
        payload,
        network,
        `${label}:${scope || "all"}`,
      ),
      false,
      Math.min(2_500, Math.max(1_000, timeoutMs)),
    ))
  ) {
    const canonicalFloored = await tokenPayloadWithCanonicalLedgerFloor(
      network,
      payload,
      scope,
      label,
      timeoutMs,
    );
    return tokenPayloadWithCanonicalWorkTransferValues(
      network,
      canonicalFloored,
      payload,
      scope,
      label,
      timeoutMs,
    );
  }
  return null;
}

async function currentCachedTokenPayloadForRead(
  network,
  tokenScope = "",
  label = "token-cache",
) {
  const scope = normalizeTokenScope(tokenScope);
  const payload = await cachedTokenPayloadSnapshotNoRefresh(network, scope).catch(
    (error) => {
      console.error(
        `Cached ${label} read failed for ${scope || "all"}: ${errorSummary(error)}`,
      );
      return null;
    },
  );
  if (
    payload &&
    !rejectEmptyMainnetTokenPayload(network, payload, scope, label) &&
    (await payloadWithFallbackAfterMs(
      proofIndexPayloadCoversConfirmedTip(
        payload,
        network,
        `${label}:${scope || "all"}`,
      ),
      false,
      2_500,
    ))
  ) {
    return tokenPayloadWithCanonicalLedgerFloor(network, payload, scope, label);
  }
  return null;
}

async function currentMemoryTokenPayloadForRead(
  network,
  tokenScope = "",
  label = "token-memory-cache",
) {
  const scope = normalizeTokenScope(tokenScope);
  const payload = RESPONSE_CACHE.get(`payload:token:${network}:${scope}`)?.payload;
  if (
    payload &&
    tokenPayloadCanPopulateFullStateCache(payload, network) &&
    !rejectEmptyMainnetTokenPayload(network, payload, scope, label) &&
    (await payloadWithFallbackAfterMs(
      proofIndexPayloadCoversConfirmedTip(
        payload,
        network,
        `${label}:${scope || "all"}`,
      ),
      false,
      2_500,
    ))
  ) {
    return tokenPayloadWithCanonicalLedgerFloor(network, payload, scope, label);
  }
  return null;
}

async function currentExactTipTokenPayloadForRead(
  network,
  tokenScope = "",
  label = "token-exact-tip-cache",
  canonicalGate = null,
) {
  const scope = normalizeTokenScope(tokenScope);
  const cacheKey = `token:${network}:${scope}`;
  const cached = EXACT_TIP_TOKEN_CACHE.get(cacheKey);
  const payload = cached?.payload;
  if (
    !payload ||
    !tokenPayloadCanPopulateFullStateCache(payload, network) ||
    Number(cached?.validatedUntil) < Date.now() ||
    rejectEmptyMainnetTokenPayload(network, payload, scope, label)
  ) {
    EXACT_TIP_TOKEN_CACHE.delete(cacheKey);
    return null;
  }
  const indexedThroughBlock = proofIndexPayloadIndexedThroughBlock(payload);
  if (canonicalGate && canonicalGate.ok === true) {
    if (!tokenPayloadMatchesCanonicalGate(payload, canonicalGate)) {
      EXACT_TIP_TOKEN_CACHE.delete(cacheKey);
      return null;
    }
    return retainedExactTipTokenPayloadForRead(payload, canonicalGate, cached);
  }
  const tipHeight = await payloadWithFallbackAfterMs(
    healthNodeTipHeight(),
    null,
    2_500,
  );
  if (!Number.isSafeInteger(tipHeight) || tipHeight <= 0) {
    return null;
  }
  if (
    Number.isSafeInteger(indexedThroughBlock) &&
    indexedThroughBlock > 0 &&
    indexedThroughBlock === tipHeight
  ) {
    return payload;
  }
  EXACT_TIP_TOKEN_CACHE.delete(cacheKey);
  return null;
}

function tokenPayloadMatchesCanonicalGate(payload, canonicalGate) {
  if (!canonicalGate || canonicalGate.ok !== true || canonicalGate.atTip !== true) {
    return false;
  }
  return tokenPayloadMatchesCanonicalIndexedGate(payload, canonicalGate);
}

function tokenPayloadMatchesCanonicalIndexedGate(payload, canonicalGate) {
  if (!canonicalGate || canonicalGate.ok !== true) {
    return false;
  }
  const indexedThroughBlock = proofIndexPayloadIndexedThroughBlock(payload);
  const indexedThroughBlockHash = payloadIndexedThroughBlockHash(payload);
  const canonicalHash = String(canonicalGate.canonicalHash ?? "")
    .trim()
    .toLowerCase();
  return (
    Number(canonicalGate.indexedThroughBlock) === indexedThroughBlock &&
    /^[0-9a-f]{64}$/u.test(indexedThroughBlockHash) &&
    canonicalHash === indexedThroughBlockHash
  );
}

function tokenPayloadMatchesCanonicalFreshGate(
  payload,
  canonicalGate,
  { allowLastGood = false } = {},
) {
  return (
    tokenPayloadMatchesCanonicalGate(payload, canonicalGate) ||
    (
      allowLastGood === true &&
      canonicalGateCanUseBoundedLastGood(canonicalGate) &&
      tokenPayloadMatchesCanonicalIndexedGate(payload, canonicalGate)
    )
  );
}

async function currentCanonicalTokenSummaryPayloadForFreshRead(
  network,
  tokenScope,
  canonicalGate,
) {
  const scope = normalizeTokenScope(tokenScope);
  if (
    network !== "livenet" ||
    (scope !== WORK_TOKEN_ID && canonicalGate?.ready === true)
  ) {
    return null;
  }
  const payload = await storedCanonicalTokenSummaryPayload(network, scope).catch(
    (error) => {
      console.error(
        `Canonical token summary fresh read failed for ${scope || "all"}: ${errorSummary(error)}`,
      );
      return null;
    },
  );
  if (
    !payload ||
    !tokenPayloadMatchesCanonicalIndexedGate(payload, canonicalGate) ||
    rejectEmptyMainnetTokenPayload(
      network,
      payload,
      scope,
      "canonical-token-summary-fresh",
    )
  ) {
    return null;
  }
  const checkpointHash = String(canonicalGate?.canonicalHash ?? "")
    .trim()
    .toLowerCase();
  const checkpointHeight = Number(canonicalGate?.indexedThroughBlock);
  const pendingReady =
    canonicalGate?.atTip === true && canonicalGate?.workerOk === true;
  return {
    ...payload,
    confirmedRead: {
      checkpointHash,
      checkpointHeight,
      mode: canonicalGate?.atTip === true ? "exact-tip" : "bounded-last-good",
      ready: true,
    },
    pendingProjection: {
      ready: pendingReady,
      status: pendingReady ? "current" : "unverified-last-observed",
    },
  };
}

async function cachedTokenPayloadFallbackForRead(
  network,
  tokenScope = "",
  label = "token-cache-fallback",
) {
  const scope = normalizeTokenScope(tokenScope);
  let payload = await cachedTokenPayloadSnapshotNoRefresh(network, scope).catch(
    (error) => {
      console.error(
        `Fallback ${label} read failed for ${scope || "all"}: ${errorSummary(error)}`,
      );
      return null;
    },
  );
  if (
    payload &&
    !rejectEmptyMainnetTokenPayload(network, payload, scope, label)
  ) {
    refreshTokenPayloadCacheInBackground(network, scope);
    return tokenPayloadWithCanonicalLedgerFloor(network, payload, scope, label);
  }

  if (network === "livenet") {
    let ledger = await existingCurrentCanonicalLedgerPayloadWithinMs(
      network,
      `token fallback ledger:${label}:${scope || "all"}`,
      SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    );
    if (!ledger) {
      ledger = await existingCanonicalLedgerPayload(network).catch((error) => {
        console.error(
          `Fallback ${label} canonical ledger read failed for ${scope || "all"}: ${errorSummary(error)}`,
        );
        return null;
      });
    }
    payload = ledgerPayloadForFreshnessCompare(ledger, scope);
    if (
      payload &&
      !rejectEmptyMainnetTokenPayload(network, payload, scope, `${label}-ledger`)
    ) {
      refreshTokenPayloadCacheInBackground(network, scope);
      refreshCanonicalLedgerPayloadInBackground(network, true);
      return tokenPayloadWithCanonicalLedgerFloor(
        network,
        payload,
        scope,
        `${label}-ledger`,
      );
    }
  }

  return null;
}

async function indexedTokenPayloadFreshnessFloor(network, scope, options = {}) {
  if (
    network !== "livenet" ||
    (Array.isArray(options.recoveryAddresses) &&
      options.recoveryAddresses.length > 0) ||
    (Array.isArray(options.recoveryTxids) &&
      options.recoveryTxids.length > 0) ||
    !proofIndexReadFeatureEnabled("token-state,token-default,token")
  ) {
    return null;
  }

  const params = new URLSearchParams();
  if (scope) {
    params.set("asset", scope);
  }
  const payload = await proofIndexTokenPayload(network, scope, params).catch(
    (error) => {
      console.error(
        `Proof index token-state fresh floor failed for ${scope || "all"}: ${errorSummary(error)}`,
      );
      return null;
    },
  );
  if (
    payload &&
    tokenPayloadCanPopulateFullStateCache(payload, network) &&
    !rejectEmptyMainnetTokenPayload(
      network,
      payload,
      scope,
      `token-state fresh-floor:${scope || "all"}`,
    ) &&
    (await proofIndexPayloadCoversConfirmedTip(
      payload,
      network,
        `token-state fresh-floor:${scope || "all"}`,
    ))
  ) {
    return tokenPayloadWithCanonicalLedgerFloor(
      network,
      payload,
      scope,
      `token-state fresh-floor:${scope || "all"}`,
      options.timeoutMs ?? SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    );
  }
  return null;
}

async function tokenPayloadForRead(
  network,
  tokenScope = "",
  fresh = false,
  options = {},
) {
  const scope = normalizeTokenScope(tokenScope);
  const useLedgerSnapshot = options.useLedgerSnapshot !== false;
  const hasRecoveryAddresses =
    Array.isArray(options.recoveryAddresses) &&
    options.recoveryAddresses.length > 0;
  const hasRecoveryTxids =
    Array.isArray(options.recoveryTxids) && options.recoveryTxids.length > 0;
  const indexedFreshFloor = fresh && scope
    ? await indexedTokenPayloadFreshnessFloor(network, scope, options)
    : null;
  if (
    fresh &&
    scope &&
    scope !== WORK_TOKEN_ID &&
    options.preferScopedRefresh !== false
  ) {
    const fallback = await existingTokenPayload(network, scope);
    const scopedRefreshWaitMs = Number.isFinite(options.scopedRefreshWaitMs)
      ? options.scopedRefreshWaitMs
      : BOND_TOKEN_IDS.has(scope)
        ? Math.max(WORK_TOKEN_CANONICAL_FRESH_WAIT_MS, TOKEN_SCOPED_FRESH_WAIT_MS)
        : TOKEN_SCOPED_FRESH_WAIT_MS;
    const freshScopedPayload = await payloadWithFallbackAfterMs(
      refreshTokenPayload(network, scope),
      null,
      scopedRefreshWaitMs,
    );
    if (
      freshScopedPayload &&
      tokenPayloadCanPopulateFullStateCache(freshScopedPayload, network)
    ) {
      if (
        await proofIndexPayloadCoversConfirmedTip(
          freshScopedPayload,
          network,
          `scoped-token:${scope}`,
        )
      ) {
        const flooredScopedPayload =
          await tokenPayloadWithCanonicalLedgerFloor(
            network,
            freshScopedPayload,
            scope,
            `scoped-token:${scope}`,
            scopedRefreshWaitMs,
          );
        return tokenPayloadReadResult(
          flooredScopedPayload,
          network,
          fresh,
          options,
        );
      }
    }
    if (
      fallback &&
      tokenPayloadCanPopulateFullStateCache(fallback, network) &&
      !BOND_TOKEN_IDS.has(scope) &&
      (await proofIndexPayloadCoversConfirmedTip(
        fallback,
        network,
        `scoped-token-fallback:${scope}`,
      ))
    ) {
      const flooredFallback = await tokenPayloadWithCanonicalLedgerFloor(
        network,
        fallback,
        scope,
        `scoped-token-fallback:${scope}`,
      );
      return tokenPayloadReadResult(flooredFallback, network, fresh, options);
    }
  }
  if (network === "livenet" && useLedgerSnapshot) {
    let ledger = null;
    let cachedLedger = null;
    try {
      const shouldFreshenLedger =
        fresh &&
        !(
          scope === WORK_TOKEN_ID &&
          (hasRecoveryAddresses ||
            hasRecoveryTxids ||
            options.recoverWorkSalesOnly === true)
        );
      cachedLedger = shouldFreshenLedger
        ? await existingCanonicalLedgerPayload(network)
        : null;
      const ledgerPromise = shouldFreshenLedger
        ? summaryCanonicalLedgerPayload(network, true)
        : existingCanonicalLedgerPayload(network);
      ledger =
        shouldFreshenLedger && (indexedFreshFloor || cachedLedger)
          ? await payloadWithFallbackAfterMs(
              ledgerPromise,
              cachedLedger,
              Number.isFinite(options.ledgerFreshWaitMs)
                ? options.ledgerFreshWaitMs
                : WORK_FLOOR_FRESH_WAIT_MS,
            )
          : await ledgerPromise;
      if (
        shouldFreshenLedger &&
        cachedLedger &&
        ledger &&
        ledger !== cachedLedger
      ) {
        const cachedPayload = ledgerPayloadForFreshnessCompare(
          cachedLedger,
          scope,
        );
        const freshPayload = ledgerPayloadForFreshnessCompare(ledger, scope);
        if (tokenPayloadShouldReplaceForFreshness(cachedPayload, freshPayload)) {
          ledger = cachedLedger;
        }
      }
    } catch (error) {
      console.error(
        `Canonical token payload failed for ${network}:${scope}: ${errorSummary(error)}`,
      );
    }
    if (ledger) {
      if (
        fresh &&
        !(await proofIndexPayloadCoversConfirmedTip(
          ledger,
          network,
          `canonical-token:${scope || "all"}`,
        ))
      ) {
        ledger = await currentLedgerPayloadOrNull(
          cachedLedger,
          network,
          `canonical-token-fallback:${scope || "all"}`,
        );
      }
    }
    if (ledger) {
      let payload = attachLedgerMetadata(
        {
          ...ledgerTokenStateForScope(ledger, scope),
          indexedAt: ledger.generatedAt,
        },
        ledger,
      );
    if (scope === WORK_TOKEN_ID) {
      const liveOptions = {
        recoverClosedSales: options.recoverWorkSales !== false,
          recoverClosedSalesOnly: options.recoverWorkSalesOnly === true,
          recoveryAddresses: options.recoveryAddresses,
          recoveryTxids: options.recoveryTxids,
        };
        payload = await liveWorkTokenStateWithFallbackAfterMs(
          network,
          payload,
          liveWorkReadWaitMs(options),
          liveOptions,
        );
      }
      if (
        indexedFreshFloor &&
        tokenPayloadShouldReplaceForFreshness(indexedFreshFloor, payload)
      ) {
        payload = indexedFreshFloor;
      }
      return tokenPayloadReadResult(payload, network, fresh, options);
    }
    if (indexedFreshFloor) {
      return tokenPayloadReadResult(indexedFreshFloor, network, fresh, options);
    }
  }

  let payload = fresh
    ? await freshTokenPayloadOrSnapshot(network, scope, options)
    : await fastTokenPayloadSnapshot(network, scope, options);
  if (
    indexedFreshFloor &&
    tokenPayloadShouldReplaceForFreshness(indexedFreshFloor, payload)
  ) {
    payload = indexedFreshFloor;
  }
  if (scope === WORK_TOKEN_ID) {
    const liveOptions = {
      recoverClosedSales: options.recoverWorkSales !== false,
      recoverClosedSalesOnly: options.recoverWorkSalesOnly === true,
      recoveryAddresses: options.recoveryAddresses,
      recoveryTxids: options.recoveryTxids,
    };
    payload = await liveWorkTokenStateWithFallbackAfterMs(
      network,
      payload,
      liveWorkReadWaitMs(options),
      liveOptions,
    );
  }
  if (network === "livenet") {
    payload = await tokenPayloadWithCanonicalLedgerFloor(
      network,
      payload,
      scope,
      `token-payload:${scope || "all"}`,
    );
  }
  if (
    !hasRecoveryAddresses &&
    !hasRecoveryTxids &&
    rejectEmptyMainnetTokenPayload(
      network,
      payload,
      scope,
      `token-payload:${scope || "all"}`,
    )
  ) {
    throw freshDataUnavailableError(
      `Current token payload is unavailable for ${scope || "all"}.`,
    );
  }
  return tokenPayloadReadResult(payload, network, fresh, options);
}

async function storedCanonicalTokenSummaryPayload(network, tokenScope = "") {
  if (network !== "livenet") {
    return null;
  }
  const scope = normalizeTokenScope(tokenScope);
  const parentKey =
    scope === WORK_TOKEN_ID
      ? "workSummary"
      : scope === POWB_TOKEN_ID
        ? "infinitySummary"
        : scope === INCB_TOKEN_ID
          ? "inceptionSummary"
          : scope
            ? ""
            : "tokenSummary";
  if (parentKey) {
    const stored = await proofIndexSnapshotPayload(network, parentKey).catch(
      (error) => {
        console.error(
          `Proof index canonical token summary read failed for ${scope || "all"}: ${errorSummary(error)}`,
        );
        return null;
      },
    );
    const rawPayload = scope ? stored?.token : stored;
    const payload =
      !scope || scope === WORK_TOKEN_ID
        ? canonicalWorkMarketV2TokenSummary(rawPayload, network)
        : rawPayload;
    if (
      payload &&
      typeof payload === "object" &&
      !Array.isArray(payload) &&
      payloadSnapshotId(payload) &&
      payloadIndexedThroughBlockHash(payload)
    ) {
      const summaryPayload = scope === WORK_TOKEN_ID
        ? tokenPayloadWithCurrentWorkActiveListingPolicy(payload, network, {
            forceScopedWorkListingCounts: true,
          })
        : payload;
      return {
        ...summaryPayload,
        ...(stored?.consistency ? { consistency: stored.consistency } : {}),
      };
    }
  }

  if (!scope || !proofIndexReadFeatureEnabled("token-state,token-default,token")) {
    return null;
  }
  const params = new URLSearchParams({ asset: scope });
  if (!proofIndexTokenReadEligibility(scope, params).eligible) {
    return null;
  }
  const [binding, indexedPayload] = await Promise.all([
    proofIndexCanonicalSummaryLedgerPayload(network).catch(() => null),
    payloadWithFallbackAfterMs(
      proofIndexTokenPayload(network, scope, params).catch(() => null),
      null,
      SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    ),
  ]);
  const indexedThroughBlock = proofIndexPayloadIndexedThroughBlock(binding);
  const indexedThroughBlockHash = payloadIndexedThroughBlockHash(binding);
  if (
    !binding ||
    !indexedPayload ||
    indexedThroughBlock <= 0 ||
    proofIndexPayloadIndexedThroughBlock(indexedPayload) !== indexedThroughBlock ||
    !indexedThroughBlockHash
  ) {
    return null;
  }
  return attachLedgerMetadata(
    compactTokenSummaryPayload(indexedPayload, scope),
    {
      ...binding,
      indexedThroughBlockHash,
      metrics: {
        ...(binding.metrics ?? {}),
        indexedThroughBlock,
      },
    },
  );
}

async function tokenSummaryPayload(
  network,
  tokenScope = "",
  fresh = false,
  options = {},
) {
  const scope = normalizeTokenScope(tokenScope);
  const indexAddress = tokenIndexAddressForNetwork(network);
  if (!indexAddress) {
    return {
      ...emptyTokenState(),
      creationPriceSats: TOKEN_CREATION_PRICE_SATS,
      indexedAt: new Date().toISOString(),
      indexAddress: "",
      indexId: TOKEN_INDEX_ID,
      indexTxid: TOKEN_INDEX_TXID,
      minMutationPriceSats: TOKEN_MIN_MUTATION_PRICE_SATS,
      network,
      stats: {
        confirmedMints: 0,
        confirmedTransfers: 0,
        confirmedTokens: 0,
        holders: 0,
        pendingMints: 0,
        pendingTransfers: 0,
        pendingTokens: 0,
        registries: 0,
        transactions: 0,
      },
      workDefaults: canonicalWorkDefaults(),
    };
  }

  const summaryRecoveryAddresses = Array.isArray(options.recoveryAddresses)
    ? options.recoveryAddresses
    : [];
  if (
    network === "livenet" &&
    summaryRecoveryAddresses.length === 0
  ) {
    const storedSummary = await storedCanonicalTokenSummaryPayload(
      network,
      scope,
    );
    if (storedSummary) {
      return storedSummary;
    }
  }

  if (
    network === "livenet" &&
    !fresh &&
    summaryRecoveryAddresses.length === 0 &&
    proofIndexReadFeatureEnabled("token-state,token-default,token") &&
    proofIndexTokenReadEligibility(scope, new URLSearchParams()).eligible
  ) {
    const indexedPayload = await currentProofIndexTokenPayloadForRead(
      network,
      scope,
      "token-summary",
      10_000,
    );
    if (indexedPayload) {
      return compactTokenSummaryPayload(indexedPayload, scope);
    }
    const cachedPayload = await currentCachedTokenPayloadForRead(
      network,
      scope,
      "token-summary-cache",
    );
    if (cachedPayload) {
      refreshTokenPayloadCacheInBackground(network, scope);
      return compactTokenSummaryPayload(cachedPayload, scope);
    }
  }

  if (
    network === "livenet" &&
    summaryRecoveryAddresses.length === 0 &&
    scope !== WORK_TOKEN_ID
  ) {
    const ledger = await existingCurrentCanonicalLedgerPayloadWithinMs(
      network,
      `token-summary canonical ledger:${scope || "all"}`,
      SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    );
    if (ledger) {
      return compactTokenSummaryPayload(
        ledgerPayloadForFreshnessCompare(ledger, scope),
        scope,
      );
    }
  }

  let payload = await tokenPayloadForRead(network, scope, fresh, {
    reconcileListingStatus: false,
    recoveryAddresses: summaryRecoveryAddresses,
    liveWorkWaitMs:
      scope === WORK_TOKEN_ID &&
      summaryRecoveryAddresses.length > 0
        ? TOKEN_ADDRESS_HINT_LIVE_WAIT_MS
        : scope === WORK_TOKEN_ID && !fresh
          ? WORK_TOKEN_LIVE_WAIT_MS
          : undefined,
    recoverWorkSales: true,
    reconcileSpendable: false,
  });
  if (network === "livenet" && !scope) {
    const workPayload = await tokenPayloadForRead(network, WORK_TOKEN_ID, false, {
      reconcileListingStatus: false,
      recoveryAddresses: summaryRecoveryAddresses,
      liveWorkWaitMs: WORK_TOKEN_LIVE_WAIT_MS,
      recoverWorkSales: true,
    }).catch((error) => {
      console.error(
        `WORK summary overlay failed for ${network}: ${errorSummary(error)}`,
      );
      return null;
    });
    if (workPayload) {
      payload = tokenStateWithScopedTokenOverride(
        payload,
        workPayload,
        WORK_TOKEN_ID,
      );
    }
  }
  if (network === "livenet" && scope === WORK_TOKEN_ID) {
    const closeTxs = await payloadWithFallbackAfterMs(
      recentWorkTokenMarketCloseTransactions(
        network,
        WORK_TOKEN_LIVE_CLOSE_MAX_TXS,
        WORK_TOKEN_LIVE_CLOSE_SCAN_MAX_TXS,
      ),
      [],
      WORK_TOKEN_SUMMARY_CLOSE_WAIT_MS,
    );
    const workPayload = scopedTokenPayloadFromState(payload, WORK_TOKEN_ID);
    let closedWorkPayload =
      workTokenStateWithRecoveredListingClosesFromTransactions(
        workPayload,
        closeTxs,
        network,
      );
    closedWorkPayload = await workTokenStateWithRecoveredListingCloseSales(
      closedWorkPayload,
      network,
    );
    payload =
      scope === WORK_TOKEN_ID
        ? closedWorkPayload
        : tokenStateWithScopedTokenOverride(
            payload,
            closedWorkPayload,
            WORK_TOKEN_ID,
          );
  }
  if (
    network === "livenet" &&
    (scope === WORK_TOKEN_ID || BOND_TOKEN_IDS.has(scope))
  ) {
    payload = await tokenPayloadWithSpendableActiveListings(payload, network);
  }
  return compactTokenSummaryPayload(payload, scope);
}

async function walletScopedTokenSummaryPayload(
  network,
  tokenScope = "",
  recoveryAddresses = [],
  options = {},
) {
  const scope = normalizeTokenScope(tokenScope);
  const requireCurrent =
    options.requireCurrent === true && network === "livenet";
  if (scope === WORK_TOKEN_ID || requireCurrent) {
    return compactTokenSummaryPayload(
      await walletScopedTokenPayload(network, scope, recoveryAddresses, {
        allowLastGood: options.allowLastGood === true,
        canonicalReadGate: options.canonicalReadGate,
        requireCurrent,
      }),
      scope,
    );
  }
  const addressScopedPayload = await proofIndexWalletScopedTokenPayloadForRead(
    network,
    scope,
    recoveryAddresses,
    "wallet-scoped-token-summary",
  );
  if (addressScopedPayload) {
    const indexedPayload = await walletScopedPayloadWithIndexedEnrichment(
      addressScopedPayload,
      network,
      scope,
      recoveryAddresses,
    );
    return compactTokenSummaryPayload(indexedPayload, scope);
  }
  let payload = null;
  if (
    network === "livenet" &&
    proofIndexReadFeatureEnabled("token-state,token-default,token")
  ) {
    payload = await currentProofIndexTokenPayloadForRead(
      network,
      scope,
      "wallet-scoped-token-summary",
      5_000,
    );
  }

  if (!payload) {
    payload = await tokenPayloadForRead(network, scope, false, {
      reconcileListingStatus: false,
      reconcileSpendable: false,
      recoveryAddresses,
      liveWorkWaitMs:
        scope === WORK_TOKEN_ID
          ? Math.min(WORK_TOKEN_LIVE_RECOVERY_WAIT_MS, TOKEN_ADDRESS_HINT_LIVE_WAIT_MS)
          : TOKEN_ADDRESS_HINT_LIVE_WAIT_MS,
      recoverWorkSalesOnly: scope === WORK_TOKEN_ID,
    });
  }

  let scopedPayload = tokenPayloadScopedToAddresses(
    payload,
    recoveryAddresses,
    scope,
  );
  if (scope === WORK_TOKEN_ID) {
    scopedPayload = workTokenStateWithRecoveredListingClosesFromTransactions(
      scopedPayload,
      explicitWorkTokenCloseRecoveryTxs(network),
      network,
    );
    scopedPayload = await payloadWithFallbackAfterMs(
      workTokenStateWithRecoveredListingCloseSales(scopedPayload, network),
      scopedPayload,
      WALLET_SCOPED_RECOVERY_WAIT_MS,
    );
  }
  scopedPayload = await tokenPayloadWithIndexedWalletOverlay(
    scopedPayload,
    network,
    scope,
    recoveryAddresses,
    payload?.tokens,
  );
  scopedPayload = await tokenPayloadWithIndexedWalletHolders(
    scopedPayload,
    network,
    scope,
    recoveryAddresses,
  );
  scopedPayload = await tokenPayloadWithWalletActiveListings(
    scopedPayload,
    network,
    scope,
    recoveryAddresses,
  );
  scopedPayload =
    typeof tokenPayloadWithPendingAddressWorkMarketOverlay === "function"
      ? await tokenPayloadWithPendingAddressWorkMarketOverlay(
          scopedPayload,
          network,
          scope,
          recoveryAddresses,
        )
      : scopedPayload;
  if (scope === WORK_TOKEN_ID) {
    scopedPayload = await payloadWithFallbackAfterMs(
      tokenPayloadWithRecoveredWalletWorkTransfers(
        scopedPayload,
        network,
        scope,
        recoveryAddresses,
      ),
      scopedPayload,
      WALLET_SCOPED_RECOVERY_WAIT_MS,
    );
  }
  if (scope === WORK_TOKEN_ID) {
    scopedPayload = await payloadWithFallbackAfterMs(
      workTokenStateWithRecoveredListingCloseSales(scopedPayload, network),
      scopedPayload,
      WALLET_SCOPED_RECOVERY_WAIT_MS,
    );
  }

  return compactTokenSummaryPayload(scopedPayload, scope);
}

function walletScopedTokenCacheKey(
  network,
  scope,
  recoveryAddresses,
  { allowLastGood = false, canonicalReadGate = null, requireCurrent = false } = {},
) {
  const addresses = [...new Set(
    (Array.isArray(recoveryAddresses) ? recoveryAddresses : [])
      .map((address) => String(address ?? "").trim().toLowerCase())
      .filter(Boolean),
  )].sort();
  if (addresses.length === 0) {
    return "";
  }
  const gateKey = requireCurrent
    ? [
        Number(canonicalReadGate?.indexedThroughBlock) || 0,
        String(canonicalReadGate?.canonicalHash ?? "").trim().toLowerCase(),
        Number(canonicalReadGate?.lagBlocks) || 0,
        allowLastGood ? "last-good" : "strict",
      ].join("@")
    : "current";
  return [
    String(network ?? ""),
    normalizeTokenScope(scope),
    addresses.join(","),
    gateKey,
  ].join("|");
}

function cachedWalletScopedTokenPayload(cacheKey, now = Date.now()) {
  if (!cacheKey || WALLET_SCOPED_TOKEN_CACHE_TTL_MS <= 0) {
    return null;
  }
  const cached = WALLET_SCOPED_TOKEN_CACHE.get(cacheKey);
  if (!cached) {
    return null;
  }
  if (cached.expiresAt <= now) {
    WALLET_SCOPED_TOKEN_CACHE.delete(cacheKey);
    return null;
  }
  return cached.payload;
}

function rememberWalletScopedTokenPayload(cacheKey, payload, now = Date.now()) {
  if (
    !cacheKey ||
    WALLET_SCOPED_TOKEN_CACHE_TTL_MS <= 0 ||
    WALLET_SCOPED_TOKEN_CACHE_MAX_ENTRIES <= 0 ||
    !payload
  ) {
    return payload;
  }
  while (WALLET_SCOPED_TOKEN_CACHE.size >= WALLET_SCOPED_TOKEN_CACHE_MAX_ENTRIES) {
    const oldestKey = WALLET_SCOPED_TOKEN_CACHE.keys().next().value;
    if (!oldestKey) {
      break;
    }
    WALLET_SCOPED_TOKEN_CACHE.delete(oldestKey);
  }
  WALLET_SCOPED_TOKEN_CACHE.set(cacheKey, {
    expiresAt: now + WALLET_SCOPED_TOKEN_CACHE_TTL_MS,
    payload,
  });
  return payload;
}

async function walletScopedTokenPayload(
  network,
  tokenScope = "",
  recoveryAddresses = [],
  options = {},
) {
  const scope = normalizeTokenScope(tokenScope);
  const requireCurrent =
    options.requireCurrent === true && network === "livenet";
  const allowLastGood =
    requireCurrent && options.allowLastGood === true;
  const canonicalGate =
    options.canonicalReadGate &&
    typeof options.canonicalReadGate === "object" &&
    !Array.isArray(options.canonicalReadGate)
      ? options.canonicalReadGate
      : null;
  const walletCacheKey = walletScopedTokenCacheKey(
    network,
    scope,
    recoveryAddresses,
    { allowLastGood, canonicalReadGate: canonicalGate, requireCurrent },
  );
  const freshWalletIndexUnavailable = () => {
    const unavailable = freshDataUnavailableError(
      `Fresh wallet credit state is temporarily unavailable for ${scope || "all"}.`,
    );
    unavailable.details = {
      code: "CANONICAL_WALLET_INDEX_UNAVAILABLE",
      requiredSource: "proof-indexer-wallet-token-overlay",
    };
    return unavailable;
  };
  const cachedWalletPayload = cachedWalletScopedTokenPayload(walletCacheKey);
  if (cachedWalletPayload) {
    return cachedWalletPayload;
  }
  const withWalletAuthority = (payload) => {
    const normalizedPayload = walletScopedWorkPayloadWithQ16Supply(
      payload,
      network,
      scope,
    );
    const walletPayload =
      scope === WORK_TOKEN_ID
        ? workQ16PayloadWithoutOrphanPriceAliases(normalizedPayload, scope)
        : normalizedPayload;
    const authoritativeOverlay =
      walletScopedPayloadUsesAuthoritativeOverlay(walletPayload);
    if (requireCurrent && !authoritativeOverlay) {
      throw freshWalletIndexUnavailable();
    }
    if (!requireCurrent && !authoritativeOverlay) {
      return walletPayload;
    }
    const checkpointLastGood =
      allowLastGood &&
      tokenPayloadMatchesCanonicalIndexedGate(walletPayload, canonicalGate) &&
      !tokenPayloadMatchesCanonicalGate(walletPayload, canonicalGate);
    return {
      ...walletPayload,
      authoritativeWallet: true,
      ...(checkpointLastGood
        ? {
            authoritativeWalletCheckpoint: {
              indexedThroughBlock: Number(
                canonicalGate?.indexedThroughBlock,
              ),
              indexedThroughBlockHash: String(
                canonicalGate?.canonicalHash ?? "",
              ).trim().toLowerCase(),
              lagBlocks: Number(canonicalGate?.lagBlocks),
              mode: "last-good",
            },
          }
        : {}),
    };
  };
  const addressScopedPayload = await proofIndexWalletScopedTokenPayloadForRead(
    network,
    scope,
    recoveryAddresses,
    requireCurrent ? "wallet-scoped-token-fresh" : "wallet-scoped-token",
    { allowLastGood, requireCurrent },
  );
  if (addressScopedPayload) {
    const indexedPayload = await walletScopedPayloadWithIndexedEnrichment(
      addressScopedPayload,
      network,
      scope,
      recoveryAddresses,
    );
    const recoveredPayload =
      scope === WORK_TOKEN_ID &&
      !walletScopedPayloadUsesAuthoritativeOverlay(indexedPayload)
      ? await payloadWithFallbackAfterMs(
          tokenPayloadWithRecoveredWalletWorkTransfers(
            indexedPayload,
            network,
            scope,
            recoveryAddresses,
          ),
          indexedPayload,
          WALLET_SCOPED_RECOVERY_WAIT_MS,
        )
      : indexedPayload;
    return rememberWalletScopedTokenPayload(
      walletCacheKey,
      withWalletAuthority(recoveredPayload),
    );
  }
  if (requireCurrent) {
    throw freshWalletIndexUnavailable();
  }
  let payload = null;
  if (
    network === "livenet" &&
    proofIndexReadFeatureEnabled("token-state,token-default,token")
  ) {
    payload = await currentProofIndexTokenPayloadForRead(
      network,
      scope,
      "wallet-scoped-token",
      5_000,
    );
  }

  if (!payload) {
    payload = await tokenPayloadForRead(network, scope, false, {
      reconcileListingStatus: false,
      reconcileSpendable: false,
      recoveryAddresses,
      liveWorkWaitMs:
        scope === WORK_TOKEN_ID
          ? Math.min(WORK_TOKEN_LIVE_RECOVERY_WAIT_MS, TOKEN_ADDRESS_HINT_LIVE_WAIT_MS)
          : TOKEN_ADDRESS_HINT_LIVE_WAIT_MS,
      recoverWorkSalesOnly: scope === WORK_TOKEN_ID,
    });
  }

  let scopedPayload = tokenPayloadScopedToAddresses(
    payload,
    recoveryAddresses,
    scope,
  );
  if (scope === WORK_TOKEN_ID) {
    scopedPayload = workTokenStateWithRecoveredListingClosesFromTransactions(
      scopedPayload,
      explicitWorkTokenCloseRecoveryTxs(network),
      network,
    );
    scopedPayload = await payloadWithFallbackAfterMs(
      workTokenStateWithRecoveredListingCloseSales(scopedPayload, network),
      scopedPayload,
      WALLET_SCOPED_RECOVERY_WAIT_MS,
    );
  }
  scopedPayload = await tokenPayloadWithIndexedWalletOverlay(
    scopedPayload,
    network,
    scope,
    recoveryAddresses,
    payload?.tokens,
  );
  scopedPayload = await tokenPayloadWithIndexedWalletHolders(
    scopedPayload,
    network,
    scope,
    recoveryAddresses,
  );
  scopedPayload = await tokenPayloadWithWalletActiveListings(
    scopedPayload,
    network,
    scope,
    recoveryAddresses,
  );
  scopedPayload =
    typeof tokenPayloadWithPendingAddressWorkMarketOverlay === "function"
      ? await tokenPayloadWithPendingAddressWorkMarketOverlay(
          scopedPayload,
          network,
          scope,
          recoveryAddresses,
        )
      : scopedPayload;

  if (BOND_TOKEN_IDS.has(scope)) {
    const bondPayload = requireCurrent
      ? { ...scopedPayload, authoritativeWallet: true }
      : scopedPayload;
    return rememberWalletScopedTokenPayload(walletCacheKey, bondPayload);
  }

  if (scope === WORK_TOKEN_ID) {
    scopedPayload = await payloadWithFallbackAfterMs(
      tokenPayloadWithRecoveredWalletWorkTransfers(
        scopedPayload,
        network,
        scope,
        recoveryAddresses,
      ),
      scopedPayload,
      WALLET_SCOPED_RECOVERY_WAIT_MS,
    );
  }
  const finalPayload = scope === WORK_TOKEN_ID
    ? payloadWithFallbackAfterMs(
        workTokenStateWithRecoveredListingCloseSales(scopedPayload, network),
        scopedPayload,
        WALLET_SCOPED_RECOVERY_WAIT_MS,
      )
    : scopedPayload;
  const resolvedPayload = await finalPayload;
  return rememberWalletScopedTokenPayload(
    walletCacheKey,
    withWalletAuthority(resolvedPayload),
  );
}

async function indexedWalletClosedListings(network, tokenScope, addresses) {
  if (
    network !== "livenet" ||
    !proofIndexReadFeatureEnabled("event-history,events") ||
    !Array.isArray(addresses) ||
    addresses.length === 0
  ) {
    return [];
  }

  const scope = normalizeTokenScope(tokenScope);
  const closedListings = [];
  for (const address of addresses) {
    const value = String(address ?? "").trim();
    if (!value) {
      continue;
    }

    const searchParams = new URLSearchParams({
      kind: "token-closed-listings",
      limit: "100",
      address: value,
      status: "confirmed",
    });
    const page = await proofIndexEventHistoryPayload(
      network,
      searchParams,
    ).catch((error) => {
      console.error(
        `Proof index wallet closed-listing lookup failed for ${value}: ${errorSummary(error)}`,
      );
      return null;
    });
    for (const item of Array.isArray(page?.items) ? page.items : []) {
      const tokenId = String(item?.tokenId ?? "").trim().toLowerCase();
      const ticker = String(item?.ticker ?? "").trim().toLowerCase();
      const sellerAddress = String(
        item?.sellerAddress ?? item?.actor ?? "",
      ).trim();
      if (
        scope &&
        tokenId !== scope &&
        ticker !== scope
      ) {
        continue;
      }
      if (
        sellerAddress &&
        sellerAddress.toLowerCase() !== value.toLowerCase()
      ) {
        continue;
      }

      closedListings.push({
        ...item,
        closedAt: item.closedAt ?? item.createdAt,
        closedConfirmed: item.closedConfirmed ?? (item.confirmed === true),
        closedTxid: item.closedTxid ?? item.txid,
        sellerAddress: sellerAddress || value,
      });
    }
  }

  return closedListings;
}

async function tokenPayloadWithIndexedWalletClosedListings(
  payload,
  network,
  tokenScope,
  recoveryAddresses,
) {
  const closedListings = await indexedWalletClosedListings(
    network,
    tokenScope,
    recoveryAddresses,
  );
  if (closedListings.length === 0) {
    return payload;
  }

  return tokenStateWithPreservedListingRecords(payload, { closedListings });
}

async function indexedWorkActiveListingTxids(network, addresses, limit = 200) {
  if (
    network !== "livenet" ||
    !proofIndexReadFeatureEnabled("event-history,events") ||
    !Array.isArray(addresses) ||
    addresses.length === 0
  ) {
    return [];
  }

  const txids = new Set();
  const kinds = ["token-listing", "token-listings", "token-listing-sealed"];
  for (const address of addresses) {
    const value = String(address ?? "").trim();
    if (!value) {
      continue;
    }
    for (const kind of kinds) {
      const baseParams = {
        kind,
        limit: String(limit),
        status: "confirmed",
      };
      const pages = [];
      const addressParams = new URLSearchParams({
        ...baseParams,
        address: value,
      });
      const addressPage = await proofIndexEventHistoryPayload(
        network,
        addressParams,
      ).catch((error) => {
        console.error(
          `Proof index active listing candidate lookup failed for ${value}: ${errorSummary(error)}`,
        );
        return null;
      });
      pages.push(addressPage);

      for (const page of pages) {
        for (const item of Array.isArray(page?.items) ? page.items : []) {
          const txid = String(item?.listingId ?? item?.txid ?? "")
            .trim()
            .toLowerCase();
          if (/^[0-9a-f]{64}$/u.test(txid)) {
            txids.add(txid);
          }
        }
      }
    }
  }

  return [...txids].slice(0, Math.max(0, limit));
}

function tokenActiveListingEventKey(item) {
  const listingId = String(item?.listingId ?? item?.txid ?? "")
    .trim()
    .toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(listingId)) {
    return "";
  }
  const tokenScope = normalizeTokenScope(
    item?.tokenId ??
      item?.ticker ??
      item?.saleAuthorization?.tokenId ??
      item?.saleAuthorization?.ticker ??
      "",
  );
  return `${tokenScope || WORK_TOKEN_ID}:${listingId}`;
}

function invalidEventLooksLikeListingAttempt(event) {
  const version = String(
    event?.version ?? event?.saleAuthorization?.version ?? "",
  ).trim();
  const reason = String(event?.reasonCode ?? event?.reason ?? "").trim();
  const attempted = String(
    event?.attemptedKind ??
      event?.attemptedAction ??
      event?.parsedKind ??
      event?.eventKind ??
      event?.detail ??
      "",
  ).toLowerCase();
  return (
    version.startsWith("pwt-sale-") ||
    reason === "work-market-v2-version-required" ||
    attempted.includes("listing") ||
    attempted.includes("list")
  );
}

function tokenPayloadWithoutInvalidEventsForActiveListings(payload) {
  const activeListingKeys = new Set(
    (Array.isArray(payload?.listings) ? payload.listings : [])
      .filter((listing) => listing?.confirmed === true)
      .map(tokenActiveListingEventKey)
      .filter(Boolean),
  );
  if (activeListingKeys.size === 0 || !Array.isArray(payload?.invalidEvents)) {
    return payload;
  }

  const invalidEvents = payload.invalidEvents.filter((event) => {
    const key = tokenActiveListingEventKey(event);
    return (
      !key ||
      !activeListingKeys.has(key) ||
      !invalidEventLooksLikeListingAttempt(event)
    );
  });
  if (invalidEvents.length === payload.invalidEvents.length) {
    return payload;
  }

  return {
    ...payload,
    invalidEvents,
    stats: {
      ...(payload.stats ?? {}),
      invalidEvents: invalidEvents.length,
    },
  };
}

async function indexedWalletActiveListings(
  network,
  tokenScope,
  addresses,
  limit = 100,
) {
  const scope = normalizeTokenScope(tokenScope);
  if (
    network !== "livenet" ||
    scope !== WORK_TOKEN_ID ||
    !proofIndexReadFeatureEnabled("log-history,activity-history,log") ||
    !Array.isArray(addresses) ||
    addresses.length === 0
  ) {
    return [];
  }

  const listingsByKey = new Map();
  const kinds = ["token-listing", "token-listings", "token-listing-sealed"];
  for (const address of addresses) {
    const value = String(address ?? "").trim();
    if (!value) {
      continue;
    }

    for (const kind of kinds) {
      const page = await payloadWithFallbackAfterMs(
        stableProofIndexLogHistoryPayload(
          network,
          kind,
          new URLSearchParams({
            address: value,
            limit: String(limit),
            status: "confirmed",
          }),
        ),
        null,
        WALLET_SCOPED_RECOVERY_WAIT_MS,
      ).catch((error) => {
        console.error(
          `Proof index wallet active-listing lookup failed for ${value}: ${errorSummary(error)}`,
        );
        return null;
      });
      const pageCoversTip = page
        ? await proofIndexPayloadCoversConfirmedTip(
            page,
            network,
            "wallet active-listing recovery",
          )
        : false;
      const pageIndexedThroughBlock = Number(
        page?.indexedThroughBlock ??
          page?.stats?.indexedThroughBlock,
      );
      const pageHasIndexedCheckpoint =
        Number.isSafeInteger(pageIndexedThroughBlock) &&
        pageIndexedThroughBlock > 0;
      if (!page || (!pageCoversTip && !pageHasIndexedCheckpoint)) {
        continue;
      }

      for (const item of Array.isArray(page.items) ? page.items : []) {
        const isSealEvent =
          kind === "token-listing-sealed" ||
          item?.kind === "token-listing-sealed";
        const itemPosition =
          item?.position &&
          typeof item.position === "object" &&
          !Array.isArray(item.position)
            ? item.position
            : {};
        const itemListing =
          item?.listing &&
          typeof item.listing === "object" &&
          !Array.isArray(item.listing)
            ? item.listing
            : {};
        const listingSaleAuthorization =
          itemListing.saleAuthorization &&
          typeof itemListing.saleAuthorization === "object" &&
          !Array.isArray(itemListing.saleAuthorization)
            ? itemListing.saleAuthorization
            : {};
        const eventSaleAuthorization =
          item?.saleAuthorization &&
          typeof item.saleAuthorization === "object" &&
          !Array.isArray(item.saleAuthorization)
            ? item.saleAuthorization
            : {};
        const saleAuthorization =
          Object.keys(eventSaleAuthorization).length >
          Object.keys(listingSaleAuthorization).length
            ? eventSaleAuthorization
            : listingSaleAuthorization;
        const listingAuthorization =
          itemListing.listingAuthorization &&
          typeof itemListing.listingAuthorization === "object" &&
          !Array.isArray(itemListing.listingAuthorization)
            ? itemListing.listingAuthorization
            : item?.listingAuthorization &&
                typeof item.listingAuthorization === "object" &&
                !Array.isArray(item.listingAuthorization)
              ? item.listingAuthorization
              : saleAuthorization;
        const listingId = String(
          itemListing.listingId ?? item?.listingId ?? item?.txid ?? "",
        )
          .trim()
          .toLowerCase();
        const tokenId = normalizeTokenScope(
          itemListing.tokenId ??
            saleAuthorization.tokenId ??
            itemListing.ticker ??
            saleAuthorization.ticker ??
            item?.tokenId ??
            item?.ticker ??
            "",
        );
        const sellerAddress = String(
          itemListing.sellerAddress ??
            saleAuthorization.sellerAddress ??
            item?.sellerAddress ??
            item?.actor ??
            "",
        ).trim();
        if (
          !/^[0-9a-f]{64}$/u.test(listingId) ||
          item?.confirmed !== true ||
          tokenId !== WORK_TOKEN_ID ||
          sellerAddress.toLowerCase() !== value.toLowerCase()
        ) {
          continue;
        }

        const frozenTerms =
          itemListing.frozenTerms &&
          typeof itemListing.frozenTerms === "object" &&
          !Array.isArray(itemListing.frozenTerms)
            ? itemListing.frozenTerms
            : itemListing.workAmoFrozenTerms &&
                typeof itemListing.workAmoFrozenTerms === "object" &&
                !Array.isArray(itemListing.workAmoFrozenTerms)
              ? itemListing.workAmoFrozenTerms
              : {};
        const sealTxid = String(
          itemListing.sealTxid ??
            item?.sealTxid ??
            (isSealEvent ? item?.txid : "") ??
            "",
        )
          .trim()
          .toLowerCase();
        const listingStatus =
          itemListing.status ?? (isSealEvent ? "sealing" : item?.status);
        const listing = {
          ...itemListing,
          amountSubatoms:
            itemListing.amountSubatoms ??
            frozenTerms.unitAmountSubatoms ??
            saleAuthorization.amountSubatoms,
          confirmed: true,
          createdAt: itemListing.createdAt ?? item?.createdAt,
          listingAuthorization,
          listingId,
          network: itemListing.network ?? item?.network ?? network,
          saleAuthorization,
          sealAt:
            itemListing.sealAt ??
            item?.sealAt ??
            (isSealEvent ? item?.blockTime ?? item?.createdAt : undefined),
          sealBlockHash:
            itemListing.sealBlockHash ??
            item?.sealBlockHash ??
            (isSealEvent
              ? item?.blockHash ?? itemPosition.blockHash
              : undefined),
          sealBlockHeight:
            itemListing.sealBlockHeight ??
            item?.sealBlockHeight ??
            (isSealEvent
              ? item?.blockHeight ?? itemPosition.blockHeight
              : undefined),
          sealBlockIndex:
            itemListing.sealBlockIndex ??
            item?.sealBlockIndex ??
            (isSealEvent
              ? item?.blockIndex ?? itemPosition.blockTransactionIndex
              : undefined),
          sealConfirmed:
            itemListing.sealConfirmed ??
            item?.sealConfirmed ??
            (isSealEvent ? item?.confirmed === true : undefined),
          sealDataBytes:
            itemListing.sealDataBytes ??
            item?.sealDataBytes ??
            (isSealEvent ? item?.dataBytes : undefined),
          sealFrozenNetworkValueSats:
            itemListing.sealFrozenNetworkValueSats ??
            item?.sealFrozenNetworkValueSats ??
            (isSealEvent ? item?.frozenNetworkValueSats : undefined),
          sealLiveNetworkValueSats:
            itemListing.sealLiveNetworkValueSats ??
            item?.sealLiveNetworkValueSats ??
            (isSealEvent ? item?.liveNetworkValueSats : undefined),
          sealMinerFeeCanonical:
            itemListing.sealMinerFeeCanonical === true ||
            item?.sealMinerFeeCanonical === true ||
            item?.canonicalMinerFeeCovered === true,
          sealMinerFeeSource:
            itemListing.sealMinerFeeSource ??
            item?.sealMinerFeeSource ??
            (isSealEvent ? item?.minerFeeSource : undefined),
          sealMinerFeeSats:
            itemListing.sealMinerFeeSats ??
            item?.sealMinerFeeSats ??
            (isSealEvent ? item?.minerFeeSats : undefined),
          sealProtocolVout:
            itemListing.sealProtocolVout ??
            item?.sealProtocolVout ??
            (isSealEvent
              ? item?.protocolVout ?? itemPosition.protocolVout
              : undefined),
          sealRecordOrdinal:
            itemListing.sealRecordOrdinal ??
            item?.sealRecordOrdinal ??
            (isSealEvent
              ? item?.recordOrdinal ?? itemPosition.recordOrdinal
              : undefined),
          sealTransactionBlockHeight:
            itemListing.sealTransactionBlockHeight ??
            item?.sealTransactionBlockHeight ??
            (isSealEvent
              ? item?.blockHeight ?? itemPosition.blockHeight
              : undefined),
          sealTxid,
          sellerAddress,
          status: listingStatus,
          ticker: WORK_TOKEN_TICKER,
          tokenId: WORK_TOKEN_ID,
          txid:
            itemListing.txid ??
            (isSealEvent ? listingId : item?.txid) ??
            listingId,
        };
        listingsByKey.set(
          tokenListingItemKey(listing),
          mergeTokenListingRecord(
            listingsByKey.get(tokenListingItemKey(listing)),
            listing,
          ),
        );
      }
    }
  }

  return [...listingsByKey.values()].sort(compareTokenHistoryPageItems);
}

function workActiveListingsFromTransactions(txs, network, recoveryAddresses = []) {
  // A first-party transaction/outspend recovery cannot independently prove a
  // pwt-sale-v3 action's canonical H-1 oracle. After the livenet cutover it
  // therefore fails closed instead of reviving a legacy listing or accepting
  // a self-attested V3 oracle. Canonical indexed reads remain authoritative.
  if (network === "livenet") {
    return [];
  }
  const addressKeys = new Set(
    (Array.isArray(recoveryAddresses) ? recoveryAddresses : [])
      .map((address) => String(address ?? "").trim().toLowerCase())
      .filter(Boolean),
  );
  const listingsById = new Map();
  for (const tx of tokenProtocolSortedTransactions(
    (Array.isArray(txs) ? txs : []).filter(Boolean),
  )) {
    const txid = transactionTxid(tx);
    if (!txid || !transactionConfirmed(tx)) {
      continue;
    }

    const vin = Array.isArray(tx.vin) ? tx.vin : [];
    const vout = Array.isArray(tx.vout) ? tx.vout : [];
    const txInputAddresses = inputAddresses(vin);
    let remainingRegistrySats = tokenPaymentAmountBeforeProtocol(
      vout,
      WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
    );
    const createdAt = new Date(tokenTransactionTime(tx)).toISOString();
    const messages = decodedProtocolMessages(vout, TOKEN_PROTOCOL_PREFIX);

    for (const message of messages) {
      const parsed = parseTokenPayload(message, network);
      const authorization = parsed?.saleAuthorization;
      if (
        parsed?.kind !== "list" ||
        authorization?.tokenId !== WORK_TOKEN_ID ||
        authorization.registryAddress !== WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS ||
        authorization.ticker !== WORK_TOKEN_TICKER ||
        (txInputAddresses.length > 0 &&
          !txInputAddresses.includes(authorization.sellerAddress)) ||
        (addressKeys.size > 0 &&
          !addressKeys.has(String(authorization.sellerAddress).toLowerCase())) ||
        remainingRegistrySats < TOKEN_MIN_MUTATION_PRICE_SATS ||
        !tokenListingAnchorIsPresent(vout, authorization)
      ) {
        continue;
      }

      remainingRegistrySats -= TOKEN_MIN_MUTATION_PRICE_SATS;
      const listedAmount = tokenSaleAuthorizationLedgerAmount(authorization);
      if (listedAmount === null) {
        continue;
      }
      listingsById.set(
        txid,
        mergeTokenListingRecord(listingsById.get(txid), {
          ...tokenLedgerAmountFields(WORK_TOKEN_ID, listedAmount),
          confirmed: true,
          createdAt,
          dataBytes: proofProtocolDataBytesForVout(vout),
          listingId: txid,
          network,
          priceSats: authorization.priceSats,
          registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
          saleAuthorization: authorization,
          sellerAddress: authorization.sellerAddress,
          ticker: WORK_TOKEN_TICKER,
          tokenId: WORK_TOKEN_ID,
        }),
      );
    }
  }

  return [...listingsById.values()].sort(compareTokenHistoryPageItems);
}

async function workActiveListingHistoryPageFromTxidQuery(
  network,
  query,
  pagination,
) {
  const txid = String(query ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(txid)) {
    return null;
  }

  const tx = await fetchTransaction(txid, network).catch(() => null);
  if (!tx || !transactionConfirmed(tx)) {
    return null;
  }

  const listings = workActiveListingsFromTransactions([tx], network);
  if (listings.length === 0) {
    return null;
  }

  const authority = await strictCoreTokenListingReconciliation(
    listings,
    network,
    { requireAll: network === "livenet" },
  );

  return {
    ...paginatedHistoryPayload({
      indexedAt: new Date(tokenTransactionTime(tx)).toISOString(),
      items: authority.listings,
      kind: "listings",
      network,
      pagination,
      source: "core-authoritative-token-listing-query",
    }),
    listingAuthority: authority.evidence,
  };
}

async function workTokenStateWithIndexedActiveListings(
  payload,
  network,
  recoveryAddresses,
) {
  const txids = await indexedWorkActiveListingTxids(
    network,
    recoveryAddresses,
  );
  if (txids.length === 0) {
    return payload;
  }

  const txs = await quickConfirmedTransactionsForTxids(
    txids,
    network,
    txids.length,
  );
  if (txs.length === 0) {
    return payload;
  }

  const recoveredListings = workActiveListingsFromTransactions(
    txs,
    network,
    recoveryAddresses,
  );
  if (recoveredListings.length === 0) {
    return payload;
  }
  const recoveredPayload = tokenStateWithPreservedListingRecords(payload, {
    listings: recoveredListings,
  });
  const currentRecoveredPayload = tokenPayloadWithCurrentWorkActiveListingPolicy(
    recoveredPayload,
    network,
  );
  const spendablePayload = await tokenPayloadWithSpendableListings(
    currentRecoveredPayload,
    network,
  );
  const currentSpendablePayload = tokenPayloadWithCurrentWorkActiveListingPolicy(
    spendablePayload,
    network,
  );
  return {
    ...currentSpendablePayload,
    source: mergedSourceLabel(
      currentSpendablePayload?.source,
      "proof-indexer-token-listing-tx-recovery",
    ),
  };
}

function tokenPayloadWithCurrentWalletWorkRecoveryListingPolicy(
  payload,
  network,
) {
  return tokenPayloadWithCurrentWorkActiveListingPolicy(payload, network);
}

function tokenPayloadWithCurrentWorkActiveListingPolicy(
  payload,
  network = payload?.network,
  options = {},
) {
  const cutoverPayload = applyWorkMarketV2CutoverToTokenState(payload);
  const indexedThroughBlock = Number(
    cutoverPayload?.indexedThroughBlock ??
      cutoverPayload?.stats?.indexedThroughBlock,
  );
  if (
    network !== "livenet" ||
    !Number.isSafeInteger(indexedThroughBlock) ||
    indexedThroughBlock < WORK_AMO_V8_ACTIVATION_HEIGHT
  ) {
    return cutoverPayload;
  }

  const listings = Array.isArray(cutoverPayload?.listings)
    ? cutoverPayload.listings
    : [];
  const listingTokenId = (listing) =>
    normalizeTokenScope(
      listing?.tokenId ??
        listing?.saleAuthorization?.tokenId ??
        listing?.listingAuthorization?.tokenId ??
        listing?.authorization?.tokenId ??
        listing?.ticker ??
        listing?.saleAuthorization?.ticker ??
        listing?.listingAuthorization?.ticker ??
        listing?.authorization?.ticker ??
        "",
    );
  const listingAuthorizationVersion = (listing) =>
    String(
      listing?.saleAuthorization?.version ??
        listing?.listingAuthorization?.version ??
        listing?.authorization?.version ??
        listing?.authorizationVersion ??
        listing?.version ??
        "",
    )
      .trim()
      .toLowerCase();
  const currentListings = listings.filter((listing) => {
    if (listingTokenId(listing) !== WORK_TOKEN_ID) {
      return true;
    }
    return listingAuthorizationVersion(listing) === WORK_AMO_V8_AUTH_VERSION;
  });

  const payloadTokens = Array.isArray(cutoverPayload?.tokens)
    ? cutoverPayload.tokens
    : [];
  const scopedWorkOnlyPayload =
    payloadTokens.length === 1 &&
    isWorkTokenId(payloadTokens[0]?.tokenId) &&
    listings.every((listing) => listingTokenId(listing) === WORK_TOKEN_ID);
  const forceScopedWorkListingCounts =
    options.forceScopedWorkListingCounts === true &&
    scopedWorkOnlyPayload;
  const removedWorkListings = listings.filter(
    (listing) =>
      listingTokenId(listing) === WORK_TOKEN_ID &&
      !currentListings.includes(listing),
  );
  const workTokenHasLowestAskAlias = payloadTokens.some(
    (token) =>
      isWorkTokenId(token?.tokenId) &&
      (
        Object.prototype.hasOwnProperty.call(
          token,
          "lowestAskPricePerToken",
        ) ||
        Object.prototype.hasOwnProperty.call(
          token,
          "lowestAskPricePerTokenExact",
        )
      ),
  );
  if (
    removedWorkListings.length === 0 &&
    !workTokenHasLowestAskAlias &&
    !forceScopedWorkListingCounts
  ) {
    return cutoverPayload;
  }

  const explicitCount = (value) => {
    const count = Number(value);
    return Number.isSafeInteger(count) && count >= 0 ? count : null;
  };
  const declaredListingCount = explicitCount(
    cutoverPayload?.totalCounts?.listings,
  );
  const completeListingSet =
    cutoverPayload?.summaryOnly !== true &&
    cutoverPayload?.collectionHasMore?.listings !== true &&
    (
      declaredListingCount === null ||
      declaredListingCount === listings.length
    );
  const workMarketSummary = (() => {
    try {
      return tokenAggregateSummaries({
        ...cutoverPayload,
        listings: currentListings,
      }).get(WORK_TOKEN_ID);
    } catch {
      return null;
    }
  })();
  const existingWorkToken = payloadTokens.find((token) =>
    isWorkTokenId(token?.tokenId)
  );
  const removedConfirmedWorkListings = removedWorkListings.filter(
    (listing) => listing?.confirmed === true,
  ).length;
  const removedPendingWorkListings =
    removedWorkListings.length - removedConfirmedWorkListings;
  const reconciledWorkCount = (key, removedCount, computed) => {
    if (completeListingSet || forceScopedWorkListingCounts) {
      return computed;
    }
    const existing = tokenSummaryMetricValue(existingWorkToken?.[key]);
    return existing === undefined
      ? computed
      : Math.max(0, existing - removedCount);
  };
  const computedConfirmedOpenWorkListings =
    tokenSummaryMetricValue(workMarketSummary?.confirmedOpenListings) ??
    currentListings.filter(
      (listing) =>
        listingTokenId(listing) === WORK_TOKEN_ID &&
        listing?.confirmed === true,
    ).length;
  const computedOpenWorkListings =
    tokenSummaryMetricValue(workMarketSummary?.openListings) ??
    currentListings.filter(
      (listing) => listingTokenId(listing) === WORK_TOKEN_ID,
    ).length;
  const computedPendingOpenWorkListings =
    tokenSummaryMetricValue(workMarketSummary?.pendingOpenListings) ??
    currentListings.filter(
      (listing) =>
        listingTokenId(listing) === WORK_TOKEN_ID &&
        listing?.confirmed !== true,
    ).length;
  const workLowestAskExact = canonicalWorkQ16SummaryUnitPriceDescriptor(
    workMarketSummary?.lowestAskPricePerTokenExact,
  );
  const workLowestAsk = workLowestAskExact
    ? workLowestAskExact.decimal
    : tokenSummaryMetricValue(workMarketSummary?.lowestAskPricePerToken);
  const workMetrics = {
    confirmedOpenListings:
      reconciledWorkCount(
        "confirmedOpenListings",
        removedConfirmedWorkListings,
        computedConfirmedOpenWorkListings,
      ),
    openListings:
      reconciledWorkCount(
        "openListings",
        removedWorkListings.length,
        computedOpenWorkListings,
      ),
    pendingOpenListings:
      reconciledWorkCount(
        "pendingOpenListings",
        removedPendingWorkListings,
        computedPendingOpenWorkListings,
      ),
    ...(workLowestAskExact || (workLowestAsk !== undefined && workLowestAsk > 0)
      ? {
          lowestAskPricePerToken:
            workLowestAskExact?.decimal ?? workLowestAsk,
        }
      : {}),
    ...(workLowestAskExact
      ? { lowestAskPricePerTokenExact: workLowestAskExact }
      : {}),
  };
  const workMetricsHasAsk =
    Object.prototype.hasOwnProperty.call(
      workMetrics,
      "lowestAskPricePerToken",
    ) ||
    Object.prototype.hasOwnProperty.call(
      workMetrics,
      "lowestAskPricePerTokenExact",
    );
  const tokens = Array.isArray(cutoverPayload?.tokens)
    ? cutoverPayload.tokens.map((token) => {
        if (!isWorkTokenId(token?.tokenId)) {
          return token;
        }
        const next = { ...token, ...workMetrics };
        if (!workMetricsHasAsk) {
          delete next.lowestAskPricePerToken;
          delete next.lowestAskPricePerTokenExact;
        } else if (!workLowestAskExact) {
          delete next.lowestAskPricePerTokenExact;
        }
        return next;
      })
    : cutoverPayload?.tokens;
  const openListingCounts = Array.isArray(tokens)
    ? tokens.map((token) =>
        isWorkTokenId(token?.tokenId)
          ? workMetrics.openListings
          : explicitCount(token?.openListings),
      )
    : [];
  const totalOpenListings =
    openListingCounts.length > 0 &&
    openListingCounts.every((count) => count !== null)
      ? openListingCounts.reduce((total, count) => total + count, 0)
      : currentListings.length;
  const confirmedOpenCounts = Array.isArray(tokens)
    ? tokens.map((token) =>
        isWorkTokenId(token?.tokenId)
          ? workMetrics.confirmedOpenListings
          : explicitCount(token?.confirmedOpenListings),
      )
    : [];
  const confirmedOpenListings =
    confirmedOpenCounts.length > 0 &&
    confirmedOpenCounts.every((count) => count !== null)
      ? confirmedOpenCounts.reduce((total, count) => total + count, 0)
      : currentListings.filter((listing) => listing?.confirmed === true).length;
  const pendingOpenCounts = Array.isArray(tokens)
    ? tokens.map((token) =>
        isWorkTokenId(token?.tokenId)
          ? workMetrics.pendingOpenListings
          : explicitCount(token?.pendingOpenListings),
      )
    : [];
  const pendingOpenListings =
    pendingOpenCounts.length > 0 &&
    pendingOpenCounts.every((count) => count !== null)
      ? pendingOpenCounts.reduce((total, count) => total + count, 0)
      : currentListings.filter((listing) => listing?.confirmed !== true).length;
  const collectionHasMore =
    cutoverPayload?.collectionHasMore &&
    typeof cutoverPayload.collectionHasMore === "object" &&
    !Array.isArray(cutoverPayload.collectionHasMore)
      ? {
          ...cutoverPayload.collectionHasMore,
          listings: forceScopedWorkListingCounts
            ? false
            : totalOpenListings > currentListings.length,
        }
      : cutoverPayload?.collectionHasMore;

  return {
    ...cutoverPayload,
    ...(collectionHasMore
      ? {
          collectionHasMore,
          hasMore: Object.values(collectionHasMore).some(Boolean),
        }
      : {}),
    listings: currentListings,
    ...(cutoverPayload?.stats &&
    typeof cutoverPayload.stats === "object" &&
    !Array.isArray(cutoverPayload.stats)
      ? {
          stats: {
            ...cutoverPayload.stats,
            activeListings: totalOpenListings,
            confirmedOpenListings,
            openListings: totalOpenListings,
            pendingOpenListings,
          },
        }
      : {}),
    ...(cutoverPayload?.totalCounts &&
    typeof cutoverPayload.totalCounts === "object" &&
    !Array.isArray(cutoverPayload.totalCounts)
      ? {
          totalCounts: {
            ...cutoverPayload.totalCounts,
            listings: totalOpenListings,
          },
        }
      : {}),
    ...(tokens ? { tokens } : {}),
    currentWorkActiveListingPolicy: {
      activationHeight: WORK_AMO_V8_ACTIVATION_HEIGHT,
      authVersion: WORK_AMO_V8_AUTH_VERSION,
      removedListings: removedWorkListings.length,
    },
  };
}

async function tokenPayloadWithWalletActiveListings(
  payload,
  network,
  tokenScope,
  recoveryAddresses,
) {
  if (
    network !== "livenet" ||
    normalizeTokenScope(tokenScope) !== WORK_TOKEN_ID ||
    !Array.isArray(recoveryAddresses) ||
    recoveryAddresses.length === 0
  ) {
    return payload;
  }

  const addressKeys = new Set(
    recoveryAddresses
      .map((address) => String(address ?? "").trim().toLowerCase())
      .filter(Boolean),
  );
  const indexedListings = await indexedWalletActiveListings(
    network,
    tokenScope,
    recoveryAddresses,
  );
  const indexedPayload =
    indexedListings.length > 0
      ? {
          ...tokenStateWithPreservedListingRecords(payload, {
            listings: indexedListings,
          }),
          indexedAt: newerIso(
            payload?.indexedAt,
            indexedListings[0]?.createdAt,
          ),
          source: mergedSourceLabel(
            payload?.source,
            "proof-indexer-log-history-wallet-active-listings",
          ),
        }
      : payload;
  const currentIndexedPayload =
    tokenPayloadWithCurrentWalletWorkRecoveryListingPolicy(
      indexedPayload,
      network,
    );
  const listings = (Array.isArray(currentIndexedPayload?.listings)
    ? currentIndexedPayload.listings
    : []
  ).filter(
    (listing) =>
      listing?.confirmed === true &&
      addressKeys.has(String(listing?.sellerAddress ?? "").toLowerCase()) &&
      normalizeTokenScope(listing?.tokenId) === WORK_TOKEN_ID,
  );

  let scopedPayload = listings.length > 0
    ? tokenStateWithPreservedListingRecords(currentIndexedPayload, { listings })
    : currentIndexedPayload;
  if (listings.length > 0) {
    scopedPayload = await tokenPayloadWithSpendableListings({
      ...scopedPayload,
      listings,
    }, network);
  }

  return tokenPayloadWithoutInvalidEventsForActiveListings(scopedPayload);
}

function emptyRegistryPayload(network) {
  return {
    activity: [],
    indexedAt: new Date().toISOString(),
    listings: [],
    network,
    pendingEvents: [],
    records: [],
    registryAddress: registryAddressForNetwork(network) ?? "",
    sales: [],
    source: mempoolBase(network),
    stats: {
      confirmed: 0,
      pending: 0,
      pendingChanges: 0,
      pendingRecords: 0,
      total: 0,
    },
  };
}

const CANONICAL_SUMMARY_ITEM_OMITTED_KEYS = new Set([
  "actionAuthorization",
  "listing",
  "listingAuthorization",
  "parsed",
  "payload",
  "rawPayload",
  "replayMetadata",
  "workAmoV5RawScriptWitness",
  "workAmoV5ReplayOutput",
  "workAmoV5ReplayRawWitness",
]);

function canonicalSummaryItemPreview(record) {
  if (!record || typeof record !== "object" || Array.isArray(record)) {
    return record;
  }
  return Object.fromEntries(
    Object.entries(record).filter(
      ([key]) => !CANONICAL_SUMMARY_ITEM_OMITTED_KEYS.has(key),
    ),
  );
}

function compactRegistrySummaryPayload(payload) {
  const activity = Array.isArray(payload?.activity) ? payload.activity : [];
  const listings = Array.isArray(payload?.listings) ? payload.listings : [];
  const pendingEvents = Array.isArray(payload?.pendingEvents)
    ? payload.pendingEvents
    : [];
  const sales = Array.isArray(payload?.sales) ? payload.sales : [];
  const compactActivity = recentByCreatedAt(
    activity,
    SUMMARY_ACTIVITY_LIMIT,
  ).map(canonicalSummaryItemPreview);
  const compactListings = recentByCreatedAt(
    listings,
    SUMMARY_MARKET_LIMIT,
  ).map(canonicalSummaryItemPreview);
  const compactPendingEvents = recentByCreatedAt(
    pendingEvents,
    SUMMARY_MARKET_LIMIT,
  ).map(canonicalSummaryItemPreview);
  const compactSales = recentByCreatedAt(
    sales,
    SUMMARY_MARKET_LIMIT,
  ).map(canonicalSummaryItemPreview);
  const summaryOnly = payload?.summaryOnly === true;
  const explicitCount = (value) => {
    if (value === undefined || value === null || value === "") {
      return undefined;
    }
    const number = Number(value);
    return Number.isFinite(number) && number >= 0 ? number : undefined;
  };
  const totalCountFrom = (key, computed, statKeys = []) => {
    const existing = explicitCount(payload?.totalCounts?.[key]);
    if (existing !== undefined) {
      return existing;
    }
    if (!summaryOnly) {
      return computed;
    }
    for (const statKey of statKeys) {
      const stat = explicitCount(payload?.stats?.[statKey]);
      if (stat !== undefined) {
        return stat;
      }
    }
    return null;
  };
  const totalCounts = {
    ...(payload?.totalCounts ?? {}),
    activity:
      totalCountFrom("activity", activity.length, ["total", "activity"]) ??
      explicitCount(payload?.totalCount) ??
      null,
    listings: totalCountFrom("listings", listings.length, ["listings"]),
    pendingEvents: totalCountFrom(
      "pendingEvents",
      pendingEvents.length,
      ["pendingChanges", "pendingEvents"],
    ),
    sales: totalCountFrom("sales", sales.length, ["sales"]),
  };
  const collectionHasMoreValue = (key, total, visible) =>
    Number.isFinite(total)
      ? total > visible
      : payload?.collectionHasMore?.[key] === true;
  const collectionHasMore = {
    activity: collectionHasMoreValue(
      "activity",
      totalCounts.activity,
      compactActivity.length,
    ),
    listings: collectionHasMoreValue(
      "listings",
      totalCounts.listings,
      compactListings.length,
    ),
    pendingEvents: collectionHasMoreValue(
      "pendingEvents",
      totalCounts.pendingEvents,
      compactPendingEvents.length,
    ),
    sales: collectionHasMoreValue(
      "sales",
      totalCounts.sales,
      compactSales.length,
    ),
  };
  return {
    ...payload,
    activity: compactActivity,
    collectionHasMore,
    hasMore: Object.values(collectionHasMore).some(Boolean),
    listings: compactListings,
    pendingEvents: compactPendingEvents,
    sales: compactSales,
    summaryOnly: true,
    totalCount:
      explicitCount(payload?.totalCount) ??
      explicitCount(payload?.stats?.total) ??
      (summaryOnly ? null : activity.length),
    totalCounts,
  };
}

function compactWorkSummaryPayload(payload) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return payload;
  }
  const tokenState = payload.token && typeof payload.token === "object"
    ? tokenPayloadWithCurrentWorkActiveListingPolicy(
        payload.token,
        payload.network,
      )
    : payload.token;

  return {
    ...payload,
    token:
      tokenState && typeof tokenState === "object"
        ? compactTokenSummaryPayload(tokenState, WORK_TOKEN_ID, {
            includeAllScopedListings: false,
            compactMarketRecords: true,
          })
        : tokenState,
  };
}

function compactMarketplaceSummaryReadPayload(payload) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return payload;
  }
  const tokenState = payload.token && typeof payload.token === "object"
    ? tokenPayloadWithCurrentWorkActiveListingPolicy(
        payload.token,
        payload.network,
      )
    : payload.token;

  return {
    ...payload,
    registry:
      payload.registry && typeof payload.registry === "object"
        ? compactRegistrySummaryPayload(payload.registry)
        : payload.registry,
    token:
      tokenState && typeof tokenState === "object"
        ? compactTokenSummaryPayload(tokenState, "", {
            includeAllScopedListings: false,
            compactMarketRecords: true,
          })
        : tokenState,
  };
}

function compactTokenDirectorySummaryPayload(payload, tokenScope = "") {
  return compactTokenSummaryPayload(payload, tokenScope, {
    compactMarketRecords: true,
    includeAllScopedListings: false,
  });
}

function compactActivitySummaryPayload(payload, verifiedIndexedThroughBlock = 0) {
  const activity = Array.isArray(payload?.activity) ? payload.activity : [];
  const sourceStats =
    payload?.summaryOnly === true
      ? payload?.stats
      : activityStatsFromItems(activity, payload?.stats ?? {});
  const latestEventBlock = Math.max(
    Number(sourceStats?.latestEventBlock) || 0,
    Number(sourceStats?.indexedThroughBlock) || 0,
    Number(indexedThroughBlockFromItems(activity)) || 0,
  );
  const coverage = Number(verifiedIndexedThroughBlock);
  const stats = {
    ...(sourceStats ?? {}),
    ...(latestEventBlock > 0 ? { latestEventBlock } : {}),
    ...(Number.isSafeInteger(coverage) && coverage > 0
      ? { indexedThroughBlock: coverage }
      : {}),
  };
  const compactActivity = recentByCreatedAt(
    activity,
    SUMMARY_ACTIVITY_LIMIT,
  ).map(canonicalSummaryItemPreview);
  const totalCount = Number(
    payload?.totalCount ?? stats?.total ?? activity.length,
  );
  return {
    ...payload,
    activity: compactActivity,
    hasMore: totalCount > compactActivity.length,
    stats,
    summaryOnly: true,
    totalCount,
  };
}

function activityStatsFromItems(activity, baseStats = {}) {
  const dataBytes = totalProtocolDataBytes(activity);
  const fileActions = activity.filter((item) => item.kind === "file").length;
  const inceptionBondActions = activity.filter(isInceptionBondActivityItem).length;
  const infinityBondActions = activity.filter(isInfinityBondActivityItem).length;
  const messageActions = activity.filter(
    (item) =>
      (item.kind === "mail" || item.kind === "reply") &&
      !isBondActivityItem(item),
  ).length;
  const tokenActions = activity.filter((item) =>
    String(item.kind).startsWith("token-"),
  ).length;
  const akActions = activity.filter((item) =>
    String(item.kind).startsWith("ak-"),
  ).length;

  return {
    ...baseStats,
    ak: akActions,
    dataBytes,
    files: fileActions,
    indexedThroughBlock: indexedThroughBlockFromItems(activity),
    inceptionBonds: inceptionBondActions,
    infinityBonds: infinityBondActions,
    messages: messageActions,
    pending: activity.filter((item) => !item.confirmed).length,
    tokens: tokenActions,
    total: activity.length,
  };
}

function numericValue(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function canonicalEventIdentityDetails(item = {}) {
  return [
    "_powEventIndex",
    "eventKeyVout",
    "protocolVout",
    "recordOrdinal",
    "eventId",
  ]
    .reduce((details, key) => {
      const rawValue = item?.[key];
      if (
        rawValue === undefined ||
        rawValue === null ||
        rawValue === ""
      ) {
        return details;
      }
      const value = Number(rawValue);
      if (Number.isSafeInteger(value) && value >= 0) {
        details[key] = value;
      }
      return details;
    }, {});
}

function verifiedCanonicalMinerFeeCoverage(value) {
  const coverage = value && typeof value === "object" && !Array.isArray(value)
    ? value
    : null;
  if (!coverage) {
    return null;
  }
  const confirmedEvents = Number(coverage.confirmedEvents);
  const coveredConfirmedEvents = Number(coverage.coveredConfirmedEvents);
  const missingConfirmedEvents = Number(coverage.missingConfirmedEvents);
  const confirmedTransactions = Number(coverage.confirmedTransactions);
  const coveredConfirmedTransactions = Number(
    coverage.coveredConfirmedTransactions,
  );
  const missingConfirmedTransactions = Number(
    coverage.missingConfirmedTransactions,
  );
  const missingConfirmedTxids = Array.isArray(coverage.missingConfirmedTxids)
    ? coverage.missingConfirmedTxids
        .map((txid) => String(txid ?? "").trim().toLowerCase())
        .filter(Boolean)
    : null;
  if (
    coverage.complete !== true ||
    coverage.source !== "proof-indexer-normalized-input-output-totals" ||
    !Number.isSafeInteger(confirmedEvents) ||
    confirmedEvents <= 0 ||
    !Number.isSafeInteger(coveredConfirmedEvents) ||
    coveredConfirmedEvents !== confirmedEvents ||
    !Number.isSafeInteger(missingConfirmedEvents) ||
    missingConfirmedEvents !== 0 ||
    !Number.isSafeInteger(confirmedTransactions) ||
    confirmedTransactions <= 0 ||
    !Number.isSafeInteger(coveredConfirmedTransactions) ||
    coveredConfirmedTransactions !== confirmedTransactions ||
    !Number.isSafeInteger(missingConfirmedTransactions) ||
    missingConfirmedTransactions !== 0 ||
    !missingConfirmedTxids ||
    missingConfirmedTxids.length !== 0
  ) {
    return null;
  }
  return {
    complete: true,
    confirmedEvents,
    coveredConfirmedEvents,
    missingConfirmedEvents: 0,
    confirmedTransactions,
    coveredConfirmedTransactions,
    missingConfirmedTransactions: 0,
    missingConfirmedTxids: [],
    source: coverage.source,
  };
}

function numbersAgree(left, right, tolerance = 0.000001) {
  return Math.abs(numericValue(left) - numericValue(right)) <= tolerance;
}

function finitePositiveNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) && number > 0;
}

function workFloorPayloadHasFiniteNetworkValue(workFloor) {
  if (!workFloor) {
    return false;
  }

  const networkValue = workFloor.networkValueSats;
  const totalValue = workFloor.actualValue?.totalSats;
  const liveValue =
    workFloor.liveNetworkValueSats ?? workFloor.actualValue?.liveNetworkValueSats;
  const frozenValue =
    workFloor.frozenNetworkValueSats ??
    workFloor.actualValue?.frozenNetworkValueSats ??
    workFloor.actualValue?.frozenTotalSats;
  const hasCurrentMinerFeeAccounting =
    workFloor.network !== "livenet" ||
    (workFloor.actualValue?.creditMinerFeeAccountingModel ===
      CREDIT_MINER_FEE_ACCOUNTING_MODEL &&
      Boolean(
        verifiedCanonicalMinerFeeCoverage(
          workFloor.actualValue?.creditMinerFeeCoverage,
        ),
      ));
  return (
    hasCurrentMinerFeeAccounting &&
    finitePositiveNumber(networkValue) &&
    finitePositiveNumber(totalValue) &&
    numbersAgree(networkValue, totalValue, 0.01) &&
    (!finitePositiveNumber(liveValue) || numbersAgree(networkValue, liveValue, 0.01)) &&
    (!finitePositiveNumber(frozenValue) || Number.isFinite(Number(frozenValue)))
  );
}

function growthSummaryPayloadHasFiniteNetworkValue(growthSummary) {
  if (!growthSummary) {
    return false;
  }

  return (
    finitePositiveNumber(growthSummary.actualValue?.totalSats) &&
    (!growthSummary.workFloor ||
      workFloorPayloadHasFiniteNetworkValue(growthSummary.workFloor))
  );
}

function infinitySummaryPayloadHasKnownMainnetValue(summary) {
  return bondSummaryPayloadHasKnownMainnetValue(
    summary,
    INFINITY_BOND_CONFIG,
  );
}

function inceptionSummaryPayloadHasKnownMainnetValue(summary) {
  return bondSummaryPayloadHasKnownMainnetValue(
    summary,
    INCEPTION_BOND_CONFIG,
    { allowEmptyHistory: true },
  );
}

function exactBondSummaryPayloadIsCanonical(summary, config, options = {}) {
  const units = (value, allowZero = true) =>
    integerBigInt(value, { allowZero });
  const q8 = (value, allowZero = true) =>
    integerBigInt(value, { allowZero });
  const statSupply = units(summary?.stats?.confirmedSupply);
  const tokenSupply = units(summary?.token?.confirmedSupply);
  if (statSupply === null && tokenSupply === null) {
    return false;
  }
  const confirmedSupply =
    statSupply !== null && tokenSupply !== null
      ? statSupply > tokenSupply
        ? statSupply
        : tokenSupply
      : (statSupply ?? tokenSupply);
  const confirmedBondActions = Number(
    summary?.stats?.confirmedBondActions ??
      summary?.token?.stats?.confirmedMints ??
      0,
  );
  const mintFlow = units(summary?.actualValue?.bondMintFlowSats) ?? 0n;
  const saleFlow = units(summary?.actualValue?.bondSaleVolumeSats) ?? 0n;
  const transferFlow = units(summary?.actualValue?.bondTransferFeeSats) ?? 0n;
  const mutationFlow =
    units(summary?.actualValue?.bondMarketplaceMutationFeeSats) ?? 0n;
  const baseNetworkValueQ8 = q8(
    summary?.actualValue?.baseNetworkValueQ8,
  );
  const frozenNetworkValueQ8 = q8(
    summary?.actualValue?.frozenNetworkValueQ8 ?? summary?.frozenNetworkValueQ8,
  );
  const liveNetworkValueQ8 = q8(
    summary?.actualValue?.liveNetworkValueQ8 ?? summary?.liveNetworkValueQ8,
  );
  const networkValueQ8 = q8(
    summary?.actualValue?.networkValueQ8 ?? summary?.networkValueQ8,
  );
  const frozenFloorQ8 = q8(
    summary?.actualValue?.frozenFloorQ8 ?? summary?.frozenFloorQ8,
  );
  const liveFloorQ8 = q8(
    summary?.actualValue?.liveFloorQ8 ?? summary?.liveFloorQ8,
  );
  const chartPoints = Array.isArray(summary?.chartPoints)
    ? summary.chartPoints
    : [];
  const empty =
    confirmedSupply === 0n &&
    confirmedBondActions === 0 &&
    mintFlow === 0n &&
    networkValueQ8 === 0n;
  if (options.allowEmptyHistory === true && empty) {
    return chartPoints.length === 0;
  }
  if (
    !Number.isSafeInteger(confirmedBondActions) ||
    confirmedBondActions < 1 ||
    confirmedSupply <= 0n ||
    mintFlow <= 0n ||
    baseNetworkValueQ8 === null ||
    frozenNetworkValueQ8 === null ||
    liveNetworkValueQ8 === null ||
    networkValueQ8 === null ||
    frozenFloorQ8 === null ||
    liveFloorQ8 === null ||
    chartPoints.length === 0
  ) {
    return false;
  }
  const expectedBaseQ8 =
    (mintFlow + saleFlow + transferFlow + mutationFlow) *
    BOND_VALUE_Q8_SCALE;
  if (
    baseNetworkValueQ8 !== expectedBaseQ8 ||
    networkValueQ8 !== liveNetworkValueQ8 ||
    frozenFloorQ8 !== frozenNetworkValueQ8 / confirmedSupply ||
    liveFloorQ8 !== liveNetworkValueQ8 / confirmedSupply
  ) {
    return false;
  }
  const finalPoint = chartPoints.at(-1);
  if (
    units(finalPoint?.confirmedSupply) !== confirmedSupply ||
    q8(finalPoint?.networkValueQ8) !== networkValueQ8 ||
    q8(finalPoint?.floorQ8) !== liveFloorQ8
  ) {
    return false;
  }
  if (config.tokenId !== INCB_TOKEN_ID) {
    return (
      frozenNetworkValueQ8 === expectedBaseQ8 &&
      liveNetworkValueQ8 === expectedBaseQ8
    );
  }

  const actual = summary.actualValue ?? {};
  const confirmedIssuanceUnits = units(actual.confirmedIssuanceUnits);
  const directProofIssuanceUnits = units(actual.directProofIssuanceUnits);
  const attachedWorkIssuanceUnits = units(actual.attachedWorkIssuanceUnits);
  const issuanceNetworkValueQ8 = q8(actual.issuanceNetworkValueQ8);
  const issuanceDustQ8 = q8(actual.issuanceDustQ8);
  const issuanceFloorQ8 = q8(actual.issuanceFloorQ8);
  const attachedAtSendQ8 = q8(actual.attachedWorkLiveValueAtSendQ8);
  const attachedFrozenQ8 = q8(actual.attachedWorkFrozenValueQ8);
  const attachedLiveQ8 = q8(actual.attachedWorkLiveValueQ8);
  const attachedWorkActions = Number(actual.attachedWorkActions ?? 0);
  const attachedWorkAmountStorageModel = String(
    actual.attachedWorkAmountStorageModel ?? "",
  );
  const expectedWorkAmountStorageModel = String(
    options.workAmountStorageModel ?? "",
  );
  let attachedWorkAmountUnits = null;
  let attachedWorkProjectionExact = false;
  if (attachedWorkAmountStorageModel === WORK_ATOMIC_PROJECTION_MODEL) {
    attachedWorkAmountUnits = units(actual.attachedWorkAmountAtoms);
    attachedWorkProjectionExact =
      attachedWorkAmountUnits !== null &&
      actual.attachedWorkAmountSubatoms == null &&
      Number(actual.attachedWorkAmountDecimals) === WORK_DECIMALS &&
      String(actual.attachedWorkAmountPrecisionModel ?? "") === "" &&
      String(actual.attachedWorkAmountUnitScale ?? "") ===
        WORK_UNIT_SCALE_TEXT &&
      String(actual.attachedWorkAmountVersion ?? "") ===
        TOKEN_SEND_ATOMS_ACTION &&
      String(actual.attachedWorkAmount ?? "") ===
        formatWorkAtoms(attachedWorkAmountUnits);
  } else if (
    attachedWorkAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
  ) {
    attachedWorkAmountUnits = units(actual.attachedWorkAmountSubatoms);
    attachedWorkProjectionExact =
      attachedWorkAmountUnits !== null &&
      actual.attachedWorkAmountAtoms == null &&
      Number(actual.attachedWorkAmountDecimals) ===
        WORK_SUBATOM_DECIMALS &&
      String(actual.attachedWorkAmountPrecisionModel ?? "") ===
        WORK_PRECISION_V2_MODEL &&
      String(actual.attachedWorkAmountUnitScale ?? "") ===
        WORK_SUBATOM_UNIT_SCALE_TEXT &&
      String(actual.attachedWorkAmountVersion ?? "") ===
        TOKEN_SEND_SUBATOMS_ACTION &&
      String(actual.attachedWorkAmount ?? "") ===
        formatWorkSubatoms(attachedWorkAmountUnits);
  }
  const unmatched = Number(actual.attachedWorkUnmatchedActions ?? 0);
  const unvalued = Number(actual.attachedWorkUnvaluedActions ?? 0);
  const marketFlowQ8 =
    (saleFlow + transferFlow + mutationFlow) * BOND_VALUE_Q8_SCALE;
  if (
    confirmedIssuanceUnits === null ||
    directProofIssuanceUnits === null ||
    attachedWorkIssuanceUnits === null ||
    issuanceNetworkValueQ8 === null ||
    issuanceDustQ8 === null ||
    issuanceFloorQ8 === null ||
    attachedAtSendQ8 === null ||
    attachedFrozenQ8 === null ||
    attachedLiveQ8 === null ||
    !attachedWorkProjectionExact ||
    (expectedWorkAmountStorageModel &&
      attachedWorkAmountStorageModel !==
        expectedWorkAmountStorageModel) ||
    confirmedIssuanceUnits !== confirmedSupply ||
    directProofIssuanceUnits !== mintFlow ||
    directProofIssuanceUnits + attachedWorkIssuanceUnits !== confirmedSupply ||
    issuanceNetworkValueQ8 !==
      directProofIssuanceUnits * BOND_VALUE_Q8_SCALE + attachedAtSendQ8 ||
    issuanceDustQ8 !==
      issuanceNetworkValueQ8 -
        confirmedIssuanceUnits * BOND_VALUE_Q8_SCALE ||
    issuanceFloorQ8 !== issuanceNetworkValueQ8 / confirmedIssuanceUnits ||
    attachedFrozenQ8 !== attachedAtSendQ8 ||
    attachedLiveQ8 !== attachedAtSendQ8 ||
    frozenNetworkValueQ8 !== issuanceNetworkValueQ8 + marketFlowQ8 ||
    liveNetworkValueQ8 !== issuanceNetworkValueQ8 + marketFlowQ8 ||
    unmatched !== 0 ||
    unvalued !== 0 ||
    actual.attachmentAccountingModel !== INCEPTION_ATTACHMENT_ACCOUNTING_MODEL ||
    actual.issuanceAccountingModel !== INCEPTION_ISSUANCE_ACCOUNTING_MODEL ||
    actual.networkValueAccountingModel !==
      INCEPTION_NETWORK_VALUE_ACCOUNTING_MODEL ||
    actual.issuanceValuationFixedAtSend !== true ||
    Number(actual.issuanceUnitSats) !== 1
  ) {
    return false;
  }
  if (attachedWorkActions > 0) {
    if (attachedWorkAmountUnits === null || attachedWorkAmountUnits <= 0n) {
      return false;
    }
  } else if (
    attachedWorkAmountUnits !== 0n ||
    attachedAtSendQ8 !== 0n ||
    attachedWorkIssuanceUnits !== 0n
  ) {
    return false;
  }
  return (
    actual.issuanceCheckpointMode === "bond-transaction-provenance" &&
    actual.issuanceValueSnapshotModel === INCEPTION_VALUE_SNAPSHOT_MODEL &&
    actual.issuanceValueSnapshotMode === "canonical-summary-refresh" &&
    Number(actual.issuanceValueSnapshotBlockHeight) ===
      Number(actual.issuanceCheckpointBlockHeight) - 1 &&
    String(actual.issuanceValueSnapshotId ?? "").trim().length > 0 &&
    Number.isFinite(
      Date.parse(String(actual.issuanceValueSnapshotGeneratedAt ?? "")),
    ) &&
    [
      actual.issuanceValueSnapshotBlockHash,
      actual.issuanceValueSnapshotCanonicalSummaryHash,
      actual.issuanceCheckpointBlockHash,
    ].every((hash) => /^[0-9a-f]{64}$/u.test(String(hash ?? "").toLowerCase()))
  );
}

function bondSummaryPayloadHasKnownMainnetValue(
  summary,
  config,
  options = {},
) {
  if (!summary) {
    return false;
  }

  if (
    String(summary.tokenId ?? "").trim().toLowerCase() !== config.tokenId ||
    String(summary.ticker ?? "").trim().toUpperCase() !== config.ticker ||
    normalizePowId(summary.registryId) !== normalizePowId(config.registryId) ||
    !isValidBitcoinAddress(summary.registryAddress, "livenet")
  ) {
    return false;
  }

  if (isBondTokenId(config.tokenId)) {
    return exactBondSummaryPayloadIsCanonical(summary, config, options);
  }

  const token = summary.token;
  const confirmedSupply = Math.max(
    numericValue(summary.stats?.confirmedSupply),
    numericValue(token?.confirmedSupply),
  );
  const confirmedBondActions = Math.max(
    numericValue(summary.stats?.confirmedBondActions),
    numericValue(token?.stats?.confirmedMints),
  );
  const bondMintFlowSats = numericValue(summary.actualValue?.bondMintFlowSats);
  const bondSaleVolumeSats = numericValue(
    summary.actualValue?.bondSaleVolumeSats,
  );
  const bondTransferFeeSats = numericValue(
    summary.actualValue?.bondTransferFeeSats,
  );
  const bondMarketplaceMutationFeeSats = numericValue(
    summary.actualValue?.bondMarketplaceMutationFeeSats,
  );
  const networkValueSats = Math.max(
    numericValue(summary.networkValueSats),
    numericValue(summary.actualValue?.networkValueSats),
  );
  const subProofArithmeticTolerance = (...values) =>
    Math.min(
      0.5,
      Math.max(
        0.01,
        Number.EPSILON *
          Math.max(
            1,
            ...values.map((value) => Math.abs(numericValue(value))),
          ) *
          8,
      ),
    );
  const floorTimesSupplyAgrees = (floorSats, supply, totalSats) => {
    const projectedTotalSats = numericValue(floorSats) * numericValue(supply);
    const expectedTotalSats = numericValue(totalSats);
    return numbersAgree(
      projectedTotalSats,
      expectedTotalSats,
      subProofArithmeticTolerance(projectedTotalSats, expectedTotalSats),
    );
  };
  if (
    options.allowEmptyHistory === true &&
    confirmedSupply === 0 &&
    confirmedBondActions === 0 &&
    bondMintFlowSats === 0 &&
    networkValueSats === 0
  ) {
    return (
      summary.tokenId === config.tokenId &&
      summary.ticker === config.ticker &&
      (config.tokenId !== INCB_TOKEN_ID ||
        summary.actualValue?.networkValueAccountingModel ===
          INCEPTION_NETWORK_VALUE_ACCOUNTING_MODEL) &&
      Array.isArray(summary.chartPoints)
    );
  }
  const hasCurrentInceptionAttachmentContract =
    config.tokenId !== INCB_TOKEN_ID ||
    (summary.actualValue?.attachmentAccountingModel ===
      INCEPTION_ATTACHMENT_ACCOUNTING_MODEL &&
      summary.actualValue?.issuanceAccountingModel ===
        INCEPTION_ISSUANCE_ACCOUNTING_MODEL &&
      summary.actualValue?.networkValueAccountingModel ===
        INCEPTION_NETWORK_VALUE_ACCOUNTING_MODEL &&
      [
        "attachedWorkActions",
        "attachedWorkAmount",
        "attachedWorkFrozenValueSats",
        "attachedWorkIssuanceUnits",
        "attachedWorkLiveFloorAtSendSats",
        "attachedWorkLiveValueSats",
        "attachedWorkLiveValueAtSendSats",
        "attachedWorkUnmatchedActions",
        "attachedWorkUnvaluedActions",
        "baseNetworkValueSats",
        "confirmedIssuanceUnits",
        "directProofIssuanceUnits",
        "frozenFloorSats",
        "frozenNetworkValueSats",
        "issuanceDustSats",
        "issuanceFloorSats",
        "issuanceNetworkValueSats",
        "issuanceUnitSats",
        "issuanceCheckpointBlockHeight",
        "issuanceCheckpointBlockIndex",
        "issuanceValueSnapshotBlockHeight",
        "issuanceValueSnapshotWorkNetworkValueSats",
        "liveFloorSats",
        "liveNetworkValueSats",
      ].every(
        (field) =>
          Object.prototype.hasOwnProperty.call(
            summary.actualValue ?? {},
            field,
          ) && Number.isFinite(Number(summary.actualValue?.[field])),
      ) &&
      summary.actualValue?.issuanceCheckpointMode ===
        "bond-transaction-provenance" &&
      summary.actualValue?.issuanceValuationFixedAtSend === true &&
      Number(summary.actualValue?.issuanceUnitSats) === 1 &&
      summary.actualValue?.issuanceValueSnapshotModel ===
        INCEPTION_VALUE_SNAPSHOT_MODEL &&
      summary.actualValue?.issuanceValueSnapshotMode ===
        "canonical-summary-refresh" &&
      Number(summary.actualValue?.issuanceValueSnapshotBlockHeight) ===
        Number(summary.actualValue?.issuanceCheckpointBlockHeight) - 1 &&
      String(summary.actualValue?.issuanceValueSnapshotId ?? "").trim()
        .length > 0 &&
      Number.isFinite(
        Date.parse(
          String(
            summary.actualValue?.issuanceValueSnapshotGeneratedAt ?? "",
          ),
        ),
      ) &&
      /^[0-9a-f]{64}$/u.test(
        String(
          summary.actualValue?.issuanceValueSnapshotBlockHash ?? "",
        )
          .trim()
          .toLowerCase(),
      ) &&
      /^[0-9a-f]{64}$/u.test(
        String(
          summary.actualValue
            ?.issuanceValueSnapshotCanonicalSummaryHash ?? "",
        )
          .trim()
          .toLowerCase(),
      ) &&
      /^[0-9a-f]{64}$/u.test(
        String(summary.actualValue?.issuanceCheckpointBlockHash ?? "")
          .trim()
          .toLowerCase(),
      ));
  const baseNetworkValueSats = numericValue(
    summary.actualValue?.baseNetworkValueSats,
  );
  const frozenNetworkValueSats = numericValue(
    summary.actualValue?.frozenNetworkValueSats,
  );
  const liveNetworkValueSats = numericValue(
    summary.actualValue?.liveNetworkValueSats,
  );
  const attachedWorkActions = numericValue(
    summary.actualValue?.attachedWorkActions,
  );
  const attachedWorkAmount = numericValue(
    summary.actualValue?.attachedWorkAmount,
  );
  const attachedWorkFrozenValueSats = numericValue(
    summary.actualValue?.attachedWorkFrozenValueSats,
  );
  const attachedWorkLiveValueSats = numericValue(
    summary.actualValue?.attachedWorkLiveValueSats,
  );
  const attachedWorkLiveFloorAtSendSats = numericValue(
    summary.actualValue?.attachedWorkLiveFloorAtSendSats,
  );
  const attachedWorkLiveValueAtSendSats = numericValue(
    summary.actualValue?.attachedWorkLiveValueAtSendSats,
  );
  const attachedWorkIssuanceUnits = numericValue(
    summary.actualValue?.attachedWorkIssuanceUnits,
  );
  const confirmedIssuanceUnits = numericValue(
    summary.actualValue?.confirmedIssuanceUnits,
  );
  const directProofIssuanceUnits = numericValue(
    summary.actualValue?.directProofIssuanceUnits,
  );
  const issuanceNetworkValueSats = numericValue(
    summary.actualValue?.issuanceNetworkValueSats,
  );
  const inceptionMarketFlowSats =
    bondSaleVolumeSats +
    bondTransferFeeSats +
    bondMarketplaceMutationFeeSats;
  const inceptionFixedNetworkValueSats =
    issuanceNetworkValueSats + inceptionMarketFlowSats;
  const inceptionAttachmentValuesAgree =
    config.tokenId !== INCB_TOKEN_ID ||
    (numericValue(summary.actualValue?.attachedWorkUnmatchedActions) === 0 &&
      numericValue(summary.actualValue?.attachedWorkUnvaluedActions) === 0 &&
      numbersAgree(confirmedSupply, confirmedIssuanceUnits, 0.01) &&
      numbersAgree(directProofIssuanceUnits, bondMintFlowSats, 0.01) &&
      directProofIssuanceUnits + attachedWorkIssuanceUnits ===
        confirmedIssuanceUnits &&
      numbersAgree(
        issuanceNetworkValueSats,
        directProofIssuanceUnits + attachedWorkLiveValueAtSendSats,
        subProofArithmeticTolerance(
          issuanceNetworkValueSats,
          directProofIssuanceUnits + attachedWorkLiveValueAtSendSats,
        ),
      ) &&
      numbersAgree(
        numericValue(summary.actualValue?.issuanceDustSats),
        issuanceNetworkValueSats - confirmedIssuanceUnits,
        subProofArithmeticTolerance(
          summary.actualValue?.issuanceDustSats,
          issuanceNetworkValueSats - confirmedIssuanceUnits,
        ),
      ) &&
      floorTimesSupplyAgrees(
        summary.actualValue?.issuanceFloorSats,
        confirmedIssuanceUnits,
        issuanceNetworkValueSats,
      ) &&
      numbersAgree(baseNetworkValueSats, bondMintFlowSats +
        bondSaleVolumeSats + bondTransferFeeSats +
        bondMarketplaceMutationFeeSats, subProofArithmeticTolerance(
          baseNetworkValueSats,
          bondMintFlowSats + bondSaleVolumeSats + bondTransferFeeSats +
            bondMarketplaceMutationFeeSats,
        )) &&
      numbersAgree(
        frozenNetworkValueSats,
        baseNetworkValueSats + attachedWorkLiveValueAtSendSats,
        subProofArithmeticTolerance(
          frozenNetworkValueSats,
          baseNetworkValueSats + attachedWorkLiveValueAtSendSats,
        ),
      ) &&
      numbersAgree(
        attachedWorkFrozenValueSats,
        attachedWorkLiveValueAtSendSats,
        subProofArithmeticTolerance(
          attachedWorkFrozenValueSats,
          attachedWorkLiveValueAtSendSats,
        ),
      ) &&
      numbersAgree(
        attachedWorkLiveValueSats,
        attachedWorkLiveValueAtSendSats,
        subProofArithmeticTolerance(
          attachedWorkLiveValueSats,
          attachedWorkLiveValueAtSendSats,
        ),
      ) &&
      numbersAgree(
        frozenNetworkValueSats,
        inceptionFixedNetworkValueSats,
        subProofArithmeticTolerance(
          frozenNetworkValueSats,
          inceptionFixedNetworkValueSats,
        ),
      ) &&
      numbersAgree(
        liveNetworkValueSats,
        inceptionFixedNetworkValueSats,
        subProofArithmeticTolerance(
          liveNetworkValueSats,
          inceptionFixedNetworkValueSats,
        ),
      ) &&
      numbersAgree(
        networkValueSats,
        liveNetworkValueSats,
        subProofArithmeticTolerance(networkValueSats, liveNetworkValueSats),
      ) &&
      floorTimesSupplyAgrees(
        summary.actualValue?.frozenFloorSats,
        confirmedSupply,
        frozenNetworkValueSats,
      ) &&
      floorTimesSupplyAgrees(
        summary.actualValue?.liveFloorSats,
        confirmedSupply,
        liveNetworkValueSats,
      ) &&
      (attachedWorkActions > 0
        ? attachedWorkAmount > 0 &&
          attachedWorkLiveFloorAtSendSats > 0 &&
          numbersAgree(
            attachedWorkLiveValueAtSendSats,
            attachedWorkAmount * attachedWorkLiveFloorAtSendSats,
            subProofArithmeticTolerance(
              attachedWorkLiveValueAtSendSats,
              attachedWorkAmount * attachedWorkLiveFloorAtSendSats,
            ),
          ) &&
          attachedWorkFrozenValueSats > 0 &&
          attachedWorkLiveValueSats > 0 &&
          attachedWorkIssuanceUnits > 0
        : attachedWorkAmount === 0 &&
          attachedWorkFrozenValueSats === 0 &&
          attachedWorkLiveValueSats === 0 &&
          attachedWorkLiveValueAtSendSats === 0 &&
          attachedWorkIssuanceUnits === 0));
  return (
    finitePositiveNumber(confirmedSupply) &&
    finitePositiveNumber(confirmedBondActions) &&
    finitePositiveNumber(bondMintFlowSats) &&
    finitePositiveNumber(networkValueSats) &&
    networkValueSats >= bondMintFlowSats &&
    hasCurrentInceptionAttachmentContract &&
    inceptionAttachmentValuesAgree &&
    Array.isArray(summary.chartPoints) &&
    summary.chartPoints.length > 0
  );
}

function ledgerPayloadHasFiniteNetworkValues(payload) {
  if (payload?.network !== "livenet") {
    return true;
  }

  return (
    workFloorPayloadHasFiniteNetworkValue(payload?.workFloor) &&
    (!payload?.growthSummary ||
      growthSummaryPayloadHasFiniteNetworkValue(payload.growthSummary))
  );
}

function summaryPayloadHasFiniteNetworkValue(network, key, payload) {
  if (network !== "livenet") {
    return true;
  }

  if (key === "workFloor") {
    return workFloorPayloadHasFiniteNetworkValue(payload);
  }
  if (key === "workSummary") {
    return workFloorPayloadHasFiniteNetworkValue(payload?.floor);
  }
  if (key === "growthSummary") {
    return growthSummaryPayloadHasFiniteNetworkValue(payload);
  }
  if (key === "marketplaceSummary") {
    return workFloorPayloadHasFiniteNetworkValue(payload?.workFloor);
  }
  if (key === "infinitySummary") {
    return infinitySummaryPayloadHasKnownMainnetValue(payload);
  }
  if (key === "inceptionSummary") {
    return inceptionSummaryPayloadHasKnownMainnetValue(payload);
  }

  return true;
}

function summaryKeyRequiresCanonicalLedger(network, key) {
  return (
    network === "livenet" &&
    new Set([
      "growthSummary",
      "inceptionSummary",
      "infinitySummary",
      "marketplaceSummary",
      "workFloor",
      "workSummary",
    ]).has(key)
  );
}

function tokenPayloadHasKnownMainnetHistory(payload, scope = "") {
  const tokenScope = normalizeTokenScope(scope);
  const tokens = Array.isArray(payload?.tokens) ? payload.tokens : [];
  const mints = Array.isArray(payload?.mints) ? payload.mints : [];
  const transfers = Array.isArray(payload?.transfers) ? payload.transfers : [];
  const listings = Array.isArray(payload?.listings) ? payload.listings : [];
  const sales = Array.isArray(payload?.sales) ? payload.sales : [];
  const holders = Array.isArray(payload?.holders) ? payload.holders : [];
  const stats = payload?.stats && typeof payload.stats === "object"
    ? payload.stats
    : {};
  const confirmedTokens = Math.max(
    numericValue(stats.confirmedTokens),
    tokens.filter((token) => token?.confirmed !== false).length,
  );
  const confirmedMints = Math.max(
    numericValue(stats.confirmedMints),
    mints.filter((mint) => mint?.confirmed !== false).length,
  );
  const confirmedSupply = Math.max(
    numericValue(payload?.confirmedSupply),
    tokens.reduce((total, token) => total + numericValue(token.confirmedSupply), 0),
  );
  const exactBondSupply = BOND_TOKEN_IDS.has(tokenScope)
    ? maxIntegerTexts(
        canonicalIntegerText(payload?.confirmedSupply, { allowZero: true }) ||
          "0",
        tokens.reduce(
          (total, token) =>
            addIntegerTexts(
              total,
              canonicalIntegerText(token?.confirmedSupply, {
                allowZero: true,
              }) || "0",
            ),
          "0",
        ),
      )
    : "0";

  if (!tokenScope) {
    return confirmedTokens > 0 || tokens.length > 0;
  }

  if (tokenScope === WORK_TOKEN_ID) {
    return (
      confirmedSupply > 0 ||
      confirmedMints > 0 ||
      holders.length > 0 ||
      transfers.length > 0 ||
      listings.length > 0 ||
      sales.length > 0
    );
  }

  if (BOND_TOKEN_IDS.has(tokenScope)) {
    const bondConfig = bondConfigForTokenId(tokenScope);
    const hasCanonicalEmptyDefinition =
      bondConfig?.tokenId === INCB_TOKEN_ID &&
      tokens.some(
        (token) =>
          token?.tokenId === bondConfig.tokenId &&
          String(token?.ticker ?? "").trim().toUpperCase() ===
            bondConfig.ticker &&
          token?.confirmed !== false &&
          isValidBitcoinAddress(token?.registryAddress, "livenet"),
      );
    return (
      hasCanonicalEmptyDefinition ||
      BigInt(exactBondSupply) > 0n ||
      confirmedMints > 0 ||
      holders.length > 0 ||
      transfers.length > 0 ||
      listings.length > 0 ||
      sales.length > 0
    );
  }

  return true;
}

function rejectEmptyMainnetTokenPayload(network, payload, scope, label) {
  if (network !== "livenet") {
    return false;
  }
  if (tokenPayloadHasKnownMainnetHistory(payload, scope)) {
    return false;
  }
  console.error(
    `Rejected empty proof-index ${label} read for ${scope || "all"} on livenet.`,
  );
  return true;
}

function rejectEmptyBondTokenPayload(network, payload, config, label) {
  const hasSyntheticDefinition = (Array.isArray(payload?.tokens)
    ? payload.tokens
    : []
  ).some((token) => token?.tokenId === config.tokenId);
  if (
    config.tokenId === INCB_TOKEN_ID &&
    hasSyntheticDefinition &&
    (canonicalIntegerText(payload?.confirmedSupply, { allowZero: true }) ||
      "0") === "0"
  ) {
    return false;
  }
  return rejectEmptyMainnetTokenPayload(
    network,
    payload,
    config.tokenId,
    label,
  );
}

function sourceCollectionFingerprint(items) {
  const list = Array.isArray(items) ? items : [];
  const confirmed = list.filter((item) => item?.confirmed).length;
  const newest = list.reduce((max, item) => {
    const time = Date.parse(item?.createdAt ?? "");
    return Number.isFinite(time) ? Math.max(max, time) : max;
  }, 0);
  const sample = list
    .slice(0, 8)
    .map(
      (item) =>
        item?.txid ??
        item?.listingId ??
        item?.closedTxid ??
        item?.id ??
        "",
    )
    .filter(Boolean);

  return {
    confirmed,
    count: list.length,
    newest,
    sample,
  };
}

function ledgerSourceHashes({
  activityState,
  registryState,
  seededMailActivityState,
  tokenState,
  workTokenState,
}) {
  return {
    activity: sourceCollectionFingerprint(activityState?.activity),
    registry: sourceCollectionFingerprint(registryState?.activity),
    registryRecords: sourceCollectionFingerprint(registryState?.records),
    seededMail: sourceCollectionFingerprint(seededMailActivityState?.activity),
    tokenMints: sourceCollectionFingerprint(tokenState?.mints),
    tokenSales: sourceCollectionFingerprint(tokenState?.sales),
    tokenInvalidEvents: sourceCollectionFingerprint(tokenState?.invalidEvents),
    tokenTransfers: sourceCollectionFingerprint(tokenState?.transfers),
    tokens: sourceCollectionFingerprint(tokenState?.tokens),
    workInvalidEvents: sourceCollectionFingerprint(workTokenState?.invalidEvents),
    workMints: sourceCollectionFingerprint(workTokenState?.mints),
    workSales: sourceCollectionFingerprint(workTokenState?.sales),
    workTransfers: sourceCollectionFingerprint(workTokenState?.transfers),
  };
}

function ledgerMetricsFromState({
  activity,
  registryState,
  tokenState,
  workFloor,
}) {
  const tokenDefinitions = tokenState?.tokens ?? [];
  const tokenMints = tokenState?.mints ?? [];
  const tokenTransfers = tokenState?.transfers ?? [];
  const tokenSales = tokenState?.sales ?? [];
  const workFloorConfirmedComputerActions = Number(
    workFloor?.stats?.confirmedComputerActions,
  );
  const confirmedComputerActions =
    Number.isSafeInteger(workFloorConfirmedComputerActions) &&
    workFloorConfirmedComputerActions >= 0
      ? workFloorConfirmedComputerActions
      : (Array.isArray(activity) ? activity : []).filter(
          (item) => item?.confirmed && item?.valid !== false,
        ).length;

  return {
    activityItems: Array.isArray(activity) ? activity.length : 0,
    confirmedComputerActions,
    confirmedTokenMints:
      workFloor?.stats?.confirmedTokenMints ?? confirmedItemCount(tokenMints),
    confirmedTokenSales: confirmedItemCount(tokenSales),
    confirmedTokenTransfers: confirmedItemCount(tokenTransfers),
    confirmedTokens:
      workFloor?.stats?.confirmedTokens ?? confirmedItemCount(tokenDefinitions),
    invalidTokenEvents: confirmedItemCount(tokenState?.invalidEvents),
    indexedThroughBlock: indexedThroughBlockFromItems(activity ?? []),
    networkValueSats: numericValue(
      workFloor?.networkValueSats ?? workFloor?.actualValue?.totalSats,
    ),
    powids: registryConfirmedCount(registryState),
  };
}

function ledgerPayloadLooksWorse(nextPayload, previousPayload) {
  if (!previousPayload?.metrics) {
    return false;
  }

  const next = nextPayload?.metrics ?? {};
  const previous = previousPayload.metrics;
  const guardedKeys = [
    "powids",
    "confirmedTokenMints",
    "confirmedTokenSales",
    "confirmedTokenTransfers",
    "confirmedTokens",
    "confirmedComputerActions",
  ];
  const hasPreviousHistory = guardedKeys.some(
    (key) => numericValue(previous[key]) > 0,
  );
  if (!hasPreviousHistory) {
    return false;
  }

  const nextNetworkValue = numericValue(next.networkValueSats);
  const previousNetworkValue = numericValue(previous.networkValueSats);
  if (nextNetworkValue + 1 < previousNetworkValue) {
    return true;
  }

  const countRegression = guardedKeys.some(
    (key) => numericValue(next[key]) < numericValue(previous[key]),
  );
  if (!countRegression) {
    return false;
  }

  const countGain = guardedKeys.some(
    (key) => numericValue(next[key]) > numericValue(previous[key]),
  );
  return !(
    nextPayload?.consistency?.ok === true &&
    countGain &&
    nextNetworkValue > previousNetworkValue + 1
  );
}

function ledgerPayloadHasCurrentChecks(payload) {
  const checks = payload?.consistency?.checks ?? [];
  const checkNames = new Set(checks.map((check) => check?.name));
  return (
    Boolean(payload?.snapshotId) &&
    payload?.consistency?.ok === true &&
    payload?.consistency?.status !== "summary-snapshot-fallback" &&
    checks.every((check) => check?.ok === true) &&
    ledgerPayloadHasFiniteNetworkValues(payload) &&
    checkNames.has("livenet-confirmed-history-present") &&
    checkNames.has("token-definitions-cover-confirmed-mints") &&
    checkNames.has("token-components-cover-confirmed-activity") &&
    checkNames.has("canonical-activity-count-matches-public-log") &&
    checkNames.has("network-values-finite") &&
    checkNames.has("marketplace-mutation-fees-counted") &&
    checkNames.has("marketplace-value-includes-mutation-fees") &&
    checkNames.has("work-amo-v5-legacy-bootstrap-carry-proven") &&
    checkNames.has("credit-frozen-value-includes-event-components") &&
    checkNames.has("credit-live-value-is-active-network-value") &&
    checkNames.has("computer-event-flow-excludes-marketplace") &&
    checkNames.has("token-sales-logged") &&
    checkNames.has("seeded-mail-events-logged") &&
    checkNames.has("seeded-inception-bonds-logged") &&
    checkNames.has("seeded-infinity-bonds-logged") &&
    checkNames.has("inception-live-issuance-matches-incb-supply") &&
    checkNames.has("inception-fixed-value-reconciles") &&
    checkNames.has("infinity-bond-flow-matches-powb-supply") &&
    checkNames.has("ledger-covers-node-tip")
  );
}

function ledgerPayloadIsUsableFallback(payload) {
  return Boolean(
    payload?.network &&
      payload?.generatedAt &&
      payload?.registryState &&
      payload?.tokenState &&
      payload?.workFloor &&
      ledgerPayloadHasFiniteNetworkValues(payload),
  );
}

function ledgerPayloadAgeMs(payload, now = Date.now()) {
  const generatedAt = Date.parse(payload?.generatedAt ?? "");
  return Number.isFinite(generatedAt) ? Math.max(0, now - generatedAt) : Infinity;
}

function ledgerPayloadIndexedThroughBlock(payload) {
  const height = Math.max(
    Number(payload?.metrics?.indexedThroughBlock) || 0,
    Number(payload?.indexedThroughBlock) || 0,
  );
  return Number.isSafeInteger(height) && height > 0 ? height : 0;
}

function ledgerPayloadTipStatus(payload, tipHeight) {
  const indexedThroughBlock = ledgerPayloadIndexedThroughBlock(payload);
  const normalizedTipHeight = Number(tipHeight);
  if (!Number.isSafeInteger(normalizedTipHeight) || normalizedTipHeight <= 0) {
    return {
      coversTip: true,
      indexedThroughBlock,
      lagBlocks: 0,
      tipHeight: null,
    };
  }

  const lagBlocks =
    indexedThroughBlock > 0
      ? Math.max(0, normalizedTipHeight - indexedThroughBlock)
      : Number.POSITIVE_INFINITY;
  return {
    coversTip:
      indexedThroughBlock > 0 &&
      lagBlocks <= PROOF_INDEX_CONFIRMED_READ_MAX_LAG_BLOCKS,
    indexedThroughBlock,
    lagBlocks,
    tipHeight: normalizedTipHeight,
  };
}

function growthDeltaForProofIndexEvents(events) {
  const delta = {
    browserFlowSats: 0,
    browserSats: 0,
    computerEventFlowSats: 0,
    computerEventSats: 0,
    driveFlowSats: 0,
    driveSats: 0,
    idMarketplaceFeeSats: 0,
    idMarketplaceVolumeSats: 0,
    inceptionBondFlowSats: 0,
    inceptionBondSats: 0,
    infinityBondFlowSats: 0,
    infinityBondSats: 0,
    mailFlowSats: 0,
    mailSats: 0,
    marketplaceFeeSats: 0,
    marketplaceFlowSats: 0,
    marketplaceMutationFeeSats: 0,
    marketplaceSaleVolumeSats: 0,
    marketplaceSats: 0,
    marketplaceVolumeSats: 0,
    tokenCreationFlowSats: 0,
    tokenMarketplaceFeeSats: 0,
    tokenMintFlowSats: 0,
    tokenSaleFlowSats: 0,
    tokenSaleVolumeSats: 0,
    tokenSats: 0,
    tokenTransferFlowSats: 0,
    totalSats: 0,
    walletFlowSats: 0,
    walletSats: 0,
  };
  const addScaled = (flowKey, satsKey, sats) => {
    delta[flowKey] += sats;
    delta[satsKey] += sats * GROWTH_MODEL_INPUTS.valueMultiple;
    delta.totalSats += sats * GROWTH_MODEL_INPUTS.valueMultiple;
  };
  const countedMarketplaceMutationEvents = new Set(
    uniqueMarketplaceMutationActivity(
      events,
      MARKETPLACE_MUTATION_KINDS,
    ),
  );

  for (const event of Array.isArray(events) ? events : []) {
    const kind = String(event?.kind ?? "");
    if (BOOST_EVENT_KINDS.has(kind)) {
      continue;
    }
    if (
      MARKETPLACE_MUTATION_KINDS.has(kind) &&
      !countedMarketplaceMutationEvents.has(event)
    ) {
      continue;
    }
    const sats = MARKETPLACE_MUTATION_KINDS.has(kind)
      ? marketplaceMutationPaymentSats(event)
      : numericValue(event?.totalSats);
    if (sats <= 0) {
      continue;
    }

    if (kind === "mail" || kind === "reply") {
      addScaled("mailFlowSats", "mailSats", sats);
    } else if (kind === "file") {
      addScaled("driveFlowSats", "driveSats", sats);
    } else if (kind === INFINITY_BOND_KIND) {
      addScaled("infinityBondFlowSats", "infinityBondSats", sats);
    } else if (kind === INCEPTION_BOND_KIND) {
      addScaled("inceptionBondFlowSats", "inceptionBondSats", sats);
    } else if (ID_MARKETPLACE_MUTATION_KINDS.has(kind)) {
      delta.idMarketplaceFeeSats += sats;
      delta.marketplaceFeeSats += sats;
      delta.marketplaceMutationFeeSats += sats;
      delta.marketplaceFlowSats += sats;
      delta.marketplaceSats += sats * GROWTH_MODEL_INPUTS.valueMultiple;
      delta.totalSats += sats * GROWTH_MODEL_INPUTS.valueMultiple;
    } else if (TOKEN_MARKETPLACE_MUTATION_KINDS.has(kind)) {
      delta.tokenMarketplaceFeeSats += sats;
      delta.marketplaceFeeSats += sats;
      delta.marketplaceMutationFeeSats += sats;
      delta.marketplaceFlowSats += sats;
      delta.marketplaceSats += sats * GROWTH_MODEL_INPUTS.valueMultiple;
      delta.totalSats += sats * GROWTH_MODEL_INPUTS.valueMultiple;
    } else if (kind === "token-create") {
      addScaled("tokenCreationFlowSats", "tokenSats", sats);
    } else if (kind === "token-mint") {
      addScaled("tokenMintFlowSats", "tokenSats", sats);
    } else if (kind === "token-transfer") {
      delta.tokenTransferFlowSats += sats;
      delta.walletFlowSats += sats;
      delta.walletSats += sats * GROWTH_MODEL_INPUTS.valueMultiple;
      delta.totalSats += sats * GROWTH_MODEL_INPUTS.valueMultiple;
    } else if (kind === "token-sale") {
      delta.tokenSaleFlowSats += sats;
      delta.tokenSaleVolumeSats += sats;
      delta.marketplaceSaleVolumeSats += sats;
      delta.marketplaceVolumeSats += sats;
      delta.marketplaceFlowSats += sats;
      delta.marketplaceSats += sats * GROWTH_MODEL_INPUTS.valueMultiple;
      delta.totalSats += sats * GROWTH_MODEL_INPUTS.valueMultiple;
    } else {
      addScaled("computerEventFlowSats", "computerEventSats", sats);
    }
  }

  return delta;
}

function exactWorkNetworkQ8State(actualValue) {
  const actual =
    actualValue && typeof actualValue === "object" && !Array.isArray(actualValue)
      ? actualValue
      : {};
  if (
    ![
      WORK_NETWORK_VALUE_ACCOUNTING_MODEL,
      "canonical-work-amo-v5-network-accumulator-v1",
    ].includes(actual.workNetworkValueAccountingModel)
  ) {
    return null;
  }
  const q8 = (field) => {
    const text = canonicalNonNegativeIntegerText(actual[field]);
    return text ? BigInt(text) : null;
  };
  const base = q8("baseNetworkValueQ8");
  const baseTotal = q8("baseTotalQ8");
  const frozen = q8("frozenNetworkValueQ8");
  const frozenTotal = q8("frozenTotalQ8");
  const live = q8("liveNetworkValueQ8");
  const liveTotal = q8("liveTotalQ8");
  const network = q8("networkValueQ8");
  const total = q8("totalQ8");
  const floor = q8("floorQ8");
  const frozenFloor = q8("frozenFloorQ8");
  const liveFloor = q8("liveFloorQ8");
  if (
    base === null ||
    baseTotal !== base ||
    frozen === null ||
    frozenTotal !== frozen ||
    live === null ||
    liveTotal !== live ||
    network !== live ||
    total !== live ||
    floor === null ||
    liveFloor !== floor ||
    frozenFloor === null ||
    floor !== live / BigInt(WORK_TOKEN_MAX_SUPPLY) ||
    frozenFloor !== frozen / BigInt(WORK_TOKEN_MAX_SUPPLY)
  ) {
    return null;
  }
  const aliases = [
    ["baseNetworkValueSats", base],
    ["baseTotalSats", base],
    ["floorSats", floor],
    ["frozenFloorSats", frozenFloor],
    ["frozenNetworkValueSats", frozen],
    ["frozenTotalSats", frozen],
    ["liveFloorSats", floor],
    ["liveNetworkValueSats", live],
    ["liveTotalSats", live],
    ["networkValueSats", live],
    ["totalSats", live],
  ];
  if (
    aliases.some(
      ([field, value]) =>
        typeof actual[field] !== "string" ||
        actual[field] !== q8ToCanonicalDecimal(value),
    )
  ) {
    return null;
  }
  return { base, frozen, live };
}

function actualValueWithExactWorkNetworkQ8(actualValue, state) {
  const actual = { ...(actualValue ?? {}) };
  const base = state.base;
  const frozen = state.frozen;
  const live = state.live;
  const floor = live / BigInt(WORK_TOKEN_MAX_SUPPLY);
  const frozenFloor = frozen / BigInt(WORK_TOKEN_MAX_SUPPLY);
  return {
    ...actual,
    workNetworkValueAccountingModel: WORK_NETWORK_VALUE_ACCOUNTING_MODEL,
    baseNetworkValueQ8: base.toString(),
    baseNetworkValueSats: q8ToCanonicalDecimal(base),
    baseNetworkValueSatsApproximate: q8ToNumber(base),
    baseNetworkValueSatsExact: q8ToCanonicalDecimal(base),
    baseTotalQ8: base.toString(),
    baseTotalSats: q8ToCanonicalDecimal(base),
    baseTotalSatsApproximate: q8ToNumber(base),
    baseTotalSatsExact: q8ToCanonicalDecimal(base),
    floorQ8: floor.toString(),
    floorSats: q8ToCanonicalDecimal(floor),
    floorSatsApproximate: q8ToNumber(floor),
    floorSatsExact: q8ToCanonicalDecimal(floor),
    frozenFloorQ8: frozenFloor.toString(),
    frozenFloorSats: q8ToCanonicalDecimal(frozenFloor),
    frozenFloorSatsApproximate: q8ToNumber(frozenFloor),
    frozenFloorSatsExact: q8ToCanonicalDecimal(frozenFloor),
    frozenNetworkValueQ8: frozen.toString(),
    frozenNetworkValueSats: q8ToCanonicalDecimal(frozen),
    frozenNetworkValueSatsApproximate: q8ToNumber(frozen),
    frozenNetworkValueSatsExact: q8ToCanonicalDecimal(frozen),
    frozenTotalQ8: frozen.toString(),
    frozenTotalSats: q8ToCanonicalDecimal(frozen),
    frozenTotalSatsApproximate: q8ToNumber(frozen),
    frozenTotalSatsExact: q8ToCanonicalDecimal(frozen),
    liveFloorQ8: floor.toString(),
    liveFloorSats: q8ToCanonicalDecimal(floor),
    liveFloorSatsApproximate: q8ToNumber(floor),
    liveFloorSatsExact: q8ToCanonicalDecimal(floor),
    liveNetworkValueQ8: live.toString(),
    liveNetworkValueSats: q8ToCanonicalDecimal(live),
    liveNetworkValueSatsApproximate: q8ToNumber(live),
    liveNetworkValueSatsExact: q8ToCanonicalDecimal(live),
    liveTotalQ8: live.toString(),
    liveTotalSats: q8ToCanonicalDecimal(live),
    liveTotalSatsApproximate: q8ToNumber(live),
    liveTotalSatsExact: q8ToCanonicalDecimal(live),
    networkValueQ8: live.toString(),
    networkValueSats: q8ToCanonicalDecimal(live),
    networkValueSatsApproximate: q8ToNumber(live),
    networkValueSatsExact: q8ToCanonicalDecimal(live),
    totalQ8: live.toString(),
    totalSats: q8ToCanonicalDecimal(live),
    totalSatsApproximate: q8ToNumber(live),
    totalSatsExact: q8ToCanonicalDecimal(live),
  };
}

function exactWorkFloorNetworkQ8State(workFloor) {
  const floor =
    workFloor && typeof workFloor === "object" && !Array.isArray(workFloor)
      ? workFloor
      : {};
  const state = exactWorkNetworkQ8State(floor.actualValue);
  if (
    !state ||
    ![
      WORK_NETWORK_VALUE_ACCOUNTING_MODEL,
      "canonical-work-amo-v5-network-accumulator-v1",
    ].includes(floor.workNetworkValueAccountingModel)
  ) {
    return null;
  }
  const expected = {
    baseNetworkValueQ8: state.base,
    baseTotalQ8: state.base,
    floorQ8: state.live / BigInt(WORK_TOKEN_MAX_SUPPLY),
    frozenFloorQ8: state.frozen / BigInt(WORK_TOKEN_MAX_SUPPLY),
    frozenNetworkValueQ8: state.frozen,
    frozenTotalQ8: state.frozen,
    liveFloorQ8: state.live / BigInt(WORK_TOKEN_MAX_SUPPLY),
    liveNetworkValueQ8: state.live,
    liveTotalQ8: state.live,
    networkValueQ8: state.live,
    totalQ8: state.live,
  };
  for (const [field, value] of Object.entries(expected)) {
    const text = canonicalNonNegativeIntegerText(floor[field]);
    if (!text || BigInt(text) !== value) {
      return null;
    }
  }
  const aliases = [
    ["baseNetworkValueSats", state.base],
    ["baseTotalSats", state.base],
    ["floorSats", expected.floorQ8],
    ["frozenFloorSats", expected.frozenFloorQ8],
    ["frozenNetworkValueSats", state.frozen],
    ["frozenTotalSats", state.frozen],
    ["liveFloorSats", expected.liveFloorQ8],
    ["liveNetworkValueSats", state.live],
    ["liveTotalSats", state.live],
    ["networkValueSats", state.live],
    ["totalSats", state.live],
  ];
  return aliases.every(
    ([field, value]) =>
      typeof floor[field] === "string" &&
      floor[field] === q8ToCanonicalDecimal(value),
  )
    ? state
    : null;
}

function workFloorWithExactWorkNetworkQ8(workFloor, actualValue) {
  const state = exactWorkNetworkQ8State(actualValue);
  if (!state) {
    return null;
  }
  const exactActual = actualValueWithExactWorkNetworkQ8(actualValue, state);
  const exactTop = actualValueWithExactWorkNetworkQ8(workFloor, state);
  return {
    ...exactTop,
    actualValue: exactActual,
  };
}

function actualValueWithProofIndexDelta(actualValue, delta) {
  const exact = exactWorkNetworkQ8State(actualValue);
  const deltaTotalSats = integerBigInt(delta?.totalSats, {
    allowZero: false,
  });
  if (!exact || deltaTotalSats === null) {
    return null;
  }
  const actual = { ...(actualValue ?? {}) };
  for (const [key, value] of Object.entries(delta)) {
    if (key === "totalSats" || value === 0) {
      continue;
    }
    actual[key] = numericValue(actual[key]) + value;
  }
  const deltaQ8 = deltaTotalSats * VALUE_Q8_SCALE;
  return actualValueWithExactWorkNetworkQ8(actual, {
    base: exact.base + deltaQ8,
    frozen: exact.frozen + deltaQ8,
    live: exact.live + deltaQ8,
  });
}

function workFloorWithProofIndexEventDelta(workFloor, deltaPayload) {
  if (!workFloor) {
    return workFloor;
  }
  const indexedThroughBlock = Math.max(
    Number(workFloor.indexedThroughBlock) || 0,
    Number(deltaPayload.indexedThroughBlock) || 0,
    Number(deltaPayload.maxEventBlock) || 0,
  );
  const coveredWorkFloor = {
    ...workFloor,
    indexedAt: newerIso(workFloor.indexedAt, deltaPayload.indexedAt),
    indexedThroughBlock,
    source: mergedSourceLabel(workFloor.source, deltaPayload.source),
    stats: {
      ...(workFloor.stats ?? {}),
      confirmedComputerActions:
        numericValue(workFloor.stats?.confirmedComputerActions) +
        numericValue(deltaPayload.totalCount),
      indexedThroughBlock,
    },
  };
  if (numericValue(deltaPayload?.totalSats) <= 0) {
    return coveredWorkFloor;
  }

  const delta = growthDeltaForProofIndexEvents(deltaPayload.events);
  if (numericValue(delta.totalSats) <= 0) {
    return coveredWorkFloor;
  }
  if (!exactWorkFloorNetworkQ8State(workFloor)) {
    return workFloor;
  }
  const actualValue = actualValueWithProofIndexDelta(
    workFloor.actualValue,
    delta,
  );
  return actualValue
    ? workFloorWithExactWorkNetworkQ8(coveredWorkFloor, actualValue) ?? workFloor
    : workFloor;
}

function growthSummaryWithProofIndexEventDelta(growthSummary, deltaPayload) {
  if (!growthSummary) {
    return growthSummary;
  }
  const coveredWorkFloor = growthSummary.workFloor
    ? workFloorWithProofIndexEventDelta(growthSummary.workFloor, deltaPayload)
    : growthSummary.workFloor;
  const indexedThroughBlock = Math.max(
    Number(growthSummary.indexedThroughBlock) || 0,
    Number(coveredWorkFloor?.indexedThroughBlock) || 0,
    Number(deltaPayload.indexedThroughBlock) || 0,
    Number(deltaPayload.maxEventBlock) || 0,
  );
  const coveredGrowthSummary = {
    ...growthSummary,
    indexedAt: newerIso(growthSummary.indexedAt, deltaPayload.indexedAt),
    indexedThroughBlock,
    source: mergedSourceLabel(growthSummary.source, deltaPayload.source),
    workFloor: coveredWorkFloor,
  };
  if (numericValue(deltaPayload?.totalSats) <= 0) {
    return coveredWorkFloor
      ? growthSummaryWithCanonicalWorkFloor(coveredGrowthSummary, coveredWorkFloor)
      : coveredGrowthSummary;
  }

  const delta = growthDeltaForProofIndexEvents(deltaPayload.events);
  if (numericValue(delta.totalSats) <= 0) {
    return coveredWorkFloor
      ? growthSummaryWithCanonicalWorkFloor(coveredGrowthSummary, coveredWorkFloor)
      : coveredGrowthSummary;
  }
  const actualValue = actualValueWithProofIndexDelta(
    growthSummary.actualValue,
    delta,
  );
  if (!actualValue) {
    return growthSummary;
  }
  const state = exactWorkNetworkQ8State(actualValue);
  if (!state) {
    return growthSummary;
  }
  const nextGrowthSummary = {
    ...actualValueWithExactWorkNetworkQ8(coveredGrowthSummary, state),
    actualValue,
    workFloor: coveredWorkFloor,
  };
  return coveredWorkFloor
    ? growthSummaryWithCanonicalWorkFloor(nextGrowthSummary, coveredWorkFloor)
    : nextGrowthSummary;
}

async function proofIndexSummaryPayloadWithValueEventDelta(
  payload,
  network,
  key,
  label,
) {
  if (network !== "livenet" || !payload) {
    return null;
  }

  const indexedThroughBlock = proofIndexPayloadIndexedThroughBlock(payload);
  if (!indexedThroughBlock) {
    return null;
  }

  const deltaPayload = await proofIndexConfirmedValueEventsAfterBlock(
    network,
    indexedThroughBlock,
  ).catch((error) => {
    console.error(
      `Proof index summary value-event delta read failed for ${label}: ${errorSummary(error)}`,
    );
    return null;
  });
  if (
    !deltaPayload ||
    !(await proofIndexPayloadCoversConfirmedTip(
      deltaPayload,
      network,
      `${label} summary value-event delta`,
    ))
  ) {
    return null;
  }

  const deltaEvents = Array.isArray(deltaPayload.events)
    ? deltaPayload.events
    : [];
  const hasValueDelta =
    numericValue(deltaPayload.totalCount) > 0 &&
    numericValue(deltaPayload.totalSats) > 0;
  let nextPayload = payload;
  if (key === "workSummary") {
    nextPayload = {
      ...payload,
      floor: workFloorWithProofIndexEventDelta(payload.floor, deltaPayload),
    };
  } else if (key === "growthSummary") {
    nextPayload = growthSummaryWithProofIndexEventDelta(payload, deltaPayload);
  } else if (key === "marketplaceSummary") {
    nextPayload = {
      ...payload,
      workFloor: workFloorWithProofIndexEventDelta(
        payload.workFloor,
        deltaPayload,
      ),
    };
  } else if (
    hasValueDelta &&
    BOND_TOKEN_CONFIGS.some(
      (config) =>
        key === config.summaryKey &&
        deltaEvents.some(
          (event) => String(event?.kind ?? "") === config.kind,
        ),
    )
  ) {
    console.error(
      `Rejected ${label} summary value-event delta: bond events require a refreshed bond summary snapshot.`,
    );
    return null;
  }

  const deltaIndexedThroughBlock = proofIndexPayloadIndexedThroughBlock(
    deltaPayload,
  );
  const mergedIndexedThroughBlock = Math.max(
    proofIndexPayloadIndexedThroughBlock(nextPayload),
    deltaIndexedThroughBlock,
    Number(deltaPayload.maxEventBlock) || 0,
  );
  console.error(
    `Accepted ${label}: summary snapshot block ${indexedThroughBlock} is covered by proof-index scan block ${mergedIndexedThroughBlock}.`,
  );
  return {
    ...nextPayload,
    indexedAt: newerIso(nextPayload.indexedAt, deltaPayload.indexedAt),
    indexedThroughBlock: mergedIndexedThroughBlock,
    source: mergedSourceLabel(nextPayload.source, deltaPayload.source),
  };
}

async function ledgerWithProofIndexEventDelta(ledger, network, label) {
  if (network !== "livenet" || !ledgerPayloadIsUsableFallback(ledger)) {
    return null;
  }
  const ledgerBlock = ledgerPayloadIndexedThroughBlock(ledger);
  if (!ledgerBlock) {
    return null;
  }
  const deltaPayload = await proofIndexConfirmedValueEventsAfterBlock(
    network,
    ledgerBlock,
  ).catch((error) => {
    console.error(
      `Proof index value-event delta read failed for ${label}: ${errorSummary(error)}`,
    );
    return null;
  });
  if (!deltaPayload || numericValue(deltaPayload.totalCount) <= 0) {
    return null;
  }
  const hasCreditTokenDelta = (Array.isArray(deltaPayload.events)
    ? deltaPayload.events
    : []
  ).some((event) => String(event?.kind ?? "").startsWith("token-"));
  if (hasCreditTokenDelta) {
    console.error(
      `Rejected ${label} proof-index value-event delta: credit events require canonical value replay.`,
    );
    return null;
  }
  if (
    !(await proofIndexPayloadCoversConfirmedTip(
      deltaPayload,
      network,
      `${label} value-event delta`,
    ))
  ) {
    return null;
  }

  const workFloor = workFloorWithProofIndexEventDelta(
    ledger.workFloor,
    deltaPayload,
  );
  const growthSummary = growthSummaryWithCanonicalWorkFloor(
    growthSummaryWithProofIndexEventDelta(ledger.growthSummary, deltaPayload),
    workFloor,
  );
  const indexedThroughBlock = Math.max(
    ledgerPayloadIndexedThroughBlock(ledger),
    Number(deltaPayload.maxEventBlock) || 0,
  );
  console.error(
    `Accepted ${label}: applied ${deltaPayload.totalCount} proof-index events after ledger block ${ledgerBlock} through block ${indexedThroughBlock}.`,
  );
  return {
    ...ledger,
    generatedAt: newerIso(ledger.generatedAt, deltaPayload.indexedAt),
    growthSummary,
    indexedThroughBlock,
    metrics: {
      ...(ledger.metrics ?? {}),
      indexedThroughBlock,
    },
    source: mergedSourceLabel(ledger.source, deltaPayload.source),
    workFloor,
  };
}

function proofIndexPayloadIndexedThroughBlock(payload) {
  const height = Math.max(
    Number(payload?.indexedThroughBlock) || 0,
    Number(payload?.metrics?.indexedThroughBlock) || 0,
    Number(payload?.stats?.indexedThroughBlock) || 0,
    Number(payload?.token?.indexedThroughBlock) || 0,
    Number(payload?.workFloor?.indexedThroughBlock) || 0,
  );
  return Number.isSafeInteger(height) && height > 0 ? height : 0;
}

async function ledgerTipHeight(network) {
  const now = Date.now();
  const cacheKey = network;
  const cached = LEDGER_TIP_HEIGHT_CACHE.get(cacheKey);
  if (cached && now - cached.fetchedAtMs < LEDGER_TIP_CACHE_TTL_MS) {
    return cached.tipHeight;
  }

  try {
    const tip = await fetchText(`${mempoolBase(network)}/api/blocks/tip/height`, {
      signal: AbortSignal.timeout(LEDGER_TIP_FETCH_TIMEOUT_MS),
    });
    const height = Number(tip);
    if (Number.isSafeInteger(height) && height > 0) {
      LEDGER_TIP_HEIGHT_CACHE.set(cacheKey, {
        fetchedAtMs: now,
        tipHeight: height,
      });
      return height;
    }
  } catch {
    // A timed-out tip check should fail open for read-model freshness, matching
    // the previous null-tip behavior while avoiding request hangs.
  }
  return null;
}

async function ledgerPayloadCoversTip(payload, network) {
  if (network !== "livenet") {
    return true;
  }
  const tipHeight = await healthNodeTipHeight();
  return ledgerPayloadTipStatus(payload, tipHeight).coversTip;
}

function ledgerWithProofIndexScanFloor(ledger, scan, tipHeight) {
  if (!ledger || !scan) {
    return ledger;
  }

  const scanBlock = Number(scan.indexedThroughBlock) || 0;
  const indexedThroughBlock = Math.max(
    ledgerPayloadIndexedThroughBlock(ledger),
    Number.isSafeInteger(scanBlock) ? scanBlock : 0,
  );
  if (!indexedThroughBlock) {
    return ledger;
  }

  const normalizedTipHeight = Number(tipHeight);
  const sourceTipHeight = Number.isSafeInteger(normalizedTipHeight)
    ? normalizedTipHeight
    : Number(ledger.sourceTipHeight) ||
      Number(ledger.metrics?.sourceTipHeight) ||
      undefined;
  const metrics = {
    ...(ledger.metrics ?? {}),
    indexedThroughBlock,
    sourceTipHeight,
    tipLagBlocks:
      Number.isSafeInteger(sourceTipHeight) && indexedThroughBlock
        ? Math.max(0, sourceTipHeight - indexedThroughBlock)
        : ledger.metrics?.tipLagBlocks,
  };
  const snapshotId = sha256Hex(
    Buffer.from(
      JSON.stringify({
        metrics,
        network: ledger.network,
        proofEventScanFloor: ledger.snapshotId ?? "",
        sourceHashes: ledger.sourceHashes ?? {},
      }),
    ),
  ).slice(0, 24);
  const floored = {
    ...ledger,
    generatedAt: newerIso(ledger.generatedAt, scan.indexedAt),
    indexedThroughBlock,
    metrics,
    snapshotId,
    source: mergedSourceLabel(ledger.source, scan.source),
    sourceTipHeight,
  };
  const growthSummary = growthSummaryPayloadFromLedger(floored);
  const consistency = ledgerSnapshotChecks({
    activity: floored.activity,
    growthSummary,
    metrics,
    network: floored.network,
    seededMailActivityState: floored.seededMailActivityState,
    sourceHashes: floored.sourceHashes,
    tokenState: floored.tokenState,
    workFloor: floored.workFloor,
  });
  const result = {
    ...floored,
    consistency,
    growthSummary,
  };
  const inceptionSummary = inceptionSummaryPayloadFromLedger(result);
  const infinitySummary = infinitySummaryPayloadFromLedger(result);
  return {
    ...result,
    activityPayload: attachLedgerMetadata(result.activityPayload, result),
    growthSummary: attachLedgerMetadata(growthSummary, result),
    inceptionSummary: attachLedgerMetadata(inceptionSummary, result),
    infinitySummary: attachLedgerMetadata(infinitySummary, result),
    workFloor: attachLedgerMetadata(result.workFloor, result),
  };
}

async function proofIndexScanCoversCurrentProofEvents(payload, network, label) {
  if (network !== "livenet") {
    return null;
  }
  const ledgerBlock = ledgerPayloadIndexedThroughBlock(payload);
  if (!ledgerBlock) {
    return null;
  }

  const valueSummary = await proofIndexValueSummaryPayload(network).catch(
    (error) => {
      console.error(
        `Proof index value-event coverage read failed for ${label}: ${errorSummary(error)}`,
      );
      return null;
    },
  );
  if (
    !valueSummary ||
    !(await proofIndexPayloadCoversConfirmedTip(
      valueSummary,
      network,
      `${label} value-event coverage`,
    ))
  ) {
    return null;
  }

  const maxEventBlock = Number(valueSummary.stats?.maxEventBlock ?? 0);
  if (!Number.isSafeInteger(maxEventBlock) || maxEventBlock <= 0) {
    return null;
  }
  if (maxEventBlock > ledgerBlock) {
    console.error(
      `Rejected ${label}: proof-index has confirmed events through block ${maxEventBlock}, ledger only covers ${ledgerBlock}.`,
    );
    return null;
  }

  console.error(
    `Accepted ${label}: ledger block ${ledgerBlock} covers current proof-index event block ${maxEventBlock}.`,
  );
  return {
    indexedAt: valueSummary.indexedAt,
    indexedThroughBlock: proofIndexPayloadIndexedThroughBlock(valueSummary),
    maxEventBlock,
    source: valueSummary.source,
  };
}

function freshDataUnavailableError(message) {
  const error = new Error(message);
  error.statusCode = 503;
  return error;
}

async function currentLedgerPayloadOrNull(payload, network, label = "ledger") {
  if (!payload) {
    return null;
  }
  if (!ledgerPayloadHasCurrentChecks(payload)) {
    console.error(`Rejected ${label}: missing current ledger checks.`);
    return null;
  }
  const tipHeight = await ledgerTipHeight(network);
  const status = ledgerPayloadTipStatus(payload, tipHeight);
  if (!status.coversTip) {
    const currentScan = await proofIndexScanCoversCurrentProofEvents(
      payload,
      network,
      label,
    );
    if (currentScan) {
      return ledgerWithProofIndexScanFloor(payload, currentScan, tipHeight);
    }
    console.error(
      `Rejected stale ${label}: indexedThroughBlock ${status.indexedThroughBlock || "unknown"}, tip ${status.tipHeight ?? "unknown"}, lag ${Number.isFinite(status.lagBlocks) ? status.lagBlocks : "unknown"} blocks.`,
    );
    return null;
  }
  return payload;
}

async function exactTipLedgerPayloadOrNull(payload, network, label = "ledger") {
  if (!payload || !ledgerPayloadHasCurrentChecks(payload)) {
    return null;
  }
  if (network !== "livenet") {
    return payload;
  }
  const tipHeight = await healthNodeTipHeight();
  const indexedThroughBlock = ledgerPayloadIndexedThroughBlock(payload);
  if (
    !Number.isSafeInteger(tipHeight) ||
    !Number.isSafeInteger(indexedThroughBlock) ||
    indexedThroughBlock !== tipHeight
  ) {
    console.error(
      `Rejected non-fresh ${label}: indexedThroughBlock ${indexedThroughBlock || "unknown"}, tip ${Number.isSafeInteger(tipHeight) ? tipHeight : "unknown"}.`,
    );
    return null;
  }
  return payload;
}

async function proofIndexPayloadCoversConfirmedTip(
  payload,
  network,
  label = "proof-index",
) {
  if (network !== "livenet") {
    return true;
  }
  const indexedThroughBlock = proofIndexPayloadIndexedThroughBlock(payload);
  if (!indexedThroughBlock) {
    console.error(
      `Rejected ${label} proof-index read: payload has no indexedThroughBlock.`,
    );
    return false;
  }

  const tipHeight = await ledgerTipHeight(network);
  if (!Number.isSafeInteger(tipHeight)) {
    return true;
  }

  const lagBlocks = tipHeight - indexedThroughBlock;
  if (lagBlocks <= PROOF_INDEX_CONFIRMED_READ_MAX_LAG_BLOCKS) {
    return true;
  }

  console.error(
    `Rejected stale ${label} proof-index read: indexedThroughBlock ${indexedThroughBlock}, tip ${tipHeight}, lag ${lagBlocks} blocks.`,
  );
  return false;
}

async function proofIndexPayloadHasExplicitCurrentCoverage(
  payload,
  network,
  label = "proof-index",
) {
  if (network !== "livenet") {
    return true;
  }
  const indexedThroughBlock = proofIndexPayloadIndexedThroughBlock(payload);
  const tipHeight = await ledgerTipHeight(network);
  if (
    !Number.isSafeInteger(indexedThroughBlock) ||
    indexedThroughBlock <= 0 ||
    !Number.isSafeInteger(tipHeight) ||
    tipHeight <= 0
  ) {
    console.error(
      `Rejected ${label} proof-index read without explicit indexed/tip coverage.`,
    );
    return false;
  }
  const lagBlocks = tipHeight - indexedThroughBlock;
  return (
    lagBlocks >= 0 &&
    lagBlocks <= PROOF_INDEX_CONFIRMED_READ_MAX_LAG_BLOCKS
  );
}

async function existingCanonicalLedgerPayload(network) {
  const cacheKey = `ledger:${network}`;
  const payloadKey = `payload:ledger:${network}`;
  const cachedPayload = RESPONSE_CACHE.get(payloadKey)?.payload;
  if (
    cachedPayload &&
    (ledgerPayloadHasCurrentChecks(cachedPayload) ||
      ledgerPayloadIsUsableFallback(cachedPayload))
  ) {
    return ledgerWithHistoricalWorkFloorChart(cachedPayload);
  }

  const persistedPayload = await persistedPayloadForCache(
    cacheKey,
    LEDGER_CACHE_STALE_MS,
  );
  if (
    persistedPayload &&
    (ledgerPayloadHasCurrentChecks(persistedPayload) ||
      ledgerPayloadIsUsableFallback(persistedPayload))
  ) {
    const payload = ledgerWithHistoricalWorkFloorChart(persistedPayload);
    RESPONSE_CACHE.set(payloadKey, {
      expiresAt: Date.now() - 1,
      payload,
      staleUntil: Date.now() + LEDGER_CACHE_STALE_MS,
    });
    return payload;
  }

  return null;
}

async function existingCurrentCanonicalLedgerPayload(
  network,
  label = "canonical ledger",
) {
  const existing = await existingCanonicalLedgerPayload(network);
  return currentLedgerPayloadOrNull(existing, network, label);
}

async function existingCurrentCanonicalLedgerPayloadWithinMs(
  network,
  label = "canonical ledger",
  timeoutMs = SUMMARY_PROOF_INDEX_READ_WAIT_MS,
) {
  return payloadWithFallbackAfterMs(
    existingCurrentCanonicalLedgerPayload(network, label),
    null,
    timeoutMs,
  );
}

function payloadSnapshotId(payload) {
  return String(payload?.snapshotId ?? "").trim();
}

function payloadIndexedThroughBlockHash(payload) {
  for (const value of [
    payload?.indexedThroughBlockHash,
    payload?.provenance?.indexedThroughBlockHash,
    payload?.sourceHashes?.blockScan,
  ]) {
    const hash = String(value ?? "").trim().toLowerCase();
    if (/^[0-9a-f]{64}$/u.test(hash)) {
      return hash;
    }
  }
  return "";
}

function payloadSnapshotMatchesLedger(payload, ledger) {
  const payloadId = payloadSnapshotId(payload);
  const ledgerId = payloadSnapshotId(ledger);
  return !payloadId || !ledgerId || payloadId === ledgerId;
}

function logStaleSnapshotPayload(label, payload, ledger) {
  console.error(
    `Rejected stale ${label}: snapshot ${payloadSnapshotId(payload) || "unknown"} does not match canonical ledger snapshot ${payloadSnapshotId(ledger) || "unknown"}.`,
  );
}

function workFloorChartPointCount(workFloor) {
  return Array.isArray(workFloor?.chartPoints)
    ? workFloor.chartPoints.length
    : 0;
}

function workFloorHasHistoricalChart(workFloor) {
  const pointCount = workFloorChartPointCount(workFloor);
  const confirmedActions = numericValue(
    workFloor?.stats?.confirmedComputerActions,
  );
  if (confirmedActions <= 2) {
    return true;
  }
  return pointCount >= Math.min(confirmedActions + 1, 10);
}

async function currentProofIndexSummarySnapshotPayload(
  network,
  key,
  label,
  options = {},
) {
  let indexedPayload = await payloadWithFallbackAfterMs(
    proofIndexSnapshotPayload(network, key),
    null,
    SUMMARY_PROOF_INDEX_READ_WAIT_MS,
  ).catch((error) => {
    console.error(`Proof index ${label} read failed: ${errorSummary(error)}`);
    return null;
  });
  if (!indexedPayload) {
    return null;
  }
  if (options.allowWithoutCurrentCoverage === true) {
    console.error(
      `Accepted proof-index ${label} fallback without current coverage proof; serving latest complete indexed summary while refresh continues.`,
    );
  } else if (
    !(await payloadWithFallbackAfterMs(
      proofIndexPayloadCoversConfirmedTip(
        indexedPayload,
        network,
        `summary:${label}`,
      ),
      false,
      SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    ))
  ) {
    const coveredPayload = await proofIndexSummaryPayloadWithValueEventDelta(
      indexedPayload,
      network,
      key,
      label,
    );
    if (coveredPayload) {
      indexedPayload = coveredPayload;
    } else {
      return null;
    }
  }
  if (!summaryPayloadHasFiniteNetworkValue(network, key, indexedPayload)) {
    console.error(
      `Rejected malformed proof-index ${label} read: network value is not finite.`,
    );
    return null;
  }

  const ledger =
    options.allowWithoutCanonicalLedger === true
      ? null
      : await existingCurrentCanonicalLedgerPayloadWithinMs(
          network,
          `canonical snapshot check for ${label}`,
          SUMMARY_PROOF_INDEX_READ_WAIT_MS,
        );
  if (
    summaryKeyRequiresCanonicalLedger(network, key) &&
    !ledger &&
    options.allowWithoutCanonicalLedger !== true
  ) {
    console.error(
      `Rejected proof-index ${label} read: no current canonical ledger is available to verify the summary.`,
    );
    return null;
  }
  if (ledger && !payloadSnapshotMatchesLedger(indexedPayload, ledger)) {
    logStaleSnapshotPayload(`proof-index ${label} read`, indexedPayload, ledger);
    return null;
  }

  return indexedPayload;
}

async function currentProofIndexSummarySnapshotFallbackPayload(
  network,
  key,
  label,
) {
  const payload = await currentProofIndexSummarySnapshotPayload(
    network,
    key,
    label,
    {
      allowWithoutCanonicalLedger: true,
      allowWithoutCurrentCoverage: true,
    },
  );
  if (payload) {
    if (INDEXED_FALLBACK_BACKGROUND_REFRESH) {
      refreshCanonicalLedgerPayloadInBackground(network, true);
    }
  }
  return payload;
}

async function currentProofIndexWorkFloorFallbackPayload(
  network,
  fresh = false,
) {
  if (network !== "livenet") {
    return null;
  }

  const workSummary = await currentProofIndexSummarySnapshotFallbackPayload(
    network,
    "workSummary",
    "work-summary",
  );
  if (workSummary?.floor) {
    return workFloorWithSummaryMarketOverlay(
      workSummary.floor,
      network,
      fresh,
      workSummary.token,
    );
  }

  const growthSummary = await currentProofIndexSummarySnapshotFallbackPayload(
    network,
    "growthSummary",
    "growth-summary",
  );
  if (growthSummary?.workFloor) {
    return workFloorWithSummaryMarketOverlay(
      growthSummary.workFloor,
      network,
      fresh,
      growthSummary.token,
    );
  }

  return null;
}

async function currentProofIndexWorkFloorIfNewer(
  baseWorkFloor,
  network,
  fresh = false,
  label = "WORK floor",
) {
  if (network !== "livenet") {
    return baseWorkFloor;
  }

  const indexedWorkFloor = await currentProofIndexWorkFloorFallbackPayload(
    network,
    fresh,
  ).catch((error) => {
    console.error(
      `Proof-index ${label} overlay failed: ${errorSummary(error)}`,
    );
    return null;
  });
  if (!indexedWorkFloor) {
    return baseWorkFloor;
  }

  if (
    payloadSnapshotId(indexedWorkFloor) &&
    payloadSnapshotId(baseWorkFloor) &&
    !payloadSnapshotMatchesLedger(indexedWorkFloor, baseWorkFloor)
  ) {
    logStaleSnapshotPayload(label, indexedWorkFloor, baseWorkFloor);
    return baseWorkFloor;
  }

  const indexedBlock = proofIndexPayloadIndexedThroughBlock(indexedWorkFloor);
  const baseBlock = proofIndexPayloadIndexedThroughBlock(baseWorkFloor);
  const indexedValue = numericValue(
    indexedWorkFloor.actualValue?.totalSats ?? indexedWorkFloor.networkValueSats,
  );
  const baseValue = numericValue(
    baseWorkFloor?.actualValue?.totalSats ?? baseWorkFloor?.networkValueSats,
  );
  if (
    indexedBlock >= baseBlock &&
    finitePositiveNumber(indexedValue) &&
    (!finitePositiveNumber(baseValue) || indexedValue + 0.01 >= baseValue)
  ) {
    if (indexedWorkFloor !== baseWorkFloor) {
      console.error(
        `Accepted ${label}: proof-index WORK floor block ${indexedBlock || "unknown"} supersedes base block ${baseBlock || "unknown"}.`,
      );
    }
    return indexedWorkFloor;
  }

  console.error(
    `Rejected ${label}: proof-index WORK floor block ${indexedBlock || "unknown"} value ${indexedValue || "unknown"} is behind base block ${baseBlock || "unknown"} value ${baseValue || "unknown"}.`,
  );
  return baseWorkFloor;
}

async function ledgerWithReplayedCreditNetworkValues(
  ledger,
  network,
  label = "ledger",
) {
  const canonicalMinerFeeCoverage = verifiedCanonicalMinerFeeCoverage(
    ledger?.workFloor?.actualValue?.creditMinerFeeCoverage,
  );
  if (
    network !== "livenet" ||
    !ledgerPayloadIsUsableFallback(ledger) ||
    !ledger?.registryState ||
    !ledger?.tokenState ||
    !canonicalMinerFeeCoverage
  ) {
    return null;
  }

  const registryState = ledger.registryState;
  const initialTokenState = tokenStateWithScopedTokenOverride(
    ledger.tokenState,
    ledger.workTokenState,
    WORK_TOKEN_ID,
  );
  const initialWorkTokenState =
    ledger.workTokenState ??
    scopedTokenPayloadFromState(initialTokenState, WORK_TOKEN_ID);
  const existingActivity = Array.isArray(ledger.activity)
    ? ledger.activity
    : Array.isArray(ledger.activityPayload?.activity)
      ? ledger.activityPayload.activity
      : [];
  const baseActivity = dedupeActivityItems([
    ...existingActivity.filter((item) => !isTokenActivityItem(item)),
    ...tokenActivityItemsFromState(
      initialTokenState,
      initialTokenState?.indexAddress ?? "",
    ),
  ]);
  const creditValueDetails = creditNetworkValueMetrics({
    baseValueAt: growthActualBaseNetworkValueAtProvider(
      registryState.records ?? [],
      baseActivity,
      registryState.sales ?? [],
      initialTokenState.tokens ?? [],
      initialTokenState.mints ?? [],
      initialTokenState.transfers ?? [],
      initialTokenState.sales ?? [],
    ),
    canonicalMinerFeeCoverage,
    confirmedActivity: baseActivity,
    cutoffMs: CANONICAL_CONFIRMED_TIP_CUTOFF_MS,
    includeEvents: true,
    tokenDefinitions: initialTokenState.tokens ?? [],
    tokenMints: initialTokenState.mints ?? [],
    tokenSales: initialTokenState.sales ?? [],
    tokenTransfers: initialTokenState.transfers ?? [],
  });
  const tokenState = tokenStateWithCreditNetworkValueDetails(
    initialTokenState,
    creditValueDetails,
  );
  const workTokenState = tokenStateWithCreditNetworkValueDetails(
    initialWorkTokenState,
    creditValueDetails,
  );
  const activity = dedupeActivityItems([
    ...existingActivity.filter((item) => !isTokenActivityItem(item)),
    ...tokenActivityItemsFromState(
      tokenState,
      tokenState?.indexAddress ?? "",
    ),
  ]);
  const activityPayload = {
    ...(ledger.activityPayload ?? {}),
    activity,
    canonicalMinerFeeCoverage,
    indexedAt: new Date().toISOString(),
    network,
    source: mergedSourceLabel(
      ledger.activityPayload?.source ?? ledger.source,
      "credit-value-replay",
    ),
    stats: activityStatsFromItems(activity, ledger.activityPayload?.stats ?? {}),
  };
  let workFloor = workFloorPayloadFromState(
    network,
    registryState,
    activityPayload,
    tokenState,
    workTokenState,
    {
      btcUsdQuote: ledger.btcUsdQuote,
      valueCutoffMs: CANONICAL_CONFIRMED_TIP_CUTOFF_MS,
    },
  );
  workFloor = await workFloorWithPreConsistencyMarketOverlay(
    workFloor,
    network,
    tokenState,
    { required: false },
  );
  const baseMetrics = ledgerMetricsFromState({
    activity,
    registryState,
    tokenState,
    workFloor,
  });
  const sourceTipHeight =
    Number(ledger.sourceTipHeight) ||
    Number(ledger.metrics?.sourceTipHeight) ||
    (await ledgerTipHeight(network)) ||
    undefined;
  const indexedThroughBlock =
    Math.max(
      Number(baseMetrics.indexedThroughBlock) || 0,
      Number(ledger.indexedThroughBlock) || 0,
      Number(ledger.metrics?.indexedThroughBlock) || 0,
      Number(ledger.activityPayload?.indexedThroughBlock) || 0,
      Number(ledger.activityPayload?.stats?.indexedThroughBlock) || 0,
      Number(registryState?.indexedThroughBlock) || 0,
      Number(tokenState?.indexedThroughBlock) || 0,
      Number(workTokenState?.indexedThroughBlock) || 0,
    ) || baseMetrics.indexedThroughBlock;
  const metrics = {
    ...baseMetrics,
    indexedThroughBlock,
    sourceTipHeight: Number.isSafeInteger(sourceTipHeight)
      ? sourceTipHeight
      : undefined,
    tipLagBlocks:
      Number.isSafeInteger(sourceTipHeight) && indexedThroughBlock
        ? Math.max(0, sourceTipHeight - indexedThroughBlock)
        : undefined,
  };
  const sourceHashes = ledgerSourceHashes({
    activityState: activityPayload,
    registryState,
    seededMailActivityState: ledger.seededMailActivityState,
    tokenState,
    workTokenState,
  });
  const snapshotId = sha256Hex(
    Buffer.from(
      JSON.stringify({
        metrics,
        network,
        replayedFrom: ledger.snapshotId ?? "",
        sourceHashes,
      }),
    ),
  ).slice(0, 24);
  const replayed = {
    ...ledger,
    activity,
    activityPayload,
    generatedAt: new Date().toISOString(),
    indexedThroughBlock,
    metrics,
    network,
    registryState,
    snapshotId,
    source: mergedSourceLabel(ledger.source, "credit-value-replay"),
    sourceHashes,
    sourceTipHeight,
    tokenState,
    workFloor,
    workTokenState,
  };
  const growthSummary = growthSummaryPayloadFromLedger(replayed);
  const consistency = ledgerSnapshotChecks({
    activity,
    growthSummary,
    metrics,
    network,
    seededMailActivityState: ledger.seededMailActivityState,
    sourceHashes,
    tokenState,
    workFloor,
  });
  const summaryLedger = {
    ...replayed,
    consistency,
  };
  const inceptionSummary = inceptionSummaryPayloadFromLedger(summaryLedger);
  const infinitySummary = infinitySummaryPayloadFromLedger(summaryLedger);
  const result = {
    ...replayed,
    activityPayload: attachLedgerMetadata(activityPayload, {
      ...replayed,
      consistency,
    }),
    consistency,
    growthSummary: attachLedgerMetadata(growthSummary, {
      ...replayed,
      consistency,
    }),
    inceptionSummary: attachLedgerMetadata(inceptionSummary, {
      ...replayed,
      consistency,
    }),
    infinitySummary: attachLedgerMetadata(infinitySummary, {
      ...replayed,
      consistency,
    }),
    workFloor: attachLedgerMetadata(workFloor, {
      ...replayed,
      consistency,
    }),
  };
  console.error(
    `Replayed credit network values for ${label}: frozen ${Math.round(numericValue(workFloor.actualValue?.creditEventFrozenValueSats ?? workFloor.actualValue?.creditFrozenNetworkValueSats)).toLocaleString()} proofs, live ${Math.round(numericValue(workFloor.actualValue?.creditEventLiveValueSats ?? workFloor.actualValue?.creditLiveNetworkValueSats)).toLocaleString()} proofs.`,
  );
  return result;
}

function cacheDerivedLedgerPayload(cacheKey, payload, ttlMs, staleMs) {
  const payloadKey = `payload:${cacheKey}`;
  const body = JSON.stringify(payload);
  RESPONSE_CACHE.set(payloadKey, {
    expiresAt: Date.now() + ttlMs,
    payload,
    staleUntil: Date.now() + staleMs,
  });
  cacheJsonBody(`json:${cacheKey}`, body, ttlMs, staleMs);
  if (shouldPersistJsonCache(cacheKey)) {
    void writePersistedJsonCache(`json:${cacheKey}`, body);
  }
}

function readOnlyRetainedWorkAmoV8Metadata(metadata) {
  if (!metadata || typeof metadata !== "object" || Array.isArray(metadata)) {
    return metadata;
  }
  const migrationReadiness = metadata.migrationReadiness;
  const workerReadiness = metadata.workerReadiness;
  return {
    ...metadata,
    indexReady: false,
    listingWritesEnabled: false,
    migrationReady: false,
    protocolReady: false,
    protocolWritesEnabled: false,
    ready: false,
    reasonCode: "work-amo-v8-writes-paused",
    settlementWritesEnabled: false,
    writeAdmission: false,
    ...(migrationReadiness &&
    typeof migrationReadiness === "object" &&
    !Array.isArray(migrationReadiness)
      ? {
          migrationReadiness: {
            ...migrationReadiness,
            exactTipReady: false,
            pendingReady: false,
            ready: false,
          },
        }
      : {}),
    ...(workerReadiness &&
    typeof workerReadiness === "object" &&
    !Array.isArray(workerReadiness)
      ? {
          workerReadiness: {
            ...workerReadiness,
            ready: false,
          },
        }
      : {}),
  };
}

function retainedExactTipTokenPayloadForRead(payload, canonicalGate, cached) {
  if (
    canonicalGate?.ready === true &&
    Number(cached?.greenUntil) >= Date.now()
  ) {
    return payload;
  }
  const withReadOnlyMetadata = (container) =>
    container && typeof container === "object" && !Array.isArray(container)
      ? {
          ...container,
          workAmoV8: readOnlyRetainedWorkAmoV8Metadata(container.workAmoV8),
        }
      : container;
  return {
    ...payload,
    workAmoV8: readOnlyRetainedWorkAmoV8Metadata(payload?.workAmoV8),
    ...(payload?.floor && typeof payload.floor === "object"
      ? { floor: withReadOnlyMetadata(payload.floor) }
      : {}),
    ...(payload?.workFloor && typeof payload.workFloor === "object"
      ? { workFloor: withReadOnlyMetadata(payload.workFloor) }
      : {}),
  };
}

function cacheCanonicalLedgerPayload(network, payload) {
  const cacheKey = `ledger:${network}`;
  const payloadKey = `payload:${cacheKey}`;
  const body = JSON.stringify(payload);
  RESPONSE_CACHE.set(payloadKey, {
    expiresAt: Date.now() + LEDGER_CACHE_TTL_MS,
    payload,
    staleUntil: Date.now() + LEDGER_CACHE_STALE_MS,
  });
  cacheJsonBody(
    `json:${cacheKey}`,
    body,
    LEDGER_CACHE_TTL_MS,
    LEDGER_CACHE_STALE_MS,
  );
  if (shouldPersistJsonCache(cacheKey)) {
    void writePersistedJsonCache(`json:${cacheKey}`, body);
  }

  if (payload?.workFloor) {
    cacheDerivedLedgerPayload(
      `work-floor:${network}`,
      payload.workFloor,
      WORK_FLOOR_CACHE_TTL_MS,
      WORK_FLOOR_CACHE_STALE_MS,
    );
  }
  if (payload?.growthSummary) {
    cacheDerivedLedgerPayload(
      `growth-summary:${network}`,
      payload.growthSummary,
      LEDGER_CACHE_TTL_MS,
      HEAVY_READ_STALE_MS,
    );
  }
  if (payload?.infinitySummary) {
    cacheDerivedLedgerPayload(
      `infinity-summary:${network}`,
      payload.infinitySummary,
      LEDGER_CACHE_TTL_MS,
      HEAVY_READ_STALE_MS,
    );
  }
  if (payload?.inceptionSummary) {
    cacheDerivedLedgerPayload(
      `inception-summary:${network}`,
      payload.inceptionSummary,
      LEDGER_CACHE_TTL_MS,
      HEAVY_READ_STALE_MS,
    );
  }
}

function ledgerTokenStateForScope(ledger, scope) {
  if (!scope) {
    return ledger.tokenState;
  }

  if (scope === WORK_TOKEN_ID && ledger.workTokenState) {
    return ledger.workTokenState;
  }

  const tokenState = ledger.tokenState ?? emptyTokenPayloadSnapshot(ledger.network);
  return scopedTokenPayloadFromState(tokenState, scope);
}

function tokenStateLogExpectations(tokenState) {
  const expectations = [];
  const seenSealTxids = new Set();
  const add = (item) => {
    const txid = String(item?.txid ?? "").toLowerCase();
    if (!item?.kind || !/^[0-9a-f]{64}$/u.test(txid)) {
      return;
    }
    expectations.push({
      ...item,
      participants: Array.isArray(item.participants) ? item.participants : [],
      tokenId: item.tokenId ?? "",
      txid,
    });
  };

  for (const token of tokenState?.tokens ?? []) {
    if (
      !token?.confirmed ||
      token.tokenId === WORK_TOKEN_ID ||
      BOND_TOKEN_IDS.has(token.tokenId)
    ) {
      continue;
    }
    add({
      kind: "token-create",
      participants: [token.creatorAddress, token.registryAddress].filter(Boolean),
      tokenId: token.tokenId,
      txid: token.txid,
    });
  }

  for (const mint of tokenState?.mints ?? []) {
    if (!mint?.confirmed) {
      continue;
    }
    add({
      kind: "token-mint",
      participants: [mint.minterAddress, mint.registryAddress].filter(Boolean),
      tokenId: mint.tokenId,
      txid: mint.txid,
    });
  }

  for (const transfer of tokenState?.transfers ?? []) {
    if (!transfer?.confirmed) {
      continue;
    }
    add({
      kind: "token-transfer",
      participants: [
        transfer.senderAddress,
        transfer.recipientAddress,
        transfer.registryAddress,
      ].filter(Boolean),
      tokenId: transfer.tokenId,
      txid: transfer.txid,
    });
  }

  for (const listing of [
    ...(tokenState?.listings ?? []),
    ...(tokenState?.closedListings ?? []).filter(
      (item) => item?.relic === true,
    ),
  ]) {
    if (listing?.confirmed) {
      add({
        kind: "token-listing",
        listingId: listing.listingId,
        participants: [
          listing.sellerAddress,
          listing.saleAuthorization?.buyerAddress,
          listing.registryAddress,
        ].filter(Boolean),
        tokenId: listing.tokenId,
        txid: listing.listingId,
      });
    }
  }

  for (const listing of [
    ...(tokenState?.listings ?? []),
    ...(tokenState?.closedListings ?? []),
  ]) {
    const sealTxid = String(listing?.sealTxid ?? "").toLowerCase();
    if (
      listing?.sealConfirmed !== true ||
      !/^[0-9a-f]{64}$/u.test(sealTxid) ||
      seenSealTxids.has(sealTxid)
    ) {
      continue;
    }
    seenSealTxids.add(sealTxid);
    add({
      kind: "token-listing-sealed",
      listingId: listing.listingId,
      participants: [
        listing.sellerAddress,
        listing.saleAuthorization?.buyerAddress,
        listing.registryAddress,
      ].filter(Boolean),
      tokenId: listing.tokenId,
      txid: sealTxid,
    });
  }

  for (const listing of (tokenState?.closedListings ?? []).filter(
    (item) => item?.relic !== true,
  )) {
    const closedTxid = listing?.closedTxid || listing?.listingId;
    if (
      !listing?.closedConfirmed ||
      !closedTxid ||
      listing?.closedByCanonicalOutpointSpend === true
    ) {
      continue;
    }
    add({
      kind: "token-listing-closed",
      listingId: listing.listingId,
      participants: [
        listing.sellerAddress,
        listing.saleAuthorization?.buyerAddress,
        listing.registryAddress,
      ].filter(Boolean),
      tokenId: listing.tokenId,
      txid: closedTxid,
    });
  }

  for (const sale of tokenState?.sales ?? []) {
    if (!sale?.confirmed) {
      continue;
    }
    add({
      kind: "token-sale",
      listingId: sale.listingId,
      participants: [
        sale.buyerAddress,
        sale.sellerAddress,
        sale.registryAddress,
      ].filter(Boolean),
      tokenId: sale.tokenId,
      txid: sale.txid,
    });
  }

  return expectations;
}

function activityCoverageByTxidKind(activity) {
  const coverageByKey = new Map();
  for (const item of activity ?? []) {
    if (!item?.txid || !item?.kind) {
      continue;
    }
    const key = `${item.kind}:${item.txid}`;
    const coverage = coverageByKey.get(key) ?? {
      items: 0,
      participants: new Set(),
    };
    coverage.items += 1;
    for (const participant of Array.isArray(item?.participants)
      ? item.participants
      : []) {
      if (participant) {
        coverage.participants.add(participant);
      }
    }
    coverageByKey.set(key, coverage);
  }
  return coverageByKey;
}

function tokenComponentCoverageFromConfirmedActivity(activity, tokenState) {
  const confirmedActivity = (Array.isArray(activity) ? activity : []).filter(
    (item) => item?.confirmed && item?.valid !== false,
  );
  const activityCounts = {
    mints: confirmedActivity.filter((item) => item?.kind === "token-mint").length,
    sales: confirmedActivity.filter((item) => item?.kind === "token-sale").length,
    tokens: confirmedActivity.filter((item) => item?.kind === "token-create").length,
    transfers: confirmedActivity.filter((item) => item?.kind === "token-transfer")
      .length,
  };
  const stateCounts = {
    mints: (tokenState?.mints ?? []).filter((item) => item?.confirmed).length,
    sales: (tokenState?.sales ?? []).filter((item) => item?.confirmed).length,
    tokens: (tokenState?.tokens ?? []).filter((item) => item?.confirmed).length,
    transfers: (tokenState?.transfers ?? []).filter((item) => item?.confirmed)
      .length,
  };
  const missing = Object.keys(activityCounts).filter(
    (key) => activityCounts[key] > 0 && stateCounts[key] === 0,
  );
  return { activityCounts, missing, ok: missing.length === 0, stateCounts };
}

function canonicalActivityCountCoverage(metrics, sourceHashes) {
  const canonicalActivityCount = numericValue(sourceHashes?.activity?.count);
  const canonicalConfirmedActivityCount = numericValue(
    sourceHashes?.activity?.confirmed,
  );
  const ledgerActivityCount = numericValue(metrics?.activityItems);
  const ledgerConfirmedActivityCount = numericValue(
    metrics?.confirmedComputerActions,
  );
  return {
    canonicalActivityCount,
    canonicalConfirmedActivityCount,
    ledgerActivityCount,
    ledgerConfirmedActivityCount,
    ok:
      ledgerActivityCount === canonicalActivityCount &&
      ledgerConfirmedActivityCount === canonicalConfirmedActivityCount,
  };
}

function exactCreditFrozenValueComponentsAgree(actualValue) {
  const source = actualValue && typeof actualValue === "object"
    ? actualValue
    : {};
  const eventValueQ8Absent = source.creditEventFrozenValueQ8 == null;
  const movementValueQ8Absent = source.creditMovementFrozenValueQ8 == null;
  if (eventValueQ8Absent && movementValueQ8Absent) {
    return null;
  }
  if (eventValueQ8Absent || movementValueQ8Absent) {
    return false;
  }
  const eventValueQ8 = canonicalIntegerText(
    source.creditEventFrozenValueQ8,
    { allowZero: true },
  );
  const movementValueQ8 = canonicalIntegerText(
    source.creditMovementFrozenValueQ8,
    { allowZero: true },
  );
  const fixedValueQ8 = canonicalIntegerText(source.creditFixedQ8, {
    allowZero: true,
  });
  const flowFields = [
    "creditProofPaymentFlowSats",
    "creditRegistryMutationFlowSats",
    "creditMarketplaceMutationFlowSats",
    "creditSalePaymentFlowSats",
    "creditMinerFeeFlowSats",
  ];
  const presentFlows = flowFields.filter(
    (field) =>
      source[field] !== undefined &&
      source[field] !== null &&
      source[field] !== "",
  );
  const flows = flowFields.map((field) =>
    canonicalIntegerText(source[field], { allowZero: true }),
  );
  const legacyCreditFixedQ8Present =
    source.legacyBootstrapCreditFixedQ8 !== undefined &&
    source.legacyBootstrapCreditFixedQ8 !== null &&
    source.legacyBootstrapCreditFixedQ8 !== "";
  const legacyCreditFixedSatsPresent =
    source.legacyBootstrapCreditFixedSats !== undefined &&
    source.legacyBootstrapCreditFixedSats !== null &&
    source.legacyBootstrapCreditFixedSats !== "";
  const postActivationCreditFixedQ8Present =
    source.postActivationCreditFixedQ8 !== undefined &&
    source.postActivationCreditFixedQ8 !== null &&
    source.postActivationCreditFixedQ8 !== "";
  const postActivationCreditFixedSatsPresent =
    source.postActivationCreditFixedSats !== undefined &&
    source.postActivationCreditFixedSats !== null &&
    source.postActivationCreditFixedSats !== "";
  if (
    legacyCreditFixedQ8Present !== legacyCreditFixedSatsPresent ||
    postActivationCreditFixedQ8Present !==
      postActivationCreditFixedSatsPresent ||
    (presentFlows.length > 0 && presentFlows.length !== flowFields.length)
  ) {
    return false;
  }
  const legacyCreditFixedQ8 = canonicalIntegerText(
    legacyCreditFixedQ8Present
      ? source.legacyBootstrapCreditFixedQ8
      : "0",
    { allowZero: true },
  );
  const legacyCreditFixedSats = canonicalIntegerText(
    legacyCreditFixedSatsPresent
      ? source.legacyBootstrapCreditFixedSats
      : "0",
    { allowZero: true },
  );
  const postActivationCreditFixedQ8 = canonicalIntegerText(
    postActivationCreditFixedQ8Present
      ? source.postActivationCreditFixedQ8
      : "0",
    { allowZero: true },
  );
  const postActivationCreditFixedSats = canonicalIntegerText(
    postActivationCreditFixedSatsPresent
      ? source.postActivationCreditFixedSats
      : "0",
    { allowZero: true },
  );
  if (
    !eventValueQ8 ||
    !movementValueQ8 ||
    !legacyCreditFixedQ8 ||
    !legacyCreditFixedSats ||
    !postActivationCreditFixedQ8 ||
    !postActivationCreditFixedSats ||
    BigInt(legacyCreditFixedQ8) !==
      BigInt(legacyCreditFixedSats) * VALUE_Q8_SCALE ||
    BigInt(postActivationCreditFixedQ8) !==
      BigInt(postActivationCreditFixedSats) * VALUE_Q8_SCALE
  ) {
    return false;
  }
  const expectedFixedQ8 =
    presentFlows.length === flowFields.length &&
    flows.every((value) => value !== null)
      ? flows.reduce(
          (total, value) =>
            total + BigInt(value) * VALUE_Q8_SCALE,
          BigInt(legacyCreditFixedQ8) +
            BigInt(postActivationCreditFixedQ8),
        )
      : null;
  if (fixedValueQ8) {
    return (
      BigInt(eventValueQ8) ===
        BigInt(movementValueQ8) + BigInt(fixedValueQ8) &&
      (expectedFixedQ8 === null ||
        BigInt(fixedValueQ8) === expectedFixedQ8)
    );
  }
  return (
    expectedFixedQ8 !== null &&
    BigInt(eventValueQ8) ===
      BigInt(movementValueQ8) + expectedFixedQ8
  );
}

function ledgerSnapshotChecks({
  activity,
  growthSummary,
  metrics,
  network,
  seededMailActivityState,
  sourceHashes,
  tokenState,
  workFloor,
}) {
  const checks = [];
  const missingLogEvents = [];
  const addCheck = (name, ok, details = {}) => {
    checks.push({ details, name, ok });
  };

  addCheck(
    "livenet-confirmed-history-present",
    network !== "livenet" ||
      numericValue(metrics?.powids) > 0 ||
      numericValue(metrics?.confirmedTokens) > 0 ||
      numericValue(metrics?.activityItems) > 0,
    {
      activityItems: numericValue(metrics?.activityItems),
      confirmedTokens: numericValue(metrics?.confirmedTokens),
      powids: numericValue(metrics?.powids),
    },
  );
  addCheck(
    "token-definitions-cover-confirmed-mints",
    numericValue(metrics?.confirmedTokenMints) === 0 ||
      numericValue(metrics?.confirmedTokens) > 0,
    {
      confirmedTokenMints: numericValue(metrics?.confirmedTokenMints),
      confirmedTokens: numericValue(metrics?.confirmedTokens),
    },
  );
  const tokenComponentCoverage = tokenComponentCoverageFromConfirmedActivity(
    activity,
    tokenState,
  );
  addCheck(
    "token-components-cover-confirmed-activity",
    network !== "livenet" || tokenComponentCoverage.ok,
    tokenComponentCoverage,
  );
  const canonicalActivityCoverage = canonicalActivityCountCoverage(
    metrics,
    sourceHashes,
  );
  addCheck(
    "canonical-activity-count-matches-public-log",
    network !== "livenet" || canonicalActivityCoverage.ok,
    canonicalActivityCoverage,
  );
  const indexedThroughBlock = numericValue(metrics?.indexedThroughBlock);
  const sourceTipHeight = numericValue(metrics?.sourceTipHeight);
  const tipLagBlocks =
    sourceTipHeight > 0 && indexedThroughBlock > 0
      ? Math.max(0, sourceTipHeight - indexedThroughBlock)
      : 0;
  addCheck(
    "ledger-covers-node-tip",
    network !== "livenet" ||
      sourceTipHeight <= 0 ||
      (indexedThroughBlock > 0 &&
        tipLagBlocks <= PROOF_INDEX_CONFIRMED_READ_MAX_LAG_BLOCKS),
    {
      indexedThroughBlock,
      lagBlocks: tipLagBlocks,
      maxLagBlocks: PROOF_INDEX_CONFIRMED_READ_MAX_LAG_BLOCKS,
      tipHeight: sourceTipHeight,
    },
  );

  const workNetworkValue = numericValue(workFloor?.networkValueSats);
  const workActualValue = numericValue(workFloor?.actualValue?.totalSats);
  const growthActualValue = numericValue(growthSummary?.actualValue?.totalSats);
  const growthFloorValue = numericValue(
    growthSummary?.workFloor?.networkValueSats,
  );
  const confirmedActivity = (activity ?? []).filter((item) => item?.confirmed);
  const incbTokenState = scopedTokenPayloadFromState(tokenState, INCB_TOKEN_ID);
  const incbConfirmedSupply =
    canonicalIntegerText(incbTokenState?.confirmedSupply, { allowZero: true }) ||
    "0";
  const inceptionIssuance = inceptionIssuanceMetadataFromMints(
    incbTokenState?.mints,
  );
  addCheck(
    "inception-live-issuance-matches-incb-supply",
    network !== "livenet" ||
      (inceptionIssuance.complete &&
        inceptionIssuance.confirmedIssuanceUnits === incbConfirmedSupply),
    {
      canonicalMints: inceptionIssuance.canonicalMints,
      confirmedIssuanceUnits: inceptionIssuance.confirmedIssuanceUnits,
      confirmedMints: inceptionIssuance.confirmedMints,
      incbConfirmedSupply,
      issuanceAccountingModel: inceptionIssuance.issuanceAccountingModel,
      issuanceNetworkValueSats: inceptionIssuance.issuanceNetworkValueSats,
    },
  );
  const sumExactSats = (items, field) =>
    items.reduce((total, item) => {
      const value = integerBigInt(item?.[field], { allowZero: true });
      return value === null ? total : total + value;
    }, 0n);
  const inceptionSaleVolume = sumExactSats(
    (incbTokenState?.sales ?? [])
    .filter((sale) => sale?.confirmed && sale.tokenId === INCB_TOKEN_ID)
    ,
    "priceSats",
  );
  const inceptionTransferFee = sumExactSats(
    (incbTokenState?.transfers ?? [])
    .filter(
      (transfer) =>
        transfer?.confirmed && transfer.tokenId === INCB_TOKEN_ID,
    ),
    "paidSats",
  );
  const inceptionMarketplaceMutationFee = confirmedActivity
    .filter(
      (item) =>
        item?.tokenId === INCB_TOKEN_ID &&
        TOKEN_MARKETPLACE_MUTATION_KINDS.has(item?.kind),
    )
    .reduce((total, item) => {
      const value = integerBigInt(marketplaceMutationPaymentSats(item), {
        allowZero: true,
      });
      return value === null ? total : total + value;
    }, 0n);
  const inceptionIssuanceNetworkValueQ8 =
    integerBigInt(inceptionIssuance.issuanceNetworkValueQ8, {
      allowZero: true,
    }) ?? 0n;
  const inceptionFixedNetworkValueQ8 =
    inceptionIssuanceNetworkValueQ8 +
    (inceptionSaleVolume +
      inceptionTransferFee +
      inceptionMarketplaceMutationFee) *
      BOND_VALUE_Q8_SCALE;
  const incbConfirmedSupplyUnits = BigInt(incbConfirmedSupply);
  const inceptionFixedFloorQ8 =
    incbConfirmedSupplyUnits > 0n
      ? inceptionFixedNetworkValueQ8 / incbConfirmedSupplyUnits
      : 0n;
  addCheck(
    "inception-fixed-value-reconciles",
    network !== "livenet" ||
      (inceptionIssuance.complete &&
        inceptionIssuance.confirmedIssuanceUnits === incbConfirmedSupply &&
        (incbConfirmedSupplyUnits === 0n
          ? inceptionFixedNetworkValueQ8 === 0n
          : inceptionFixedNetworkValueQ8 > 0n &&
            inceptionFixedFloorQ8 ===
              inceptionFixedNetworkValueQ8 / incbConfirmedSupplyUnits)),
    {
      confirmedSupply: incbConfirmedSupply,
      fixedFloorQ8: inceptionFixedFloorQ8.toString(),
      fixedFloorSats: decimalTextFromQ8(inceptionFixedFloorQ8),
      fixedNetworkValueQ8: inceptionFixedNetworkValueQ8.toString(),
      fixedNetworkValueSats: decimalTextFromQ8(inceptionFixedNetworkValueQ8),
      issuanceNetworkValueSats:
        inceptionIssuance.issuanceNetworkValueSats,
      marketplaceMutationFeeSats:
        inceptionMarketplaceMutationFee.toString(),
      networkValueAccountingModel:
        INCEPTION_NETWORK_VALUE_ACCOUNTING_MODEL,
      saleVolumeSats: inceptionSaleVolume.toString(),
      transferFeeSats: inceptionTransferFee.toString(),
    },
  );
  const powbTokenState = scopedTokenPayloadFromState(tokenState, POWB_TOKEN_ID);
  const powbConfirmedSupply =
    canonicalIntegerText(powbTokenState?.confirmedSupply, { allowZero: true }) ||
    "0";
  const infinityBondFlow = confirmedActivity
    .filter(isInfinityBondActivityItem)
    .reduce(
      (total, item) => total + BigInt(activityAmountSats(item)),
      0n,
    );
  addCheck(
    "infinity-bond-flow-matches-powb-supply",
    network !== "livenet" ||
      (BigInt(powbConfirmedSupply) > 0n &&
        infinityBondFlow === BigInt(powbConfirmedSupply)),
    {
      infinityBondFlowSats: infinityBondFlow.toString(),
      powbConfirmedSupply,
    },
  );
  const confirmedMarketplaceMutationFeeSats = confirmedActivityFlowSats(
    confirmedActivity,
    MARKETPLACE_MUTATION_KINDS,
  );
  const marketplaceFeeSats = numericValue(
    workFloor?.actualValue?.marketplaceFeeSats,
  );
  const marketplaceMutationFeeSats = numericValue(
    workFloor?.actualValue?.marketplaceMutationFeeSats,
  );
  const legacyBootstrapMarketplaceCarrySats = numericValue(
    workFloor?.actualValue?.legacyBootstrapMarketplaceCarrySats,
  );
  const marketplaceSaleVolumeSats = numericValue(
    workFloor?.actualValue?.marketplaceSaleVolumeSats ??
      workFloor?.actualValue?.marketplaceVolumeSats,
  );
  const marketplaceFlowSats = numericValue(
    workFloor?.actualValue?.marketplaceFlowSats,
  );
  const marketplaceSats = numericValue(workFloor?.actualValue?.marketplaceSats);
  const expectedMarketplaceFlowSats =
    marketplaceSaleVolumeSats + marketplaceMutationFeeSats;
  const expectedMarketplaceSats =
    expectedMarketplaceFlowSats * GROWTH_MODEL_INPUTS.valueMultiple;
  const expectedComputerEventFlowSats =
    unbucketedConfirmedComputerLogFlowSats(confirmedActivity);
  const computerEventFlowSats = numericValue(
    workFloor?.actualValue?.computerEventFlowSats,
  );
  const creditMovementFrozenValueSats = numericValue(
    workFloor?.actualValue?.creditMovementFrozenValueSats,
  );
  const creditProofPaymentFlowSats = numericValue(
    workFloor?.actualValue?.creditProofPaymentFlowSats,
  );
  const creditRegistryMutationFlowSats = numericValue(
    workFloor?.actualValue?.creditRegistryMutationFlowSats,
  );
  const creditMarketplaceMutationFlowSats = numericValue(
    workFloor?.actualValue?.creditMarketplaceMutationFlowSats,
  );
  const creditSalePaymentFlowSats = numericValue(
    workFloor?.actualValue?.creditSalePaymentFlowSats,
  );
  const creditMinerFeeFlowSats = numericValue(
    workFloor?.actualValue?.creditMinerFeeFlowSats,
  );
  const legacyBootstrapCreditFixedSats = numericValue(
    workFloor?.actualValue?.legacyBootstrapCreditFixedSats,
  );
  const legacyBootstrapCreditFixedQ8 =
    workFloor?.actualValue?.legacyBootstrapCreditFixedQ8;
  const postActivationCreditFixedSats = numericValue(
    workFloor?.actualValue?.postActivationCreditFixedSats,
  );
  const postActivationCreditFixedQ8 =
    workFloor?.actualValue?.postActivationCreditFixedQ8;
  const legacyBootstrapEvidence =
    workFloor?.actualValue?.workAmoV5LegacyBootstrap;
  const creditNetworkValueSats = numericValue(
    workFloor?.actualValue?.creditNetworkValueSats,
  );
  const creditEventFrozenValueSats = numericValue(
    workFloor?.actualValue?.creditEventFrozenValueSats ??
      workFloor?.actualValue?.creditFrozenNetworkValueSats,
  );
  const creditEventLiveValueSats = numericValue(
    workFloor?.actualValue?.creditEventLiveValueSats ??
      workFloor?.actualValue?.creditLiveNetworkValueSats,
  );
  const creditLiveNetworkValueSats = numericValue(
    workFloor?.actualValue?.creditLiveNetworkValueSats ??
      creditEventLiveValueSats,
  );
  const exactCreditFrozenComponents =
    exactCreditFrozenValueComponentsAgree(workFloor?.actualValue);
  addCheck(
    "network-values-finite",
    network !== "livenet" ||
      (workFloorPayloadHasFiniteNetworkValue(workFloor) &&
        growthSummaryPayloadHasFiniteNetworkValue(growthSummary)),
    {
      growthActualValueSats: growthActualValue,
      growthWorkFloorValueSats: growthFloorValue,
      workActualValueSats: workActualValue,
      workNetworkValueSats: workNetworkValue,
    },
  );
  addCheck("work-floor-actual-total", numbersAgree(workNetworkValue, workActualValue), {
    actualValueSats: workActualValue,
    networkValueSats: workNetworkValue,
  });
  addCheck("growth-actual-total", numbersAgree(workNetworkValue, growthActualValue), {
    growthValueSats: growthActualValue,
    workValueSats: workNetworkValue,
  });
  addCheck("growth-work-floor-total", numbersAgree(workNetworkValue, growthFloorValue), {
    growthWorkFloorSats: growthFloorValue,
    workValueSats: workNetworkValue,
  });
  addCheck(
    "marketplace-mutation-fees-counted",
    numbersAgree(marketplaceFeeSats, marketplaceMutationFeeSats) &&
      (numbersAgree(
        confirmedMarketplaceMutationFeeSats,
        marketplaceMutationFeeSats,
      ) ||
        numbersAgree(
          confirmedMarketplaceMutationFeeSats,
          marketplaceMutationFeeSats +
            legacyBootstrapMarketplaceCarrySats,
        )),
    {
      confirmedMarketplaceMutationFeeSats,
      legacyBootstrapMarketplaceCarrySats,
      marketplaceFeeSats,
      marketplaceMutationFeeSats,
    },
  );
  addCheck(
    "work-amo-v5-legacy-bootstrap-carry-proven",
    network !== "livenet" ||
      indexedThroughBlock < WORK_AMO_V5_ACTIVATION_HEIGHT ||
      workAmoV5LegacyBootstrapEvidenceMatches(
        legacyBootstrapEvidence,
      ),
    {
      evidence: legacyBootstrapEvidence ?? null,
      indexedThroughBlock,
      model: WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_MODEL,
    },
  );
  addCheck(
    "marketplace-value-includes-mutation-fees",
    numbersAgree(marketplaceFlowSats, expectedMarketplaceFlowSats) &&
      numbersAgree(marketplaceSats, expectedMarketplaceSats),
    {
      marketplaceFlowSats,
      marketplaceMutationFeeSats,
      marketplaceSaleVolumeSats,
      marketplaceSats,
    },
  );
  addCheck(
    "computer-event-flow-excludes-marketplace",
    numbersAgree(computerEventFlowSats, expectedComputerEventFlowSats),
    {
      computerEventFlowSats,
      expectedComputerEventFlowSats,
      marketplaceMutationFeeSats,
    },
  );
  addCheck(
    "credit-frozen-value-includes-event-components",
    exactCreditFrozenComponents === true ||
      (exactCreditFrozenComponents === null &&
        numbersAgree(
          creditEventFrozenValueSats,
          creditMovementFrozenValueSats +
            creditProofPaymentFlowSats +
            creditRegistryMutationFlowSats +
            creditMarketplaceMutationFlowSats +
            creditSalePaymentFlowSats +
            creditMinerFeeFlowSats +
            legacyBootstrapCreditFixedSats +
            postActivationCreditFixedSats,
          // Historical snapshots predate exact aggregate Q8 fields. Keep the
          // old sub-proof fallback only for those stored payloads.
          0.01,
        )),
    {
      creditMinerFeeFlowSats,
      creditEventFrozenValueSats,
      creditEventFrozenValueQ8:
        workFloor?.actualValue?.creditEventFrozenValueQ8,
      creditMarketplaceMutationFlowSats,
      creditMovementFrozenValueSats,
      creditMovementFrozenValueQ8:
        workFloor?.actualValue?.creditMovementFrozenValueQ8,
      legacyBootstrapCreditFixedQ8,
      legacyBootstrapCreditFixedSats,
      postActivationCreditFixedQ8,
      postActivationCreditFixedSats,
      creditProofPaymentFlowSats,
      creditRegistryMutationFlowSats,
      creditSalePaymentFlowSats,
    },
  );
  addCheck(
    "credit-live-value-is-active-network-value",
    numbersAgree(creditNetworkValueSats, creditLiveNetworkValueSats) &&
      numbersAgree(creditNetworkValueSats, creditEventLiveValueSats),
    {
      creditEventLiveValueSats,
      creditLiveNetworkValueSats,
      creditNetworkValueSats,
    },
  );

  const activityByTxidKind = activityCoverageByTxidKind(activity);

  const missingTokenLogEvents = [];
  for (const expected of tokenStateLogExpectations(tokenState)) {
    const coverage = activityByTxidKind.get(
      `${expected.kind}:${expected.txid}`,
    );
    const participantOk = expected.participants.every((address) =>
      coverage?.participants.has(address),
    );
    if (!coverage || !participantOk) {
      const missing = {
        kind: expected.kind,
        listingId: expected.listingId,
        txid: expected.txid,
        tokenId: expected.tokenId,
      };
      missingTokenLogEvents.push(missing);
      missingLogEvents.push(missing);
    }
  }

  addCheck("token-events-logged", missingTokenLogEvents.length === 0, {
    missing: missingTokenLogEvents.length,
    sample: missingTokenLogEvents.slice(0, 5),
  });
  addCheck(
    "token-sales-logged",
    !missingTokenLogEvents.some((item) => item.kind === "token-sale"),
    {
      missing: missingTokenLogEvents.filter(
        (item) => item.kind === "token-sale",
      ).length,
    },
  );

  const seededConfirmedMail = (seededMailActivityState?.activity ?? []).filter(
    (item) => item?.confirmed && item?.txid && item?.kind,
  );
  const missingSeededMailEvents = [];
  const missingSeededInceptionBondEvents = [];
  const missingSeededInfinityBondEvents = [];
  for (const item of seededConfirmedMail) {
    if (!activityByTxidKind.has(`${item.kind}:${item.txid}`)) {
      const missing = {
        amountSats: activityAmountSats(item),
        kind: item.kind,
        txid: item.txid,
      };
      missingSeededMailEvents.push(missing);
      missingLogEvents.push(missing);
      if (isInceptionBondActivityItem(item)) {
        missingSeededInceptionBondEvents.push(missing);
      }
      if (isInfinityBondActivityItem(item)) {
        missingSeededInfinityBondEvents.push(missing);
      }
    }
  }
  const seededInceptionBondFlowSats = seededConfirmedMail
    .filter(isInceptionBondActivityItem)
    .reduce((total, item) => total + activityAmountSats(item), 0);
  const loggedInceptionBondFlowSats = (activity ?? [])
    .filter((item) => item?.confirmed && isInceptionBondActivityItem(item))
    .reduce((total, item) => total + activityAmountSats(item), 0);
  const seededInfinityBondFlowSats = seededConfirmedMail
    .filter(isInfinityBondActivityItem)
    .reduce((total, item) => total + activityAmountSats(item), 0);
  const loggedInfinityBondFlowSats = (activity ?? [])
    .filter((item) => item?.confirmed && isInfinityBondActivityItem(item))
    .reduce((total, item) => total + activityAmountSats(item), 0);
  addCheck("seeded-mail-events-logged", missingSeededMailEvents.length === 0, {
    missing: missingSeededMailEvents.length,
    seeded: seededConfirmedMail.length,
  });
  addCheck(
    "seeded-inception-bonds-logged",
    missingSeededInceptionBondEvents.length === 0 &&
      loggedInceptionBondFlowSats >= seededInceptionBondFlowSats,
    {
      loggedFlowSats: loggedInceptionBondFlowSats,
      missing: missingSeededInceptionBondEvents.length,
      seeded: seededConfirmedMail.filter(isInceptionBondActivityItem).length,
      seededFlowSats: seededInceptionBondFlowSats,
    },
  );
  addCheck(
    "seeded-infinity-bonds-logged",
    missingSeededInfinityBondEvents.length === 0 &&
      loggedInfinityBondFlowSats >= seededInfinityBondFlowSats,
    {
      loggedFlowSats: loggedInfinityBondFlowSats,
      missing: missingSeededInfinityBondEvents.length,
      seeded: seededConfirmedMail.filter(isInfinityBondActivityItem).length,
      seededFlowSats: seededInfinityBondFlowSats,
    },
  );

  const ok = checks.every((check) => check.ok);
  return {
    checks,
    missingLogEvents,
    ok,
    status: ok ? "green" : "red",
  };
}

function attachLedgerMetadata(payload, ledger) {
  const indexedThroughBlockHash = String(
    ledger?.indexedThroughBlockHash ?? payload?.indexedThroughBlockHash ?? "",
  )
    .trim()
    .toLowerCase();
  return {
    ...payload,
    consistency: ledger.consistency,
    indexedThroughBlock: ledger.metrics.indexedThroughBlock,
    ...(/^[0-9a-f]{64}$/u.test(indexedThroughBlockHash)
      ? { indexedThroughBlockHash }
      : {}),
    ledgerGeneratedAt: ledger.generatedAt,
    snapshotId: ledger.snapshotId,
  };
}

function summaryPayloadRequiredComponents(payload, surface) {
  const required = [["root", payload]];
  const add = (...names) => {
    for (const name of names) {
      required.push([name, payload?.[name]]);
    }
  };
  if (surface === "growth-summary") {
    add("activity", "registry", "token", "workFloor");
  } else if (surface === "marketplace-summary") {
    add("registry", "token", "workFloor");
  } else if (surface === "work-summary") {
    add("floor", "token");
  } else if (
    surface === "inception-summary" ||
    surface === "infinity-summary"
  ) {
    add("token");
  }
  return required;
}

async function canonicalBlockHashAtHeight(height) {
  const response = await bitcoinRpc("getblockhash", [height]);
  const hash = String(response?.ok ? response.result : "")
    .trim()
    .toLowerCase();
  return /^[0-9a-f]{64}$/u.test(hash) ? hash : "";
}

async function verifiedSummaryPayloadCheckpoint(
  payload,
  network,
  requestedFresh,
  surface,
) {
  const indexedThroughBlock = proofIndexPayloadIndexedThroughBlock(payload);
  const indexedThroughBlockHash = payloadIndexedThroughBlockHash(payload);
  if (network !== "livenet") {
    return {
      exactTip: true,
      indexedThroughBlock,
      indexedThroughBlockHash: indexedThroughBlockHash || null,
      tipHash: null,
      tipHeight: indexedThroughBlock || null,
    };
  }
  if (indexedThroughBlock <= 0 || !indexedThroughBlockHash) {
    const error = freshDataUnavailableError(
      `${surface} has no hash-bound canonical checkpoint.`,
    );
    error.details = {
      code: "CANONICAL_SUMMARY_CHECKPOINT_MISSING",
      indexedThroughBlock: indexedThroughBlock || null,
      indexedThroughBlockHash: indexedThroughBlockHash || null,
      surface,
    };
    throw error;
  }

  const firstGate = await canonicalPublicReadGate(network, { force: true });
  const firstTipHeight = Number(firstGate?.tipHeight);
  if (
    firstGate?.ok !== true ||
    !Number.isSafeInteger(firstTipHeight) ||
    indexedThroughBlock > firstTipHeight
  ) {
    const error = freshDataUnavailableError(
      `${surface} cannot prove its checkpoint against the current canonical index.`,
    );
    error.details = {
      code: "CANONICAL_SUMMARY_CHECKPOINT_UNAVAILABLE",
      indexedThroughBlock,
      indexedThroughBlockHash,
      requestedFresh,
      surface,
      ...firstGate,
    };
    throw error;
  }

  const canonicalHash = await canonicalBlockHashAtHeight(indexedThroughBlock);
  if (!canonicalHash || canonicalHash !== indexedThroughBlockHash) {
    const error = freshDataUnavailableError(
      `${surface} checkpoint no longer matches Bitcoin Core.`,
    );
    error.details = {
      canonicalHash: canonicalHash || null,
      code: "CANONICAL_SUMMARY_CHECKPOINT_MISMATCH",
      indexedThroughBlock,
      indexedThroughBlockHash,
      surface,
    };
    throw error;
  }

  let finalGate = firstGate;
  const firstGateExactTip =
    firstGate?.ready === true &&
    indexedThroughBlock === firstTipHeight &&
    indexedThroughBlockHash === firstGate?.canonicalHash;
  if (requestedFresh && firstGateExactTip) {
    finalGate = await canonicalPublicReadGate(network, { force: true });
    if (
      finalGate?.ready !== true ||
      finalGate?.tipHeight !== firstGate.tipHeight ||
      finalGate?.canonicalHash !== firstGate.canonicalHash ||
      finalGate?.storedHash !== firstGate.storedHash ||
      finalGate?.tipHeight !== indexedThroughBlock ||
      finalGate?.canonicalHash !== indexedThroughBlockHash
    ) {
      const error = freshDataUnavailableError(
        `${surface} canonical tip changed during checkpoint verification.`,
      );
      error.details = {
        code: "CANONICAL_SUMMARY_TIP_CHANGED",
        firstGate,
        finalGate,
        indexedThroughBlock,
        indexedThroughBlockHash,
        surface,
      };
      throw error;
    }
  }

  return {
    exactTip:
      finalGate?.ready === true &&
      indexedThroughBlock === finalGate.tipHeight &&
      indexedThroughBlockHash === finalGate.canonicalHash,
    indexedThroughBlock,
    indexedThroughBlockHash,
    tipHash: finalGate?.canonicalHash ?? null,
    tipHeight: Number.isSafeInteger(Number(finalGate?.tipHeight))
      ? Number(finalGate.tipHeight)
      : null,
  };
}

async function summaryPayloadWithCanonicalProvenance(
  payload,
  network,
  requestedFresh,
  surface,
) {
  if (!payload || typeof payload !== "object") {
    throw freshDataUnavailableError(
      `${surface} has no canonical summary payload.`,
    );
  }

  const requiredComponents = summaryPayloadRequiredComponents(payload, surface);
  const componentSnapshotIds = Object.fromEntries(
    requiredComponents.map(([name, candidate]) => [
      name,
      candidate && typeof candidate === "object" && !Array.isArray(candidate)
        ? payloadSnapshotId(candidate)
        : "",
    ]),
  );
  const missingSnapshotIds = Object.entries(componentSnapshotIds)
    .filter(([, snapshotId]) => !snapshotId)
    .map(([name]) => name);
  const snapshotIds = [
    ...new Set(Object.values(componentSnapshotIds).filter(Boolean)),
  ];
  const snapshotId = snapshotIds[0] ?? "";
  const coherent = missingSnapshotIds.length === 0 && snapshotIds.length === 1;
  if (!coherent || (network === "livenet" && !snapshotId)) {
    const error = freshDataUnavailableError(
      `${surface} cannot prove one coherent canonical snapshot.`,
    );
    error.details = {
      code: "CANONICAL_SUMMARY_INCOHERENT",
      coherent,
      componentSnapshotIds,
      missingSnapshotIds,
      snapshotIds,
      surface,
    };
    throw error;
  }

  const checkpoint = await verifiedSummaryPayloadCheckpoint(
    payload,
    network,
    requestedFresh,
    surface,
  );
  const indexedThroughBlock = checkpoint.indexedThroughBlock;
  const tipHeight = checkpoint.tipHeight;
  const lagBlocks =
    Number.isSafeInteger(tipHeight) && indexedThroughBlock > 0
      ? Math.max(0, tipHeight - indexedThroughBlock)
      : null;
  const exactTip = checkpoint.exactTip;
  const ready =
    coherent && exactTip && (network !== "livenet" || Boolean(snapshotId));

  return {
    ...payload,
    provenance: {
      catchingUp: lagBlocks === null ? null : lagBlocks > 0,
      coherent,
      componentSnapshotIds,
      contract: "proof-of-work-canonical-summary-v1",
      generatedAt:
        payload.ledgerGeneratedAt ?? payload.generatedAt ?? payload.indexedAt ?? null,
      indexedThroughBlock: indexedThroughBlock || null,
      indexedThroughBlockHash: checkpoint.indexedThroughBlockHash,
      lagBlocks,
      ready,
      requested: requestedFresh ? "fresh" : "stable",
      served: ready ? "exact-tip" : "last-good",
      snapshotId: snapshotId || null,
      surface,
      tipHash: checkpoint.tipHash,
      tipHeight: Number.isSafeInteger(tipHeight) ? tipHeight : null,
    },
  };
}

function growthSummaryPayloadFromLedger(ledger) {
  const {
    activity,
    activityPayload,
    registryState,
    workFloor,
  } = ledger;
  const tokenState = tokenPayloadWithCurrentWorkActiveListingPolicy(
    ledger.tokenState,
    ledger.network,
  );
  const registrySummary = compactRegistrySummaryPayload(registryState);
  const activitySummary = compactActivitySummaryPayload(
    activityPayload,
    ledger.metrics?.indexedThroughBlock,
  );
  const tokenSummary = compactTokenSummaryPayload(tokenState, "", {
    compactMarketRecords: true,
    includeAllScopedListings: false,
  });
  const registry = attachLedgerMetadata(
    {
      ...registrySummary,
      activity: [],
      listings: [],
      pendingEvents: [],
      records: [],
      sales: [],
    },
    ledger,
  );
  const compactActivity = attachLedgerMetadata(
    {
      ...activitySummary,
      activity: [],
    },
    ledger,
  );
  const token = attachLedgerMetadata(
    {
      ...tokenSummary,
      closedListings: [],
      holders: [],
      invalidEvents: [],
      listings: [],
      mints: [],
      sales: [],
      tokens: [],
      transfers: [],
    },
    ledger,
  );
  const tokenMints = tokenState.mints ?? [];
  const tokenTransfers = tokenState.transfers ?? [];
  const tokenSales = Array.isArray(tokenState.sales) ? tokenState.sales : [];
  const actualValue = workFloor.actualValue;
  const marketplaceStats = marketplaceStatsFromSales(registryState.sales ?? []);
  const confirmedActivity = activity.filter((item) => item.confirmed);
  const events = growthRealEventItems(
    registryState.records ?? [],
    activity,
    registryState.sales ?? [],
    tokenState.tokens ?? [],
    tokenMints,
    tokenTransfers,
    tokenSales,
  ).slice(0, SUMMARY_ACTIVITY_LIMIT);
  const confirmedTokenSales = tokenSales.filter((sale) => sale.confirmed).length;

  return {
    actualValue,
    activity: compactActivity,
    btcUsd: workFloor.btcUsd,
    btcUsdIndexedAt: workFloor.btcUsdIndexedAt,
    counts: {
      browserActions: confirmedActivity.filter(isBrowserActivityItem).length,
      confirmedComputerActions: ledger.metrics.confirmedComputerActions,
      confirmedTokenDefinitions: (tokenState.tokens ?? []).filter(
        (item) => item.confirmed,
      ).length,
      confirmedTokenMints: ledger.metrics.confirmedTokenMints,
      confirmedTokenSales,
      confirmedTokenTransfers: tokenTransfers.filter((item) => item.confirmed)
        .length,
      driveActions: confirmedActivity.filter(
        (item) => item.kind === "file" && !isBrowserActivityItem(item),
      ).length,
      idListings: (registryState.listings ?? []).length,
      inceptionBondActions: confirmedActivity.filter(isInceptionBondActivityItem)
        .length,
      infinityBondActions: confirmedActivity.filter(isInfinityBondActivityItem)
        .length,
      mailActions: confirmedActivity.filter(
        (item) =>
          (item.kind === "mail" || item.kind === "reply") &&
          !isBondActivityItem(item),
      ).length,
      marketplaceSaleCount: marketplaceStats.confirmedSales + confirmedTokenSales,
      pendingRecords: (registryState.records ?? []).filter(
        (record) => !record.confirmed,
      ).length,
      powids: actualValue.powids,
      tokenCount: (tokenState.tokens ?? []).length,
    },
    events,
    indexedAt: ledger.generatedAt,
    network: ledger.network,
    registry,
    summaryOnly: true,
    token,
    usdSource: workFloor.usdSource,
    usdSourceUrl: workFloor.usdSourceUrl,
    workFloor: attachLedgerMetadata(workFloor, ledger),
  };
}

