function bondSummaryPayloadFromLedger(ledger, config) {
  const tokenState = ledgerTokenStateForScope(ledger, config.tokenId);
  const token = attachLedgerMetadata(
    compactTokenSummaryPayload(tokenState, config.tokenId, {
      compactMarketRecords: true,
      includeAllScopedListings: false,
    }),
    ledger,
  );
  const activity = Array.isArray(ledger?.activity) ? ledger.activity : [];
  const confirmedActivity = activity.filter((item) => item?.confirmed);
  const confirmedBondActions = confirmedActivity.filter(
    (item) =>
      isBondActivityItem(item, config) &&
      (config.tokenId !== INCB_TOKEN_ID ||
        !inceptionBondHasExplicitlyRejectedMint(item, tokenState)),
  );
  const confirmedTransfers = (tokenState?.transfers ?? []).filter(
    (transfer) => transfer?.confirmed && transfer.tokenId === config.tokenId,
  );
  const confirmedSales = (tokenState?.sales ?? []).filter(
    (sale) => sale?.confirmed && sale.tokenId === config.tokenId,
  );
  const sumIntegerValues = (items, valueFromItem) =>
    items.reduce((total, item) => {
      const value = integerBigInt(valueFromItem(item), { allowZero: true });
      return value === null ? total : total + value;
    }, 0n);
  const bondMintFlow = sumIntegerValues(
    confirmedBondActions,
    activityAmountSats,
  );
  const bondSaleVolume = sumIntegerValues(
    confirmedSales,
    (sale) => sale.priceSats,
  );
  const bondTransferFee = sumIntegerValues(
    confirmedTransfers,
    (transfer) => transfer.paidSats,
  );
  const confirmedMarketplaceMutations = uniqueMarketplaceMutationActivity(
    confirmedActivity.filter((item) => item?.tokenId === config.tokenId),
    TOKEN_MARKETPLACE_MUTATION_KINDS,
  );
  const bondMarketplaceMutationFee = sumIntegerValues(
    confirmedMarketplaceMutations,
    marketplaceMutationPaymentSats,
  );
  const baseNetworkValue =
    bondMintFlow +
    bondSaleVolume +
    bondTransferFee +
    bondMarketplaceMutationFee;
  const attachedWork = bondAttachedWorkValueDetails(
    ledger,
    confirmedBondActions,
    config,
  );
  const issuance =
    config.tokenId === INCB_TOKEN_ID
      ? inceptionIssuanceMetadataFromMints(tokenState?.mints)
      : null;
  const inceptionAttachmentProjection = issuance
    ? inceptionAttachedWorkProjectionFromIssuance(
        issuance,
        exactWorkAmountStorageModelFromState(
          ledgerTokenStateForScope(ledger, WORK_TOKEN_ID),
        ),
      )
    : null;
  const bondMarketFlow =
    bondSaleVolume + bondTransferFee + bondMarketplaceMutationFee;
  const baseNetworkValueQ8 = baseNetworkValue * BOND_VALUE_Q8_SCALE;
  const marketFlowQ8 = bondMarketFlow * BOND_VALUE_Q8_SCALE;
  const issuanceNetworkValueQ8 = integerBigInt(
    issuance?.issuanceNetworkValueQ8 ?? "0",
    { allowZero: true },
  ) ?? 0n;
  const inceptionFixedNetworkValueQ8 = issuanceNetworkValueQ8 + marketFlowQ8;
  const attachedWorkFrozenValueQ8 = integerBigInt(
    attachedWork.attachedWorkFrozenValueQ8 ?? "0",
    { allowZero: true },
  ) ?? 0n;
  const attachedWorkLiveValueQ8 = integerBigInt(
    attachedWork.attachedWorkLiveValueQ8 ?? "0",
    { allowZero: true },
  ) ?? 0n;
  const frozenNetworkValueQ8 =
    config.tokenId === INCB_TOKEN_ID
      ? inceptionFixedNetworkValueQ8
      : baseNetworkValueQ8 + attachedWorkFrozenValueQ8;
  const liveNetworkValueQ8 =
    config.tokenId === INCB_TOKEN_ID
      ? inceptionFixedNetworkValueQ8
      : baseNetworkValueQ8 + attachedWorkLiveValueQ8;
  const networkValueQ8 = liveNetworkValueQ8;
  const confirmedSupply =
    canonicalIntegerText(tokenState?.confirmedSupply, { allowZero: true }) ||
    "0";
  const pendingSupply =
    canonicalIntegerText(tokenState?.pendingSupply, { allowZero: true }) ||
    "0";
  const confirmedSupplyUnits = BigInt(confirmedSupply);
  const frozenFloorQ8 =
    confirmedSupplyUnits > 0n
      ? frozenNetworkValueQ8 / confirmedSupplyUnits
      : 0n;
  const liveFloorQ8 =
    confirmedSupplyUnits > 0n
      ? liveNetworkValueQ8 / confirmedSupplyUnits
      : 0n;
  const floorQ8 = liveFloorQ8;
  const bondMintFlowSats = bondMintFlow.toString();
  const bondSaleVolumeSats = bondSaleVolume.toString();
  const bondTransferFeeSats = bondTransferFee.toString();
  const bondMarketplaceMutationFeeSats =
    bondMarketplaceMutationFee.toString();
  const baseNetworkValueSats = decimalTextFromQ8(baseNetworkValueQ8);
  const frozenNetworkValueSats = decimalTextFromQ8(frozenNetworkValueQ8);
  const liveNetworkValueSats = decimalTextFromQ8(liveNetworkValueQ8);
  const networkValueSats = decimalTextFromQ8(networkValueQ8);
  const frozenFloorSats = decimalTextFromQ8(frozenFloorQ8);
  const liveFloorSats = decimalTextFromQ8(liveFloorQ8);
  const floorSats = decimalTextFromQ8(floorQ8);
  const btcUsdMetadata = btcUsdResponseMetadata(ledger?.btcUsdQuote);
  const floorUsd =
    btcUsdMetadata.btcUsd > 0
      ? satsToUsdAtBtcUsd(Number(floorSats), btcUsdMetadata.btcUsd)
      : 0;
  const networkUsd =
    btcUsdMetadata.btcUsd > 0
      ? satsToUsdAtBtcUsd(Number(networkValueSats), btcUsdMetadata.btcUsd)
      : 0;
  const chartPoints = infinityBondChartPointsFromEvents({
    bonds: confirmedBondActions,
    marketplaceMutations: confirmedMarketplaceMutations,
    sales: confirmedSales,
    transfers: confirmedTransfers,
  }, config, {
    bondFrozenValueByTxid: attachedWork.attachedWorkFrozenValueByTxid,
    bondFrozenValueQ8ByTxid:
      attachedWork.attachedWorkFrozenValueQ8ByTxid,
    bondSupplyByTxid: attachedWork.bondIssuanceByTxid,
    bondValueByTxid: attachedWork.bondIssuanceNetworkValueByTxid,
    bondValueQ8ByTxid:
      attachedWork.bondIssuanceNetworkValueQ8ByTxid,
  });

  return {
    ...btcUsdMetadata,
    actualValue: {
      attachedWorkActions: attachedWork.attachedWorkActions,
      ...(config.tokenId === INCB_TOKEN_ID
        ? inceptionAttachmentProjection ?? {}
        : {
            attachedWorkAmount: attachedWork.attachedWorkAmount,
            ...(attachedWork?.attachedWorkAmountAtoms !== undefined
              ? {
                  attachedWorkAmountAtoms:
                    attachedWork.attachedWorkAmountAtoms,
                }
              : {}),
          }),
      attachedWorkIssuanceUnits:
        issuance?.attachedWorkIssuanceUnits ?? 0,
      attachedWorkLiveFloorAtSendSats:
        issuance?.attachedWorkLiveFloorAtSendSats ?? 0,
      attachedWorkLiveFloorAtSendQ8:
        issuance?.attachedWorkLiveFloorAtSendQ8 ?? "0",
      attachedWorkLiveValueAtSendSats:
        issuance?.attachedWorkLiveValueAtSendSats ?? 0,
      attachedWorkLiveValueAtSendQ8:
        issuance?.attachedWorkLiveValueAtSendQ8 ?? "0",
      attachmentAccountingModel:
        config.tokenId === INCB_TOKEN_ID
          ? INCEPTION_ATTACHMENT_ACCOUNTING_MODEL
          : undefined,
      attachedWorkFrozenValueSats:
        attachedWork.attachedWorkFrozenValueSats,
      attachedWorkFrozenValueQ8:
        attachedWork.attachedWorkFrozenValueQ8,
      attachedWorkLiveValueSats: attachedWork.attachedWorkLiveValueSats,
      attachedWorkLiveValueQ8: attachedWork.attachedWorkLiveValueQ8,
      attachedWorkUnmatchedActions:
        attachedWork.attachedWorkUnmatchedActions,
      attachedWorkUnvaluedActions:
        attachedWork.attachedWorkUnvaluedActions,
      bondMarketplaceMutationFeeSats,
      bondMintFlowSats,
      bondSaleVolumeSats,
      bondTransferFeeSats,
      baseNetworkValueSats,
      baseNetworkValueQ8: baseNetworkValueQ8.toString(),
      confirmedIssuanceUnits: issuance?.confirmedIssuanceUnits ?? 0,
      directProofIssuanceUnits:
        issuance?.directProofIssuanceUnits ?? 0,
      floorSats,
      floorQ8: floorQ8.toString(),
      floorUsd,
      frozenFloorSats,
      frozenFloorQ8: frozenFloorQ8.toString(),
      frozenNetworkValueSats,
      frozenNetworkValueQ8: frozenNetworkValueQ8.toString(),
      issuanceAccountingModel:
        config.tokenId === INCB_TOKEN_ID
          ? INCEPTION_ISSUANCE_ACCOUNTING_MODEL
          : undefined,
      issuanceUnitSats:
        config.tokenId === INCB_TOKEN_ID ? 1 : undefined,
      issuanceValuationFixedAtSend:
        config.tokenId === INCB_TOKEN_ID ? true : undefined,
      issuanceCheckpointBlockHash:
        issuance?.issuanceCheckpointBlockHash ?? "",
      issuanceCheckpointBlockHeight:
        issuance?.issuanceCheckpointBlockHeight ?? 0,
      issuanceCheckpointBlockIndex:
        issuance?.issuanceCheckpointBlockIndex ?? 0,
      issuanceCheckpointMode:
        config.tokenId === INCB_TOKEN_ID
          ? issuance?.issuanceCheckpointMode ?? ""
          : undefined,
      issuanceValueSnapshotBlockHash:
        issuance?.issuanceValueSnapshotBlockHash ?? "",
      issuanceValueSnapshotBlockHeight:
        issuance?.issuanceValueSnapshotBlockHeight ?? 0,
      issuanceValueSnapshotCanonicalSummaryHash:
        issuance?.issuanceValueSnapshotCanonicalSummaryHash ?? "",
      issuanceValueSnapshotGeneratedAt:
        issuance?.issuanceValueSnapshotGeneratedAt ?? "",
      issuanceValueSnapshotId:
        issuance?.issuanceValueSnapshotId ?? "",
      issuanceValueSnapshotMode:
        config.tokenId === INCB_TOKEN_ID
          ? issuance?.issuanceValueSnapshotMode ?? ""
          : undefined,
      issuanceValueSnapshotModel:
        config.tokenId === INCB_TOKEN_ID
          ? issuance?.issuanceValueSnapshotModel ?? ""
          : undefined,
      issuanceValueSnapshotWorkNetworkValueSats:
        issuance?.issuanceValueSnapshotWorkNetworkValueSats ?? 0,
      issuanceValueSnapshotWorkNetworkValueQ8:
        issuance?.issuanceValueSnapshotWorkNetworkValueQ8 ?? "0",
      issuanceDustSats: issuance?.issuanceDustSats ?? 0,
      issuanceDustQ8: issuance?.issuanceDustQ8 ?? "0",
      issuanceFloorSats: issuance?.issuanceFloorSats ?? 0,
      issuanceFloorQ8: issuance?.issuanceFloorQ8 ?? "0",
      issuanceNetworkValueSats:
        issuance?.issuanceNetworkValueSats ?? 0,
      issuanceNetworkValueQ8:
        issuance?.issuanceNetworkValueQ8 ?? "0",
      liveFloorSats,
      liveFloorQ8: liveFloorQ8.toString(),
      liveNetworkValueSats,
      liveNetworkValueQ8: liveNetworkValueQ8.toString(),
      networkValueAccountingModel:
        config.tokenId === INCB_TOKEN_ID
          ? INCEPTION_NETWORK_VALUE_ACCOUNTING_MODEL
          : undefined,
      networkValueSats,
      networkValueQ8: networkValueQ8.toString(),
      networkUsd,
      totalSats: networkValueSats,
      totalUsd: networkUsd,
    },
    chartPoints,
    floorSats,
    floorQ8: floorQ8.toString(),
    floorUsd,
    frozenFloorSats,
    frozenFloorQ8: frozenFloorQ8.toString(),
    frozenNetworkValueSats,
    frozenNetworkValueQ8: frozenNetworkValueQ8.toString(),
    indexedAt: ledger.generatedAt,
    indexedThroughBlock:
      ledger.indexedThroughBlock ??
      ledger.metrics?.indexedThroughBlock ??
      tokenState?.indexedThroughBlock,
    network: ledger.network,
    liveFloorSats,
    liveFloorQ8: liveFloorQ8.toString(),
    liveNetworkValueSats,
    liveNetworkValueQ8: liveNetworkValueQ8.toString(),
    networkValueSats,
    networkValueQ8: networkValueQ8.toString(),
    registryAddress: tokenState?.tokens?.[0]?.registryAddress ?? "",
    registryId: config.registryId,
    source: tokenState?.source,
    stats: {
      confirmedAttachedWorkActions: attachedWork.attachedWorkActions,
      confirmedBondActions: confirmedBondActions.length,
      confirmedListings: (tokenState?.listings ?? []).filter(
        (listing) => listing.confirmed,
      ).length,
      confirmedSales: confirmedSales.length,
      confirmedSupply,
      confirmedTransfers: confirmedTransfers.length,
      holders: (tokenState?.holders ?? []).length,
      pendingBondActions: (tokenState?.mints ?? []).filter(
        (mint) => !mint.confirmed && mint.tokenId === config.tokenId,
      ).length,
      pendingSupply,
    },
    ticker: config.ticker,
    token,
    tokenId: config.tokenId,
  };
}

function ledgerConsistencyPayloadFromLedger(ledger) {
  const growthSummary = ledger.growthSummary;
  return {
    checks: ledger.consistency.checks,
    generatedAt: ledger.generatedAt,
    indexedThroughBlock: ledger.metrics.indexedThroughBlock,
    ...(payloadIndexedThroughBlockHash(ledger)
      ? { indexedThroughBlockHash: payloadIndexedThroughBlockHash(ledger) }
      : {}),
    metrics: ledger.metrics,
    missingLogEvents: ledger.consistency.missingLogEvents,
    network: ledger.network,
    ok: ledger.consistency.ok,
    snapshotId: ledger.snapshotId,
    sourceHashes: ledger.sourceHashes,
    status: ledger.consistency.status,
    totals: {
      growthActualValueSats: numericValue(growthSummary?.actualValue?.totalSats),
      growthWorkFloorValueSats: numericValue(
        growthSummary?.workFloor?.networkValueSats,
      ),
      workActualValueSats: numericValue(
        ledger.workFloor?.actualValue?.totalSats,
      ),
      workNetworkValueSats: numericValue(ledger.workFloor?.networkValueSats),
    },
  };
}

function replaceLedgerConsistencyCheck(checks, name, ok, details = {}) {
  const nextChecks = Array.isArray(checks) ? checks : [];
  let found = false;
  const replaced = nextChecks.map((check) => {
    if (check?.name !== name) {
      return check;
    }
    found = true;
    return {
      ...check,
      details,
      name,
      ok,
    };
  });
  if (!found) {
    replaced.push({ details, name, ok });
  }
  return replaced;
}

function replaceLedgerConsistencyChecks(checks, replacements) {
  return replacements.reduce(
    (nextChecks, replacement) =>
      replaceLedgerConsistencyCheck(
        nextChecks,
        replacement.name,
        replacement.ok,
        replacement.details,
      ),
    Array.isArray(checks) ? checks : [],
  );
}

async function ledgerConsistencyPayloadWithCurrentSummaries(
  payload,
  ledger,
  network,
  fresh = false,
) {
  if (network !== "livenet" || !payload || !ledger) {
    return payload;
  }

  const workFloor = await currentProofIndexWorkFloorIfNewer(
    ledger.workFloor,
    network,
    fresh,
    "ledger consistency",
  );
  if (!workFloor) {
    return payload;
  }

  const growthSummary = growthSummaryWithCanonicalWorkFloor(
    ledger.growthSummary,
    workFloor,
  );
  const indexedThroughBlock = Math.max(
    numericValue(payload.indexedThroughBlock),
    numericValue(payload.metrics?.indexedThroughBlock),
    proofIndexPayloadIndexedThroughBlock(workFloor),
    proofIndexPayloadIndexedThroughBlock(growthSummary),
  );
  const tipHeight = await ledgerTipHeight(network);
  const sourceTipHeight = Number.isSafeInteger(tipHeight)
    ? tipHeight
    : Number(payload.metrics?.sourceTipHeight) || undefined;
  const tipLagBlocks =
    Number.isSafeInteger(sourceTipHeight) && indexedThroughBlock > 0
      ? Math.max(0, sourceTipHeight - indexedThroughBlock)
      : payload.metrics?.tipLagBlocks;
  const workNetworkValue = numericValue(workFloor.networkValueSats);
  const workActualValue = numericValue(workFloor.actualValue?.totalSats);
  const growthActualValue = numericValue(growthSummary?.actualValue?.totalSats);
  const growthFloorValue = numericValue(
    growthSummary?.workFloor?.networkValueSats,
  );
  const updatedChecks = replaceLedgerConsistencyChecks(payload.checks, [
    {
      details: {
        indexedThroughBlock,
        lagBlocks: Number.isFinite(tipLagBlocks) ? tipLagBlocks : 0,
        maxLagBlocks: PROOF_INDEX_CONFIRMED_READ_MAX_LAG_BLOCKS,
        tipHeight: sourceTipHeight ?? null,
      },
      name: "ledger-covers-node-tip",
      ok:
        !Number.isSafeInteger(sourceTipHeight) ||
        (indexedThroughBlock > 0 &&
          tipLagBlocks <= PROOF_INDEX_CONFIRMED_READ_MAX_LAG_BLOCKS),
    },
    {
      details: {
        growthActualValueSats: growthActualValue,
        growthWorkFloorValueSats: growthFloorValue,
        workActualValueSats: workActualValue,
        workNetworkValueSats: workNetworkValue,
      },
      name: "network-values-finite",
      ok:
        workFloorPayloadHasFiniteNetworkValue(workFloor) &&
        growthSummaryPayloadHasFiniteNetworkValue(growthSummary),
    },
    {
      details: {
        actualValueSats: workActualValue,
        networkValueSats: workNetworkValue,
      },
      name: "work-floor-actual-total",
      ok: numbersAgree(workNetworkValue, workActualValue),
    },
    {
      details: {
        growthValueSats: growthActualValue,
        workValueSats: workNetworkValue,
      },
      name: "growth-actual-total",
      ok: numbersAgree(workNetworkValue, growthActualValue),
    },
    {
      details: {
        growthWorkFloorSats: growthFloorValue,
        workValueSats: workNetworkValue,
      },
      name: "growth-work-floor-total",
      ok: numbersAgree(workNetworkValue, growthFloorValue),
    },
  ]);
  const ok = updatedChecks.every((check) => check?.ok === true);
  return {
    ...payload,
    checks: updatedChecks,
    generatedAt: newerIso(
      newerIso(payload.generatedAt, workFloor.indexedAt),
      growthSummary?.indexedAt,
    ),
    indexedThroughBlock,
    metrics: {
      ...(payload.metrics ?? {}),
      indexedThroughBlock,
      networkValueSats: workNetworkValue,
      sourceTipHeight,
      tipLagBlocks,
    },
    ok,
    snapshotId:
      payloadSnapshotId(workFloor) ||
      payloadSnapshotId(growthSummary) ||
      payload.snapshotId,
    status: ok ? "green" : "red",
    totals: {
      ...(payload.totals ?? {}),
      growthActualValueSats: growthActualValue,
      growthWorkFloorValueSats: growthFloorValue,
      workActualValueSats: workActualValue,
      workNetworkValueSats: workNetworkValue,
    },
  };
}

async function ledgerConsistencyPayload(network, fresh = false) {
  if (network === "livenet") {
    if (!fresh) {
      try {
        const summary = await summaryPayloadWithCanonicalProvenance(
          await activitySummaryPayload(network, false),
          network,
          false,
          "log-summary",
        );
        const summaryHeight = proofIndexPayloadIndexedThroughBlock(summary);
        const summaryHash = payloadIndexedThroughBlockHash(summary);
        const summarySnapshotId = payloadSnapshotId(summary);
        const indexedLedger = await payloadWithFallbackAfterMs(
          proofIndexCanonicalSummaryLedgerPayload(
            network,
            summaryHeight,
            summaryHash,
          ),
          null,
          SUMMARY_PROOF_INDEX_READ_WAIT_MS,
        ).catch((error) => {
          console.error(
            `Proof index pinned consistency read failed: ${errorSummary(error)}`,
          );
          return null;
        });
        if (
          !indexedLedger ||
          proofIndexPayloadIndexedThroughBlock(indexedLedger) !== summaryHeight ||
          payloadIndexedThroughBlockHash(indexedLedger) !== summaryHash ||
          payloadSnapshotId(indexedLedger) !== summarySnapshotId
        ) {
          const error = freshDataUnavailableError(
            "Stable consistency cannot bind to the authenticated canonical summary snapshot.",
          );
          error.details = {
            code: "CANONICAL_CONSISTENCY_SNAPSHOT_MISMATCH",
            indexedLedgerHeight:
              proofIndexPayloadIndexedThroughBlock(indexedLedger) || null,
            indexedLedgerSnapshotId: payloadSnapshotId(indexedLedger) || null,
            summaryHeight: summaryHeight || null,
            summarySnapshotId: summarySnapshotId || null,
          };
          throw error;
        }
        await verifyStableLogCheckpointAfterRead(
          summary,
          network,
          "ledger-consistency",
        );
        const payload = ledgerConsistencyPayloadFromLedger(indexedLedger);
        return {
          ...payload,
          indexedThroughBlockHash: summaryHash,
          provenance: {
            ...(summary.provenance ?? {}),
            surface: "ledger-consistency",
          },
        };
      } catch (error) {
        if (!ENABLE_REQUEST_LEDGER_RECOVERY) {
          throw error;
        }
        console.error(
          `Stable pinned consistency read failed; using explicitly enabled recovery: ${errorSummary(error)}`,
        );
      }
    }

    const indexedLedger = await payloadWithFallbackAfterMs(
      proofIndexCanonicalSummaryLedgerPayload(network),
      null,
      SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    ).catch((error) => {
      console.error(
        `Proof index canonical consistency read failed: ${errorSummary(error)}`,
      );
      return null;
    });
    if (ledgerPayloadHasCurrentChecks(indexedLedger)) {
      const indexedPayload = ledgerConsistencyPayloadFromLedger(indexedLedger);
      if (fresh) {
        try {
          await verifiedSummaryPayloadCheckpoint(
            indexedPayload,
            network,
            true,
            "ledger-consistency",
          );
          return indexedPayload;
        } catch (error) {
          console.error(
            `Rejected non-exact fresh consistency snapshot: ${errorSummary(error)}`,
          );
        }
      } else if (await ledgerPayloadCoversTip(indexedLedger, network)) {
        return indexedPayload;
      }
    }
    if (!ENABLE_REQUEST_LEDGER_RECOVERY) {
      throw freshDataUnavailableError(
        "The canonical consistency snapshot is unavailable.",
      );
    }
  }

  const ledger = await summaryCanonicalLedgerPayload(network, fresh);
  if (ledger) {
    const payload = await ledgerConsistencyPayloadWithCurrentSummaries(
      ledgerConsistencyPayloadFromLedger(ledger),
      ledger,
      network,
      fresh,
    );
    if (fresh) {
      await verifiedSummaryPayloadCheckpoint(
        payload,
        network,
        true,
        "ledger-consistency",
      );
    }
    return payload;
  }

  if (fresh) {
    throw freshDataUnavailableError(
      "Fresh ledger consistency payload is unavailable.",
    );
  }

  const fallbackLedger = await canonicalLedgerPayload(network, false);
  return ledgerConsistencyPayloadWithCurrentSummaries(
    ledgerConsistencyPayloadFromLedger(fallbackLedger),
    fallbackLedger,
    network,
    false,
  );
}

async function ledgerTokenPayload(network, tokenScope = "", fresh = false) {
  const scope = normalizeTokenScope(tokenScope);
  const indexedFallback =
    network === "livenet"
      ? await indexedTokenStateForCanonicalLedger(network, scope)
      : null;
  if (indexedFallback) {
    return fresh
      ? tokenStateWithLivePendingTransactionCheck(indexedFallback, network)
      : tokenStateWithoutDroppedPendingTransactions(indexedFallback, network);
  }
  let fallback = await fastTokenPayloadSnapshot(network, scope, {
    reconcileSpendable: false,
  });
  if (scope === WORK_TOKEN_ID) {
    fallback = await liveWorkTokenStateWithFallbackAfterMs(
      network,
      fallback,
      WORK_TOKEN_LIVE_WAIT_MS,
      { recoverClosedSales: true },
    );
  }
  if (!fresh || (!ENABLE_SUMMARY_TOKEN_REFRESH && scope !== WORK_TOKEN_ID)) {
    return tokenStateWithoutDroppedPendingTransactions(fallback, network);
  }

  const payload = await payloadWithFallbackAfterMs(
    refreshTokenPayload(network, scope),
    null,
    scope === WORK_TOKEN_ID
      ? WORK_TOKEN_CANONICAL_FRESH_WAIT_MS
      : Math.max(WORK_TOKEN_CANONICAL_FRESH_WAIT_MS, TOKEN_SCOPED_FRESH_WAIT_MS),
  );
  if (payload) {
    return tokenStateWithLivePendingTransactionCheck(payload, network);
  }
  if (
    fallback &&
    (await proofIndexPayloadCoversConfirmedTip(
      fallback,
      network,
      `ledger-token-fallback:${scope || "all"}`,
    ))
  ) {
    return tokenStateWithLivePendingTransactionCheck(fallback, network);
  }
  throw freshDataUnavailableError(
    `Fresh ledger token payload is unavailable for ${scope || "all"}.`,
  );
}

async function indexedActivityStateForCanonicalLedger(network, options = {}) {
  if (
    network !== "livenet" ||
    !proofIndexReadFeatureEnabled("log-history,activity-history,log,event-history")
  ) {
    return null;
  }

  const payload = await proofIndexCanonicalActivityPayload(network).catch(
    (error) => {
      console.error(
        `Proof index canonical activity read failed: ${errorSummary(error)}`,
      );
      return null;
    },
  );
  if (!payload?.activity?.length) {
    return null;
  }
  const canonicalMinerFeeCoverage =
    payload.canonicalMinerFeeCoverage ??
    payload.stats?.canonicalMinerFeeCoverage;
  const verifiedMinerFeeCoverage = verifiedCanonicalMinerFeeCoverage(
    canonicalMinerFeeCoverage,
  );
  if (
    options.requireCanonicalMinerFeeCoverage !== false &&
    !verifiedMinerFeeCoverage
  ) {
    console.error(
      `Rejected canonical activity: normalized miner-fee coverage is incomplete for ${Number(canonicalMinerFeeCoverage?.missingConfirmedEvents) || 0} confirmed event(s) across ${Number(canonicalMinerFeeCoverage?.missingConfirmedTransactions) || 0} transaction(s).`,
    );
    return null;
  }
  const exactHeight = Number(options.exactHeight);
  if (Number.isSafeInteger(exactHeight) && exactHeight > 0) {
    if (proofIndexPayloadIndexedThroughBlock(payload) !== exactHeight) {
      console.error(
        `Rejected canonical activity: coverage is not exact at block ${exactHeight}.`,
      );
      return null;
    }
  } else if (
    !(await proofIndexPayloadCoversConfirmedTip(
      payload,
      network,
      "canonical-activity",
    ))
  ) {
    return null;
  }
  return verifiedMinerFeeCoverage
    ? {
        ...payload,
        canonicalMinerFeeCoverage: verifiedMinerFeeCoverage,
      }
    : payload;
}

async function activityStateForCanonicalLedger(network, fresh) {
  const indexedActivity = await indexedActivityStateForCanonicalLedger(network);
  if (indexedActivity) {
    return indexedActivity;
  }
  if (network === "livenet") {
    throw freshDataUnavailableError(
      "Canonical activity with complete normalized miner-fee coverage is unavailable.",
    );
  }
  return fresh && ENABLE_GLOBAL_ACTIVITY_CRAWL
    ? globalActivityPayload(network, true)
    : cachedGlobalActivityPayloadNoRefresh(network);
}

async function indexedRegistryStateForCanonicalLedger(network, options = {}) {
  if (network !== "livenet") {
    return null;
  }

  const exactHeight = Number(options.exactHeight);
  const exactHash = String(options.exactHash ?? "").trim().toLowerCase();
  if (
    Number.isSafeInteger(exactHeight) &&
    exactHeight > 0 &&
    !/^[0-9a-f]{64}$/u.test(exactHash)
  ) {
    console.error(
      `Rejected canonical registry state: checkpoint hash is invalid at block ${exactHeight}.`,
    );
    return null;
  }
  const payload = await indexedRegistryPayload(network, {
    exactHash,
    exactHeight,
  });
  if (!payload) {
    return null;
  }
  if (Number.isSafeInteger(exactHeight) && exactHeight > 0) {
    if (
      proofIndexPayloadIndexedThroughBlock(payload) !== exactHeight ||
      String(payload?.indexedThroughBlockHash ?? "")
        .trim()
        .toLowerCase() !== exactHash
    ) {
      console.error(
        `Rejected canonical registry state: coverage is not exact and hash-bound at block ${exactHeight}.`,
      );
      return null;
    }
    return payload;
  }
  return (await proofIndexPayloadCoversConfirmedTip(
    payload,
    network,
    "canonical-registry-state",
  ))
    ? payload
    : null;
}

async function indexedTokenStateForCanonicalLedger(network, scope = "") {
  const tokenScope = normalizeTokenScope(scope);
  if (
    network !== "livenet" ||
    !proofIndexReadFeatureEnabled("token-state,token-default,token")
  ) {
    return null;
  }

  const params = new URLSearchParams();
  if (tokenScope) {
    params.set("asset", tokenScope);
  }
  const payload = await proofIndexTokenPayload(network, tokenScope, params).catch(
    (error) => {
      console.error(
        `Proof index canonical token-state read failed for ${tokenScope || "all"}: ${errorSummary(error)}`,
      );
      return null;
    },
  );
  if (!payload) {
    return null;
  }
  if (
    !(await proofIndexPayloadCoversConfirmedTip(
      payload,
      network,
      `canonical-token-state:${tokenScope || "all"}`,
    ))
  ) {
    return null;
  }
  return tokenStateWithoutDroppedPendingTransactions(payload, network);
}

const INDEXED_REGISTRY_ACTIVITY_KINDS = new Set([
  "id-buy",
  "id-delist",
  "id-list",
  "id-register",
  "id-seal",
  "id-transfer",
  "id-update",
]);

function indexedActivityValue(item, ...keys) {
  for (const key of keys) {
    const value = item?.[key];
    if (value !== undefined && value !== null && value !== "") {
      return value;
    }
  }
  return "";
}

function registryStateFromIndexedActivity(network, activityState) {
  if (!Array.isArray(activityState?.activity)) {
    return null;
  }

  const activity = dedupeActivityItems(
    activityState.activity.filter((item) =>
      INDEXED_REGISTRY_ACTIVITY_KINDS.has(String(item?.kind ?? "")),
    ),
  );
  if (activity.length === 0) {
    return null;
  }

  const sorted = [...activity].sort(
    (left, right) =>
      Date.parse(left.createdAt ?? "") - Date.parse(right.createdAt ?? "") ||
      compareCanonicalUtf8(left.txid, right.txid),
  );
  const recordsById = new Map();
  const listingsById = new Map();
  const sales = [];

  for (const item of sorted) {
    const id = String(item?.id ?? "").trim().toLowerCase();
    if (item.kind === "id-register" && id) {
      recordsById.set(id, {
        amountSats: activityAmountSats(item),
        blockHeight: numericValue(item.blockHeight),
        confirmed: item.confirmed !== false,
        createdAt: item.createdAt,
        id,
        network,
        ownerAddress: indexedActivityValue(
          item,
          "ownerAddress",
          "currentOwnerAddress",
          "actor",
        ),
        receiveAddress: indexedActivityValue(
          item,
          "receiveAddress",
          "currentReceiveAddress",
          "counterparty",
        ),
        txid: item.txid,
      });
      continue;
    }

    if ((item.kind === "id-update" || item.kind === "id-transfer") && id) {
      const record = recordsById.get(id);
      if (!record) {
        continue;
      }
      const ownerAddress = indexedActivityValue(
        item,
        "ownerAddress",
        "currentOwnerAddress",
        "actor",
      );
      const receiveAddress = indexedActivityValue(
        item,
        "receiveAddress",
        "currentReceiveAddress",
        "counterparty",
      );
      recordsById.set(id, {
        ...record,
        ownerAddress: ownerAddress || record.ownerAddress,
        receiveAddress: receiveAddress || record.receiveAddress,
        updatedAt: item.createdAt,
      });
      continue;
    }

    if (item.kind === "id-list") {
      const listingId = String(item.listingId ?? item.txid ?? "").toLowerCase();
      if (!listingId) {
        continue;
      }
      listingsById.set(listingId, {
        amountSats: activityAmountSats(item),
        blockHeight: numericValue(item.blockHeight),
        confirmed: item.confirmed !== false,
        createdAt: item.createdAt,
        id,
        listingId,
        network,
        priceSats: numericValue(
          item.priceSats ??
            item.salePriceSats ??
            item.saleAuthorization?.priceSats,
        ),
        saleAuthorization: item.saleAuthorization,
        sellerAddress: indexedActivityValue(
          item,
          "sellerAddress",
          "ownerAddress",
          "actor",
        ),
        txid: item.txid,
      });
      continue;
    }

    if (item.kind === "id-delist") {
      const listingId = String(item.listingId ?? "").toLowerCase();
      if (listingId) {
        listingsById.delete(listingId);
      }
      continue;
    }

    if (item.kind === "id-buy") {
      const listingId = String(item.listingId ?? "").toLowerCase();
      if (listingId) {
        listingsById.delete(listingId);
      }
      const priceSats = numericValue(
        item.priceSats ??
          item.salePriceSats ??
          item.saleAuthorization?.priceSats,
      );
      if (id) {
        const record = recordsById.get(id);
        if (record) {
          const ownerAddress = indexedActivityValue(
            item,
            "ownerAddress",
            "buyerAddress",
            "actor",
          );
          const receiveAddress = indexedActivityValue(
            item,
            "receiveAddress",
            "currentReceiveAddress",
          );
          recordsById.set(id, {
            ...record,
            ownerAddress: ownerAddress || record.ownerAddress,
            receiveAddress:
              receiveAddress || ownerAddress || record.receiveAddress,
            updatedAt: item.createdAt,
          });
        }
      }
      sales.push({
        amountSats: activityAmountSats(item),
        buyerAddress: indexedActivityValue(
          item,
          "ownerAddress",
          "buyerAddress",
          "actor",
        ),
        confirmed: item.confirmed !== false,
        createdAt: item.createdAt,
        id,
        listingId,
        network,
        priceSats,
        sellerAddress: indexedActivityValue(item, "sellerAddress", "counterparty"),
        transferVersion: item.transferVersion ?? "buy5",
        txid: item.txid,
      });
    }
  }

  const records = [...recordsById.values()].sort(
    (left, right) =>
      compareCanonicalUtf8(left.id, right.id) ||
      compareCanonicalUtf8(left.txid, right.txid),
  );
  const listings = [...listingsById.values()].sort(compareActivityItems);
  const marketplaceStats = marketplaceStatsFromSales(sales);

  return {
    activity,
    indexedAt: activityState.indexedAt ?? new Date().toISOString(),
    indexedThroughBlock:
      activityState.indexedThroughBlock ??
      activityState.stats?.indexedThroughBlock ??
      indexedThroughBlockFromItems(activity),
    listings,
    network,
    pendingEvents: [],
    records,
    registryAddress: registryAddressForNetwork(network) ?? "",
    sales,
    source: mergedSourceLabel(
      activityState.source,
      "proof-indexer-derived-registry",
    ),
    stats: {
      confirmed: records.filter((record) => record.confirmed).length,
      confirmedSales: marketplaceStats.confirmedSales,
      confirmedSalesVolumeSats: marketplaceStats.confirmedVolumeSats,
      pending: 0,
      pendingChanges: 0,
      pendingRecords: 0,
      pendingSales: marketplaceStats.pendingSales,
      pendingSalesVolumeSats: marketplaceStats.pendingVolumeSats,
      sales: marketplaceStats.totalSales,
      salesVolumeSats: marketplaceStats.totalVolumeSats,
      total: records.length,
      transactions: new Set(activity.map((item) => item.txid).filter(Boolean))
        .size,
    },
  };
}

function formattedNumberValue(value) {
  const normalized = String(value ?? "").replace(/,/gu, "").trim();
  const number = Number(normalized);
  return Number.isFinite(number) ? number : 0;
}

function tokenTickerFromActivityItem(item) {
  const direct = String(item?.ticker ?? "").trim().toUpperCase();
  if (direct) {
    return direct;
  }
  const detailMatch = /^\s*[0-9,]+\s+([A-Z0-9]{1,12})\s+for\s+[0-9,]+/u.exec(
    String(item?.detail ?? ""),
  );
  if (detailMatch) {
    return detailMatch[1];
  }
  const tags = Array.isArray(item?.tags) ? item.tags : [];
  return (
    tags
      .map((tag) => String(tag ?? "").trim().toUpperCase())
      .find((tag) => /^[A-Z0-9]{1,12}$/u.test(tag)) ?? ""
  );
}

function canonicalMinerFeeDetailsFromActivity(item) {
  return item?.canonicalMinerFeeCovered === true
    ? {
        canonicalMinerFeeCovered: true,
        canonicalMinerFeeSats: numericValue(item.canonicalMinerFeeSats),
      }
    : {};
}

function canonicalCreditValueFieldsFromRecord(item) {
  const fields = {};
  for (const [q8Field, decimalField] of [
    ["creditFloorAtConfirmQ8", "creditFloorAtConfirmSats"],
    ["creditLiveFloorQ8", "creditLiveFloorSats"],
    ["creditLiveValueQ8", "creditLiveValueSats"],
    ["creditRevaluationFloorQ8", "creditRevaluationFloorSats"],
    ["creditValueAtConfirmQ8", "creditValueAtConfirmSats"],
    ["fixedEventFlowQ8", "fixedEventFlowSats"],
    ["frozenNetworkValueQ8", "frozenNetworkValueSats"],
    [
      "liveNetworkValueBeforeEventQ8",
      "liveNetworkValueBeforeEventSats",
    ],
    ["liveNetworkValueQ8", "liveNetworkValueSats"],
    ["networkValueBeforeEventQ8", "networkValueBeforeEventSats"],
  ]) {
    const q8 = canonicalNonNegativeIntegerText(item?.[q8Field]);
    if (q8) {
      fields[q8Field] = q8;
      fields[decimalField] = q8ToCanonicalDecimal(q8);
    }
  }
  return fields;
}

function tokenDefinitionFromIndexedCreate(
  item,
  network,
  workAmountStorageModel = WORK_ATOMIC_PROJECTION_MODEL,
) {
  const tokenId = String(item?.tokenId ?? item?.txid ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(tokenId)) {
    return null;
  }
  if (tokenId === WORK_TOKEN_ID) {
    return canonicalWorkTokenDefinition(
      network,
      workAmountStorageModel,
    );
  }
  if (tokenId === POWB_TOKEN_ID) {
    return {
      ...canonicalPowbTokenDefinition(
        network,
        indexedActivityValue(item, "actor", "creatorAddress"),
      ),
      confirmed: item.confirmed !== false,
    };
  }
  if (tokenId === INCB_TOKEN_ID) {
    return {
      ...canonicalIncbTokenDefinition(
        network,
        indexedActivityValue(item, "actor", "creatorAddress"),
      ),
      confirmed: item.confirmed !== false,
    };
  }

  const detail = String(item?.detail ?? "");
  const description = String(item?.description ?? "");
  const detailMatch = /^\s*([0-9,]+)\s+([A-Z0-9]{1,12})\s+for\s+([0-9,]+)\s+proofs/u.exec(
    detail,
  );
  const maxSupplyMatch = /with\s+([0-9,]+)\s+max supply/iu.exec(description);
  const participants = Array.isArray(item?.participants) ? item.participants : [];
  const actor = indexedActivityValue(item, "actor", "creatorAddress");
  const registryAddress =
    indexedActivityValue(item, "registryAddress") ||
    participants.find(
      (address) =>
        address &&
        address !== actor &&
        isValidBitcoinAddress(String(address), network),
    ) ||
    indexedActivityValue(item, "counterparty");
  const ticker = tokenTickerFromActivityItem(item);
  const maxSupply =
    formattedNumberValue(item?.maxSupply) ||
    formattedNumberValue(maxSupplyMatch?.[1]);
  const mintAmount =
    formattedNumberValue(item?.mintAmount) ||
    formattedNumberValue(detailMatch?.[1]);
  const mintPriceSats =
    formattedNumberValue(item?.mintPriceSats) ||
    formattedNumberValue(detailMatch?.[3]);
  if (
    !ticker ||
    maxSupply <= 0 ||
    mintAmount <= 0 ||
    mintPriceSats <= 0 ||
    !isValidBitcoinAddress(String(registryAddress ?? ""), network)
  ) {
    return null;
  }

  return {
    confirmed: item.confirmed !== false,
    createdAt: item.createdAt,
    creationFeeSats: numericValue(
      item.proofPaymentSats ?? item.paidSats ?? item.amountSats,
    ),
    creatorAddress: actor,
    dataBytes: numericValue(item.dataBytes),
    maxSupply,
    mintAmount,
    mintPriceSats,
    ...canonicalMinerFeeDetailsFromActivity(item),
    minerFeeSats: numericValue(item.minerFeeSats),
    network,
    registryAddress,
    ticker,
    tokenId,
    txid: tokenId,
  };
}

function creditAmountFromActivityItem(item, ticker = "") {
  const direct = numericValue(
    item?.amount ?? item?.tokenAmount ?? item?.creditAmountMoved,
  );
  if (direct > 0) {
    return direct;
  }
  const normalizedTicker = String(ticker ?? "").trim();
  if (!normalizedTicker) {
    return 0;
  }
  const pattern = new RegExp(
    `([0-9][0-9,]*(?:\\.[0-9]{1,8})?)\\s+${normalizedTicker.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&")}`,
    "iu",
  );
  const values = [
    item?.description,
    item?.detail,
    ...(Array.isArray(item?.tags) ? item.tags : []),
  ];
  for (const value of values) {
    const match = pattern.exec(String(value ?? ""));
    const amount = formattedNumberValue(match?.[1]);
    if (amount > 0) {
      return amount;
    }
  }
  return 0;
}

function creditSalePriceFromActivityItem(item) {
  const direct = numericValue(
    item?.priceSats ?? item?.salePriceSats ?? item?.saleAuthorization?.priceSats,
  );
  if (direct > 0) {
    return direct;
  }

  const values = [
    item?.description,
    item?.detail,
    ...(Array.isArray(item?.tags) ? item.tags : []),
  ];
  for (const value of values) {
    const text = String(value ?? "");
    const tagMatch = /^\s*([0-9][0-9,]*)\s+sale\s+proofs\s*$/iu.exec(text);
    const proseMatch = /\bfor\s+([0-9][0-9,]*)\s+proofs\b/iu.exec(text);
    const amount = formattedNumberValue(tagMatch?.[1] ?? proseMatch?.[1]);
    if (amount > 0) {
      return amount;
    }
  }
  return 0;
}

async function completeTokenMarketOverlayItems(network, scope, kind) {
  const items = [];
  const params = new URLSearchParams();
  params.set("limit", "500");
  let cursor = "";
  for (let page = 0; page < 20; page += 1) {
    if (cursor) {
      params.set("cursor", cursor);
    } else {
      params.delete("cursor");
    }
    const payload = await proofIndexTokenMarketHistoryOverlayPayload(
      network,
      scope,
      kind,
      params,
    ).catch((error) => {
      console.error(
        `Proof index token market ${kind} overlay read failed: ${errorSummary(error)}`,
      );
      return null;
    });
    if (!payload) {
      break;
    }
    items.push(...(Array.isArray(payload.items) ? payload.items : []));
    cursor = String(payload.nextCursor ?? "");
    if (!cursor) {
      break;
    }
  }
  return items;
}

function tokenTransferFromIndexedActivityItem(
  item,
  token,
  network,
  requestedWorkAmountStorageModel = "",
) {
  const workAmountStorageModel = isWorkTokenId(token?.tokenId)
    ? [
        requestedWorkAmountStorageModel,
        token?.amountStorageModel,
        item?.amountStorageModel,
        item?.creditAmountMovedStorageModel,
      ].find((model) =>
        [
          WORK_ATOMIC_PROJECTION_MODEL,
          WORK_SUBATOM_PROJECTION_MODEL,
        ].includes(String(model ?? "")),
      ) ?? WORK_ATOMIC_PROJECTION_MODEL
    : "";
  const amount =
    workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL
      ? undefined
      : creditAmountFromActivityItem(item, token.ticker);
  const amountRecord = {
    amount:
      item?.amount ?? item?.tokenAmount ?? item?.creditAmountMoved ?? amount,
    amountAtoms: item?.amountAtoms ?? item?.tokenAmountAtoms,
    amountStorageModel: workAmountStorageModel,
    amountSubatoms:
      item?.amountSubatoms ??
      item?.tokenAmountSubatoms ??
      item?.creditAmountMovedSubatoms,
    amountVersion: item?.amountVersion,
    precisionModel:
      item?.precisionModel ?? item?.creditAmountMovedPrecisionModel,
  };
  const ledgerAmount = tokenLedgerAmountFromRecord(
    token?.tokenId,
    amountRecord,
    { workAmountStorageModel },
  );
  if (
    ledgerAmount === null ||
    item?.confirmed === false
  ) {
    return null;
  }
  const amountFields = tokenLedgerAmountFields(
    token.tokenId,
    ledgerAmount,
    { workAmountStorageModel },
  );
  return {
    ...canonicalEventIdentityDetails(item),
    ...amountFields,
    ...tokenCreditAmountMovedFields({
      ...amountRecord,
      ...amountFields,
      tokenId: token.tokenId,
    }),
    ...(item?.amountVersion ? { amountVersion: item.amountVersion } : {}),
    arbSats: numericValue(item.arbSats),
    blockHash: String(item.blockHash ?? "").trim().toLowerCase(),
    blockHeight: numericValue(item.blockHeight),
    blockIndex: numericValue(item.blockIndex),
    confirmed: true,
    creditFloorAtConfirmSats: numericValue(
      item.creditFloorAtConfirmSats,
    ),
    creditFloorAtConfirmModel: String(
      item.creditFloorAtConfirmModel ?? "",
    ),
    creditLiveFloorSats: numericValue(item.creditLiveFloorSats),
    creditLiveValueSats: numericValue(item.creditLiveValueSats),
    creditRevaluationFloorSats: numericValue(
      item.creditRevaluationFloorSats,
    ),
    creditValueAtConfirmSats: numericValue(
      item.creditValueAtConfirmSats,
    ),
    createdAt: item.createdAt,
    dataBytes: numericValue(item.dataBytes),
    frozenNetworkValueSats: numericValue(item.frozenNetworkValueSats),
    ...canonicalMinerFeeDetailsFromActivity(item),
    minerFeeSats: numericValue(item.minerFeeSats),
    network,
    paidSats: numericValue(
      item.registryMutationFeeSats ?? item.paidSats ?? item.amountSats,
    ),
    recipientAddress: indexedActivityValue(
      item,
      "recipientAddress",
      "counterparty",
    ),
    registryAddress:
      item.registryAddress ??
      token.registryAddress ??
      item.recipients?.[0]?.address ??
      "",
    registryMutationFeeSats: numericValue(item.registryMutationFeeSats),
    senderAddress: indexedActivityValue(item, "senderAddress", "actor"),
    ticker: token.ticker,
    tokenId: token.tokenId,
    txid: String(item.txid ?? "").toLowerCase(),
    valid: item.valid !== false,
    valueSnapshotBlockHash: String(
      item.valueSnapshotBlockHash ?? "",
    ),
    valueSnapshotBlockHeight: numericValue(
      item.valueSnapshotBlockHeight,
    ),
    valueSnapshotCanonicalSummaryHash: String(
      item.valueSnapshotCanonicalSummaryHash ?? "",
    ),
    valueSnapshotGeneratedAt: String(
      item.valueSnapshotGeneratedAt ?? "",
    ),
    valueSnapshotId: String(item.valueSnapshotId ?? ""),
    liveNetworkValueSats: numericValue(item.liveNetworkValueSats),
    ...canonicalCreditValueFieldsFromRecord(item),
  };
}

async function tokenValueStateFromIndexedActivity(
  network,
  activityState,
  scope = "",
  options = {},
) {
  if (!Array.isArray(activityState?.activity)) {
    return null;
  }
  const tokenScope = normalizeTokenScope(scope);
  const requestedWorkAmountStorageModel = [
    options?.workAmountStorageModel,
    activityState?.amountStorageModel,
  ].find((model) =>
    [
      WORK_ATOMIC_PROJECTION_MODEL,
      WORK_SUBATOM_PROJECTION_MODEL,
    ].includes(String(model ?? "")),
  ) ?? WORK_ATOMIC_PROJECTION_MODEL;
  const tokensById = new Map([
    [
      WORK_TOKEN_ID,
      canonicalWorkTokenDefinition(
        network,
        requestedWorkAmountStorageModel,
      ),
    ],
    [
      POWB_TOKEN_ID,
      {
        ...canonicalPowbTokenDefinition(network, ""),
        confirmed: true,
      },
    ],
    [
      INCB_TOKEN_ID,
      {
        ...canonicalIncbTokenDefinition(network, ""),
        confirmed: true,
      },
    ],
  ]);

  for (const item of activityState.activity) {
    if (item?.kind !== "token-create" || item?.confirmed === false) {
      continue;
    }
    const token = tokenDefinitionFromIndexedCreate(
      item,
      network,
      requestedWorkAmountStorageModel,
    );
    if (token?.tokenId) {
      tokensById.set(token.tokenId, token);
    }
  }

  const scopeMatches = (tokenId, ticker = "") => {
    if (!tokenScope) {
      return true;
    }
    return (
      String(tokenId ?? "").toLowerCase() === tokenScope ||
      String(ticker ?? "").toLowerCase() === tokenScope
    );
  };
  const tokenFor = (tokenId) => tokensById.get(String(tokenId ?? "").toLowerCase());
  const exactActivityPositionInteger = (value, minimum) => {
    if (value === undefined || value === null || value === "") {
      return undefined;
    }
    const number = Number(value);
    return Number.isSafeInteger(number) && number >= minimum
      ? number
      : undefined;
  };
  const activityPositionFields = (item) => {
    const blockHash = String(item?.blockHash ?? "").trim().toLowerCase();
    const blockHeight = exactActivityPositionInteger(item?.blockHeight, 1);
    const blockIndex = exactActivityPositionInteger(item?.blockIndex, 0);
    return {
      ...canonicalEventIdentityDetails(item),
      ...(blockHash ? { blockHash } : {}),
      ...(blockHeight !== undefined ? { blockHeight } : {}),
      ...(blockIndex !== undefined ? { blockIndex } : {}),
    };
  };
  const prefixedActivityPositionFields = (item, prefix) => {
    const blockHash = String(item?.blockHash ?? "").trim().toLowerCase();
    const blockHeight = exactActivityPositionInteger(item?.blockHeight, 1);
    const blockIndex = exactActivityPositionInteger(item?.blockIndex, 0);
    const identity = canonicalEventIdentityDetails(item);
    return {
      ...(blockHash ? { [`${prefix}BlockHash`]: blockHash } : {}),
      ...(blockHeight !== undefined
        ? { [`${prefix}BlockHeight`]: blockHeight }
        : {}),
      ...(blockIndex !== undefined
        ? { [`${prefix}BlockIndex`]: blockIndex }
        : {}),
      ...(identity.protocolVout !== undefined
        ? { [`${prefix}ProtocolVout`]: identity.protocolVout }
        : {}),
      ...(identity.recordOrdinal !== undefined
        ? { [`${prefix}RecordOrdinal`]: identity.recordOrdinal }
        : {}),
    };
  };
  const mints = [];
  const transfers = [];
  const listingTermsById = new Map();

  for (const item of activityState.activity) {
    const tokenId = String(item?.tokenId ?? "").trim().toLowerCase();
    const token = tokenFor(tokenId);
    if (!token || !scopeMatches(token.tokenId, token.ticker)) {
      continue;
    }
    if (item.kind === "token-mint") {
      const fallbackAmount =
        isWorkTokenId(token.tokenId) &&
        requestedWorkAmountStorageModel ===
          WORK_SUBATOM_PROJECTION_MODEL
          ? undefined
          : creditAmountFromActivityItem(item, token.ticker);
      const amountRecord = {
        amount:
          item?.amount ??
          item?.tokenAmount ??
          item?.confirmedIssuanceUnits ??
          fallbackAmount,
        amountAtoms: item?.amountAtoms ?? item?.tokenAmountAtoms,
        amountStorageModel: requestedWorkAmountStorageModel,
        amountSubatoms:
          item?.amountSubatoms ??
          item?.tokenAmountSubatoms ??
          item?.creditAmountMovedSubatoms,
        amountVersion: item?.amountVersion,
        precisionModel:
          item?.precisionModel ?? item?.creditAmountMovedPrecisionModel,
      };
      const amount = tokenLedgerAmountFromRecord(
        token.tokenId,
        amountRecord,
        {
          workAmountStorageModel: isWorkTokenId(token.tokenId)
            ? requestedWorkAmountStorageModel
            : "",
        },
      );
      if (amount === null || item.confirmed === false) {
        continue;
      }
      const amountFields = tokenLedgerAmountFields(
        token.tokenId,
        amount,
        {
          workAmountStorageModel: isWorkTokenId(token.tokenId)
            ? requestedWorkAmountStorageModel
            : "",
        },
      );
      mints.push({
        ...canonicalEventIdentityDetails(item),
        ...amountFields,
        ...tokenCreditAmountMovedFields({
          ...amountRecord,
          ...amountFields,
          tokenId: token.tokenId,
        }),
        ...(item.issuanceAccountingModel ===
        INCEPTION_ISSUANCE_ACCOUNTING_MODEL
          ? {
              ...canonicalInceptionMintMetadata(item),
              issuanceCheckpointBlockHash: String(
                item.issuanceCheckpointBlockHash ?? "",
              )
                .trim()
                .toLowerCase(),
              issuanceCheckpointBlockHeight: numericValue(
                item.issuanceCheckpointBlockHeight,
              ),
              issuanceCheckpointBlockIndex: numericValue(
                item.issuanceCheckpointBlockIndex,
              ),
              issuanceCheckpointMode: String(
                item.issuanceCheckpointMode ?? "",
              ),
            }
          : {}),
        blockHash: String(item.blockHash ?? "").trim().toLowerCase(),
        blockHeight: numericValue(item.blockHeight),
        blockIndex: numericValue(item.blockIndex),
        confirmed: true,
        createdAt: item.createdAt,
        dataBytes: numericValue(item.dataBytes),
        ...canonicalMinerFeeDetailsFromActivity(item),
        minterAddress: indexedActivityValue(
          item,
          "minterAddress",
          "actor",
          "senderAddress",
        ),
        minerFeeSats: numericValue(item.minerFeeSats),
        network,
        paidSats: numericValue(
          item.proofPaymentSats ?? item.paidSats ?? item.amountSats,
        ),
        registryAddress:
          item.registryAddress ??
          token.registryAddress ??
          item.recipients?.[0]?.address ??
          "",
        ticker: token.ticker,
        tokenId: token.tokenId,
        txid: String(item.txid ?? "").toLowerCase(),
        ...canonicalCreditValueFieldsFromRecord(item),
      });
    } else if (item.kind === "token-transfer") {
      const transfer = tokenTransferFromIndexedActivityItem(
        item,
        token,
        network,
        requestedWorkAmountStorageModel,
      );
      if (transfer) {
        transfers.push(transfer);
      }
    } else if (
      item.kind === "token-listing" ||
      item.kind === "token-listings"
    ) {
      const listingId = String(item?.listingId ?? item?.txid ?? "")
        .trim()
        .toLowerCase();
      const fallbackAmount =
        isWorkTokenId(token.tokenId) &&
        requestedWorkAmountStorageModel ===
          WORK_SUBATOM_PROJECTION_MODEL
          ? undefined
          : creditAmountFromActivityItem(item, token.ticker);
      const amountRecord = {
        amount:
          item?.amount ??
          item?.tokenAmount ??
          item?.creditAmountMoved ??
          fallbackAmount,
        amountAtoms: item?.amountAtoms ?? item?.tokenAmountAtoms,
        amountStorageModel: requestedWorkAmountStorageModel,
        amountSubatoms:
          item?.amountSubatoms ??
          item?.tokenAmountSubatoms ??
          item?.creditAmountMovedSubatoms,
        amountVersion: item?.amountVersion,
        precisionModel:
          item?.precisionModel ?? item?.creditAmountMovedPrecisionModel,
        saleAuthorization: item?.saleAuthorization,
      };
      const ledgerAmount = tokenLedgerAmountFromRecord(
        token.tokenId,
        amountRecord,
        {
          workAmountStorageModel: isWorkTokenId(token.tokenId)
            ? requestedWorkAmountStorageModel
            : "",
        },
      );
      const priceSats = creditSalePriceFromActivityItem(item);
      if (
        !listingId ||
        ledgerAmount === null ||
        priceSats <= 0 ||
        item.confirmed === false
      ) {
        continue;
      }
      const sellerAddress = indexedActivityValue(
        item,
        "sellerAddress",
        "actor",
      );
      const registryAddress =
        item.registryAddress ??
        item.saleAuthorization?.registryAddress ??
        token.registryAddress ??
        indexedActivityValue(item, "counterparty") ??
        "";
      const current = listingTermsById.get(listingId);
      const listing = {
        ...activityPositionFields(item),
        ...tokenLedgerAmountFields(
          token.tokenId,
          ledgerAmount,
          {
            workAmountStorageModel: isWorkTokenId(token.tokenId)
              ? requestedWorkAmountStorageModel
              : "",
          },
        ),
        confirmed: true,
        createdAt: item.createdAt,
        dataBytes: numericValue(item.dataBytes),
        ...canonicalMinerFeeDetailsFromActivity(item),
        listingId,
        minerFeeSats: numericValue(item.minerFeeSats),
        network,
        priceSats,
        registryAddress,
        saleAuthorization: item.saleAuthorization,
        sealAt: item.sealAt,
        sealConfirmed: item.sealConfirmed,
        sealDataBytes: numericValue(item.sealDataBytes),
        sealTxid: String(item.sealTxid ?? "").trim().toLowerCase(),
        sellerAddress,
        status: item.status,
        ticker: token.ticker,
        tokenId: token.tokenId,
        txid: listingId,
      };
      if (
        !current ||
        numericValue(listing.saleAuthorization?.priceSats) >
          numericValue(current.saleAuthorization?.priceSats) ||
        Object.keys(listing.saleAuthorization ?? {}).length >
          Object.keys(current.saleAuthorization ?? {}).length
      ) {
        listingTermsById.set(listingId, listing);
      }
    }
  }

  for (const item of activityState.activity) {
    if (item?.kind !== "token-listing-sealed") {
      continue;
    }
    const listingId = String(item?.listingId ?? "").trim().toLowerCase();
    const listing = listingTermsById.get(listingId);
    if (!listing || !scopeMatches(listing.tokenId, listing.ticker)) {
      continue;
    }
    const sealedListing = {
      ...listing,
      ...prefixedActivityPositionFields(item, "seal"),
      saleAuthorization:
        item.saleAuthorization && Object.keys(item.saleAuthorization).length > 0
          ? {
              ...listing.saleAuthorization,
              ...item.saleAuthorization,
          }
          : listing.saleAuthorization,
      sealAt: item.createdAt ?? listing.sealAt,
      sealConfirmed: item.confirmed !== false,
      sealDataBytes: numericValue(item.dataBytes) || listing.sealDataBytes,
      sealFrozenNetworkValueSats:
        numericValue(item.frozenNetworkValueSats) ||
        numericValue(item.sealFrozenNetworkValueSats) ||
        listing.sealFrozenNetworkValueSats,
      sealLiveNetworkValueSats:
        numericValue(item.liveNetworkValueSats) ||
        numericValue(item.sealLiveNetworkValueSats) ||
        listing.sealLiveNetworkValueSats,
      ...(item?.canonicalMinerFeeCovered === true
        ? {
            sealCanonicalMinerFeeSats: numericValue(
              item.canonicalMinerFeeSats,
            ),
          }
        : {}),
      sealMinerFeeSats: numericValue(item.minerFeeSats),
      sealTxid: String(item.txid ?? listing.sealTxid ?? "").trim().toLowerCase(),
    };
    listingTermsById.set(
      listingId,
      mergeTokenListingRecord(listing, sealedListing),
    );
  }

  const indexedSales = [];
  const indexedClosedListings = [];
  for (const item of activityState.activity) {
    if (item?.kind !== "token-sale" || item?.confirmed === false) {
      continue;
    }
    const txid = String(item?.txid ?? "").trim().toLowerCase();
    const listingId = String(item?.listingId ?? "").trim().toLowerCase();
    const listing = listingTermsById.get(listingId);
    if (!txid || !listing || !scopeMatches(listing.tokenId, listing.ticker)) {
      continue;
    }
    const paidSats = numericValue(item.paidSats ?? item.amountSats);
    const listingWorkAmountStorageModel = isWorkTokenId(listing.tokenId)
      ? requestedWorkAmountStorageModel
      : "";
    const listingLedgerAmount = tokenLedgerAmountFromRecord(
      listing.tokenId,
      listing,
      { workAmountStorageModel: listingWorkAmountStorageModel },
    );
    if (listingLedgerAmount === null) {
      continue;
    }
    indexedSales.push({
      ...activityPositionFields(item),
      ...prefixedActivityPositionFields(item, "sale"),
      ...tokenLedgerAmountFields(
        listing.tokenId,
        listingLedgerAmount,
        { workAmountStorageModel: listingWorkAmountStorageModel },
      ),
      buyerAddress: indexedActivityValue(
        item,
        "buyerAddress",
        "actor",
        "senderAddress",
      ),
      confirmed: true,
      createdAt: item.createdAt,
      dataBytes: numericValue(item.dataBytes),
      ...canonicalMinerFeeDetailsFromActivity(item),
      listingId,
      marketplaceMutationFeeSats: TOKEN_MIN_MUTATION_PRICE_SATS,
      minerFeeSats: numericValue(item.minerFeeSats),
      network,
      paidSats:
        paidSats > 0
          ? paidSats
          : listing.priceSats + TOKEN_MIN_MUTATION_PRICE_SATS,
      priceSats: listing.priceSats,
      registryAddress: listing.registryAddress,
      salePaymentSats: listing.priceSats,
      sellerAddress: listing.sellerAddress,
      ticker: listing.ticker,
      tokenId: listing.tokenId,
      txid,
      ...canonicalCreditValueFieldsFromRecord(item),
    });
    indexedClosedListings.push({
      ...prefixedActivityPositionFields(item, "closed"),
      ...tokenLedgerAmountFields(
        listing.tokenId,
        listingLedgerAmount,
        { workAmountStorageModel: listingWorkAmountStorageModel },
      ),
      closedAt: item.createdAt,
      closedConfirmed: true,
      closedTxid: txid,
      confirmed: true,
      createdAt: listing.createdAt,
      dataBytes: numericValue(item.dataBytes),
      ...(item?.canonicalMinerFeeCovered === true
        ? {
            closedCanonicalMinerFeeSats: numericValue(
              item.canonicalMinerFeeSats,
            ),
          }
        : {}),
      closedMinerFeeSats: numericValue(item.minerFeeSats),
      listingId,
      network,
      priceSats: listing.priceSats,
      registryAddress: listing.registryAddress,
      saleAuthorization: listing.saleAuthorization,
      sealAt: listing.sealAt,
      sealConfirmed: listing.sealConfirmed,
      sealDataBytes: listing.sealDataBytes,
      sealTxid: listing.sealTxid,
      sellerAddress: listing.sellerAddress,
      status: "sold",
      ticker: listing.ticker,
      tokenId: listing.tokenId,
      txid: listing.listingId,
    });
  }

  const [overlaySales, closedListings] = await Promise.all([
    completeTokenMarketOverlayItems(network, tokenScope, "sales"),
    completeTokenMarketOverlayItems(network, tokenScope, "closed-listings"),
  ]);
  const scopedTokens = [...tokensById.values()].filter((token) =>
    scopeMatches(token.tokenId, token.ticker),
  );
  const tokenIds = new Set(scopedTokens.map((token) => token.tokenId));
  const scopedListings = [...listingTermsById.values()].filter((listing) =>
    tokenIds.has(listing.tokenId),
  );
  const scopedSales = mergeTokenStateItemsByKey(
    indexedSales.filter((sale) => tokenIds.has(sale.tokenId)),
    overlaySales.filter((sale) => tokenIds.has(sale.tokenId)),
    tokenSaleItemKey,
    mergeTokenSaleRecord,
  );
  const scopedClosedListings = mergeTokenStateItemsByKey(
    indexedClosedListings.filter((listing) => tokenIds.has(listing.tokenId)),
    closedListings.filter((listing) => tokenIds.has(listing.tokenId)),
    tokenClosedListingItemKey,
    mergeTokenListingRecord,
  );
  const exactBondScopeId =
    scopedTokens.length === 1 && isBondTokenId(scopedTokens[0]?.tokenId)
      ? scopedTokens[0].tokenId
      : "";
  const exactWorkScope =
    scopedTokens.length === 1 && isWorkTokenId(scopedTokens[0]?.tokenId);
  const exactWorkQ16 =
    exactWorkScope &&
    requestedWorkAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL;
  const confirmedWorkSupplyUnits = exactWorkScope
    ? mints
        .filter(
          (mint) =>
            mint.confirmed && isWorkTokenId(mint.tokenId),
        )
        .reduce((total, mint) => {
          const amount = exactWorkQ16
            ? workSubatomsBigIntFromRecord(mint, {
                convertLegacyAtoms: true,
              })
            : workAtomsBigIntFromRecord(mint);
          if (amount === null) {
            throw new Error(
              "Indexed WORK value state contains an inexact mint amount.",
            );
          }
          return total + amount;
        }, 0n)
    : null;
  const confirmedSupply = exactWorkScope
    ? exactWorkQ16
      ? formatWorkSubatoms(confirmedWorkSupplyUnits)
      : formatWorkAtoms(confirmedWorkSupplyUnits)
    : exactBondScopeId
    ? mints
        .filter(
          (mint) =>
            mint.confirmed && mint.tokenId === exactBondScopeId,
        )
        .reduce((total, mint) => {
          const amount = tokenLedgerAmountFromRecord(exactBondScopeId, mint);
          return amount === null ? total : total + amount;
        }, 0n)
        .toString()
    : mints
        .filter((mint) => mint.confirmed)
        .reduce((total, mint) => total + numericValue(mint.amount), 0);
  const creationSats = scopedTokens.reduce(
    (total, token) => total + numericValue(token.creationFeeSats),
    0,
  );
  return {
    ...emptyTokenPayloadSnapshot(network),
    ...(exactWorkScope
      ? requestedWorkAmountStorageModel ===
        WORK_SUBATOM_PROJECTION_MODEL
        ? {
            amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
            decimals: WORK_SUBATOM_DECIMALS,
            precisionModel: WORK_PRECISION_V2_MODEL,
            unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
            workDefaults: canonicalWorkDefaults(
              WORK_SUBATOM_PROJECTION_MODEL,
            ),
          }
        : {
            amountStorageModel: WORK_ATOMIC_PROJECTION_MODEL,
            decimals: WORK_DECIMALS,
            unitScale: WORK_UNIT_SCALE_TEXT,
            workDefaults: canonicalWorkDefaults(
              WORK_ATOMIC_PROJECTION_MODEL,
            ),
          }
      : {}),
    closedListings: scopedClosedListings,
    confirmedSupply,
    ...(confirmedWorkSupplyUnits === null
      ? {}
      : exactWorkQ16
        ? {
            confirmedSupplySubatoms:
              confirmedWorkSupplyUnits.toString(),
            pendingSupplySubatoms: "0",
          }
        : {
            confirmedSupplyAtoms:
              confirmedWorkSupplyUnits.toString(),
            pendingSupplyAtoms: "0",
          }),
    creationSats,
    holders: [],
    indexedAt: activityState.indexedAt ?? new Date().toISOString(),
    indexedThroughBlock:
      activityState.indexedThroughBlock ??
      activityState.stats?.indexedThroughBlock ??
      indexedThroughBlockFromItems(activityState.activity),
    listings: scopedListings,
    mints,
    pendingSupply:
      exactWorkScope || exactBondScopeId ? "0" : 0,
    sales: scopedSales,
    source: mergedSourceLabel(
      activityState.source,
      "proof-indexer-derived-token-value-state",
    ),
    stats: {
      confirmedMints: mints.length,
      confirmedSales: scopedSales.length,
      confirmedTransfers: transfers.length,
      confirmedTokens: scopedTokens.filter((token) => token.confirmed).length,
      holders: 0,
      invalidEvents: 0,
      pendingMints: 0,
      pendingTransfers: 0,
      pendingTokens: 0,
      registries: new Set(
        scopedTokens.map((token) => token.registryAddress).filter(Boolean),
      ).size,
      transactions:
        scopedTokens.length +
        mints.length +
        transfers.length +
        scopedSales.length +
        scopedClosedListings.length,
    },
    tokens: scopedTokens,
    transfers,
  };
}

async function currentProofIndexTokenTablePayloadForLedger(
  network,
  label,
  options = {},
) {
  if (
    network !== "livenet" ||
    !proofIndexReadFeatureEnabled("token-state,token-default,token")
  ) {
    return null;
  }

  const bootstrapPayload = await payloadWithFallbackAfterMs(
    proofIndexCanonicalSummaryTokenTablePayload(network, {
      exactHash: options.exactHash,
      exactHeight: options.exactHeight,
    }).catch((error) => {
        console.error(
          `Proof index canonical-summary token bootstrap failed for ${label}: ${errorSummary(error)}`,
        );
        return null;
      }),
    null,
    SUMMARY_PROOF_INDEX_READ_WAIT_MS,
  );
  const payload =
    bootstrapPayload ??
    await payloadWithFallbackAfterMs(
      proofIndexTokenPayload(
        network,
        "",
        new URLSearchParams(),
      ).catch((error) => {
        console.error(
          `Proof index token-table overlay failed for ${label}: ${errorSummary(error)}`,
        );
        return null;
      }),
      null,
      SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    );
  if (
    !payload ||
    rejectEmptyMainnetTokenPayload(
      network,
      payload,
      "",
      `${label} token-table overlay`,
    )
  ) {
    return null;
  }
  const exactHeight = Number(options.exactHeight);
  const exactHash = String(options.exactHash ?? "")
    .trim()
    .toLowerCase();
  if (Number.isSafeInteger(exactHeight) && exactHeight > 0) {
    if (
      proofIndexPayloadIndexedThroughBlock(payload) !== exactHeight ||
      !/^[0-9a-f]{64}$/u.test(exactHash) ||
      payloadIndexedThroughBlockHash(payload) !== exactHash
    ) {
      console.error(
        `Rejected ${label} token-table overlay: coverage is not exact and hash-bound at block ${exactHeight}.`,
      );
      return null;
    }
  } else if (
    !(await proofIndexPayloadCoversConfirmedTip(
      payload,
      network,
      `${label} token-table overlay`,
    ))
  ) {
    return null;
  }

  return payload;
}

function tokenTablePayloadHasConservedBalances(payload) {
  const tokens = Array.isArray(payload?.tokens) ? payload.tokens : [];
  const mints = Array.isArray(payload?.mints) ? payload.mints : [];
  const holders = Array.isArray(payload?.holders) ? payload.holders : [];
  if (tokens.length === 0 || mints.length === 0 || holders.length === 0) {
    return false;
  }
  const tokenIds = new Set();
  for (const token of tokens) {
    const tokenId = String(token?.tokenId ?? "").trim().toLowerCase();
    if (!tokenId || tokenIds.has(tokenId)) {
      return false;
    }
    tokenIds.add(tokenId);
  }
  const workStorageModelByTokenId = new Map(
    tokens
      .filter((token) => isWorkTokenId(token?.tokenId))
      .map((token) => [
        String(token.tokenId).trim().toLowerCase(),
        workRecordUsesSubatoms(token) ||
        (
          tokens.length === 1 &&
          (
            payload?.amountStorageModel ===
              WORK_SUBATOM_PROJECTION_MODEL ||
            payload?.precisionModel === WORK_PRECISION_V2_MODEL
          )
        )
          ? WORK_SUBATOM_PROJECTION_MODEL
          : WORK_ATOMIC_PROJECTION_MODEL,
      ]),
  );
  const ledgerAmount = (tokenId, record, field) => {
    if (isWorkTokenId(tokenId)) {
      const workAmountStorageModel =
        workStorageModelByTokenId.get(tokenId);
      if (!workAmountStorageModel) {
        return null;
      }
      return tokenLedgerAmountFromRecord(
        tokenId,
        {
          amount: record?.[field],
          amountAtoms: record?.[`${field}Atoms`],
          amountStorageModel: record?.amountStorageModel,
          amountSubatoms: record?.[`${field}Subatoms`],
          amountVersion: record?.amountVersion,
          precisionModel: record?.precisionModel,
          saleAuthorization: record?.saleAuthorization,
          transferVersion: record?.transferVersion,
        },
        {
          allowZero: true,
          workAmountStorageModel,
        },
      );
    }
    if (isBondTokenId(tokenId)) {
      return integerBigInt(record?.[field], { allowZero: true });
    }
    const amount = Number(record?.[field]);
    return Number.isSafeInteger(amount) && amount >= 0 ? amount : null;
  };
  const ledgerAmountIsDeclared = (record, field) =>
    [
      record?.[field],
      record?.[`${field}Atoms`],
      record?.[`${field}Subatoms`],
    ].some(
      (value) => value !== undefined && value !== null && value !== "",
    );
  const ledgerZero = (tokenId) =>
    isWorkTokenId(tokenId) || isBondTokenId(tokenId) ? 0n : 0;
  const mintedByToken = new Map();
  for (const mint of mints) {
    if (mint?.confirmed !== true) {
      continue;
    }
    const tokenId = String(mint?.tokenId ?? "").trim().toLowerCase();
    const amount = ledgerAmount(tokenId, mint, "amount");
    if (
      !tokenId ||
      amount === null ||
      amount <= ledgerZero(tokenId)
    ) {
      return false;
    }
    if (!tokenIds.has(tokenId)) {
      return false;
    }
    mintedByToken.set(
      tokenId,
      (mintedByToken.get(tokenId) ?? ledgerZero(tokenId)) + amount,
    );
  }
  const heldByToken = new Map();
  for (const holder of holders) {
    const tokenId = String(holder?.tokenId ?? "").trim().toLowerCase();
    const balance = ledgerAmount(tokenId, holder, "balance");
    if (
      !tokenId ||
      balance === null ||
      balance <= ledgerZero(tokenId)
    ) {
      return false;
    }
    if (!tokenIds.has(tokenId)) {
      return false;
    }
    heldByToken.set(
      tokenId,
      (heldByToken.get(tokenId) ?? ledgerZero(tokenId)) + balance,
    );
  }
  const conserved = tokens.every((token) => {
    const tokenId = String(token?.tokenId ?? "").trim().toLowerCase();
    const minted = mintedByToken.get(tokenId) ?? ledgerZero(tokenId);
    const held = heldByToken.get(tokenId) ?? ledgerZero(tokenId);
    const declaredSupply = ledgerAmount(tokenId, token, "confirmedSupply");
    return (
      minted === held &&
      (!ledgerAmountIsDeclared(token, "confirmedSupply")
        ? true
        : declaredSupply !== null && declaredSupply === minted)
    );
  });
  if (!conserved) {
    return false;
  }

  const workTokens = tokens.filter((token) => isWorkTokenId(token?.tokenId));
  if (workTokens.length > 0) {
    if (tokens.length !== 1) {
      // Per-token conservation above is exact. A mixed token table has no
      // coherent cross-token atomic unit in which to validate one grand total.
      return true;
    }
    const workTokenId = String(workTokens[0].tokenId).trim().toLowerCase();
    const payloadSupply = ledgerAmount(
      workTokenId,
      payload,
      "confirmedSupply",
    );
    return (
      !ledgerAmountIsDeclared(payload, "confirmedSupply") ||
      (payloadSupply !== null &&
        payloadSupply === (mintedByToken.get(workTokenId) ?? 0n))
    );
  }

  const bondTokens = tokens.filter((token) => isBondTokenId(token?.tokenId));
  if (bondTokens.length > 0) {
    if (tokens.length !== 1) {
      // Cross-token totals have no shared unit. Per-token mint/holder/supply
      // conservation above remains exact for each synthetic bond credit.
      return true;
    }
    const bondTokenId = String(bondTokens[0].tokenId).trim().toLowerCase();
    const payloadSupply = ledgerAmount(
      bondTokenId,
      payload,
      "confirmedSupply",
    );
    return (
      !ledgerAmountIsDeclared(payload, "confirmedSupply") ||
      (payloadSupply !== null &&
        payloadSupply === (mintedByToken.get(bondTokenId) ?? 0n))
    );
  }

  const mintedSupply = [...mintedByToken.values()].reduce(
    (total, amount) => total + amount,
    0,
  );
  const heldSupply = [...heldByToken.values()].reduce(
    (total, amount) => total + amount,
    0,
  );
  const payloadSupply = Number(payload?.confirmedSupply);
  return (
    mintedSupply === heldSupply &&
    (!Number.isFinite(payloadSupply) || payloadSupply === mintedSupply)
  );
}

async function exactTokenTablePayloadForCanonicalLedger(
  network,
  label,
  exactHeight,
  exactHash,
) {
  const normalizedExactHash = String(exactHash ?? "")
    .trim()
    .toLowerCase();
  if (
    !Number.isSafeInteger(exactHeight) ||
    exactHeight <= 0 ||
    !/^[0-9a-f]{64}$/u.test(normalizedExactHash)
  ) {
    throw freshDataUnavailableError(
      `Rejected ${label}: an exact positive hash-bound token-table checkpoint is required.`,
    );
  }
  const payload = await currentProofIndexTokenTablePayloadForLedger(
    network,
    label,
    { exactHash: normalizedExactHash, exactHeight },
  );
  if (!payload || !tokenTablePayloadHasConservedBalances(payload)) {
    throw freshDataUnavailableError(
      `Rejected ${label}: exact conserved token balances are unavailable.`,
    );
  }
  return payload;
}

function activityStateIsProofIndexCanonical(activityState) {
  return activityState?.source === "proof-indexer-events";
}

const SEEDED_MAIL_ACTIVITY_KINDS = new Set([
  "attachment",
  "browser",
  "file",
  INCEPTION_BOND_KIND,
  INFINITY_BOND_KIND,
  "mail",
  "reply",
]);

function activityItemAddressValues(item) {
  return [
    item?.actor,
    item?.counterparty,
    item?.senderAddress,
    item?.recipientAddress,
    item?.sellerAddress,
    item?.buyerAddress,
    item?.registryAddress,
    ...(Array.isArray(item?.participants) ? item.participants : []),
    ...(Array.isArray(item?.recipients)
      ? item.recipients.map((recipient) => recipient?.address)
      : []),
  ];
}

function activityItemTouchesAddressSet(item, addressSet) {
  return activityItemAddressValues(item).some((address) =>
    addressSet.has(String(address ?? "").trim().toLowerCase()),
  );
}

function seededMailActivityPayloadFromIndexedActivity(
  network,
  seedAddresses,
  activityState,
) {
  const addresses = [...new Set(seedAddresses)]
    .filter((address) => isValidBitcoinAddress(address, network))
    .slice(0, SEEDED_MAIL_ACTIVITY_MAX_ADDRESSES);
  const addressSet = new Set(addresses.map((address) => address.toLowerCase()));
  const activity = dedupeActivityItems(
    (Array.isArray(activityState?.activity) ? activityState.activity : []).filter(
      (item) =>
        SEEDED_MAIL_ACTIVITY_KINDS.has(String(item?.kind ?? "")) &&
        activityItemTouchesAddressSet(item, addressSet),
    ),
  );
  return {
    activity,
    indexedAt: activityState?.indexedAt ?? new Date().toISOString(),
    indexedThroughBlock: indexedThroughBlockFromItems(activity),
    network,
    seedAddresses: addresses,
    source: activityState?.source ?? "proof-indexer-events",
    stats: activityStatsFromItems(activity, {
      addresses: addresses.length,
      transactions: new Set(activity.map((item) => item.txid).filter(Boolean))
        .size,
    }),
  };
}

async function buildIndexedCanonicalLedgerPayload(
  network,
  label = "indexed ledger",
  options = {},
) {
  if (network !== "livenet") {
    return null;
  }
  const exactHeight = Number(options.exactHeight);
  const exactHash = String(options.exactHash ?? "").trim().toLowerCase();
  if (!Number.isSafeInteger(exactHeight) || exactHeight <= 0) {
    throw freshDataUnavailableError(
      `Rejected ${label}: an exact positive canonical checkpoint is required.`,
    );
  }
  if (!/^[0-9a-f]{64}$/u.test(exactHash)) {
    throw freshDataUnavailableError(
      `Rejected ${label}: an exact canonical checkpoint hash is required.`,
    );
  }
  const workPrecisionOptions = await workAmoV8ReplayPrecisionOptions(
    network,
    exactHeight,
    exactHash,
  );
  const expectedWorkAmountStorageModel = String(
    workPrecisionOptions.workAmountStorageModel ?? "",
  );
  if (
    ![
      WORK_ATOMIC_PROJECTION_MODEL,
      WORK_SUBATOM_PROJECTION_MODEL,
    ].includes(expectedWorkAmountStorageModel)
  ) {
    throw freshDataUnavailableError(
      `Rejected ${label}: the exact WORK precision era is unavailable.`,
    );
  }
  const timingStartedAt = Date.now();
  let timingPreviousAt = timingStartedAt;
  const timingMs = {};
  const markTiming = (stage) => {
    const now = Date.now();
    timingMs[stage] = now - timingPreviousAt;
    timingPreviousAt = now;
  };

  const [
    activityState,
    registrySnapshot,
    btcUsdQuote,
    currentTokenTableState,
    currentMarketOverlay,
  ] = await Promise.all([
    indexedActivityStateForCanonicalLedger(network, { exactHeight }),
    indexedRegistryStateForCanonicalLedger(network, {
      exactHash,
      exactHeight,
    }),
    payloadWithFallbackAfterMs(
      btcUsdPricePayload(network, { fresh: false }),
      null,
      SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    ),
    exactTokenTablePayloadForCanonicalLedger(
      network,
      label,
      exactHeight,
      exactHash,
    ),
    indexedTokenMarketSummaryOverlay(network).catch((error) => {
      console.error(
        `WORK pre-consistency marketplace overlay failed: ${errorSummary(error)}`,
      );
      return null;
    }),
  ]);
  markTiming("sources");
  const tableWorkAmountStorageModel =
    exactWorkAmountStorageModelFromState(currentTokenTableState);
  if (
    tableWorkAmountStorageModel !== expectedWorkAmountStorageModel
  ) {
    throw freshDataUnavailableError(
      `Rejected ${label}: the canonical WORK definition conflicts with the exact replay precision era.`,
    );
  }
  const sourceTipHeight = exactHeight;
  const registryState = registrySnapshot;
  const derivedTokenState = await tokenValueStateFromIndexedActivity(
    network,
    activityState,
    "",
    {
      workAmountStorageModel: expectedWorkAmountStorageModel,
    },
  );
  const tokenState = derivedTokenState;
  const ledgerTokenTableState = tokenStateWithAuthoritativeCurrentListings(
    mergeTokenPayloadWithCanonicalFloor(
      tokenState,
      currentTokenTableState,
      "",
    ),
    currentTokenTableState,
  );
  const indexedWorkTokenState = ledgerTokenTableState
    ? scopedTokenPayloadFromState(ledgerTokenTableState, WORK_TOKEN_ID)
    : null;
  const indexedPowbState = ledgerTokenTableState
    ? scopedTokenPayloadFromState(ledgerTokenTableState, POWB_TOKEN_ID)
    : null;
  const indexedIncbState = ledgerTokenTableState
    ? scopedTokenPayloadFromState(ledgerTokenTableState, INCB_TOKEN_ID)
    : null;
  markTiming("token-state");

  if (!activityState || !registryState || !ledgerTokenTableState) {
    console.error(
      `Rejected ${label}: missing indexed source(s) activity=${Boolean(activityState)} registry=${Boolean(registryState)} token=${Boolean(ledgerTokenTableState)}; activityItems=${numericValue(activityState?.activity?.length)} registryRecords=${numericValue(registryState?.records?.length)} tokenMints=${numericValue(ledgerTokenTableState?.mints?.length)} workMints=${numericValue(indexedWorkTokenState?.mints?.length)}.`,
    );
    return null;
  }
  if (currentTokenTableState) {
    console.error(
      `Merged ${label} with current proof-index token tables while preserving canonical movement history and accepting exact current listing state.`,
    );
  }

  const baseWorkTokenState =
    indexedWorkTokenState ??
    scopedTokenPayloadFromState(ledgerTokenTableState, WORK_TOKEN_ID);
  if (
    exactWorkAmountStorageModelFromState(baseWorkTokenState) !==
      expectedWorkAmountStorageModel
  ) {
    throw freshDataUnavailableError(
      `Rejected ${label}: the reconstructed WORK state conflicts with the exact replay precision era.`,
    );
  }
  const valueTokenState = tokenStateWithScopedTokenOverride(
    ledgerTokenTableState,
    baseWorkTokenState,
    WORK_TOKEN_ID,
  );
  const seedAddresses = canonicalMailSeedAddresses({
    activityState,
    network,
    registryState,
    tokenState: valueTokenState,
    workTokenState: baseWorkTokenState,
  });
  const seededMailActivityState = seededMailActivityPayloadFromIndexedActivity(
    network,
    seedAddresses,
    activityState,
  );
  const baseActivity = dedupeActivityItems([
    ...(Array.isArray(activityState?.activity) ? activityState.activity : []),
    ...(Array.isArray(seededMailActivityState?.activity)
      ? seededMailActivityState.activity
      : []),
    ...(Array.isArray(registryState?.activity) ? registryState.activity : []),
  ]);
  const ledgerTokenStateWithPowb = indexedPowbState
    ? tokenStateWithScopedTokenOverride(
        valueTokenState,
        indexedPowbState,
        POWB_TOKEN_ID,
      )
    : valueTokenState;
  const ledgerTokenState = indexedIncbState
    ? tokenStateWithScopedTokenOverride(
        ledgerTokenStateWithPowb,
        indexedIncbState,
        INCB_TOKEN_ID,
      )
    : ledgerTokenStateWithPowb;
  const indexedInceptionState = scopedTokenPayloadFromState(
    ledgerTokenState,
    INCB_TOKEN_ID,
  );
  const indexedInceptionIssuance = inceptionIssuanceMetadataFromMints(
    indexedInceptionState.mints,
  );
  const indexedInceptionSupply =
    canonicalIntegerText(indexedInceptionState.confirmedSupply, {
      allowZero: true,
    }) || "0";
  if (
    (BigInt(indexedInceptionSupply) > 0n ||
      indexedInceptionIssuance.confirmedMints > 0) &&
    (!indexedInceptionIssuance.complete ||
      indexedInceptionIssuance.confirmedIssuanceUnits !==
        indexedInceptionSupply)
  ) {
    throw freshDataUnavailableError(
      `Rejected ${label}: indexed INCB is not a fully bound v2 replay.`,
    );
  }
  let activity = dedupeActivityItems([
    ...tokenActivityItemsFromStateForCanonicalLedger(
      ledgerTokenState,
      ledgerTokenState?.indexAddress ?? "",
      baseActivity,
    ),
    ...baseActivity,
  ]);
  let activityPayload = {
    activity,
    canonicalMinerFeeCoverage: activityState?.canonicalMinerFeeCoverage,
    indexedAt: new Date().toISOString(),
    network,
    source: mergedSourceLabel(activityState?.source, "indexed-canonical-ledger"),
    stats: activityStatsFromItems(activity, {
      addresses: Math.max(
        numericValue(activityState?.stats?.addresses),
        numericValue(seededMailActivityState?.stats?.addresses),
      ),
      registry: Array.isArray(registryState?.activity)
        ? registryState.activity.length
        : undefined,
      seededMail: seededMailActivityState?.stats?.total,
    }),
  };
  markTiming("activity");
  const creditValueDetails = creditNetworkValueMetrics({
    baseValueAt: growthActualBaseNetworkValueAtProvider(
      registryState.records ?? [],
      activity,
      registryState.sales ?? [],
      ledgerTokenState.tokens ?? [],
      ledgerTokenState.mints ?? [],
      ledgerTokenState.transfers ?? [],
      ledgerTokenState.sales ?? [],
    ),
    canonicalMinerFeeCoverage: activityState?.canonicalMinerFeeCoverage,
    confirmedActivity: activity,
    cutoffMs: CANONICAL_CONFIRMED_TIP_CUTOFF_MS,
    includeEvents: true,
    tokenDefinitions: ledgerTokenState.tokens ?? [],
    tokenMints: ledgerTokenState.mints ?? [],
    tokenSales: ledgerTokenState.sales ?? [],
    tokenTransfers: ledgerTokenState.transfers ?? [],
  });
  markTiming("credit-value");
  const valuedTokenState = tokenStateWithCreditNetworkValueDetails(
    ledgerTokenState,
    creditValueDetails,
  );
  const valuedWorkTokenState = tokenStateWithCreditNetworkValueDetails(
    baseWorkTokenState,
    creditValueDetails,
  );
  if (
    exactWorkAmountStorageModelFromState(valuedWorkTokenState) !==
      expectedWorkAmountStorageModel
  ) {
    throw freshDataUnavailableError(
      `Rejected ${label}: WORK value enrichment changed the exact replay precision era.`,
    );
  }
  activity = dedupeActivityItems([
    ...tokenActivityItemsFromStateForCanonicalLedger(
      valuedTokenState,
      valuedTokenState?.indexAddress ?? "",
      baseActivity,
    ),
    ...baseActivity,
  ]);
  activityPayload = {
    ...activityPayload,
    activity,
    indexedAt: new Date().toISOString(),
    stats: activityStatsFromItems(activity, {
      addresses: Math.max(
        numericValue(activityState?.stats?.addresses),
        numericValue(seededMailActivityState?.stats?.addresses),
      ),
      registry: Array.isArray(registryState?.activity)
        ? registryState.activity.length
        : undefined,
      seededMail: seededMailActivityState?.stats?.total,
    }),
  };
  const canonicalBaseLookupDiagnostics = {};
  let workFloor = workFloorPayloadFromState(
    network,
    registryState,
    activityPayload,
    valuedTokenState,
    valuedWorkTokenState,
    {
      btcUsdQuote,
      canonicalBaseLookupDiagnostics,
      valueCutoffMs: CANONICAL_CONFIRMED_TIP_CUTOFF_MS,
    },
  );
  markTiming("valued-state");
  if (currentMarketOverlay) {
    workFloor = workFloorWithIndexedMarketSummaryOverlay(
      workFloor,
      currentMarketOverlay,
      valuedTokenState,
    );
  }
  workFloor = await workFloorWithVerifiedWorkAmoV5ClosingState(
    workFloor,
    network,
    exactHeight,
    exactHash,
  );
  markTiming("market-overlay");
  const baseMetrics = ledgerMetricsFromState({
    activity,
    registryState,
    tokenState: valuedTokenState,
    workFloor,
  });
  const indexedThroughBlock =
    Math.max(
      Number(baseMetrics.indexedThroughBlock) || 0,
      Number(activityState?.indexedThroughBlock) || 0,
      Number(activityState?.stats?.indexedThroughBlock) || 0,
      Number(registryState?.indexedThroughBlock) || 0,
      Number(valuedTokenState?.indexedThroughBlock) || 0,
      Number(valuedWorkTokenState?.indexedThroughBlock) || 0,
    ) || baseMetrics.indexedThroughBlock;
  const metrics = {
    ...baseMetrics,
    indexedThroughBlock,
    sourceTipHeight: Number.isSafeInteger(sourceTipHeight)
      ? sourceTipHeight
      : undefined,
    tipLagBlocks:
      Number.isSafeInteger(sourceTipHeight) && indexedThroughBlock
        ? Math.max(0, sourceTipHeight - indexedThroughBlock)
        : undefined,
  };
  const sourceHashes = {
    ...ledgerSourceHashes({
      activityState,
      registryState,
      seededMailActivityState,
      tokenState: valuedTokenState,
      workTokenState: valuedWorkTokenState,
    }),
    ...(workFloor.workAmoV5Transition
      ? {
          workAmoV5Transition:
            workFloor.workAmoV5Transition,
        }
      : {}),
  };
  const snapshotId = sha256Hex(
    Buffer.from(
      JSON.stringify({
        metrics,
        network,
        sourceHashes,
      }),
    ),
  ).slice(0, 24);
  const ledger = {
    activity,
    activityPayload,
    btcUsdQuote,
    generatedAt: new Date().toISOString(),
    indexedThroughBlock,
    metrics,
    network,
    registryState,
    seededMailActivityState,
    snapshotId,
    source: "proof-indexer-indexed-canonical-ledger",
    sourceHashes,
    sourceTipHeight,
    tokenState: valuedTokenState,
    workFloor,
    workTokenState: valuedWorkTokenState,
  };
  const growthSummary = growthSummaryPayloadFromLedger(ledger);
  const consistency = ledgerSnapshotChecks({
    activity,
    growthSummary,
    metrics,
    network,
    seededMailActivityState,
    sourceHashes,
    tokenState: valuedTokenState,
    workFloor,
  });
  const summaryLedger = {
    ...ledger,
    consistency,
  };
  const inceptionSummary = inceptionSummaryPayloadFromLedger(summaryLedger);
  const infinitySummary = infinitySummaryPayloadFromLedger(summaryLedger);
  const result = {
    ...ledger,
    activityPayload: attachLedgerMetadata(activityPayload, {
      ...ledger,
      consistency,
    }),
    consistency,
    growthSummary: attachLedgerMetadata(growthSummary, {
      ...ledger,
      consistency,
    }),
    inceptionSummary: attachLedgerMetadata(inceptionSummary, {
      ...ledger,
      consistency,
    }),
    infinitySummary: attachLedgerMetadata(infinitySummary, {
      ...ledger,
      consistency,
    }),
    workFloor: attachLedgerMetadata(workFloor, {
      ...ledger,
      consistency,
    }),
  };
  markTiming("finalize");
  console.error(
    JSON.stringify({
      activityItems: activity.length,
      indexedThroughBlock,
      label,
      phase: "canonical-ledger-timing",
      timingMs: {
        ...timingMs,
        total: Date.now() - timingStartedAt,
      },
      canonicalBaseLookup: canonicalBaseLookupDiagnostics,
      tokenMints: Array.isArray(valuedTokenState?.mints)
        ? valuedTokenState.mints.length
        : 0,
    }),
  );
  return result;
}

function internalCanonicalWorkSummaryPayload(ledger) {
  const workTokenState = tokenPayloadWithCurrentWorkActiveListingPolicy(
    ledgerTokenStateForScope(ledger, WORK_TOKEN_ID),
    ledger.network,
  );
  return attachLedgerMetadata(
    {
      floor: attachLedgerMetadata(ledger.workFloor, ledger),
      indexedAt: ledger.generatedAt,
      network: ledger.network,
      summaryOnly: true,
      token: attachLedgerMetadata(
        compactTokenSummaryPayload(workTokenState, WORK_TOKEN_ID, {
          compactMarketRecords: true,
          includeAllScopedListings: false,
        }),
        ledger,
      ),
      workTransferValueProjection:
        canonicalWorkTransferValueProjectionFromState(
          workTokenState,
          ledger.workFloor?.liveFloorSats ?? ledger.workFloor?.floorSats,
        ),
    },
    ledger,
  );
}

async function exactCanonicalSummaryCheckpoint(network, options = {}) {
  const checkpointHeight = Number(options.checkpointHeight);
  const checkpointHash = String(options.checkpointHash ?? "")
    .trim()
    .toLowerCase();
  const checkpointRequested =
    checkpointHeight > 0 || checkpointHash.length > 0;
  if (
    checkpointRequested &&
    (!Number.isSafeInteger(checkpointHeight) ||
      checkpointHeight <= 0 ||
      !/^[0-9a-f]{64}$/u.test(checkpointHash))
  ) {
    throw freshDataUnavailableError(
      "The requested canonical summary checkpoint is malformed.",
    );
  }
  const [status, canonical, chainResponse, checkpointResponse] =
    await Promise.all([
      proofIndexOperationalStatusPayload(network),
      proofIndexCanonicalStateMetaPayload(network),
      bitcoinRpc("getblockchaininfo", []),
      checkpointRequested
        ? bitcoinRpc("getblockhash", [checkpointHeight])
        : Promise.resolve(null),
    ]);
  const chainInfo = chainResponse?.ok ? chainResponse.result : null;
  const tipHeight = Number(chainInfo?.blocks);
  const tipHash = String(chainInfo?.bestblockhash ?? "").trim().toLowerCase();
  const canonicalCheckpointHash = checkpointRequested
    ? String(checkpointResponse?.ok ? checkpointResponse.result : "")
        .trim()
        .toLowerCase()
    : tipHash;
  const indexedThroughBlock = Number(status?.indexedThroughBlock) || 0;
  const storedHash = String(status?.scan?.blockHash ?? "").trim().toLowerCase();
  const rebuild = canonical?.rebuild ?? {};
  const fault = canonical?.fault ?? {};
  const rebuildHeight = Number(rebuild?.indexedThroughBlock);
  const rebuildHash = String(rebuild?.indexedThroughBlockHash ?? "")
    .trim()
    .toLowerCase();
  const rebuildCheckpointMatches =
    rebuild?.network === network &&
    rebuildHeight === indexedThroughBlock &&
    rebuildHash === storedHash;
  const rebuildTrustState = canonicalRebuildTrustState(rebuild, network);
  const rebuildStateValid = checkpointRequested
    ? rebuildCheckpointMatches &&
      ["active", "complete"].includes(rebuildTrustState)
    : rebuildTrustState === "complete";
  const readModelsOk =
    Number(status?.readModels?.confirmedIds?.count) > 0 &&
    Number(status?.readModels?.confirmedTransfers?.count) > 0;
  if (
    network !== "livenet" ||
    !status ||
    !canonical ||
    !Number.isSafeInteger(tipHeight) ||
    !/^[0-9a-f]{64}$/u.test(tipHash) ||
    (checkpointRequested
      ? checkpointHeight > tipHeight ||
        indexedThroughBlock !== checkpointHeight ||
        storedHash !== checkpointHash ||
        canonicalCheckpointHash !== checkpointHash
      : status?.scan?.complete !== true ||
        indexedThroughBlock !== tipHeight ||
        storedHash !== tipHash) ||
    fault?.active === true ||
    !rebuildStateValid ||
    !readModelsOk
  ) {
    throw freshDataUnavailableError(
      checkpointRequested
        ? "The requested indexed canonical summary checkpoint is not exact and hash-bound."
        : "The indexed canonical summary checkpoint is not exactly at the Bitcoin Core tip.",
    );
  }
  return {
    indexedThroughBlock,
    tipHash: checkpointRequested ? checkpointHash : tipHash,
  };
}

async function internalCanonicalSummaryPayload(network, options = {}) {
  const before = await exactCanonicalSummaryCheckpoint(network, options);
  const ledger = await buildIndexedCanonicalLedgerPayload(
    network,
    "internal canonical summary",
    {
      exactHash: before.tipHash,
      exactHeight: before.indexedThroughBlock,
    },
  );
  if (
    !ledger ||
    ledger?.consistency?.ok !== true ||
    !ledgerPayloadHasCurrentChecks(ledger) ||
    ledgerPayloadIndexedThroughBlock(ledger) !== before.indexedThroughBlock
  ) {
    console.error(
      "Rejected internal canonical summary ledger:",
      JSON.stringify({
        consistency: ledger?.consistency ?? null,
        expectedIndexedThroughBlock: before.indexedThroughBlock,
        hasCurrentChecks: Boolean(ledger && ledgerPayloadHasCurrentChecks(ledger)),
        indexedThroughBlock: ledger
          ? ledgerPayloadIndexedThroughBlock(ledger)
          : null,
      }),
    );
    throw freshDataUnavailableError(
      "The indexed canonical ledger could not produce an exact consistent summary.",
    );
  }

  const checkpointSnapshotId = sha256Hex(
    Buffer.from(
      JSON.stringify({
        indexedThroughBlock: before.indexedThroughBlock,
        indexedThroughBlockHash: before.tipHash,
        sourceSnapshotId: ledger.snapshotId,
      }),
    ),
  ).slice(0, 24);
  const hashBoundLedger = {
    ...ledger,
    indexedThroughBlockHash: before.tipHash,
    snapshotId: checkpointSnapshotId,
  };
  const summaryPayloads = {
    growthSummary: attachLedgerMetadata(
      growthSummaryPayloadFromLedger(hashBoundLedger),
      hashBoundLedger,
    ),
    inceptionSummary: attachLedgerMetadata(
      inceptionSummaryPayloadFromLedger(hashBoundLedger),
      hashBoundLedger,
    ),
    infinitySummary: attachLedgerMetadata(
      infinitySummaryPayloadFromLedger(hashBoundLedger),
      hashBoundLedger,
    ),
    logSummary: attachLedgerMetadata(
      compactActivitySummaryPayload(
        hashBoundLedger.activityPayload,
        hashBoundLedger.metrics?.indexedThroughBlock,
      ),
      hashBoundLedger,
    ),
    marketplaceSummary: marketplaceSummaryPayloadFromLedger(hashBoundLedger),
    tokenSummary: attachLedgerMetadata(
      compactTokenDirectorySummaryPayload(
        ledgerTokenStateForScope(hashBoundLedger, ""),
      ),
      hashBoundLedger,
    ),
    workFloor: attachLedgerMetadata(hashBoundLedger.workFloor, hashBoundLedger),
    workSummary: internalCanonicalWorkSummaryPayload(hashBoundLedger),
  };
  for (const [key, payload] of Object.entries(summaryPayloads)) {
    const snapshotMatches =
      payloadSnapshotId(payload) === hashBoundLedger.snapshotId;
    const coverageMatches =
      proofIndexPayloadIndexedThroughBlock(payload) ===
      before.indexedThroughBlock;
    const networkValueValid = summaryPayloadHasFiniteNetworkValue(
      network,
      key,
      payload,
    );
    if (
      !payload ||
      !snapshotMatches ||
      !coverageMatches ||
      !networkValueValid
    ) {
      console.error(
        "Rejected internal canonical summary payload:",
        JSON.stringify({
          actualValue: payload?.actualValue ?? null,
          chartPoints: Array.isArray(payload?.chartPoints)
            ? payload.chartPoints.length
            : null,
          coverageMatches,
          expectedIndexedThroughBlock: before.indexedThroughBlock,
          indexedThroughBlock: proofIndexPayloadIndexedThroughBlock(payload),
          key,
          networkValueValid,
          registryAddress: payload?.registryAddress ?? null,
          registryId: payload?.registryId ?? null,
          snapshotMatches,
          stats: payload?.stats ?? null,
          ticker: payload?.ticker ?? null,
          tokenId: payload?.tokenId ?? null,
          tokenStats: payload?.token?.stats ?? null,
        }),
      );
      throw freshDataUnavailableError(
        `The indexed canonical ${key} payload is not a valid exact-ledger summary.`,
      );
    }
  }

  const after = await exactCanonicalSummaryCheckpoint(network, options);
  if (
    after.indexedThroughBlock !== before.indexedThroughBlock ||
    after.tipHash !== before.tipHash
  ) {
    throw freshDataUnavailableError(
      "The Bitcoin Core tip changed during canonical summary construction.",
    );
  }
  return {
    indexedThroughBlock: before.indexedThroughBlock,
    indexedThroughBlockHash: before.tipHash,
    ledger: ledgerConsistencyPayloadFromLedger(hashBoundLedger),
    network,
    snapshotId: hashBoundLedger.snapshotId,
    summaryPayloads,
  };
}

async function buildCanonicalLedgerPayload(network, fresh = false) {
  const emptyRegistryState = emptyRegistryPayload(network);
  const [
    activityState,
    registryState,
    tokenState,
    workTokenState,
    btcUsdQuote,
    sourceTipHeight,
  ] = await Promise.all([
    activityStateForCanonicalLedger(network, fresh),
    fresh
      ? safeRegistryPayload(network)
      : fastJsonBackedPayload(
          `registry:${network}`,
          `payload:registry:${network}`,
          () => safeRegistryPayload(network),
          REGISTRY_CACHE_TTL_MS,
          REGISTRY_CACHE_STALE_MS,
          emptyRegistryState,
        ),
    ledgerTokenPayload(network, "", fresh),
    ledgerTokenPayload(network, WORK_TOKEN_ID, fresh),
    network === "livenet"
      ? btcUsdPricePayload(network, { fresh })
      : Promise.resolve(null),
    network === "livenet" ? ledgerTipHeight(network) : Promise.resolve(null),
  ]);

  const valueTokenState = tokenStateWithScopedTokenOverride(
    tokenState,
    workTokenState,
    WORK_TOKEN_ID,
  );
  const seedAddresses = canonicalMailSeedAddresses({
    activityState,
    network,
    registryState,
    tokenState: valueTokenState,
    workTokenState,
  });
  const seededMailActivityState = activityStateIsProofIndexCanonical(activityState)
    ? seededMailActivityPayloadFromIndexedActivity(
        network,
        seedAddresses,
        activityState,
      )
    : await seededMailActivityPayload(network, seedAddresses);
  const baseActivity = dedupeActivityItems([
    ...(Array.isArray(activityState?.activity) ? activityState.activity : []),
    ...(Array.isArray(seededMailActivityState?.activity)
      ? seededMailActivityState.activity
      : []),
    ...(Array.isArray(registryState?.activity) ? registryState.activity : []),
  ]);
  let ledgerTokenState = valueTokenState;
  for (const config of BOND_TOKEN_CONFIGS) {
    const registryAddress = await bondRegistryAddressForNetwork(
      config,
      network,
      registryState,
    );
    if (!registryAddress) {
      continue;
    }
    const registryTxs = await fetchLegacyGenericTokenReplayTransactions(
      registryAddress,
      network,
    );
    const bondSeedTokens = [
      canonicalBondTokenDefinition(config, network, registryAddress),
    ];
    const bondSeedMints = bondMintsFromActivity(
      baseActivity,
      registryAddress,
      network,
      config,
    );
    const inceptionIssuanceOptions =
      config.tokenId === INCB_TOKEN_ID
        ? await canonicalInceptionIssuanceOptions(network, baseActivity)
        : {};
    const replayArguments = [
      [],
      new Map([[registryAddress, registryTxs]]),
      tokenIndexAddressForNetwork(network),
      network,
      config.tokenId,
      bondSeedTokens,
      bondSeedMints,
    ];
    const bondState =
      config.tokenId === INCB_TOKEN_ID
        ? tokenStateFromTransactionsWithCanonicalInceptionIssuance(
            ...replayArguments,
            baseActivity,
            {
              activity: baseActivity,
              registryState,
              tokenState: ledgerTokenState,
              workTokenState,
            },
            inceptionIssuanceOptions,
          )
        : tokenStateFromTransactions(...replayArguments);
    ledgerTokenState = tokenStateWithScopedTokenOverride(
      ledgerTokenState,
      await tokenPayloadWithSpendableListings(bondState, network),
      config.tokenId,
    );
  }
  let activity = dedupeActivityItems([
    ...tokenActivityItemsFromState(
      ledgerTokenState,
      ledgerTokenState?.indexAddress ?? "",
    ),
    ...baseActivity.filter((item) => !isTokenActivityItem(item)),
  ]);
  let activityPayload = {
    activity,
    canonicalMinerFeeCoverage: activityState?.canonicalMinerFeeCoverage,
    indexedAt: new Date().toISOString(),
    network,
    source: activityState?.source ?? mempoolBase(network),
    stats: activityStatsFromItems(activity, {
      addresses: Math.max(
        numericValue(activityState?.stats?.addresses),
        numericValue(seededMailActivityState?.stats?.addresses),
      ),
      registry: Array.isArray(registryState?.activity)
        ? registryState.activity.length
        : undefined,
      seededMail: seededMailActivityState?.stats?.total,
    }),
  };
  let workFloor = workFloorPayloadFromState(
    network,
    registryState,
    activityPayload,
    ledgerTokenState,
    workTokenState,
    {
      btcUsdQuote,
      valueCutoffMs: CANONICAL_CONFIRMED_TIP_CUTOFF_MS,
    },
  );
  const creditValueDetails = creditNetworkValueMetrics({
    baseValueAt: growthActualBaseNetworkValueAtProvider(
      registryState.records ?? [],
      activity,
      registryState.sales ?? [],
      ledgerTokenState.tokens ?? [],
      ledgerTokenState.mints ?? [],
      ledgerTokenState.transfers ?? [],
      ledgerTokenState.sales ?? [],
    ),
    canonicalMinerFeeCoverage: activityState?.canonicalMinerFeeCoverage,
    confirmedActivity: activity,
    cutoffMs: CANONICAL_CONFIRMED_TIP_CUTOFF_MS,
    includeEvents: true,
    tokenDefinitions: ledgerTokenState.tokens ?? [],
    tokenMints: ledgerTokenState.mints ?? [],
    tokenSales: ledgerTokenState.sales ?? [],
    tokenTransfers: ledgerTokenState.transfers ?? [],
  });
  ledgerTokenState = tokenStateWithCreditNetworkValueDetails(
    ledgerTokenState,
    creditValueDetails,
  );
  const valuedWorkTokenState = tokenStateWithCreditNetworkValueDetails(
    workTokenState,
    creditValueDetails,
  );
  activity = dedupeActivityItems([
    ...tokenActivityItemsFromState(
      ledgerTokenState,
      ledgerTokenState?.indexAddress ?? "",
    ),
    ...baseActivity.filter((item) => !isTokenActivityItem(item)),
  ]);
  activityPayload = {
    ...activityPayload,
    activity,
    indexedAt: new Date().toISOString(),
    stats: activityStatsFromItems(activity, {
      addresses: Math.max(
        numericValue(activityState?.stats?.addresses),
        numericValue(seededMailActivityState?.stats?.addresses),
      ),
      registry: Array.isArray(registryState?.activity)
        ? registryState.activity.length
        : undefined,
      seededMail: seededMailActivityState?.stats?.total,
    }),
  };
  workFloor = workFloorPayloadFromState(
    network,
    registryState,
    activityPayload,
    ledgerTokenState,
    valuedWorkTokenState,
    {
      btcUsdQuote,
      valueCutoffMs: CANONICAL_CONFIRMED_TIP_CUTOFF_MS,
    },
  );
  workFloor = await workFloorWithPreConsistencyMarketOverlay(
    workFloor,
    network,
    ledgerTokenState,
    { required: false },
  );
  const baseMetrics = ledgerMetricsFromState({
    activity,
    registryState,
    tokenState: ledgerTokenState,
    workFloor,
  });
  const indexedThroughBlock =
    Math.max(
      Number(baseMetrics.indexedThroughBlock) || 0,
      Number(activityState?.indexedThroughBlock) || 0,
      Number(activityState?.stats?.indexedThroughBlock) || 0,
      Number(registryState?.indexedThroughBlock) || 0,
      Number(ledgerTokenState?.indexedThroughBlock) || 0,
      Number(valuedWorkTokenState?.indexedThroughBlock) || 0,
    ) || baseMetrics.indexedThroughBlock;
  const metrics = {
    ...baseMetrics,
    indexedThroughBlock,
    sourceTipHeight: Number.isSafeInteger(sourceTipHeight)
      ? sourceTipHeight
      : undefined,
    tipLagBlocks:
      Number.isSafeInteger(sourceTipHeight) && indexedThroughBlock
        ? Math.max(0, sourceTipHeight - indexedThroughBlock)
        : undefined,
  };
  const sourceHashes = ledgerSourceHashes({
    activityState,
    registryState,
    seededMailActivityState,
    tokenState: ledgerTokenState,
    workTokenState: valuedWorkTokenState,
  });
  const snapshotId = sha256Hex(
    Buffer.from(
      JSON.stringify({
        metrics,
        network,
        sourceHashes,
      }),
    ),
  ).slice(0, 24);
  const ledger = {
    activity,
    activityPayload,
    btcUsdQuote,
    generatedAt: new Date().toISOString(),
    metrics,
    network,
    registryState,
    seededMailActivityState,
    snapshotId,
    sourceHashes,
    sourceTipHeight,
    tokenState: ledgerTokenState,
    workFloor,
    workTokenState: valuedWorkTokenState,
  };
  const growthSummary = growthSummaryPayloadFromLedger(ledger);
  const consistency = ledgerSnapshotChecks({
    activity,
    growthSummary,
    metrics,
    network,
    seededMailActivityState,
    sourceHashes,
    tokenState: ledgerTokenState,
    workFloor,
  });
  const summaryLedger = {
    ...ledger,
    consistency,
  };
  const inceptionSummary = inceptionSummaryPayloadFromLedger(summaryLedger);
  const infinitySummary = infinitySummaryPayloadFromLedger(summaryLedger);

  return {
    ...ledger,
    activityPayload: attachLedgerMetadata(activityPayload, {
      ...ledger,
      consistency,
    }),
    consistency,
    growthSummary: attachLedgerMetadata(growthSummary, {
      ...ledger,
      consistency,
    }),
    inceptionSummary: attachLedgerMetadata(inceptionSummary, {
      ...ledger,
      consistency,
    }),
    infinitySummary: attachLedgerMetadata(infinitySummary, {
      ...ledger,
      consistency,
    }),
    workFloor: attachLedgerMetadata(workFloor, {
      ...ledger,
      consistency,
    }),
  };
}

async function refreshCanonicalLedgerPayload(network, fresh = false) {
  const previous = await existingCanonicalLedgerPayload(network);
  const next = await buildCanonicalLedgerPayload(network, fresh).catch((error) => {
    console.error(
      `Canonical ledger refresh build failed for ${network}: ${errorSummary(error)}`,
    );
    return null;
  });
  if (!next) {
    if (previous) {
      return previous;
    }
    throw freshDataUnavailableError(
      `Canonical ledger refresh is unavailable for ${network}.`,
    );
  }
  const [nextCoversTip, previousCoversTip] = await Promise.all([
    ledgerPayloadCoversTip(next, network),
    previous ? ledgerPayloadCoversTip(previous, network) : Promise.resolve(false),
  ]);
  const shouldRejectRegression =
    ledgerPayloadLooksWorse(next, previous) &&
    !(nextCoversTip && !previousCoversTip);
  const payload = shouldRejectRegression ? previous : next;

  if (payload === previous) {
    console.error(
      `Rejected ledger payload regression for ${network}: ${JSON.stringify(next.metrics)} < ${JSON.stringify(previous?.metrics)}.`,
    );
  }

  cacheCanonicalLedgerPayload(network, payload);
  return payload;
}

async function canonicalLedgerPayload(network, fresh = false) {
  const cacheKey = `ledger:${network}`;
  const payloadKey = `payload:${cacheKey}`;
  let cached = RESPONSE_CACHE.get(payloadKey);
  const now = Date.now();
  if (cached?.payload && !ledgerPayloadHasCurrentChecks(cached.payload)) {
    RESPONSE_CACHE.delete(payloadKey);
    cached = null;
  }
  if (!cached?.payload) {
    const persistedPayload = await existingCanonicalLedgerPayload(network);
    if (persistedPayload) {
      cached = RESPONSE_CACHE.get(payloadKey);
    }
  }
  if (fresh) {
    if (
      cached?.payload &&
      ledgerPayloadAgeMs(cached.payload, now) < LEDGER_FRESH_MIN_INTERVAL_MS &&
      (await ledgerPayloadCoversTip(cached.payload, network))
    ) {
      return cached.payload;
    }
    if (cached?.promise) {
      return cached.promise;
    }
    const promise = refreshCanonicalLedgerPayload(network, true).finally(() => {
      const current = RESPONSE_CACHE.get(payloadKey);
      if (current?.promise === promise) {
        RESPONSE_CACHE.set(payloadKey, { ...current, promise: null });
      }
    });
    RESPONSE_CACHE.set(payloadKey, {
      expiresAt: cached?.expiresAt ?? Date.now(),
      payload: cached?.payload,
      promise,
      staleUntil: cached?.staleUntil ?? Date.now() + LEDGER_CACHE_STALE_MS,
    });
    return promise;
  }

  if (cached?.payload && now < cached.expiresAt) {
    return cached.payload;
  }
  if (cached?.payload && now < cached.staleUntil) {
    return cached.payload;
  }
  if (cached?.promise) {
    return cached.promise;
  }

  const promise = refreshCanonicalLedgerPayload(network, false).finally(() => {
    const current = RESPONSE_CACHE.get(payloadKey);
    if (current?.promise === promise) {
      RESPONSE_CACHE.set(payloadKey, { ...current, promise: null });
    }
  });
  RESPONSE_CACHE.set(payloadKey, {
    expiresAt: now,
    promise,
    staleUntil: now + LEDGER_CACHE_STALE_MS,
  });
  return promise;
}

function refreshCanonicalLedgerPayloadInBackground(network, fresh = false) {
  if (!ENABLE_API_LEDGER_BACKGROUND_REFRESH) {
    return;
  }

  const cacheKey = `ledger:${network}`;
  if (BACKGROUND_LEDGER_REFRESHES.has(cacheKey)) {
    return;
  }
  if (
    backgroundRefreshRecentlyStarted(
      cacheKey,
      BACKGROUND_DERIVED_REFRESH_INTERVAL_MS,
    )
  ) {
    return;
  }

  BACKGROUND_LEDGER_REFRESHES.add(cacheKey);
  void refreshCanonicalLedgerPayload(network, fresh)
    .catch((error) => {
      console.error(
        `Ledger refresh failed for ${network}: ${errorSummary(error)}`,
      );
    })
    .finally(() => {
      BACKGROUND_LEDGER_REFRESHES.delete(cacheKey);
    });
}

async function summaryCanonicalLedgerPayload(network, fresh = false) {
  const fallback = await existingCanonicalLedgerPayload(network);
  if (fresh) {
    const currentFallback = await exactTipLedgerPayloadOrNull(
      fallback,
      network,
      "fresh canonical ledger fallback",
    );
    if (currentFallback) {
      refreshCanonicalLedgerPayloadInBackground(network, true);
      return currentFallback;
    }
    const refreshed = await payloadWithFallbackAfterMs(
      canonicalLedgerPayload(network, true),
      null,
      LEDGER_SUMMARY_FRESH_WAIT_MS,
    );
    const currentRefreshed = await exactTipLedgerPayloadOrNull(
      refreshed,
      network,
      "fresh canonical ledger",
    );
    if (
      currentRefreshed &&
      !(currentFallback && ledgerPayloadLooksWorse(currentRefreshed, currentFallback))
    ) {
      return currentRefreshed;
    }
    refreshCanonicalLedgerPayloadInBackground(network, true);
    throw freshDataUnavailableError(
      "Fresh canonical ledger is catching up to the Bitcoin Core tip.",
    );
  }

  if (network === "livenet") {
    const currentFallback = await currentLedgerPayloadOrNull(
      fallback,
      network,
      "canonical ledger fallback",
    );
    if (currentFallback) {
      return currentFallback;
    }
    if (!ENABLE_REQUEST_LEDGER_RECOVERY) {
      refreshCanonicalLedgerPayloadInBackground(network, true);
      return ledgerPayloadHasFiniteNetworkValues(fallback) ? fallback : null;
    }
    const replayedFallback = await ledgerWithReplayedCreditNetworkValues(
      fallback,
      network,
      "canonical ledger fallback",
    );
    const currentReplayedFallback = await currentLedgerPayloadOrNull(
      replayedFallback,
      network,
      "credit-value replay fallback",
    );
    if (currentReplayedFallback) {
      cacheCanonicalLedgerPayload(network, currentReplayedFallback);
      return currentReplayedFallback;
    }
    const deltaFallback = await ledgerWithProofIndexEventDelta(
      fallback,
      network,
      "canonical ledger fallback",
    );
    if (deltaFallback) {
      return deltaFallback;
    }
    const refreshed = await payloadWithFallbackAfterMs(
      canonicalLedgerPayload(network, true),
      null,
      LEDGER_SUMMARY_FRESH_WAIT_MS,
    );
    const currentRefreshed = await currentLedgerPayloadOrNull(
      refreshed,
      network,
      "recovered canonical ledger",
    );
    if (
      currentRefreshed &&
      !(currentFallback && ledgerPayloadLooksWorse(currentRefreshed, currentFallback))
    ) {
      return currentRefreshed;
    }
    refreshCanonicalLedgerPayloadInBackground(network, true);
    return ledgerPayloadHasFiniteNetworkValues(fallback) ? fallback : null;
  }

  if (fallback) {
    return fallback;
  }

  refreshCanonicalLedgerPayloadInBackground(network, false);
  return null;
}

async function activityPayloadWithLiveWorkTokenOverlay(ledger, fresh = false) {
  if (!ledger || ledger.network !== "livenet" || !ledger.tokenState) {
    return ledger?.activityPayload;
  }

  let workTokenState = await liveWorkTokenStateWithFallbackAfterMs(
    ledger.network,
    ledgerTokenStateForScope(ledger, WORK_TOKEN_ID),
    WORK_TOKEN_LIVE_RECOVERY_WAIT_MS,
    { recoverClosedSales: true, recoverClosedSalesOnly: true },
  );
  workTokenState = fresh
    ? await tokenStateWithLivePendingTransactionCheck(
        workTokenState,
        ledger.network,
      )
    : tokenStateWithoutDroppedPendingTransactions(workTokenState, ledger.network);
  let valueTokenState = tokenStateWithScopedTokenOverride(
    tokenStateWithoutDroppedPendingTransactions(ledger.tokenState, ledger.network),
    workTokenState,
    WORK_TOKEN_ID,
  );
  valueTokenState = fresh
    ? await tokenStateWithLivePendingTransactionCheck(
        valueTokenState,
        ledger.network,
      )
    : tokenStateWithoutDroppedPendingTransactions(valueTokenState, ledger.network);
  valueTokenState = await tokenStateWithReconciledListingSeals(
    valueTokenState,
    ledger.network,
  );
  const baseActivity = Array.isArray(ledger.activityPayload?.activity)
    ? ledger.activityPayload.activity
    : Array.isArray(ledger.activity)
      ? ledger.activity
      : [];
  const activity = dedupeActivityItems([
    ...baseActivity.filter((item) => !isTokenActivityItem(item)),
    ...tokenActivityItemsFromState(
      valueTokenState,
      valueTokenState?.indexAddress ?? "",
    ),
  ]);
  const payload = {
    ...(ledger.activityPayload ?? {}),
    activity,
    indexedAt: new Date().toISOString(),
    network: ledger.network,
    stats: activityStatsFromItems(activity, ledger.activityPayload?.stats ?? {}),
  };
  return attachLedgerMetadata(payload, ledger);
}

async function mergedLogActivityPayload(network, fresh = false) {
  if (network === "livenet" && !fresh) {
    return stableProofIndexLogPayload(network);
  }

  const ledger = await summaryCanonicalLedgerPayload(network, fresh);
  if (ledger) {
    return (
      (await activityPayloadWithLiveWorkTokenOverlay(ledger, fresh)) ??
      ledger.activityPayload
    );
  }

  if (fresh) {
    throw freshDataUnavailableError("Fresh Log ledger is unavailable.");
  }

  if (network === "livenet") {
    throw freshDataUnavailableError("Current Log ledger is unavailable.");
  }

  const canonicalLedger = await canonicalLedgerPayload(network, false);
  return (
    (await activityPayloadWithLiveWorkTokenOverlay(canonicalLedger, fresh)) ??
    canonicalLedger.activityPayload
  );
}

function definitivePinnedLogQueryDisposition(value) {
  return new Set([
    "confirmed-invalid-nonpublic",
    "confirmed-nonpublic",
    "nonpublic-kind-filter",
    "not-indexed-proof-event",
    "terminal-nonpublic",
  ]).has(String(value ?? ""));
}

function logHistoryReadRequiresFullSummaryTotal(requestedKind, eligibility) {
  return (
    !String(requestedKind ?? "").trim() &&
    !String(eligibility?.pagination?.query ?? "").trim()
  );
}

async function stableCanonicalLogSummaryPayload(network, surface) {
  const summary = await summaryPayloadWithCanonicalProvenance(
    await activitySummaryPayload(network, false),
    network,
    false,
    "log-summary",
  );
  if (!payloadSnapshotId(summary)) {
    const error = freshDataUnavailableError(
      `Stable ${surface} has no authenticated canonical Log snapshot.`,
    );
    error.details = {
      code: "CANONICAL_LOG_SNAPSHOT_UNAVAILABLE",
      surface,
    };
    throw error;
  }
  return summary;
}

async function verifyStableLogCheckpointAfterRead(summary, network, surface) {
  const checkpoint = await verifiedSummaryPayloadCheckpoint(
    summary,
    network,
    false,
    surface,
  );
  if (
    checkpoint.indexedThroughBlock !==
      proofIndexPayloadIndexedThroughBlock(summary) ||
    checkpoint.indexedThroughBlockHash !==
      payloadIndexedThroughBlockHash(summary)
  ) {
    const error = freshDataUnavailableError(
      `Stable ${surface} changed while its pinned snapshot was being read.`,
    );
    error.details = {
      code: "CANONICAL_LOG_STABLE_CHECKPOINT_CHANGED",
      indexedThroughBlock: proofIndexPayloadIndexedThroughBlock(summary) || null,
      indexedThroughBlockHash: payloadIndexedThroughBlockHash(summary) || null,
      snapshotId: payloadSnapshotId(summary) || null,
      surface,
    };
    throw error;
  }
  return checkpoint;
}

async function stableProofIndexLogPayload(network) {
  const summary = await stableCanonicalLogSummaryPayload(network, "Log");
  const summarySnapshotId = payloadSnapshotId(summary);
  const summaryHeight = proofIndexPayloadIndexedThroughBlock(summary);
  const summaryTotal = Number(
    summary.totalCount ?? summary.stats?.total ?? summary.activity?.length ?? 0,
  );
  const summaryPending = Number(summary.stats?.pending ?? -1);
  const page = await proofIndexCanonicalActivityPayload(network, {
    snapshotId: summarySnapshotId,
  });
  const activity = Array.isArray(page?.activity) ? page.activity : [];
  const pageHeight = proofIndexPayloadIndexedThroughBlock(page);
  const pageSnapshotId = payloadSnapshotId(page);
  const pageTotal = Number(
    page?.totalCount ?? page?.stats?.total ?? activity.length,
  );
  const pageSnapshotTotal = Number(page?.snapshotTotalCount ?? -1);
  const pagePending = activity.filter((item) => !item?.confirmed).length;
  const canonicalMinerFeeCoverage = verifiedCanonicalMinerFeeCoverage(
    page?.canonicalMinerFeeCoverage ?? page?.stats?.canonicalMinerFeeCoverage,
  );
  const summaryLatestEventBlock = Number(summary.stats?.latestEventBlock ?? 0);
  const pageLatestEventBlock = Number(page?.latestEventBlock ?? 0);
  if (
    !page ||
    summaryHeight <= 0 ||
    summaryTotal < 0 ||
    pageHeight !== summaryHeight ||
    pageSnapshotId !== summarySnapshotId ||
    pageTotal !== summaryTotal ||
    pageSnapshotTotal !== summaryTotal ||
    activity.length !== summaryTotal ||
    (summaryPending >= 0 && pagePending !== summaryPending) ||
    !canonicalMinerFeeCoverage ||
    (summaryLatestEventBlock > 0 &&
      pageLatestEventBlock !== summaryLatestEventBlock)
  ) {
    const error = freshDataUnavailableError(
      "Stable relational Log does not match its authenticated canonical summary snapshot.",
    );
    error.details = {
      code: "CANONICAL_LOG_STABLE_MISMATCH",
      pageHeight: pageHeight || null,
      pageLatestEventBlock: pageLatestEventBlock || null,
      pagePending,
      pageSnapshotId: pageSnapshotId || null,
      pageSnapshotTotal,
      pageTotal,
      summaryHeight,
      summaryLatestEventBlock: summaryLatestEventBlock || null,
      summaryPending,
      summarySnapshotId,
      summaryTotal,
    };
    throw error;
  }

  await verifyStableLogCheckpointAfterRead(summary, network, "log");

  return {
    activity,
    canonicalMinerFeeCoverage,
    consistency: summary.consistency,
    hasMore: false,
    indexedAt: summary.indexedAt ?? page.indexedAt,
    indexedThroughBlock: summaryHeight,
    indexedThroughBlockHash: payloadIndexedThroughBlockHash(summary),
    ledgerGeneratedAt: summary.ledgerGeneratedAt ?? page.ledgerGeneratedAt,
    network,
    provenance: {
      ...(summary.provenance ?? {}),
      surface: "log",
    },
    snapshotId: summarySnapshotId,
    source: page.source,
    stats: {
      ...activityStatsFromItems(activity, {
        ...(summary.stats ?? {}),
        canonicalMinerFeeCoverage,
      }),
      indexedThroughBlock: summaryHeight,
      latestEventBlock: pageLatestEventBlock || undefined,
    },
    summaryOnly: false,
    totalCount: summaryTotal,
  };
}

async function stableProofIndexLogHistoryPayload(
  network,
  kind,
  searchParams,
) {
  const requestedKind = String(kind ?? "").trim().toLowerCase();
  const eligibility = proofIndexLogHistoryReadEligibility(
    requestedKind,
    searchParams,
  );
  const summary = await stableCanonicalLogSummaryPayload(
    network,
    "Log history",
  );
  const summarySnapshotId = payloadSnapshotId(summary);
  const summaryHeight = proofIndexPayloadIndexedThroughBlock(summary);
  const summaryTotal = Number(
    summary.totalCount ?? summary.stats?.total ?? summary.activity?.length ?? 0,
  );
  const requestedSnapshotId = String(
    eligibility.pagination.snapshotId ?? "",
  ).trim();
  if (requestedSnapshotId && requestedSnapshotId !== summarySnapshotId) {
    const error = freshDataUnavailableError(
      "Stable Log history cursor does not match the authenticated last-good snapshot.",
    );
    error.details = {
      code: "CANONICAL_LOG_HISTORY_STABLE_SNAPSHOT_MISMATCH",
      requestedSnapshotId,
      summarySnapshotId,
    };
    throw error;
  }

  const boundSearchParams = new URLSearchParams(searchParams ?? undefined);
  boundSearchParams.set("snapshot", summarySnapshotId);
  let page = await proofIndexLogHistoryPayload(
    network,
    requestedKind,
    boundSearchParams,
    { currentRelational: true },
  );
  if (!page) {
    throw freshDataUnavailableError(
      "Stable Log history is unavailable for the authenticated last-good snapshot.",
    );
  }

  const pageHeight = proofIndexPayloadIndexedThroughBlock(page);
  const pageSnapshotId = payloadSnapshotId(page);
  const exactQueryTxid = /^[0-9a-f]{64}$/u.test(
    eligibility.pagination.query,
  )
    ? eligibility.pagination.query
    : "";
  if (
    pageSnapshotId !== summarySnapshotId ||
    (!exactQueryTxid && pageHeight !== summaryHeight) ||
    (exactQueryTxid && (pageHeight <= 0 || pageHeight > summaryHeight)) ||
    (!requestedKind &&
      !eligibility.pagination.query &&
      Number(page.totalCount ?? -1) !== summaryTotal)
  ) {
    const error = freshDataUnavailableError(
      "Stable Log history page does not match its authenticated canonical summary snapshot.",
    );
    error.details = {
      code: "CANONICAL_LOG_HISTORY_STABLE_MISMATCH",
      pageHeight: pageHeight || null,
      pageSnapshotId: pageSnapshotId || null,
      pageTotal: Number(page.totalCount ?? -1),
      summaryHeight,
      summarySnapshotId,
      summaryTotal,
    };
    throw error;
  }

  if (exactQueryTxid) {
    const pageItems = Array.isArray(page.items) ? page.items : [];
    if (pageItems.length > 0) {
      const pageEventIds = [
        ...new Set(pageItems.map((item) => Number(item?.eventId))),
      ];
      const validPageEventIds =
        pageEventIds.length === pageItems.length &&
        pageEventIds.every(
          (eventId) => Number.isSafeInteger(eventId) && eventId > 0,
        );
      const canonicalPage = validPageEventIds
        ? await proofIndexCanonicalActivityPayload(network, {
            eventIds: pageEventIds,
            snapshotId: summarySnapshotId,
          })
        : null;
      const canonicalItems = Array.isArray(canonicalPage?.activity)
        ? canonicalPage.activity
        : [];
      const canonicalItemsByEventId = new Map(
        canonicalItems.map((item) => [Number(item?.eventId), item]),
      );
      const membershipEventIds = Array.isArray(
        canonicalPage?.membershipEventIds,
      )
        ? canonicalPage.membershipEventIds.map(Number)
        : [];
      const confirmedPageItems = pageItems.filter(
        (item) => item?.confirmed === true,
      );
      const confirmedCoverage = confirmedPageItems.length > 0
        ? verifiedCanonicalMinerFeeCoverage(
            canonicalPage?.canonicalMinerFeeCoverage ??
              canonicalPage?.stats?.canonicalMinerFeeCoverage,
          )
        : true;
      if (
        !validPageEventIds ||
        canonicalPage?.membershipRestricted !== true ||
        proofIndexPayloadIndexedThroughBlock(canonicalPage) !== summaryHeight ||
        payloadSnapshotId(canonicalPage) !== summarySnapshotId ||
        membershipEventIds.length !== pageEventIds.length ||
        pageEventIds.some(
          (eventId) => !membershipEventIds.includes(eventId),
        ) ||
        canonicalItems.length !== pageItems.length ||
        pageItems.some((item) => {
          const canonicalItem = canonicalItemsByEventId.get(
            Number(item?.eventId),
          );
          return (
            !canonicalItem ||
            activityKey(canonicalItem) !== activityKey(item)
          );
        }) ||
        !confirmedCoverage
      ) {
        const error = freshDataUnavailableError(
          "Exact Log query returned data outside its authenticated last-good snapshot.",
        );
        error.details = {
          code: "CANONICAL_LOG_EXACT_QUERY_OUTSIDE_SNAPSHOT",
          query: exactQueryTxid,
          snapshotId: summarySnapshotId,
        };
        throw error;
      }
    }
    if (
      pageItems.length === 0 &&
      !definitivePinnedLogQueryDisposition(page.queryDisposition)
    ) {
      page = await exactLogHistoryMissPayload(
        page,
        network,
        exactQueryTxid,
        boundSearchParams,
      );
    }
    const finalPageItems = Array.isArray(page?.items) ? page.items : [];
    if (
      !page ||
      (finalPageItems.length === 0 &&
        !definitivePinnedLogQueryDisposition(page.queryDisposition))
    ) {
      const error = freshDataUnavailableError(
        "Exact Log query is not present in the authenticated last-good snapshot.",
      );
      error.details = {
        code: "CANONICAL_LOG_EXACT_QUERY_NOT_IN_SNAPSHOT",
        query: exactQueryTxid,
        snapshotId: summarySnapshotId,
      };
      throw error;
    }
  }

  await verifyStableLogCheckpointAfterRead(summary, network, "log-history");

  return {
    ...page,
    consistency: summary.consistency,
    indexedAt: summary.indexedAt ?? page.indexedAt,
    indexedThroughBlock: summaryHeight,
    indexedThroughBlockHash: payloadIndexedThroughBlockHash(summary),
    ledgerGeneratedAt: summary.ledgerGeneratedAt ?? page.ledgerGeneratedAt,
    provenance: {
      ...(summary.provenance ?? {}),
      surface: "log-history",
    },
    snapshotId: summarySnapshotId,
  };
}

async function freshProofIndexLogHistoryPayload(network, kind, searchParams) {
  const requestedKind = String(kind ?? "").trim().toLowerCase();
  const eligibility = proofIndexLogHistoryReadEligibility(
    requestedKind,
    searchParams,
  );
  const summary = await summaryPayloadWithCanonicalProvenance(
    await activitySummaryPayload(network, true),
    network,
    true,
    "log-summary",
  );
  const summarySnapshotId = payloadSnapshotId(summary);
  const requestedSnapshotId = String(
    eligibility.pagination.snapshotId ?? "",
  ).trim();
  if (
    !summarySnapshotId ||
    (requestedSnapshotId && requestedSnapshotId !== summarySnapshotId)
  ) {
    const error = freshDataUnavailableError(
      "Fresh Log history cannot bind to the exact canonical Log summary.",
    );
    error.details = {
      code: "CANONICAL_LOG_HISTORY_SNAPSHOT_MISMATCH",
      requestedSnapshotId: requestedSnapshotId || null,
      summarySnapshotId: summarySnapshotId || null,
    };
    throw error;
  }
  const boundSearchParams = new URLSearchParams(searchParams ?? undefined);
  boundSearchParams.set("snapshot", summarySnapshotId);
  const page = await proofIndexLogHistoryPayload(
    network,
    requestedKind,
    boundSearchParams,
    { currentRelational: true },
  );
  if (!page) {
    throw freshDataUnavailableError(
      "Fresh relational Log history is unavailable.",
    );
  }
  const pageHeight = proofIndexPayloadIndexedThroughBlock(page);
  const summaryHeight = proofIndexPayloadIndexedThroughBlock(summary);
  const pageSnapshotId = payloadSnapshotId(page);
  const pageTotal = Number(page.totalCount ?? page.items?.length ?? 0);
  const pageSnapshotTotal = Number(page.snapshotTotalCount ?? -1);
  const summaryTotal = Number(
    summary.totalCount ?? summary.stats?.total ?? summary.activity?.length ?? 0,
  );
  const fullSummaryRead = logHistoryReadRequiresFullSummaryTotal(
    requestedKind,
    eligibility,
  );
  if (
    pageHeight <= 0 ||
    pageHeight !== summaryHeight ||
    !pageSnapshotId ||
    pageSnapshotId !== summarySnapshotId ||
    (fullSummaryRead && pageSnapshotTotal !== summaryTotal)
  ) {
    const error = freshDataUnavailableError(
      "Fresh Log history does not match the exact canonical Log summary.",
    );
    error.details = {
      code: "CANONICAL_LOG_HISTORY_MISMATCH",
      pageHeight: pageHeight || null,
      pageSnapshotId: pageSnapshotId || null,
      pageSnapshotTotal,
      pageTotal,
      requestedKind: requestedKind || null,
      summaryHeight: summaryHeight || null,
      summarySnapshotId: summarySnapshotId || null,
      summaryTotal,
    };
    throw error;
  }

  await verifiedFreshLogCheckpointAfterRead(
    summary,
    network,
    "log-history",
  );

  return {
    ...page,
    consistency: summary.consistency,
    indexedAt: summary.indexedAt ?? page.indexedAt,
    indexedThroughBlock: summaryHeight,
    indexedThroughBlockHash: payloadIndexedThroughBlockHash(summary),
    ledgerGeneratedAt: summary.ledgerGeneratedAt ?? page.ledgerGeneratedAt,
    provenance: {
      ...(summary.provenance ?? {}),
      surface: "log-history",
    },
    snapshotId: summarySnapshotId,
  };
}

async function verifiedFreshLogCheckpointAfterRead(summary, network, surface) {
  try {
    const checkpoint = await verifiedSummaryPayloadCheckpoint(
      summary,
      network,
      true,
      surface,
    );
    if (
      checkpoint?.exactTip !== true ||
      checkpoint.indexedThroughBlock !==
        proofIndexPayloadIndexedThroughBlock(summary) ||
      checkpoint.indexedThroughBlockHash !==
        payloadIndexedThroughBlockHash(summary)
    ) {
      throw new Error("Post-read checkpoint is not the requested exact tip.");
    }
    return checkpoint;
  } catch (cause) {
    const error = freshDataUnavailableError(
      `${surface} canonical tip changed during the relational read.`,
    );
    error.details = {
      causeCode: cause?.details?.code ?? null,
      code:
        surface === "log-history"
          ? "CANONICAL_LOG_HISTORY_TIP_CHANGED"
          : "CANONICAL_LOG_TIP_CHANGED",
      indexedThroughBlock: proofIndexPayloadIndexedThroughBlock(summary) || null,
      indexedThroughBlockHash: payloadIndexedThroughBlockHash(summary) || null,
      snapshotId: payloadSnapshotId(summary) || null,
      surface,
    };
    throw error;
  }
}

