const BOOST_VISIBLE_EVENT_KINDS = new Set([
  "boost-post",
  "boost-reply",
  "boost-reboost",
]);

const BOOST_INDEX_EVENT_KINDS = new Set(BOOST_EVENT_KINDS);

const BOOST_VALUE_WINDOWS = new Set(["hour", "day", "week", "all"]);
const BOOST_SORT_MODES = new Set(["value", "newest", "oldest"]);
const BOOST_TIMELINE_VIEWS = new Set(["all", "following"]);
const BOOST_PROFILE_TABS = new Set([
  "boosts",
  "replies",
  "purchased",
  "likes",
  "replies-to",
]);

function boostHexTxid(value) {
  const txid = String(value ?? "").trim().toLowerCase();
  return /^[0-9a-f]{64}$/u.test(txid) ? txid : "";
}

function boostAddress(value) {
  return String(value ?? "").trim();
}

function boostSignalSats(item) {
  return Math.max(
    0,
    numericValue(
      item?.proofSignalSats ??
        item?.signalSats ??
        item?.amountSats ??
        item?.proofs ??
        0,
    ),
  );
}

function boostWorkSignalSubatoms(item) {
  const value = String(
    item?.workSignalSubatoms ?? item?.workSignalAtoms ?? item?.workSignal ?? "",
  ).trim();
  if (!/^(?:0|[1-9]\d*)$/u.test(value) || value === "0") {
    return "";
  }
  return value;
}

function boostWorkSignalDisplay(item) {
  const subatoms = boostWorkSignalSubatoms(item);
  if (!subatoms) {
    return "";
  }
  try {
    return formatWorkSubatoms(BigInt(subatoms));
  } catch {
    return "";
  }
}

function boostWorkNetworkValue(workFloor) {
  const actual = workFloor?.actualValue ?? {};
  const networkValueQ8 = canonicalNonNegativeIntegerText(
    workFloor?.liveNetworkValueQ8 ??
      actual.liveNetworkValueQ8 ??
      workFloor?.networkValueQ8 ??
      actual.networkValueQ8 ??
      workFloor?.totalQ8 ??
      actual.totalQ8 ??
      "",
  );
  const networkValueSats = String(
    workFloor?.liveNetworkValueSats ??
      actual.liveNetworkValueSats ??
      workFloor?.networkValueSats ??
      actual.networkValueSats ??
      workFloor?.totalSats ??
      actual.totalSats ??
      "",
  ).trim();
  return { networkValueQ8, networkValueSats };
}

function emptyBoostWorkSignalValue() {
  return {
    workSignalValueQ8: "0",
    workSignalValueSats: 0,
    workSignalValueSatsExact: "0",
  };
}

function boostWorkSignalValue(workSignalSubatoms, workFloor) {
  const subatoms = canonicalNonNegativeIntegerText(workSignalSubatoms, {
    allowZero: false,
  });
  if (!subatoms) {
    return emptyBoostWorkSignalValue();
  }
  const { networkValueQ8, networkValueSats } =
    boostWorkNetworkValue(workFloor);
  try {
    const valueQ8 = workSubatomsValueAtNetworkQ8(
      BigInt(subatoms),
      networkValueSats,
      networkValueQ8,
    );
    if (valueQ8 === null || valueQ8 < 0n) {
      return emptyBoostWorkSignalValue();
    }
    return {
      workSignalValueQ8: valueQ8.toString(),
      workSignalValueSats: q8ToNumber(valueQ8),
      workSignalValueSatsExact: q8ToCanonicalDecimal(valueQ8),
    };
  } catch {
    return emptyBoostWorkSignalValue();
  }
}

function boostSortMode(searchParams) {
  const mode = String(searchParams.get("sort") ?? "value")
    .trim()
    .toLowerCase();
  return BOOST_SORT_MODES.has(mode) ? mode : "value";
}

function boostValueWindow(searchParams) {
  const valueWindow = String(searchParams.get("window") ?? "all")
    .trim()
    .toLowerCase();
  return BOOST_VALUE_WINDOWS.has(valueWindow) ? valueWindow : "all";
}

function boostTimelineView(searchParams) {
  const view = String(searchParams.get("view") ?? searchParams.get("tab") ?? "all")
    .trim()
    .toLowerCase();
  return BOOST_TIMELINE_VIEWS.has(view) ? view : "all";
}

function boostProfileTab(searchParams) {
  const tab = String(
    searchParams.get("profileTab") ?? searchParams.get("profileView") ?? "boosts",
  )
    .trim()
    .toLowerCase();
  return BOOST_PROFILE_TABS.has(tab) ? tab : "boosts";
}

function boostWindowStartMs(valueWindow, nowMs = Date.now()) {
  if (valueWindow === "hour") {
    return nowMs - 60 * 60_000;
  }
  if (valueWindow === "day") {
    return nowMs - 24 * 60 * 60_000;
  }
  if (valueWindow === "week") {
    return nowMs - 7 * 24 * 60 * 60_000;
  }
  return 0;
}

function boostEventTimeMs(item) {
  const date = new Date(
    item?.createdAt ??
      item?.confirmedAt ??
      item?.timestamp ??
      item?.indexedAt ??
      Date.now(),
  );
  return Number.isFinite(date.getTime()) ? date.getTime() : 0;
}

function boostEventSearchText(item, state, profileState) {
  return [
    item?.text,
    item?.memo,
    item?.detail,
    item?.title,
    item?.authorAddress,
    item?.actor,
    item?.profileId,
    profileState?.id,
    profileState?.name,
    state?.ownerAddress,
  ]
    .map((value) => String(value ?? "").trim().toLowerCase())
    .filter(Boolean)
    .join(" ");
}

function boostDisplayName(...values) {
  return values.map((value) => String(value ?? "").trim()).find(Boolean) ?? "";
}

function boostPostTxid(item) {
  return boostHexTxid(
    item?.boostTxid ??
      item?.targetTxid ??
      item?.parentTxid ??
      item?.replyToTxid ??
      item?.txid,
  );
}

function boostTargetTxid(item) {
  return boostHexTxid(
    item?.targetTxid ??
      item?.boostTxid ??
      item?.parentTxid ??
      item?.replyToTxid ??
      "",
  );
}

function boostFollowTargetAddress(item) {
  return boostAddress(
    item?.targetAddress ??
      item?.followedAddress ??
      item?.recipientAddress ??
      item?.to ??
      item?.currentOwnerAddress,
  );
}

function boostFollowTargetId(item) {
  return normalizePowId(
    String(
      item?.targetId ??
        item?.followedId ??
        item?.profileId ??
        item?.authorId ??
        "",
    ),
  );
}

function boostPriceSats(item) {
  return Math.max(
    0,
    numericValue(
      item?.priceSats ??
        item?.salePriceSats ??
        item?.listingPriceSats ??
        item?.priceProofs ??
        0,
    ),
  );
}

function boostOwnershipState(items) {
  const states = new Map();
  const counts = new Map();
  const followStates = new Map();
  const profiles = new Map();
  const ordered = [...items].sort(
    (left, right) => boostEventTimeMs(left) - boostEventTimeMs(right),
  );

  const ensureState = (txid) => {
    if (!txid) {
      return null;
    }
    const existing = states.get(txid);
    if (existing) {
      return existing;
    }
    const next = {
      listing: null,
      ownerAddress: "",
    };
    states.set(txid, next);
    return next;
  };

  const ensureCounts = (txid) => {
    if (!txid) {
      return null;
    }
    const existing = counts.get(txid);
    if (existing) {
      return existing;
    }
    const next = {
      likes: 0,
      reboosts: 0,
      replies: 0,
    };
    counts.set(txid, next);
    return next;
  };

  const ensureFollowState = (followerAddress) => {
    const followerKey = boostAddress(followerAddress).toLowerCase();
    if (!followerKey) {
      return null;
    }
    const existing = followStates.get(followerKey);
    if (existing) {
      return existing;
    }
    const next = new Map();
    followStates.set(followerKey, next);
    return next;
  };

  for (const item of ordered) {
    const kind = String(item?.kind ?? "").trim().toLowerCase();
    if (!BOOST_INDEX_EVENT_KINDS.has(kind) || item?.valid === false) {
      continue;
    }

    if (kind === "boost-follow" || kind === "boost-unfollow") {
      const followerAddress = boostAddress(item?.authorAddress ?? item?.actor);
      const targetAddress = boostFollowTargetAddress(item);
      const followerState = ensureFollowState(followerAddress);
      const targetKey = targetAddress.toLowerCase();
      if (followerState && targetKey) {
        followerState.set(targetKey, {
          following: kind === "boost-follow",
          targetAddress,
          targetId: boostFollowTargetId(item) || undefined,
          txid: boostHexTxid(item?.txid),
          updatedAt: dateIso(
            item?.createdAt ?? item?.confirmedAt ?? item?.indexedAt,
            new Date(),
          ),
        });
      }
      continue;
    }

    if (kind === "boost-profile") {
      const address = boostAddress(
        item?.authorAddress ?? item?.actor ?? item?.currentOwnerAddress,
      );
      const profile =
        item?.profile && typeof item.profile === "object" && !Array.isArray(item.profile)
          ? item.profile
          : {};
      const profileId = normalizePowId(
        String(
          item?.profileId ??
            item?.authorId ??
            profile?.profileId ??
            profile?.id ??
            profile?.handle ??
            "",
        ),
      );
      if (address && profileId) {
        profiles.set(address.toLowerCase(), {
          address,
          id: profileId,
          image:
            profile?.image &&
            typeof profile.image === "object" &&
            !Array.isArray(profile.image)
              ? profile.image
              : undefined,
          name: boostDisplayName(
            item?.displayName,
            profile?.name,
            `${profileId}@proofofwork.me`,
          ),
          profileId,
        });
      }
      continue;
    }

    if (kind === "boost-like") {
      const counter = ensureCounts(boostTargetTxid(item));
      if (counter) {
        counter.likes += 1;
      }
      continue;
    }

    if (kind === "boost-reply") {
      const counter = ensureCounts(boostTargetTxid(item));
      if (counter) {
        counter.replies += 1;
      }
    }

    if (kind === "boost-reboost") {
      const counter = ensureCounts(boostTargetTxid(item));
      if (counter) {
        counter.reboosts += 1;
      }
    }

    const boostTxid = boostPostTxid(item);
    const state = ensureState(boostTxid);
    if (!state) {
      continue;
    }

    if (BOOST_VISIBLE_EVENT_KINDS.has(kind)) {
      state.ownerAddress ||= boostAddress(
        item?.currentOwnerAddress ?? item?.authorAddress ?? item?.actor,
      );
      continue;
    }

    if (kind === "boost-list" || kind === "boost-seal") {
      const priceSats = boostPriceSats(item);
      state.listing = priceSats > 0
        ? {
            listingTxid: boostHexTxid(item?.listingTxid ?? item?.txid),
            priceSats,
            sellerAddress: boostAddress(
              item?.sellerAddress ?? item?.currentOwnerAddress ?? item?.actor,
            ),
          }
        : state.listing;
      continue;
    }

    if (kind === "boost-delist") {
      state.listing = null;
      continue;
    }

    if (kind === "boost-transfer" || kind === "boost-buy") {
      state.listing = null;
      state.ownerAddress = boostAddress(
        item?.newOwnerAddress ??
          item?.buyerAddress ??
          item?.recipientAddress ??
          item?.to ??
          item?.currentOwnerAddress,
      ) || state.ownerAddress;
    }
  }

  const followingByFollower = new Map();
  const followersByTarget = new Map();
  for (const [followerKey, targets] of followStates) {
    const activeTargets = new Set();
    for (const [targetKey, state] of targets) {
      if (!state?.following) {
        continue;
      }
      activeTargets.add(targetKey);
      const targetFollowers = followersByTarget.get(targetKey) ?? new Set();
      targetFollowers.add(followerKey);
      followersByTarget.set(targetKey, targetFollowers);
    }
    followingByFollower.set(followerKey, activeTargets);
  }

  return {
    counts,
    followersByTarget,
    followingByFollower,
    profiles,
    states,
  };
}

function boostFeedItemFromEvent(
  item,
  state,
  profileState,
  counts,
  network,
  btcUsd,
  workFloor,
) {
  const kind = String(item?.kind ?? "").trim().toLowerCase();
  const txid = boostHexTxid(item?.txid);
  if (!txid || !BOOST_VISIBLE_EVENT_KINDS.has(kind)) {
    return null;
  }

  const boostTxid = boostPostTxid(item) || txid;
  const targetTxid = boostTargetTxid(item);
  const createdAt = dateIso(
    item?.createdAt ?? item?.confirmedAt ?? item?.indexedAt,
    new Date(),
  );
  const proofSignalSats = boostSignalSats(item);
  const counter = counts.get(boostTxid) ?? {};
  const ownerAddress = boostAddress(
    state?.ownerAddress ?? item?.currentOwnerAddress ?? item?.authorAddress,
  );
  const authorAddress = boostAddress(item?.authorAddress ?? item?.actor);
  const text = String(item?.text ?? item?.memo ?? item?.detail ?? "").trim();
  const media = Array.isArray(item?.media)
    ? item.media[0]
    : typeof item?.media === "object" && item.media
      ? item.media
      : null;
  const profileId = String(
    item?.profileId ??
      item?.authorId ??
      profileState?.id ??
      profileState?.profileId ??
      "",
  ).trim();
  const profileName = boostDisplayName(
    profileState?.name,
    profileId ? `${profileId}@proofofwork.me` : "",
  );
  const actionType = kind.replace(/^boost-/u, "");
  const workSignal = boostWorkSignalDisplay(item);
  const workSignalSubatoms = boostWorkSignalSubatoms(item);
  const workSignalValue = boostWorkSignalValue(workSignalSubatoms, workFloor);
  const proofSignalQ8 = BigInt(Math.floor(proofSignalSats)) * VALUE_Q8_SCALE;
  const totalSignalQ8 =
    proofSignalQ8 + BigInt(workSignalValue.workSignalValueQ8);
  const totalSignalSats = q8ToNumber(totalSignalQ8);
  const totalSignalUsd =
    btcUsd > 0
      ? Number(satsToUsdAtBtcUsd(totalSignalSats, btcUsd).toFixed(6))
      : 0;

  return {
    actionType,
    actionCount:
      Number(counter.likes ?? 0) +
      Number(counter.reboosts ?? 0) +
      Number(counter.replies ?? 0),
    authorId: profileId,
    authorAddress,
    authorDisplay: boostDisplayName(profileName, profileId, authorAddress, item?.actor),
    boostTxid,
    confirmed: item?.confirmed !== false,
    createdAt,
    currentOwnerAddress: ownerAddress,
    kind,
    likeCount: Number(counter.likes ?? 0),
    listing: state?.listing ?? null,
    listingPriceSats: state?.listing?.priceSats ?? 0,
    media: media
      ? {
          mime: String(media.mime ?? media.type ?? "").trim(),
          name: String(media.name ?? media.filename ?? "").trim(),
          sha256: String(media.sha256 ?? media.hash ?? "").trim(),
          size: numericValue(media.size),
        }
      : null,
    network,
    ownerDisplay: boostDisplayName(ownerAddress),
    profile:
      profileState || profileId
        ? {
            address: authorAddress,
            ...(profileState?.image ? { image: profileState.image } : {}),
            ...(profileId ? { id: profileId, profileId } : {}),
            ...(profileName ? { name: profileName } : {}),
          }
        : undefined,
    profileId,
    proofSignalSats,
    proofSignalUsd:
      btcUsd > 0
        ? Number(satsToUsdAtBtcUsd(proofSignalSats, btcUsd).toFixed(6))
        : 0,
    reboostCount: Number(counter.reboosts ?? 0),
    replyCount: Number(counter.replies ?? 0),
    signalSats: totalSignalSats,
    signalUsd: totalSignalUsd,
    targetTxid,
    text,
    totalSignalQ8: totalSignalQ8.toString(),
    totalSignalSats,
    totalSignalSatsExact: q8ToCanonicalDecimal(totalSignalQ8),
    totalSignalUsd,
    txid,
    valueRank: totalSignalSats,
    workSignal,
    workSignalSubatoms,
    workSignalUsd:
      btcUsd > 0
        ? Number(
            satsToUsdAtBtcUsd(
              workSignalValue.workSignalValueSats,
              btcUsd,
            ).toFixed(6),
          )
        : 0,
    ...workSignalValue,
  };
}

function compareBoostFeedItems(sortMode) {
  return (left, right) => {
    if (sortMode === "oldest") {
      return boostEventTimeMs(left) - boostEventTimeMs(right);
    }
    if (sortMode === "newest") {
      return boostEventTimeMs(right) - boostEventTimeMs(left);
    }
    return (
      numericValue(right?.valueRank) - numericValue(left?.valueRank) ||
      boostEventTimeMs(right) - boostEventTimeMs(left)
    );
  };
}

function boostFeedItemWithGraph(
  feedItem,
  sourceItem,
  followersByTarget,
  followingByFollower,
  viewerFollowing,
) {
  if (!feedItem) {
    return null;
  }
  const authorKey = boostAddress(sourceItem?.authorAddress ?? sourceItem?.actor)
    .toLowerCase();
  return {
    ...feedItem,
    followerCount: followersByTarget.get(authorKey)?.size ?? 0,
    followingCount: followingByFollower.get(authorKey)?.size ?? 0,
    viewerFollowsAuthor: viewerFollowing.has(authorKey),
  };
}

function boostProfileSourceAuthorKey(item) {
  return boostAddress(item?.authorAddress ?? item?.actor).toLowerCase();
}

function boostProfileSourceOwnerKey(item, state, feedItem) {
  return boostAddress(
    state?.ownerAddress ??
      feedItem?.currentOwnerAddress ??
      item?.currentOwnerAddress ??
      item?.ownerAddress ??
      item?.newOwnerAddress ??
      item?.buyerAddress ??
      item?.recipientAddress,
  ).toLowerCase();
}

function boostProfileSourceIds(item, profileState) {
  return [
    item?.profileId,
    item?.authorId,
    item?.currentOwnerId,
    profileState?.id,
    profileState?.profileId,
  ]
    .map((value) => normalizePowId(String(value ?? "")))
    .filter(Boolean);
}

function boostLooksLikeAddress(value) {
  return /^(?:bc1|[13])[a-z0-9]{20,}$/iu.test(String(value ?? "").trim());
}

function boostProfileSubjectForQuery(
  profile,
  sourceItems,
  profiles,
  followersByTarget,
  followingByFollower,
  viewerFollowing,
) {
  const query = String(profile ?? "").trim();
  if (!query) {
    return null;
  }
  const queryKey = query.toLowerCase();
  const queryId = boostLooksLikeAddress(query) ? "" : normalizePowId(query);
  let address = "";
  let profileState = null;

  for (const [profileKey, candidate] of profiles) {
    const candidateIds = [
      candidate?.id,
      candidate?.profileId,
      candidate?.name,
    ].map((value) => normalizePowId(String(value ?? "")));
    if (
      profileKey === queryKey ||
      (queryId && candidateIds.includes(queryId))
    ) {
      address = boostAddress(candidate?.address) || profileKey;
      profileState = candidate;
      break;
    }
  }

  const adoptAddress = (value) => {
    if (!address && boostAddress(value).toLowerCase() === queryKey) {
      address = boostAddress(value);
    }
  };

  for (const item of sourceItems) {
    if (address) {
      break;
    }
    adoptAddress(item?.authorAddress);
    adoptAddress(item?.actor);
    adoptAddress(item?.currentOwnerAddress);
    adoptAddress(item?.ownerAddress);
    adoptAddress(item?.newOwnerAddress);
    adoptAddress(item?.buyerAddress);
    adoptAddress(item?.recipientAddress);
    adoptAddress(item?.followerAddress);
    adoptAddress(item?.targetAddress);
    adoptAddress(item?.sellerAddress);
  }

  if (!address && queryId) {
    for (const item of sourceItems) {
      const authorKey = boostProfileSourceAuthorKey(item);
      const itemProfileState = profiles.get(authorKey);
      const ids = [
        ...boostProfileSourceIds(item, itemProfileState),
        item?.targetId,
        item?.followedId,
      ].map((value) => normalizePowId(String(value ?? "")));
      if (ids.includes(queryId)) {
        address =
          boostAddress(item?.authorAddress ?? item?.actor) ||
          boostAddress(item?.targetAddress) ||
          boostAddress(item?.currentOwnerAddress);
        profileState = itemProfileState ?? null;
        break;
      }
    }
  }

  if (!address && queryKey) {
    address = query;
  }

  const addressKey = address.toLowerCase();
  profileState = profileState ?? profiles.get(addressKey) ?? null;
  const id = boostDisplayName(profileState?.id, profileState?.profileId, queryId);
  return {
    address,
    addressKey,
    displayName: boostDisplayName(
      profileState?.name,
      id ? `${id}@proofofwork.me` : "",
      address,
      query,
    ),
    followerCount: addressKey ? (followersByTarget.get(addressKey)?.size ?? 0) : 0,
    followingCount: addressKey ? (followingByFollower.get(addressKey)?.size ?? 0) : 0,
    id,
    profile: profileState || undefined,
    query,
    viewerFollowsProfile: addressKey ? viewerFollowing.has(addressKey) : false,
  };
}

function boostProfileSubjectMatchesAuthor(item, profileState, subject) {
  if (!subject) {
    return false;
  }
  const authorKey = boostProfileSourceAuthorKey(item);
  if (subject.addressKey && authorKey === subject.addressKey) {
    return true;
  }
  if (!subject.id) {
    return false;
  }
  return boostProfileSourceIds(item, profileState).includes(subject.id);
}

function boostUniqueProfileEntries(entries) {
  const seen = new Set();
  const unique = [];
  for (const entry of entries) {
    const key = `${entry.feedItem?.kind ?? ""}:${entry.feedItem?.txid ?? ""}`;
    if (!key || seen.has(key)) {
      continue;
    }
    seen.add(key);
    unique.push(entry);
  }
  return unique;
}

function boostProfileEntriesByTab(entries, sourceItems, subject, states, profiles) {
  if (!subject) {
    return {
      boosts: entries,
      likes: [],
      purchased: [],
      replies: [],
      "replies-to": [],
    };
  }

  const authoredBoosts = [];
  const authoredReplies = [];
  const purchased = [];
  const subjectBoostTxids = new Set();

  for (const entry of entries) {
    const { feedItem, sourceItem } = entry;
    const kind = String(sourceItem?.kind ?? "").trim().toLowerCase();
    const authorKey = boostProfileSourceAuthorKey(sourceItem);
    const profileState = profiles.get(authorKey);
    const authored = boostProfileSubjectMatchesAuthor(
      sourceItem,
      profileState,
      subject,
    );
    const state = states.get(boostPostTxid(sourceItem));
    const ownerKey = boostProfileSourceOwnerKey(sourceItem, state, feedItem);

    if (authored && (kind === "boost-post" || kind === "boost-reboost")) {
      authoredBoosts.push(entry);
      if (kind === "boost-post") {
        const txid = boostPostTxid(sourceItem) || boostHexTxid(feedItem?.txid);
        if (txid) {
          subjectBoostTxids.add(txid);
        }
      }
    }
    if (authored && kind === "boost-reply") {
      authoredReplies.push(entry);
    }
    if (subject.addressKey && ownerKey === subject.addressKey && !authored) {
      purchased.push(entry);
    }
  }

  const likedTargetTxids = new Set();
  for (const item of sourceItems) {
    const kind = String(item?.kind ?? "").trim().toLowerCase();
    if (kind !== "boost-like" || item?.valid === false) {
      continue;
    }
    const authorKey = boostProfileSourceAuthorKey(item);
    const profileState = profiles.get(authorKey);
    if (boostProfileSubjectMatchesAuthor(item, profileState, subject)) {
      const targetTxid = boostTargetTxid(item);
      if (targetTxid) {
        likedTargetTxids.add(targetTxid);
      }
    }
  }

  const likes = entries.filter((entry) => {
    const kind = String(entry.sourceItem?.kind ?? "").trim().toLowerCase();
    if (kind === "boost-reboost") {
      return false;
    }
    return likedTargetTxids.has(
      boostHexTxid(entry.feedItem?.txid) || boostPostTxid(entry.sourceItem),
    );
  });
  const repliesTo = entries.filter((entry) => {
    const kind = String(entry.sourceItem?.kind ?? "").trim().toLowerCase();
    return kind === "boost-reply" && subjectBoostTxids.has(boostTargetTxid(entry.sourceItem));
  });

  return {
    boosts: boostUniqueProfileEntries(authoredBoosts),
    likes: boostUniqueProfileEntries(likes),
    purchased: boostUniqueProfileEntries(purchased),
    replies: boostUniqueProfileEntries(authoredReplies),
    "replies-to": boostUniqueProfileEntries(repliesTo),
  };
}

function boostProfileSignalStats(entries) {
  let totalSignalSats = 0;
  let totalSignalUsd = 0;
  let proofSignalSats = 0;
  let workSignalSubatoms = 0n;
  for (const entry of boostUniqueProfileEntries(entries)) {
    const item = entry.feedItem;
    totalSignalSats += numericValue(item?.totalSignalSats ?? item?.signalSats);
    totalSignalUsd += numericValue(item?.totalSignalUsd ?? item?.signalUsd);
    proofSignalSats += numericValue(item?.proofSignalSats);
    const subatoms = canonicalNonNegativeIntegerText(item?.workSignalSubatoms, {
      allowZero: false,
    });
    if (subatoms) {
      workSignalSubatoms += BigInt(subatoms);
    }
  }
  return {
    proofSignalSats,
    totalSignalSats,
    totalSignalUsd,
    workSignalSubatoms: workSignalSubatoms.toString(),
  };
}

async function boostFeedPayload(network, searchParams, fresh = false) {
  const sort = boostSortMode(searchParams);
  const view = boostTimelineView(searchParams);
  const profileTab = boostProfileTab(searchParams);
  const valueWindow = boostValueWindow(searchParams);
  const limit = boundedInteger(searchParams.get("limit"), 50, 1, 100);
  const includePending = /^(?:1|true|yes)$/iu.test(
    String(searchParams.get("pending") ?? ""),
  );
  const profile = String(searchParams.get("profile") ?? "").trim();
  const viewerAddress = boostAddress(
    searchParams.get("viewer") ??
      searchParams.get("viewerAddress") ??
      searchParams.get("address") ??
      "",
  );
  const viewerKey = viewerAddress.toLowerCase();
  const query = String(
    searchParams.get("q") ?? searchParams.get("search") ?? "",
  )
    .trim()
    .toLowerCase();

  let indexedPayload = null;
  if (proofIndexReadFeatureEnabled("event-history,events")) {
    const eventParams = new URLSearchParams({
      limit: "200",
      protocol: "pwb1",
      status: includePending ? "all" : "confirmed",
    });
    indexedPayload = await proofIndexEventHistoryPayload(
      network,
      eventParams,
    ).catch((error) => {
      console.error(`Boost event history read failed: ${errorSummary(error)}`);
      return null;
    });
  }

  const [quote, workFloor] = network === "livenet"
    ? await Promise.all([
        btcUsdPricePayload(network, { fresh }).catch((error) => {
          console.error(`Boost BTC/USD overlay failed: ${errorSummary(error)}`);
          return null;
        }),
        cachedWorkFloorPayload(network, fresh).catch((error) => {
          console.error(
            `Boost WORK floor overlay failed: ${errorSummary(error)}`,
          );
          return null;
        }),
      ])
    : [null, null];
  const btcUsd = btcUsdFromQuote(quote) || numericValue(workFloor?.btcUsd);
  const sourceItems = Array.isArray(indexedPayload?.items)
    ? indexedPayload.items
    : [];
  const {
    counts,
    followersByTarget,
    followingByFollower,
    profiles,
    states,
  } = boostOwnershipState(sourceItems);
  const viewerFollowing =
    viewerKey && followingByFollower.get(viewerKey)
      ? followingByFollower.get(viewerKey)
      : new Set();
  const windowStartMs = boostWindowStartMs(valueWindow);
  const profileSubject = boostProfileSubjectForQuery(
    profile,
    sourceItems,
    profiles,
    followersByTarget,
    followingByFollower,
    viewerFollowing,
  );
  const entries = sourceItems
    .filter((item) => {
      const kind = String(item?.kind ?? "").trim().toLowerCase();
      if (!BOOST_VISIBLE_EVENT_KINDS.has(kind)) {
        return false;
      }
      if (!includePending && item?.confirmed === false) {
        return false;
      }
      if (windowStartMs > 0 && boostEventTimeMs(item) < windowStartMs) {
        return false;
      }
      const state = states.get(boostPostTxid(item));
      const profileState = profiles.get(
        boostAddress(item?.authorAddress ?? item?.actor).toLowerCase(),
      );
      const authorKey = boostAddress(item?.authorAddress ?? item?.actor)
        .toLowerCase();
      if (
        !profileSubject &&
        view === "following" &&
        (!viewerKey || !authorKey || !viewerFollowing.has(authorKey))
      ) {
        return false;
      }
      return !query || boostEventSearchText(item, state, profileState).includes(query);
    })
    .map((item) => {
      const feedItem = boostFeedItemWithGraph(
        boostFeedItemFromEvent(
          item,
          states.get(boostPostTxid(item)),
          profiles.get(
            boostAddress(item?.authorAddress ?? item?.actor).toLowerCase(),
          ),
          counts,
          network,
          btcUsd,
          workFloor,
        ),
        item,
        followersByTarget,
        followingByFollower,
        viewerFollowing,
      );
      return feedItem ? { feedItem, sourceItem: item } : null;
    })
    .filter(Boolean);

  const profileTabs = profileSubject
    ? boostProfileEntriesByTab(entries, sourceItems, profileSubject, states, profiles)
    : null;
  const filteredEntries = (
    profileTabs ? profileTabs[profileTab] : entries
  ).sort((left, right) => compareBoostFeedItems(sort)(left.feedItem, right.feedItem));

  const items = filteredEntries.slice(0, limit).map((entry) => entry.feedItem);
  const profileStatEntries = profileTabs
    ? boostUniqueProfileEntries([
        ...profileTabs.boosts,
        ...profileTabs.replies,
        ...profileTabs.purchased,
      ])
    : [];
  const profileSignalStats = profileTabs
    ? boostProfileSignalStats(profileStatEntries)
    : null;
  return {
    btcUsd,
    btcUsdIndexedAt: quote?.priceIndexedAt,
    indexedAt: indexedPayload?.indexedAt ?? new Date().toISOString(),
    indexedThroughBlock: indexedPayload?.indexedThroughBlock,
    items,
    limit,
    mode: profileSubject ? "profile" : "timeline",
    network,
    profile: profile || undefined,
    profileSubject: profileSubject
      ? {
          address: profileSubject.address || undefined,
          displayName: profileSubject.displayName,
          followerCount: profileSubject.followerCount,
          followingCount: profileSubject.followingCount,
          id: profileSubject.id || undefined,
          profile: profileSubject.profile,
          proofSignalSats: profileSignalStats?.proofSignalSats ?? 0,
          purchasedCount: profileTabs.purchased.length,
          query: profileSubject.query,
          replyCount: profileTabs.replies.length,
          repliesToCount: profileTabs["replies-to"].length,
          boostCount: profileTabs.boosts.length,
          likeCount: profileTabs.likes.length,
          totalSignalSats: profileSignalStats?.totalSignalSats ?? 0,
          totalSignalUsd: profileSignalStats?.totalSignalUsd ?? 0,
          viewerFollowsProfile: profileSubject.viewerFollowsProfile,
          workSignalSubatoms: profileSignalStats?.workSignalSubatoms ?? "0",
        }
      : undefined,
    profileTab: profileSubject ? profileTab : undefined,
    profileTabs: profileTabs
      ? {
          boosts: profileTabs.boosts.length,
          likes: profileTabs.likes.length,
          purchased: profileTabs.purchased.length,
          replies: profileTabs.replies.length,
          "replies-to": profileTabs["replies-to"].length,
        }
      : undefined,
    graph: {
      followingCount: viewerFollowing.size,
      viewerAddress: viewerAddress || undefined,
    },
    sort,
    source: indexedPayload?.source ?? "proof-indexer-boost-events-unavailable",
    stats: {
      confirmed: items.filter((item) => item.confirmed !== false).length,
      pending: items.filter((item) => item.confirmed === false).length,
      total: filteredEntries.length,
    },
    totalCount: filteredEntries.length,
    valueWindow,
    view,
  };
}

async function registrySummaryPayload(network, fresh = false) {
  return compactRegistrySummaryPayload(
    await strictPublicRegistryPayload(network, { fresh }),
  );
}

async function activitySummaryPayload(network, fresh = false) {
  if (network === "livenet") {
    const storedSummary = await proofIndexSnapshotPayload(
      network,
      "logSummary",
    ).catch((error) => {
      console.error(
        `Proof index canonical Log summary read failed: ${errorSummary(error)}`,
      );
      return null;
    });
    if (
      storedSummary &&
      payloadSnapshotId(storedSummary) &&
      payloadIndexedThroughBlockHash(storedSummary)
    ) {
      return storedSummary;
    }
    throw freshDataUnavailableError(
      fresh
        ? "Fresh hash-bound Log summary is still catching up."
        : "Current hash-bound Log summary is unavailable.",
    );
  }
  const ledger = await summaryCanonicalLedgerPayload(network, fresh);
  if (!ledger?.activityPayload) {
    throw freshDataUnavailableError(
      fresh
        ? "Fresh Log summary ledger is unavailable."
        : "Current Log summary ledger is unavailable.",
    );
  }
  return attachLedgerMetadata(
    compactActivitySummaryPayload(
      ledger.activityPayload,
      ledger.metrics?.indexedThroughBlock,
    ),
    ledger,
  );
}

function payloadWithFallbackAfterMs(promise, fallbackPayload, timeoutMs) {
  let timer;
  return Promise.race([
    promise.catch((error) => {
      console.error(`Fresh payload refresh failed: ${errorSummary(error)}`);
      return fallbackPayload;
    }),
    new Promise((resolve) => {
      timer = setTimeout(() => resolve(fallbackPayload), timeoutMs);
    }),
  ]).finally(() => clearTimeout(timer));
}

async function freshTokenPayloadOrSnapshot(
  network,
  tokenScope = "",
  options = {},
) {
  const scope = normalizeTokenScope(tokenScope);
  const fallback = await fastTokenPayloadSnapshot(network, scope, options);
  if (!ENABLE_SUMMARY_TOKEN_REFRESH && options.forceRefresh !== true) {
    return fallback;
  }

  const waitMs = Number.isFinite(options.fullRefreshWaitMs)
    ? options.fullRefreshWaitMs
    : scope === WORK_TOKEN_ID
      ? Math.max(WORK_FLOOR_FRESH_WAIT_MS, liveWorkReadWaitMs(options))
      : Math.max(WORK_TOKEN_CANONICAL_FRESH_WAIT_MS, TOKEN_SCOPED_FRESH_WAIT_MS);
  const refreshed = await payloadWithFallbackAfterMs(
    refreshTokenPayload(network, scope),
    null,
    waitMs,
  );
  if (refreshed) {
    if (
      await proofIndexPayloadCoversConfirmedTip(
        refreshed,
        network,
        `token-fresh:${scope || "all"}`,
      )
    ) {
      return refreshed;
    }
  }

  refreshTokenPayloadCacheInBackground(network, scope);
  if (
    fallback &&
    (await proofIndexPayloadCoversConfirmedTip(
      fallback,
      network,
      `token-fresh-fallback:${scope || "all"}`,
    ))
  ) {
    return fallback;
  }

  throw freshDataUnavailableError(
    `Fresh token payload is unavailable for ${scope || "all"}.`,
  );
}

async function cachedWorkFloorSnapshotNoRefresh(network) {
  const cacheKey = `work-floor:${network}`;
  const payloadKey = `payload:${cacheKey}`;
  const cachedPayload = RESPONSE_CACHE.get(payloadKey)?.payload;
  if (
    cachedPayload &&
    summaryPayloadHasFiniteNetworkValue(network, "workFloor", cachedPayload)
  ) {
    return cachedPayload;
  }
  if (cachedPayload) {
    RESPONSE_CACHE.delete(payloadKey);
  }

  const persistedPayload = await persistedPayloadForCache(
    cacheKey,
    WORK_FLOOR_CACHE_STALE_MS,
  );
  if (
    persistedPayload &&
    summaryPayloadHasFiniteNetworkValue(network, "workFloor", persistedPayload)
  ) {
    RESPONSE_CACHE.set(payloadKey, {
      expiresAt: Date.now() - 1,
      payload: persistedPayload,
      staleUntil: Date.now() + WORK_FLOOR_CACHE_STALE_MS,
    });
    return persistedPayload;
  }

  return null;
}

function workFloorWithBtcUsdQuote(workFloor, quote) {
  const btcUsdMetadata = btcUsdResponseMetadata(quote);
  if (!workFloor || btcUsdMetadata.btcUsd <= 0) {
    return workFloor;
  }

  const totalSats = numericValue(
    workFloor.actualValue?.totalSats ?? workFloor.networkValueSats,
  );
  const floorSats = numericValue(
    workFloor.actualValue?.floorSats ?? workFloor.floorSats,
  );
  const totalUsd = satsToUsdAtBtcUsd(totalSats, btcUsdMetadata.btcUsd);
  const floorUsd = satsToUsdAtBtcUsd(floorSats, btcUsdMetadata.btcUsd);
  return {
    ...workFloor,
    ...btcUsdMetadata,
    floorUsd,
    networkUsd: totalUsd,
    totalUsd,
    actualValue: {
      ...(workFloor.actualValue ?? {}),
      floorUsd,
      networkUsd: totalUsd,
      totalUsd,
    },
  };
}

async function workFloorWithCurrentBtcUsd(workFloor, network, fresh = false) {
  if (network !== "livenet") {
    return workFloor;
  }

  try {
    const quote = await btcUsdPricePayload(network, { fresh });
    return workFloorWithBtcUsdQuote(workFloor, quote);
  } catch (error) {
    console.error(`WORK BTC/USD overlay failed: ${errorSummary(error)}`);
    return workFloor;
  }
}

async function workFloorWithSummaryMarketOverlay(
  workFloor,
  network,
  fresh = false,
  tokenState = null,
  overlay = null,
) {
  if (network !== "livenet" || !workFloor) {
    return workFloorWithCurrentBtcUsd(workFloor, network, fresh);
  }
  if (workFloor.consistency) {
    return workFloorWithCurrentBtcUsd(workFloor, network, fresh);
  }

  const marketOverlay =
    overlay === null ? await indexedTokenMarketSummaryOverlay(network) : overlay;
  const overlaidWorkFloor = marketOverlay
    ? workFloorWithIndexedMarketSummaryOverlay(
        workFloor,
        marketOverlay,
        tokenState,
      )
    : workFloor;
  return workFloorWithCurrentBtcUsd(overlaidWorkFloor, network, fresh);
}

async function workSummaryWithCurrentBtcUsd(payload, network, fresh = false) {
  const scopedPayload = payload
    ? {
        ...payload,
        token: tokenPayloadWithScopedHolderIdentity(
          payload.token,
          WORK_TOKEN_ID,
        ),
      }
    : payload;
  if (!scopedPayload?.floor) {
    return scopedPayload;
  }

  return {
    ...scopedPayload,
    floor: await workFloorWithCurrentBtcUsd(
      scopedPayload.floor,
      network,
      fresh,
    ),
  };
}

function growthSummaryWithCanonicalWorkFloor(growthSummary, workFloor) {
  if (!growthSummary || !workFloor) {
    return growthSummary;
  }
  const state = exactWorkFloorNetworkQ8State(workFloor);
  if (!state || state.live <= 0n) {
    return growthSummary;
  }
  const actualValue = actualValueWithExactWorkNetworkQ8(
    {
      ...(growthSummary.actualValue ?? {}),
      ...(workFloor.actualValue ?? {}),
    },
    state,
  );
  const canonicalTop = actualValueWithExactWorkNetworkQ8(
    {
      ...growthSummary,
      ...(workFloor.actualValue ?? {}),
      modelTotalUsd:
        workFloor.modelTotalUsd ??
        workFloor.actualValue?.modelTotalUsd ??
        growthSummary.modelTotalUsd,
      powids:
        workFloor.powids ??
        workFloor.actualValue?.powids ??
        growthSummary.powids,
      tokenFlowSats:
        workFloor.tokenFlowSats ??
        workFloor.actualValue?.tokenFlowSats ??
        growthSummary.tokenFlowSats,
      totalUsd:
        workFloor.totalUsd ??
        workFloor.actualValue?.totalUsd ??
        growthSummary.totalUsd,
      workAmoV5AccumulatorModel:
        workFloor.workAmoV5AccumulatorModel,
      workAmoV5Transition: workFloor.workAmoV5Transition,
    },
    state,
  );
  return {
    ...canonicalTop,
    actualValue,
    chartPoints: Array.isArray(workFloor.chartPoints)
      ? workFloor.chartPoints.map((point) => ({ ...point }))
      : [],
    stats: {
      ...(growthSummary.stats ?? {}),
      ...(workFloor.stats ?? {}),
    },
    workFloor,
  };
}

async function marketplaceSummaryWithCurrentBtcUsd(
  payload,
  network,
  fresh = false,
) {
  if (!payload?.workFloor) {
    return payload;
  }

  return {
    ...payload,
    workFloor: await workFloorWithCurrentBtcUsd(
      payload.workFloor,
      network,
      fresh,
    ),
  };
}

function growthSummaryWithBtcUsdQuote(growthSummary, quote) {
  const btcUsdMetadata = btcUsdResponseMetadata(quote);
  if (!growthSummary || btcUsdMetadata.btcUsd <= 0) {
    return growthSummary;
  }

  const totalSats = numericValue(growthSummary.actualValue?.totalSats);
  const totalUsd = satsToUsdAtBtcUsd(totalSats, btcUsdMetadata.btcUsd);
  return {
    ...growthSummary,
    ...btcUsdMetadata,
    networkUsd: totalUsd,
    totalUsd,
    actualValue: {
      ...(growthSummary.actualValue ?? {}),
      networkUsd: totalUsd,
      totalUsd,
    },
    workFloor: workFloorWithBtcUsdQuote(growthSummary.workFloor, quote),
  };
}

async function growthSummaryWithCurrentBtcUsd(
  growthSummary,
  network,
  fresh = false,
) {
  if (network !== "livenet") {
    return growthSummary;
  }

  try {
    const quote = await btcUsdPricePayload(network, { fresh });
    return growthSummaryWithBtcUsdQuote(growthSummary, quote);
  } catch (error) {
    console.error(`Growth BTC/USD overlay failed: ${errorSummary(error)}`);
    return growthSummary;
  }
}

async function proofIndexWorkFloorPayload(network) {
  void network;
  console.error(
    "Rejected proof-index value summary as WORK floor: canonical ledger required.",
  );
  return null;
}

async function cachedWorkFloorPayload(network, fresh = false) {
  if (network === "livenet") {
    const indexedFloor = await currentProofIndexWorkFloorFallbackPayload(
      network,
      fresh,
    );
    if (indexedFloor) {
      return indexedFloor;
    }

    if (!fresh) {
      const ledger = await existingCurrentCanonicalLedgerPayloadWithinMs(
        network,
        "work-floor canonical ledger",
      );
      if (ledger?.workFloor) {
        return workFloorWithCurrentBtcUsd(ledger.workFloor, network, false);
      }

      throw freshDataUnavailableError(
        "Current WORK floor ledger is unavailable.",
      );
    }

    const ledger = await payloadWithFallbackAfterMs(
      summaryCanonicalLedgerPayload(network, fresh),
      null,
      WORK_FLOOR_FRESH_WAIT_MS,
    );
    if (ledger?.workFloor) {
      return workFloorWithCurrentBtcUsd(ledger.workFloor, network, fresh);
    }

    throw freshDataUnavailableError(
      "Fresh WORK floor ledger is unavailable.",
    );
  }

  return workFloorWithCurrentBtcUsd(
    await workFloorPayload(network, false),
    network,
    fresh,
  );
}

async function fastLivenetWorkSummaryPayload(network) {
  const ledger = await existingCurrentCanonicalLedgerPayloadWithinMs(
    network,
    "work-summary canonical ledger",
  );
  if (!ledger) {
    const indexedPayload = await currentProofIndexSummarySnapshotFallbackPayload(
      network,
      "workSummary",
      "work-summary",
    );
    const indexedToken = canonicalWorkMarketV2TokenSummary(
      indexedPayload?.token,
      network,
    );
    if (indexedPayload && indexedToken) {
      const currentIndexedToken =
        tokenPayloadWithCurrentWorkActiveListingPolicy(
          indexedToken,
          network,
        );
      return workSummaryWithCurrentBtcUsd(
        {
          ...indexedPayload,
          token: currentIndexedToken,
          floor: await workFloorWithSummaryMarketOverlay(
            indexedPayload.floor,
            network,
            false,
            currentIndexedToken,
          ),
        },
        network,
        false,
      );
    }

    throw freshDataUnavailableError("Current WORK summary ledger is unavailable.");
  }

  const marketOverlay = await indexedTokenMarketSummaryOverlay(
    network,
    WORK_TOKEN_ID,
  );
  const ledgerWorkTokenState = tokenStateWithoutDroppedPendingTransactions(
    ledgerTokenStateForScope(ledger, WORK_TOKEN_ID),
    network,
  );
  const workTokenSummary = await tokenSummaryPayload(
    network,
    WORK_TOKEN_ID,
    false,
  ).catch((error) => {
    console.error(
      `WORK summary token read failed: ${errorSummary(error)}`,
    );
    return compactTokenSummaryPayload(
      tokenPayloadWithCurrentWorkActiveListingPolicy(
        ledgerWorkTokenState,
        network,
      ),
      WORK_TOKEN_ID,
    );
  });
  const valueWorkTokenState = marketOverlay
    ? tokenStateWithIndexedMarketSummaryOverlay(workTokenSummary, marketOverlay)
    : workTokenSummary;
  const currentValueWorkTokenState =
    tokenPayloadWithCurrentWorkActiveListingPolicy(
      valueWorkTokenState,
      network,
    );
  const overlayTokenState = tokenStateWithScopedTokenOverride(
    tokenStateWithoutDroppedPendingTransactions(ledger.tokenState, network),
    currentValueWorkTokenState,
    WORK_TOKEN_ID,
  );
  const floor = await workFloorWithSummaryMarketOverlay(
    ledger.workFloor,
    network,
    false,
    overlayTokenState,
    marketOverlay,
  );
  return workSummaryWithCurrentBtcUsd(
    attachLedgerMetadata(
      {
        floor: attachLedgerMetadata(floor, ledger),
        indexedAt: newerIso(
          ledger.generatedAt,
          currentValueWorkTokenState?.indexedAt,
        ),
        network,
        summaryOnly: true,
        token: attachLedgerMetadata(currentValueWorkTokenState, ledger),
      },
      ledger,
    ),
    network,
    false,
  );
}

async function workSummaryPayload(network, fresh = false) {
  if (network === "livenet") {
    const exactIndexedPayload =
      await currentProofIndexSummarySnapshotFallbackPayload(
        network,
        "workSummary",
        "work-summary",
      );
    const exactIndexedToken = canonicalWorkMarketV2TokenSummary(
      exactIndexedPayload?.token,
      network,
    );
    if (exactIndexedPayload && exactIndexedToken) {
      const currentExactIndexedToken =
        tokenPayloadWithCurrentWorkActiveListingPolicy(
          exactIndexedToken,
          network,
        );
      return workSummaryWithCurrentBtcUsd(
        {
          ...exactIndexedPayload,
          token: currentExactIndexedToken,
          floor: await workFloorWithSummaryMarketOverlay(
            exactIndexedPayload.floor,
            network,
            fresh,
            currentExactIndexedToken,
          ),
        },
        network,
        fresh,
      );
    }
    if (!fresh) {
      return fastLivenetWorkSummaryPayload(network);
    }

    const ledger = await summaryCanonicalLedgerPayload(network, fresh);
    if (ledger) {
      if (fresh) {
        const baseWorkTokenState = ledgerTokenStateForScope(
          ledger,
          WORK_TOKEN_ID,
        );
        const refreshedWorkTokenState = await payloadWithFallbackAfterMs(
          workTokenStateForSummaryRead(network, true),
          baseWorkTokenState,
          SUMMARY_TOKEN_CURRENT_FALLBACK_WAIT_MS,
        );
        const tokenReadReturnedCanonical =
          refreshedWorkTokenState && refreshedWorkTokenState !== baseWorkTokenState;
        let spendableWorkTokenState = await workTokenStateWithSummaryListingTruth(
          refreshedWorkTokenState,
          network,
          { recoverActiveListings: !tokenReadReturnedCanonical },
        );
        spendableWorkTokenState = await workTokenStateWithIndexedMintStats(
          spendableWorkTokenState,
          network,
        );
        const overlayTokenState = tokenStateWithScopedTokenOverride(
          ledger.tokenState,
          spendableWorkTokenState,
          WORK_TOKEN_ID,
        );
        const floor = await workFloorWithSummaryMarketOverlay(
          ledger.workFloor,
          network,
          true,
          overlayTokenState,
        );
        return workSummaryWithCurrentBtcUsd(
          attachLedgerMetadata(
            {
              floor: attachLedgerMetadata(floor, ledger),
              indexedAt: ledger.generatedAt,
              network,
              summaryOnly: true,
              token: attachLedgerMetadata(
                compactTokenSummaryPayload(
                  spendableWorkTokenState,
                  WORK_TOKEN_ID,
                ),
                ledger,
              ),
            },
            ledger,
          ),
          network,
          true,
        );
      }
      const summaryReadWaitMs = fresh
        ? LEDGER_SUMMARY_CURRENT_FALLBACK_WAIT_MS
        : WORK_TOKEN_LIVE_WAIT_MS;
      const summaryWorkTokenState = fresh
        ? await payloadWithFallbackAfterMs(
            workTokenStateForSummaryRead(network, true),
            null,
            summaryReadWaitMs,
          )
        : null;
      const workTokenState =
        summaryWorkTokenState ??
        (await liveWorkTokenStateWithFallbackAfterMs(
          network,
          ledgerTokenStateForScope(ledger, WORK_TOKEN_ID),
          summaryReadWaitMs,
          { recoverClosedSales: true },
        ));
      let mergedWorkTokenState =
        summaryWorkTokenState && summaryWorkTokenState !== workTokenState
        ? tokenStateWithMergedListingSeals(
            tokenStateWithPreservedListingRecords(
              workTokenState,
              summaryWorkTokenState,
            ),
            summaryWorkTokenState,
          )
        : workTokenState;
      mergedWorkTokenState = await workTokenStateWithSummaryListingTruth(
        mergedWorkTokenState,
        network,
        { recoverActiveListings: true },
      );
      const closeTxs = await payloadWithFallbackAfterMs(
        recentWorkTokenMarketCloseTransactions(
          network,
          WORK_TOKEN_LIVE_CLOSE_MAX_TXS,
          WORK_TOKEN_LIVE_CLOSE_SCAN_MAX_TXS,
        ),
        [],
        fresh
          ? Math.min(
              WORK_TOKEN_SUMMARY_CLOSE_WAIT_MS,
              LEDGER_SUMMARY_CURRENT_FALLBACK_WAIT_MS,
            )
          : WORK_TOKEN_SUMMARY_CLOSE_WAIT_MS,
      );
      let closedWorkTokenState =
        workTokenStateWithRecoveredListingClosesFromTransactions(
          mergedWorkTokenState,
          closeTxs,
          network,
        );
      closedWorkTokenState = await payloadWithFallbackAfterMs(
        workTokenStateWithRecoveredListingCloseSales(
          closedWorkTokenState,
          network,
        ),
        closedWorkTokenState,
        fresh
          ? LEDGER_SUMMARY_CURRENT_FALLBACK_WAIT_MS
          : WORK_TOKEN_SUMMARY_CLOSE_WAIT_MS,
      );
      let spendableWorkTokenState =
        await tokenPayloadWithSpendableActiveListings(
          closedWorkTokenState,
          network,
        );
      spendableWorkTokenState = await workTokenStateWithIndexedMintStats(
        spendableWorkTokenState,
        network,
      );
      const marketOverlay = await indexedTokenMarketSummaryOverlay(network);
      const currentSpendableWorkTokenState =
        tokenPayloadWithCurrentWorkActiveListingPolicy(
          spendableWorkTokenState,
          network,
        );
      const overlayTokenState = tokenStateWithScopedTokenOverride(
        ledger.tokenState,
        currentSpendableWorkTokenState,
        WORK_TOKEN_ID,
      );
      const floor = await workFloorWithSummaryMarketOverlay(
        ledger.workFloor,
        network,
        fresh,
        overlayTokenState,
        marketOverlay,
      );
      return workSummaryWithCurrentBtcUsd(
        attachLedgerMetadata(
          {
            floor: attachLedgerMetadata(floor, ledger),
            indexedAt: ledger.generatedAt,
            network,
            summaryOnly: true,
            token: attachLedgerMetadata(
              compactTokenSummaryPayload(
                currentSpendableWorkTokenState,
                WORK_TOKEN_ID,
              ),
              ledger,
            ),
          },
          ledger,
        ),
        network,
        fresh,
      );
    }

    const indexedPayload = await currentProofIndexSummarySnapshotFallbackPayload(
      network,
      "workSummary",
      "work-summary",
    );
    const indexedToken = canonicalWorkMarketV2TokenSummary(
      indexedPayload?.token,
      network,
    );
    if (indexedPayload && indexedToken) {
      return workSummaryWithCurrentBtcUsd(
        {
          ...indexedPayload,
          token: indexedToken,
          floor: await workFloorWithSummaryMarketOverlay(
            indexedPayload.floor,
            network,
            fresh,
            indexedToken,
          ),
        },
        network,
        fresh,
      );
    }

    throw freshDataUnavailableError(
      fresh
        ? "Fresh WORK summary ledger is unavailable."
        : "Current WORK summary ledger is unavailable.",
    );
  }

  const [token, floor] = await Promise.all([
    tokenSummaryPayload(network, WORK_TOKEN_ID, fresh),
    fresh
      ? cachedWorkFloorPayload(network, true)
      : cachedWorkFloorPayload(network, false),
  ]);
  return {
    floor,
    indexedAt: new Date().toISOString(),
    network,
    summaryOnly: true,
    token,
  };
}

function marketplaceSummaryCacheKey(network) {
  return `marketplace-summary:${network}`;
}

function marketplaceSummaryPayloadKey(network) {
  return `payload:${marketplaceSummaryCacheKey(network)}`;
}

function cacheMarketplaceSummaryPayload(network, payload) {
  const cacheKey = marketplaceSummaryCacheKey(network);
  const payloadKey = marketplaceSummaryPayloadKey(network);
  const body = JSON.stringify(payload);
  RESPONSE_CACHE.set(payloadKey, {
    expiresAt: Date.now() + MARKETPLACE_SUMMARY_CACHE_TTL_MS,
    payload,
    staleUntil: Date.now() + MARKETPLACE_SUMMARY_CACHE_STALE_MS,
  });
  cacheJsonBody(
    `json:${cacheKey}`,
    body,
    MARKETPLACE_SUMMARY_CACHE_TTL_MS,
    MARKETPLACE_SUMMARY_CACHE_STALE_MS,
  );
  if (shouldPersistJsonCache(cacheKey)) {
    void writePersistedJsonCache(`json:${cacheKey}`, body);
  }
  return payload;
}

async function cachedMarketplaceSummaryPayloadNoRefresh(network) {
  const cacheKey = marketplaceSummaryCacheKey(network);
  const payloadKey = marketplaceSummaryPayloadKey(network);
  const ledger =
    network === "livenet"
      ? await existingCurrentCanonicalLedgerPayloadWithinMs(
          network,
          "marketplace-summary canonical ledger",
        )
      : await existingCanonicalLedgerPayload(network);
  if (network === "livenet" && !ledger) {
    return null;
  }
  const cachedPayload = RESPONSE_CACHE.get(payloadKey)?.payload;
  if (cachedPayload) {
    if (
      payloadSnapshotMatchesLedger(cachedPayload, ledger) &&
      summaryPayloadHasFiniteNetworkValue(
        network,
        "marketplaceSummary",
        cachedPayload,
      )
    ) {
      return cachedPayload;
    }
    logStaleSnapshotPayload("marketplace-summary cache", cachedPayload, ledger);
    RESPONSE_CACHE.delete(payloadKey);
  }

  const persistedPayload = await persistedPayloadForCache(
    cacheKey,
    MARKETPLACE_SUMMARY_CACHE_STALE_MS,
  );
  if (persistedPayload) {
    if (
      !payloadSnapshotMatchesLedger(persistedPayload, ledger) ||
      !summaryPayloadHasFiniteNetworkValue(
        network,
        "marketplaceSummary",
        persistedPayload,
      )
    ) {
      logStaleSnapshotPayload(
        "persisted marketplace-summary cache",
        persistedPayload,
        ledger,
      );
      return null;
    }
    RESPONSE_CACHE.set(payloadKey, {
      expiresAt: Date.now() - 1,
      payload: persistedPayload,
      staleUntil: Date.now() + MARKETPLACE_SUMMARY_CACHE_STALE_MS,
    });
    return persistedPayload;
  }

  return null;
}

function marketplaceSummaryPayloadFromLedger(
  ledger,
  tokenState = ledger?.tokenState,
) {
  if (!ledger) {
    return null;
  }

  return attachLedgerMetadata(
    {
      indexedAt: ledger.generatedAt,
      network: ledger.network,
      registry: attachLedgerMetadata(
        compactRegistrySummaryPayload(ledger.registryState),
        ledger,
      ),
      summaryOnly: true,
      token: attachLedgerMetadata(
        compactTokenSummaryPayload(
          tokenPayloadWithCurrentWorkActiveListingPolicy(
            tokenState,
            ledger.network,
          ),
          "",
          {
          compactMarketRecords: true,
          includeAllScopedListings: false,
          },
        ),
        ledger,
      ),
      workFloor: attachLedgerMetadata(ledger.workFloor, ledger),
    },
    ledger,
  );
}

function summaryWithDerivedSnapshot(payload, label, evidence) {
  const sourceSnapshotId = payloadSnapshotId(payload);
  if (!sourceSnapshotId) {
    return payload;
  }
  const snapshotId = sha256Hex(
    Buffer.from(
      JSON.stringify({
        evidence,
        label,
        sourceSnapshotId,
      }),
    ),
  ).slice(0, 24);
  const rebind = (nested) =>
    nested && payloadSnapshotId(nested)
      ? { ...nested, snapshotId }
      : nested;
  return {
    ...payload,
    derivedFromSnapshotId: sourceSnapshotId,
    floor: rebind(payload.floor),
    registry: rebind(payload.registry),
    snapshotId,
    token: rebind(payload.token),
    workFloor: rebind(payload.workFloor),
  };
}

async function marketplaceSummaryWithSpendableIdListings(payload, network) {
  const listings = Array.isArray(payload?.registry?.listings)
    ? payload.registry.listings
    : [];
  if (network !== "livenet") {
    return payload;
  }
  const ownersById = new Map(
    (Array.isArray(payload?.registry?.records) ? payload.registry.records : [])
      .filter((record) => record?.confirmed !== false)
      .map((record) => [
        normalizePowId(record?.id),
        String(record?.ownerAddress ?? "").trim(),
      ]),
  );
  const ownedListings = listings.filter((listing) => {
    const owner = ownersById.get(normalizePowId(listing?.id));
    return !owner || owner === String(listing?.sellerAddress ?? "").trim();
  });
  const reconciliation = await strictCoreRegistryListingReconciliation(
    {
      ...payload.registry,
      listings: ownedListings,
    },
    network,
  );
  const spendableListings = reconciliation.payload.listings;
  if (spendableListings.length === listings.length) {
    return {
      ...payload,
      registry: reconciliation.payload,
    };
  }
  const nextPayload = {
    ...payload,
    registry: reconciliation.payload,
  };
  return summaryWithDerivedSnapshot(
    nextPayload,
    "marketplace-id-listing-reconciliation",
    spendableListings.map((listing) => listing?.listingId).filter(Boolean),
  );
}

function emptyMarketplaceSummaryPayload(network) {
  return {
    indexedAt: new Date().toISOString(),
    network,
    registry: compactRegistrySummaryPayload(emptyRegistryPayload(network)),
    summaryOnly: true,
    token: compactTokenSummaryPayload(emptyTokenPayloadSnapshot(network)),
    workFloor: emptyWorkFloorPayload(network),
  };
}

async function currentProofIndexMarketplaceSummaryFallbackPayload(
  network,
  fresh = false,
  options = {},
) {
  if (network !== "livenet") {
    return null;
  }

  const indexedPayload = await currentProofIndexSummarySnapshotFallbackPayload(
    network,
    "marketplaceSummary",
    "marketplace-summary",
  );
  if (!indexedPayload) {
    return null;
  }

  const workFloor = options.fast
    ? indexedPayload.workFloor
    : await workFloorWithSummaryMarketOverlay(
        indexedPayload.workFloor,
        network,
        fresh,
        indexedPayload.token,
      );
  return marketplaceSummaryPayloadWithIndexedMarketOverlay(
    {
      ...indexedPayload,
      workFloor,
    },
    network,
    options,
  );
}

async function marketplaceSummaryFallbackPayload(network) {
  const cached = await cachedMarketplaceSummaryPayloadNoRefresh(network);
  if (cached) {
    return marketplaceSummaryPayloadWithIndexedMarketOverlay(cached, network);
  }

  const ledger =
    network === "livenet"
      ? await existingCurrentCanonicalLedgerPayloadWithinMs(
          network,
          "marketplace-summary fallback ledger",
        )
      : await existingCanonicalLedgerPayload(network);
  const ledgerPayload = marketplaceSummaryPayloadFromLedger(ledger);
  if (ledgerPayload) {
    return marketplaceSummaryPayloadWithIndexedMarketOverlay(
      ledgerPayload,
      network,
    );
  }

  const indexedPayload =
    await currentProofIndexMarketplaceSummaryFallbackPayload(network);
  if (indexedPayload) {
    return indexedPayload;
  }

  const indexedFloor =
    network === "livenet" ? await proofIndexWorkFloorPayload(network) : null;
  return marketplaceSummaryPayloadWithIndexedMarketOverlay(
    {
      ...emptyMarketplaceSummaryPayload(network),
      ...(indexedFloor ? { workFloor: indexedFloor } : {}),
    },
    network,
  );
}

async function marketplaceSummaryFastFallbackPayload(network) {
  if (network === "livenet") {
    const indexedPayload =
      await currentProofIndexMarketplaceSummaryFallbackPayload(network, false, {
        fast: true,
      });
    if (indexedPayload) {
      return indexedPayload;
    }
  }

  const cached = await payloadWithFallbackAfterMs(
    cachedMarketplaceSummaryPayloadNoRefresh(network),
    null,
    Math.min(2_500, MARKETPLACE_SUMMARY_FRESH_WAIT_MS),
  );
  if (cached) {
    return marketplaceSummaryPayloadWithIndexedMarketOverlay(cached, network, {
      fast: true,
    });
  }

  const ledger =
    network === "livenet"
      ? await payloadWithFallbackAfterMs(
          existingCurrentCanonicalLedgerPayload(
            network,
            "marketplace-summary fast fallback ledger",
          ),
          null,
          Math.min(2_500, MARKETPLACE_SUMMARY_FRESH_WAIT_MS),
        )
      : await payloadWithFallbackAfterMs(
          existingCanonicalLedgerPayload(network),
          null,
          Math.min(2_500, MARKETPLACE_SUMMARY_FRESH_WAIT_MS),
        );
  const ledgerPayload = marketplaceSummaryPayloadFromLedger(ledger);
  if (ledgerPayload) {
    return marketplaceSummaryPayloadWithIndexedMarketOverlay(ledgerPayload, network, {
      fast: true,
    });
  }

  const indexedPayload =
    await currentProofIndexMarketplaceSummaryFallbackPayload(network, false, {
      fast: true,
    });
  if (indexedPayload) {
    return indexedPayload;
  }

  const indexedFloor =
    network === "livenet" ? await proofIndexWorkFloorPayload(network) : null;
  return marketplaceSummaryPayloadWithIndexedMarketOverlay(
    {
      ...emptyMarketplaceSummaryPayload(network),
      ...(indexedFloor ? { workFloor: indexedFloor } : {}),
    },
    network,
    { fast: true },
  );
}

async function reconciledLivenetMarketplaceSummaryPayload(
  network,
  fresh = false,
) {
  if (network === "livenet") {
    let ledger = await summaryCanonicalLedgerPayload(network, fresh);
    if (!ledger && fresh) {
      ledger = await existingCanonicalLedgerPayload(network).catch((error) => {
        console.error(
          `Marketplace summary existing ledger fallback failed: ${errorSummary(error)}`,
        );
        return null;
      });
      if (ledger) {
        refreshCanonicalLedgerPayloadInBackground(network, true);
      }
    }
    if (ledger) {
      if (fresh) {
        const baseWorkTokenState = ledgerTokenStateForScope(
          ledger,
          WORK_TOKEN_ID,
        );
        const refreshedWorkTokenState = await payloadWithFallbackAfterMs(
          workTokenStateForSummaryRead(network, true),
          baseWorkTokenState,
          SUMMARY_TOKEN_CURRENT_FALLBACK_WAIT_MS,
        );
        const currentWorkTokenState = await workTokenStateWithSummaryListingTruth(
          refreshedWorkTokenState,
          network,
          { recoverActiveListings: true },
        );
        const baseTokenState = tokenStateWithScopedTokenOverride(
          ledger.tokenState,
          currentWorkTokenState,
          WORK_TOKEN_ID,
        );
        const marketOverlay = await indexedTokenMarketSummaryOverlay(network);
        const overlaidTokenState = tokenStateWithIndexedMarketSummaryOverlay(
          baseTokenState,
          marketOverlay,
        );
        const tokenState = await tokenPayloadWithSpendableActiveListings(
          overlaidTokenState,
          network,
        );
        const currentTokenState =
          tokenPayloadWithCurrentWorkActiveListingPolicy(
            tokenState,
            network,
          );
        const canonicalTokenState =
          await tokenStateWithCanonicalWorkListingBookForMarketplaceSummary(
            currentTokenState,
            network,
          );
        const ledgerWorkFloor = await workFloorWithSummaryMarketOverlay(
          ledger.workFloor,
          network,
          true,
          canonicalTokenState,
          marketOverlay,
        );
        const workFloor = await currentProofIndexWorkFloorIfNewer(
          ledgerWorkFloor,
          network,
          true,
          "marketplace-summary",
        );
        const registryReconciliation =
          await strictCoreRegistryListingReconciliation(
            attachLedgerMetadata(ledger.registryState, ledger),
            network,
          );
        const registryState = {
          ...ledger.registryState,
          ...registryReconciliation.payload,
          listings: registryReconciliation.payload.listings,
        };
        const indexedAt = newerIso(
          ledger.generatedAt,
          canonicalTokenState?.indexedAt,
        );
        return attachLedgerMetadata(
          {
            indexedAt,
            network,
            registry: attachLedgerMetadata(
              compactRegistrySummaryPayload(registryState),
              ledger,
            ),
            summaryOnly: true,
            token: attachLedgerMetadata(
              compactTokenSummaryPayload(canonicalTokenState),
              ledger,
            ),
            workFloor: attachLedgerMetadata(workFloor, ledger),
          },
          ledger,
        );
      }
      const summaryReadWaitMs = fresh
        ? MARKETPLACE_SUMMARY_CURRENT_FALLBACK_WAIT_MS
        : WORK_TOKEN_LIVE_WAIT_MS;
      const summaryWorkTokenState = fresh
        ? await payloadWithFallbackAfterMs(
            workTokenStateForSummaryRead(network, true),
            null,
            summaryReadWaitMs,
          )
        : null;
      const workTokenState =
        summaryWorkTokenState ??
        (await liveWorkTokenStateWithFallbackAfterMs(
          network,
          ledgerTokenStateForScope(ledger, WORK_TOKEN_ID),
          summaryReadWaitMs,
          { recoverClosedSales: true },
        ));
      const mergedWorkTokenState =
        summaryWorkTokenState && summaryWorkTokenState !== workTokenState
        ? tokenStateWithMergedListingSeals(
            tokenStateWithPreservedListingRecords(
              workTokenState,
              summaryWorkTokenState,
            ),
            summaryWorkTokenState,
          )
        : workTokenState;
      const closeTxs = await payloadWithFallbackAfterMs(
        recentWorkTokenMarketCloseTransactions(
          network,
          WORK_TOKEN_LIVE_CLOSE_MAX_TXS,
          WORK_TOKEN_LIVE_CLOSE_SCAN_MAX_TXS,
        ),
        [],
        fresh
          ? Math.min(
              WORK_TOKEN_SUMMARY_CLOSE_WAIT_MS,
              MARKETPLACE_SUMMARY_CURRENT_FALLBACK_WAIT_MS,
            )
          : WORK_TOKEN_SUMMARY_CLOSE_WAIT_MS,
      );
      let closedWorkTokenState =
        workTokenStateWithRecoveredListingClosesFromTransactions(
          mergedWorkTokenState,
          closeTxs,
          network,
        );
      closedWorkTokenState = await payloadWithFallbackAfterMs(
        workTokenStateWithRecoveredListingCloseSales(
          closedWorkTokenState,
          network,
        ),
        closedWorkTokenState,
        fresh
          ? MARKETPLACE_SUMMARY_CURRENT_FALLBACK_WAIT_MS
          : WORK_TOKEN_SUMMARY_CLOSE_WAIT_MS,
      );
      closedWorkTokenState = await workTokenStateWithSummaryListingTruth(
        closedWorkTokenState,
        network,
        { recoverActiveListings: true },
      );
      const baseTokenState = tokenStateWithScopedTokenOverride(
        ledger.tokenState,
        closedWorkTokenState,
        WORK_TOKEN_ID,
      );
      const marketOverlay = await indexedTokenMarketSummaryOverlay(network);
      const overlaidTokenState = tokenStateWithIndexedMarketSummaryOverlay(
        baseTokenState,
        marketOverlay,
      );
      const tokenState = await tokenPayloadWithSpendableActiveListings(
        overlaidTokenState,
        network,
      );
      const currentTokenState =
        tokenPayloadWithCurrentWorkActiveListingPolicy(
          tokenState,
          network,
        );
      const canonicalTokenState =
        await tokenStateWithCanonicalWorkListingBookForMarketplaceSummary(
          currentTokenState,
          network,
        );
      const ledgerWorkFloor = await workFloorWithCurrentBtcUsd(
        workFloorWithIndexedMarketSummaryOverlay(
          ledger.workFloor,
          marketOverlay,
          canonicalTokenState,
        ),
        network,
        fresh,
      );
      const workFloor = await currentProofIndexWorkFloorIfNewer(
        ledgerWorkFloor,
        network,
        fresh,
        "marketplace-summary",
      );
      const indexedAt = newerIso(
        ledger.generatedAt,
        canonicalTokenState?.indexedAt,
      );
      return attachLedgerMetadata(
        {
          indexedAt,
          network,
          registry: attachLedgerMetadata(
            compactRegistrySummaryPayload(ledger.registryState),
            ledger,
          ),
          summaryOnly: true,
          token: attachLedgerMetadata(
            compactTokenSummaryPayload(canonicalTokenState),
            ledger,
          ),
          workFloor: attachLedgerMetadata(workFloor, ledger),
        },
        ledger,
      );
    }

    throw freshDataUnavailableError(
      fresh
        ? "Fresh marketplace summary ledger is unavailable."
        : "Current marketplace summary ledger is unavailable.",
    );
  }
}

async function refreshMarketplaceSummaryPayloadCache(network, fresh = false) {
  return cacheMarketplaceSummaryPayload(
    network,
    await reconciledLivenetMarketplaceSummaryPayload(network, fresh),
  );
}

async function livenetMarketplaceSummaryPayload(network, fresh = false) {
  const exactIndexedPayload =
    await currentProofIndexMarketplaceSummaryFallbackPayload(
      network,
      fresh,
      { fast: true },
    );
  if (exactIndexedPayload) {
    return marketplaceSummaryWithSpendableIdListings(
      exactIndexedPayload,
      network,
    );
  }
  if (!fresh) {
    const fastFallback = await marketplaceSummaryFastFallbackPayload(network);
    if (
      summaryPayloadHasFiniteNetworkValue(
        network,
        "marketplaceSummary",
        fastFallback,
      )
    ) {
      if (INDEXED_FALLBACK_BACKGROUND_REFRESH) {
        refreshPayloadCacheInBackground(
          marketplaceSummaryCacheKey(network),
          marketplaceSummaryPayloadKey(network),
          () => reconciledLivenetMarketplaceSummaryPayload(network, false),
          MARKETPLACE_SUMMARY_CACHE_TTL_MS,
          MARKETPLACE_SUMMARY_CACHE_STALE_MS,
        );
      }
      return marketplaceSummaryWithSpendableIdListings(
        fastFallback,
        network,
      );
    }

    const [token, workFloor] = await Promise.all([
      tokenSummaryPayload(network, "", false),
      cachedWorkFloorPayload(network, false),
    ]);
    const payload = await marketplaceSummaryPayloadWithIndexedMarketOverlay(
      {
        indexedAt: newerIso(workFloor?.indexedAt, token?.indexedAt),
        network,
        registry: compactRegistrySummaryPayload(emptyRegistryPayload(network)),
        summaryOnly: true,
        token,
        workFloor,
      },
      network,
      { fast: true },
    );
    if (
      summaryPayloadHasFiniteNetworkValue(
        network,
        "marketplaceSummary",
        payload,
      ) &&
      numericValue(payload?.token?.stats?.confirmedTokens) > 0
    ) {
      return payload;
    }
    throw freshDataUnavailableError(
      "Current marketplace summary is unavailable.",
    );
  }

  if (fresh) {
    const refreshed = await payloadWithFallbackAfterMs(
      refreshMarketplaceSummaryPayloadCache(network, true),
      null,
      MARKETPLACE_SUMMARY_CURRENT_FALLBACK_WAIT_MS,
    );
    if (
      summaryPayloadHasFiniteNetworkValue(
        network,
        "marketplaceSummary",
        refreshed,
      )
    ) {
      return refreshed;
    }
    refreshPayloadCacheInBackground(
      marketplaceSummaryCacheKey(network),
      marketplaceSummaryPayloadKey(network),
      () => reconciledLivenetMarketplaceSummaryPayload(network, true),
      MARKETPLACE_SUMMARY_CACHE_TTL_MS,
      MARKETPLACE_SUMMARY_CACHE_STALE_MS,
    );
    throw freshDataUnavailableError(
      "Fresh marketplace summary is unavailable.",
    );
  }

  const fallback = await payloadWithFallbackAfterMs(
    refreshMarketplaceSummaryPayloadCache(network, false),
    null,
    Math.min(2_500, MARKETPLACE_SUMMARY_FRESH_WAIT_MS),
  );
  if (!fallback) {
    const ledgerFallback = await marketplaceSummaryFastFallbackPayload(network);
    if (
      summaryPayloadHasFiniteNetworkValue(
        network,
        "marketplaceSummary",
        ledgerFallback,
      )
    ) {
      refreshPayloadCacheInBackground(
        marketplaceSummaryCacheKey(network),
        marketplaceSummaryPayloadKey(network),
        () => reconciledLivenetMarketplaceSummaryPayload(network, false),
        MARKETPLACE_SUMMARY_CACHE_TTL_MS,
        MARKETPLACE_SUMMARY_CACHE_STALE_MS,
      );
      return ledgerFallback;
    }
    refreshPayloadCacheInBackground(
      marketplaceSummaryCacheKey(network),
      marketplaceSummaryPayloadKey(network),
      () => reconciledLivenetMarketplaceSummaryPayload(network, false),
      MARKETPLACE_SUMMARY_CACHE_TTL_MS,
      MARKETPLACE_SUMMARY_CACHE_STALE_MS,
    );
    throw freshDataUnavailableError(
      "Current marketplace summary is unavailable.",
    );
  }
  refreshPayloadCacheInBackground(
    marketplaceSummaryCacheKey(network),
    marketplaceSummaryPayloadKey(network),
    () => reconciledLivenetMarketplaceSummaryPayload(network, false),
    MARKETPLACE_SUMMARY_CACHE_TTL_MS,
    MARKETPLACE_SUMMARY_CACHE_STALE_MS,
  );
  return fallback;
}

async function marketplaceSummaryPayload(network, fresh = false) {
  if (network === "livenet") {
    return livenetMarketplaceSummaryPayload(network, fresh);
  }

  if (fresh) {
    refreshPayloadCacheInBackground(
      `registry:${network}`,
      `payload:registry:${network}`,
      () => safeRegistryPayload(network),
      REGISTRY_CACHE_TTL_MS,
      REGISTRY_CACHE_STALE_MS,
    );
  }

  const [registry, token, floor] = await Promise.all([
    registrySummaryPayload(network, false),
    tokenSummaryPayload(network, "", fresh),
    fresh
      ? cachedWorkFloorPayload(network, true)
      : cachedWorkFloorPayload(network, false),
  ]);
  return {
    indexedAt: new Date().toISOString(),
    network,
    registry,
    summaryOnly: true,
    token,
    workFloor: floor,
  };
}

function refreshGrowthCachesInBackground(network) {
  refreshCanonicalLedgerPayloadInBackground(network, true);
}

async function growthSummaryPayload(network, fresh = false) {
  if (network === "livenet") {
    const indexedPayload = await currentProofIndexSummarySnapshotFallbackPayload(
      network,
      "growthSummary",
      "growth-summary",
    );
    if (indexedPayload) {
      const currentIndexedPayload = await growthSummaryWithCurrentBtcUsd(
        indexedPayload,
        network,
        fresh,
      );
      if (INDEXED_FALLBACK_BACKGROUND_REFRESH) {
        refreshGrowthCachesInBackground(network);
      }
      return growthSummaryWithCanonicalWorkFloor(
        currentIndexedPayload,
        currentIndexedPayload.workFloor,
      );
    }
  }

  const ledger =
    network === "livenet" && !fresh
      ? await existingCurrentCanonicalLedgerPayloadWithinMs(
          network,
          "growth-summary canonical ledger",
        )
      : await payloadWithFallbackAfterMs(
          summaryCanonicalLedgerPayload(network, fresh),
          null,
          LEDGER_SUMMARY_FRESH_WAIT_MS,
        );
  if (ledger) {
    const ledgerWorkFloor = await workFloorWithSummaryMarketOverlay(
      ledger.workFloor,
      network,
      fresh,
      ledger.tokenState,
    );
    const workFloor = await currentProofIndexWorkFloorIfNewer(
      ledgerWorkFloor,
      network,
      fresh,
      "growth-summary",
    );
    return growthSummaryWithCurrentBtcUsd(
      growthSummaryWithCanonicalWorkFloor(ledger.growthSummary, workFloor),
      network,
      fresh,
    );
  }

  if (network === "livenet") {
    const indexedPayload = await currentProofIndexSummarySnapshotFallbackPayload(
      network,
      "growthSummary",
      "growth-summary",
    );
    if (indexedPayload) {
      const workFloor = await currentProofIndexWorkFloorIfNewer(
        indexedPayload.workFloor,
        network,
        fresh,
        "growth-summary fallback",
      );
      return growthSummaryWithCurrentBtcUsd(
        growthSummaryWithCanonicalWorkFloor(indexedPayload, workFloor),
        network,
        fresh,
      );
    }

    throw freshDataUnavailableError(
      fresh
        ? "Fresh Growth summary ledger is unavailable."
        : "Current Growth summary ledger is unavailable.",
    );
  }

  return growthSummaryWithCurrentBtcUsd(
    (await canonicalLedgerPayload(network, false)).growthSummary,
    network,
    fresh,
  );
}

async function infinitySummaryFromCanonicalLedger(ledger, network, fresh = false) {
  return bondSummaryFromCanonicalLedger(
    ledger,
    network,
    fresh,
    INFINITY_BOND_CONFIG,
  );
}

async function inceptionSummaryFromCanonicalLedger(ledger, network, fresh = false) {
  return bondSummaryFromCanonicalLedger(
    ledger,
    network,
    fresh,
    INCEPTION_BOND_CONFIG,
  );
}

async function bondSummaryFromCanonicalLedger(
  ledger,
  network,
  fresh = false,
  config,
) {
  if (!ledger) {
    return null;
  }

  let btcUsdQuote = ledger.btcUsdQuote;
  if (network === "livenet") {
    btcUsdQuote = await btcUsdPricePayload(network, { fresh }).catch((error) => {
      console.error(
        `${config.displayName} BTC/USD overlay failed: ${errorSummary(error)}`,
      );
      return ledger.btcUsdQuote;
    });
  }

  return attachLedgerMetadata(
    bondSummaryPayloadFromLedger({
      ...ledger,
      btcUsdQuote,
    }, config),
    ledger,
  );
}

async function proofIndexInfinitySummaryPayload(network, fresh = false) {
  return proofIndexBondSummaryPayload(
    network,
    fresh,
    INFINITY_BOND_CONFIG,
  );
}

async function proofIndexInceptionSummaryPayload(network, fresh = false) {
  return proofIndexBondSummaryPayload(
    network,
    fresh,
    INCEPTION_BOND_CONFIG,
  );
}

async function proofIndexBondSummaryPayload(
  network,
  fresh = false,
  config,
  canonicalLedger = null,
) {
  const params = new URLSearchParams([["asset", config.tokenId]]);
  const bondActivityState = await indexedBondActivityForTokenState(
    network,
    config,
  ).catch(
    (error) => {
      console.error(
        `Proof index ${config.displayName} activity read failed: ${errorSummary(error)}`,
      );
      return null;
    },
  );
  let bondTokenState = await currentProofIndexTokenPayloadForRead(
    network,
    config.tokenId,
    `${config.summaryRoute}-token-state`,
    SUMMARY_PROOF_INDEX_READ_WAIT_MS,
  );
  if (!bondTokenState) {
    bondTokenState = await payloadWithFallbackAfterMs(
      proofIndexTokenPayload(network, config.tokenId, params),
      null,
      SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    ).catch((error) => {
      console.error(
        `Proof index ${config.displayName} token-state read failed: ${errorSummary(error)}`,
      );
      return null;
    });
  }

  if (bondTokenState) {
    const rejectedEmpty = rejectEmptyBondTokenPayload(
      network,
      bondTokenState,
      config,
      `${config.summaryRoute}-token-state`,
    );
    const coversTip =
      !rejectedEmpty &&
      (await proofIndexPayloadCoversConfirmedTip(
        bondTokenState,
        network,
        `${config.summaryRoute}-token-state`,
      ));
    if (rejectedEmpty || !coversTip) {
      bondTokenState = null;
    }
  }

  if (!bondTokenState) {
    bondTokenState = await tokenPayloadForRead(network, config.tokenId, fresh, {
      reconcileListingStatus: fresh,
      reconcileSpendable: true,
      scopedRefreshWaitMs: SUMMARY_PROOF_INDEX_READ_WAIT_MS,
      useLedgerSnapshot: false,
    }).catch((error) => {
      console.error(
        `Canonical ${config.displayName} token-state read failed: ${errorSummary(error)}`,
      );
      return null;
    });
    if (bondTokenState) {
      const rejectedEmpty = rejectEmptyBondTokenPayload(
        network,
        bondTokenState,
        config,
        `${config.summaryRoute}-token-state-fallback`,
      );
      const coversTip =
        !rejectedEmpty &&
        (await proofIndexPayloadCoversConfirmedTip(
          bondTokenState,
          network,
          `${config.summaryRoute}-token-state-fallback`,
        ));
      if (rejectedEmpty || !coversTip) {
        bondTokenState = null;
      }
    }
  }

  const bondActivityCoversTip =
    bondActivityState &&
    (await proofIndexPayloadCoversConfirmedTip(
      bondActivityState,
      network,
      `${config.summaryRoute}-activity`,
    ));
  if (!bondTokenState || !bondActivityCoversTip) {
    return null;
  }
  if (
    config.tokenId === INCB_TOKEN_ID &&
    BigInt(
      canonicalIntegerText(bondTokenState.confirmedSupply, {
        allowZero: true,
      }) || "0",
    ) > 0n &&
    !canonicalLedger?.workTokenState
  ) {
    console.error(
      `Rejected ${config.displayName} summary: canonical WORK valuation state is unavailable.`,
    );
    return null;
  }
  const indexedBondFlowSats = (bondActivityState.activity ?? [])
    .filter((item) => item?.confirmed && isBondActivityItem(item, config))
    .reduce((total, item) => total + BigInt(activityAmountSats(item)), 0n);
  const inceptionIssuance = inceptionIssuanceMetadataFromMints(
    bondTokenState.mints,
  );
  const exactBondSupply =
    canonicalIntegerText(bondTokenState.confirmedSupply, { allowZero: true }) ||
    "0";
  if (
    config.tokenId === INCB_TOKEN_ID
      ? !inceptionIssuance.complete ||
        inceptionIssuance.confirmedIssuanceUnits !== exactBondSupply
      : indexedBondFlowSats !== BigInt(exactBondSupply)
  ) {
    console.error(
      `Rejected ${config.displayName} summary: canonical issuance does not match ${config.ticker} supply.`,
    );
    return null;
  }

  bondTokenState = await tokenPayloadWithSpendableActiveListings(
    bondTokenState,
    network,
  );
  const btcUsdQuote = await btcUsdPricePayload(network, { fresh }).catch(
    () => null,
  );
  const generatedAt = Number.isFinite(
    Date.parse(bondTokenState.indexedAt ?? ""),
  )
    ? bondTokenState.indexedAt
    : new Date().toISOString();
  const payload = bondSummaryPayloadFromLedger({
    activity: dedupeActivityItems([
      ...tokenActivityItemsFromState(
        bondTokenState,
        bondTokenState.indexAddress ?? tokenIndexAddressForNetwork(network),
      ),
      ...(bondActivityState.activity ?? []),
    ]),
    btcUsdQuote,
    generatedAt,
    indexedThroughBlock: bondTokenState.indexedThroughBlock,
    network,
    tokenState: bondTokenState,
    ...(canonicalLedger?.workFloor
      ? { workFloor: canonicalLedger.workFloor }
      : {}),
    ...(canonicalLedger?.workTokenState
      ? { workTokenState: canonicalLedger.workTokenState }
      : {}),
  }, config);
  if (
    network === "livenet" &&
    !bondSummaryPayloadHasKnownMainnetValue(payload, config, {
      allowEmptyHistory: config.tokenId === INCB_TOKEN_ID,
      workAmountStorageModel:
        exactWorkAmountStorageModelFromState(
          canonicalLedger?.workTokenState,
        ),
    })
  ) {
    console.error(
      `Rejected ${config.displayName} summary: composite value contract is incomplete.`,
    );
    return null;
  }
  const tokenSnapshotId = String(
    bondTokenState.snapshotId ?? bondTokenState.ledgerSnapshotId ?? "",
  ).trim();
  const tokenLedgerGeneratedAt =
    bondTokenState.ledgerGeneratedAt ??
    bondTokenState.generatedAt ??
    bondTokenState.indexedAt ??
    generatedAt;
  return {
    ...payload,
    indexedThroughBlock:
      bondTokenState.indexedThroughBlock ?? payload.indexedThroughBlock,
    ledgerGeneratedAt: tokenLedgerGeneratedAt,
    ...(tokenSnapshotId ? { snapshotId: tokenSnapshotId } : {}),
    source: mergedSourceLabel(payload.source, bondTokenState.source),
  };
}

async function standaloneInfinitySummaryPayload(network, fresh = false) {
  return standaloneBondSummaryPayload(
    network,
    fresh,
    INFINITY_BOND_CONFIG,
  );
}

async function standaloneInceptionSummaryPayload(network, fresh = false) {
  return standaloneBondSummaryPayload(
    network,
    fresh,
    INCEPTION_BOND_CONFIG,
  );
}

async function standaloneBondSummaryPayload(network, fresh = false, config) {
  void fresh;
  const registryState =
    (await indexedRegistryPayload(network).catch(() => null)) ??
    (await fastJsonBackedPayload(
        `registry:${network}`,
        `payload:registry:${network}`,
        () => safeRegistryPayload(network),
        REGISTRY_CACHE_TTL_MS,
        REGISTRY_CACHE_STALE_MS,
        emptyRegistryPayload(network),
      ).catch(() => null));
  const registryAddress = await bondRegistryAddressForNetwork(
    config,
    network,
    registryState,
  );
  const indexedActivity = await indexedBondActivityForTokenState(
    network,
    config,
  ).catch(() => null);
  const activity = indexedActivity?.activity ?? [];
  const state = tokenStateFromTransactions(
    [],
    new Map(),
    tokenIndexAddressForNetwork(network),
    network,
    config.tokenId,
    [canonicalBondTokenDefinition(config, network, registryAddress)],
    registryAddress
      ? bondMintsFromActivity(activity, registryAddress, network, config)
      : [],
  );
  const bondTokenState = {
    ...state,
    creationPriceSats: TOKEN_CREATION_PRICE_SATS,
    indexedAt: newerIso(indexedActivity?.indexedAt, registryState?.indexedAt),
    indexAddress: tokenIndexAddressForNetwork(network),
    indexId: TOKEN_INDEX_ID,
    indexTxid: TOKEN_INDEX_TXID,
    minMutationPriceSats: TOKEN_MIN_MUTATION_PRICE_SATS,
    network,
    source: indexedActivity?.source ?? "proof-indexer",
    stats: {
      confirmedMints: state.mints.filter((mint) => mint.confirmed).length,
      confirmedTransfers: state.transfers.filter((transfer) => transfer.confirmed)
        .length,
      confirmedTokens: state.tokens.filter((token) => token.confirmed).length,
      creationSats: state.creationSats,
      holders: state.holders.length,
      invalidEvents: (state.invalidEvents ?? []).filter((event) => event.confirmed)
        .length,
      pendingMints: state.mints.filter((mint) => !mint.confirmed).length,
      pendingTransfers: state.transfers.filter((transfer) => !transfer.confirmed)
        .length,
      pendingTokens: state.tokens.filter((token) => !token.confirmed).length,
      registries: registryAddress ? 1 : 0,
      transactions: activity.length,
    },
    workDefaults: canonicalWorkDefaults(),
  };
  const btcUsdQuote =
    network === "livenet"
      ? await btcUsdPricePayload(network, { fresh }).catch(() => null)
      : null;
  const indexedAt = newerIso(
    bondTokenState.indexedAt,
    registryState?.indexedAt,
  );
  return bondSummaryPayloadFromLedger({
    activity: dedupeActivityItems([
      ...tokenActivityItemsFromState(
        bondTokenState,
        bondTokenState.indexAddress ?? tokenIndexAddressForNetwork(network),
      ),
      ...activity,
    ]),
    btcUsdQuote,
    generatedAt: Number.isFinite(Date.parse(indexedAt ?? ""))
      ? indexedAt
      : new Date().toISOString(),
    network,
    tokenState: bondTokenState,
    workTokenState: {
      amountStorageModel: WORK_ATOMIC_PROJECTION_MODEL,
      transfers: [],
    },
  }, config);
}

async function infinitySummaryPayload(network, fresh = false) {
  return bondSummaryPayload(network, fresh, INFINITY_BOND_CONFIG);
}

async function inceptionSummaryPayload(network, fresh = false) {
  return bondSummaryPayload(network, fresh, INCEPTION_BOND_CONFIG);
}

async function bondSummaryPayload(network, fresh = false, config) {
  if (network === "livenet") {
    const exactIndexedPayload =
      await currentProofIndexSummarySnapshotFallbackPayload(
        network,
        config.summaryKey,
        config.summaryRoute,
      );
    if (exactIndexedPayload) {
      return exactIndexedPayload;
    }
  }

  const currentLedger =
    network === "livenet"
      ? await existingCurrentCanonicalLedgerPayloadWithinMs(
          network,
          `${config.summaryRoute} canonical ledger`,
        )
      : null;
  const ledger =
    network === "livenet"
      ? currentLedger ??
        (fresh
          ? await payloadWithFallbackAfterMs(
              summaryCanonicalLedgerPayload(network, true),
              null,
              LEDGER_SUMMARY_FRESH_WAIT_MS,
            )
          : null)
      : await payloadWithFallbackAfterMs(
          summaryCanonicalLedgerPayload(network, fresh),
          null,
          LEDGER_SUMMARY_FRESH_WAIT_MS,
        );

  if (network === "livenet") {
    const indexed = await proofIndexBondSummaryPayload(
      network,
      fresh,
      config,
      ledger,
    );
    const ledgerSummary = ledger?.[config.summaryKey];
    const indexedSupply = integerBigInt(indexed?.stats?.confirmedSupply, {
      allowZero: true,
    });
    const ledgerSupply = integerBigInt(
      ledgerSummary?.stats?.confirmedSupply,
      { allowZero: true },
    );
    if (
      indexed &&
      (!ledgerSummary?.registryAddress ||
        (indexedSupply !== null &&
          ledgerSupply !== null &&
          indexedSupply >= ledgerSupply &&
          numericValue(indexed.stats?.confirmedBondActions) >=
            numericValue(ledgerSummary.stats?.confirmedBondActions) &&
          numericValue(indexed.stats?.holders) >=
            numericValue(ledgerSummary.stats?.holders)))
    ) {
      return indexed;
    }
    if (ledgerSummary?.registryAddress) {
      const canonicalPayload = await bondSummaryFromCanonicalLedger(
        ledger,
        network,
        fresh,
        config,
      );
      if (
        summaryPayloadHasFiniteNetworkValue(
          network,
          config.summaryKey,
          canonicalPayload,
        )
      ) {
        return canonicalPayload;
      }
      console.error(
        `Rejected ${config.displayName} canonical-ledger summary: composite value contract is incomplete.`,
      );
    }
    if (indexed) {
      return indexed;
    }
    throw freshDataUnavailableError(
      fresh
        ? `Fresh ${config.displayName} summary ledger is unavailable.`
        : `Current ${config.displayName} summary ledger is unavailable.`,
    );
  }

  return standaloneBondSummaryPayload(network, fresh, config);
}

function registryPendingHistoryItems(payload) {
  const seen = new Set();
  const items = [];
  const pendingCollections = [
    ["pending-event", payload?.pendingEvents],
    ["register", payload?.records],
    ["list", payload?.listings],
    ["marketTransfer", payload?.sales],
  ];
  const shouldInclude = (item, sourceKind) => {
    if (!item || typeof item !== "object" || Array.isArray(item)) {
      return false;
    }
    if (sourceKind === "pending-event") {
      return true;
    }
    return (
      item.confirmed === false ||
      String(item.status ?? "").trim().toLowerCase() === "pending"
    );
  };
  const identityFor = (item, sourceKind) => {
    const txid = String(item.txid ?? "").trim().toLowerCase();
    const listingId = String(item.listingId ?? "").trim().toLowerCase();
    const id = normalizePowId(String(item.id ?? ""));
    const itemKind = String(item.kind ?? sourceKind).trim().toLowerCase();
    return [txid, listingId, id, itemKind].join(":");
  };

  for (const [sourceKind, collection] of pendingCollections) {
    for (const item of Array.isArray(collection) ? collection : []) {
      if (!shouldInclude(item, sourceKind)) {
        continue;
      }
      const key = identityFor(item, sourceKind);
      if (!key || seen.has(key)) {
        continue;
      }
      seen.add(key);
      items.push({
        ...item,
        confirmed: false,
        kind:
          sourceKind === "pending-event"
            ? (item.kind ?? "pending")
            : (item.kind ?? sourceKind),
        status: item.status ?? "pending",
      });
    }
  }

  return items.sort(
    (left, right) =>
      Date.parse(right.createdAt ?? "") - Date.parse(left.createdAt ?? "") ||
      compareCanonicalUtf8(String(left.txid ?? ""), String(right.txid ?? "")),
  );
}

const REGISTRY_HISTORY_CURSOR_PREFIX = "registry-v2";
const REGISTRY_HISTORY_CURSOR_MODEL = "proof-registry-history-cursor-v2";

function registryHistoryStableKey(item) {
  const parsedTime = Date.parse(
    String(item?.createdAt ?? item?.indexedAt ?? ""),
  );
  return {
    digest: sha256Hex(
      Buffer.from(checkpointCursorCanonicalJson(item), "utf8"),
    ),
    effectiveTime: Number.isFinite(parsedTime)
      ? new Date(parsedTime).toISOString()
      : "",
    protocolVout: Number.isSafeInteger(Number(item?.protocolVout))
      ? Number(item.protocolVout)
      : -1,
    recordOrdinal: Number.isSafeInteger(Number(item?.recordOrdinal))
      ? Number(item.recordOrdinal)
      : -1,
    txid: String(item?.txid ?? item?.listingId ?? "").trim().toLowerCase(),
  };
}

function compareRegistryHistoryStableKeys(left, right) {
  return (
    Date.parse(right.effectiveTime || 0) -
      Date.parse(left.effectiveTime || 0) ||
    compareCanonicalUtf8(right.txid, left.txid) ||
    left.protocolVout - right.protocolVout ||
    left.recordOrdinal - right.recordOrdinal ||
    compareCanonicalUtf8(left.digest, right.digest)
  );
}

function registryHistoryCursorPage({
  indexedAt,
  indexedThroughBlock,
  indexedThroughBlockHash,
  items,
  kind,
  network,
  request,
  source,
}) {
  const checkpointHeight = Number(indexedThroughBlock);
  const checkpointHash = String(indexedThroughBlockHash ?? "")
    .trim()
    .toLowerCase();
  if (
    !Number.isSafeInteger(checkpointHeight) ||
    checkpointHeight < 1 ||
    !/^[0-9a-f]{64}$/u.test(checkpointHash)
  ) {
    throw registryAuthorityUnavailable(
      "Registry history has no exact hashed scan checkpoint.",
    );
  }
  const filterFingerprint = sha256Hex(
    Buffer.from(
      checkpointCursorCanonicalJson({ kind, network, query: request.query }),
      "utf8",
    ),
  );
  const entries = historyItemsMatchingQuery(
    Array.isArray(items) ? items : [],
    request.query,
  )
    .map((item) => ({ item, key: registryHistoryStableKey(item) }))
    .sort((left, right) =>
      compareRegistryHistoryStableKeys(left.key, right.key),
    );
  const membershipSha256 = sha256Hex(
    Buffer.from(
      checkpointCursorCanonicalJson(entries.map((entry) => entry.key)),
      "utf8",
    ),
  );
  const totalCount = entries.length;
  let start = 0;
  if (request.cursor) {
    const cursor = request.cursor;
    const emitted = Number(cursor.emitted);
    const cursorMatches =
      cursor.model === REGISTRY_HISTORY_CURSOR_MODEL &&
      cursor.network === network &&
      cursor.kind === kind &&
      cursor.filterFingerprint === filterFingerprint &&
      cursor.checkpointHeight === checkpointHeight &&
      cursor.checkpointHash === checkpointHash &&
      cursor.membershipSha256 === membershipSha256 &&
      cursor.total === totalCount &&
      Number.isSafeInteger(emitted) &&
      emitted > 0 &&
      emitted <= totalCount &&
      checkpointCursorCanonicalJson(cursor.last) ===
        checkpointCursorCanonicalJson(entries[emitted - 1]?.key);
    if (!cursorMatches) {
      throw historyCursorConflict(
        "Registry history changed after the prior page; restart from page one.",
        {
          checkpointHash,
          checkpointHeight,
          kind,
          network,
        },
      );
    }
    start = emitted;
  }
  const end = Math.min(totalCount, start + request.limit);
  const pageEntries = entries.slice(start, end);
  const hasMore = end < totalCount;
  const nextCursor = hasMore
    ? encodedCheckpointCursor(REGISTRY_HISTORY_CURSOR_PREFIX, {
        checkpointHash,
        checkpointHeight,
        emitted: end,
        filterFingerprint,
        kind,
        last: pageEntries.at(-1).key,
        membershipSha256,
        model: REGISTRY_HISTORY_CURSOR_MODEL,
        network,
        total: totalCount,
      })
    : "";
  const snapshotId = `registry:${checkpointHeight}:${checkpointHash.slice(0, 16)}:${membershipSha256.slice(0, 16)}`;
  return {
    cursor: request.cursorRaw,
    emitted: end,
    end,
    hasMore,
    indexedAt,
    indexedThroughBlock: checkpointHeight,
    indexedThroughBlockHash: checkpointHash,
    items: pageEntries.map((entry) => entry.item),
    kind,
    limit: request.limit,
    membershipSha256,
    network,
    nextCursor,
    page: Math.floor(start / request.limit),
    pageCount: Math.max(1, Math.ceil(totalCount / request.limit)),
    pageSize: request.limit,
    query: request.query,
    snapshotId,
    source,
    start,
    totalCount,
  };
}

async function registryHistoryPayload(network, kind, searchParams, fresh = false) {
  const payload = network === "livenet"
    ? await strictPublicRegistryPayload(network, { fresh })
    : fresh
      ? await safeRegistryPayload(network)
      : await fastJsonBackedPayload(
          `registry:${network}`,
          `payload:registry:${network}`,
          () => safeRegistryPayload(network),
          REGISTRY_CACHE_TTL_MS,
          REGISTRY_CACHE_STALE_MS,
          emptyRegistryPayload(network),
        );
  const safeKind = new Set([
    "activity",
    "listings",
    "pending",
    "records",
    "sales",
  ]).has(kind)
    ? kind
    : "records";
  const items =
    safeKind === "pending"
      ? registryPendingHistoryItems(payload)
      : (payload[safeKind] ?? []);

  return registryHistoryCursorPage({
    indexedAt: payload.indexedAt ?? new Date().toISOString(),
    indexedThroughBlock: payload.indexedThroughBlock,
    indexedThroughBlockHash: payload.indexedThroughBlockHash,
    items,
    kind: safeKind,
    network,
    request: checkpointHistoryRequest(
      searchParams,
      REGISTRY_HISTORY_CURSOR_PREFIX,
    ),
    source: payload.source ?? mempoolBase(network),
  });
}

function dateIso(value, fallback = new Date()) {
  const date = value instanceof Date ? value : new Date(value ?? fallback);
  if (Number.isNaN(date.getTime())) {
    return fallback.toISOString();
  }
  return date.toISOString();
}

function mailActivityItemFromMailMessage(message, address, network) {
  const txid = String(message?.txid ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(txid)) {
    return null;
  }

  const confirmed =
    message?.confirmed === true || message?.status === "confirmed";
  const createdAt = dateIso(
    message?.createdAt ?? message?.confirmedAt ?? message?.lastCheckedAt,
    new Date(),
  );
  const from = String(message?.from ?? message?.actor ?? "").trim();
  const to = String(message?.to ?? message?.counterparty ?? "").trim();
  const recipients = Array.isArray(message?.recipients)
    ? message.recipients
        .map((recipient) => ({
          address: String(recipient?.address ?? recipient?.display ?? "").trim(),
          amountSats: numericValue(recipient?.amountSats),
          display: String(recipient?.display ?? recipient?.address ?? "").trim(),
        }))
        .filter((recipient) => recipient.address || recipient.display)
    : [];
  if (recipients.length === 0 && isValidBitcoinAddress(to, network)) {
    recipients.push({
      address: to,
      amountSats: numericValue(message?.amountSats),
      display: to,
    });
  }

  const memo = String(message?.memo ?? "").trim();
  const protocolKind = String(message?.protocolKind ?? message?.kind ?? "")
    .trim()
    .toLowerCase();
  const isFile = ["attachment", "browser", "file"].includes(protocolKind);
  const isReply = Boolean(message?.parentTxid ?? message?.replyTo);
  const bondConfig =
    bondConfigForKind(protocolKind) ??
    (!isFile && !isReply ? bondConfigForMemo(memo) : null);
  const kind = isFile
    ? "file"
    : isReply
      ? "reply"
      : bondConfig
        ? bondConfig.kind
        : "mail";
  const amountSats =
    numericValue(message?.amountSats) ||
    recipients.reduce(
      (total, recipient) => total + numericValue(recipient.amountSats),
      0,
    );
  const attachedCredits = mailAttachedCreditsFromRecord(message, network);
  const actor = from || address;
  const counterparty =
    to ||
    (recipients.length === 1
      ? recipients[0].display || recipients[0].address
      : recipients.length > 1
        ? `${recipients[0].display || recipients[0].address} +${recipients.length - 1}`
        : "Unknown");
  const attachment = message?.attachment;
  const detail = attachment
    ? `${attachment.name} · ${formatBytes(attachment.size)} · ${attachment.mime}`
    : message?.subject
      ? `Subject: ${message.subject}`
      : compactText(memo, 120) || "No message body";

  return {
    amountSats,
    actor,
    attachedCredits:
      attachedCredits.length > 0 ? attachedCredits : undefined,
    blockHash: String(message?.blockHash ?? "").trim().toLowerCase(),
    blockHeight: message?.blockHeight,
    blockIndex: message?.blockIndex,
    confirmed,
    counterparty,
    createdAt,
    dataBytes: numericValue(message?.dataBytes),
    description: `${shortAddress(actor)} sent ${bondConfig ? bondConfig.displayName.toLowerCase() : kind} to ${counterparty}${amountSats > 0 ? ` for ${amountSats.toLocaleString()} proofs` : ""}.`,
    detail,
    kind,
    memo,
    network,
    parentTxid: message?.parentTxid,
    participants: [
      actor,
      ...recipients.map((recipient) => recipient.address || recipient.display),
    ].filter(Boolean),
    recipients,
    subject: message?.subject,
    tags: [
      activityStatusTag(confirmed),
      networkLabel(network),
      bondConfig
        ? bondConfig.displayName
        : kind === "file"
          ? "Attachment"
          : kind === "reply"
            ? "Reply"
            : "Message",
      recipients.length > 1 ? `${recipients.length} recipients` : "1 recipient",
      amountSats > 0 ? `${amountSats.toLocaleString()} proofs` : "",
    ].filter(Boolean),
    title: `${bondConfig?.displayName ?? (kind === "file" ? "File" : kind === "reply" ? "Reply" : "Mail")} ${confirmed ? "sent" : "pending"}`,
    txid,
  };
}

function mailActivityItemsFromMailPayload(payload, address, network) {
  const messages = [
    ...(Array.isArray(payload?.inboxMessages) ? payload.inboxMessages : []),
    ...(Array.isArray(payload?.sentMessages) ? payload.sentMessages : []),
  ];
  return dedupeActivityItems(
    messages
      .map((message) =>
        mailActivityItemFromMailMessage(message, address, network),
      )
      .filter(Boolean),
  );
}

async function mailActivityItemsForAddressSearch(address, network) {
  return cachedPayload(
    `direct-mail-activity:${network}:${address}`,
    async () => {
      const indexedPayload = await indexedMailPayload(address, network);
      const indexedItems = mailActivityItemsFromMailPayload(
        indexedPayload,
        address,
        network,
      );
      if (indexedItems.length > 0) {
        return indexedItems;
      }

      const payload = await nodeMailPayload(address, network, {
        includeExternal: true,
        maxPages: MAIL_INDEXED_REPAIR_TX_PAGES,
      });
      return mailActivityItemsFromMailPayload(payload, address, network);
    },
    ACTIVITY_CACHE_TTL_MS,
    ACTIVITY_CACHE_STALE_MS,
  );
}

async function mailActivityItemsForTxidSearch(txid, network) {
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(normalizedTxid)) {
    return [];
  }

  return cachedPayload(
    `direct-mail-activity-txid:${network}:${normalizedTxid}`,
    async () => {
      const tx = await fetchTransactionWithSourceFallback(
        normalizedTxid,
        network,
      );
      const item = mailActivityItemFromTransaction(tx, network);
      return item ? [item] : [];
    },
    ACTIVITY_CACHE_TTL_MS,
    ACTIVITY_CACHE_STALE_MS,
  );
}

function isMailRecoveryHistoryKind(kind) {
  const normalizedKind = String(kind ?? "").trim().toLowerCase();
  return (
    !normalizedKind ||
    [
      "attachment",
      "browser",
      "file",
      INCEPTION_BOND_KIND,
      INFINITY_BOND_KIND,
      "mail",
      "reply",
    ].includes(normalizedKind)
  );
}

function mailRecoveryKindMatches(item, kind) {
  const normalizedKind = String(kind ?? "").trim().toLowerCase();
  if (!normalizedKind) {
    return true;
  }
  const itemKind = String(item?.kind ?? "").trim().toLowerCase();
  return (
    itemKind === normalizedKind ||
    (normalizedKind === "attachment" && itemKind === "file")
  );
}

async function recoveredMailActivityItemsForHistorySearch(
  network,
  requestedKind,
  searchParams,
) {
  const normalizedKind = String(requestedKind ?? "").trim().toLowerCase();
  if (!isMailRecoveryHistoryKind(normalizedKind)) {
    return [];
  }

  const recoveryTxids = recoveryTxidsFromSearchParams(searchParams);
  const recoveryAddresses = recoveryAddressesFromSearchParams(
    searchParams,
    network,
  );
  if (recoveryTxids.length === 0 && recoveryAddresses.length === 0) {
    return [];
  }

  const [txidResults, addressResults] = await Promise.all([
    Promise.all(
      recoveryTxids.map((txid) =>
        mailActivityItemsForTxidSearch(txid, network).catch((error) => {
          console.error(
            `Direct log mail txid lookup failed for ${txid}: ${errorSummary(error)}`,
          );
          return [];
        }),
      ),
    ),
    Promise.all(
      recoveryAddresses.map((address) =>
        mailActivityItemsForAddressSearch(address, network).catch((error) => {
          console.error(
            `Direct log mail address lookup failed for ${address}: ${errorSummary(error)}`,
          );
          return [];
        }),
      ),
    ),
  ]);

  return dedupeActivityItems([...txidResults, ...addressResults].flat()).filter(
    (item) => mailRecoveryKindMatches(item, normalizedKind),
  );
}

async function recoveredWorkTokenActivityItemsForLogSearch(
  network,
  requestedKind,
  searchParams,
) {
  const recoveryTxids = recoveryTxidsFromSearchParams(searchParams);
  const recoveryAddresses = pendingWorkMarketAddressesFromSearch(
    searchParams,
    network,
  );
  if (
    network !== "livenet" ||
    (recoveryTxids.length === 0 && recoveryAddresses.length === 0)
  ) {
    return [];
  }

  const kind = String(requestedKind ?? "").trim();
  if (
    kind &&
    kind !== "token-sale" &&
    kind !== "token-listing-closed" &&
    kind !== "token-listing" &&
    kind !== "token-event-invalid"
  ) {
    return [];
  }

  if (!kind || kind === "token-listing") {
    const pendingListingPage = await pendingWorkMarketHistoryPage(
      network,
      WORK_TOKEN_ID,
      "listings",
      searchParams,
    ).catch((error) => {
      console.error(
        `Recovered pending WORK listing Log lookup failed: ${errorSummary(error)}`,
      );
      return null;
    });
    if (Array.isArray(pendingListingPage?.items) &&
      pendingListingPage.items.length > 0) {
      return tokenActivityItemsFromState(
        {
          closedListings: [],
          listings: pendingListingPage.items,
          mints: [],
          sales: [],
          tokens: [],
          transfers: [],
        },
        "",
      ).filter((item) => (kind ? item.kind === kind : true));
    }
  }

  const state = {
    closedListings: [],
    listings: [],
    mints: [],
    sales: [],
    tokens: [],
    transfers: [],
    invalidEvents: [],
  };
  if (!kind || kind === "token-listing") {
    const listingsPage = await tokenHistoryPayload(
      network,
      WORK_TOKEN_ID,
      "listings",
      searchParams,
      true,
    ).catch((error) => {
      console.error(
        `Recovered WORK listing Log lookup failed: ${errorSummary(error)}`,
      );
      return null;
    });
    state.listings = Array.isArray(listingsPage?.items)
      ? listingsPage.items
      : [];
  }
  if (!kind || kind === "token-sale") {
    const salesPage = await tokenHistoryPayload(
      network,
      WORK_TOKEN_ID,
      "sales",
      searchParams,
      true,
    ).catch((error) => {
      console.error(
        `Recovered WORK sale Log lookup failed: ${errorSummary(error)}`,
      );
      return null;
    });
    state.sales = Array.isArray(salesPage?.items) ? salesPage.items : [];
  }
  if (!kind || kind === "token-listing-closed") {
    const closedPage = await tokenHistoryPayload(
      network,
      WORK_TOKEN_ID,
      "closed-listings",
      searchParams,
      true,
    ).catch((error) => {
      console.error(
        `Recovered WORK close Log lookup failed: ${errorSummary(error)}`,
      );
      return null;
    });
    state.closedListings = Array.isArray(closedPage?.items)
      ? closedPage.items
      : [];
  }
  if (!kind || kind === "token-event-invalid") {
    const invalidPage = await tokenHistoryPayload(
      network,
      WORK_TOKEN_ID,
      "invalid-events",
      searchParams,
      true,
    ).catch((error) => {
      console.error(
        `Recovered WORK invalid-event Log lookup failed: ${errorSummary(error)}`,
      );
      return null;
    });
    state.invalidEvents = Array.isArray(invalidPage?.items)
      ? invalidPage.items
      : [];
  }

  const invalidActivity = (state.invalidEvents ?? []).map((event) => ({
    ...canonicalEventIdentityDetails(event),
    amountSats: numericValue(event?.paidSats ?? event?.amountSats),
    actor:
      event?.sellerAddress ??
      event?.senderAddress ??
      event?.minterAddress ??
      event?.actor,
    confirmed: event?.confirmed === true,
    counterparty: event?.registryAddress,
    createdAt: event?.createdAt,
    dataBytes: numericValue(event?.dataBytes),
    description:
      event?.reason ??
      `Invalid ${event?.ticker ?? "credit"} event ${shortAddress(event?.txid)}`,
    detail: event?.reasonCode ?? "Invalid credit event",
    kind: "token-event-invalid",
    minerFeeSats: numericValue(event?.minerFeeSats),
    network: event?.network ?? network,
    participants: Array.isArray(event?.participants)
      ? event.participants
      : [
          event?.sellerAddress,
          event?.senderAddress,
          event?.recipientAddress,
          event?.registryAddress,
        ].filter(Boolean),
    protocol: "pwt1",
    tags: [
      activityStatusTag(event?.confirmed === true),
      networkLabel(event?.network ?? network),
      "Credit",
      "Invalid",
      event?.ticker,
    ].filter(Boolean),
    title: event?.confirmed === true
      ? "Credit event invalid"
      : "Credit event invalid pending",
    tokenId: event?.tokenId,
    txid: event?.txid,
  }));
  return dedupeActivityItems([
    ...tokenActivityItemsFromState(state, ""),
    ...invalidActivity,
  ]).filter((item) => (kind ? item.kind === kind : true));
}

async function exactLogHistoryMissPayload(
  indexedPayload,
  network,
  txid,
  searchParams = null,
) {
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  if (!indexedPayload || !/^[0-9a-f]{64}$/u.test(normalizedTxid)) {
    return null;
  }

  const unavailableDisposition = {
    resolved: false,
    status: null,
  };
  const disposition = await payloadWithFallbackAfterMs(
    proofIndexTxStatusPayload(normalizedTxid, network, {
      includeUnconfirmed: true,
    })
      .then((status) => ({ resolved: true, status }))
      .catch((error) => {
        console.error(
          `Exact Log transaction disposition failed for ${normalizedTxid}: ${errorSummary(error)}`,
        );
        return unavailableDisposition;
      }),
    unavailableDisposition,
    SUMMARY_PROOF_INDEX_READ_WAIT_MS,
  );
  if (disposition?.resolved !== true) {
    const unavailable = freshDataUnavailableError(
      "The canonical Log transaction disposition is unavailable.",
    );
    unavailable.details = {
      code: "CANONICAL_LOG_TX_DISPOSITION_UNAVAILABLE",
      txid: normalizedTxid,
    };
    throw unavailable;
  }
  const status = disposition.status;
  if (!status) {
    return {
      ...indexedPayload,
      queryDisposition: "not-indexed-proof-event",
    };
  }
  if (status.status === "dropped") {
    return {
      ...indexedPayload,
      queryDisposition: "terminal-nonpublic",
    };
  }

  const recoverySearchParams = new URLSearchParams(
    searchParams ?? undefined,
  );
  if (!recoverySearchParams.has("q")) {
    recoverySearchParams.set("q", normalizedTxid);
  }
  const recoveredTokenItems =
    typeof recoveredWorkTokenActivityItemsForLogSearch === "function"
      ? await recoveredWorkTokenActivityItemsForLogSearch(
          network,
          String(recoverySearchParams.get("kind") ?? "").trim(),
          recoverySearchParams,
        ).catch((error) => {
          console.error(
            `Exact Log pending WORK market recovery failed for ${normalizedTxid}: ${errorSummary(error)}`,
          );
          return [];
        })
      : [];
  if (recoveredTokenItems.length > 0) {
    return {
      ...indexedPayload,
      ...paginatedHistoryPayload({
        indexedAt: new Date().toISOString(),
        items: recoveredTokenItems,
        kind:
          String(recoverySearchParams.get("kind") ?? "").trim().toLowerCase() ||
          "activity",
        network,
        pagination: historyPaginationFromSearch(recoverySearchParams),
        source: mergedSourceLabel(
          indexedPayload.source,
          "first-party-core-pending-work-market-recovery",
        ),
      }),
      queryDisposition: "recovered-pending-proof-event",
    };
  }

  const unavailable = freshDataUnavailableError(
    "The canonical Log projection is unavailable for this indexed transaction.",
  );
  unavailable.details = {
    code: "CANONICAL_LOG_PROJECTION_MISSING",
    status: status.status,
    txid: normalizedTxid,
  };
  throw unavailable;
}

async function activityHistoryPayload(network, kind, searchParams, fresh = false) {
  const payload = await mergedLogActivityPayload(network, fresh);
  const requestedKind = String(kind ?? "").trim();
  const recoveredTokenActivity =
    await recoveredWorkTokenActivityItemsForLogSearch(
      network,
      requestedKind,
      searchParams,
    );
  const directMailActivity = await recoveredMailActivityItemsForHistorySearch(
    network,
    requestedKind,
    searchParams,
  );
  const activity = dedupeActivityItems([
    ...(payload.activity ?? []),
    ...directMailActivity,
    ...recoveredTokenActivity,
  ]);
  const items = requestedKind
    ? activity.filter((item) => item.kind === requestedKind)
    : activity;

  const page = paginatedHistoryPayload({
    indexedAt: payload.indexedAt ?? new Date().toISOString(),
    items,
    kind: requestedKind || "activity",
    network,
    pagination: historyPaginationFromSearch(searchParams),
    source: payload.source ?? mempoolBase(network),
  });
  return payload.snapshotId
    ? {
        ...page,
        consistency: payload.consistency,
        ledgerGeneratedAt: payload.ledgerGeneratedAt,
        snapshotId: payload.snapshotId,
      }
    : page;
}

async function eventHistoryRecoveryPayload(network, searchParams) {
  const requestedKind = String(searchParams.get("kind") ?? "").trim().toLowerCase();
  const [mailItems, tokenItems] = await Promise.all([
    recoveredMailActivityItemsForHistorySearch(
      network,
      requestedKind,
      searchParams,
    ),
    recoveredWorkTokenActivityItemsForLogSearch(
      network,
      requestedKind,
      searchParams,
    ),
  ]);
  const recoveredItems = dedupeActivityItems([...mailItems, ...tokenItems]);
  if (recoveredItems.length === 0) {
    return null;
  }

  return paginatedHistoryPayload({
    indexedAt: new Date().toISOString(),
    items: recoveredItems,
    kind: requestedKind || "events",
    network,
    pagination: historyPaginationFromSearch(searchParams),
    source: mergedSourceLabel(
      mailItems.length > 0 ? "first-party-mail-event-recovery" : "",
      tokenItems.length > 0
        ? "first-party-core-pending-work-market-recovery"
        : "",
    ),
  });
}

function mergeEventHistoryRecoveryPayload(
  indexedPayload,
  recoveredPayload,
  network,
  searchParams,
) {
  if (!recoveredPayload || Number(recoveredPayload.totalCount ?? 0) < 1) {
    return indexedPayload;
  }

  const mergedItems = dedupeActivityItems([
    ...(Array.isArray(indexedPayload?.items) ? indexedPayload.items : []),
    ...(Array.isArray(recoveredPayload.items) ? recoveredPayload.items : []),
  ]);
  const page = paginatedHistoryPayload({
    indexedAt: new Date().toISOString(),
    items: mergedItems,
    kind: String(searchParams.get("kind") ?? "").trim().toLowerCase() || "events",
    network,
    pagination: historyPaginationFromSearch(searchParams),
    source: mergedSourceLabel(indexedPayload?.source, recoveredPayload.source),
  });

  return {
    ...(indexedPayload ?? {}),
    ...page,
    source: page.source,
  };
}

async function canonicalTokenDirectoryPayload(
  network,
  tokenScope,
  pagination,
  fresh = false,
) {
  const scope = normalizeTokenScope(tokenScope);
  const storedSummary = await storedCanonicalTokenSummaryPayload(network, scope);
  if (!storedSummary) {
    throw freshDataUnavailableError(
      fresh
        ? `Fresh hash-bound credit directory is still catching up for ${scope || "all"}.`
        : `Current hash-bound credit directory is unavailable for ${scope || "all"}.`,
    );
  }
  const canonicalSummary = await summaryPayloadWithCanonicalProvenance(
    storedSummary,
    network,
    fresh,
    `token-directory:${scope || "all"}`,
  );
  const page = paginatedHistoryPayload({
    indexedAt:
      canonicalSummary.indexedAt ??
      canonicalSummary.generatedAt ??
      canonicalSummary.ledgerGeneratedAt,
    items: Array.isArray(canonicalSummary.tokens)
      ? canonicalSummary.tokens
      : [],
    kind: "tokens",
    network,
    pagination,
    source: canonicalSummary.source,
  });
  return {
    ...page,
    consistency: canonicalSummary.consistency,
    indexedThroughBlock:
      proofIndexPayloadIndexedThroughBlock(canonicalSummary) ||
      page.indexedThroughBlock,
    indexedThroughBlockHash:
      payloadIndexedThroughBlockHash(canonicalSummary) || undefined,
    ledgerGeneratedAt:
      canonicalSummary.ledgerGeneratedAt ??
      canonicalSummary.generatedAt ??
      canonicalSummary.indexedAt,
    provenance: canonicalSummary.provenance,
    snapshotId: canonicalSummary.snapshotId,
  };
}

const TOKEN_LISTING_HISTORY_CURSOR_PREFIX = "token-listings-v2";

function tokenListingHistoryUnavailable(message, details = {}) {
  const error = new Error(message);
  error.statusCode = 503;
  error.details = { code: "TOKEN_LISTING_HISTORY_UNAVAILABLE", ...details };
  return error;
}

function tokenListingHistoryStableKey(listing) {
  return [
    String(listing?.listingId ?? listing?.txid ?? "").trim().toLowerCase(),
    Number(listing?.blockHeight ?? 0),
    Number(listing?.blockIndex ?? 0),
    Number(listing?.protocolVout ?? 0),
    Number(listing?.recordOrdinal ?? 0),
  ];
}

async function completeTokenListingHistoryPayload(network, tokenScope, searchParams) {
  const request = checkpointHistoryRequest(searchParams, TOKEN_LISTING_HISTORY_CURSOR_PREFIX);
  const scope = normalizeTokenScope(tokenScope);
  const relational = await proofIndexCreditListingsPayload(network, scope, {
    limit: TOKEN_LISTING_LIFECYCLE_MATERIALIZATION_LIMIT,
    requireComplete: true,
  });
  const lifecycleCapacity = tokenListingLifecycleCapacityStats(relational);
  logTokenListingLifecycleCapacity(
    lifecycleCapacity,
    `complete-history:${scope || "all"}`,
  );
  const relationalItems = Array.isArray(relational?.items) ? relational.items : null;
  const declaredTotal = Number(relational?.totalCount);
  const relationalHeight = Number(relational?.indexedThroughBlock);
  const relationalHash = String(relational?.indexedThroughBlockHash ?? "").trim().toLowerCase();
  const relationalWorkMarketAuthorizationVersions = [
    ...new Set(
      (Array.isArray(relational?.stats?.workMarketAuthorizationVersions)
        ? relational.stats.workMarketAuthorizationVersions
        : [])
        .map((version) => String(version ?? "").trim().toLowerCase())
        .filter(Boolean),
    ),
  ];
  const relationalScopeIncludesWork =
    network === "livenet" &&
    (!scope ||
      String(scope).toLowerCase() === "all" ||
      scope === "work" ||
      scope === WORK_TOKEN_ID);
  const workAmoV8BoundaryConfigured =
    Number.isSafeInteger(WORK_AMO_V8_ACTIVATION_HEIGHT) &&
    WORK_AMO_V8_ACTIVATION_HEIGHT > 0;
  const relationalRequiresWorkAmoV8 =
    relationalScopeIncludesWork &&
    workAmoV8BoundaryConfigured &&
    Number.isSafeInteger(relationalHeight) &&
    relationalHeight >= WORK_AMO_V8_ACTIVATION_HEIGHT;
  if (
    !relational || relational.summaryOnly === true || relationalItems === null ||
    relational?.stats?.complete !== true || relational?.collectionHasMore?.listings === true ||
    !Number.isSafeInteger(declaredTotal) || declaredTotal < 0 ||
    declaredTotal > TOKEN_LISTING_LIFECYCLE_MATERIALIZATION_LIMIT ||
    declaredTotal !== relationalItems.length ||
    !Number.isSafeInteger(relationalHeight) || relationalHeight < 1 ||
    !/^[0-9a-f]{64}$/u.test(relationalHash) ||
    (relationalScopeIncludesWork && !workAmoV8BoundaryConfigured) ||
    (relationalRequiresWorkAmoV8 &&
      (relational?.stats?.workMarketAuthorizationReady !== true ||
        !relationalWorkMarketAuthorizationVersions.includes(
          TOKEN_SALE_AUTH_WORK_AMO_V8_VERSION,
        )))
  ) {
    throw tokenListingHistoryUnavailable(
      "Complete checkpoint-bound relational token listings are unavailable.",
      { declaredTotal: Number.isSafeInteger(declaredTotal) ? declaredTotal : null,
        materializedCount: relationalItems?.length ?? null,
        workMarketAuthorizationReady:
          relational?.stats?.workMarketAuthorizationReady === true,
        workMarketAuthorizationVersions:
          relationalWorkMarketAuthorizationVersions,
        ...lifecycleCapacity },
    );
  }
  const canonicalWorkAmoV8ListingIds = new Set();
  const canonicalItems = await mapWithConcurrency(
    relationalItems,
    Math.min(4, Math.max(1, TX_FETCH_CONCURRENCY)),
    async (listing) => {
      const record = workAmoV8ListingHistoryRecord(listing);
      if (!record) {
        return listing;
      }
      const witness = await proofIndexCanonicalWorkListingById(
        network,
        record.listingId,
      );
      const version = String(witness?.version ?? "").trim().toLowerCase();
      if (
        witness?.valid !== true || witness?.confirmed !== true ||
        witness?.unspent !== true ||
        version !== TOKEN_SALE_AUTH_WORK_AMO_V8_VERSION ||
        !witness?.listingFrozenTerms ||
        !witness?.listingAuthorization
      ) {
        return listing;
      }
      canonicalWorkAmoV8ListingIds.add(record.listingId);
      return tokenListingWithCanonicalWorkAmoV8Witness(listing, witness);
    },
  );
  const authority = await strictCoreTokenListingReconciliation(
    canonicalItems, network, { requireAll: true },
  );
  const coreHeight = Number(authority?.evidence?.checkpoint?.height);
  const coreHash = String(authority?.evidence?.checkpoint?.blockHash ?? "").trim().toLowerCase();
  const coreDigest = String(authority?.evidence?.checkedOutpointsSha256 ?? "").trim().toLowerCase();
  const authorityListings = Array.isArray(authority?.listings)
    ? authority.listings
    : null;
  const coreInputCount = authority?.evidence?.inputListingCount;
  const coreOutputCount = authority?.evidence?.outputListingCount;
  const coreSpentCount = authority?.evidence?.spentListingCount;
  const coreUnspentCount = authority?.evidence?.unspentListingCount;
  if (
    !Number.isSafeInteger(coreHeight) || coreHeight < 1 ||
    !/^[0-9a-f]{64}$/u.test(coreHash) || !/^[0-9a-f]{64}$/u.test(coreDigest) ||
    authority?.evidence?.model !== "proof-token-market-core-gettxout-v1" ||
    authority?.evidence?.includeMempool !== true ||
    authority?.evidence?.checkedListingCount !== canonicalItems.length ||
    coreInputCount !== canonicalItems.length || authorityListings === null ||
    !Number.isSafeInteger(coreOutputCount) || coreOutputCount < 0 ||
    coreOutputCount !== authorityListings.length ||
    !Number.isSafeInteger(coreSpentCount) || coreSpentCount < 0 ||
    !Number.isSafeInteger(coreUnspentCount) || coreUnspentCount < 0 ||
    coreSpentCount + coreUnspentCount !== canonicalItems.length ||
    coreUnspentCount !== authorityListings.length ||
    coreHeight !== relationalHeight || coreHash !== relationalHash
  ) {
    throw tokenListingHistoryUnavailable("Complete Core token-listing evidence is unavailable.");
  }
  const unavailableActiveWorkAmoV8 = authorityListings
    .map((listing) => workAmoV8ListingHistoryRecord(listing))
    .find((record) =>
      record && !canonicalWorkAmoV8ListingIds.has(record.listingId));
  if (unavailableActiveWorkAmoV8) {
    throw tokenListingHistoryUnavailable(
      `Canonical AMO V8 listing evidence is unavailable for ${unavailableActiveWorkAmoV8.listingId}.`,
    );
  }
  const protocolAuthority = applyWorkMarketV2CutoverToTokenState({
    closedListings: [],
    indexedThroughBlock: relationalHeight,
    invalidEvents: [],
    listings: authorityListings,
    network,
    ...(relational.workMarketV4Activation
      ? { workMarketV4Activation: relational.workMarketV4Activation }
      : {}),
  });
  const protocolAuthorityListings = Array.isArray(protocolAuthority?.listings)
    ? protocolAuthority.listings
    : null;
  const authorityStableKeys = new Set(
    authorityListings.map((listing) =>
      checkpointCursorCanonicalJson(tokenListingHistoryStableKey(listing))),
  );
  const protocolAuthorityStableKeys = new Set(
    (protocolAuthorityListings ?? []).map((listing) =>
      checkpointCursorCanonicalJson(tokenListingHistoryStableKey(listing))),
  );
  if (
    protocolAuthorityListings === null ||
    authorityStableKeys.size !== authorityListings.length ||
    protocolAuthorityStableKeys.size !== protocolAuthorityListings.length ||
    protocolAuthorityListings.length > authorityListings.length ||
    [...protocolAuthorityStableKeys].some((key) => !authorityStableKeys.has(key))
  ) {
    throw tokenListingHistoryUnavailable(
      "Canonical protocol-active token-listing projection is unavailable.",
    );
  }
  const addresses = recoveryAddressesFromSearchParams(searchParams, network);
  const filtered = historyItemsMatchingQuery(
    historyItemsMatchingAddresses(protocolAuthorityListings, addresses), request.query,
  ).map((item) => ({ item, key: tokenListingHistoryStableKey(item) }))
    .sort((left, right) => compareCanonicalUtf8(
      checkpointCursorCanonicalJson(left.key), checkpointCursorCanonicalJson(right.key),
    ));
  const digest = (value) => createHash("sha256")
    .update(checkpointCursorCanonicalJson(value), "utf8").digest("hex");
  const filterFingerprint = digest({
    addresses: [...addresses].sort(compareCanonicalUtf8), network,
    query: request.query, scope: scope || "all",
  });
  const membershipSha256 = digest(filtered.map((entry) => ({
    item: entry.item,
    key: entry.key,
  })));
  const relationalEntries = canonicalItems.map((item) => ({
    item,
    key: tokenListingHistoryStableKey(item),
  })).sort((left, right) => compareCanonicalUtf8(
    checkpointCursorCanonicalJson(left.key), checkpointCursorCanonicalJson(right.key),
  ));
  const sourceSha256 = digest(relationalEntries);
  const protocolMembershipSha256 = digest(
    protocolAuthorityListings.map((item) => ({
      item,
      key: tokenListingHistoryStableKey(item),
    })).sort((left, right) => compareCanonicalUtf8(
      checkpointCursorCanonicalJson(left.key),
      checkpointCursorCanonicalJson(right.key),
    )),
  );
  const cursor = request.cursor;
  const emitted = cursor ? Number(cursor.emitted) : 0;
  if (cursor && !(
    cursor.v === 2 && cursor.network === network && cursor.scope === (scope || "all") &&
    cursor.filterFingerprint === filterFingerprint &&
    cursor.relationalHeight === relationalHeight && cursor.relationalHash === relationalHash &&
    cursor.relationalSourceSha256 === sourceSha256 && cursor.coreHeight === coreHeight &&
    cursor.coreHash === coreHash && cursor.coreEvidenceSha256 === coreDigest &&
    cursor.protocolMembershipSha256 === protocolMembershipSha256 &&
    cursor.membershipSha256 === membershipSha256 && cursor.total === filtered.length &&
    Number.isSafeInteger(emitted) && emitted > 0 && emitted <= filtered.length &&
    checkpointCursorCanonicalJson(cursor.last) ===
      checkpointCursorCanonicalJson(filtered[emitted - 1]?.key)
  )) {
    throw historyCursorConflict(
      "The token-listing history checkpoint changed; restart pagination.",
      { reason: "token-listing-checkpoint-changed" },
    );
  }
  const end = Math.min(filtered.length, emitted + request.limit);
  const pageEntries = filtered.slice(emitted, end);
  const hasMore = end < filtered.length;
  const nextCursor = hasMore ? encodedCheckpointCursor(TOKEN_LISTING_HISTORY_CURSOR_PREFIX, {
    coreEvidenceSha256: coreDigest, coreHash, coreHeight, emitted: end,
    filterFingerprint, last: pageEntries.at(-1).key, membershipSha256, network,
    protocolMembershipSha256,
    relationalHash, relationalHeight, relationalSourceSha256: sourceSha256,
    scope: scope || "all", total: filtered.length, v: 2,
  }) : "";
  return {
    cursor: request.cursorRaw, end, hasMore, indexedAt: relational.indexedAt,
    indexedThroughBlock: relationalHeight, indexedThroughBlockHash: relationalHash,
    items: pageEntries.map((entry) => entry.item), kind: "listings", limit: request.limit,
    listingAuthority: authority.evidence, network, nextCursor,
    listingProjection: {
      activeListingCount: protocolAuthorityListings.length,
      coreUnspentListingCount: authorityListings.length,
      excludedByProtocolCount:
        authorityListings.length - protocolAuthorityListings.length,
      membershipSha256: protocolMembershipSha256,
      model: "proof-token-market-cutover-after-core-v1",
    },
    page: Math.floor(emitted / request.limit),
    pageCount: Math.max(1, Math.ceil(filtered.length / request.limit)),
    pageSize: request.limit, query: request.query,
    snapshotId: digest({
      coreDigest,
      coreHash,
      membershipSha256,
      protocolMembershipSha256,
      relationalHash,
      sourceSha256,
    }),
    source: "proof-indexer-complete-core-reconciled-token-listings",
    start: emitted, totalCount: filtered.length,
  };
}

async function tokenHistoryPayload(network, tokenScope, kind, searchParams, fresh = false) {
  const scope = normalizeTokenScope(tokenScope);
  const strictRecoveryAddresses = recoveryAddressesFromSearchParams(
    searchParams,
    network,
  );
  const recoveryAddresses =
    strictRecoveryAddresses.length > 0
      ? strictRecoveryAddresses
      : recoveryAddressHintsFromSearchParams(searchParams, network);
  const recoveryTxids = recoveryTxidsFromSearchParams(searchParams);
  const pagination = historyPaginationFromSearch(searchParams);
  const kindMap = new Map([
    ["holders", "holders"],
    ["invalid", "invalidEvents"],
    ["invalid-events", "invalidEvents"],
    ["invalid_events", "invalidEvents"],
    ["invalidevents", "invalidEvents"],
    ["closedlistings", "closedListings"],
    ["closed-listings", "closedListings"],
    ["closed_listing", "closedListings"],
    ["closed-listing", "closedListings"],
    ["listings", "listings"],
    ["market-listings", "market-listings"],
    ["market-seals", "market-seals"],
    ["market-sales", "market-sales"],
    ["marketlog", "market-log"],
    ["market-log", "market-log"],
    ["market_log", "market-log"],
    ["tokenmarketlog", "market-log"],
    ["token-market-log", "market-log"],
    ["mints", "mints"],
    ["sales", "sales"],
    ["tokens", "tokens"],
    ["transfers", "transfers"],
  ]);
  const safeKind = kindMap.get(kind) ?? "mints";
  if (network === "livenet" && safeKind === "listings") {
    return completeTokenListingHistoryPayload(network, scope, searchParams);
  }
  if (
    network === "livenet" &&
    safeKind === "tokens" &&
    recoveryAddresses.length === 0 &&
    recoveryTxids.length === 0
  ) {
    return canonicalTokenDirectoryPayload(
      network,
      scope,
      pagination,
      fresh,
    );
  }
  const workMarketHistoryKind =
    safeKind === "sales" ||
    safeKind === "market-log" ||
    safeKind === "market-listings" ||
    safeKind === "market-seals" ||
    safeKind === "market-sales" ||
    safeKind === "closedListings" ||
    safeKind === "listings";
  const workBalanceHistoryKind =
    safeKind === "holders" || safeKind === "transfers";
  const queriedWorkHistory =
    scope === WORK_TOKEN_ID &&
    (Boolean(pagination.query) ||
      recoveryAddresses.length > 0 ||
      recoveryTxids.length > 0) &&
    (workMarketHistoryKind ||
      workBalanceHistoryKind ||
      safeKind === "invalidEvents");
  const queriedWorkSaleHistory =
    queriedWorkHistory &&
    (workMarketHistoryKind || safeKind === "invalidEvents");
  const freshWorkHolderHistory =
    fresh && scope === WORK_TOKEN_ID && safeKind === "holders";
  const scopedWorkMarketHistory =
    scope === WORK_TOKEN_ID &&
    workMarketHistoryKind &&
    recoveryAddresses.length > 0;
  const recoveryBondConfig = bondConfigForTokenId(scope);
  if (
    scope === WORK_TOKEN_ID &&
    network === "livenet" &&
    (workMarketHistoryKind || safeKind === "invalidEvents") &&
    (recoveryTxids.length > 0 || recoveryAddresses.length > 0)
  ) {
    const pendingMarketPage = await pendingWorkMarketHistoryPage(
      network,
      scope,
      safeKind,
      searchParams,
    ).catch((error) => {
      console.error(
        `Pending WORK market history recovery failed: ${errorSummary(error)}`,
      );
      return null;
    });
    if (pendingMarketPage) {
      return tokenMarketActivityHistoryPageWithAuthority(
        pendingMarketPage,
        safeKind,
        false,
      );
    }
  }
  if (
    workMarketHistoryKind &&
    safeKind !== "listings" &&
    queriedWorkHistory &&
    network === "livenet"
  ) {
    const indexedMarketPage = await payloadWithFallbackAfterMs(
      proofIndexTokenMarketHistoryOverlayPayload(
        network,
        scope,
        safeKind,
        searchParams,
        { pagination },
      ).catch((error) => {
        console.error(
          `Proof index fast WORK market history read failed: ${errorSummary(error)}`,
        );
        return null;
      }),
      null,
      SUMMARY_WORK_LISTING_RECOVERY_WAIT_MS,
    );
    if (
      indexedMarketPage &&
      (Number(indexedMarketPage.totalCount ?? 0) > 0 ||
        (indexedMarketPage.items ?? []).length > 0 ||
        isTerminalTokenMarketHistoryPage(indexedMarketPage))
    ) {
      return tokenMarketActivityHistoryPageWithAuthority(
        await tokenHistoryPageWithCanonicalCreditValueOverlay(
          indexedMarketPage,
          network,
          scope,
          safeKind,
          searchParams,
        ),
        safeKind,
        false,
      );
    }
  }
  if (
    workMarketHistoryKind &&
    recoveryBondConfig &&
    recoveryTxids.length > 0 &&
    network === "livenet"
  ) {
    const recoveryTxs = await confirmedTransactionsForTxids(
      recoveryTxids,
      network,
      recoveryTxids.length,
    );
    let recoveredPayload = await recoveredBondTokenPayloadFromTransactions(
      network,
      recoveryTxs,
      recoveryBondConfig,
    ).catch((error) => {
      console.error(
        `Recovered ${recoveryBondConfig.ticker} market history lookup failed: ${errorSummary(error)}`,
      );
      return null;
    });
    if (recoveredPayload && safeKind === "listings") {
      recoveredPayload = await tokenPayloadWithSpendableListings(
        recoveredPayload,
        network,
      );
    }
    const directItems =
      safeKind === "market-log"
        ? tokenMarketLogItemsFromState(recoveredPayload)
        : ["market-listings", "market-seals", "market-sales"].includes(safeKind)
          ? tokenMarketHistoryItemsFromState(recoveredPayload, safeKind)
          : (recoveredPayload?.[safeKind] ?? []);
    const scopedDirectItems = historyItemsMatchingAddresses(
      directItems,
      recoveryAddresses,
    );
    if (scopedDirectItems.length > 0) {
      return tokenMarketActivityHistoryPageWithAuthority(
        paginatedHistoryPayload({
          indexedAt: recoveredPayload.indexedAt ?? new Date().toISOString(),
          items: scopedDirectItems,
          kind: safeKind,
          network,
          pagination,
          source: recoveredPayload.source,
        }),
        safeKind,
        false,
      );
    }
  }
  if (
    scope === WORK_TOKEN_ID &&
    recoveryTxids.length > 0 &&
    network === "livenet" &&
    (safeKind === "transfers" || safeKind === "invalidEvents")
  ) {
    const recoveryTxs = await confirmedTransactionsForTxids(
      recoveryTxids,
      network,
      recoveryTxids.length,
    );
    const recoveredTransfers = workTransfersFromTransactions(
      recoveryTxs,
      network,
    );
    const scopedTransfers = historyItemsMatchingAddresses(
      recoveredTransfers,
      recoveryAddresses,
    );
    if (scopedTransfers.length > 0) {
      return paginatedHistoryPayload({
        indexedAt: new Date().toISOString(),
        items: safeKind === "transfers" ? scopedTransfers : [],
        kind: safeKind,
        network,
        pagination,
        source: "first-party-work-transfer-txid-recovery",
      });
    }
  }
  if (
    scope === WORK_TOKEN_ID &&
    recoveryAddresses.length > 0 &&
    network === "livenet" &&
    safeKind === "transfers"
  ) {
    const recoveredTransfers = await recoveredWorkTransfersForAddresses(
      recoveryAddresses,
      network,
    );
    if (recoveredTransfers.length > 0) {
      return paginatedHistoryPayload({
        indexedAt: new Date().toISOString(),
        items: recoveredTransfers,
        kind: safeKind,
        network,
        pagination,
        source: "first-party-work-transfer-address-recovery",
      });
    }
  }
  if (
    scope === WORK_TOKEN_ID &&
    recoveryTxids.length > 0 &&
    network === "livenet" &&
    safeKind === "invalidEvents"
  ) {
    const recoveryTxs = await confirmedTransactionsForTxids(
      recoveryTxids,
      network,
      recoveryTxids.length,
    );
    const recoveredPayload = await recoveredWorkMarketPayloadFromTransactions(
      network,
      recoveryTxs,
    ).catch((error) => {
      console.error(
        `Recovered WORK market invalid-event lookup failed: ${errorSummary(error)}`,
      );
      return null;
    });
    const marketItems = tokenMarketLogItemsFromState(recoveredPayload);
    const hasRecoveredValidMarketEvent = marketItems.some((item) =>
      recoveryTxids.some(
        (txid) =>
          item?.txid === txid ||
          item?.listing?.sealTxid === txid ||
          item?.listing?.closedTxid === txid ||
          item?.sale?.txid === txid,
      ),
    );
    if (hasRecoveredValidMarketEvent) {
      return paginatedHistoryPayload({
        indexedAt: recoveredPayload.indexedAt ?? new Date().toISOString(),
        items: [],
        kind: safeKind,
        network,
        pagination,
        source: recoveredPayload.source,
      });
    }
  }
  if (
    workMarketHistoryKind &&
    scope === WORK_TOKEN_ID &&
    recoveryTxids.length > 0 &&
    network === "livenet"
  ) {
    const recoveryTxs = await confirmedTransactionsForTxids(
      recoveryTxids,
      network,
      recoveryTxids.length,
    );
    if (recoveryTxs.length > 0) {
      let recoveredPayload = {
        ...emptyTokenPayloadSnapshot(network),
        indexedAt: new Date().toISOString(),
        source: "first-party-token-txid-recovery",
      };
      if (safeKind === "listings") {
        recoveredPayload = tokenStateWithPreservedListingRecords(
          recoveredPayload,
          {
            listings: workActiveListingsFromTransactions(
              recoveryTxs,
              network,
              recoveryAddresses,
            ),
          },
        );
      } else {
        recoveredPayload = workTokenStateWithRecoveredListingsFromTransactions(
          recoveredPayload,
          recoveryTxs,
          network,
        );
      }
      recoveredPayload = workTokenStateWithRecoveredListingSeals(
        recoveredPayload,
        recoveryTxs,
        network,
      );
      recoveredPayload = workTokenStateWithRecoveredListingClosesFromTransactions(
        recoveredPayload,
        recoveryTxs,
        network,
      );
      recoveredPayload = await tokenPayloadWithSpendableListings(
        recoveredPayload,
        network,
      );
      const directItems =
        safeKind === "market-log"
          ? tokenMarketLogItemsFromState(recoveredPayload)
          : ["market-listings", "market-seals", "market-sales"].includes(
                safeKind,
              )
            ? tokenMarketHistoryItemsFromState(recoveredPayload, safeKind)
            : safeKind === "listings"
              ? activeTokenListingsFromState(recoveredPayload)
              : (recoveredPayload[safeKind] ?? []);
      const scopedDirectItems = historyItemsMatchingAddresses(
        directItems,
        recoveryAddresses,
      );
      if (safeKind !== "listings" && scopedDirectItems.length > 0) {
        return tokenMarketActivityHistoryPageWithAuthority(
          paginatedHistoryPayload({
            indexedAt: recoveredPayload.indexedAt ?? new Date().toISOString(),
            items: scopedDirectItems,
            kind: safeKind,
            network,
            pagination,
            source: recoveredPayload.source,
          }),
          safeKind,
          false,
        );
      }
    }
  }
  if (
    safeKind === "listings" &&
    scopedWorkMarketHistory &&
    network === "livenet"
  ) {
    const recoveredPayload = await workTokenStateWithIndexedActiveListings(
      emptyTokenPayloadSnapshot(network),
      network,
      recoveryAddresses,
    );
    const recoveredItems = historyItemsMatchingAddresses(
      recoveredPayload?.listings ?? [],
      recoveryAddresses,
    );
    if (recoveredItems.length > 0) {
      return paginatedHistoryPayload({
        indexedAt: recoveredPayload.indexedAt ?? new Date().toISOString(),
        items: recoveredItems,
        kind: safeKind,
        network,
        pagination,
        source:
          recoveredPayload.source ??
          "proof-indexer-token-listing-tx-recovery",
      });
    }
  }
  if (
    safeKind === "listings" &&
    queriedWorkHistory &&
    network === "livenet" &&
    recoveryAddresses.length === 0
  ) {
    const directListingPage = await workActiveListingHistoryPageFromTxidQuery(
      network,
      pagination.query,
      pagination,
    );
    if (directListingPage) {
      return directListingPage;
    }
  }
  if (
    workMarketHistoryKind &&
    safeKind !== "listings" &&
    queriedWorkHistory &&
    network === "livenet" &&
    recoveryAddresses.length === 0 &&
    pagination.query
  ) {
    const indexedHistoryPage = await payloadWithFallbackAfterMs(
      proofIndexTokenHistoryPayload(
        network,
        scope,
        safeKind,
        searchParams,
      ).catch((error) => {
        console.error(
          `Proof index queried WORK market history read failed: ${errorSummary(error)}`,
        );
        return null;
      }),
      null,
      SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    );
    if (
      indexedHistoryPage &&
      (Number(indexedHistoryPage.totalCount ?? 0) > 0 ||
        (indexedHistoryPage.items ?? []).length > 0 ||
        isTerminalTokenMarketHistoryPage(indexedHistoryPage))
    ) {
      return tokenMarketActivityHistoryPageWithAuthority(
        await tokenHistoryPageWithCanonicalCreditValueOverlay(
          indexedHistoryPage,
          network,
          scope,
          safeKind,
          searchParams,
        ),
        safeKind,
        false,
      );
    }
  }
  const indexedWorkHolderOverlayPromise =
    safeKind === "holders" && queriedWorkHistory && network === "livenet"
      ? proofIndexWalletTokenOverlayPayload(
          network,
          scope,
          recoveryAddresses,
        ).catch((error) => {
          console.error(
            `Proof index WORK holder overlay failed: ${errorSummary(error)}`,
          );
          return null;
        })
      : Promise.resolve(null);
  if (
    safeKind === "listings" &&
    scopedWorkMarketHistory &&
    network === "livenet"
  ) {
    const recoveredPayload = await workTokenStateWithIndexedActiveListings(
      emptyTokenPayloadSnapshot(network),
      network,
      recoveryAddresses,
    );
    const recoveredItems = historyItemsMatchingAddresses(
      recoveredPayload?.listings ?? [],
      recoveryAddresses,
    );
    if (recoveredItems.length > 0) {
      return paginatedHistoryPayload({
        indexedAt: recoveredPayload.indexedAt ?? new Date().toISOString(),
        items: recoveredItems,
        kind: safeKind,
        network,
        pagination,
        source:
          recoveredPayload.source ??
          "proof-indexer-token-listing-tx-recovery",
      });
    }
  }
  if (
    safeKind === "holders" &&
    queriedWorkHistory &&
    recoveryAddresses.length > 0 &&
    network === "livenet"
  ) {
    const walletPayload = await walletScopedTokenPayload(
      network,
      scope,
      recoveryAddresses,
    ).catch((error) => {
      console.error(
        `Wallet-scoped WORK holder history recovery failed: ${errorSummary(error)}`,
      );
      return null;
    });
    const walletHolderItems = historyItemsMatchingAddresses(
      walletPayload?.holders ?? [],
      recoveryAddresses,
    );
    if (walletHolderItems.length > 0) {
      return paginatedHistoryPayload({
        indexedAt: walletPayload.indexedAt ?? new Date().toISOString(),
        items: walletHolderItems,
        kind: safeKind,
        network,
        pagination,
        source: mergedSourceLabel(
          walletPayload.source,
          "wallet-scoped-holder-recovery",
        ),
      });
    }
  }
  let payload = await tokenPayloadForRead(
    network,
    scope,
    fresh || scopedWorkMarketHistory,
    {
    forceRefresh:
      (workBalanceHistoryKind && (queriedWorkHistory || freshWorkHolderHistory)) ||
      scopedWorkMarketHistory,
    fullRefreshWaitMs: WORK_TOKEN_LIVE_RECOVERY_WAIT_MS,
    reconcileListingStatus: false,
    reconcileSpendable: false,
    recoveryAddresses,
    recoveryTxids,
    useLedgerSnapshot:
      (workBalanceHistoryKind && (queriedWorkHistory || freshWorkHolderHistory)) ||
      scopedWorkMarketHistory
        ? false
        : undefined,
    liveWorkWaitMs: queriedWorkHistory || freshWorkHolderHistory || scopedWorkMarketHistory
      ? WORK_TOKEN_LIVE_RECOVERY_WAIT_MS
      : recoveryAddresses.length > 0
        ? TOKEN_ADDRESS_HINT_LIVE_WAIT_MS
        : undefined,
    recoverWorkSalesOnly: queriedWorkSaleHistory,
    },
  );
  if (workMarketHistoryKind) {
    if (scope === WORK_TOKEN_ID && recoveryTxids.length > 0) {
      const recoveryTxs = await confirmedTransactionsForTxids(
        recoveryTxids,
        network,
        recoveryTxids.length,
      );
      let recoveredPayload = workTokenStateWithRecoveredListingsFromTransactions(
        payload,
        recoveryTxs,
        network,
      );
      recoveredPayload = workTokenStateWithRecoveredListingSeals(
        recoveredPayload,
        recoveryTxs,
        network,
      );
      recoveredPayload = workTokenStateWithRecoveredListingClosesFromTransactions(
        recoveredPayload,
        recoveryTxs,
        network,
      );
      recoveredPayload = await workTokenStateWithRecoveredListingCloseSales(
        recoveredPayload,
        network,
      );
      if (recoveredPayload !== payload) {
        payload = recoveredPayload;
        cacheExplicitWorkTokenCloseRecoveryTxs(network, recoveryTxs);
        cacheLiveWorkTokenState(network, payload);
        syncWorkTokenLiveSeenTxids(network, payload);
      }
    }
    const scopeMarketItems = (items) =>
      historyItemsMatchingAddresses(items ?? [], recoveryAddresses);
    const marketPayload =
      recoveryAddresses.length > 0
        ? {
            ...payload,
            closedListings: scopeMarketItems(payload.closedListings),
            listings: scopeMarketItems(payload.listings),
            sales: scopeMarketItems(payload.sales),
          }
        : payload;
    payload = await tokenPayloadWithSpendableListings(marketPayload, network);
  }
  const rawItems =
    safeKind === "market-log"
      ? tokenMarketLogItemsFromState(payload)
      : ["market-listings", "market-seals", "market-sales"].includes(safeKind)
        ? tokenMarketHistoryItemsFromState(payload, safeKind)
        : safeKind === "listings"
          ? activeTokenListingsFromState(payload)
          : (payload[safeKind] ?? []);
  const items = historyItemsMatchingAddresses(rawItems, recoveryAddresses);

  let page = paginatedHistoryPayload({
    indexedAt: payload.indexedAt ?? new Date().toISOString(),
    items,
    kind: safeKind,
    network,
    pagination,
    source: payload.source ?? mempoolBase(network),
  });
  if (workBalanceHistoryKind && queriedWorkHistory && network === "livenet") {
    const overlayPage = await payloadWithFallbackAfterMs(
      proofIndexTokenHistoryPayload(
        network,
        scope,
        safeKind,
        searchParams,
      ).catch((error) => {
        console.error(
          `Proof index token balance overlay failed: ${errorSummary(error)}`,
        );
        return null;
      }),
      null,
      SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    );
    page = mergeTokenHistoryPageWithOverlay(page, overlayPage, pagination);
    if (safeKind === "holders") {
      const indexedWalletOverlay = await indexedWorkHolderOverlayPromise;
      const indexedHolderItems = (Array.isArray(indexedWalletOverlay?.holders)
        ? indexedWalletOverlay.holders
        : []
      ).filter(
        (holder) =>
          tokenMatchesScope(holder, scope) &&
          recoveryAddresses.some(
            (address) =>
              String(holder?.address ?? "").toLowerCase() ===
              String(address ?? "").toLowerCase(),
          ),
      );
      if (indexedHolderItems.length > 0) {
        page = mergeTokenHistoryPageWithOverlay(
          page,
          paginatedHistoryPayload({
            indexedAt:
              indexedWalletOverlay.indexedAt ?? new Date().toISOString(),
            items: indexedHolderItems,
            kind: safeKind,
            network,
            pagination,
            source: indexedWalletOverlay.source ?? "proof-indexer-wallet-overlay",
          }),
          pagination,
        );
      }
    }
  }
  if (workMarketHistoryKind && queriedWorkHistory && network === "livenet") {
    const overlayPage = await payloadWithFallbackAfterMs(
      proofIndexTokenHistoryPayload(
        network,
        scope,
        safeKind,
        searchParams,
      ).catch((error) => {
        console.error(
          `Proof index token market history overlay failed: ${errorSummary(error)}`,
        );
        return null;
      }),
      null,
      SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    );
    page = mergeTokenHistoryPageWithOverlay(page, overlayPage, pagination, {
      addOverlayItems: safeKind !== "listings",
    });
  }
  if (workMarketHistoryKind && network === "livenet") {
    const overlayPage = await payloadWithFallbackAfterMs(
      proofIndexTokenMarketHistoryOverlayPayload(
        network,
        scope,
        safeKind,
        searchParams,
      ).catch((error) => {
        console.error(
          `Proof index token market overlay failed: ${errorSummary(error)}`,
        );
        return null;
      }),
      null,
      SUMMARY_PROOF_INDEX_READ_WAIT_MS,
    );
    page = mergeTokenHistoryPageWithOverlay(page, overlayPage, pagination, {
      addOverlayItems: safeKind !== "listings",
    });
  }
  const authorityPage =
    safeKind === "listings" && payload?.listingAuthority
      ? { ...page, listingAuthority: payload.listingAuthority }
      : page;
  return tokenMarketActivityHistoryPageWithAuthority(
    payload.snapshotId
      ? {
          ...authorityPage,
          consistency: payload.consistency,
          ledgerGeneratedAt: payload.ledgerGeneratedAt,
          snapshotId: payload.snapshotId,
        }
      : authorityPage,
    safeKind,
    false,
  );
}

function growthElapsedYears() {
  return Math.max(0, (Date.now() - GROWTH_MODEL_START_MS) / MS_PER_MODEL_YEAR);
}

function growthBtcUsdAtYears(years) {
  const mu =
    Math.log(
      GROWTH_MODEL_INPUTS.currentBtcUsd / GROWTH_MODEL_INPUTS.historicalBtcUsd,
    ) / GROWTH_MODEL_INPUTS.btcBenchmarkYears;
  return GROWTH_MODEL_INPUTS.currentBtcUsd * Math.exp(mu * Math.max(0, years));
}

function growthSatsToUsdAtYears(sats, years) {
  return (sats / 100_000_000) * growthBtcUsdAtYears(years);
}

function satsToUsdAtBtcUsd(sats, btcUsd) {
  return (sats / 100_000_000) * btcUsd;
}

function btcUsdFromQuote(quote) {
  const usd = Number(quote?.usd ?? quote?.USD);
  return Number.isFinite(usd) && usd > 0 ? usd : 0;
}

function btcUsdResponseMetadata(quote) {
  const btcUsd = btcUsdFromQuote(quote);
  const metadata = {
    btcUsd,
    btcUsdIndexedAt: quote?.priceIndexedAt,
    usdSource: quote?.source,
    usdSourceUrl: quote?.sourceUrl,
  };
  if (quote?.sourceError) {
    metadata.usdSourceError = quote.sourceError;
  }
  return metadata;
}

function isBrowserActivityItem(item) {
  const tags = Array.isArray(item.tags) ? item.tags : [];
  const searchText = [
    item.title,
    item.detail,
    item.description,
    ...tags,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
  const hasHtmlAttachment =
    searchText.includes("text/html") ||
    searchText.includes("application/xhtml+xml") ||
    /\.x?html?\b/u.test(searchText);
  const hasHtmlBody =
    tags.some((tag) => String(tag).toLowerCase() === "html body") ||
    isBrowserHtmlMessageBody(item.detail ?? "");

  if (item.kind === "file") {
    return hasHtmlAttachment;
  }

  if (item.kind === "mail" || item.kind === "reply") {
    return hasHtmlBody;
  }

  return false;
}

function activityAmountSats(item) {
  const amount = Number(item?.amountSats ?? 0);
  return Number.isFinite(amount) && amount > 0 ? amount : 0;
}

function activityAmountSatsBigInt(item) {
  const amount = proofFlowBigInt(item?.amountSats);
  return amount > 0n ? amount : 0n;
}

function marketplaceMutationPaymentSats(item) {
  for (const value of [
    item?.marketplaceMutationFeeSats,
    item?.amountSats,
    item?.totalSats,
  ]) {
    const sats = numericValue(value);
    if (sats > 0) {
      return sats;
    }
  }
  return 0;
}

function marketplaceMutationPaymentSatsBigInt(item) {
  for (const value of [
    item?.marketplaceMutationFeeSats,
    item?.amountSats,
    item?.totalSats,
  ]) {
    const sats = proofFlowBigInt(value);
    if (sats > 0n) {
      return sats;
    }
  }
  return 0n;
}

function marketplaceMutationPaymentIdentity(item) {
  const kind = String(item?.kind ?? "");
  if (!MARKETPLACE_MUTATION_KINDS.has(kind)) {
    return "";
  }
  const txid = String(item?.txid ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(txid)) {
    return "";
  }
  const family = ID_MARKETPLACE_MUTATION_KINDS.has(kind) ? "id" : "token";
  const registryAddress = String(
    item?.registryAddress ??
      item?.saleAuthorization?.registryAddress ??
      (family === "token" ? item?.counterparty : "") ??
      "",
  )
    .trim()
    .toLowerCase();
  return `${family}:${txid}:${registryAddress}`;
}

function uniqueMarketplaceMutationActivity(
  activity,
  kinds = MARKETPLACE_MUTATION_KINDS,
) {
  const selected = (Array.isArray(activity) ? activity : []).filter(
    (item) => item?.valid !== false && kinds.has(item?.kind),
  );
  const registriesByPayment = new Map();
  for (const item of selected) {
    const identity = marketplaceMutationPaymentIdentity(item);
    const separator = identity.lastIndexOf(":");
    if (separator <= 0 || separator === identity.length - 1) {
      continue;
    }
    const payment = identity.slice(0, separator);
    const registryAddress = identity.slice(separator + 1);
    const registries = registriesByPayment.get(payment) ?? new Set();
    registries.add(registryAddress);
    registriesByPayment.set(payment, registries);
  }

  const unique = [];
  const indexByPayment = new Map();
  for (const item of selected) {
    let identity = marketplaceMutationPaymentIdentity(item);
    const separator = identity.lastIndexOf(":");
    if (separator > 0 && separator === identity.length - 1) {
      const payment = identity.slice(0, separator);
      const registries = registriesByPayment.get(payment);
      if (registries?.size === 1) {
        identity = `${payment}:${[...registries][0]}`;
      } else {
        identity = "";
      }
    }
    if (!identity) {
      unique.push(item);
      continue;
    }
    const currentIndex = indexByPayment.get(identity);
    if (currentIndex === undefined) {
      indexByPayment.set(identity, unique.length);
      unique.push(item);
      continue;
    }
    if (
      marketplaceMutationPaymentSatsBigInt(item) >
      marketplaceMutationPaymentSatsBigInt(unique[currentIndex])
    ) {
      unique[currentIndex] = item;
    }
  }
  return unique;
}

function marketplaceMutationPaymentFlowSats(
  activity,
  kinds = MARKETPLACE_MUTATION_KINDS,
) {
  return uniqueMarketplaceMutationActivity(activity, kinds).reduce(
    (total, item) => total + marketplaceMutationPaymentSats(item),
    0,
  );
}

function activityKindHasDedicatedGrowthBucket(item) {
  if (isBrowserActivityItem(item) || isBondActivityItem(item)) {
    return true;
  }

  return (
    BOOST_EVENT_KINDS.has(item.kind) ||
    MARKETPLACE_MUTATION_KINDS.has(item.kind) ||
    item.kind === "mail" ||
    item.kind === "reply" ||
    item.kind === "file" ||
    item.kind === "token-create" ||
    item.kind === "token-mint" ||
    item.kind === "token-transfer" ||
    item.kind === "token-sale"
  );
}

function creditMovementIdentity(item, kind) {
  const text = (value) => String(value ?? "").trim().toLowerCase();
  const blockHeight =
    item?.blockHeight !== undefined &&
    item?.blockHeight !== null &&
    item?.blockHeight !== "" &&
    Number.isSafeInteger(Number(item.blockHeight)) &&
    Number(item.blockHeight) >= 1
      ? Number(item.blockHeight)
      : null;
  const legacyPositionExempt =
    item?.relic === true || item?.canonicalSynthetic === true;
  if (
    item?.confirmed === true &&
    blockHeight === null &&
    !legacyPositionExempt
  ) {
    throw new Error("Confirmed credit movement position is incomplete.");
  }
  const canonicalPosition =
    item?.confirmed === true &&
      blockHeight !== null &&
      blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT
      ? canonicalTokenReplayPosition(item)
      : null;
  if (canonicalPosition) {
    return [
      text(item?.network),
      text(item?.txid),
      "v5",
      canonicalPosition.blockHeight,
      canonicalPosition.blockIndex,
      canonicalPosition.protocolVout,
      canonicalPosition.recordOrdinal,
    ].join(":");
  }
  const identity = canonicalPosition
    ? [
        "event",
        canonicalPosition.blockHeight,
        canonicalPosition.blockIndex,
        canonicalPosition.protocolVout,
        canonicalPosition.recordOrdinal,
      ].join(":")
    : text(
        item?._powEventIndex ??
          item?.eventKeyVout ??
          item?.protocolVout ??
          item?.eventId,
      );
  return [
    text(kind),
    text(item?.tokenId),
    text(item?.txid),
    numericValue(item?.amount),
    text(
      item?.senderAddress ?? item?.minterAddress ?? item?.buyerAddress,
    ),
    text(item?.recipientAddress ?? item?.sellerAddress),
    text(item?.listingId),
    identity,
  ].join(":");
}

function creditReplayRecordIdentity(item) {
  const txid = String(item?.txid ?? "").trim().toLowerCase();
  const blockHeight =
    item?.blockHeight !== undefined &&
    item?.blockHeight !== null &&
    item?.blockHeight !== "" &&
    Number.isSafeInteger(Number(item.blockHeight)) &&
    Number(item.blockHeight) >= 1
      ? Number(item.blockHeight)
      : null;
  const legacyPositionExempt =
    item?.relic === true || item?.canonicalSynthetic === true;
  if (
    item?.confirmed === true &&
    blockHeight === null &&
    !legacyPositionExempt
  ) {
    throw new Error("Confirmed credit replay position is incomplete.");
  }
  if (
    item?.confirmed === true &&
    blockHeight !== null &&
    blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT
  ) {
    const position = canonicalTokenReplayPosition(item);
    return [
      String(item?.network ?? "").trim().toLowerCase(),
      txid,
      "v5",
      position.blockHeight,
      position.blockIndex,
      position.protocolVout,
      position.recordOrdinal,
    ].join(":");
  }
  return txid ? `tx:${txid}` : "";
}

function unbucketedConfirmedComputerLogFlowSats(confirmedActivity) {
  return confirmedActivity
    .filter((item) => !activityKindHasDedicatedGrowthBucket(item))
    .reduce((total, item) => total + activityAmountSats(item), 0);
}

function confirmedActivityFlowSats(confirmedActivity, kinds) {
  const selected = confirmedActivity.filter(
    (item) => item?.valid !== false && kinds.has(item.kind),
  );
  const nonMarketplaceFlowSats = selected
    .filter((item) => !MARKETPLACE_MUTATION_KINDS.has(item.kind))
    .reduce((total, item) => total + activityAmountSats(item), 0);
  return (
    nonMarketplaceFlowSats +
    marketplaceMutationPaymentFlowSats(selected, kinds)
  );
}

function tokenCanUseCreditNetworkFloor(token) {
  return (
    String(token?.tokenId ?? "").trim().toLowerCase() === WORK_TOKEN_ID
  );
}

function creditValueEventMs(item) {
  const ms = Date.parse(item?.createdAt ?? "");
  return Number.isFinite(ms) ? ms : Date.now();
}

function creditValueEventPosition(item) {
  if (item?.confirmed === true) {
    const explicitLegacyReplay =
      item?.relic === true || item?.canonicalSynthetic === true;
    const blockHeightAbsent =
      item?.blockHeight === undefined ||
      item?.blockHeight === null ||
      item?.blockHeight === "";
    if (explicitLegacyReplay && blockHeightAbsent) {
      return null;
    }
    return canonicalTokenReplayPosition(item);
  }
  const exactNonNegativeInteger = (value, minimum) =>
    value !== undefined &&
    value !== null &&
    value !== "" &&
    Number.isSafeInteger(Number(value)) &&
    Number(value) >= minimum
      ? Number(value)
      : null;
  const blockHeight = exactNonNegativeInteger(item?.blockHeight, 1);
  const blockIndex = exactNonNegativeInteger(item?.blockIndex, 0);
  const protocolVout = exactNonNegativeInteger(item?.protocolVout, 0);
  const recordOrdinal = exactNonNegativeInteger(item?.recordOrdinal, 0);
  return blockHeight !== null &&
    blockIndex !== null &&
    protocolVout !== null &&
    recordOrdinal !== null
    ? { blockHeight, blockIndex, protocolVout, recordOrdinal }
    : null;
}

function creditValueEventHeight(item) {
  return creditValueEventPosition(item)?.blockHeight ??
    Number.MAX_SAFE_INTEGER;
}

function creditValueEventIndex(item) {
  return creditValueEventPosition(item)?.blockIndex ??
    Number.MAX_SAFE_INTEGER;
}

function compareCreditValueReplayEvents(left, right) {
  const leftPosition = creditValueEventPosition(left.source);
  const rightPosition = creditValueEventPosition(right.source);
  if (leftPosition && rightPosition) {
    const positionComparison =
      leftPosition.blockHeight - rightPosition.blockHeight ||
      leftPosition.blockIndex - rightPosition.blockIndex ||
      leftPosition.protocolVout - rightPosition.protocolVout ||
      leftPosition.recordOrdinal - rightPosition.recordOrdinal;
    if (positionComparison !== 0) {
      return positionComparison;
    }
    if (
      leftPosition.blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT ||
      rightPosition.blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT
    ) {
      return 0;
    }
    return (
      left.order - right.order ||
      compareCanonicalUtf8(left.txid, right.txid)
    );
  }
  if (leftPosition || rightPosition) {
    return leftPosition ? -1 : 1;
  }
  return (
    left.createdMs - right.createdMs ||
    left.order - right.order ||
    compareCanonicalUtf8(left.txid, right.txid)
  );
}

function assertUniqueCreditValueReplayPositions(events) {
  const seen = new Set();
  for (const event of Array.isArray(events) ? events : []) {
    if (event?.source?.confirmed !== true) {
      continue;
    }
    const position = creditValueEventPosition(event.source);
    if (
      !position ||
      position.blockHeight < WORK_AMO_V5_ACTIVATION_HEIGHT
    ) {
      continue;
    }
    const key = [
      position.blockHeight,
      position.blockIndex,
      position.protocolVout,
      position.recordOrdinal,
    ].join(":");
    if (seen.has(key)) {
      throw new Error(
        "Canonical AMO V5 credit replay position is duplicated.",
      );
    }
    seen.add(key);
  }
  return events;
}

function growthActualBaseNetworkValueBeforeCanonicalItem(
  source,
  collections,
  createdMs,
  timestampProvider,
) {
  const positionedLivenet =
    source?.confirmed === true &&
    source?.network === "livenet" &&
    Number.isSafeInteger(Number(source?.blockHeight)) &&
    Number(source.blockHeight) > 0 &&
    Number.isSafeInteger(Number(source?.blockIndex)) &&
    Number(source.blockIndex) >= 0;
  if (!positionedLivenet) {
    return numericValue(timestampProvider(createdMs - 1));
  }
  const before = (items) =>
    (Array.isArray(items) ? items : []).filter((item) =>
      canonicalItemPrecedesBondTransaction(item, source),
    );
  return numericValue(
    growthActualBaseNetworkValue(
      before(collections.records),
      before(collections.idActivity),
      before(collections.sales),
      before(collections.tokenDefinitions),
      before(collections.tokenMints),
      before(collections.tokenTransfers),
      before(collections.tokenSales),
      Number.MAX_SAFE_INTEGER,
    ).totalSats,
  );
}

function growthActualBaseNetworkValueBeforeCanonicalItemProvider(
  collections,
  timestampProvider,
  diagnostics = null,
) {
  const buildStartedAt = Date.now();
  if (diagnostics && typeof diagnostics === "object") {
    for (const field of [
      "allHashLookups",
      "blockHashFallbacks",
      "canonicalPositions",
      "canonicalRows",
      "canonicalValueEvents",
      "cursorResets",
      "exactHashLookups",
      "invalidCreatedAtRows",
      "lookups",
      "prefixBuildMs",
      "prefixLookups",
      "providerBuilds",
      "sameTxAdjustments",
      "sameTxFallbacks",
      "slowFallbacks",
      "timestampLookups",
    ]) {
      if (!Number.isFinite(Number(diagnostics[field]))) {
        diagnostics[field] = 0;
      }
    }
  }
  const incrementDiagnostic = (field, amount = 1) => {
    if (!diagnostics || typeof diagnostics !== "object") {
      return;
    }
    diagnostics[field] = numericValue(diagnostics[field]) + amount;
  };
  incrementDiagnostic("providerBuilds");
  const collectionNames = [
    "records",
    "idActivity",
    "sales",
    "tokenDefinitions",
    "tokenMints",
    "tokenTransfers",
    "tokenSales",
  ];
  const canonicalPositionKeys = new Set();
  const exactPositionInteger = (value, minimum = 0) =>
    value !== undefined &&
    value !== null &&
    value !== "" &&
    Number.isSafeInteger(Number(value)) &&
    Number(value) >= minimum
      ? Number(value)
      : null;
  const canonicalValuePosition = (value) => {
    const source = value?.source ?? value;
    const blockHeight = exactPositionInteger(
      value?.blockHeight ?? source?.blockHeight,
      1,
    );
    const blockIndex = exactPositionInteger(
      value?.blockIndex ?? source?.blockIndex,
    );
    if (blockHeight === null || blockIndex === null) {
      return null;
    }
    const v5 = blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT;
    const protocolVout = exactPositionInteger(
      value?.protocolVout ?? source?.protocolVout,
    );
    const recordOrdinal = exactPositionInteger(
      value?.recordOrdinal ?? source?.recordOrdinal,
    );
    if (v5 && (protocolVout === null || recordOrdinal === null)) {
      throw new Error(
        "Canonical AMO V5 network-value event position is incomplete.",
      );
    }
    return {
      blockHeight,
      blockIndex,
      protocolVout:
        protocolVout ?? Number.MAX_SAFE_INTEGER,
      recordOrdinal:
        recordOrdinal ?? Number.MAX_SAFE_INTEGER,
      v5,
    };
  };
  const compareValuePositions = (left, right) =>
    left.blockHeight - right.blockHeight ||
    left.blockIndex - right.blockIndex ||
    (left.v5 || right.v5
      ? left.protocolVout - right.protocolVout ||
        left.recordOrdinal - right.recordOrdinal
      : 0);

  for (const name of collectionNames) {
    for (const item of Array.isArray(collections?.[name])
      ? collections[name]
      : []) {
      if (item?.confirmed !== true) {
        continue;
      }
      const position = canonicalValuePosition(item);
      if (!position) {
        continue;
      }
      if (!Number.isFinite(Date.parse(item?.createdAt ?? ""))) {
        // The legacy exact scan also drops these rows in
        // growthActualBaseNetworkValue's timestamp cutoff. Keeping them out
        // of the prefix is therefore exact, not an inferred timestamp.
        incrementDiagnostic("invalidCreatedAtRows");
        continue;
      }
      incrementDiagnostic("canonicalRows");
      canonicalPositionKeys.add(
        position.v5
          ? [
              position.blockHeight,
              position.blockIndex,
              position.protocolVout,
              position.recordOrdinal,
            ].join(":")
          : `${position.blockHeight}:${position.blockIndex}`,
      );
    }
  }

  const canonicalEvents = growthActualBaseNetworkValueEvents(
    collections?.records,
    collections?.idActivity,
    collections?.sales,
    collections?.tokenDefinitions,
    collections?.tokenMints,
    collections?.tokenTransfers,
    collections?.tokenSales,
  ).filter(
    (event) => canonicalValuePosition(event) !== null,
  );
  const eventsByHeight = new Map();
  const eventsByTxid = new Map();
  for (const event of canonicalEvents) {
    if (!eventsByHeight.has(event.blockHeight)) {
      eventsByHeight.set(event.blockHeight, []);
    }
    eventsByHeight.get(event.blockHeight).push(event);
    if (event.txid) {
      if (!eventsByTxid.has(event.txid)) {
        eventsByTxid.set(event.txid, []);
      }
      eventsByTxid.get(event.txid).push(event);
    }
  }
  const heightGroups = [...eventsByHeight.entries()]
    .map(([blockHeight, events]) => ({
      blockHeight,
      events: events.sort(
        (left, right) => {
          const comparison = compareValuePositions(
            canonicalValuePosition(left),
            canonicalValuePosition(right),
          );
          return (
            comparison ||
            compareCanonicalUtf8(left.txid, right.txid)
          );
        },
      ),
    }))
    .sort((left, right) => left.blockHeight - right.blockHeight);
  incrementDiagnostic("canonicalPositions", canonicalPositionKeys.size);
  incrementDiagnostic("canonicalValueEvents", canonicalEvents.length);
  incrementDiagnostic("prefixBuildMs", Date.now() - buildStartedAt);

  let lowerState;
  let heightCursor;
  let activeHeight;
  let activeGroup;
  let activeCursor;
  let activeAllHashState;
  let activeStateByHash;
  let lastTargetHeight;
  let lastTargetIndex;
  let lastTargetProtocolVout;
  let lastTargetRecordOrdinal;
  const resetCanonicalCursor = () => {
    lowerState = emptyGrowthActualBaseState();
    heightCursor = 0;
    activeHeight = null;
    activeGroup = null;
    activeCursor = 0;
    activeAllHashState = emptyGrowthActualBaseState();
    activeStateByHash = new Map();
    lastTargetHeight = Number.NEGATIVE_INFINITY;
    lastTargetIndex = Number.NEGATIVE_INFINITY;
    lastTargetProtocolVout = Number.NEGATIVE_INFINITY;
    lastTargetRecordOrdinal = Number.NEGATIVE_INFINITY;
  };
  resetCanonicalCursor();
  const applyEvent = (state, event, multiplier = 1) =>
    growthActualBaseStateApplyContribution(
      state,
      event.contribution,
      multiplier,
    );
  const prepareCanonicalPrefix = (targetPosition) => {
    const {
      blockHeight,
      blockIndex,
      protocolVout,
      recordOrdinal,
    } = targetPosition;
    const targetRegresses =
      blockHeight < lastTargetHeight ||
      (blockHeight === lastTargetHeight &&
        (
          blockIndex < lastTargetIndex ||
          (blockIndex === lastTargetIndex &&
            targetPosition.v5 &&
            (
              protocolVout < lastTargetProtocolVout ||
              (protocolVout === lastTargetProtocolVout &&
                recordOrdinal < lastTargetRecordOrdinal)
            ))
        ));
    if (
      targetRegresses
    ) {
      incrementDiagnostic("cursorResets");
      resetCanonicalCursor();
    }
    while (
      heightCursor < heightGroups.length &&
      heightGroups[heightCursor].blockHeight < blockHeight
    ) {
      for (const event of heightGroups[heightCursor].events) {
        applyEvent(lowerState, event);
      }
      heightCursor += 1;
    }
    if (activeHeight !== blockHeight) {
      activeHeight = blockHeight;
      activeGroup =
        heightGroups[heightCursor]?.blockHeight === blockHeight
          ? heightGroups[heightCursor]
          : null;
      activeCursor = 0;
      activeAllHashState = emptyGrowthActualBaseState();
      activeStateByHash = new Map();
    }
    while (
      activeGroup &&
      activeCursor < activeGroup.events.length &&
      compareValuePositions(
        canonicalValuePosition(activeGroup.events[activeCursor]),
        targetPosition,
      ) < 0
    ) {
      const event = activeGroup.events[activeCursor];
      applyEvent(activeAllHashState, event);
      if (!activeStateByHash.has(event.blockHash)) {
        activeStateByHash.set(event.blockHash, emptyGrowthActualBaseState());
      }
      applyEvent(activeStateByHash.get(event.blockHash), event);
      activeCursor += 1;
    }
    lastTargetHeight = blockHeight;
    lastTargetIndex = blockIndex;
    lastTargetProtocolVout = protocolVout;
    lastTargetRecordOrdinal = recordOrdinal;
  };

  const lookupQ8 = (source, createdMs) => {
    incrementDiagnostic("lookups");
    const blockHeight = Number(source?.blockHeight);
    const blockIndex = Number(source?.blockIndex);
    const positionedLivenet =
      source?.confirmed === true &&
      source?.network === "livenet" &&
      Number.isSafeInteger(blockHeight) &&
      blockHeight > 0 &&
      Number.isSafeInteger(blockIndex) &&
      blockIndex >= 0;
    if (!positionedLivenet) {
      incrementDiagnostic("timestampLookups");
      const timestampQ8 =
        typeof timestampProvider?.q8At === "function"
          ? timestampProvider.q8At(createdMs - 1)
          : decimalValueToQ8(timestampProvider(createdMs - 1));
      return timestampQ8 ?? 0n;
    }

    const targetPosition = canonicalValuePosition(source);
    if (!targetPosition) {
      throw new Error(
        "Canonical network-value event position is incomplete.",
      );
    }
    prepareCanonicalPrefix(targetPosition);
    const blockHash = String(source?.blockHash ?? "")
      .trim()
      .toLowerCase();
    const exactHash = /^[0-9a-f]{64}$/u.test(blockHash);
    const state = emptyGrowthActualBaseState();
    growthActualBaseStateAdd(state, lowerState);
    if (exactHash) {
      incrementDiagnostic("exactHashLookups");
      growthActualBaseStateAdd(state, activeStateByHash.get(blockHash));
    } else {
      incrementDiagnostic("allHashLookups");
      growthActualBaseStateAdd(state, activeAllHashState);
    }

    let sameTxAdjustments = 0;
    if (!targetPosition.v5) {
      const txid = String(source?.txid ?? "").trim().toLowerCase();
      for (const event of txid ? eventsByTxid.get(txid) ?? [] : []) {
        const included =
          event.blockHeight < blockHeight ||
          (event.blockHeight === blockHeight &&
            event.blockIndex < blockIndex &&
            (!exactHash || event.blockHash === blockHash));
        if (included) {
          applyEvent(state, event, -1);
          sameTxAdjustments += 1;
        }
      }
    }
    incrementDiagnostic("sameTxAdjustments", sameTxAdjustments);
    incrementDiagnostic("prefixLookups");
    return growthActualBaseStateTotalQ8(state);
  };
  const provider = (source, createdMs) =>
    q8ToNumber(lookupQ8(source, createdMs));
  provider.q8At = lookupQ8;
  return provider;
}

function canonicalReplayTimeline(events) {
  let prefixLength = 0;
  return (Array.isArray(events) ? events : [])
    .map((event, index) => ({ createdMs: event.createdMs, index }))
    .filter((entry) => Number.isFinite(entry.createdMs))
    .sort(
      (left, right) =>
        left.createdMs - right.createdMs || left.index - right.index,
    )
    .map((entry) => {
      prefixLength = Math.max(prefixLength, entry.index + 1);
      return { ...entry, prefixLength };
    });
}

function canonicalReplayPrefixLengthAtMs(timeline, atMs) {
  const targetMs = Number(atMs);
  if (!Number.isFinite(targetMs)) {
    return 0;
  }
  let low = 0;
  let high = timeline.length - 1;
  let prefixLength = 0;
  while (low <= high) {
    const middle = Math.floor((low + high) / 2);
    if (timeline[middle].createdMs <= targetMs) {
      prefixLength = timeline[middle].prefixLength;
      low = middle + 1;
    } else {
      high = middle - 1;
    }
  }
  return prefixLength;
}

function presentNonNegativeNumber(item, field) {
  if (
    !item ||
    item[field] === undefined ||
    item[field] === null ||
    item[field] === ""
  ) {
    return null;
  }
  const value = Number(item[field]);
  return Number.isFinite(value) && value >= 0 ? value : null;
}

function creditReplayTransactionMinerFeeSats(
  event,
  activity,
  options = {},
) {
  for (const item of [activity, event?.source, event]) {
    if (item?.canonicalMinerFeeCovered !== true) {
      continue;
    }
    const value = presentNonNegativeNumber(item, "canonicalMinerFeeSats");
    if (value !== null) {
      return value;
    }
  }
  if (options.requireCanonical === true) {
    return null;
  }
  for (const [item, field] of [
    [activity, "canonicalMinerFeeSats"],
    [event?.source, "canonicalMinerFeeSats"],
    [event, "canonicalMinerFeeSats"],
    [activity, "minerFeeSats"],
    [event?.source, "minerFeeSats"],
    [event, "minerFeeSats"],
  ]) {
    const value = presentNonNegativeNumber(item, field);
    if (value !== null) {
      return value;
    }
  }
  return 0;
}

function canonicalInceptionWorkMovementOracleByIdentity(
  tokenMints = [],
  tokenTransfers = [],
) {
  const transfersByTxid = new Map();
  for (const transfer of Array.isArray(tokenTransfers) ? tokenTransfers : []) {
    const txid = String(transfer?.txid ?? "").trim().toLowerCase();
    const amountSubatoms = workSubatomsBigIntFromRecord(
      transfer,
      { convertLegacyAtoms: true },
    );
    if (
      !transfer?.confirmed ||
      String(transfer?.tokenId ?? "").trim().toLowerCase() !== WORK_TOKEN_ID ||
      !/^[0-9a-f]{64}$/u.test(txid) ||
      amountSubatoms === null ||
      amountSubatoms <= 0n
    ) {
      continue;
    }
    const current = transfersByTxid.get(txid) ?? [];
    current.push(transfer);
    transfersByTxid.set(txid, current);
  }

  const oracleByIdentity = new Map();
  const ambiguousIdentities = new Set();
  for (const mint of Array.isArray(tokenMints) ? tokenMints : []) {
    const txid = String(mint?.txid ?? "").trim().toLowerCase();
    if (
      !mint?.confirmed ||
      String(mint?.tokenId ?? "").trim().toLowerCase() !== INCB_TOKEN_ID ||
      !/^[0-9a-f]{64}$/u.test(txid)
    ) {
      continue;
    }
    const issuance = inceptionIssuanceMetadataFromMints([mint]);
    if (
      !issuance.complete ||
      issuance.canonicalMints !== 1 ||
      issuance.confirmedMints !== 1 ||
      !canonicalWorkSubatomsText(
        issuance.attachedWorkAmountSubatoms,
      ) ||
      BigInt(issuance.attachedWorkAmountSubatoms) <= 0n
    ) {
      continue;
    }

    const recipientAddress = String(mint.bondRecipientAddress ?? "").trim();
    const checkpointHeight = Number(mint.issuanceCheckpointBlockHeight);
    const checkpointIndex = Number(mint.issuanceCheckpointBlockIndex);
    const checkpointHash = String(mint.issuanceCheckpointBlockHash ?? "")
      .trim()
      .toLowerCase();
    const candidates = (transfersByTxid.get(txid) ?? []).filter(
      (transfer) =>
        samePaymentAddress(transfer?.recipientAddress, recipientAddress) &&
        Number(transfer?.blockHeight) === checkpointHeight &&
        Number(transfer?.blockIndex) === checkpointIndex &&
        String(transfer?.blockHash ?? "").trim().toLowerCase() ===
          checkpointHash,
    );
    const attachedWorkAmountSubatoms = candidates.reduce(
      (total, transfer) => {
        const subatoms = workSubatomsBigIntFromRecord(
          transfer,
          { convertLegacyAtoms: true },
        );
        return subatoms === null ? total : total + subatoms;
      },
      0n,
    );
    const workNetworkValueQ8 =
      canonicalNonNegativeIntegerText(
        issuance.issuanceValueSnapshotWorkNetworkValueQ8,
      );
    const workNetworkValueSats = workNetworkValueQ8
      ? decimalTextFromQ8(workNetworkValueQ8)
      : "";
    const workFloorQ8 = workNetworkValueQ8
      ? floorQ8PerUnit(
          workNetworkValueQ8,
          String(WORK_TOKEN_MAX_SUPPLY),
        )
      : "";
    const workFloorSats = workFloorQ8
      ? decimalTextFromQ8(workFloorQ8)
      : "";
    const expectedAttachedValueQ8 = workSubatomsValueAtNetworkQ8(
      attachedWorkAmountSubatoms,
      workNetworkValueSats,
      workNetworkValueQ8,
    );
    const storedAttachedValueQ8 = canonicalNonNegativeIntegerText(
      issuance.attachedWorkLiveValueAtSendQ8,
    );
    if (
      candidates.length === 0 ||
      attachedWorkAmountSubatoms.toString() !==
        issuance.attachedWorkAmountSubatoms ||
      !workNetworkValueQ8 ||
      BigInt(workNetworkValueQ8) <= 0n ||
      !workFloorQ8 ||
      BigInt(workFloorQ8) <= 0n ||
      expectedAttachedValueQ8 === null ||
      (storedAttachedValueQ8
        ? BigInt(storedAttachedValueQ8) !== expectedAttachedValueQ8
        : !numbersAgree(
            issuance.attachedWorkLiveValueAtSendSats,
            q8ToNumber(expectedAttachedValueQ8),
            0.01,
          ))
    ) {
      continue;
    }

    const oracle = {
      amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
      attachedWorkAmountDecimals: WORK_SUBATOM_DECIMALS,
      attachedWorkAmountPrecisionModel:
        WORK_PRECISION_V2_MODEL,
      attachedWorkAmountStorageModel:
        WORK_SUBATOM_PROJECTION_MODEL,
      attachedWorkAmountSubatoms:
        attachedWorkAmountSubatoms.toString(),
      attachedWorkAmountUnitScale:
        WORK_SUBATOM_UNIT_SCALE_TEXT,
      attachedWorkAmountVersion: TOKEN_SEND_SUBATOMS_ACTION,
      model: INCEPTION_WORK_MOVEMENT_ORACLE_MODEL,
      precisionModel: WORK_PRECISION_V2_MODEL,
      unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
      valueSnapshotBlockHash: String(
        issuance.issuanceValueSnapshotBlockHash ?? "",
      )
        .trim()
        .toLowerCase(),
      valueSnapshotBlockHeight: numericValue(
        issuance.issuanceValueSnapshotBlockHeight,
      ),
      valueSnapshotCanonicalSummaryHash: String(
        issuance.issuanceValueSnapshotCanonicalSummaryHash ?? "",
      )
        .trim()
        .toLowerCase(),
      valueSnapshotGeneratedAt: String(
        issuance.issuanceValueSnapshotGeneratedAt ?? "",
      ).trim(),
      valueSnapshotId: String(issuance.issuanceValueSnapshotId ?? "").trim(),
      workFloorQ8,
      workFloorSats,
      workNetworkValueQ8,
      workNetworkValueSats,
    };
    for (const transfer of candidates) {
      const identity = creditMovementIdentity(transfer, "transfer");
      if (!identity || oracleByIdentity.has(identity)) {
        ambiguousIdentities.add(identity);
        continue;
      }
      const movementSubatoms = workSubatomsBigIntFromRecord(
        transfer,
        { convertLegacyAtoms: true },
      );
      if (movementSubatoms === null || movementSubatoms <= 0n) {
        ambiguousIdentities.add(identity);
        continue;
      }
      oracleByIdentity.set(identity, {
        ...oracle,
        movementAmountSubatoms: movementSubatoms.toString(),
      });
    }
  }

  for (const identity of ambiguousIdentities) {
    oracleByIdentity.delete(identity);
  }
  return oracleByIdentity;
}

function creditNetworkValueMetrics({
  baseValueAt,
  baseValueBeforeEvent = null,
  baseValueBeforeEventQ8 = null,
  baseValueQ8At = null,
  canonicalMinerFeeCoverage = null,
  confirmedActivity = [],
  cutoffMs = Date.now(),
  includeEvents = false,
  tokenDefinitions = [],
  tokenMints = [],
  tokenSales = [],
  tokenTransfers = [],
}) {
  const exactBaseValueQ8At =
    typeof baseValueQ8At === "function"
      ? baseValueQ8At
      : typeof baseValueAt?.q8At === "function"
        ? baseValueAt.q8At
        : (atMs) => decimalValueToQ8(baseValueAt(atMs)) ?? 0n;
  const numericBaseValueBeforeEvent =
    typeof baseValueBeforeEvent === "function"
      ? baseValueBeforeEvent
      : typeof baseValueAt?.beforeCanonicalItem === "function"
        ? baseValueAt.beforeCanonicalItem
        : (_source, createdMs) => baseValueAt(createdMs - 1);
  const exactBaseValueBeforeEventQ8 =
    typeof baseValueBeforeEventQ8 === "function"
      ? baseValueBeforeEventQ8
      : typeof baseValueAt?.q8BeforeCanonicalItem === "function"
        ? baseValueAt.q8BeforeCanonicalItem
        : (source, createdMs) =>
            decimalValueToQ8(
              numericBaseValueBeforeEvent(source, createdMs),
            ) ?? 0n;
  const verifiedMinerFeeCoverage = verifiedCanonicalMinerFeeCoverage(
    canonicalMinerFeeCoverage,
  );
  const inceptionWorkMovementOracleByIdentity =
    canonicalInceptionWorkMovementOracleByIdentity(
      tokenMints,
      tokenTransfers,
    );
  let canonicalReplayFeesComplete = true;
  const minerFeeAccounting = () =>
    verifiedMinerFeeCoverage && canonicalReplayFeesComplete
      ? {
          creditMinerFeeAccountingModel: CREDIT_MINER_FEE_ACCOUNTING_MODEL,
          creditMinerFeeCoverage: verifiedMinerFeeCoverage,
        }
      : {};
  const tokensById = new Map(
    (Array.isArray(tokenDefinitions) ? tokenDefinitions : [])
      .filter(
        (token) =>
          token?.valid !== false && tokenCanUseCreditNetworkFloor(token),
      )
      .map((token) => [String(token.tokenId ?? "").toLowerCase(), token]),
  );
  if (tokensById.size === 0) {
    return {
      ...minerFeeAccounting(),
      creditEventFrozenValueSats: 0,
      creditEventFrozenValueQ8: "0",
      creditEventLiveValueSats: 0,
      creditEventLiveValueQ8: "0",
      creditMinerFeeFlowSats: 0,
      creditMarketplaceMutationFlowSats: 0,
      creditMovementFrozenValueSats: 0,
      creditMovementFrozenValueQ8: "0",
      creditMovementLiveValueSats: 0,
      creditMovementLiveValueQ8: "0",
      creditNetworkValueSats: 0,
      creditNetworkValueQ8: "0",
      creditFrozenNetworkValueSats: 0,
      creditFrozenNetworkValueQ8: "0",
      creditLiveNetworkValueSats: 0,
      creditLiveNetworkValueQ8: "0",
      creditProofPaymentFlowSats: 0,
      creditRegistryMutationFlowSats: 0,
      creditSalePaymentFlowSats: 0,
      events: [],
      liveFloorByTokenId: {},
      liveFloorQ8ByTokenId: {},
      frozenNetworkValueWithCreditQ8: exactBaseValueQ8At(cutoffMs).toString(),
      liveNetworkValueWithCreditQ8: exactBaseValueQ8At(cutoffMs).toString(),
    };
  }

  const activityByRecord = new Map();
  const activityByTxid = new Map();
  const addTokenActivity = (item) => {
    const txid = String(item?.txid ?? "").toLowerCase();
    const createdMs = creditValueEventMs(item);
    if (
      !/^[0-9a-f]{64}$/u.test(txid) ||
      createdMs > cutoffMs ||
      !tokensById.has(String(item?.tokenId ?? "").toLowerCase())
    ) {
      return;
    }
    const recordIdentity = creditReplayRecordIdentity(item);
    if (!recordIdentity) {
      return;
    }
    const current = activityByRecord.get(recordIdentity);
    if (
      !current ||
      numericValue(item?.minerFeeSats) > numericValue(current?.minerFeeSats) ||
      numericValue(item?.frozenNetworkValueSats) >
        numericValue(current?.frozenNetworkValueSats)
    ) {
      activityByRecord.set(recordIdentity, item);
    }
    const currentTxActivity = activityByTxid.get(txid);
    if (
      !currentTxActivity ||
      numericValue(item?.minerFeeSats) >
        numericValue(currentTxActivity?.minerFeeSats) ||
      numericValue(item?.frozenNetworkValueSats) >
        numericValue(currentTxActivity?.frozenNetworkValueSats)
    ) {
      activityByTxid.set(txid, item);
    }
  };

  for (const item of Array.isArray(confirmedActivity) ? confirmedActivity : []) {
    if (
      item?.confirmed &&
      item?.valid !== false &&
      isTokenActivityItem(item)
    ) {
      addTokenActivity(item);
    }
  }

  const movementEvents = [];
  const movementRecordIdentities = new Set();
  const addMovementEvent = (item, kind) => {
    const token = tokensById.get(String(item?.tokenId ?? "").toLowerCase());
    const txid = String(item?.txid ?? "").toLowerCase();
    const createdMs = creditValueEventMs(item);
    const workMovement = isWorkTokenId(item?.tokenId);
    const amountSubatoms = workMovement
      ? kind === "sale"
        ? canonicalTokenSaleLedgerAmount(WORK_TOKEN_ID, item, {
            workAmountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
          })
        : workSubatomsBigIntFromRecord(item, {
            convertLegacyAtoms: true,
          })
      : null;
    const amountUnits = workMovement
      ? null
      : integerBigInt(item?.amount, { allowZero: false });
    const amount = workMovement
      ? amountSubatoms === null
        ? ""
        : formatWorkSubatoms(amountSubatoms)
      : Number(amountUnits ?? 0n);
    if (
      !token ||
      !item?.confirmed ||
      item?.valid === false ||
      !/^[0-9a-f]{64}$/u.test(txid) ||
      createdMs > cutoffMs ||
      (
        workMovement
          ? amountSubatoms === null || amountSubatoms <= 0n
          : amountUnits === null
      )
    ) {
      return;
    }

    movementEvents.push({
      amount,
      ...(amountSubatoms === null
        ? {}
        : {
            amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
            amountSubatoms: amountSubatoms.toString(),
            decimals: WORK_SUBATOM_DECIMALS,
            precisionModel: WORK_PRECISION_V2_MODEL,
            unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
          }),
      ...(amountUnits === null ? {} : { amountUnits: amountUnits.toString() }),
      createdMs,
      kind,
      movementIdentity: creditMovementIdentity(item, kind),
      order: 1,
      source: item,
      token,
      txid,
    });
    const recordIdentity = creditReplayRecordIdentity(item);
    if (recordIdentity) {
      movementRecordIdentities.add(recordIdentity);
    }
  };
  for (const mint of Array.isArray(tokenMints) ? tokenMints : []) {
    addMovementEvent(mint, "mint");
  }
  for (const transfer of Array.isArray(tokenTransfers) ? tokenTransfers : []) {
    addMovementEvent(transfer, "transfer");
  }
  for (const sale of Array.isArray(tokenSales) ? tokenSales : []) {
    addMovementEvent(sale, "sale");
  }

  const mutationEvents = [];
  const addMutationEvent = (item) => {
    const txid = String(item?.txid ?? "").toLowerCase();
    const kind = String(item?.kind ?? "");
    const token = tokensById.get(String(item?.tokenId ?? "").toLowerCase());
    const createdMs = creditValueEventMs(item);
    if (
      !token ||
      !item?.confirmed ||
      !/^[0-9a-f]{64}$/u.test(txid) ||
      createdMs > cutoffMs ||
      movementRecordIdentities.has(creditReplayRecordIdentity(item))
    ) {
      return;
    }
    if (
      kind !== "token-create" &&
      kind !== "token-listing" &&
      kind !== "token-listing-sealed" &&
      kind !== "token-listing-closed"
    ) {
      return;
    }

    const proofPaymentSats =
      kind === "token-create"
        ? proofFlowBigInt(
            item?.proofPaymentSats ?? item?.amountSats,
          ).toString()
        : "0";
    const marketplaceMutationFeeSats =
      TOKEN_MARKETPLACE_MUTATION_KINDS.has(kind)
        ? (
            proofFlowBigInt(
              item?.marketplaceMutationFeeSats ?? item?.amountSats,
            ) || BigInt(TOKEN_MIN_MUTATION_PRICE_SATS)
          ).toString()
        : "0";
    const minerFeeSats = numericValue(item?.minerFeeSats);
    mutationEvents.push({
      amount: 0,
      createdMs,
      kind: kind.replace(/^token-/u, ""),
      marketplaceMutationFeeSats,
      minerFeeSats,
      order: 2,
      proofPaymentSats,
      registryMutationFeeSats: 0,
      salePaymentSats: 0,
      source: item,
      sourceKind: kind,
      token,
      txid,
    });
  };
  for (const item of activityByRecord.values()) {
    addMutationEvent(item);
  }

  const tokenMaxSupplyUnits = (token) => {
    if (isWorkTokenId(token?.tokenId)) {
      return BigInt(WORK_TOKEN_MAX_SUPPLY);
    }
    return integerBigInt(token?.maxSupply, { allowZero: false });
  };
  const movementValueAtNetworkQ8 = (event, networkValueQ8) => {
    const totalQ8 =
      typeof networkValueQ8 === "bigint"
        ? networkValueQ8
        : proofFlowBigInt(networkValueQ8);
    const supply = tokenMaxSupplyUnits(event.token);
    if (supply === null || supply <= 0n || totalQ8 < 0n) {
      return null;
    }
    if (event.amountSubatoms) {
      return (
        (BigInt(event.amountSubatoms) * totalQ8) /
        (supply * WORK_SUBATOM_UNIT_SCALE)
      );
    }
    if (event.amountUnits) {
      return (BigInt(event.amountUnits) * totalQ8) / supply;
    }
    return event.amount === 0 ? 0n : null;
  };
  const proofFlow = (value) => proofFlowBigInt(value);
  let creditMovementFrozenValueSats = 0;
  let creditEventFrozenValueSats = 0;
  let creditMovementFrozenValueQ8 = 0n;
  let creditEventFrozenValueQ8 = 0n;
  let creditMinerFeeFlowSats = 0;
  let creditMarketplaceMutationFlowSats = 0;
  let creditProofPaymentFlowSats = 0;
  let creditRegistryMutationFlowSats = 0;
  let creditSalePaymentFlowSats = 0;
  const eventDetails = [];
  let cumulativeFrozenCreditValueQ8 = 0n;
  const countedMinerFeeTxids = new Set();
  const replayEvents = assertUniqueCreditValueReplayPositions([
    ...movementEvents,
    ...mutationEvents,
  ]).sort(compareCreditValueReplayEvents);

  for (const event of replayEvents) {
    const baseBeforeQ8 = exactBaseValueBeforeEventQ8(
      event.source,
      event.createdMs,
    );
    const networkValueBeforeEventQ8 =
      baseBeforeQ8 + cumulativeFrozenCreditValueQ8;
    const maxSupply = tokenMaxSupplyUnits(event.token);
    const inceptionWorkMovementOracle =
      event.kind === "transfer"
        ? inceptionWorkMovementOracleByIdentity.get(event.movementIdentity)
        : null;
    const oracleNetworkValueQ8 = canonicalNonNegativeIntegerText(
      inceptionWorkMovementOracle?.workNetworkValueQ8,
    );
    const liveNetworkValueBeforeEventQ8 = oracleNetworkValueQ8
      ? BigInt(oracleNetworkValueQ8)
      : networkValueBeforeEventQ8;
    const oracleFloorQ8 = canonicalNonNegativeIntegerText(
      inceptionWorkMovementOracle?.workFloorQ8,
    );
    const creditFloorAtConfirmQ8 = oracleFloorQ8
      ? BigInt(oracleFloorQ8)
      : maxSupply && maxSupply > 0n
        ? liveNetworkValueBeforeEventQ8 / maxSupply
        : 0n;
    const creditValueAtConfirmQ8 =
      movementValueAtNetworkQ8(event, liveNetworkValueBeforeEventQ8) ?? 0n;
    const creditValueAtConfirmSats = q8ToNumber(creditValueAtConfirmQ8);
    const recordActivity = activityByRecord.get(
      creditReplayRecordIdentity(event.source),
    );
    const transactionActivity = activityByTxid.get(event.txid);
    const activity =
      transactionActivity?.canonicalMinerFeeCovered === true
        ? transactionActivity
        : recordActivity ?? transactionActivity;
    const canonicalTransactionMinerFeeSats = creditReplayTransactionMinerFeeSats(
      event,
      activity,
      { requireCanonical: Boolean(verifiedMinerFeeCoverage) },
    );
    if (
      verifiedMinerFeeCoverage &&
      canonicalTransactionMinerFeeSats === null
    ) {
      canonicalReplayFeesComplete = false;
    }
    const transactionMinerFee = proofFlow(canonicalTransactionMinerFeeSats);
    const minerFee = countedMinerFeeTxids.has(event.txid)
      ? 0n
      : transactionMinerFee;
    countedMinerFeeTxids.add(event.txid);
    const proofPayment =
      event.kind === "mint"
        ? proofFlow(event.source?.paidSats)
        : proofFlow(event.proofPaymentSats);
    const registryMutationFee =
      event.kind === "transfer"
        ? proofFlow(event.source?.paidSats)
        : proofFlow(event.registryMutationFeeSats);
    const marketplaceMutationFee =
      event.kind === "sale"
        ? proofFlow(event.source?.marketplaceMutationFeeSats) ||
          BigInt(TOKEN_MIN_MUTATION_PRICE_SATS)
        : proofFlow(event.marketplaceMutationFeeSats);
    const salePayment =
      event.kind === "sale" ? proofFlow(event.source?.priceSats) : 0n;
    const fixedEventFlow =
      proofPayment +
      registryMutationFee +
      marketplaceMutationFee +
      salePayment +
      minerFee;
    const fixedEventFlowQ8 = fixedEventFlow * VALUE_Q8_SCALE;
    const frozenNetworkValueQ8 =
      creditValueAtConfirmQ8 + fixedEventFlowQ8;
    const frozenNetworkValueSats = q8ToNumber(frozenNetworkValueQ8);
    const transactionMinerFeeSats = Number(transactionMinerFee);
    const minerFeeSats = Number(minerFee);
    const proofPaymentSats = Number(proofPayment);
    const registryMutationFeeSats = Number(registryMutationFee);
    const marketplaceMutationFeeSats = Number(marketplaceMutationFee);
    const salePaymentSats = Number(salePayment);
    const fixedEventFlowSats = Number(fixedEventFlow);
    creditMovementFrozenValueQ8 += creditValueAtConfirmQ8;
    creditEventFrozenValueQ8 += frozenNetworkValueQ8;

    creditMovementFrozenValueSats += creditValueAtConfirmSats;
    creditEventFrozenValueSats += frozenNetworkValueSats;
    creditMinerFeeFlowSats += minerFeeSats;
    creditMarketplaceMutationFlowSats += marketplaceMutationFeeSats;
    creditProofPaymentFlowSats += proofPaymentSats;
    creditRegistryMutationFlowSats += registryMutationFeeSats;
    creditSalePaymentFlowSats += salePaymentSats;
    cumulativeFrozenCreditValueQ8 += frozenNetworkValueQ8;
    eventDetails.push({
      amount: event.amount,
      ...(event.amountSubatoms
        ? {
            amountStorageModel: event.amountStorageModel,
            amountSubatoms: event.amountSubatoms,
            decimals: event.decimals,
            precisionModel: event.precisionModel,
            unitScale: event.unitScale,
          }
        : {}),
      ...(event.amountUnits ? { amountUnits: event.amountUnits } : {}),
      arbSats:
        event.kind === "sale" ? creditValueAtConfirmSats - salePaymentSats : 0,
      creditFloorAtConfirmSats:
        q8ToCanonicalDecimal(creditFloorAtConfirmQ8),
      creditFloorAtConfirmQ8: creditFloorAtConfirmQ8.toString(),
      creditFloorAtConfirmModel:
        inceptionWorkMovementOracle?.model ?? "canonical-frozen-credit-replay-v1",
      creditValueAtConfirmSats: q8ToCanonicalDecimal(creditValueAtConfirmQ8),
      creditValueAtConfirmQ8: creditValueAtConfirmQ8.toString(),
      fixedEventFlowSats,
      fixedEventFlowQ8: fixedEventFlowQ8.toString(),
      frozenNetworkValueSats: q8ToCanonicalDecimal(frozenNetworkValueQ8),
      frozenNetworkValueQ8: frozenNetworkValueQ8.toString(),
      kind: event.kind,
      liveNetworkValueBeforeEventSats:
        q8ToCanonicalDecimal(liveNetworkValueBeforeEventQ8),
      liveNetworkValueBeforeEventQ8:
        liveNetworkValueBeforeEventQ8.toString(),
      marketplaceMutationFeeSats,
      minerFeeSats,
      movementIdentity: event.movementIdentity,
      networkValueBeforeEventSats:
        q8ToCanonicalDecimal(networkValueBeforeEventQ8),
      networkValueBeforeEventQ8: networkValueBeforeEventQ8.toString(),
      proofPaymentSats,
      registryMutationFeeSats,
      salePaymentSats,
      sourceKind: event.sourceKind ?? `token-${event.kind}`,
      ticker: event.token.ticker,
      tokenId: event.token.tokenId,
      transactionMinerFeeSats,
      txid: event.txid,
      ...(inceptionWorkMovementOracle
        ? {
            valueSnapshotBlockHash:
              inceptionWorkMovementOracle.valueSnapshotBlockHash,
            valueSnapshotBlockHeight:
              inceptionWorkMovementOracle.valueSnapshotBlockHeight,
            valueSnapshotCanonicalSummaryHash:
              inceptionWorkMovementOracle.valueSnapshotCanonicalSummaryHash,
            valueSnapshotGeneratedAt:
              inceptionWorkMovementOracle.valueSnapshotGeneratedAt,
            valueSnapshotId: inceptionWorkMovementOracle.valueSnapshotId,
          }
        : {}),
    });
  }

  creditMovementFrozenValueSats = q8ToNumber(
    creditMovementFrozenValueQ8,
  );
  creditEventFrozenValueSats = q8ToNumber(creditEventFrozenValueQ8);
  const baseNowQ8 = exactBaseValueQ8At(cutoffMs);
  const frozenNetworkValueWithCreditQ8 =
    baseNowQ8 + creditEventFrozenValueQ8;
  const frozenNetworkValueWithCreditSats = q8ToNumber(
    frozenNetworkValueWithCreditQ8,
  );
  const revaluationFloorByTokenId = {};
  const liveFloorQ8ByTokenId = {};
  for (const token of tokensById.values()) {
    const maxSupply = tokenMaxSupplyUnits(token);
    const floorQ8 =
      maxSupply && maxSupply > 0n
        ? frozenNetworkValueWithCreditQ8 / maxSupply
        : 0n;
    liveFloorQ8ByTokenId[token.tokenId] = floorQ8.toString();
    revaluationFloorByTokenId[token.tokenId] = q8ToNumber(floorQ8);
  }
  let creditMovementLiveValueSats = 0;
  let creditEventLiveValueSats = 0;
  let creditMovementLiveValueQ8 = 0n;
  let creditEventLiveValueQ8 = 0n;
  for (const event of eventDetails) {
    const creditRevaluationFloorQ8 = BigInt(
      liveFloorQ8ByTokenId[event.tokenId] ?? "0",
    );
    const creditRevaluationFloorSats = q8ToNumber(
      creditRevaluationFloorQ8,
    );
    const creditLiveValueQ8 =
      movementValueAtNetworkQ8(
        { ...event, token: tokensById.get(event.tokenId) },
        frozenNetworkValueWithCreditQ8,
      ) ?? 0n;
    const creditLiveValueSats = q8ToNumber(creditLiveValueQ8);
    creditMovementLiveValueSats += creditLiveValueSats;
    creditMovementLiveValueQ8 += creditLiveValueQ8;
    event.creditRevaluationFloorSats = creditRevaluationFloorSats;
    event.creditLiveFloorSats = creditRevaluationFloorSats;
    event.creditLiveValueSats = q8ToCanonicalDecimal(creditLiveValueQ8);
    event.creditLiveFloorQ8 = creditRevaluationFloorQ8.toString();
    event.creditRevaluationFloorQ8 = creditRevaluationFloorQ8.toString();
    event.creditLiveValueQ8 = creditLiveValueQ8.toString();
    const liveNetworkValueQ8 =
      creditLiveValueQ8 + BigInt(event.fixedEventFlowQ8 ?? "0");
    event.liveNetworkValueSats = q8ToCanonicalDecimal(liveNetworkValueQ8);
    event.liveNetworkValueQ8 = liveNetworkValueQ8.toString();
    creditEventLiveValueQ8 += liveNetworkValueQ8;
    creditEventLiveValueSats += q8ToNumber(liveNetworkValueQ8);
  }
  const liveNetworkValueWithCreditQ8 = baseNowQ8 + creditEventLiveValueQ8;
  creditMovementLiveValueSats = q8ToNumber(creditMovementLiveValueQ8);
  creditEventLiveValueSats = q8ToNumber(creditEventLiveValueQ8);
  const liveNetworkValueWithCreditSats = q8ToNumber(
    liveNetworkValueWithCreditQ8,
  );

  return {
    ...minerFeeAccounting(),
    creditEventFrozenValueSats,
    creditEventFrozenValueQ8: creditEventFrozenValueQ8.toString(),
    creditEventLiveValueSats,
    creditEventLiveValueQ8: creditEventLiveValueQ8.toString(),
    creditFrozenNetworkValueSats: creditEventFrozenValueSats,
    creditFrozenNetworkValueQ8: creditEventFrozenValueQ8.toString(),
    creditMinerFeeFlowSats,
    creditMarketplaceMutationFlowSats,
    creditMovementFrozenValueSats,
    creditMovementFrozenValueQ8: creditMovementFrozenValueQ8.toString(),
    creditMovementLiveValueSats,
    creditMovementLiveValueQ8: creditMovementLiveValueQ8.toString(),
    creditLiveNetworkValueSats: creditEventLiveValueSats,
    creditLiveNetworkValueQ8: creditEventLiveValueQ8.toString(),
    creditNetworkValueSats: creditEventLiveValueSats,
    creditNetworkValueQ8: creditEventLiveValueQ8.toString(),
    creditProofPaymentFlowSats,
    creditRegistryMutationFlowSats,
    creditSalePaymentFlowSats,
    events: includeEvents ? eventDetails : [],
    frozenNetworkValueWithCreditSats,
    frozenNetworkValueWithCreditQ8:
      frozenNetworkValueWithCreditQ8.toString(),
    liveFloorByTokenId: revaluationFloorByTokenId,
    liveFloorQ8ByTokenId,
    revaluationFloorByTokenId,
    liveNetworkValueWithCreditSats,
    liveNetworkValueWithCreditQ8: liveNetworkValueWithCreditQ8.toString(),
  };
}

function tokenStateWithScopedTokenOverride(tokenState, scopedState, tokenId) {
  if (!scopedState || !tokenId) {
    return tokenState;
  }

  const scopedTokens = Array.isArray(scopedState.tokens)
    ? scopedState.tokens.filter((item) => item.tokenId === tokenId)
    : [];
  if (scopedTokens.length === 0) {
    return tokenState;
  }

  const unscopedItems = (items) =>
    (Array.isArray(items) ? items : []).filter((item) => item.tokenId !== tokenId);
  const scopedItemsFrom = (items) =>
    (Array.isArray(items) ? items : []).filter((item) => item.tokenId === tokenId);
  const scopedInvalidEventKey = (item) =>
    [
      String(item?.kind ?? "").trim().toLowerCase(),
      String(item?.tokenId ?? "").trim().toLowerCase(),
      String(item?.txid ?? "").trim().toLowerCase(),
    ].join(":");
  const scopedTokenKey = (item) =>
    String(item?.tokenId ?? "").trim().toLowerCase();
  const mergeScopedItems = (
    globalItems,
    scopedItems,
    keyForItem,
    mergeItem,
  ) => [
    ...unscopedItems(globalItems),
    ...mergeTokenStateItemsByKey(
      scopedItemsFrom(globalItems),
      scopedItemsFrom(scopedItems),
      keyForItem,
      mergeItem,
    ),
  ];
  const replaceScopedListingItems = (globalItems, scopedItems) => {
    return mergeScopedItems(
      globalItems,
      scopedItems,
      tokenListingItemKey,
      mergeTokenListingRecord,
    );
  };

  const merged = {
    ...tokenState,
    closedListings: replaceScopedListingItems(
      tokenState?.closedListings,
      scopedState.closedListings,
    ),
    invalidEvents: mergeScopedItems(
      tokenState?.invalidEvents,
      scopedState.invalidEvents,
      scopedInvalidEventKey,
    ),
    listings: replaceScopedListingItems(
      tokenState?.listings,
      scopedState.listings,
    ),
    mints: mergeScopedItems(
      tokenState?.mints,
      scopedState.mints,
      tokenMintHistoryItemKey,
    ),
    sales: mergeScopedItems(
      tokenState?.sales,
      scopedState.sales,
      tokenSaleItemKey,
    ),
    tokens: mergeScopedItems(
      tokenState?.tokens,
      scopedState.tokens,
      scopedTokenKey,
    ),
    transfers: mergeScopedItems(
      tokenState?.transfers,
      scopedState.transfers,
      tokenTransferHistoryItemKey,
      mergeTokenTransferRecord,
    ),
  };
  return tokenStateWithPendingStats(merged);
}

function tokenMarketRecordTokenId(item) {
  return normalizeTokenScope(
    item?.tokenId ??
      item?.saleAuthorization?.tokenId ??
      item?.listingAuthorization?.tokenId ??
      item?.authorization?.tokenId ??
      item?.sale?.tokenId ??
      item?.listing?.tokenId ??
      item?.closedListing?.tokenId ??
      item?.ticker ??
      item?.saleAuthorization?.ticker ??
      item?.listingAuthorization?.ticker ??
      item?.authorization?.ticker ??
      item?.sale?.ticker ??
      item?.listing?.ticker ??
      item?.closedListing?.ticker ??
      "",
  );
}

function tokenSummaryNonNegativeInteger(value) {
  const number = Number(value);
  return Number.isSafeInteger(number) && number >= 0 ? number : null;
}

function tokenStateWorkListingBookCounts(state) {
  const isWorkMarketRecord = (item) =>
    isWorkTokenId(tokenMarketRecordTokenId(item));
  const workListings = (Array.isArray(state?.listings)
    ? state.listings
    : []
  ).filter(isWorkMarketRecord);
  const workToken = (Array.isArray(state?.tokens)
    ? state.tokens
    : []
  ).find((token) => isWorkTokenId(token?.tokenId));
  const count = (key, fallback) =>
    tokenSummaryNonNegativeInteger(workToken?.[key]) ?? fallback;
  const confirmedWorkListings = workListings.filter(
    (listing) => listing?.confirmed === true,
  ).length;

  return {
    confirmedOpenListings: count(
      "confirmedOpenListings",
      confirmedWorkListings,
    ),
    materializedListings: workListings.length,
    openListings: count("openListings", workListings.length),
    pendingOpenListings: count(
      "pendingOpenListings",
      Math.max(0, workListings.length - confirmedWorkListings),
    ),
  };
}

function tokenStateHasFullerWorkListingBook(currentState, candidateState) {
  const current = tokenStateWorkListingBookCounts(currentState);
  const candidate = tokenStateWorkListingBookCounts(candidateState);
  return (
    current.openListings > candidate.openListings ||
    current.confirmedOpenListings > candidate.confirmedOpenListings ||
    current.materializedListings > candidate.materializedListings
  );
}

function tokenStateWithCanonicalWorkListingBook(tokenState, scopedWorkState) {
  if (!tokenState || !scopedWorkState) {
    return tokenState;
  }

  const scopedWorkToken = (Array.isArray(scopedWorkState.tokens)
    ? scopedWorkState.tokens
    : []
  ).find((token) => isWorkTokenId(token?.tokenId));
  if (!scopedWorkToken) {
    return tokenState;
  }

  const isWorkMarketRecord = (item) =>
    isWorkTokenId(tokenMarketRecordTokenId(item));
  const withoutWorkRecords = (items) =>
    (Array.isArray(items) ? items : []).filter(
      (item) => !isWorkMarketRecord(item),
    );
  const scopedWorkRecords = (items) =>
    (Array.isArray(items) ? items : []).filter(isWorkMarketRecord);
  const scopedWorkListings = scopedWorkRecords(scopedWorkState.listings);
  const scopedWorkClosedListings = scopedWorkRecords(
    scopedWorkState.closedListings,
  );
  const scopedWorkSales = scopedWorkRecords(scopedWorkState.sales);
  const scopedWorkInvalidEvents = scopedWorkRecords(
    scopedWorkState.invalidEvents,
  );

  const tokens = (() => {
    const existingTokens = Array.isArray(tokenState.tokens)
      ? tokenState.tokens
      : [];
    if (existingTokens.length === 0) {
      return [scopedWorkToken];
    }
    let replaced = false;
    const next = existingTokens.map((token) => {
      if (!isWorkTokenId(token?.tokenId)) {
        return token;
      }
      replaced = true;
      return scopedWorkToken;
    });
    return replaced ? next : [...next, scopedWorkToken];
  })();

  const countFromTokens = (key) => {
    const counts = tokens.map((token) =>
      tokenSummaryNonNegativeInteger(token?.[key]),
    );
    return counts.length > 0 && counts.every((count) => count !== null)
      ? counts.reduce((total, count) => total + count, 0)
      : null;
  };
  const listings = [
    ...withoutWorkRecords(tokenState.listings),
    ...scopedWorkListings,
  ].sort(compareTokenHistoryPageItems);
  const closedListings = sortClosedTokenListings([
    ...withoutWorkRecords(tokenState.closedListings),
    ...scopedWorkClosedListings,
  ]);
  const sales = [
    ...withoutWorkRecords(tokenState.sales),
    ...scopedWorkSales,
  ].sort(compareTokenHistoryPageItems);
  const invalidEvents = [
    ...withoutWorkRecords(tokenState.invalidEvents),
    ...scopedWorkInvalidEvents,
  ].sort(compareTokenHistoryPageItems);
  const openListings = countFromTokens("openListings") ?? listings.length;
  const confirmedOpenListings =
    countFromTokens("confirmedOpenListings") ??
    listings.filter((listing) => listing?.confirmed === true).length;
  const pendingOpenListings =
    countFromTokens("pendingOpenListings") ??
    Math.max(0, openListings - confirmedOpenListings);
  const collectionHasMore =
    tokenState.collectionHasMore &&
    typeof tokenState.collectionHasMore === "object" &&
    !Array.isArray(tokenState.collectionHasMore)
      ? {
          ...tokenState.collectionHasMore,
          listings: openListings > listings.length,
        }
      : tokenState.collectionHasMore;

  return tokenStateWithPendingStats({
    ...tokenState,
    closedListings,
    invalidEvents,
    listings,
    sales,
    ...(collectionHasMore
      ? {
          collectionHasMore,
          hasMore: Object.values(collectionHasMore).some(Boolean),
        }
      : {}),
    ...(tokenState.stats &&
    typeof tokenState.stats === "object" &&
    !Array.isArray(tokenState.stats)
      ? {
          stats: {
            ...tokenState.stats,
            activeListings: openListings,
            confirmedOpenListings,
            openListings,
            pendingOpenListings,
          },
        }
      : {}),
    ...(tokenState.totalCounts &&
    typeof tokenState.totalCounts === "object" &&
    !Array.isArray(tokenState.totalCounts)
      ? {
          totalCounts: {
            ...tokenState.totalCounts,
            listings: openListings,
          },
        }
      : {}),
    tokens,
  });
}

async function tokenStateWithCanonicalWorkListingBookForMarketplaceSummary(
  tokenState,
  network,
) {
  if (network !== "livenet" || !tokenState) {
    return tokenState;
  }

  const scopedWorkState = await storedCanonicalTokenSummaryPayload(
    network,
    WORK_TOKEN_ID,
  ).catch((error) => {
    console.error(
      `WORK canonical listing book unavailable for marketplace summary: ${errorSummary(error)}`,
    );
    return null;
  });
  if (!scopedWorkState) {
    return tokenState;
  }

  const tokenStateHeight = proofIndexPayloadIndexedThroughBlock(tokenState);
  const scopedWorkHeight = proofIndexPayloadIndexedThroughBlock(scopedWorkState);
  if (
    tokenStateHeight > 0 &&
    scopedWorkHeight > 0 &&
    scopedWorkHeight < tokenStateHeight
  ) {
    console.error(
      `Rejected stale WORK canonical listing book for marketplace summary: scoped ${scopedWorkHeight}, summary ${tokenStateHeight}.`,
    );
    return tokenState;
  }
  if (
    tokenStateHeight > 0 &&
    scopedWorkHeight > 0 &&
    scopedWorkHeight === tokenStateHeight &&
    tokenStateHasFullerWorkListingBook(tokenState, scopedWorkState)
  ) {
    console.error(
      `Rejected smaller same-checkpoint WORK canonical listing book for marketplace summary: ${JSON.stringify({
        current: tokenStateWorkListingBookCounts(tokenState),
        height: tokenStateHeight,
        scoped: tokenStateWorkListingBookCounts(scopedWorkState),
      })}.`,
    );
    return tokenState;
  }

  return tokenStateWithCanonicalWorkListingBook(tokenState, scopedWorkState);
}

function growthActualBaseNetworkValue(
  records,
  idActivity,
  sales,
  tokenDefinitions,
  tokenMints,
  tokenTransfers = [],
  tokenSales = [],
  cutoffMs = Date.now(),
) {
  const state = emptyGrowthActualBaseState();
  for (const event of growthActualBaseNetworkValueEvents(
    records,
    idActivity,
    sales,
    tokenDefinitions,
    tokenMints,
    tokenTransfers,
    tokenSales,
  )) {
    if (event.createdMs <= cutoffMs) {
      growthActualBaseStateApplyContribution(state, event.contribution);
    }
  }

  const numberFromInteger = (value) => Number(value);
  const valueQ8 = (value) =>
    value * GROWTH_VALUE_MULTIPLE * VALUE_Q8_SCALE;
  const powids = numberFromInteger(state.powids);
  const browserFlowSats = numberFromInteger(state.browserFlowSats);
  const computerEventFlowSats = numberFromInteger(state.computerEventFlowSats);
  const driveFlowSats = numberFromInteger(state.driveFlowSats);
  const idMarketplaceFeeSats = numberFromInteger(state.idMarketplaceFeeSats);
  const idMarketplaceVolumeSats = numberFromInteger(
    state.idMarketplaceVolumeSats,
  );
  const inceptionBondFlowSats = numberFromInteger(
    state.inceptionBondFlowSats,
  );
  const infinityBondFlowSats = numberFromInteger(
    state.infinityBondFlowSats,
  );
  const mailFlowSats = numberFromInteger(state.mailFlowSats);
  const tokenCreationFlowSats = numberFromInteger(
    state.tokenCreationFlowSats,
  );
  const tokenMarketplaceFeeSats = numberFromInteger(
    state.tokenMarketplaceFeeSats,
  );
  const tokenMintFlowSats = numberFromInteger(state.tokenMintFlowSats);
  const tokenSaleVolumeSats = numberFromInteger(state.tokenSaleVolumeSats);
  const tokenSaleFlowSats = tokenSaleVolumeSats;
  const tokenTransferFlowSats = numberFromInteger(
    state.tokenTransferFlowSats,
  );
  const walletFlowSats = tokenTransferFlowSats;
  const marketplaceSaleVolumeSats =
    idMarketplaceVolumeSats + tokenSaleVolumeSats;
  const marketplaceVolumeSats = marketplaceSaleVolumeSats;
  const marketplaceFeeSats =
    idMarketplaceFeeSats + tokenMarketplaceFeeSats;
  const marketplaceMutationFeeSats = marketplaceFeeSats;
  const marketplaceFlowSats =
    marketplaceSaleVolumeSats + marketplaceMutationFeeSats;

  const idValueQ8 =
    (state.powids *
      state.powids *
      GROWTH_ID_DENSITY_NUMERATOR *
      VALUE_Q8_SCALE) /
    GROWTH_ID_DENSITY_DENOMINATOR;
  const browserValueQ8 = valueQ8(state.browserFlowSats);
  const computerEventValueQ8 = valueQ8(state.computerEventFlowSats);
  const driveValueQ8 = valueQ8(state.driveFlowSats);
  const inceptionBondValueQ8 = valueQ8(state.inceptionBondFlowSats);
  const infinityBondValueQ8 = valueQ8(state.infinityBondFlowSats);
  const mailValueQ8 = valueQ8(state.mailFlowSats);
  const marketplaceValueQ8 = valueQ8(
    state.idMarketplaceVolumeSats +
      state.tokenSaleVolumeSats +
      state.idMarketplaceFeeSats +
      state.tokenMarketplaceFeeSats,
  );
  const tokenValueQ8 = valueQ8(
    state.tokenCreationFlowSats + state.tokenMintFlowSats,
  );
  const walletValueQ8 = valueQ8(state.tokenTransferFlowSats);
  const totalQ8 = growthActualBaseStateTotalQ8(state);
  const idSats = q8ToNumber(idValueQ8);
  const mailSats = q8ToNumber(mailValueQ8);
  const inceptionBondSats = q8ToNumber(inceptionBondValueQ8);
  const infinityBondSats = q8ToNumber(infinityBondValueQ8);
  const driveSats = q8ToNumber(driveValueQ8);
  const marketplaceSats = q8ToNumber(marketplaceValueQ8);
  const browserSats = q8ToNumber(browserValueQ8);
  const tokenSats = q8ToNumber(tokenValueQ8);
  const walletSats = q8ToNumber(walletValueQ8);
  const computerEventSats = q8ToNumber(computerEventValueQ8);
  const totalSats = q8ToNumber(totalQ8);
  const years = Math.max(
    0,
    (Math.min(cutoffMs, Date.now()) - GROWTH_MODEL_START_MS) /
      MS_PER_MODEL_YEAR,
  );

  return {
    baseNetworkValueQ8: totalQ8.toString(),
    baseNetworkValueSatsExact: q8ToCanonicalDecimal(totalQ8),
    baseTotalQ8: totalQ8.toString(),
    baseTotalSatsExact: q8ToCanonicalDecimal(totalQ8),
    browserFlowSats,
    browserSats,
    computerEventFlowSats,
    computerEventSats,
    driveFlowSats,
    driveSats,
    idSats,
    inceptionBondFlowSats,
    inceptionBondSats,
    mailFlowSats,
    mailSats,
    marketplaceSats,
    idMarketplaceFeeSats,
    idMarketplaceVolumeSats,
    infinityBondFlowSats,
    infinityBondSats,
    marketplaceFeeSats,
    marketplaceFlowSats,
    marketplaceMutationFeeSats,
    marketplaceSaleVolumeSats,
    marketplaceVolumeSats,
    powids,
    tokenMarketplaceFeeSats,
    tokenCreationFlowSats,
    tokenMintFlowSats,
    tokenSaleFlowSats,
    tokenSaleVolumeSats,
    tokenTransferFlowSats,
    tokenSats,
    walletFlowSats,
    walletSats,
    totalSats,
    totalSatsExact: q8ToCanonicalDecimal(totalQ8),
    totalUsd: growthSatsToUsdAtYears(totalSats, years),
  };
}

function emptyGrowthActualBaseState() {
  return {
    browserFlowSats: 0n,
    computerEventFlowSats: 0n,
    driveFlowSats: 0n,
    idMarketplaceFeeSats: 0n,
    idMarketplaceVolumeSats: 0n,
    inceptionBondFlowSats: 0n,
    infinityBondFlowSats: 0n,
    mailFlowSats: 0n,
    powids: 0n,
    tokenCreationFlowSats: 0n,
    tokenMarketplaceFeeSats: 0n,
    tokenMintFlowSats: 0n,
    tokenSaleVolumeSats: 0n,
    tokenTransferFlowSats: 0n,
  };
}

function growthActualBaseStateApplyContribution(
  state,
  contribution,
  multiplier = 1,
) {
  const field = String(contribution?.field ?? "");
  if (Object.hasOwn(state, field)) {
    state[field] +=
      proofFlowBigInt(contribution?.value) * BigInt(multiplier);
  }
  return state;
}

function growthActualBaseStateAdd(state, addition, multiplier = 1) {
  for (const field of Object.keys(state)) {
    state[field] +=
      proofFlowBigInt(addition?.[field]) * BigInt(multiplier);
  }
  return state;
}

function growthActualBaseStateTotalQ8(state) {
  const marketplaceSaleVolumeSats =
    state.idMarketplaceVolumeSats + state.tokenSaleVolumeSats;
  const marketplaceMutationFeeSats =
    state.idMarketplaceFeeSats + state.tokenMarketplaceFeeSats;
  const marketplaceFlowSats =
    marketplaceSaleVolumeSats + marketplaceMutationFeeSats;
  return (
    (state.powids *
      state.powids *
      GROWTH_ID_DENSITY_NUMERATOR *
      VALUE_Q8_SCALE) /
      GROWTH_ID_DENSITY_DENOMINATOR +
    state.mailFlowSats * GROWTH_VALUE_MULTIPLE * VALUE_Q8_SCALE +
    state.inceptionBondFlowSats * GROWTH_VALUE_MULTIPLE * VALUE_Q8_SCALE +
    state.infinityBondFlowSats * GROWTH_VALUE_MULTIPLE * VALUE_Q8_SCALE +
    state.driveFlowSats * GROWTH_VALUE_MULTIPLE * VALUE_Q8_SCALE +
    marketplaceFlowSats * GROWTH_VALUE_MULTIPLE * VALUE_Q8_SCALE +
    state.browserFlowSats * GROWTH_VALUE_MULTIPLE * VALUE_Q8_SCALE +
    (state.tokenCreationFlowSats + state.tokenMintFlowSats) *
      GROWTH_VALUE_MULTIPLE *
      VALUE_Q8_SCALE +
    state.tokenTransferFlowSats * GROWTH_VALUE_MULTIPLE * VALUE_Q8_SCALE +
    state.computerEventFlowSats * GROWTH_VALUE_MULTIPLE * VALUE_Q8_SCALE
  );
}

function growthActualBaseStateTotalSats(state) {
  return q8ToNumber(growthActualBaseStateTotalQ8(state));
}

function growthActualBaseNetworkValueEvents(
  records,
  idActivity,
  sales,
  tokenDefinitions,
  tokenMints,
  tokenTransfers = [],
  tokenSales = [],
) {
  const events = [];
  const countedMarketplaceMutationActivity = new Set(
    uniqueMarketplaceMutationActivity(
      idActivity,
      MARKETPLACE_MUTATION_KINDS,
    ),
  );
  const addEvent = (source, field, value) => {
    const createdMs = Date.parse(source?.createdAt ?? "");
    if (source?.valid === false || !Number.isFinite(createdMs)) {
      return;
    }
    const blockHeight = Number(source?.blockHeight);
    const blockIndex = Number(source?.blockIndex);
    const exactPositionInteger = (name) => {
      const candidate = source?.[name];
      return candidate !== undefined &&
        candidate !== null &&
        candidate !== "" &&
        Number.isSafeInteger(Number(candidate)) &&
        Number(candidate) >= 0
        ? Number(candidate)
        : null;
    };
    const protocolVout = exactPositionInteger("protocolVout");
    const recordOrdinal = exactPositionInteger("recordOrdinal");
    if (
      source?.confirmed === true &&
      Number.isSafeInteger(blockHeight) &&
      blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT &&
      (
        !Number.isSafeInteger(blockIndex) ||
        blockIndex < 0 ||
        protocolVout === null ||
        recordOrdinal === null
      )
    ) {
      throw new Error(
        "Canonical AMO V5 network-value event position is incomplete.",
      );
    }
    events.push({
      blockHash: String(source?.blockHash ?? "").trim().toLowerCase(),
      blockHeight,
      blockIndex,
      contribution: { field, value: proofFlowBigInt(value) },
      createdMs,
      protocolVout,
      recordOrdinal,
      source,
      txid: String(source?.txid ?? "").trim().toLowerCase(),
    });
  };

  for (const record of Array.isArray(records) ? records : []) {
    if (record?.confirmed) {
      addEvent(record, "powids", 1);
    }
  }
  for (const item of Array.isArray(idActivity) ? idActivity : []) {
    if (!item?.confirmed) {
      continue;
    }
    const sats = activityAmountSatsBigInt(item);
    if (
      (item.kind === "mail" || item.kind === "reply") &&
      !isBondActivityItem(item) &&
      !isBrowserActivityItem(item)
    ) {
      addEvent(item, "mailFlowSats", sats);
    } else if (isInceptionBondActivityItem(item)) {
      addEvent(item, "inceptionBondFlowSats", sats);
    } else if (isInfinityBondActivityItem(item)) {
      addEvent(item, "infinityBondFlowSats", sats);
    } else if (isBrowserActivityItem(item)) {
      addEvent(item, "browserFlowSats", sats);
    } else if (item.kind === "file" && !isBrowserActivityItem(item)) {
      addEvent(item, "driveFlowSats", sats);
    } else if (
      ID_MARKETPLACE_MUTATION_KINDS.has(item.kind) &&
      countedMarketplaceMutationActivity.has(item)
    ) {
      addEvent(
        item,
        "idMarketplaceFeeSats",
        marketplaceMutationPaymentSatsBigInt(item),
      );
    } else if (
      TOKEN_MARKETPLACE_MUTATION_KINDS.has(item.kind) &&
      countedMarketplaceMutationActivity.has(item)
    ) {
      addEvent(
        item,
        "tokenMarketplaceFeeSats",
        marketplaceMutationPaymentSatsBigInt(item),
      );
    } else if (!activityKindHasDedicatedGrowthBucket(item)) {
      addEvent(item, "computerEventFlowSats", sats);
    }
  }
  for (const sale of publicMarketplaceSales(Array.isArray(sales) ? sales : [])) {
    if (sale?.confirmed) {
      addEvent(sale, "idMarketplaceVolumeSats", sale.priceSats);
    }
  }
  for (const token of Array.isArray(tokenDefinitions) ? tokenDefinitions : []) {
    if (token?.confirmed) {
      addEvent(token, "tokenCreationFlowSats", token.creationFeeSats);
    }
  }
  for (const mint of Array.isArray(tokenMints) ? tokenMints : []) {
    if (mint?.confirmed && !BOND_TOKEN_IDS.has(mint.tokenId)) {
      addEvent(mint, "tokenMintFlowSats", mint.paidSats);
    }
  }
  for (const transfer of Array.isArray(tokenTransfers) ? tokenTransfers : []) {
    if (transfer?.confirmed) {
      addEvent(transfer, "tokenTransferFlowSats", transfer.paidSats);
    }
  }
  for (const sale of Array.isArray(tokenSales) ? tokenSales : []) {
    if (sale?.confirmed) {
      addEvent(sale, "tokenSaleVolumeSats", sale.priceSats);
    }
  }

  return events;
}

function growthActualBaseNetworkValueAtProvider(
  records,
  idActivity,
  sales,
  tokenDefinitions,
  tokenMints,
  tokenTransfers = [],
  tokenSales = [],
) {
  const events = growthActualBaseNetworkValueEvents(
    records,
    idActivity,
    sales,
    tokenDefinitions,
    tokenMints,
    tokenTransfers,
    tokenSales,
  );

  events.sort((left, right) => left.createdMs - right.createdMs);
  let cursor = 0;
  let cursorMs = Number.NEGATIVE_INFINITY;
  let state = emptyGrowthActualBaseState();
  const reset = () => {
    cursor = 0;
    cursorMs = Number.NEGATIVE_INFINITY;
    state = emptyGrowthActualBaseState();
  };

  const lookupQ8 = (atMs) => {
    const targetMs = Number(atMs);
    if (!Number.isFinite(targetMs)) {
      return 0n;
    }
    if (targetMs < cursorMs) {
      reset();
    }
    while (cursor < events.length && events[cursor].createdMs <= targetMs) {
      growthActualBaseStateApplyContribution(
        state,
        events[cursor].contribution,
      );
      cursor += 1;
    }
    cursorMs = targetMs;
    return growthActualBaseStateTotalQ8(state);
  };
  const provider = (atMs) => q8ToNumber(lookupQ8(atMs));
  provider.q8At = lookupQ8;
  let canonicalBeforeProvider = null;
  const beforeCanonicalItemProvider = () => {
    if (!canonicalBeforeProvider) {
      canonicalBeforeProvider =
        growthActualBaseNetworkValueBeforeCanonicalItemProvider(
          {
            idActivity,
            records,
            sales,
            tokenDefinitions,
            tokenMints,
            tokenSales,
            tokenTransfers,
          },
          provider,
        );
    }
    return canonicalBeforeProvider;
  };
  provider.beforeCanonicalItem = (source, createdMs) =>
    beforeCanonicalItemProvider()(source, createdMs);
  provider.q8BeforeCanonicalItem = (source, createdMs) =>
    beforeCanonicalItemProvider().q8At(source, createdMs);
  return provider;
}

function growthActualNetworkValue(
  records,
  idActivity,
  sales,
  tokenDefinitions,
  tokenMints,
  tokenTransfers = [],
  tokenSales = [],
  cutoffMs = Date.now(),
  options = {},
) {
  const baseValue = growthActualBaseNetworkValue(
    records,
    idActivity,
    sales,
    tokenDefinitions,
    tokenMints,
    tokenTransfers,
    tokenSales,
    cutoffMs,
  );
  const baseValueAt = growthActualBaseNetworkValueAtProvider(
    records,
    idActivity,
    sales,
    tokenDefinitions,
    tokenMints,
    tokenTransfers,
    tokenSales,
  );
  const creditValue = creditNetworkValueMetrics({
    baseValueAt,
    baseValueQ8At: baseValueAt.q8At,
    canonicalMinerFeeCoverage: options.canonicalMinerFeeCoverage,
    confirmedActivity: idActivity,
    cutoffMs,
    tokenDefinitions,
    tokenMints,
    tokenSales,
    tokenTransfers,
  });
  const baseTotalQ8 = BigInt(baseValue.baseTotalQ8 ?? "0");
  const frozenTotalQ8 =
    baseTotalQ8 + BigInt(creditValue.creditEventFrozenValueQ8 ?? "0");
  const liveTotalQ8 =
    baseTotalQ8 + BigInt(creditValue.creditEventLiveValueQ8 ?? "0");
  const frozenTotalSats = q8ToNumber(frozenTotalQ8);
  const liveTotalSats = q8ToNumber(liveTotalQ8);
  const totalSats = liveTotalSats;
  const years = Math.max(
    0,
    (Math.min(cutoffMs, Date.now()) - GROWTH_MODEL_START_MS) /
      MS_PER_MODEL_YEAR,
  );

  return {
    ...baseValue,
    workNetworkValueAccountingModel: WORK_NETWORK_VALUE_ACCOUNTING_MODEL,
    ...(creditValue.creditMinerFeeAccountingModel
      ? {
          creditMinerFeeAccountingModel:
            creditValue.creditMinerFeeAccountingModel,
          creditMinerFeeCoverage: creditValue.creditMinerFeeCoverage,
        }
      : {}),
    creditMinerFeeFlowSats: creditValue.creditMinerFeeFlowSats,
    creditEventFrozenValueSats: creditValue.creditEventFrozenValueSats,
    ...(creditValue.creditEventFrozenValueQ8
      ? { creditEventFrozenValueQ8: creditValue.creditEventFrozenValueQ8 }
      : {}),
    creditEventLiveValueSats: creditValue.creditEventLiveValueSats,
    creditEventLiveValueQ8: creditValue.creditEventLiveValueQ8,
    creditMarketplaceMutationFlowSats:
      creditValue.creditMarketplaceMutationFlowSats,
    creditMovementFrozenValueSats:
      creditValue.creditMovementFrozenValueSats,
    ...(creditValue.creditMovementFrozenValueQ8
      ? {
          creditMovementFrozenValueQ8:
            creditValue.creditMovementFrozenValueQ8,
        }
      : {}),
    creditMovementLiveValueSats: creditValue.creditMovementLiveValueSats,
    creditMovementLiveValueQ8: creditValue.creditMovementLiveValueQ8,
    creditNetworkValueSats: creditValue.creditNetworkValueSats,
    creditNetworkValueQ8: creditValue.creditNetworkValueQ8,
    creditFrozenNetworkValueSats: creditValue.creditFrozenNetworkValueSats,
    creditFrozenNetworkValueQ8: creditValue.creditFrozenNetworkValueQ8,
    creditLiveNetworkValueSats: creditValue.creditLiveNetworkValueSats,
    creditLiveNetworkValueQ8: creditValue.creditLiveNetworkValueQ8,
    creditProofPaymentFlowSats: creditValue.creditProofPaymentFlowSats,
    creditRegistryMutationFlowSats:
      creditValue.creditRegistryMutationFlowSats,
    creditSalePaymentFlowSats: creditValue.creditSalePaymentFlowSats,
    baseNetworkValueQ8: baseTotalQ8.toString(),
    baseNetworkValueSats: q8ToCanonicalDecimal(baseTotalQ8),
    baseNetworkValueSatsApproximate: q8ToNumber(baseTotalQ8),
    baseNetworkValueSatsExact: q8ToCanonicalDecimal(baseTotalQ8),
    baseTotalQ8: baseTotalQ8.toString(),
    baseTotalSats: q8ToCanonicalDecimal(baseTotalQ8),
    baseTotalSatsApproximate: q8ToNumber(baseTotalQ8),
    baseTotalSatsExact: q8ToCanonicalDecimal(baseTotalQ8),
    frozenNetworkValueQ8: frozenTotalQ8.toString(),
    frozenNetworkValueSats: q8ToCanonicalDecimal(frozenTotalQ8),
    frozenNetworkValueSatsApproximate: frozenTotalSats,
    frozenNetworkValueSatsExact: q8ToCanonicalDecimal(frozenTotalQ8),
    frozenTotalQ8: frozenTotalQ8.toString(),
    frozenTotalSats: q8ToCanonicalDecimal(frozenTotalQ8),
    frozenTotalSatsApproximate: frozenTotalSats,
    frozenTotalSatsExact: q8ToCanonicalDecimal(frozenTotalQ8),
    liveNetworkValueQ8: liveTotalQ8.toString(),
    liveNetworkValueSats: q8ToCanonicalDecimal(liveTotalQ8),
    liveNetworkValueSatsApproximate: liveTotalSats,
    liveNetworkValueSatsExact: q8ToCanonicalDecimal(liveTotalQ8),
    liveTotalQ8: liveTotalQ8.toString(),
    liveTotalSats: q8ToCanonicalDecimal(liveTotalQ8),
    liveTotalSatsApproximate: liveTotalSats,
    liveTotalSatsExact: q8ToCanonicalDecimal(liveTotalQ8),
    networkValueQ8: liveTotalQ8.toString(),
    networkValueSats: q8ToCanonicalDecimal(liveTotalQ8),
    networkValueSatsApproximate: liveTotalSats,
    networkValueSatsExact: q8ToCanonicalDecimal(liveTotalQ8),
    totalQ8: liveTotalQ8.toString(),
    totalSats: q8ToCanonicalDecimal(liveTotalQ8),
    totalSatsApproximate: totalSats,
    totalSatsExact: q8ToCanonicalDecimal(liveTotalQ8),
    totalUsd: growthSatsToUsdAtYears(totalSats, years),
  };
}

function compactGrowthEventTimes(eventTimes) {
  const sorted = [...eventTimes].sort(
    (left, right) => left.createdMs - right.createdMs,
  );
  if (sorted.length <= MAX_GROWTH_ACTUAL_CHART_EVENTS) {
    return sorted;
  }

  const indexes = new Set([0, sorted.length - 1]);
  for (let index = 0; index < MAX_GROWTH_ACTUAL_CHART_EVENTS; index += 1) {
    indexes.add(
      Math.round(
        (index * (sorted.length - 1)) /
          Math.max(1, MAX_GROWTH_ACTUAL_CHART_EVENTS - 1),
      ),
    );
  }

  return [...indexes]
    .sort((left, right) => left - right)
    .map((index) => sorted[index])
    .filter(Boolean);
}

function growthActualLiveTotalSatsAtProvider(
  records,
  idActivity,
  sales,
  tokenDefinitions,
  tokenMints,
  tokenTransfers = [],
  tokenSales = [],
  options = {},
) {
  const baseValueForCredit = growthActualBaseNetworkValueAtProvider(
    records,
    idActivity,
    sales,
    tokenDefinitions,
    tokenMints,
    tokenTransfers,
    tokenSales,
  );
  const baseValueAt = growthActualBaseNetworkValueAtProvider(
    records,
    idActivity,
    sales,
    tokenDefinitions,
    tokenMints,
    tokenTransfers,
    tokenSales,
  );
  const baseCollections = {
    idActivity,
    records,
    sales,
    tokenDefinitions,
    tokenMints,
    tokenSales,
    tokenTransfers,
  };
  const baseValueBeforeCanonicalItem =
    growthActualBaseNetworkValueBeforeCanonicalItemProvider(
      baseCollections,
      baseValueForCredit,
      options.canonicalBaseLookupDiagnostics,
    );
  const exactBaseValueQ8At =
    typeof baseValueAt?.q8At === "function"
      ? baseValueAt.q8At
      : (atMs) => decimalValueToQ8(baseValueAt(atMs)) ?? 0n;
  const exactBaseValueBeforeCanonicalItemQ8 =
    typeof baseValueBeforeCanonicalItem?.q8At === "function"
      ? baseValueBeforeCanonicalItem.q8At
      : (source, createdMs) =>
          decimalValueToQ8(
            baseValueBeforeCanonicalItem(source, createdMs),
          ) ?? 0n;
  const tokensById = new Map(
    (Array.isArray(tokenDefinitions) ? tokenDefinitions : [])
      .filter(
        (token) =>
          token?.valid !== false && tokenCanUseCreditNetworkFloor(token),
      )
      .map((token) => [String(token.tokenId ?? "").toLowerCase(), token]),
  );
  if (tokensById.size === 0) {
    return (atMs) => numericValue(baseValueAt(atMs));
  }
  const inceptionWorkMovementOracleByIdentity =
    canonicalInceptionWorkMovementOracleByIdentity(
      tokenMints,
      tokenTransfers,
    );

  const activityByRecord = new Map();
  const activityByTxid = new Map();
  for (const item of Array.isArray(idActivity) ? idActivity : []) {
    const txid = String(item?.txid ?? "").toLowerCase();
    if (
      !item?.confirmed ||
      item?.valid === false ||
      !isTokenActivityItem(item) ||
      !/^[0-9a-f]{64}$/u.test(txid) ||
      !tokensById.has(String(item?.tokenId ?? "").toLowerCase())
    ) {
      continue;
    }
    const recordIdentity = creditReplayRecordIdentity(item);
    if (!recordIdentity) {
      continue;
    }
    const current = activityByRecord.get(recordIdentity);
    if (
      !current ||
      numericValue(item?.minerFeeSats) > numericValue(current?.minerFeeSats) ||
      numericValue(item?.frozenNetworkValueSats) >
        numericValue(current?.frozenNetworkValueSats)
    ) {
      activityByRecord.set(recordIdentity, item);
    }
    const currentTxActivity = activityByTxid.get(txid);
    if (
      !currentTxActivity ||
      numericValue(item?.minerFeeSats) >
        numericValue(currentTxActivity?.minerFeeSats) ||
      numericValue(item?.frozenNetworkValueSats) >
        numericValue(currentTxActivity?.frozenNetworkValueSats)
    ) {
      activityByTxid.set(txid, item);
    }
  }

  const movementEvents = [];
  const movementRecordIdentities = new Set();
  const addMovementEvent = (item, kind) => {
    const token = tokensById.get(String(item?.tokenId ?? "").toLowerCase());
    const txid = String(item?.txid ?? "").toLowerCase();
    const createdMs = creditValueEventMs(item);
    const workMovement = isWorkTokenId(item?.tokenId);
    const amountSubatoms = workMovement
      ? kind === "sale"
        ? canonicalTokenSaleLedgerAmount(WORK_TOKEN_ID, item, {
            workAmountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
          })
        : workSubatomsBigIntFromRecord(item, {
            convertLegacyAtoms: true,
          })
      : null;
    const amountUnits = workMovement
      ? null
      : integerBigInt(item?.amount, { allowZero: false });
    if (
      !token ||
      !item?.confirmed ||
      item?.valid === false ||
      !/^[0-9a-f]{64}$/u.test(txid) ||
      !Number.isFinite(createdMs) ||
      (
        workMovement
          ? amountSubatoms === null || amountSubatoms <= 0n
          : amountUnits === null
      )
    ) {
      return;
    }
    movementEvents.push({
      ...(amountSubatoms === null
        ? {}
        : {
            amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
            amountSubatoms: amountSubatoms.toString(),
            decimals: WORK_SUBATOM_DECIMALS,
            precisionModel: WORK_PRECISION_V2_MODEL,
            unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
          }),
      ...(amountUnits === null ? {} : { amountUnits: amountUnits.toString() }),
      createdMs,
      kind,
      order: 1,
      source: item,
      token,
      txid,
    });
    const recordIdentity = creditReplayRecordIdentity(item);
    if (recordIdentity) {
      movementRecordIdentities.add(recordIdentity);
    }
  };
  for (const mint of Array.isArray(tokenMints) ? tokenMints : []) {
    addMovementEvent(mint, "mint");
  }
  for (const transfer of Array.isArray(tokenTransfers) ? tokenTransfers : []) {
    addMovementEvent(transfer, "transfer");
  }
  for (const sale of Array.isArray(tokenSales) ? tokenSales : []) {
    addMovementEvent(sale, "sale");
  }

  const mutationEvents = [];
  for (const item of activityByRecord.values()) {
    const txid = String(item?.txid ?? "").toLowerCase();
    const kind = String(item?.kind ?? "");
    const token = tokensById.get(String(item?.tokenId ?? "").toLowerCase());
    const createdMs = creditValueEventMs(item);
    if (
      !token ||
      !Number.isFinite(createdMs) ||
      movementRecordIdentities.has(creditReplayRecordIdentity(item)) ||
      ![
        "token-create",
        "token-listing",
        "token-listing-sealed",
        "token-listing-closed",
      ].includes(kind)
    ) {
      continue;
    }
    const proofPaymentSats =
      kind === "token-create"
        ? numericValue(item?.proofPaymentSats ?? item?.amountSats)
        : 0;
    const marketplaceMutationFeeSats =
      TOKEN_MARKETPLACE_MUTATION_KINDS.has(kind)
        ? numericValue(item?.marketplaceMutationFeeSats ?? item?.amountSats) ||
          TOKEN_MIN_MUTATION_PRICE_SATS
        : 0;
    mutationEvents.push({
      amount: 0,
      createdMs,
      kind: kind.replace(/^token-/u, ""),
      marketplaceMutationFeeSats,
      minerFeeSats: numericValue(item?.minerFeeSats),
      order: 2,
      proofPaymentSats,
      registryMutationFeeSats: 0,
      salePaymentSats: 0,
      source: item,
      token,
      txid,
    });
  }

  const tokenMaxSupplyUnits = (token) => {
    if (isWorkTokenId(token?.tokenId)) {
      return BigInt(WORK_TOKEN_MAX_SUPPLY);
    }
    return integerBigInt(token?.maxSupply, { allowZero: false });
  };
  const movementValueAtNetworkQ8 = (event, networkValueQ8) => {
    const supply = tokenMaxSupplyUnits(event.token);
    if (supply === null || supply <= 0n || networkValueQ8 < 0n) {
      return null;
    }
    if (event.amountSubatoms) {
      return (
        (BigInt(event.amountSubatoms) * networkValueQ8) /
        (supply * WORK_SUBATOM_UNIT_SCALE)
      );
    }
    if (event.amountUnits) {
      return (BigInt(event.amountUnits) * networkValueQ8) / supply;
    }
    return event.amount === 0 ? 0n : null;
  };
  let cumulativeFrozenCreditValueQ8 = 0n;
  const countedMinerFeeTxids = new Set();
  const replayEvents = assertUniqueCreditValueReplayPositions([
    ...movementEvents,
    ...mutationEvents,
  ])
    .sort(compareCreditValueReplayEvents)
    .map((event) => {
      const baseBeforeQ8 = exactBaseValueBeforeCanonicalItemQ8(
        event.source,
        event.createdMs,
      );
      const networkValueBeforeEventQ8 =
        baseBeforeQ8 + cumulativeFrozenCreditValueQ8;
      const maxSupply = tokenMaxSupplyUnits(event.token);
      const inceptionWorkMovementOracle =
        event.kind === "transfer"
          ? inceptionWorkMovementOracleByIdentity.get(
              creditMovementIdentity(event.source, event.kind),
            )
          : null;
      const oracleNetworkValueQ8 = canonicalNonNegativeIntegerText(
        inceptionWorkMovementOracle?.workNetworkValueQ8,
      );
      const liveNetworkValueBeforeEventQ8 = oracleNetworkValueQ8
        ? BigInt(oracleNetworkValueQ8)
        : networkValueBeforeEventQ8;
      const creditValueAtConfirmQ8 =
        movementValueAtNetworkQ8(
          event,
          liveNetworkValueBeforeEventQ8,
        ) ?? 0n;
      const recordActivity = activityByRecord.get(
        creditReplayRecordIdentity(event.source),
      );
      const transactionActivity = activityByTxid.get(event.txid);
      const activity =
        transactionActivity?.canonicalMinerFeeCovered === true
          ? transactionActivity
          : recordActivity ?? transactionActivity;
      const transactionMinerFeeSats = proofFlowBigInt(
        creditReplayTransactionMinerFeeSats(
          event,
          activity,
        ),
      );
      const minerFeeSats = countedMinerFeeTxids.has(event.txid)
        ? 0n
        : transactionMinerFeeSats;
      countedMinerFeeTxids.add(event.txid);
      const proofPaymentSats =
        event.kind === "mint"
          ? proofFlowBigInt(event.source?.paidSats)
          : proofFlowBigInt(event.proofPaymentSats);
      const registryMutationFeeSats =
        event.kind === "transfer"
          ? proofFlowBigInt(event.source?.paidSats)
          : proofFlowBigInt(event.registryMutationFeeSats);
      const marketplaceMutationFeeSats =
        event.kind === "sale"
          ? proofFlowBigInt(event.source?.marketplaceMutationFeeSats) ||
            BigInt(TOKEN_MIN_MUTATION_PRICE_SATS)
          : proofFlowBigInt(event.marketplaceMutationFeeSats);
      const salePaymentSats =
        event.kind === "sale"
          ? proofFlowBigInt(event.source?.priceSats)
          : 0n;
      const fixedEventFlowSats =
        proofPaymentSats +
        registryMutationFeeSats +
        marketplaceMutationFeeSats +
        salePaymentSats +
        minerFeeSats;
      const fixedEventFlowQ8 = fixedEventFlowSats * VALUE_Q8_SCALE;
      const frozenNetworkValueQ8 =
        creditValueAtConfirmQ8 + fixedEventFlowQ8;
      cumulativeFrozenCreditValueQ8 += frozenNetworkValueQ8;
      const movementFactorNumerator = event.amountSubatoms
        ? BigInt(event.amountSubatoms)
        : event.amountUnits
          ? BigInt(event.amountUnits)
          : 0n;
      const movementFactorDenominator =
        maxSupply && maxSupply > 0n
          ? event.amountSubatoms
            ? maxSupply * WORK_SUBATOM_UNIT_SCALE
            : maxSupply
          : 1n;
      return {
        createdMs: event.createdMs,
        fixedEventFlowQ8: fixedEventFlowQ8.toString(),
        frozenNetworkValueQ8: frozenNetworkValueQ8.toString(),
        movementFactorDenominator:
          movementFactorDenominator.toString(),
        movementFactorNumerator: movementFactorNumerator.toString(),
      };
    });

  const gcd = (left, right) => {
    let a = left < 0n ? -left : left;
    let b = right < 0n ? -right : right;
    while (b !== 0n) {
      const remainder = a % b;
      a = b;
      b = remainder;
    }
    return a;
  };
  let cursor = 0;
  let frozenCreditQ8 = 0n;
  let fixedCreditQ8 = 0n;
  let movementFactorNumerator = 0n;
  let movementFactorDenominator = 1n;
  const replayTimeline = canonicalReplayTimeline(replayEvents);
  const reset = () => {
    cursor = 0;
    frozenCreditQ8 = 0n;
    fixedCreditQ8 = 0n;
    movementFactorNumerator = 0n;
    movementFactorDenominator = 1n;
  };
  return (atMs) => {
    const targetMs = Number(atMs);
    if (!Number.isFinite(targetMs)) {
      return 0;
    }
    const prefixLength = canonicalReplayPrefixLengthAtMs(
      replayTimeline,
      targetMs,
    );
    if (prefixLength < cursor) {
      reset();
    }
    while (cursor < prefixLength) {
      const event = replayEvents[cursor];
      frozenCreditQ8 += BigInt(event.frozenNetworkValueQ8);
      fixedCreditQ8 += BigInt(event.fixedEventFlowQ8);
      const eventNumerator = BigInt(event.movementFactorNumerator);
      const eventDenominator = BigInt(event.movementFactorDenominator);
      if (eventNumerator > 0n && eventDenominator > 0n) {
        const commonDenominator = gcd(
          movementFactorDenominator,
          eventDenominator,
        );
        const nextNumerator =
          movementFactorNumerator *
            (eventDenominator / commonDenominator) +
          eventNumerator *
            (movementFactorDenominator / commonDenominator);
        const nextDenominator =
          (movementFactorDenominator / commonDenominator) *
          eventDenominator;
        const commonFactor = gcd(nextNumerator, nextDenominator);
        movementFactorNumerator = nextNumerator / commonFactor;
        movementFactorDenominator = nextDenominator / commonFactor;
      }
      cursor += 1;
    }
    const baseNowQ8 = exactBaseValueQ8At(targetMs);
    const liveMovementQ8 =
      movementFactorNumerator > 0n
        ? (
            (baseNowQ8 + frozenCreditQ8) *
            movementFactorNumerator
          ) / movementFactorDenominator
        : 0n;
    return q8ToNumber(
      baseNowQ8 + liveMovementQ8 + fixedCreditQ8,
    );
  };
}

function growthActualValuePoints(
  records,
  idActivity,
  sales,
  tokenDefinitions,
  tokenMints,
  tokenTransfers = [],
  tokenSales = [],
  options = {},
) {
  // Display time remains wall-clock ordered even when a confirmed block's
  // miner timestamp is slightly ahead of the API host. Exact confirmed-tip
  // aggregate math is reconciled separately by workFloorPayloadFromState.
  const timelineCutoffMs = Date.now();
  const startMs = Math.max(
    options.startMs ?? GROWTH_MODEL_START_MS,
    GROWTH_MODEL_START_MS,
  );
  const startYears = Math.max(
    0,
    (startMs - GROWTH_MODEL_START_MS) / MS_PER_MODEL_YEAR,
  );
  const eventTimes = [];
  const addEventTime = (createdAt, label) => {
    const createdMs = Date.parse(createdAt);
    if (
      Number.isFinite(createdMs) &&
      createdMs >= startMs &&
      createdMs <= timelineCutoffMs
    ) {
      eventTimes.push({ createdMs, label });
    }
  };

  for (const record of records) {
    if (record.confirmed && record.valid !== false) {
      addEventTime(record.createdAt, `${record.id}@proofofwork.me`);
    }
  }

  for (const item of idActivity) {
    if (item.confirmed && item.valid !== false) {
      addEventTime(item.createdAt, item.title);
    }
  }

  for (const sale of publicMarketplaceSales(sales)) {
    if (sale.confirmed && sale.valid !== false) {
      addEventTime(sale.createdAt, `${sale.id}@proofofwork.me sale`);
    }
  }

  for (const token of tokenDefinitions) {
    if (token.confirmed && token.valid !== false) {
      addEventTime(token.createdAt, `${token.ticker} credit created`);
    }
  }

  for (const mint of tokenMints) {
    if (mint.confirmed && mint.valid !== false) {
      addEventTime(mint.createdAt, `${mint.ticker} credit mint`);
    }
  }

  for (const transfer of tokenTransfers) {
    if (transfer.confirmed && transfer.valid !== false) {
      addEventTime(transfer.createdAt, `${transfer.ticker} credit transfer`);
    }
  }

  for (const sale of tokenSales) {
    if (sale.confirmed && sale.valid !== false) {
      addEventTime(sale.createdAt, `${sale.ticker} credit sale`);
    }
  }

  // Replaying the full ledger once per chart point is quadratic at current
  // chain volume. This provider preserves the same frozen/live credit math
  // while advancing the canonical event stream only once.
  const totalSatsAt = growthActualLiveTotalSatsAtProvider(
    records,
    idActivity,
    sales,
    tokenDefinitions,
    tokenMints,
    tokenTransfers,
    tokenSales,
    options,
  );
  const points = [];
  const startValueSats = totalSatsAt(startMs);
  points.push({
    label: options.startLabel ?? "Model start",
    sats: startValueSats,
    usd: growthSatsToUsdAtYears(startValueSats, startYears),
    years: startYears,
  });

  for (const { createdMs, label } of compactGrowthEventTimes(eventTimes)) {
    const valueSats = totalSatsAt(createdMs);
    points.push({
      label,
      sats: valueSats,
      usd: growthSatsToUsdAtYears(
        valueSats,
        Math.max(0, (createdMs - GROWTH_MODEL_START_MS) / MS_PER_MODEL_YEAR),
      ),
      years: Math.max(
        0,
        (createdMs - GROWTH_MODEL_START_MS) / MS_PER_MODEL_YEAR,
      ),
    });
  }

  const elapsed = Math.max(
    0,
    (timelineCutoffMs - GROWTH_MODEL_START_MS) / MS_PER_MODEL_YEAR,
  );
  const nowValueSats = totalSatsAt(timelineCutoffMs);
  const lastPoint = points[points.length - 1];
  if (
    !lastPoint ||
    lastPoint.sats !== nowValueSats ||
    lastPoint.years < elapsed
  ) {
    points.push({
      label: "Real now",
      sats: nowValueSats,
      usd: growthSatsToUsdAtYears(nowValueSats, elapsed),
      years: elapsed,
    });
  }

  return points;
}

function growthActivityKindLabel(kind) {
  if (
    kind === "id-register" ||
    kind === "id-update" ||
    kind === "id-transfer"
  ) {
    return "ID";
  }

  if (
    kind === "id-list" ||
    kind === "id-seal" ||
    kind === "id-delist" ||
    kind === "id-buy" ||
    kind === "token-listing" ||
    kind === "token-listing-sealed" ||
    kind === "token-listing-closed" ||
    kind === "token-sale"
  ) {
    return "AMO";
  }

  if (kind === "file") {
    return "Drive";
  }

  if (kind === "token-transfer" || kind === "token-event-invalid") {
    return "Wallet";
  }

  if (kind === "infinity-bond") {
    return "Infinity Bond";
  }

  if (kind === "inception-bond") {
    return "Inception Bond";
  }

  if (
    kind === "token-create" ||
    kind === "token-mint"
  ) {
    return "Credit";
  }

  return kind === "reply" ? "Mail reply" : "Mail";
}

function confirmedComputerActionCount(
  records,
  idActivity,
  tokenDefinitions,
  tokenMints,
  tokenTransfers = [],
  tokenSales = [],
) {
  const txids = new Set();
  const add = (confirmed, txid) => {
    if (confirmed && txid) {
      txids.add(txid);
    }
  };

  records.forEach((record) => add(record.confirmed, record.txid));
  idActivity.forEach((item) => add(item.confirmed, item.txid));
  tokenDefinitions.forEach((token) => add(token.confirmed, token.txid));
  tokenMints.forEach((mint) => add(mint.confirmed, mint.txid));
  tokenTransfers.forEach((transfer) => add(transfer.confirmed, transfer.txid));
  tokenSales.forEach((sale) => add(sale.confirmed, sale.txid));

  return txids.size;
}

function growthRealEventItems(
  records,
  idActivity,
  sales,
  tokenDefinitions,
  tokenMints,
  tokenTransfers = [],
  tokenSales = [],
) {
  const events = new Map();
  const setEvent = (event) => {
    events.set(event.key, event);
  };

  for (const record of records) {
    if (!record.confirmed) {
      continue;
    }

    setEvent({
      amountLabel: `${numericValue(
        record.amountSats ?? ID_REGISTRATION_PRICE_SATS,
      ).toLocaleString()} proofs`,
      createdAt: record.createdAt,
      detail: `${record.id}@proofofwork.me joined the confirmed ID graph.`,
      key: record.txid,
      kind: "ID",
      network: record.network,
      title: "ID registered",
      txid: record.txid,
    });
  }

  for (const item of idActivity) {
    if (!item.confirmed) {
      continue;
    }

    setEvent({
      amountLabel: item.amountSats
        ? `${item.amountSats.toLocaleString()} proofs`
        : "Confirmed",
      createdAt: item.createdAt,
      detail: item.detail || item.description,
      key: item.txid,
      kind: isBondActivityItem(item)
        ? bondActivityConfig(item)?.displayName ?? "Bond"
        : isBrowserActivityItem(item)
        ? "Browser"
        : growthActivityKindLabel(item.kind),
      network: item.network,
      title: item.id ? `${item.title}: ${item.id}@proofofwork.me` : item.title,
      txid: item.txid,
    });
  }

  for (const sale of publicMarketplaceSales(sales)) {
    if (!sale.confirmed) {
      continue;
    }

    setEvent({
      amountLabel: `${sale.priceSats.toLocaleString()} sale proofs`,
      createdAt: sale.createdAt,
      detail: `${sale.id}@proofofwork.me transferred from ${shortAddress(sale.sellerAddress)} to ${shortAddress(sale.buyerAddress)}.`,
      key: sale.txid,
      kind: "AMO",
      network: sale.network,
      title: "AMO sale",
      txid: sale.txid,
    });
  }

  for (const token of tokenDefinitions) {
    if (!token.confirmed || BOND_TOKEN_IDS.has(token.tokenId)) {
      continue;
    }

    setEvent({
      amountLabel: `${token.creationFeeSats.toLocaleString()} creation proofs`,
      createdAt: token.createdAt,
      detail: `${token.ticker} created with ${token.maxSupply.toLocaleString()} max supply and registry ${shortAddress(token.registryAddress)}.`,
      key: token.txid,
      kind: "Credit",
      network: token.network,
      title: "Credit created",
      txid: token.txid,
    });
  }

  for (const mint of tokenMints) {
    if (!mint.confirmed || BOND_TOKEN_IDS.has(mint.tokenId)) {
      continue;
    }

    setEvent({
      amountLabel: `${mint.paidSats.toLocaleString()} mint proofs`,
      createdAt: mint.createdAt,
      detail: `${mint.amount.toLocaleString()} ${mint.ticker} minted by ${shortAddress(mint.minterAddress)}.`,
      key: mint.txid,
      kind: "Credit",
      network: mint.network,
      title: "Credit mint",
      txid: mint.txid,
    });
  }

  for (const transfer of tokenTransfers) {
    if (!transfer.confirmed) {
      continue;
    }

    setEvent({
      amountLabel: `${transfer.paidSats.toLocaleString()} registry proofs`,
      createdAt: transfer.createdAt,
      detail: `${transfer.amount.toLocaleString()} ${transfer.ticker} moved from ${shortAddress(transfer.senderAddress)} to ${shortAddress(transfer.recipientAddress)}.`,
      key: transfer.txid,
      kind: "Wallet",
      network: transfer.network,
      title: "Wallet transfer",
      txid: transfer.txid,
    });
  }

  for (const sale of tokenSales) {
    if (!sale.confirmed) {
      continue;
    }

    setEvent({
      amountLabel: `${sale.priceSats.toLocaleString()} sale proofs`,
      createdAt: sale.createdAt,
      detail: `${sale.amount.toLocaleString()} ${sale.ticker} bought by ${shortAddress(sale.buyerAddress)} from ${shortAddress(sale.sellerAddress)}.`,
      key: sale.txid,
      kind: "AMO",
      network: sale.network,
      title: "AMO sale",
      txid: sale.txid,
    });
  }

  return [...events.values()].sort(
    (left, right) => Date.parse(right.createdAt) - Date.parse(left.createdAt),
  );
}

