async function workFloorPayload(network, fresh = false) {
  if (network !== "livenet") {
    return emptyWorkFloorPayload(network);
  }

  const emptyRegistryState = {
    activity: [],
    indexedAt: new Date().toISOString(),
    listings: [],
    network,
    pendingEvents: [],
    records: [],
    registryAddress: registryAddressForNetwork(network),
    sales: [],
    source: mempoolBase(network),
  };
  const [registryState, computerActivity, tokenState, workTokenState, btcUsdQuote] =
    await Promise.all([
      fresh
        ? safeRegistryPayload(network)
        : fastJsonBackedPayload(
            `registry:${network}`,
            `payload:registry:${network}`,
            () => safeRegistryPayload(network),
            REGISTRY_CACHE_TTL_MS,
            REGISTRY_CACHE_STALE_MS,
            emptyRegistryState,
          ),
      fresh
        ? globalActivityPayload(network, true)
        : fastGlobalActivityPayload(network),
      fresh && ENABLE_SUMMARY_TOKEN_REFRESH
        ? refreshTokenPayload(network)
        : fastTokenPayloadSnapshot(network, "", { reconcileSpendable: false }),
      fresh && ENABLE_SUMMARY_TOKEN_REFRESH
        ? refreshTokenPayload(network, WORK_TOKEN_ID)
        : fastTokenPayloadSnapshot(network, WORK_TOKEN_ID, {
            reconcileSpendable: false,
          }),
      btcUsdPricePayload(network, { fresh }),
    ]);

  return workFloorPayloadFromState(
    network,
    registryState,
    computerActivity,
    tokenState,
    workTokenState,
    { btcUsdQuote },
  );
}

function workFloorValueCutoffMs(options = {}) {
  const requestedValueCutoffMs = Number(options.valueCutoffMs);
  return Number.isSafeInteger(requestedValueCutoffMs) &&
      requestedValueCutoffMs >= GROWTH_MODEL_START_MS
    ? requestedValueCutoffMs
    : Date.now();
}

function workFloorPayloadFromState(
  network,
  registryState,
  computerActivity,
  tokenState,
  workTokenState,
  options = {},
) {
  if (network !== "livenet") {
    return emptyWorkFloorPayload(network);
  }

  const valueTokenState = tokenStateWithScopedTokenOverride(
    tokenState,
    workTokenState,
    WORK_TOKEN_ID,
  );
  const activityForGrowth = (
    Array.isArray(computerActivity.activity) &&
    computerActivity.activity.length > 0
      ? computerActivity.activity
      : registryState.activity ?? []
  ).filter((item) => item?.valid !== false);
  const tokenSalesForValue = Array.isArray(valueTokenState.sales)
    ? valueTokenState.sales
    : [];
  const canonicalConfirmedComputerActions = Number(
    computerActivity?.stats?.confirmed,
  );
  const confirmedComputerActions =
    Number.isSafeInteger(canonicalConfirmedComputerActions) &&
    canonicalConfirmedComputerActions >= 0
      ? canonicalConfirmedComputerActions
      : activityForGrowth.filter(
          (item) => item?.confirmed && item?.valid !== false,
        ).length;
  const valueCutoffMs = workFloorValueCutoffMs(options);
  const actualValue = growthActualNetworkValue(
    registryState.records ?? [],
    activityForGrowth,
    registryState.sales ?? [],
    valueTokenState.tokens ?? [],
    valueTokenState.mints ?? [],
    valueTokenState.transfers ?? [],
    tokenSalesForValue,
    valueCutoffMs,
    {
      canonicalMinerFeeCoverage:
        computerActivity?.canonicalMinerFeeCoverage ??
        computerActivity?.stats?.canonicalMinerFeeCoverage,
    },
  );
  const globalWorkMintFlow = (valueTokenState.mints ?? [])
    .filter((mint) => mint.confirmed && mint.tokenId === WORK_TOKEN_ID)
    .reduce((total, mint) => total + proofFlowBigInt(mint.paidSats), 0n);
  const scopedWorkMintFlow = (workTokenState.mints ?? [])
    .filter((mint) => mint.confirmed)
    .reduce((total, mint) => total + proofFlowBigInt(mint.paidSats), 0n);
  const globalWorkMintCount = (valueTokenState.mints ?? []).filter(
    (mint) => mint.confirmed && mint.tokenId === WORK_TOKEN_ID,
  ).length;
  const scopedWorkMintCount = (workTokenState.mints ?? []).filter(
    (mint) => mint.confirmed,
  ).length;
  const missingWorkMintFlow =
    scopedWorkMintFlow > globalWorkMintFlow
      ? scopedWorkMintFlow - globalWorkMintFlow
      : 0n;
  const missingWorkMintFlowSats = Number(missingWorkMintFlow);
  const missingWorkMintCount = Math.max(
    0,
    scopedWorkMintCount - globalWorkMintCount,
  );
  const correctedTokenMintFlowSats =
    actualValue.tokenMintFlowSats + missingWorkMintFlowSats;
  const correctedTokenSats =
    (actualValue.tokenCreationFlowSats + correctedTokenMintFlowSats) *
    GROWTH_MODEL_INPUTS.valueMultiple;
  const missingWorkMintValueQ8 =
    missingWorkMintFlow * GROWTH_VALUE_MULTIPLE * VALUE_Q8_SCALE;
  const correctedBaseNetworkValueQ8 =
    BigInt(actualValue.baseNetworkValueQ8 ?? "0") +
    missingWorkMintValueQ8;
  const correctedNetworkValueQ8 =
    BigInt(actualValue.liveNetworkValueQ8 ?? actualValue.totalQ8 ?? "0") +
    missingWorkMintValueQ8;
  const correctedFrozenNetworkValueQ8 =
    BigInt(
      actualValue.frozenNetworkValueQ8 ??
        actualValue.frozenTotalQ8 ??
        actualValue.totalQ8 ??
        "0",
    ) + missingWorkMintValueQ8;
  const correctedFloorQ8 =
    correctedNetworkValueQ8 / BigInt(WORK_TOKEN_MAX_SUPPLY);
  const correctedFrozenFloorQ8 =
    correctedFrozenNetworkValueQ8 / BigInt(WORK_TOKEN_MAX_SUPPLY);
  const correctedNetworkValueSats = q8ToNumber(correctedNetworkValueQ8);
  const correctedFrozenNetworkValueSats = q8ToNumber(
    correctedFrozenNetworkValueQ8,
  );
  const modelTotalUsd = growthSatsToUsdAtYears(
    correctedNetworkValueSats,
    growthElapsedYears(),
  );
  const btcUsdMetadata = btcUsdResponseMetadata(options.btcUsdQuote);
  const liveTotalUsd =
    btcUsdMetadata.btcUsd > 0
      ? satsToUsdAtBtcUsd(correctedNetworkValueSats, btcUsdMetadata.btcUsd)
      : modelTotalUsd;
  const correctedActualValue = {
    ...actualValue,
    workNetworkValueAccountingModel: WORK_NETWORK_VALUE_ACCOUNTING_MODEL,
    modelTotalUsd,
    tokenMintFlowSats: correctedTokenMintFlowSats,
    tokenSats: correctedTokenSats,
    baseNetworkValueQ8: correctedBaseNetworkValueQ8.toString(),
    baseNetworkValueSats:
      q8ToCanonicalDecimal(correctedBaseNetworkValueQ8),
    baseNetworkValueSatsApproximate:
      q8ToNumber(correctedBaseNetworkValueQ8),
    baseNetworkValueSatsExact:
      q8ToCanonicalDecimal(correctedBaseNetworkValueQ8),
    baseTotalQ8: correctedBaseNetworkValueQ8.toString(),
    baseTotalSats: q8ToCanonicalDecimal(correctedBaseNetworkValueQ8),
    baseTotalSatsApproximate: q8ToNumber(correctedBaseNetworkValueQ8),
    baseTotalSatsExact: q8ToCanonicalDecimal(correctedBaseNetworkValueQ8),
    floorSats: q8ToCanonicalDecimal(correctedFloorQ8),
    floorSatsApproximate: q8ToNumber(correctedFloorQ8),
    floorSatsExact: q8ToCanonicalDecimal(correctedFloorQ8),
    floorQ8: correctedFloorQ8.toString(),
    frozenFloorSats: q8ToCanonicalDecimal(correctedFrozenFloorQ8),
    frozenFloorSatsApproximate: q8ToNumber(correctedFrozenFloorQ8),
    frozenFloorSatsExact: q8ToCanonicalDecimal(correctedFrozenFloorQ8),
    frozenFloorQ8: correctedFrozenFloorQ8.toString(),
    frozenNetworkValueQ8: correctedFrozenNetworkValueQ8.toString(),
    frozenNetworkValueSats:
      q8ToCanonicalDecimal(correctedFrozenNetworkValueQ8),
    frozenNetworkValueSatsApproximate: correctedFrozenNetworkValueSats,
    frozenNetworkValueSatsExact:
      q8ToCanonicalDecimal(correctedFrozenNetworkValueQ8),
    frozenTotalQ8: correctedFrozenNetworkValueQ8.toString(),
    frozenTotalSats: q8ToCanonicalDecimal(correctedFrozenNetworkValueQ8),
    frozenTotalSatsApproximate: correctedFrozenNetworkValueSats,
    frozenTotalSatsExact:
      q8ToCanonicalDecimal(correctedFrozenNetworkValueQ8),
    liveFloorSats: q8ToCanonicalDecimal(correctedFloorQ8),
    liveFloorSatsApproximate: q8ToNumber(correctedFloorQ8),
    liveFloorSatsExact: q8ToCanonicalDecimal(correctedFloorQ8),
    liveFloorQ8: correctedFloorQ8.toString(),
    liveNetworkValueQ8: correctedNetworkValueQ8.toString(),
    liveNetworkValueSats: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    liveNetworkValueSatsApproximate: correctedNetworkValueSats,
    liveNetworkValueSatsExact: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    liveTotalQ8: correctedNetworkValueQ8.toString(),
    liveTotalSats: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    liveTotalSatsApproximate: correctedNetworkValueSats,
    liveTotalSatsExact: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    networkValueQ8: correctedNetworkValueQ8.toString(),
    networkValueSats: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    networkValueSatsApproximate: correctedNetworkValueSats,
    networkValueSatsExact: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    totalQ8: correctedNetworkValueQ8.toString(),
    totalSats: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    totalSatsApproximate: correctedNetworkValueSats,
    totalSatsExact: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    totalUsd: liveTotalUsd,
  };
  const workToken = (valueTokenState.tokens ?? []).find(
    (token) =>
      token.tokenId === WORK_TOKEN_ID || token.ticker === WORK_TOKEN_TICKER,
  ) ?? (workTokenState.tokens ?? [])[0];
  const workCreatedMs = workToken
    ? Date.parse(workToken.createdAt)
    : GROWTH_MODEL_START_MS;
  const chartPoints = growthActualValuePoints(
    registryState.records ?? [],
    activityForGrowth,
    registryState.sales ?? [],
    valueTokenState.tokens ?? [],
    valueTokenState.mints ?? [],
    valueTokenState.transfers ?? [],
    tokenSalesForValue,
    {
      canonicalBaseLookupDiagnostics:
        options.canonicalBaseLookupDiagnostics,
      startLabel: "WORK deploy",
      startMs: workCreatedMs,
    },
  )
    .map((point) => ({
      floorSats: point.sats / WORK_TOKEN_MAX_SUPPLY,
      label: point.label,
      networkValueSats: point.sats,
      years: point.years,
    }));
  const lastChartPoint = chartPoints[chartPoints.length - 1];
  const correctedNowPoint = {
    floorSats: correctedNetworkValueSats / WORK_TOKEN_MAX_SUPPLY,
    label: "Real now",
    networkValueSats: correctedNetworkValueSats,
    years: growthElapsedYears(),
  };
  if (!lastChartPoint || lastChartPoint.label !== "Real now") {
    chartPoints.push(correctedNowPoint);
  } else {
    chartPoints[chartPoints.length - 1] = correctedNowPoint;
  }

  return {
    actualValue: correctedActualValue,
    ...btcUsdMetadata,
    chartPoints,
    workNetworkValueAccountingModel: WORK_NETWORK_VALUE_ACCOUNTING_MODEL,
    baseNetworkValueQ8: correctedBaseNetworkValueQ8.toString(),
    baseNetworkValueSats:
      q8ToCanonicalDecimal(correctedBaseNetworkValueQ8),
    baseNetworkValueSatsApproximate:
      q8ToNumber(correctedBaseNetworkValueQ8),
    baseNetworkValueSatsExact:
      q8ToCanonicalDecimal(correctedBaseNetworkValueQ8),
    baseTotalQ8: correctedBaseNetworkValueQ8.toString(),
    baseTotalSats: q8ToCanonicalDecimal(correctedBaseNetworkValueQ8),
    baseTotalSatsApproximate: q8ToNumber(correctedBaseNetworkValueQ8),
    floorSats: q8ToCanonicalDecimal(correctedFloorQ8),
    floorSatsApproximate: q8ToNumber(correctedFloorQ8),
    floorSatsExact: q8ToCanonicalDecimal(correctedFloorQ8),
    floorQ8: correctedFloorQ8.toString(),
    frozenFloorSats: q8ToCanonicalDecimal(correctedFrozenFloorQ8),
    frozenFloorSatsApproximate: q8ToNumber(correctedFrozenFloorQ8),
    frozenFloorSatsExact: q8ToCanonicalDecimal(correctedFrozenFloorQ8),
    frozenFloorQ8: correctedFrozenFloorQ8.toString(),
    frozenNetworkValueQ8: correctedFrozenNetworkValueQ8.toString(),
    frozenNetworkValueSats:
      q8ToCanonicalDecimal(correctedFrozenNetworkValueQ8),
    frozenNetworkValueSatsApproximate: correctedFrozenNetworkValueSats,
    frozenNetworkValueSatsExact:
      q8ToCanonicalDecimal(correctedFrozenNetworkValueQ8),
    frozenTotalQ8: correctedFrozenNetworkValueQ8.toString(),
    frozenTotalSats: q8ToCanonicalDecimal(correctedFrozenNetworkValueQ8),
    frozenTotalSatsApproximate: correctedFrozenNetworkValueSats,
    indexedAt: new Date().toISOString(),
    liveFloorSats: q8ToCanonicalDecimal(correctedFloorQ8),
    liveFloorSatsApproximate: q8ToNumber(correctedFloorQ8),
    liveFloorSatsExact: q8ToCanonicalDecimal(correctedFloorQ8),
    liveFloorQ8: correctedFloorQ8.toString(),
    liveNetworkValueQ8: correctedNetworkValueQ8.toString(),
    liveNetworkValueSats: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    liveNetworkValueSatsApproximate: correctedNetworkValueSats,
    liveNetworkValueSatsExact: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    liveTotalQ8: correctedNetworkValueQ8.toString(),
    liveTotalSats: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    liveTotalSatsApproximate: correctedNetworkValueSats,
    network,
    networkValueQ8: correctedNetworkValueQ8.toString(),
    networkValueSats: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    networkValueSatsApproximate: correctedNetworkValueSats,
    networkValueSatsExact: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    powids: actualValue.powids,
    source: mempoolBase(network),
    tokenFlowSats:
      actualValue.tokenCreationFlowSats + correctedTokenMintFlowSats,
    totalQ8: correctedNetworkValueQ8.toString(),
    totalSats: q8ToCanonicalDecimal(correctedNetworkValueQ8),
    totalSatsApproximate: correctedNetworkValueSats,
    stats: {
      confirmedTokenMints: (valueTokenState.mints ?? []).filter(
        (mint) => mint.confirmed,
      ).length + missingWorkMintCount,
      confirmedTokens: (valueTokenState.tokens ?? []).filter(
        (token) => token.confirmed,
      ).length,
      confirmedComputerActions,
      browserFlowSats: actualValue.browserFlowSats,
      browserSats: actualValue.browserSats,
      computerEventFlowSats: actualValue.computerEventFlowSats,
      computerEventSats: actualValue.computerEventSats,
      driveFlowSats: actualValue.driveFlowSats,
      driveSats: actualValue.driveSats,
      idSats: actualValue.idSats,
      inceptionBondFlowSats: actualValue.inceptionBondFlowSats,
      inceptionBondSats: actualValue.inceptionBondSats,
      infinityBondFlowSats: actualValue.infinityBondFlowSats,
      infinityBondSats: actualValue.infinityBondSats,
      mailFlowSats: actualValue.mailFlowSats,
      mailSats: actualValue.mailSats,
      idMarketplaceFeeSats: actualValue.idMarketplaceFeeSats,
      idMarketplaceVolumeSats: actualValue.idMarketplaceVolumeSats,
      marketplaceFeeSats: actualValue.marketplaceFeeSats,
      marketplaceFlowSats: actualValue.marketplaceFlowSats,
      marketplaceMutationFeeSats: actualValue.marketplaceMutationFeeSats,
      marketplaceSaleVolumeSats: actualValue.marketplaceSaleVolumeSats,
      marketplaceSats: actualValue.marketplaceSats,
      marketplaceVolumeSats: actualValue.marketplaceVolumeSats,
      tokenMarketplaceFeeSats: actualValue.tokenMarketplaceFeeSats,
      tokenCreationFlowSats: actualValue.tokenCreationFlowSats,
      tokenMintFlowSats: correctedTokenMintFlowSats,
      tokenSaleFlowSats: actualValue.tokenSaleFlowSats,
      tokenSaleVolumeSats: actualValue.tokenSaleVolumeSats,
      tokenSats: correctedTokenSats,
      tokenTransferFlowSats: actualValue.tokenTransferFlowSats,
      walletFlowSats: actualValue.walletFlowSats,
      walletSats: actualValue.walletSats,
      frozenNetworkValueSats: correctedFrozenNetworkValueSats,
      liveNetworkValueSats: correctedNetworkValueSats,
      networkValueSats: correctedNetworkValueSats,
      totalSats: correctedNetworkValueSats,
      tokenTransactions:
        valueTokenState.stats?.transactions ??
        (valueTokenState.tokens ?? []).length +
          (valueTokenState.mints ?? []).length +
          tokenSalesForValue.length,
    },
  };
}

function historicalWorkFloorChartPointsFromLedger(ledger, workFloor) {
  if (
    ledger?.network !== "livenet" ||
    !ledger?.registryState ||
    !ledger?.tokenState ||
    !workFloor
  ) {
    return [];
  }

  const activityPayload = Array.isArray(ledger.activityPayload?.activity)
    ? ledger.activityPayload
    : {
        activity: Array.isArray(ledger.activity)
          ? ledger.activity
          : ledger.registryState.activity ?? [],
        indexedAt: ledger.generatedAt ?? new Date().toISOString(),
        network: ledger.network,
        source: ledger.source,
      };
  const workTokenState =
    ledger.workTokenState ??
    scopedTokenPayloadFromState(ledger.tokenState, WORK_TOKEN_ID);
  const valueTokenState = tokenStateWithScopedTokenOverride(
    ledger.tokenState,
    workTokenState,
    WORK_TOKEN_ID,
  );
  const rebuilt = workFloorPayloadFromState(
    ledger.network,
    ledger.registryState,
    activityPayload,
    valueTokenState,
    workTokenState,
    { btcUsdQuote: ledger.btcUsdQuote },
  );
  const chartPoints = Array.isArray(rebuilt.chartPoints)
    ? [...rebuilt.chartPoints]
    : [];
  const currentValueSats = numericValue(
    workFloor.actualValue?.totalSats ??
      workFloor.actualValue?.liveTotalSats ??
      workFloor.liveNetworkValueSats ??
      workFloor.networkValueSats,
  );
  if (currentValueSats > 0) {
    const nowPoint = {
      floorSats: currentValueSats / WORK_TOKEN_MAX_SUPPLY,
      label: "Real now",
      networkValueSats: currentValueSats,
      years: growthElapsedYears(),
    };
    const lastPoint = chartPoints[chartPoints.length - 1];
    if (!lastPoint || lastPoint.label !== "Real now") {
      chartPoints.push(nowPoint);
    } else {
      chartPoints[chartPoints.length - 1] = nowPoint;
    }
  }
  return chartPoints.filter(
    (point) =>
      Number.isFinite(point?.floorSats) &&
      Number.isFinite(point?.networkValueSats) &&
      Number.isFinite(point?.years),
  );
}

function workFloorWithHistoricalChartFromLedger(workFloor, ledger) {
  if (
    !workFloor ||
    ledger?.network !== "livenet" ||
    workFloorHasHistoricalChart(workFloor)
  ) {
    return workFloor;
  }

  const chartPoints = historicalWorkFloorChartPointsFromLedger(
    ledger,
    workFloor,
  );
  if (chartPoints.length <= workFloorChartPointCount(workFloor)) {
    return workFloor;
  }

  return {
    ...workFloor,
    chartPoints,
    source: mergedSourceLabel(workFloor.source, "historical-chart-replay"),
  };
}

function ledgerWithHistoricalWorkFloorChart(ledger) {
  if (!ledger?.workFloor || ledger.network !== "livenet") {
    return ledger;
  }

  const workFloor = workFloorWithHistoricalChartFromLedger(
    ledger.workFloor,
    ledger,
  );
  if (workFloor === ledger.workFloor) {
    return ledger;
  }

  return {
    ...ledger,
    growthSummary: growthSummaryWithCanonicalWorkFloor(
      ledger.growthSummary,
      workFloor,
    ),
    workFloor,
  };
}

function mailPayloadHasMessages(payload) {
  return (
    Array.isArray(payload?.inboxMessages) &&
      payload.inboxMessages.length > 0
  ) || (
    Array.isArray(payload?.sentMessages) &&
      payload.sentMessages.length > 0
  );
}

function mailMessageRichness(message) {
  return [
    message?.memo,
    message?.subject,
    message?.attachment,
    ...(Array.isArray(message?.attachedCredits)
      ? message.attachedCredits
      : []),
    ...(Array.isArray(message?.recipients) ? message.recipients : []),
  ].filter(Boolean).length;
}

function mergeMailMessageLists(indexedMessages, scannedMessages) {
  const merged = new Map();
  for (const message of [
    ...(Array.isArray(indexedMessages) ? indexedMessages : []),
    ...(Array.isArray(scannedMessages) ? scannedMessages : []),
  ]) {
    if (!message?.txid) {
      continue;
    }

    const current = merged.get(message.txid);
    if (!current) {
      merged.set(message.txid, message);
      continue;
    }
    const messageConfirmed =
      message?.confirmed === true || message?.status === "confirmed";
    const currentConfirmed =
      current?.confirmed === true || current?.status === "confirmed";
    const messagePreferred =
      messageConfirmed !== currentConfirmed
        ? messageConfirmed
        : mailMessageRichness(message) >= mailMessageRichness(current);
    const primary = messagePreferred ? message : current;
    const secondary = messagePreferred ? current : message;
    const attachedCredits =
      currentConfirmed && messageConfirmed
        ? current.attachedCredits
        : currentConfirmed !== messageConfirmed
          ? (currentConfirmed
              ? current.attachedCredits
              : message.attachedCredits)
          : primary.attachedCredits ?? secondary.attachedCredits;
    merged.set(message.txid, {
      ...secondary,
      ...primary,
      attachedCredits,
      attachment: primary.attachment ?? secondary.attachment,
      confirmedAt: primary.confirmedAt ?? secondary.confirmedAt,
      createdAt: primary.createdAt ?? secondary.createdAt,
      lastCheckedAt: primary.lastCheckedAt ?? secondary.lastCheckedAt,
      memo: primary.memo || secondary.memo,
      parentTxid: primary.parentTxid ?? secondary.parentTxid,
      recipients: primary.recipients ?? secondary.recipients,
      replyTo: primary.replyTo || secondary.replyTo,
      subject: primary.subject ?? secondary.subject,
      to: primary.to || secondary.to,
    });
  }

  return [...merged.values()].sort(
    (left, right) =>
      Date.parse(right.createdAt) - Date.parse(left.createdAt) ||
      compareCanonicalUtf8(right.txid, left.txid),
  );
}

function subjectOnlyMailBody(value) {
  return /^Subject:\s*/iu.test(String(value ?? "").trim());
}

function mailMessageNeedsBodyRepair(message) {
  const txid = String(message?.txid ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(txid)) {
    return false;
  }
  if (message?.confirmed === false || message?.status === "pending") {
    return false;
  }
  const subject = String(message?.subject ?? "").trim();
  if (!subject) {
    return false;
  }
  const memo = String(message?.memo ?? "").trim();
  return !memo || subjectOnlyMailBody(memo);
}

function mailMessageNeedsAttachmentRepair(message) {
  const txid = String(message?.txid ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(txid)) {
    return false;
  }
  if (message?.confirmed === false || message?.status === "pending") {
    return false;
  }
  const protocolKind = String(message?.protocolKind ?? message?.kind ?? "")
    .trim()
    .toLowerCase();
  if (!["file", "attachment", "browser"].includes(protocolKind)) {
    return false;
  }
  return !message?.attachment;
}

function mailMessageNeedsContentRepair(message) {
  return (
    mailMessageNeedsBodyRepair(message) ||
    mailMessageNeedsAttachmentRepair(message)
  );
}

function mailMessageTimeMs(message) {
  const timeMs = Date.parse(message?.createdAt ?? "");
  return Number.isFinite(timeMs) ? timeMs : 0;
}

function compareMailContentRepairPriority(left, right) {
  return (
    Number(mailMessageNeedsAttachmentRepair(right)) -
      Number(mailMessageNeedsAttachmentRepair(left)) ||
    mailMessageTimeMs(right) - mailMessageTimeMs(left) ||
    compareCanonicalUtf8(right?.txid, left?.txid)
  );
}

function mailMessageHasRealBody(message) {
  const memo = String(message?.memo ?? "").trim();
  return Boolean(memo && !subjectOnlyMailBody(memo));
}

function mergeRepairedMailMessage(message, recovered) {
  const hasRecoveredBody = mailMessageHasRealBody(recovered);
  const recoveredAttachment = recovered?.attachment;
  if (!hasRecoveredBody && !recoveredAttachment) {
    return message;
  }

  return {
    ...message,
    attachedCredits: recovered?.attachedCredits ?? message.attachedCredits,
    attachment: recoveredAttachment ?? message.attachment,
    memo: hasRecoveredBody ? recovered.memo : message.memo,
    parentTxid: recovered.parentTxid ?? message.parentTxid,
    recipients: recovered.recipients ?? message.recipients,
    replyTo:
      recovered.replyTo && recovered.replyTo !== "Unknown"
        ? recovered.replyTo
        : message.replyTo,
    subject: recovered.subject ?? message.subject,
    to: recovered.to ?? message.to,
    ...(recovered.from && recovered.from !== "Unknown"
      ? { from: recovered.from }
      : {}),
  };
}

function mailMessageNeedsPendingWorkRepair(message, folder) {
  const txid = String(message?.txid ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(txid)) {
    return false;
  }
  const pending =
    folder === "inbox"
      ? message?.confirmed !== true
      : String(message?.status ?? "pending").trim().toLowerCase() === "pending";
  return (
    pending &&
    (!Array.isArray(message?.attachedCredits) ||
      message.attachedCredits.length === 0)
  );
}

async function repairPendingMailWorkAttachments(payload, address, network) {
  if (!payload || network !== "livenet") {
    return payload;
  }
  const inboxMessages = Array.isArray(payload.inboxMessages)
    ? payload.inboxMessages
    : [];
  const sentMessages = Array.isArray(payload.sentMessages)
    ? payload.sentMessages
    : [];
  const repairTxids = [
    ...new Set([
      ...inboxMessages
        .filter((message) =>
          mailMessageNeedsPendingWorkRepair(message, "inbox"),
        )
        .map((message) => String(message.txid).trim().toLowerCase()),
      ...sentMessages
        .filter((message) =>
          mailMessageNeedsPendingWorkRepair(message, "sent"),
        )
        .map((message) => String(message.txid).trim().toLowerCase()),
    ]),
  ].slice(
    0,
    Math.max(0, Math.floor(MAIL_PENDING_WORK_REPAIR_MAX_TXS)),
  );
  if (repairTxids.length === 0) {
    return payload;
  }

  const recoveredByTxid = new Map();
  const settled = await Promise.allSettled(
    repairTxids.map(async (txid) => {
      const tx = await payloadWithFallbackAfterMs(
        fetchPendingMailTransactionFromFirstParty(txid, network),
        null,
        Math.max(100, Math.floor(MAIL_PENDING_WORK_REPAIR_WAIT_MS)),
      );
      if (
        !tx ||
        transactionTxid(tx) !== txid ||
        transactionConfirmed(tx)
      ) {
        return;
      }
      recoveredByTxid.set(txid, {
        inbox: inboxMessagesFromTransactions([tx], address, network),
        sent: sentMessagesFromTransactions([tx], address, network),
      });
    }),
  );
  for (const result of settled) {
    if (result.status === "rejected") {
      console.error(
        `Pending mail WORK attachment repair failed: ${errorSummary(result.reason)}`,
      );
    }
  }

  let repairedPendingWorkAttachments = 0;
  const repairList = (messages, folder) =>
    messages.map((message) => {
      if (!mailMessageNeedsPendingWorkRepair(message, folder)) {
        return message;
      }
      const txid = String(message.txid).trim().toLowerCase();
      const recovered = recoveredByTxid.get(txid)?.[folder]?.find(
        (candidate) =>
          String(candidate?.txid ?? "").trim().toLowerCase() === txid &&
          Array.isArray(candidate?.attachedCredits) &&
          candidate.attachedCredits.length > 0,
      );
      if (!recovered) {
        return message;
      }
      repairedPendingWorkAttachments += 1;
      return {
        ...message,
        attachedCredits: recovered.attachedCredits,
      };
    });

  const repairedInbox = repairList(inboxMessages, "inbox");
  const repairedSent = repairList(sentMessages, "sent");
  if (repairedPendingWorkAttachments === 0) {
    return payload;
  }
  return {
    ...payload,
    inboxMessages: repairedInbox,
    indexedAt: new Date().toISOString(),
    sentMessages: repairedSent,
    source: mergedSourceLabel(
      payload.source,
      "first-party-pending-work-attachment-repair",
    ),
    stats: {
      ...(payload.stats ?? {}),
      repairedPendingWorkAttachments,
    },
  };
}

async function repairMailPayloadBodies(payload, address, network) {
  if (!payload || network !== "livenet") {
    return payload;
  }

  const inboxMessages = Array.isArray(payload.inboxMessages)
    ? payload.inboxMessages
    : [];
  const sentMessages = Array.isArray(payload.sentMessages)
    ? payload.sentMessages
    : [];
  const repairTxids = [
    ...new Set(
      [...inboxMessages, ...sentMessages]
        .filter(mailMessageNeedsContentRepair)
        .sort(compareMailContentRepairPriority)
        .map((message) => String(message.txid).toLowerCase()),
    ),
  ].slice(0, Math.max(0, MAIL_BODY_REPAIR_MAX_TXS));
  if (repairTxids.length === 0) {
    return payload;
  }

  const recoveredByTxid = new Map();
  const settled = await Promise.allSettled(
    repairTxids.map(async (txid) => {
      const tx = await fetchTransactionWithSourceFallback(txid, network);
      recoveredByTxid.set(txid, {
        inbox: inboxMessagesFromTransactions([tx], address, network),
        sent: sentMessagesFromTransactions([tx], address, network),
      });
    }),
  );
  for (const result of settled) {
    if (result.status === "rejected") {
      console.error(
        `Mail body repair failed: ${errorSummary(result.reason)}`,
      );
    }
  }

  let repairedBodies = 0;
  let repairedAttachments = 0;
  const repairList = (messages, folder) =>
    messages.map((message) => {
      if (!mailMessageNeedsContentRepair(message)) {
        return message;
      }
      const txid = String(message.txid ?? "").toLowerCase();
      const recoveredGroup = recoveredByTxid.get(txid);
      const recovered = recoveredGroup?.[folder]?.find(
        (candidate) => String(candidate?.txid ?? "").toLowerCase() === txid,
      );
      const hadRealBody = mailMessageHasRealBody(message);
      const hadAttachment = Boolean(message.attachment);
      const repaired = mergeRepairedMailMessage(message, recovered);
      if (!hadRealBody && mailMessageHasRealBody(repaired)) {
        repairedBodies += 1;
      }
      if (!hadAttachment && repaired.attachment) {
        repairedAttachments += 1;
      }
      return repaired;
    });

  const repairedInbox = repairList(inboxMessages, "inbox");
  const repairedSent = repairList(sentMessages, "sent");
  if (repairedBodies === 0 && repairedAttachments === 0) {
    return payload;
  }

  return {
    ...payload,
    inboxMessages: repairedInbox,
    indexedAt: new Date().toISOString(),
    sentMessages: repairedSent,
    source: mergedSourceLabel(payload.source, "raw-mail-body-repair"),
    stats: {
      ...(payload.stats ?? {}),
      repairedAttachments,
      repairedBodies,
    },
  };
}

function mailStats(inboxMessages, sentMessages, extras = {}) {
  return {
    inbox: inboxMessages.filter((message) => message.confirmed).length,
    incoming: inboxMessages.filter((message) => !message.confirmed).length,
    scanFailed: false,
    scannedTransactions: 0,
    sent: sentMessages.filter((message) => message.status === "confirmed")
      .length,
    outbox: sentMessages.filter((message) => message.status !== "confirmed")
      .length,
    ...extras,
  };
}

async function recentAddressMailTransactions(address, network, maxPages) {
  const firstPartyTxs = await fetchAddressTransactionsViaMempoolPagination(
    address,
    network,
    maxPages,
    { includeExternal: false },
  ).catch((error) => {
    console.error(
      `Recent first-party mail scan failed for ${address}: ${errorSummary(error)}`,
    );
    return [];
  });

  try {
    const fallbackTxs = await fetchAddressTransactionsViaExplorerFallback(
      address,
      network,
      maxPages,
    );
    return dedupeTransactions([...firstPartyTxs, ...fallbackTxs]);
  } catch (error) {
    console.error(
      `Recent recovery mail scan failed for ${address}: ${errorSummary(error)}`,
    );
    return firstPartyTxs;
  }
}

async function recentNodeMailPayload(address, network, options = {}) {
  const maxPages = options.maxPages ?? MAIL_INDEXED_RECENT_TX_PAGES;
  const txs = await recentAddressMailTransactions(address, network, maxPages);
  const activityItems = mailActivityItemsFromTransactions(txs, network);
  const mailboxActivityItems = activityItems.map((item) =>
    item?.confirmed === true
      ? { ...item, attachedCredits: undefined }
      : item,
  );
  const inboxMessages = mergeMailMessageLists(
    inboxMessagesFromTransactions(txs, address, network),
    inboxMessagesFromActivityItems(mailboxActivityItems, address, network),
  );
  const sentMessages = mergeMailMessageLists(
    sentMessagesFromTransactions(txs, address, network),
    sentMessagesFromActivityItems(mailboxActivityItems, address, network),
  );
  return {
    address,
    inboxMessages,
    indexedAt: new Date().toISOString(),
    network,
    sentMessages,
    source: `${mempoolBase(network)}:recent-mail`,
    stats: mailStats(inboxMessages, sentMessages, {
      recentActivityItems: activityItems.length,
      recentScan: true,
      scannedTransactions: txs.length,
    }),
  };
}

function mergeMailPayloads(indexedPayload, scannedPayload) {
  if (!indexedPayload) {
    return scannedPayload;
  }
  if (!scannedPayload) {
    return indexedPayload;
  }

  const inboxMessages = mergeMailMessageLists(
    indexedPayload.inboxMessages,
    scannedPayload.inboxMessages,
  );
  const sentMessages = mergeMailMessageLists(
    indexedPayload.sentMessages,
    scannedPayload.sentMessages,
  );

  return {
    ...indexedPayload,
    inboxMessages,
    indexedAt: new Date().toISOString(),
    sentMessages,
    ...(scannedPayload.scanError ? { scanError: scannedPayload.scanError } : {}),
    source: scannedPayload.scanError
      ? indexedPayload.source
      : `${indexedPayload.source}+${scannedPayload.source}`,
    stats: mailStats(inboxMessages, sentMessages, {
      indexedEvents: indexedPayload.stats?.indexedEvents ?? 0,
      scanFailed: Boolean(scannedPayload.scanError),
      scannedTransactions: scannedPayload.stats?.scannedTransactions ?? 0,
    }),
  };
}

async function mailPayloadWithRecentOverlay(payload, address, network) {
  if (!payload || network !== "livenet") {
    return payload;
  }

  const recentPayload = await recentNodeMailPayload(address, network).catch(
    (error) => {
      console.error(
        `Recent indexed mail overlay failed for ${address}: ${errorSummary(error)}`,
      );
      return null;
    },
  );
  if (!recentPayload || !mailPayloadHasMessages(recentPayload)) {
    return payload;
  }

  return mergeMailPayloads(payload, recentPayload);
}

function pendingOnlyMailPayload(payload) {
  const inboxMessages = Array.isArray(payload?.inboxMessages)
    ? payload.inboxMessages.filter((message) => !message?.confirmed)
    : [];
  const sentMessages = Array.isArray(payload?.sentMessages)
    ? payload.sentMessages.filter(
        (message) => message?.status !== "confirmed",
      )
    : [];
  if (inboxMessages.length === 0 && sentMessages.length === 0) {
    return null;
  }
  return {
    ...payload,
    inboxMessages,
    sentMessages,
    source: payload.source
      ? `${payload.source}:pending-only`
      : "recent-mail:pending-only",
    stats: mailStats(inboxMessages, sentMessages, {
      ...(payload.stats ?? {}),
      pendingOnlyOverlay: true,
    }),
  };
}

async function mailPayloadWithPendingRecentOverlay(payload, address, network) {
  if (!payload || network !== "livenet") {
    return payload;
  }

  const recentPayload = await recentNodeMailPayload(address, network).catch(
    (error) => {
      console.error(
        `Pending indexed mail overlay failed for ${address}: ${errorSummary(error)}`,
      );
      return null;
    },
  );
  const pendingPayload = pendingOnlyMailPayload(recentPayload);
  if (!pendingPayload || !mailPayloadHasMessages(pendingPayload)) {
    return payload;
  }

  return mergeMailPayloads(payload, pendingPayload);
}

function mailEventHistoryItemNeedsActorHydration(item, address, network) {
  const txid = String(item?.txid ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(txid)) {
    return false;
  }
  if (mailAddressKey(item?.actor ?? item?.senderAddress) === mailAddressKey(address)) {
    return false;
  }
  if (sentMessagesFromActivityItems([item], address, network).length > 0) {
    return false;
  }
  return inboxMessagesFromActivityItems([item], address, network).length > 0;
}

async function mailPayloadWithIndexedEventOverlay(payload, address, network) {
  if (
    !payload ||
    network !== "livenet" ||
    !proofIndexReadFeatureEnabled("event-history,events")
  ) {
    return payload;
  }

  const searchParams = new URLSearchParams({
    address,
    limit: String(Math.max(1, MAIL_INDEXED_EVENT_OVERLAY_LIMIT)),
    status: "confirmed",
  });
  const eventPage = await proofIndexEventHistoryPayload(
    network,
    searchParams,
  ).catch((error) => {
    console.error(
      `Proof index mail event overlay failed for ${address}: ${errorSummary(error)}`,
    );
    return null;
  });
  const eventItems = (Array.isArray(eventPage?.items) ? eventPage.items : [])
    .filter((item) => isMailRecoveryHistoryKind(item?.kind))
    .map((item) => ({ ...item, attachedCredits: undefined }));
  if (eventItems.length === 0) {
    return payload;
  }

  const hydrateTxids = [
    ...new Set(
      eventItems
        .filter((item) =>
          mailEventHistoryItemNeedsActorHydration(item, address, network),
        )
        .map((item) => String(item.txid).trim().toLowerCase()),
    ),
  ].slice(0, Math.max(0, MAIL_INDEXED_EVENT_HYDRATE_MAX_TXS));
  const hydratedResults = await Promise.allSettled(
    hydrateTxids.map((txid) => mailActivityItemsForTxidSearch(txid, network)),
  );
  const hydratedItems = hydratedResults.flatMap((result) => {
    if (result.status === "fulfilled") {
      return result.value.map((item) => ({
        ...item,
        attachedCredits: undefined,
      }));
    }
    console.error(
      `Proof index mail event hydration failed: ${errorSummary(result.reason)}`,
    );
    return [];
  });
  const overlayItems = dedupeActivityItems([
    ...eventItems,
    ...hydratedItems,
  ]);
  const inboxMessages = inboxMessagesFromActivityItems(
    overlayItems,
    address,
    network,
  );
  const sentMessages = sentMessagesFromActivityItems(
    overlayItems,
    address,
    network,
  );
  if (inboxMessages.length === 0 && sentMessages.length === 0) {
    return payload;
  }

  return mergeMailPayloads(payload, {
    address,
    inboxMessages,
    indexedAt: eventPage?.indexedAt ?? new Date().toISOString(),
    network,
    sentMessages,
    source: "proof-indexer-event-mail-overlay",
    stats: mailStats(inboxMessages, sentMessages, {
      indexedEvents: eventItems.length,
    }),
  });
}

async function reconcileMailPayloadStatuses(payload, network) {
  if (!payload) {
    return payload;
  }

  const inboxMessages = Array.isArray(payload.inboxMessages)
    ? payload.inboxMessages
    : [];
  const sentMessages = Array.isArray(payload.sentMessages)
    ? payload.sentMessages
    : [];
  const statusTxids = [
    ...inboxMessages
      .filter((message) => !message?.confirmed)
      .map((message) => message?.txid),
    ...sentMessages
      .filter((message) => message?.status !== "confirmed")
      .map((message) => message?.txid),
  ]
    .map((txid) => String(txid ?? "").trim().toLowerCase())
    .filter((txid) => /^[0-9a-f]{64}$/u.test(txid));
  const uniqueTxids = [...new Set(statusTxids)].slice(0, 25);
  if (uniqueTxids.length === 0) {
    return payload;
  }

  const settled = await Promise.allSettled(
    uniqueTxids.map(async (txid) => [txid, await txStatusPayload(txid, network)]),
  );
  const statusByTxid = new Map();
  for (const result of settled) {
    if (result.status !== "fulfilled") {
      continue;
    }
    const [txid, status] = result.value;
    if (status?.status) {
      statusByTxid.set(txid, status);
    }
  }

  const reconciledInbox = inboxMessages.flatMap((message) => {
    const status = statusByTxid.get(String(message?.txid ?? "").toLowerCase());
    if (status?.status === "dropped") {
      return [];
    }
    if (status?.status === "confirmed" && !message.confirmed) {
      return [
        {
          ...message,
          attachedCredits: undefined,
          confirmed: true,
          confirmedAt: message.confirmedAt ?? status.indexedAt,
        },
      ];
    }
    return [message];
  });
  const reconciledSent = sentMessages.map((message) => {
    const status = statusByTxid.get(String(message?.txid ?? "").toLowerCase());
    if (status?.status === "dropped" && message.status !== "dropped") {
      return {
        ...message,
        droppedAt: message.droppedAt ?? status.indexedAt,
        lastCheckedAt: status.indexedAt,
        status: "dropped",
      };
    }
    if (status?.status === "confirmed" && message.status !== "confirmed") {
      return {
        ...message,
        attachedCredits: undefined,
        confirmedAt: message.confirmedAt ?? status.indexedAt,
        lastCheckedAt: status.indexedAt,
        status: "confirmed",
      };
    }
    return message;
  });

  return {
    ...payload,
    inboxMessages: reconciledInbox,
    sentMessages: reconciledSent,
    stats: mailStats(reconciledInbox, reconciledSent, {
      ...(payload.stats ?? {}),
      reconciledStatuses: statusByTxid.size,
    }),
  };
}

async function nodeMailPayload(address, network, options = {}) {
  let scanError = "";
  let txs = await fetchAddressTransactions(
    address,
    network,
    options.maxPages ?? MAIL_ADDRESS_TX_PAGES,
    {
      includeExternal: options.includeExternal !== false,
      preferExternal: options.preferExternal === true,
    },
  ).catch((error) => {
    scanError = errorSummary(error);
    console.error(
      `Mail scan failed for ${address}: ${scanError}`,
    );
    return [];
  });
  if (txs.length === 0 && scanError) {
    const recentTxs = await recentAddressMailTransactions(
      address,
      network,
      options.maxPages ?? MAIL_INDEXED_RECENT_TX_PAGES,
    );
    if (recentTxs.length > 0) {
      txs = recentTxs;
    }
  }
  const inboxMessages = inboxMessagesFromTransactions(txs, address, network);
  const sentMessages = sentMessagesFromTransactions(txs, address, network);

  return {
    address,
    inboxMessages,
    indexedAt: new Date().toISOString(),
    network,
    sentMessages,
    ...(scanError ? { scanError } : {}),
    source: mempoolBase(network),
    stats: mailStats(inboxMessages, sentMessages, {
      partialScan: Boolean(scanError && txs.length > 0),
      scanFailed: Boolean(scanError),
      scannedTransactions: txs.length,
    }),
  };
}

async function indexedMailPayload(address, network) {
  if (
    network !== "livenet" ||
    !proofIndexReadFeatureEnabled("address-mail,mail,event-history,events")
  ) {
    return null;
  }

  try {
    const payload = await payloadWithFallbackAfterMs(
      proofIndexAddressMailPayload(network, address),
      null,
      MAIL_INDEXED_LOOKUP_WAIT_MS,
    );
    if (!payload) {
      console.error(
        `Proof index mail lookup timed out for ${address} after ${MAIL_INDEXED_LOOKUP_WAIT_MS}ms.`,
      );
    }
    return payload;
  } catch (error) {
    console.error(
      `Proof index mail lookup failed for ${address}: ${errorSummary(error)}`,
    );
    return null;
  }
}

function livenetAddressMailRequiresProofIndex(network) {
  return (
    network === "livenet" &&
    proofIndexReadFeatureEnabled("address-mail,mail,event-history,events")
  );
}

async function mailPayload(address, network, options = {}) {
  const fresh = Boolean(options.fresh);
  const indexedPayload = await indexedMailPayload(address, network);
  const requiresIndexedMail = livenetAddressMailRequiresProofIndex(network);

  const indexedOnlyPayload = () =>
    payloadWithFallbackAfterMs(
      (async () => {
        const eventOverlayPayload = await mailPayloadWithIndexedEventOverlay(
          indexedPayload,
          address,
          network,
        );
        const pendingOverlayPayload = await mailPayloadWithPendingRecentOverlay(
          eventOverlayPayload,
          address,
          network,
        );
        const reconciled = await reconcileMailPayloadStatuses(
          pendingOverlayPayload,
          network,
        );
        return repairPendingMailWorkAttachments(
          reconciled,
          address,
          network,
        );
      })(),
      indexedPayload,
      MAIL_INDEXED_ENRICH_WAIT_MS,
    );

  const enrichIndexedPayload = () =>
    payloadWithFallbackAfterMs(
      (async () => {
        const eventOverlayPayload = await mailPayloadWithIndexedEventOverlay(
          indexedPayload,
          address,
          network,
        );
        const overlayPayload = await mailPayloadWithRecentOverlay(
          eventOverlayPayload,
          address,
          network,
        );
        const repairedBodies = await repairMailPayloadBodies(
          overlayPayload,
          address,
          network,
        );
        const reconciled = await reconcileMailPayloadStatuses(
          repairedBodies,
          network,
        );
        return repairPendingMailWorkAttachments(
          reconciled,
          address,
          network,
        );
      })(),
      indexedPayload,
      MAIL_INDEXED_ENRICH_WAIT_MS,
    );

  if (
    indexedPayload &&
    requiresIndexedMail &&
    !MAIL_INDEXED_REQUEST_NODE_ENRICH_ENABLED
  ) {
    return indexedOnlyPayload();
  }

  if (indexedPayload && (!fresh || requiresIndexedMail)) {
    return enrichIndexedPayload();
  }

  if (requiresIndexedMail) {
    throw freshDataUnavailableError("Current indexed mailbox is unavailable.");
  }

  const indexedWasEmpty = Boolean(indexedPayload) && !mailPayloadHasMessages(indexedPayload);
  const scannedPayload = await nodeMailPayload(address, network, {
    includeExternal: indexedWasEmpty || fresh || !indexedPayload,
    preferExternal: indexedWasEmpty,
  }).catch((error) => {
    console.error(
      `Mail node scan failed for ${address}: ${errorSummary(error)}`,
    );
    if (indexedPayload) {
      return {
        ...indexedPayload,
        scanError: errorSummary(error),
        stats: mailStats(
          Array.isArray(indexedPayload.inboxMessages)
            ? indexedPayload.inboxMessages
            : [],
          Array.isArray(indexedPayload.sentMessages)
            ? indexedPayload.sentMessages
            : [],
          {
            ...(indexedPayload.stats ?? {}),
            scanFailed: true,
          },
        ),
      };
    }
    throw error;
  });
  if (!indexedPayload) {
    const overlayPayload = await mailPayloadWithRecentOverlay(
      scannedPayload,
      address,
      network,
    );
    return reconcileMailPayloadStatuses(
      await repairMailPayloadBodies(overlayPayload, address, network),
      network,
    );
  }

  if (
    indexedWasEmpty ||
    scannedPayload.scanError ||
    mailPayloadHasMessages(scannedPayload)
  ) {
    const mergedPayload = mergeMailPayloads(indexedPayload, scannedPayload);
    const overlayPayload = await mailPayloadWithRecentOverlay(
      mergedPayload,
      address,
      network,
    );
    return reconcileMailPayloadStatuses(
      await repairMailPayloadBodies(overlayPayload, address, network),
      network,
    );
  }

  return reconcileMailPayloadStatuses(
    await repairMailPayloadBodies(indexedPayload, address, network),
    network,
  );
}

async function firstPartyAddressUtxoPayload(address, network) {
  const fetchUtxosFromBase = async (base) => {
    const url = `${base}/api/address/${address}/utxo`;
    const timeoutMs = String(base).startsWith("https://")
      ? ADDRESS_UTXO_EXTERNAL_FETCH_TIMEOUT_MS
      : ADDRESS_UTXO_FETCH_TIMEOUT_MS;
    return String(base).startsWith("https://")
      ? fetchJsonViaHttps(url, timeoutMs)
      : fetchJson(url, {
          signal: AbortSignal.timeout(timeoutMs),
        });
  };
  const requireUtxoArray = async (label, promise) => {
    const utxos = await promise;
    if (!Array.isArray(utxos)) {
      throw new Error(`${label} did not return a UTXO array.`);
    }
    return utxos;
  };

  let lastError = null;
  if (
    network === "livenet" &&
    String(ELECTRUM_HOST).trim() &&
    ELECTRUM_PORT > 0
  ) {
    try {
      return await requireUtxoArray(
        "Electrum",
        fetchAddressUtxosFromElectrum(address, network),
      );
    } catch (error) {
      console.error(
        `UTXO lookup failed for Electrum ${address}: ${errorSummary(error)}`,
      );
      throw error;
    }
  }

  const candidates = firstPartyAddressReadBases(network).map((base) => ({
      label: base,
      read: () => requireUtxoArray(base, fetchUtxosFromBase(base)),
    }));
  for (const candidate of candidates) {
    try {
      return await candidate.read();
    } catch (error) {
      lastError = error;
      console.error(
        `UTXO lookup failed for ${candidate.label} ${address}: ${errorSummary(error)}`,
      );
    }
  }

  if (network !== "livenet") {
    try {
      return await requireUtxoArray(
        "secondary explorers",
        fetchAddressUtxosFromSecondaryExplorers(address, network),
      );
    } catch (error) {
      lastError = error;
      console.error(
        `UTXO lookup failed for secondary explorers ${address}: ${errorSummary(error)}`,
      );
    }
  }

  throw lastError ?? new Error("No first-party wallet UTXO reader is configured.");
}

async function addressUtxoPayload(address, network) {
  try {
    return await firstPartyAddressUtxoPayload(address, network);
  } catch (lastError) {
    const error = new Error(
      `Wallet UTXO lookup timed out for ${shortAddress(address)}. The node could not return spendable outputs before timeout. Refresh and try again.`,
    );
    error.statusCode = 503;
    error.details = { cause: errorSummary(lastError) };
    throw error;
  }
}

async function txHexPayload(txid, network) {
  let lastError = null;
  const rpcHex = await fetchTransactionHexFromBitcoinRpc(txid, network).catch(
    (error) => {
      lastError = error;
      console.error(
        `Bitcoin RPC transaction hex lookup failed for ${txid}: ${errorSummary(error)}`,
      );
      return "";
    },
  );
  if (rpcHex) {
    return {
      hex: rpcHex,
      indexedAt: new Date().toISOString(),
      network,
      source: "bitcoin-rpc",
      txid,
    };
  }

  const electrumHex = await fetchTransactionHexFromElectrum(txid, network).catch(
    (error) => {
      lastError = error;
      console.error(
        `Electrum transaction hex lookup failed for ${txid}: ${errorSummary(error)}`,
      );
      return "";
    },
  );
  if (electrumHex) {
    return {
      hex: electrumHex,
      indexedAt: new Date().toISOString(),
      network,
      source: "electrum",
      txid,
    };
  }

  for (const base of firstPartyAddressReadBases(network)) {
    const url = `${base}/api/tx/${txid}/hex`;
    try {
      const hex = await fetchText(url, {
        signal: AbortSignal.timeout(TX_OUTSPEND_PRIMARY_FETCH_TIMEOUT_MS),
      });
      return {
        hex,
        indexedAt: new Date().toISOString(),
        network,
        source: base,
        txid,
      };
    } catch (error) {
      lastError = error;
      console.error(
        `Transaction hex lookup failed for ${base} ${txid}: ${errorSummary(error)}`,
      );
    }
  }

  throw lastError ?? new Error(`Transaction hex lookup failed for ${txid}.`);
}

async function directTxOutspendPayload(txid, vout, network) {
  let lastOutspend = null;
  let lastSpentOutspend = null;
  const readBase = async (base) => {
    const timeoutMs = String(base).startsWith("https://")
      ? TX_OUTSPEND_EXTERNAL_FETCH_TIMEOUT_MS
      : TX_OUTSPEND_PRIMARY_FETCH_TIMEOUT_MS;
    const fetchOutspendJson = async (url) => {
      try {
        return await fetchJson(url, {
          signal: AbortSignal.timeout(timeoutMs),
        });
      } catch (error) {
        if (!String(base).startsWith("https://")) {
          throw error;
        }
        return fetchJsonViaHttps(url, timeoutMs);
      }
    };

    try {
      const outspends = await fetchOutspendJson(`${base}/api/tx/${txid}/outspends`);
      const outspend = Array.isArray(outspends) ? outspends[vout] : null;
      if (outspend?.spent) {
        const hydrated = await hydrateOutspendStatus(outspend, network);
        if (outspendHasConfirmedSpender(hydrated)) {
          return { done: true, payload: hydrated };
        }
        return { payload: hydrated, spentIncomplete: true };
      }
      if (outspend && typeof outspend === "object") {
        return { payload: outspend };
      }
    } catch (error) {
      console.error(
        `Outspends lookup failed for ${base} ${txid}:${vout}: ${errorSummary(error)}`,
      );
    }

    try {
      const url = `${base}/api/tx/${txid}/outspend/${vout}`;
      const outspend = await fetchOutspendJson(url);
      if (outspend?.spent) {
        const hydrated = await hydrateOutspendStatus(outspend, network);
        if (outspendHasConfirmedSpender(hydrated)) {
          return { done: true, payload: hydrated };
        }
        return { payload: hydrated, spentIncomplete: true };
      }
      if (outspend && typeof outspend === "object") {
        return { payload: outspend };
      }
    } catch (error) {
      console.error(
        `Outspend lookup failed for ${base} ${txid}:${vout}: ${errorSummary(error)}`,
      );
    }

    return null;
  };

  for (const base of firstPartyAddressReadBases(network)) {
    const result = await readBase(base);
    if (result?.done) {
      return result.payload;
    }
    if (result?.spentIncomplete) {
      lastSpentOutspend = result.payload;
      continue;
    }
    if (result?.payload && typeof result.payload === "object") {
      lastOutspend = result.payload;
      if (result.payload.spent === false && !result.payload.unknown) {
        return result.payload;
      }
    }
  }

  if (lastSpentOutspend) {
    const indexedOutspend =
      await hydrateIncompleteSpentOutspendFromProofIndex(
        txid,
        vout,
        network,
        lastSpentOutspend,
      );
    if (outspendHasConfirmedSpender(indexedOutspend)) {
      return indexedOutspend;
    }
    return indexedOutspend ?? lastSpentOutspend;
  }

  return lastSpentOutspend ?? lastOutspend;
}

async function txOutputScriptHex(txid, vout, network) {
  try {
    const sourceTxHex = await fetchText(
      `${mempoolBase(network)}/api/tx/${txid}/hex`,
      { signal: AbortSignal.timeout(TX_OUTSPEND_PRIMARY_FETCH_TIMEOUT_MS) },
    );
    const sourceTx = bitcoin.Transaction.fromHex(sourceTxHex);
    const output = sourceTx.outs[vout];
    if (output) {
      return bytesToHex(output.script);
    }
  } catch {
    // Fall back to JSON transaction sources below.
  }

  const sourceTx = await fetchTransactionWithSourceFallback(txid, network).catch(
    () => null,
  );
  const scriptHex = sourceTx?.vout?.[vout]?.scriptpubkey;
  return typeof scriptHex === "string" && /^[0-9a-fA-F]+$/u.test(scriptHex)
    ? scriptHex
    : "";
}

async function scriptHistoryOutspendPayload(txid, vout, scriptHex, network) {
  if (network !== "livenet" || !ELECTRUM_HOST || !ELECTRUM_PORT || !scriptHex) {
    return null;
  }

  const scripthash = scriptHashForScriptHex(scriptHex);
  const history = await electrumRequest(
    "blockchain.scripthash.get_history",
    [scripthash],
    TX_OUTSPEND_HISTORY_FETCH_TIMEOUT_MS,
  );
  const historyTxids = [
    ...new Set(
      (Array.isArray(history) ? history : [])
        .map((entry) => entry?.tx_hash)
        .filter(
          (value) => typeof value === "string" && /^[0-9a-fA-F]{64}$/u.test(value),
        )
        .map((value) => value.toLowerCase())
        .filter((value) => value !== txid),
    ),
  ]
    .reverse()
    .slice(0, Math.max(0, TX_OUTSPEND_HISTORY_MAX_TXS));

  const txs = await mapWithConcurrency(
    historyTxids,
    TX_FETCH_CONCURRENCY,
    async (historyTxid) =>
      (await fetchTransactionFromElectrum(historyTxid, network).catch(
        () => null,
      )) ??
      (await fetchTransactionWithSourceFallback(historyTxid, network).catch(
        () => null,
      )),
  );

  for (const tx of txs) {
    const outspend = outspendPayloadFromSpenderTransaction(tx, txid, vout);
    if (outspend) {
      return outspend;
    }
  }

  return null;
}

async function txOutspendPayload(txid, vout, network) {
  const unknownUnspent = { spent: false, unknown: true };
  const directPrimaryOutspend = await payloadWithFallbackAfterMs(
    directTxOutspendPayload(txid, vout, network).catch((error) => {
      console.error(
        `Direct outspend lookup failed for ${txid}:${vout}: ${errorSummary(error)}`,
      );
      return null;
    }),
    null,
    TX_OUTSPEND_PRIMARY_FETCH_TIMEOUT_MS,
  );
  if (outspendHasConfirmedSpender(directPrimaryOutspend)) {
    return directPrimaryOutspend;
  }
  if (
    directPrimaryOutspend?.spent === false &&
    directPrimaryOutspend.unknown !== true
  ) {
    return directPrimaryOutspend;
  }
  const directPrimarySpent = directPrimaryOutspend?.spent
    ? directPrimaryOutspend
    : null;
  if (directPrimarySpent) {
    return hydrateIncompleteSpentOutspendFromProofIndex(
      txid,
      vout,
      network,
      directPrimarySpent,
    );
  }

  const rpcOutspend = await payloadWithFallbackAfterMs(
    bitcoinRpcOutspendPayload(txid, vout, network).catch((error) => {
      console.error(
        `Bitcoin RPC outspend lookup failed for ${txid}:${vout}: ${errorSummary(error)}`,
      );
      return null;
    }),
    null,
    TX_OUTSPEND_PRIMARY_FETCH_TIMEOUT_MS,
  );
  if (rpcOutspend && !rpcOutspend.spent) {
    return rpcOutspend;
  }
  const rpcSpent = rpcOutspend?.spent ? rpcOutspend : null;

  const outputScriptHex = await payloadWithFallbackAfterMs(
    txOutputScriptHex(txid, vout, network).catch(() => ""),
    "",
    TX_OUTSPEND_PRIMARY_FETCH_TIMEOUT_MS,
  );
  let electrumSpent = null;

  if (outputScriptHex && network === "livenet" && ELECTRUM_HOST && ELECTRUM_PORT) {
    const scripthash = scriptHashForScriptHex(outputScriptHex);
    try {
      const unspent = await electrumRequest(
        "blockchain.scripthash.listunspent",
        [scripthash],
        TX_OUTSPEND_PRIMARY_FETCH_TIMEOUT_MS,
      );
      if (Array.isArray(unspent)) {
        const stillUnspent = unspent.some((entry) => {
          const entryTxid =
            typeof entry?.tx_hash === "string"
              ? entry.tx_hash.toLowerCase()
              : "";
          const entryVout = Number(entry?.tx_pos);
          return entryTxid === txid && entryVout === vout;
        });
        if (stillUnspent) {
          return { spent: false };
        }
        electrumSpent = { spent: true, status: null };
      }
    } catch (error) {
      console.error(
        `Electrum outspend lookup failed for ${txid}:${vout}: ${errorSummary(error)}`,
      );
    }
  }

  if (network === "livenet") {
    if (electrumSpent) {
      if (outputScriptHex) {
        const historyOutspend = await scriptHistoryOutspendPayload(
          txid,
          vout,
          outputScriptHex,
          network,
        ).catch(() => null);
        if (historyOutspend) {
          return historyOutspend;
        }
      }

      const directOutspend = await directTxOutspendPayload(
        txid,
        vout,
        network,
      ).catch(() => null);
      return directOutspend?.spent
        ? await hydrateIncompleteSpentOutspendFromProofIndex(
            txid,
            vout,
            network,
            directOutspend,
          )
        : await hydrateIncompleteSpentOutspendFromProofIndex(
            txid,
            vout,
            network,
            electrumSpent,
          );
    }

    return rpcSpent
      ? await hydrateIncompleteSpentOutspendFromProofIndex(
          txid,
          vout,
          network,
          rpcSpent,
        )
      : directPrimarySpent
        ? await hydrateIncompleteSpentOutspendFromProofIndex(
            txid,
            vout,
            network,
            directPrimarySpent,
          )
      : unknownUnspent;
  }

  const primaryOutspend =
    directPrimaryOutspend ?? (await directTxOutspendPayload(txid, vout, network));
  if (primaryOutspend?.spent) {
    return hydrateIncompleteSpentOutspendFromProofIndex(
      txid,
      vout,
      network,
      primaryOutspend,
    );
  }
  if (electrumSpent) {
    if (!outputScriptHex) {
      return electrumSpent;
    }

    const historyOutspend = await scriptHistoryOutspendPayload(
      txid,
      vout,
      outputScriptHex,
      network,
    ).catch(() => null);
    const payload = historyOutspend ?? electrumSpent;
    return hydrateIncompleteSpentOutspendFromProofIndex(
      txid,
      vout,
      network,
      payload,
    );
  }
  if (
    primaryOutspend &&
    primaryOutspend.spent === false &&
    !primaryOutspend.unknown
  ) {
    return primaryOutspend;
  }

  if (!outputScriptHex) {
    return primaryOutspend ?? unknownUnspent;
  }

  const historyOutspend = await scriptHistoryOutspendPayload(
    txid,
    vout,
    outputScriptHex,
    network,
  ).catch(() => null);
  return historyOutspend ?? primaryOutspend ?? unknownUnspent;
}

async function bitcoinCoreTxStatusPayload(txid, network) {
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  const unavailable = (message, details = {}) => {
    const error = freshDataUnavailableError(message);
    error.details = {
      code: "TX_STATUS_UNAVAILABLE",
      network,
      txid: normalizedTxid,
      ...details,
    };
    return error;
  };
  if (network !== "livenet" || !/^[0-9a-f]{64}$/u.test(normalizedTxid)) {
    throw unavailable("Authoritative Bitcoin Core status is unavailable.");
  }

  const observedAt = new Date().toISOString();
  let transactionResponse;
  try {
    transactionResponse = await bitcoinRpc("getrawtransaction", [
      normalizedTxid,
      true,
    ]);
  } catch (error) {
    throw unavailable("Bitcoin Core transaction status lookup failed.", {
      cause: errorSummary(error),
    });
  }
  if (!transactionResponse) {
    throw unavailable("Bitcoin Core transaction status is not configured.");
  }

  if (!transactionResponse.ok) {
    const errorCode = Number(transactionResponse?.error?.code);
    if (errorCode !== -5) {
      throw unavailable("Bitcoin Core transaction status lookup failed.", {
        rpcCode: Number.isFinite(errorCode) ? errorCode : undefined,
      });
    }

    let mempoolResponse;
    let chainResponse;
    let indexResponse;
    try {
      [mempoolResponse, chainResponse, indexResponse] = await Promise.all([
        bitcoinRpc("getmempoolentry", [normalizedTxid]),
        bitcoinRpc("getblockchaininfo", []),
        bitcoinRpc("getindexinfo", ["txindex"]),
      ]);
    } catch (error) {
      throw unavailable("Bitcoin Core absence proof could not be completed.", {
        cause: errorSummary(error),
      });
    }
    const mempoolErrorCode = Number(mempoolResponse?.error?.code);
    const chain = chainResponse?.ok ? chainResponse.result : null;
    const blocks = Number(chain?.blocks);
    const headers = Number(chain?.headers);
    const verificationProgress = Number(chain?.verificationprogress);
    const txindex = indexResponse?.ok ? indexResponse.result?.txindex : null;
    const txindexHeight = Number(txindex?.best_block_height);
    if (
      !mempoolResponse ||
      mempoolResponse.ok ||
      mempoolErrorCode !== -5 ||
      !chain ||
      chain.chain !== "main" ||
      chain.pruned === true ||
      chain.initialblockdownload === true ||
      !Number.isSafeInteger(blocks) ||
      !Number.isSafeInteger(headers) ||
      headers - blocks > 1 ||
      !Number.isFinite(verificationProgress) ||
      verificationProgress < 0.999 ||
      !txindex ||
      txindex.synced !== true ||
      !Number.isSafeInteger(txindexHeight) ||
      txindexHeight !== blocks
    ) {
      throw unavailable("Bitcoin Core absence proof was inconclusive.");
    }
    return {
      absenceProven: true,
      confirmed: false,
      contract: "proof-of-work-tx-status-v2",
      droppedAt: observedAt,
      indexedAt: observedAt,
      network,
      observedAt,
      reason:
        "absent-from-synced-unpruned-mainnet-bitcoin-core-txindex-and-mempool",
      sources: [
        "bitcoin-core:getrawtransaction",
        "bitcoin-core:getmempoolentry",
        "bitcoin-core:getblockchaininfo",
        "bitcoin-core:getindexinfo:txindex",
      ],
      status: "dropped",
      txid: normalizedTxid,
    };
  }

  const transaction = transactionResponse.result;
  if (
    !transaction ||
    typeof transaction !== "object" ||
    String(transaction.txid ?? "").trim().toLowerCase() !== normalizedTxid
  ) {
    throw unavailable("Bitcoin Core returned invalid transaction evidence.");
  }
  const confirmations = Number(transaction.confirmations ?? 0);
  if (!(confirmations > 0)) {
    let mempoolResponse;
    try {
      mempoolResponse = await bitcoinRpc("getmempoolentry", [normalizedTxid]);
    } catch (error) {
      throw unavailable("Bitcoin Core mempool evidence lookup failed.", {
        cause: errorSummary(error),
      });
    }
    const mempoolTime = Number(mempoolResponse?.result?.time);
    if (
      !mempoolResponse?.ok ||
      !Number.isSafeInteger(mempoolTime) ||
      mempoolTime * 1000 < Date.UTC(2009, 0, 3, 18, 15, 5)
    ) {
      throw unavailable("Bitcoin Core pending status lacks mempool evidence.");
    }
    return {
      confirmed: false,
      contract: "proof-of-work-tx-status-v2",
      indexedAt: observedAt,
      mempoolFirstSeenAt: new Date(mempoolTime * 1000).toISOString(),
      mempoolSeen: true,
      network,
      observedAt,
      sources: [
        "bitcoin-core:getrawtransaction",
        "bitcoin-core:getmempoolentry",
      ],
      status: "pending",
      txid: normalizedTxid,
    };
  }

  const blockHash = String(transaction.blockhash ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(blockHash)) {
    throw unavailable("Bitcoin Core confirmation lacks a block hash.");
  }
  let headerResponse;
  let blockResponse;
  try {
    [headerResponse, blockResponse] = await Promise.all([
      bitcoinRpc("getblockheader", [blockHash, true]),
      bitcoinRpc("getblock", [blockHash, 1]),
    ]);
  } catch (error) {
    throw unavailable("Bitcoin Core canonical block proof lookup failed.", {
      cause: errorSummary(error),
    });
  }
  const header = headerResponse?.ok ? headerResponse.result : null;
  const block = blockResponse?.ok ? blockResponse.result : null;
  const blockHeight = Number(header?.height);
  const blockTime = Number(header?.time);
  if (
    !header ||
    !block ||
    Number(header.confirmations) <= 0 ||
    !Number.isSafeInteger(blockHeight) ||
    blockHeight <= 0 ||
    !Number.isSafeInteger(blockTime) ||
    blockTime * 1000 < Date.UTC(2009, 0, 3, 18, 15, 5) ||
    String(header.hash ?? "").trim().toLowerCase() !== blockHash ||
    String(block.hash ?? "").trim().toLowerCase() !== blockHash ||
    Number(block.height) !== blockHeight ||
    !(Array.isArray(block.tx) ? block.tx : []).some(
      (candidate) => String(candidate).trim().toLowerCase() === normalizedTxid,
    )
  ) {
    throw unavailable("Bitcoin Core canonical block evidence was invalid.");
  }
  let canonicalHashResponse;
  try {
    canonicalHashResponse = await bitcoinRpc("getblockhash", [blockHeight]);
  } catch (error) {
    throw unavailable("Bitcoin Core canonical height lookup failed.", {
      cause: errorSummary(error),
    });
  }
  if (
    !canonicalHashResponse?.ok ||
    String(canonicalHashResponse.result ?? "").trim().toLowerCase() !== blockHash
  ) {
    throw unavailable("Bitcoin Core block is not canonical at its height.");
  }
  return {
    blockHash,
    blockHeight,
    blockTime: new Date(blockTime * 1000).toISOString(),
    canonical: true,
    confirmed: true,
    contract: "proof-of-work-tx-status-v2",
    indexedAt: observedAt,
    network,
    observedAt,
    sources: [
      "bitcoin-core:getrawtransaction",
      "bitcoin-core:getblockheader",
      "bitcoin-core:getblock",
      "bitcoin-core:getblockhash",
    ],
    status: "confirmed",
    txid: normalizedTxid,
  };
}

async function txStatusPayload(txid, network) {
  if (proofIndexReadFeatureEnabled("tx-status,tx")) {
    const indexedStatus = await proofIndexTxStatusPayload(txid, network, {
      includeUnconfirmed: proofIndexReadUnconfirmedTxStatus(),
    }).catch((error) => {
      console.error(
        `Proof index tx-status read failed for ${txid}: ${errorSummary(error)}`,
      );
      return null;
    });
    if (indexedStatus) {
      return indexedStatus;
    }
  }

  if (network === "livenet") {
    return bitcoinCoreTxStatusPayload(txid, network);
  }

  const tx = await fetchTransactionWithSourceFallback(txid, network).catch(
    (error) => {
      const unavailable = freshDataUnavailableError(
        "Transaction status sources are unavailable.",
      );
      unavailable.details = {
        cause: errorSummary(error),
        code: "TX_STATUS_UNAVAILABLE",
        network,
        txid,
      };
      throw unavailable;
    },
  );
  if (!tx) {
    const unavailable = freshDataUnavailableError(
      "Transaction absence could not be proven.",
    );
    unavailable.details = {
      code: "TX_STATUS_UNAVAILABLE",
      network,
      txid,
    };
    throw unavailable;
  }
  const confirmed = transactionConfirmed(tx);
  const observedAt = new Date().toISOString();
  return {
    confirmed,
    contract: "proof-of-work-tx-status-v2",
    indexedAt: observedAt,
    network,
    observedAt,
    sources: ["configured-transaction-source"],
    status: confirmed ? "confirmed" : "pending",
    txid,
  };
}

function shadowProofIndexLogHistory(canonicalPayload, network, kind, searchParams) {
  if (!proofIndexShadowFeatureEnabled("log-history,activity-history,log")) {
    return;
  }
  const eligibility = proofIndexLogHistoryReadEligibility(kind, searchParams);
  if (!eligibility.eligible || eligibility.reason === "snapshot-pinned-activity") {
    return;
  }

  void proofIndexLogHistoryPayload(network, kind, searchParams)
    .then((indexedPayload) => {
      if (!indexedPayload) {
        console.error("Proof index log-history shadow read returned no payload.");
        return;
      }
      const mismatches = compareProofIndexHistoryPayloads(
        canonicalPayload,
        indexedPayload,
      );
      if (mismatches.length > 0) {
        console.error(
          `Proof index log-history shadow mismatch: ${mismatches.join("; ")}`,
        );
      }
    })
    .catch((error) => {
      console.error(
        `Proof index log-history shadow read failed: ${errorSummary(error)}`,
      );
    });
}

function shadowProofIndexTokenHistory(
  canonicalPayload,
  network,
  tokenScope,
  kind,
  searchParams,
) {
  if (!proofIndexShadowFeatureEnabled("token-history,token")) {
    return;
  }
  const eligibility = proofIndexTokenHistoryReadEligibility(
    tokenScope,
    kind,
    searchParams,
  );
  if (!eligibility.eligible) {
    return;
  }

  void proofIndexTokenHistoryPayload(network, tokenScope, kind, searchParams)
    .then((indexedPayload) => {
      if (!indexedPayload) {
        console.error("Proof index token-history shadow read returned no payload.");
        return;
      }
      const mismatches = compareProofIndexHistoryPayloads(
        canonicalPayload,
        indexedPayload,
      );
      if (mismatches.length > 0) {
        console.error(
          `Proof index token-history shadow mismatch: ${mismatches.join("; ")}`,
        );
      }
    })
    .catch((error) => {
      console.error(
        `Proof index token-history shadow read failed: ${errorSummary(error)}`,
      );
    });
}

async function txPayload(txid, network) {
  const tx = await fetchTransactionWithSourceFallback(txid, network).catch(
    () => null,
  );
  if (!tx) {
    return {
      confirmed: false,
      indexedAt: new Date().toISOString(),
      network,
      status: "dropped",
      tx: null,
      txid,
    };
  }

  const confirmed = transactionConfirmed(tx);
  return {
    confirmed,
    indexedAt: new Date().toISOString(),
    network,
    status: confirmed ? "confirmed" : "pending",
    tx,
    txid,
  };
}

const INTERNAL_VERIFIER_STATE_TTL_MS = Math.max(
  1_000,
  Number(process.env.POW_INTERNAL_VERIFIER_STATE_TTL_MS ?? 10_000),
);
const INTERNAL_VERIFIER_TOKEN = String(
  process.env.POW_INTERNAL_VERIFIER_TOKEN ?? "",
).trim();
const INTERNAL_VERIFIER_STATE_CACHE = new Map();

function reusableInternalVerifierStateCacheKey(key) {
  const normalized = String(key ?? "");
  return (
    normalized.startsWith("token:") ||
    normalized.startsWith("id:") ||
    normalized.startsWith("token-indexed-current:")
  );
}

function pruneInternalVerifierStateCache(activeBlockHeight = 0) {
  const now = Date.now();
  const activeMarker = activeBlockHeight > 0 ? `:h${activeBlockHeight}:` : "";
  for (const [key, entry] of INTERNAL_VERIFIER_STATE_CACHE) {
    const completeState =
      key.startsWith("token-complete:") ||
      key.startsWith("id-complete:") ||
      key.startsWith("work-amo-v5-block:") ||
      key.startsWith("canonical-context:");
    if (
      (entry?.settled && entry.expiresAt <= now) ||
      (activeMarker && completeState && !key.includes(activeMarker))
    ) {
      INTERNAL_VERIFIER_STATE_CACHE.delete(key);
    }
  }
  while (INTERNAL_VERIFIER_STATE_CACHE.size >= 16) {
    const settledEntries = [...INTERNAL_VERIFIER_STATE_CACHE].filter(
      ([key, entry]) =>
        entry?.settled && !key.startsWith("canonical-context:"),
    );
    // Shared pending replay state is expensive to hydrate and is reused across
    // many mempool txids. Prefer evicting one-shot confirmed/per-tx states so a
    // busy canonical block cannot force every pending verifier back to cold
    // replay. Expiry and loader failures still remove shared state normally.
    const oldestSettled =
      settledEntries.find(
        ([key]) => !reusableInternalVerifierStateCacheKey(key),
      ) ?? settledEntries[0];
    if (!oldestSettled) {
      break;
    }
    INTERNAL_VERIFIER_STATE_CACHE.delete(oldestSettled[0]);
  }
}

async function cachedInternalVerifierState(key, loader) {
  pruneInternalVerifierStateCache();
  const now = Date.now();
  const cached = INTERNAL_VERIFIER_STATE_CACHE.get(key);
  if (cached && (!cached.settled || cached.expiresAt > now)) {
    return cached.promise;
  }
  const entry = {
    expiresAt: Number.POSITIVE_INFINITY,
    promise: null,
    settled: false,
  };
  const promise = Promise.resolve()
    .then(loader)
    .then((value) => {
      entry.expiresAt = Date.now() + INTERNAL_VERIFIER_STATE_TTL_MS;
      entry.settled = true;
      return value;
    });
  entry.promise = promise;
  INTERNAL_VERIFIER_STATE_CACHE.set(key, entry);
  try {
    return await promise;
  } catch (error) {
    if (INTERNAL_VERIFIER_STATE_CACHE.get(key)?.promise === promise) {
      INTERNAL_VERIFIER_STATE_CACHE.delete(key);
    }
    throw error;
  }
}

async function canonicalVerifierCurrentBlock(
  network,
  requiredBlockHeight,
  expectedPreviousHash,
  expectedBlockHash,
) {
  if (network !== "livenet") {
    throw new Error("Canonical block verification is only configured for livenet.");
  }
  const hashResponse = await bitcoinRpc("getblockhash", [requiredBlockHeight]);
  const blockHash = String(hashResponse?.ok ? hashResponse.result : "")
    .trim()
    .toLowerCase();
  if (
    !/^[0-9a-f]{64}$/u.test(blockHash) ||
    blockHash !== String(expectedBlockHash ?? "").trim().toLowerCase()
  ) {
    throw new Error(
      `Bitcoin Core block ${requiredBlockHeight} does not match the requested canonical hash.`,
    );
  }
  const blockResponse = await bitcoinRpc("getblock", [blockHash, 2]);
  const block = blockResponse?.ok ? blockResponse.result : null;
  const blockTransactions = Array.isArray(block?.tx) ? block.tx : [];
  if (
    Number(block?.height) !== requiredBlockHeight ||
    String(block?.hash ?? "").toLowerCase() !== blockHash ||
    String(block?.previousblockhash ?? "").toLowerCase() !==
      String(expectedPreviousHash ?? "").toLowerCase() ||
    Number(block?.nTx) !== blockTransactions.length ||
    blockTransactions.length === 0 ||
    blockTransactions.some(
      (tx) => !/^[0-9a-f]{64}$/u.test(String(tx?.txid ?? "").toLowerCase()),
    )
  ) {
    throw new Error(
      `Canonical verifier block ${requiredBlockHeight} does not extend its stored checkpoint.`,
    );
  }
  const headerResponse = await bitcoinRpc(
    "getblockheader",
    [blockHash, false],
  );
  const blockHeaderHex = String(
    headerResponse?.ok ? headerResponse.result : "",
  )
    .trim()
    .toLowerCase();
  if (!/^[0-9a-f]{160}$/u.test(blockHeaderHex)) {
    throw new Error(
      `Canonical verifier block ${requiredBlockHeight} lacks its exact Core header.`,
    );
  }
  const candidates = blockTransactions.flatMap(
    (raw, blockIndex) => {
      const txid = String(raw?.txid ?? "").trim().toLowerCase();
      const rawRecordSet =
        canonicalRawProtocolRecordSetFromTransaction(raw);
      return /^[0-9a-f]{64}$/u.test(txid) &&
        rawRecordSet.rawProtocolCandidateCount > 0
        ? [{ blockIndex, txid }]
        : [];
    },
  );
  const hydratedCandidates = await mapWithConcurrency(
    candidates,
    Math.min(4, Math.max(1, TX_FETCH_CONCURRENCY)),
    async ({ blockIndex, txid }) => {
      const tx = await fetchTransactionFromBitcoinRpc(txid, network, {
        requireCanonicalPrevouts: true,
      });
      if (
        !tx ||
        !transactionConfirmed(tx) ||
        transactionTxid(tx) !== txid ||
        transactionBlockHash(tx) !== blockHash
      ) {
        throw new Error(
          `Bitcoin Core could not hydrate canonical verifier transaction ${txid}.`,
        );
      }
      return {
        blockIndex,
        transaction: {
          ...tx,
          _powBlockIndex: blockIndex,
          hex: String(blockTransactions[blockIndex]?.hex ?? "")
            .trim()
            .toLowerCase(),
          status: {
            ...(tx.status ?? {}),
            block_hash: blockHash,
            block_height: requiredBlockHeight,
            block_index: blockIndex,
            block_time: Number(block?.time) || tx.status?.block_time,
            confirmed: true,
          },
        },
      };
    },
  );
  const hydratedByIndex = new Map(
    hydratedCandidates.map(({ blockIndex, transaction }) => [
      blockIndex,
      transaction,
    ]),
  );
  const canonicalBlockTransactions = blockTransactions.map(
    (raw, blockIndex) =>
      hydratedByIndex.get(blockIndex) ?? {
        ...raw,
        _powBlockIndex: blockIndex,
      },
  );
  return {
    blockHash,
    blockHeaderHex,
    blockTransactions: canonicalBlockTransactions,
    transactions: hydratedCandidates.map(
      ({ transaction }) => transaction,
    ),
  };
}

async function loadCanonicalVerifierContextFromCheckpoint(
  network,
  requiredBlockHeight,
  expectedBlockHash,
  expectedPreviousBlockHash,
  replayVerifierBinding = null,
) {
  const priorHeight = Number(requiredBlockHeight) - 1;
  if (!Number.isSafeInteger(priorHeight) || priorHeight < 1) {
    throw new Error("Canonical verifier requires a positive prior block height.");
  }
  const prior = await proofIndexCanonicalTransactionsPayload(
    network,
    priorHeight,
  );
  const replayBinding = canonicalPwtReplayVerifierBindingDescriptor(
    replayVerifierBinding,
    network,
  );
  if (replayVerifierBinding && !replayBinding) {
    throw internalReplayVerifierBindingError(
      "The canonical verifier received an invalid authenticated range-replay binding.",
      { priorHeight, requiredBlockHeight },
    );
  }
  if (replayBinding) {
    const priorReplayState = canonicalInternalPwtRangeReplayState(
      prior?.rebuild,
      network,
    );
    const priorBinding = canonicalInternalReplayVerifierBinding(
      prior?.rebuild,
      network,
    );
    if (
      !["active", "complete"].includes(priorReplayState) ||
      !canonicalPwtReplayVerifierBindingsEqual(priorBinding, replayBinding)
    ) {
      throw internalReplayVerifierBindingError(
        "The canonical verifier context does not match the authenticated range-replay database binding.",
        {
          bindingId: replayBinding.bindingId,
          priorHeight,
          requiredBlockHeight,
        },
      );
    }
  }
  const checkpointHash = String(prior?.checkpointHash ?? "")
    .trim()
    .toLowerCase();
  if (
    Number(prior?.indexedThroughBlock) !== priorHeight ||
    !/^[0-9a-f]{64}$/u.test(checkpointHash) ||
    checkpointHash !==
      String(expectedPreviousBlockHash ?? "").trim().toLowerCase() ||
    prior?.fault?.active === true
  ) {
    throw new Error(
      `Canonical verifier DB coverage is not authoritative through block ${priorHeight}.`,
    );
  }
  const canonicalHashResponse = await bitcoinRpc("getblockhash", [priorHeight]);
  const canonicalHash = String(
    canonicalHashResponse?.ok ? canonicalHashResponse.result : "",
  )
    .trim()
    .toLowerCase();
  if (canonicalHash !== checkpointHash) {
    throw new Error(
      `Canonical verifier checkpoint ${priorHeight} no longer matches Bitcoin Core.`,
    );
  }
  const current = await canonicalVerifierCurrentBlock(
    network,
    requiredBlockHeight,
    checkpointHash,
    expectedBlockHash,
  );
  const transactions = dedupeTransactions([
    ...(Array.isArray(prior?.transactions) ? prior.transactions : []),
    ...current.transactions,
  ]);
  return {
    blockHash: current.blockHash,
    blockHeaderHex: current.blockHeaderHex,
    blockTransactions: current.blockTransactions,
    canonicalCoverage: true,
    coverageHeight: requiredBlockHeight,
    indexedThroughBlock: requiredBlockHeight,
    previousBlockHash: checkpointHash,
    priorInvalidEvents: Array.isArray(prior?.invalidEvents)
      ? prior.invalidEvents
      : [],
    transactions,
  };
}

async function canonicalVerifierContextFromCheckpoint(
  network,
  requiredBlockHeight,
  expectedBlockHash,
  expectedPreviousBlockHash,
  replayVerifierBinding = null,
) {
  const height = Number(requiredBlockHeight);
  if (!Number.isSafeInteger(height) || height <= 0) {
    throw new Error("Canonical verifier requires a positive block height.");
  }
  const blockHash = String(expectedBlockHash ?? "").trim().toLowerCase();
  const previousBlockHash = String(expectedPreviousBlockHash ?? "")
    .trim()
    .toLowerCase();
  if (
    !/^[0-9a-f]{64}$/u.test(blockHash) ||
    !/^[0-9a-f]{64}$/u.test(previousBlockHash)
  ) {
    throw new Error(
      "Canonical verifier requires exact current and previous block hashes.",
    );
  }
  const replayBinding = canonicalPwtReplayVerifierBindingDescriptor(
    replayVerifierBinding,
    network,
  );
  if (replayVerifierBinding && !replayBinding) {
    throw internalReplayVerifierBindingError(
      "The canonical verifier received an invalid authenticated range-replay binding.",
      { requiredBlockHeight: height },
    );
  }
  const replayBindingCacheKey =
    canonicalPwtReplayVerifierBindingCacheKey(replayBinding, network);
  pruneInternalVerifierStateCache(height);
  return cachedInternalVerifierState(
    `canonical-context:${network}:h${height}:${previousBlockHash}:${blockHash}${replayBindingCacheKey}`,
    () =>
      loadCanonicalVerifierContextFromCheckpoint(
        network,
        height,
        blockHash,
        previousBlockHash,
        replayBinding,
      ),
  );
}

async function canonicalTokenListingScopeEvidenceFromCore(
  context,
  network,
  listingId,
) {
  if (network !== "livenet") {
    return {
      reason: "canonical-listing-lookup-is-not-configured",
      status: "unresolved",
    };
  }
  let transactionResponse;
  try {
    transactionResponse = await bitcoinRpc("getrawtransaction", [listingId, true]);
  } catch {
    return {
      reason: "canonical-listing-lookup-failed",
      status: "unresolved",
    };
  }
  if (!transactionResponse) {
    return {
      reason: "canonical-listing-lookup-is-not-configured",
      status: "unresolved",
    };
  }
  if (!transactionResponse.ok) {
    const errorCode = Number(transactionResponse?.error?.code);
    return errorCode === -5
      ? {
          reason: "referenced-listing-does-not-exist",
          status: "deterministically-invalid",
        }
      : {
          reason: "canonical-listing-lookup-failed",
          status: "unresolved",
        };
  }
  const raw = transactionResponse.result;
  const blockHash = String(raw?.blockhash ?? "").trim().toLowerCase();
  if (
    !raw ||
    typeof raw !== "object" ||
    Number(raw?.confirmations ?? 0) <= 0 ||
    !/^[0-9a-f]{64}$/u.test(blockHash)
  ) {
    return {
      reason: "referenced-listing-is-not-prior-canonical-state",
      status: "deterministically-invalid",
    };
  }
  let headerResponse;
  try {
    headerResponse = await bitcoinRpc("getblockheader", [blockHash, true]);
  } catch {
    return {
      reason: "canonical-listing-header-lookup-failed",
      status: "unresolved",
    };
  }
  const listingHeight = Number(
    headerResponse?.ok ? headerResponse.result?.height : Number.NaN,
  );
  if (!Number.isSafeInteger(listingHeight) || listingHeight < 0) {
    return {
      reason: "canonical-listing-header-lookup-failed",
      status: "unresolved",
    };
  }
  let canonicalHashResponse;
  try {
    canonicalHashResponse = await bitcoinRpc("getblockhash", [listingHeight]);
  } catch {
    return {
      reason: "canonical-listing-hash-lookup-failed",
      status: "unresolved",
    };
  }
  if (
    !canonicalHashResponse?.ok ||
    String(canonicalHashResponse.result ?? "").trim().toLowerCase() !== blockHash
  ) {
    return {
      reason: "referenced-listing-is-not-on-the-canonical-chain",
      status: "deterministically-invalid",
    };
  }
  if (listingHeight >= Number(context?.coverageHeight ?? 0)) {
    return {
      reason: "referenced-listing-is-not-prior-canonical-state",
      status: "deterministically-invalid",
    };
  }
  const tokenIds = new Set(
    decodedProtocolMessages(
      (Array.isArray(raw?.vout) ? raw.vout : []).map(coreVoutToMempoolVout),
      TOKEN_PROTOCOL_PREFIX,
    ).flatMap((message) => {
      const parsed = parseTokenPayload(message, network);
      const tokenId = String(parsed?.saleAuthorization?.tokenId ?? "")
        .trim()
        .toLowerCase();
      return parsed?.kind === "list" && /^[0-9a-f]{64}$/u.test(tokenId)
        ? [tokenId]
        : [];
    }),
  );
  if (tokenIds.size === 1) {
    return {
      reason: "canonical-listing-is-missing-from-index-context",
      status: "unresolved",
      tokenIds: [...tokenIds],
    };
  }
  if (tokenIds.size > 1) {
    return {
      reason: "canonical-listing-has-ambiguous-token-scope",
      status: "unresolved",
      tokenIds: [...tokenIds].sort(),
    };
  }
  return {
    reason: "referenced-transaction-is-not-a-valid-token-listing",
    status: "deterministically-invalid",
  };
}

async function confirmedTokenVerifierScopeFromContext(
  context,
  network,
  targetTxid,
) {
  const normalizedTargetTxid = String(targetTxid ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(normalizedTargetTxid)) {
    return {
      reason: "invalid-target-txid",
      status: "unresolved",
    };
  }
  const transactionsByTxid = new Map(
    (Array.isArray(context?.transactions) ? context.transactions : []).flatMap(
      (tx) => {
        const txid = transactionTxid(tx);
        return /^[0-9a-f]{64}$/u.test(txid) ? [[txid, tx]] : [];
      },
    ),
  );
  const target = transactionsByTxid.get(normalizedTargetTxid);
  if (!target) {
    return {
      reason: "target-not-in-canonical-context",
      status: "unresolved",
    };
  }
  if (
    transactionBlockHeight(target) !== Number(context?.coverageHeight ?? 0) ||
    transactionBlockHash(target) !==
      String(context?.blockHash ?? "").trim().toLowerCase()
  ) {
    return {
      reason: "target-is-not-in-the-requested-canonical-block",
      status: "unresolved",
    };
  }
  const parseMessages = (tx) =>
    decodedProtocolMessages(tx?.vout ?? [], TOKEN_PROTOCOL_PREFIX).map(
      (message) => parseTokenPayload(message, network),
    );
  const targetMessages = parseMessages(target);
  if (targetMessages.length === 0) {
    return {
      reason: "target-has-no-token-message",
      status: "unresolved",
    };
  }
  const parsedTargetMessages = targetMessages.filter(Boolean);
  if (parsedTargetMessages.length === 0) {
    return {
      reason: "malformed-target-token-payload",
      status: "deterministically-invalid",
    };
  }

  const tokenIds = new Set();
  let deterministicallyInvalidMessages = 0;
  let unresolvedMessages = 0;
  const addTokenId = (value) => {
    const tokenId = String(value ?? "").trim().toLowerCase();
    if (/^[0-9a-f]{64}$/u.test(tokenId)) {
      tokenIds.add(tokenId);
    }
  };
  for (const parsed of parsedTargetMessages) {
    if (parsed.kind === "create") {
      addTokenId(normalizedTargetTxid);
      continue;
    }
    if (parsed.kind === "mint" || parsed.kind === "send") {
      addTokenId(parsed.tokenId);
      continue;
    }
    if (parsed.kind === "list" || parsed.kind === "seal") {
      addTokenId(parsed.saleAuthorization?.tokenId);
      continue;
    }
    if (parsed.kind !== "buy" && parsed.kind !== "delist") {
      continue;
    }
    const listingId = String(parsed.listingId ?? "").trim().toLowerCase();
    const listingTransaction = transactionsByTxid.get(listingId);
    if (!listingTransaction) {
      const evidence = await canonicalTokenListingScopeEvidenceFromCore(
        context,
        network,
        listingId,
      );
      if (evidence.status === "unresolved") {
        return evidence;
      }
      deterministicallyInvalidMessages += 1;
      continue;
    }
    const listingMessages = parseMessages(listingTransaction).filter(Boolean);
    const listingTokenIds = new Set();
    for (const listing of listingMessages) {
      if (listing?.kind === "list") {
        const tokenId = String(listing.saleAuthorization?.tokenId ?? "")
          .trim()
          .toLowerCase();
        if (/^[0-9a-f]{64}$/u.test(tokenId)) {
          listingTokenIds.add(tokenId);
        }
      }
    }
    if (listingTokenIds.size === 0) {
      deterministicallyInvalidMessages += 1;
      continue;
    }
    if (listingTokenIds.size > 1) {
      unresolvedMessages += 1;
      continue;
    }
    addTokenId([...listingTokenIds][0]);
  }
  if (unresolvedMessages > 0 || tokenIds.size > 1) {
    return {
      reason: "ambiguous-token-scope",
      status: "unresolved",
      tokenIds: [...tokenIds].sort(),
    };
  }
  if (tokenIds.size === 1) {
    return {
      scope: [...tokenIds][0],
      status: "resolved",
    };
  }
  if (deterministicallyInvalidMessages > 0) {
    return {
      reason: "referenced-listing-is-not-canonical",
      status: "deterministically-invalid",
    };
  }
  return {
    reason: "token-scope-not-resolved",
    status: "unresolved",
  };
}

function governedWorkMarketActionTransactions(transactions, network) {
  const actions = [];
  for (const tx of Array.isArray(transactions) ? transactions : []) {
    const txid = transactionTxid(tx);
    const blockHeight = transactionBlockHeight(tx);
    if (
      !transactionConfirmed(tx) ||
      !/^[0-9a-f]{64}$/u.test(txid) ||
      !Number.isSafeInteger(blockHeight) ||
      blockHeight < WORK_MARKET_V2_ACTIVATION_HEIGHT
    ) {
      continue;
    }
    const vout = Array.isArray(tx.vout) ? tx.vout : [];
    for (let protocolVout = 0; protocolVout < vout.length; protocolVout += 1) {
      for (const message of decodedProtocolMessages(
        [vout[protocolVout]],
        TOKEN_PROTOCOL_PREFIX,
      )) {
        const governed = parseTokenPayload(message, network);
        if (
          !["list", "seal", "buy"].includes(governed?.kind) ||
          governed?.saleAuthorization?.tokenId !== WORK_TOKEN_ID ||
          !TOKEN_SALE_AUTH_WORK_MARKET_VERSIONS.has(
            governed.saleAuthorization.version,
          )
        ) {
          continue;
        }
        actions.push({
          authorization: governed.saleAuthorization,
          blockHash: transactionBlockHash(tx),
          blockHeight,
          protocolVout,
          txid,
        });
      }
    }
  }
  return actions;
}

async function canonicalWorkMarketV2OraclesForTransactions(
  transactions,
  network,
  { currentBlockHeight, currentPreviousBlockHash } = {},
) {
  const actions = governedWorkMarketActionTransactions(transactions, network);
  if (actions.length === 0) {
    return new Map();
  }
  const currentHeight = Number(currentBlockHeight);
  const currentPriorHash = String(currentPreviousBlockHash ?? "")
    .trim()
    .toLowerCase();
  const oraclesByHeight = new Map();
  const uncachedActions = [];
  for (const action of actions) {
    const cached = workMarketCachedOracleContext(
      WORK_MARKET_V2_ORACLE_CACHE,
      action,
      network,
    );
    if (cached) {
      oraclesByHeight.set(
        cached.confirmationOracle.blockHeight,
        cached.confirmationOracle,
      );
      oraclesByHeight.set(cached.quoteOracle.blockHeight, cached.quoteOracle);
      continue;
    }
    uncachedActions.push(action);
  }
  const requiredOracleHeights = [
    ...new Set(
      uncachedActions.flatMap((action) => {
        const confirmationHeight = action.blockHeight - 1;
        const quoteHeight = Number(action.authorization?.oracleBlockHeight);
        if (
          action.authorization?.version ===
            TOKEN_SALE_AUTH_WORK_MARKET_V4_VERSION &&
          !workMarketV4QuoteHeightWithinBound(
            action.blockHeight,
            quoteHeight,
          )
        ) {
          return [];
        }
        return [
          confirmationHeight,
          ...(action.authorization?.version ===
            TOKEN_SALE_AUTH_WORK_MARKET_V4_VERSION &&
          Number.isSafeInteger(quoteHeight) &&
          quoteHeight > 0 &&
          quoteHeight < action.blockHeight
            ? [quoteHeight]
            : []),
        ];
      }),
    ),
  ];
  const hashesByHeight = new Map();
  await Promise.all(
    requiredOracleHeights.map(async (priorHeight) => {
      if (
        priorHeight === currentHeight - 1 &&
        /^[0-9a-f]{64}$/u.test(currentPriorHash)
      ) {
        hashesByHeight.set(priorHeight, currentPriorHash);
        return;
      }
      const response = await bitcoinRpc("getblockhash", [priorHeight]);
      const blockHash = String(response?.ok ? response.result : "")
        .trim()
        .toLowerCase();
      if (/^[0-9a-f]{64}$/u.test(blockHash)) {
        hashesByHeight.set(priorHeight, blockHash);
      }
    }),
  );
  await Promise.all(
    requiredOracleHeights.map(async (priorHeight) => {
      const blockHash = hashesByHeight.get(priorHeight);
      if (!blockHash) {
        return;
      }
      const snapshot = await proofIndexCanonicalSummaryLedgerPayload(
        network,
        priorHeight,
        blockHash,
      );
      const networkValueQ8 = canonicalNonNegativeIntegerText(
        snapshot?.workNetworkValueQ8 ??
          snapshot?.workFloor?.liveNetworkValueQ8 ??
          snapshot?.workFloor?.actualValue?.liveNetworkValueQ8 ??
          snapshot?.workFloor?.networkValueQ8,
        { allowZero: false },
      );
      if (networkValueQ8) {
        oraclesByHeight.set(priorHeight, {
          blockHash,
          blockHeight: priorHeight,
          networkValueQ8,
          snapshotId: String(snapshot?.snapshotId ?? "").trim(),
        });
      }
    }),
  );
  for (const action of actions) {
    const confirmationOracle = oraclesByHeight.get(action.blockHeight - 1);
    const quoteHeight = Number(action.authorization?.oracleBlockHeight);
    const quoteOracle =
      action.authorization?.version === TOKEN_SALE_AUTH_WORK_MARKET_V4_VERSION
        ? oraclesByHeight.get(quoteHeight)
        : confirmationOracle;
    const actionBlockHash = String(action.blockHash ?? "").toLowerCase();
    if (
      !confirmationOracle ||
      !quoteOracle ||
      !/^[0-9a-f]{64}$/u.test(actionBlockHash)
    ) {
      continue;
    }
    const cacheKey = workMarketOracleCacheKey(action, network);
    if (!WORK_MARKET_V2_ORACLE_CACHE.has(cacheKey)) {
      while (
        WORK_MARKET_V2_ORACLE_CACHE.size >=
        WORK_MARKET_V2_ORACLE_CACHE_MAX_ENTRIES
      ) {
        WORK_MARKET_V2_ORACLE_CACHE.delete(
          WORK_MARKET_V2_ORACLE_CACHE.keys().next().value,
        );
      }
      WORK_MARKET_V2_ORACLE_CACHE.set(cacheKey, {
        confirmationOracle,
        quoteOracle,
      });
    }
  }
  return new Map(
    actions.flatMap((action) => {
      const confirmationOracle = oraclesByHeight.get(action.blockHeight - 1);
      const quoteHeight = Number(action.authorization?.oracleBlockHeight);
      const quoteOracle =
        action.authorization?.version === TOKEN_SALE_AUTH_WORK_MARKET_V4_VERSION
          ? oraclesByHeight.get(quoteHeight)
          : confirmationOracle;
      if (!confirmationOracle || !quoteOracle) {
        return [];
      }
      return [
        [
          workMarketOracleActionKey(action.txid, action.protocolVout),
          action.authorization?.version ===
          TOKEN_SALE_AUTH_WORK_MARKET_V4_VERSION
            ? { confirmationOracle, quoteOracle }
            : {
                ...confirmationOracle,
                confirmationOracle,
                quoteOracle,
              },
        ],
      ];
    }),
  );
}

function workAmoV5ExactInteger(value, { positive = false } = {}) {
  const text = canonicalNonNegativeIntegerText(value, {
    allowZero: !positive,
  });
  return text ? BigInt(text) : null;
}

function workAmoV5JsonNumbersAreExact(value) {
  if (typeof value === "number") {
    return Number.isSafeInteger(value);
  }
  if (Array.isArray(value)) {
    return value.every(workAmoV5JsonNumbersAreExact);
  }
  if (value && typeof value === "object") {
    return Object.values(value).every(workAmoV5JsonNumbersAreExact);
  }
  return true;
}

function workAmoV5TokenStateUsesSubatomProjection(tokenState) {
  const state =
    tokenState && typeof tokenState === "object" && !Array.isArray(tokenState)
      ? tokenState
      : {};
  return Boolean(
    state.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL ||
      state.precisionModel === WORK_PRECISION_V2_MODEL ||
      state.model === WORK_AMO_V8_TOKEN_STATE_PREIMAGE_MODEL ||
      state.confirmedSupplySubatoms !== undefined ||
      (Array.isArray(state.holders) &&
        state.holders.some(
          (holder) => holder?.balanceSubatoms !== undefined,
        )) ||
      (Array.isArray(state.listings) &&
        state.listings.some(
          (listing) => listing?.amountSubatoms !== undefined,
        )),
  );
}

function workAmoV5TokenStateCommitmentProjection(tokenState) {
  if (workAmoV5TokenStateUsesSubatomProjection(tokenState)) {
    return normalizeWorkAmoV5RawWorkState(tokenState);
  }
  const holders = (Array.isArray(tokenState?.holders)
    ? tokenState.holders
    : [])
    .filter(
      (holder) =>
        String(holder?.tokenId ?? "").trim().toLowerCase() === WORK_TOKEN_ID,
    )
    .map((holder) => ({
      address: String(holder?.address ?? "").trim(),
      balanceAtoms:
        canonicalWorkAtomsText(
          holder?.balanceAtoms ??
            parseWorkAmountToAtoms(holder?.balance ?? 0),
          { allowZero: true },
        ) || "0",
    }))
    .sort((left, right) =>
      compareWorkAmoUtf8(left.address, right.address)
    );
  const listings = (Array.isArray(tokenState?.listings)
    ? tokenState.listings
    : [])
    .filter(
      (listing) =>
        String(listing?.tokenId ?? "").trim().toLowerCase() === WORK_TOKEN_ID,
    )
    .map((listing) => ({
      amountAtoms:
        canonicalWorkAtomsText(
          listing?.amountAtoms ??
            workAmountAtomsFromRecord(listing, {
              storedAmountIsAtoms: false,
            }),
        ) || "",
      frozenTerms:
        listing?.frozenTerms ??
        listing?.workAmoPricing?.frozenTerms ??
        listing?.workMarketPricing?.frozenTerms ??
        null,
      listingId: String(listing?.listingId ?? "").trim().toLowerCase(),
      listingAuthorization: listing?.listingAuthorization ?? null,
      priceSats: canonicalNonNegativeIntegerText(listing?.priceSats),
      saleAuthorization: listing?.saleAuthorization ?? null,
      sellerAddress: String(listing?.sellerAddress ?? "").trim(),
    }))
    .sort((left, right) =>
      compareWorkAmoUtf8(left.listingId, right.listingId)
    );
  return {
    confirmedSupplyAtoms:
      canonicalWorkAtomsText(tokenState?.confirmedSupplyAtoms, {
        allowZero: true,
      }) || "0",
    holders,
    listings,
  };
}

async function workAmoV5WorkStateWithCanonicalListingWitnesses(
  tokenState,
  network,
) {
  const governedState =
    workAmoV5WorkStateWithoutLegacyListingReservations(tokenState);
  const listings = governedState.listings;
  const referenceIds = [
    ...new Set(
      listings.flatMap((listing) => {
        const versions = [
          listing?.saleAuthorization?.version,
          listing?.listingAuthorization?.version,
        ]
          .map((version) => String(version ?? "").trim())
          .filter(Boolean);
        const listingId = String(listing?.listingId ?? "")
          .trim()
          .toLowerCase();
        return (
          versions.some((version) =>
            [
              TOKEN_SALE_AUTH_WORK_MARKET_V4_VERSION,
              TOKEN_SALE_AUTH_WORK_AMO_V5_VERSION,
              TOKEN_SALE_AUTH_WORK_AMO_V6_VERSION,
            ].includes(version)
          ) &&
          /^[0-9a-f]{64}$/u.test(listingId)
        )
          ? [listingId]
          : [];
      }),
    ),
  ];
  const witnesses = new Map(
    (
      await mapWithConcurrency(
        referenceIds,
        Math.min(4, Math.max(1, TX_FETCH_CONCURRENCY)),
        async (listingId) => [
          listingId,
          await proofIndexCanonicalWorkListingById(
            network,
            listingId,
          ).catch(() => null),
        ],
      )
    ).filter(([, witness]) => witness),
  );
  const missingWitnessIds = referenceIds.filter(
    (listingId) => !witnesses.has(listingId),
  );
  if (missingWitnessIds.length > 0) {
    throw new Error(
      `Canonical AMO opening listing witness is unavailable for ${missingWitnessIds[0]}.`,
    );
  }
  return {
    ...governedState,
    listings: listings.map((listing) => {
      const witness = witnesses.get(
        String(listing?.listingId ?? "").trim().toLowerCase(),
      );
      if (!witness) {
        return listing;
      }
      const canonicalAuthorization =
        witness.listingAuthorization;
      const canonicalFrozenTerms =
        witness.listingFrozenTerms;
      const authorizationSources = [
        listing?.saleAuthorization,
        listing?.listingAuthorization,
      ];
      const malformedAuthorizationPresent =
        authorizationSources.some(
          (authorization) =>
            authorization !== undefined &&
            authorization !== null &&
            (
              typeof authorization !== "object" ||
              Array.isArray(authorization)
            ),
        );
      const existingAuthorizations = authorizationSources.filter(
        (authorization) =>
          authorization &&
          typeof authorization === "object" &&
          !Array.isArray(authorization),
      );
      const frozenTermsPresent =
        listing?.frozenTerms !== undefined &&
        listing?.frozenTerms !== null;
      const existingFrozenTerms =
        frozenTermsPresent &&
        typeof listing.frozenTerms === "object" &&
        !Array.isArray(listing.frozenTerms)
          ? listing.frozenTerms
          : null;
      if (
        !canonicalAuthorization ||
        !canonicalFrozenTerms ||
        malformedAuthorizationPresent ||
        (frozenTermsPresent && !existingFrozenTerms) ||
        existingAuthorizations.some(
          (authorization) =>
            workAmoV5CanonicalPayloadCommitment(authorization)
              .sha256 !==
            workAmoV5CanonicalPayloadCommitment(
              canonicalAuthorization,
            ).sha256,
        ) ||
        (
          existingFrozenTerms &&
          workAmoV5CanonicalPayloadCommitment(existingFrozenTerms)
            .sha256 !==
            workAmoV5CanonicalPayloadCommitment(
              canonicalFrozenTerms,
            ).sha256
        )
      ) {
        throw new Error(
          `Canonical AMO opening listing witness diverged for ${listing.listingId}.`,
        );
      }
      return {
        ...listing,
        frozenTerms: canonicalFrozenTerms,
        listingAuthorization: canonicalAuthorization,
        saleAuthorization: canonicalAuthorization,
      };
    }),
  };
}

function workAmoV5HistoricalMovements(tokenState, throughHeight) {
  const movements = [];
  const identities = new Set();
  const postActivationPositions = new Set();
  const add = (item, kind) => {
    const blockHeight = Number(item?.blockHeight);
    const txid = String(item?.txid ?? "").trim().toLowerCase();
    const q16 = workRecordUsesSubatoms(item);
    const amountAtoms = workAtomsBigIntFromRecord(item);
    const amountSubatoms = q16
      ? workSubatomsBigIntFromRecord(item)
      : null;
    const amountUnits = q16 ? amountSubatoms : amountAtoms;
    const blockIndex =
      item?.blockIndex === undefined ||
      item?.blockIndex === null ||
      item?.blockIndex === ""
        ? Number.NaN
        : Number(item.blockIndex);
    const protocolVout =
      item?.protocolVout === undefined ||
      item?.protocolVout === null ||
      item?.protocolVout === ""
        ? Number.NaN
        : Number(item.protocolVout);
    const recordOrdinal =
      item?.recordOrdinal === undefined ||
      item?.recordOrdinal === null ||
      item?.recordOrdinal === ""
        ? Number.NaN
        : Number(item.recordOrdinal);
    if (
      item?.confirmed !== true ||
      String(item?.tokenId ?? "").trim().toLowerCase() !== WORK_TOKEN_ID ||
      !Number.isSafeInteger(blockHeight) ||
      blockHeight <= 0 ||
      blockHeight > throughHeight ||
      !/^[0-9a-f]{64}$/u.test(txid) ||
      !Number.isSafeInteger(blockIndex) ||
      blockIndex < 0 ||
      !Number.isSafeInteger(protocolVout) ||
      protocolVout < 0 ||
      !Number.isSafeInteger(recordOrdinal) ||
      recordOrdinal < 0 ||
      amountUnits === null ||
      amountUnits <= 0n
    ) {
      return;
    }
    const identity = [
      kind,
      txid,
      protocolVout,
      recordOrdinal,
    ].join(":");
    if (blockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT) {
      const position = [
        blockHeight,
        blockIndex,
        protocolVout,
        recordOrdinal,
      ].join(":");
      if (postActivationPositions.has(position)) {
        throw new Error(
          `Canonical AMO opening state has duplicate position ${position}.`,
        );
      }
      postActivationPositions.add(position);
    }
    if (identities.has(identity)) {
      throw new Error(
        `Canonical AMO opening state has duplicate movement ${identity}.`,
      );
    }
    identities.add(identity);
    movements.push({
      ...(q16
        ? {
            amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
            amountSubatoms: amountSubatoms.toString(),
          }
        : { amountAtoms: amountAtoms.toString() }),
      blockHeight,
      blockIndex,
      identity,
      protocolVout,
      recordOrdinal,
      txid,
    });
  };
  for (const mint of Array.isArray(tokenState?.mints)
    ? tokenState.mints
    : []) {
    add(mint, "mint");
  }
  for (const transfer of Array.isArray(tokenState?.transfers)
    ? tokenState.transfers
    : []) {
    add(transfer, "transfer");
  }
  for (const sale of Array.isArray(tokenState?.sales)
    ? tokenState.sales
    : []) {
    add(sale, "sale");
  }
  return movements.sort(
    (left, right) =>
      left.blockHeight - right.blockHeight ||
      left.blockIndex - right.blockIndex ||
      left.protocolVout - right.protocolVout ||
      left.recordOrdinal - right.recordOrdinal ||
      compareWorkAmoUtf8(left.identity, right.identity),
  );
}

function workAmoV5AccumulatorNetworkValueQ8(state) {
  const base = Object.fromEntries(
    WORK_AMO_V5_BASE_STATE_FIELDS.map((field) => [
      field,
      BigInt(state?.baseState?.[field] ?? "0"),
    ]),
  );
  const baseNetworkValueQ8 = growthActualBaseStateTotalQ8(base);
  const creditFixedQ8 = BigInt(state?.creditFixedQ8 ?? "0");
  const creditMovementFrozenValueQ8 = BigInt(
    state?.creditMovementFrozenValueQ8 ?? "0",
  );
  const frozenNetworkValueQ8 =
    baseNetworkValueQ8 + creditFixedQ8 + creditMovementFrozenValueQ8;
  let creditMovementLiveValueQ8 = 0n;
  for (const movement of Array.isArray(state?.movements)
    ? state.movements
    : []) {
    const movementValueQ8 = workAmoV5MovementValueAtNetworkQ8(
      movement,
      frozenNetworkValueQ8,
    );
    if (movementValueQ8 === null) {
      throw new Error(
        "Canonical AMO accumulator movement amount is not exact.",
      );
    }
    creditMovementLiveValueQ8 += movementValueQ8;
  }
  return {
    baseNetworkValueQ8,
    creditMovementLiveValueQ8,
    frozenNetworkValueQ8,
    networkValueQ8:
      baseNetworkValueQ8 + creditFixedQ8 + creditMovementLiveValueQ8,
  };
}

function workAmoV5AccumulatorWithRecomputedValue(state) {
  const next = structuredClone(state);
  next.networkValueQ8 =
    workAmoV5AccumulatorNetworkValueQ8(next).networkValueQ8.toString();
  return next;
}

function workAmoV5ExactValueAliases(prefix, valueQ8) {
  const exact = q8ToCanonicalDecimal(valueQ8);
  return {
    [`${prefix}Q8`]: valueQ8.toString(),
    [`${prefix}Sats`]: exact,
    [`${prefix}SatsApproximate`]: q8ToNumber(valueQ8),
    [`${prefix}SatsExact`]: exact,
  };
}

function workAmoV5LegacyBootstrapEvidenceMatches(evidence) {
  const item =
    evidence &&
    typeof evidence === "object" &&
    !Array.isArray(evidence)
      ? evidence
      : {};
  const integer = (value) => workAmoV5ExactInteger(value);
  const mutationSats = integer(item.marketplaceMutationFeeSats);
  const minerFeeSats = integer(item.minerFeeSats);
  const creditFixedSats = integer(item.creditFixedSats);
  const creditFixedQ8 = integer(item.creditFixedQ8);
  const growthValueSats = integer(item.growthValueSats);
  const growthValueQ8 = integer(item.growthValueQ8);
  return (
    item.complete === true &&
    String(item.model ?? "") ===
      WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_MODEL &&
    String(item.txid ?? "").trim().toLowerCase() ===
      WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_TXID &&
    String(item.blockHash ?? "").trim().toLowerCase() ===
      WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_BLOCK_HASH &&
    Number(item.blockHeight) ===
      WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_BLOCK_HEIGHT &&
    Number(item.blockIndex) ===
      WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_BLOCK_INDEX &&
    Number(item.protocolVout) ===
      WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_PROTOCOL_VOUT &&
    Number(item.recordOrdinal) ===
      WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_RECORD_ORDINAL &&
    String(item.reasonCode ?? "") ===
      WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_REASON_CODE &&
    mutationSats ===
      BigInt(WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_MUTATION_SATS) &&
    minerFeeSats ===
      BigInt(WORK_AMO_V5_LEGACY_BOOTSTRAP_CARRY_MINER_FEE_SATS) &&
    creditFixedSats === mutationSats + minerFeeSats &&
    creditFixedQ8 === creditFixedSats * VALUE_Q8_SCALE &&
    growthValueSats === mutationSats * GROWTH_VALUE_MULTIPLE &&
    growthValueQ8 === growthValueSats * VALUE_Q8_SCALE &&
    Number.isSafeInteger(Number(item.eventId)) &&
    Number(item.eventId) > 0 &&
    Number(item.listingCount) === 1 &&
    Number(item.activeListingCount) === 0
  );
}

function workAmoV5LegacyBootstrapReconciliation(
  state,
  value,
  workFloor,
  evidence,
) {
  const invalid = (reason, details) => ({
    ...(details ? { details } : {}),
    reason,
    valid: false,
  });
  if (!workAmoV5LegacyBootstrapEvidenceMatches(evidence)) {
    return invalid("legacy-bootstrap-evidence-mismatch");
  }
  const committedBaseState = {};
  const validBaseState = {};
  const legacyBootstrapCarrySats = BigInt(
    evidence.marketplaceMutationFeeSats,
  );
  const legacyBootstrapCarryFields = new Set([
    "tokenMarketplaceFeeSats",
    "tokenTransferFlowSats",
  ]);
  const excludedCarryFields = [];
  const includedCarryCandidates = [];
  const postActivationBaseCarryFields = [];
  let postActivationBaseCarryQ8 = 0n;
  let legacyBootstrapBaseCarryMode = "published-valid-excludes-carry";
  let legacyBootstrapBaseCarryField = "";
  for (const field of WORK_AMO_V5_BASE_STATE_FIELDS) {
    const committed = workAmoV5ExactInteger(state?.baseState?.[field]);
    const published = workAmoV5ExactInteger(
      workFloor?.actualValue?.[field],
    );
    if (committed === null || published === null) {
      return invalid(`legacy-bootstrap-base-field-missing:${field}`);
    }
    const expectedCarry =
      legacyBootstrapCarryFields.has(field)
        ? legacyBootstrapCarrySats
        : 0n;
    let valid = published;
    if (expectedCarry > 0n) {
      if (committed === published + expectedCarry) {
        excludedCarryFields.push(field);
      } else if (committed === published) {
        includedCarryCandidates.push(field);
      } else {
        return invalid(`legacy-bootstrap-base-field-diverged:${field}`, {
          committed: committed.toString(),
          expectedCarry: expectedCarry.toString(),
          field,
          published: published.toString(),
        });
      }
    } else if (committed !== valid + expectedCarry) {
      return invalid(`legacy-bootstrap-base-field-diverged:${field}`, {
        committed: committed.toString(),
        expectedCarry: expectedCarry.toString(),
        field,
        published: published.toString(),
      });
    }
    committedBaseState[field] = committed;
    validBaseState[field] = valid;
  }
  const committedBaseNetworkValueQ8 = workAmoV5ExactInteger(
    value?.baseNetworkValueQ8,
  );
  const publishedValidBaseNetworkValueQ8 = workAmoV5ExactInteger(
    workFloor?.actualValue?.baseNetworkValueQ8,
  );
  const legacyBootstrapGrowthValueQ8 = BigInt(evidence.growthValueQ8);
  if (excludedCarryFields.length > 1) {
    if (!excludedCarryFields.includes("tokenMarketplaceFeeSats")) {
      return invalid("legacy-bootstrap-base-carry-ambiguous");
    }
    legacyBootstrapBaseCarryField = "tokenMarketplaceFeeSats";
    for (const field of excludedCarryFields) {
      if (field !== legacyBootstrapBaseCarryField) {
        const delta = committedBaseState[field] - validBaseState[field];
        validBaseState[field] = committedBaseState[field];
        postActivationBaseCarryFields.push(field);
        postActivationBaseCarryQ8 +=
          delta * GROWTH_VALUE_MULTIPLE * VALUE_Q8_SCALE;
      }
    }
  } else if (excludedCarryFields.length === 1) {
    legacyBootstrapBaseCarryField = excludedCarryFields[0];
  } else {
    for (const field of includedCarryCandidates) {
      if (validBaseState[field] < legacyBootstrapCarrySats) {
        continue;
      }
      const candidateBaseState = {
        ...validBaseState,
        [field]: validBaseState[field] - legacyBootstrapCarrySats,
      };
      const candidateBaseNetworkValueQ8 =
        growthActualBaseStateTotalQ8(candidateBaseState);
      if (
        committedBaseNetworkValueQ8 !== null &&
        publishedValidBaseNetworkValueQ8 !== null &&
        growthActualBaseStateTotalQ8(committedBaseState) ===
          committedBaseNetworkValueQ8 &&
        publishedValidBaseNetworkValueQ8 ===
          committedBaseNetworkValueQ8 &&
        committedBaseNetworkValueQ8 ===
          candidateBaseNetworkValueQ8 + legacyBootstrapGrowthValueQ8
      ) {
        validBaseState[field] = candidateBaseState[field];
        legacyBootstrapBaseCarryField = field;
        legacyBootstrapBaseCarryMode = "published-valid-includes-carry";
        break;
      }
    }
  }
  const finalValidBaseNetworkValueQ8 =
    growthActualBaseStateTotalQ8(validBaseState);
  const publishedBaseNetworkValueMatches =
    publishedValidBaseNetworkValueQ8 === finalValidBaseNetworkValueQ8 ||
    publishedValidBaseNetworkValueQ8 + postActivationBaseCarryQ8 ===
      finalValidBaseNetworkValueQ8 ||
    (legacyBootstrapBaseCarryMode ===
      "published-valid-includes-carry" &&
      publishedValidBaseNetworkValueQ8 === committedBaseNetworkValueQ8);
  if (
    committedBaseNetworkValueQ8 === null ||
    publishedValidBaseNetworkValueQ8 === null ||
    growthActualBaseStateTotalQ8(committedBaseState) !==
      committedBaseNetworkValueQ8 ||
    !publishedBaseNetworkValueMatches ||
    committedBaseNetworkValueQ8 !==
      finalValidBaseNetworkValueQ8 + legacyBootstrapGrowthValueQ8
  ) {
    return invalid("legacy-bootstrap-base-value-diverged");
  }
  const creditFlowFields = [
    "creditProofPaymentFlowSats",
    "creditRegistryMutationFlowSats",
    "creditMarketplaceMutationFlowSats",
    "creditSalePaymentFlowSats",
    "creditMinerFeeFlowSats",
  ];
  const validCreditFlows = {};
  let validCreditFixedSats = 0n;
  for (const field of creditFlowFields) {
    const amount = workAmoV5ExactInteger(
      workFloor?.actualValue?.[field],
    );
    if (amount === null) {
      return invalid(`legacy-bootstrap-credit-field-missing:${field}`);
    }
    validCreditFlows[field] = amount;
    validCreditFixedSats += amount;
  }
  const committedCreditFixedQ8 = workAmoV5ExactInteger(
    state?.creditFixedQ8,
  );
  const publishedValidCreditFixedQ8Present =
    workFloor?.actualValue?.creditFixedQ8 !== undefined &&
    workFloor?.actualValue?.creditFixedQ8 !== null &&
    workFloor?.actualValue?.creditFixedQ8 !== "";
  const publishedValidCreditFixedQ8 =
    publishedValidCreditFixedQ8Present
      ? workAmoV5ExactInteger(
          workFloor?.actualValue?.creditFixedQ8,
        )
      : null;
  const validCreditFixedQ8 = validCreditFixedSats * VALUE_Q8_SCALE;
  const legacyBootstrapCreditFixedQ8 = BigInt(evidence.creditFixedQ8);
  const legacyBaselineCreditFixedQ8 =
    validCreditFixedQ8 + legacyBootstrapCreditFixedQ8;
  const postActivationCreditFixedQ8 =
    committedCreditFixedQ8 !== null &&
    committedCreditFixedQ8 >= legacyBaselineCreditFixedQ8
      ? committedCreditFixedQ8 - legacyBaselineCreditFixedQ8
      : null;
  const publishedCreditFixedQ8Matches =
    !publishedValidCreditFixedQ8Present ||
    publishedValidCreditFixedQ8 === validCreditFixedQ8 ||
    publishedValidCreditFixedQ8 === legacyBaselineCreditFixedQ8 ||
    publishedValidCreditFixedQ8 === committedCreditFixedQ8;
  if (
    committedCreditFixedQ8 === null ||
    postActivationCreditFixedQ8 === null ||
    !publishedCreditFixedQ8Matches ||
    committedCreditFixedQ8 !==
      legacyBaselineCreditFixedQ8 + postActivationCreditFixedQ8
  ) {
    return {
      details: {
        committedCreditFixedQ8:
          committedCreditFixedQ8?.toString() ?? null,
        legacyBaselineCreditFixedQ8:
          legacyBaselineCreditFixedQ8.toString(),
        legacyBootstrapCreditFixedQ8:
          legacyBootstrapCreditFixedQ8.toString(),
        postActivationCreditFixedQ8:
          postActivationCreditFixedQ8?.toString() ?? null,
        publishedValidCreditFixedQ8:
          publishedValidCreditFixedQ8?.toString() ?? null,
        validCreditFixedQ8: validCreditFixedQ8.toString(),
      },
      reason: "legacy-bootstrap-credit-value-diverged",
      valid: false,
    };
  }
  const committedState = Object.fromEntries(
    Object.entries(committedBaseState).map(([field, amount]) => [
      field,
      amount.toString(),
    ]),
  );
  const validState = Object.fromEntries(
    Object.entries(validBaseState).map(([field, amount]) => [
      field,
      amount.toString(),
    ]),
  );
  const legacyBootstrap = {
    ...evidence,
    baseCarryField: legacyBootstrapBaseCarryField,
    baseCarryMode: legacyBootstrapBaseCarryMode,
    committedBaseState: committedState,
    committedCreditFixedQ8: committedCreditFixedQ8.toString(),
    postActivationBaseCarryFields,
    postActivationBaseCarryQ8: postActivationBaseCarryQ8.toString(),
    publishedBaseNetworkValueQ8:
      publishedValidBaseNetworkValueQ8.toString(),
    validActivityContributionSats: 0,
    validBaseNetworkValueQ8: finalValidBaseNetworkValueQ8.toString(),
    validBaseState: validState,
    validCreditFixedQ8: validCreditFixedQ8.toString(),
    validCreditFixedSats: Number(validCreditFixedSats),
    validMarketplaceMutationFeeSats: Number(
      validBaseState.idMarketplaceFeeSats +
        validBaseState.tokenMarketplaceFeeSats,
    ),
  };
  return {
    committedBaseState,
    legacyBootstrap,
    legacyBootstrapCreditFixedQ8,
    legacyBootstrapGrowthValueQ8,
    postActivationCreditFixedQ8,
    valid: true,
    validBaseNetworkValueQ8: finalValidBaseNetworkValueQ8,
    validBaseState,
    validCreditFixedQ8,
    validCreditFixedSats,
    validCreditFlows,
  };
}

function workAmoV5ClosingSummaryProjection(
  state,
  value,
  workFloor,
  reconciliation,
) {
  if (reconciliation?.valid !== true) {
    throw new Error("AMO V5 legacy bootstrap reconciliation is unavailable.");
  }
  const baseState = reconciliation.validBaseState;
  const supply = BigInt(WORK_TOKEN_MAX_SUPPLY);
  const creditFixedQ8 = BigInt(state.creditFixedQ8);
  const creditMovementFrozenValueQ8 = BigInt(
    state.creditMovementFrozenValueQ8,
  );
  const creditEventFrozenValueQ8 =
    creditFixedQ8 + creditMovementFrozenValueQ8;
  const creditEventLiveValueQ8 =
    creditFixedQ8 + value.creditMovementLiveValueQ8;
  const frozenFloorQ8 = value.frozenNetworkValueQ8 / supply;
  const liveFloorQ8 = value.networkValueQ8 / supply;
  const exactAliases = {
    ...workAmoV5ExactValueAliases(
      "baseNetworkValue",
      value.baseNetworkValueQ8,
    ),
    ...workAmoV5ExactValueAliases(
      "baseTotal",
      value.baseNetworkValueQ8,
    ),
    ...workAmoV5ExactValueAliases(
      "creditEventFrozenValue",
      creditEventFrozenValueQ8,
    ),
    ...workAmoV5ExactValueAliases(
      "creditEventLiveValue",
      creditEventLiveValueQ8,
    ),
    ...workAmoV5ExactValueAliases("creditFixed", creditFixedQ8),
    ...workAmoV5ExactValueAliases(
      "creditFrozenNetworkValue",
      creditEventFrozenValueQ8,
    ),
    ...workAmoV5ExactValueAliases(
      "creditLiveNetworkValue",
      creditEventLiveValueQ8,
    ),
    ...workAmoV5ExactValueAliases(
      "creditMovementFrozenValue",
      creditMovementFrozenValueQ8,
    ),
    ...workAmoV5ExactValueAliases(
      "creditMovementLiveValue",
      value.creditMovementLiveValueQ8,
    ),
    ...workAmoV5ExactValueAliases(
      "creditNetworkValue",
      creditEventLiveValueQ8,
    ),
    ...workAmoV5ExactValueAliases("floor", liveFloorQ8),
    ...workAmoV5ExactValueAliases("frozenFloor", frozenFloorQ8),
    ...workAmoV5ExactValueAliases(
      "frozenNetworkValue",
      value.frozenNetworkValueQ8,
    ),
    ...workAmoV5ExactValueAliases(
      "frozenTotal",
      value.frozenNetworkValueQ8,
    ),
    ...workAmoV5ExactValueAliases("liveFloor", liveFloorQ8),
    ...workAmoV5ExactValueAliases(
      "liveNetworkValue",
      value.networkValueQ8,
    ),
    ...workAmoV5ExactValueAliases("liveTotal", value.networkValueQ8),
    ...workAmoV5ExactValueAliases(
      "networkValue",
      value.networkValueQ8,
    ),
    ...workAmoV5ExactValueAliases("total", value.networkValueQ8),
    ...workAmoV5ExactValueAliases(
      "workNetworkValue",
      value.networkValueQ8,
    ),
  };
  const numberState = Object.fromEntries(
    Object.entries(baseState).map(([field, fieldValue]) => [
      field,
      Number(fieldValue),
    ]),
  );
  const marketplaceFee =
    baseState.idMarketplaceFeeSats +
    baseState.tokenMarketplaceFeeSats;
  const marketplaceSaleVolume =
    baseState.idMarketplaceVolumeSats +
    baseState.tokenSaleVolumeSats;
  const marketplaceFlow = marketplaceFee + marketplaceSaleVolume;
  const tokenFlow =
    baseState.tokenCreationFlowSats + baseState.tokenMintFlowSats;
  const walletFlow = baseState.tokenTransferFlowSats;
  const scaledQ8 = (flow) =>
    flow * GROWTH_VALUE_MULTIPLE * VALUE_Q8_SCALE;
  const componentQ8 = {
    browserSats: scaledQ8(baseState.browserFlowSats),
    computerEventSats: scaledQ8(baseState.computerEventFlowSats),
    driveSats: scaledQ8(baseState.driveFlowSats),
    idSats:
      (baseState.powids *
        baseState.powids *
        GROWTH_ID_DENSITY_NUMERATOR *
        VALUE_Q8_SCALE) /
      GROWTH_ID_DENSITY_DENOMINATOR,
    inceptionBondSats: scaledQ8(baseState.inceptionBondFlowSats),
    infinityBondSats: scaledQ8(baseState.infinityBondFlowSats),
    mailSats: scaledQ8(baseState.mailFlowSats),
    marketplaceSats: scaledQ8(marketplaceFlow),
    tokenSats: scaledQ8(tokenFlow),
    walletSats: scaledQ8(walletFlow),
    legacyBootstrapSats:
      reconciliation.legacyBootstrapGrowthValueQ8,
  };
  const componentFields = Object.fromEntries(
    Object.entries(componentQ8).map(([field, fieldValueQ8]) => [
      field,
      q8ToNumber(fieldValueQ8),
    ]),
  );
  const flowFields = {
    ...numberState,
    marketplaceFeeSats: Number(marketplaceFee),
    marketplaceFlowSats: Number(marketplaceFlow),
    marketplaceMutationFeeSats: Number(marketplaceFee),
    marketplaceSaleVolumeSats: Number(marketplaceSaleVolume),
    marketplaceVolumeSats: Number(marketplaceSaleVolume),
    legacyBootstrapCreditFixedQ8:
      reconciliation.legacyBootstrapCreditFixedQ8.toString(),
    legacyBootstrapCreditFixedSats:
      reconciliation.legacyBootstrap.creditFixedSats,
    legacyBootstrapFlowSats:
      reconciliation.legacyBootstrap.marketplaceMutationFeeSats,
    legacyBootstrapGrowthValueQ8:
      reconciliation.legacyBootstrapGrowthValueQ8.toString(),
    legacyBootstrapMarketplaceCarrySats:
      reconciliation.legacyBootstrap.marketplaceMutationFeeSats,
    legacyBootstrapSats:
      reconciliation.legacyBootstrap.growthValueSats,
    legacyBootstrapTokenMarketplaceFeeSats:
      reconciliation.legacyBootstrap.marketplaceMutationFeeSats,
    postActivationCreditFixedQ8:
      (reconciliation.postActivationCreditFixedQ8 ?? 0n).toString(),
    postActivationCreditFixedSats: Number(
      (reconciliation.postActivationCreditFixedQ8 ?? 0n) / VALUE_Q8_SCALE,
    ),
    tokenFlowSats: Number(tokenFlow),
    tokenSaleFlowSats: Number(baseState.tokenSaleVolumeSats),
    walletFlowSats: Number(walletFlow),
  };
  const networkValueSats = q8ToNumber(value.networkValueQ8);
  const floorSats = q8ToNumber(liveFloorQ8);
  const modelTotalUsd = growthSatsToUsdAtYears(
    networkValueSats,
    growthElapsedYears(),
  );
  const btcUsd = numericValue(workFloor?.btcUsd);
  const totalUsd =
    btcUsd > 0
      ? satsToUsdAtBtcUsd(networkValueSats, btcUsd)
      : modelTotalUsd;
  const floorUsd =
    btcUsd > 0
      ? satsToUsdAtBtcUsd(floorSats, btcUsd)
      : modelTotalUsd / Number(supply);
  return {
    componentFields,
    exactAliases,
    flowFields,
    floorSats,
    floorUsd,
    modelTotalUsd,
    networkValueSats,
    totalUsd,
  };
}

function exactWorkAmoV5RawTransitionChainCommitment(value) {
  const model = String(value?.model ?? "").trim();
  const payloadBytes = Number(value?.payloadBytes);
  const sha256 = String(value?.sha256 ?? "").trim().toLowerCase();
  return model === WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL &&
    Number.isSafeInteger(payloadBytes) &&
    payloadBytes > 0 &&
    /^[0-9a-f]{64}$/u.test(sha256)
    ? { model, payloadBytes, sha256 }
    : null;
}

function exactWorkAmoV5RawBlockDescriptorCommitment(value) {
  const model = String(value?.model ?? "").trim();
  const payloadBytes = Number(value?.payloadBytes);
  const sha256 = String(value?.sha256 ?? "").trim().toLowerCase();
  return model === WORK_AMO_V5_PAYLOAD_COMMITMENT_MODEL &&
    Number.isSafeInteger(payloadBytes) &&
    payloadBytes > 0 &&
    /^[0-9a-f]{64}$/u.test(sha256)
    ? { model, payloadBytes, sha256 }
    : null;
}

function workAmoV5RawTransitionChainCommitmentsEqual(left, right) {
  const normalizedLeft =
    exactWorkAmoV5RawTransitionChainCommitment(left);
  const normalizedRight =
    exactWorkAmoV5RawTransitionChainCommitment(right);
  return Boolean(
    normalizedLeft &&
      normalizedRight &&
      normalizedLeft.model === normalizedRight.model &&
      normalizedLeft.payloadBytes === normalizedRight.payloadBytes &&
      normalizedLeft.sha256 === normalizedRight.sha256,
  );
}

async function workFloorWithVerifiedWorkAmoV5ClosingState(
  workFloor,
  network,
  blockHeight,
  blockHash,
) {
  if (
    network !== "livenet" ||
    blockHeight < WORK_AMO_V5_ACTIVATION_HEIGHT
  ) {
    return workFloor;
  }
  const transition = await proofIndexWorkAmoBlockTransition(
    network,
    blockHeight,
    blockHash,
  );
  const validation = validateWorkAmoV5SufficientState(
    transition?.payload?.closingSufficientState,
  );
  if (
    !transition ||
    !validation.valid ||
    transition.blockHeight !== blockHeight ||
    transition.blockHash !== blockHash ||
    validation.state.throughBlockHeight !== blockHeight ||
    validation.state.throughBlockHash !== blockHash
  ) {
    throw freshDataUnavailableError(
      "The canonical AMO transition closing state is unavailable.",
    );
  }
  const state = validation.state;
  const commitment = workAmoV5CanonicalStateCommitment(state);
  const payloadCommitment = transition.payload?.closingStateCommitment;
  const transitionChainCommitment =
    exactWorkAmoV5RawTransitionChainCommitment(
      transition.payload?.transitionChainCommitment,
    );
  const blockDescriptorCommitment =
    exactWorkAmoV5RawBlockDescriptorCommitment(
      transition.payload?.blockDescriptorCommitment,
    );
  const blockTransactionCount = Number(
    transition.payload?.blockTransactionCount,
  );
  const bip141Witness = normalizedWorkAmoV5Bip141Witness(
    transition.payload?.bip141Witness,
    blockTransactionCount,
  );
  const value = workAmoV5AccumulatorNetworkValueQ8(state);
  if (
    transition.payload?.blockDescriptorModel !==
      WORK_AMO_V5_RAW_BLOCK_DESCRIPTOR_MODEL ||
    !blockDescriptorCommitment ||
    !Number.isSafeInteger(blockTransactionCount) ||
    blockTransactionCount < 1 ||
    !bip141Witness ||
    transition.payload?.transitionChainModel !==
      WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL ||
    !transitionChainCommitment ||
    commitment.sha256 !==
      String(transition.closing_state_sha256 ?? "").trim().toLowerCase() ||
    commitment.payloadBytes !==
      Number(transition.closing_state_payload_bytes) ||
    commitment.sha256 !==
      String(payloadCommitment?.sha256 ?? "").trim().toLowerCase() ||
    commitment.payloadBytes !== Number(payloadCommitment?.payloadBytes) ||
    value.networkValueQ8.toString() !== state.networkValueQ8 ||
    state.networkValueQ8 !==
      String(transition.closing_network_value_q8 ?? "")
  ) {
    throw freshDataUnavailableError(
      "The canonical AMO transition closing commitment diverged.",
    );
  }
  const [relationalTokenState, legacyBootstrapEvidence] =
    await Promise.all([
      transition.workTokenStateModel ===
      WORK_AMO_V8_TOKEN_STATE_PREIMAGE_MODEL
        ? proofIndexWorkAmoV8RelationalTokenStateEvidence(
            network,
            state.tokenStateCommitment,
          )
        : proofIndexWorkAmoRelationalTokenStateEvidence(
            network,
            state.tokenStateCommitment,
          ),
      proofIndexWorkAmoLegacyBootstrapCarryEvidence(network),
    ]);
  if (relationalTokenState?.complete !== true) {
    throw freshDataUnavailableError(
      "The canonical AMO transition token state is not relationally complete.",
    );
  }
  if (legacyBootstrapEvidence?.complete !== true) {
    throw freshDataUnavailableError(
      "The canonical AMO legacy bootstrap evidence is unavailable.",
    );
  }
  const reconciliation = workAmoV5LegacyBootstrapReconciliation(
    state,
    value,
    workFloor,
    legacyBootstrapEvidence,
  );
  if (reconciliation.valid !== true) {
    throw freshDataUnavailableError(
      `The canonical AMO legacy bootstrap reconciliation diverged (${reconciliation.reason})${reconciliation.details ? `: ${JSON.stringify(reconciliation.details)}` : ""}.`,
    );
  }

  const projection = workAmoV5ClosingSummaryProjection(
    state,
    value,
    workFloor,
    reconciliation,
  );
  const transitionEvidence = {
    blockHash,
    blockHeight,
    blockDescriptorCommitment,
    blockDescriptorModel: WORK_AMO_V5_RAW_BLOCK_DESCRIPTOR_MODEL,
    blockTransactionCount,
    closingStateCommitment: commitment,
    eventSetCommitment: transition.payload?.eventSetCommitment,
    model: WORK_AMO_V5_BLOCK_SEQUENCER_MODEL,
    networkValueQ8: value.networkValueQ8.toString(),
    transitionChainCommitment,
    transitionChainModel: WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL,
  };
  const actualValue = {
    ...(workFloor?.actualValue ?? {}),
    ...projection.flowFields,
    ...projection.componentFields,
    ...projection.exactAliases,
    floorUsd: projection.floorUsd,
    modelTotalUsd: projection.modelTotalUsd,
    networkUsd: projection.totalUsd,
    totalUsd: projection.totalUsd,
    workAmoV5LegacyBootstrap:
      reconciliation.legacyBootstrap,
    workAmoV5Transition: transitionEvidence,
    workAmoV5AccumulatorModel:
      WORK_AMO_V5_NETWORK_ACCUMULATOR_MODEL,
    workNetworkValueAccountingModel:
      WORK_NETWORK_VALUE_ACCOUNTING_MODEL,
  };
  const chartPoints = Array.isArray(workFloor?.chartPoints)
    ? [...workFloor.chartPoints]
    : [];
  const finalChartPoint = {
    ...(chartPoints.at(-1) ?? {}),
    floorQ8: projection.exactAliases.floorQ8,
    floorSats: projection.floorSats,
    label: chartPoints.at(-1)?.label ?? "Real now",
    networkValueQ8: projection.exactAliases.networkValueQ8,
    networkValueSats: projection.networkValueSats,
    years: Number.isFinite(chartPoints.at(-1)?.years)
      ? chartPoints.at(-1).years
      : growthElapsedYears(),
  };
  if (chartPoints.length > 0) {
    chartPoints[chartPoints.length - 1] = finalChartPoint;
  } else {
    chartPoints.push(finalChartPoint);
  }
  const stats = {
    ...(workFloor?.stats ?? {}),
    ...projection.flowFields,
    ...projection.componentFields,
    frozenNetworkValueSats:
      projection.exactAliases.frozenNetworkValueSatsApproximate,
    liveNetworkValueSats:
      projection.exactAliases.liveNetworkValueSatsApproximate,
    networkValueSats:
      projection.exactAliases.networkValueSatsApproximate,
    totalSats: projection.exactAliases.totalSatsApproximate,
    workAmoV5LegacyBootstrap:
      reconciliation.legacyBootstrap,
  };
  return {
    ...workFloor,
    ...projection.exactAliases,
    actualValue,
    chartPoints,
    floorUsd: projection.floorUsd,
    modelTotalUsd: projection.modelTotalUsd,
    networkUsd: projection.totalUsd,
    powids: projection.flowFields.powids,
    stats,
    tokenFlowSats: projection.flowFields.tokenFlowSats,
    totalUsd: projection.totalUsd,
    workAmoV5LegacyBootstrap:
      reconciliation.legacyBootstrap,
    workAmoV5Transition: transitionEvidence,
    workAmoV5AccumulatorModel:
      WORK_AMO_V5_NETWORK_ACCUMULATOR_MODEL,
    workNetworkValueAccountingModel:
      WORK_NETWORK_VALUE_ACCOUNTING_MODEL,
  };
}

function exactCanonicalAmoPositionInteger(value, minimum = 0) {
  if (value === undefined || value === null || value === "") {
    return null;
  }
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
}

function workAmoV5QuoteHeadCommitmentProjection(quote) {
  if (quote == null) {
    return null;
  }
  const blockHash = String(quote?.blockHash ?? "")
    .trim()
    .toLowerCase();
  const blockHeight = exactCanonicalAmoPositionInteger(
    quote?.blockHeight,
    1,
  );
  const blockTransactionIndex = exactCanonicalAmoPositionInteger(
    quote?.blockTransactionIndex ?? quote?.blockIndex,
  );
  const protocolVout = exactCanonicalAmoPositionInteger(
    quote?.protocolVout,
  );
  const recordOrdinal = exactCanonicalAmoPositionInteger(
    quote?.recordOrdinal,
  );
  const txid = String(quote?.txid ?? "").trim().toLowerCase();
  const v1DeclarationTxid = String(
    quote?.v1DeclarationTxid ?? quote?.declarationTxid ?? "",
  )
    .trim()
    .toLowerCase();
  const previousQuoteTxid = String(quote?.previousQuoteTxid ?? "")
    .trim()
    .toLowerCase();
  const sequence = canonicalNonNegativeIntegerText(quote?.sequence, {
    allowZero: false,
  });
  const usdPer100mProofsQ8 = canonicalNonNegativeIntegerText(
    quote?.usdPer100mProofsQ8,
    { allowZero: false },
  );
  if (
    !/^[0-9a-f]{64}$/u.test(blockHash) ||
    blockHeight === null ||
    blockHeight < WORK_AMO_V5_V1_ACTIVATION_HEIGHT ||
    blockTransactionIndex === null ||
    protocolVout === null ||
    recordOrdinal !== 0 ||
    !/^[0-9a-f]{64}$/u.test(txid) ||
    v1DeclarationTxid !== WORK_AMO_V5_V1_DECLARATION_TXID ||
    !/^[0-9a-f]{64}$/u.test(previousQuoteTxid) ||
    !sequence ||
    !usdPer100mProofsQ8
  ) {
    return null;
  }
  return {
    blockHash,
    blockHeight,
    blockTransactionIndex,
    previousQuoteTxid,
    protocolVout,
    recordOrdinal,
    sequence,
    txid,
    usdPer100mProofsQ8,
    v1DeclarationTxid,
  };
}

async function workAmoV5OpeningAccumulatorFromPriorTransition(
  network,
  priorHeight,
  priorBlockHash,
) {
  const prior = await proofIndexWorkAmoBlockTransition(
    network,
    priorHeight,
    priorBlockHash,
  );
  const closingStateSource =
    prior?.payload?.closingSufficientState;
  const validation =
    validateWorkAmoV5SufficientState(closingStateSource);
  if (
    !prior ||
    !validation.valid ||
    prior.blockHeight !== priorHeight ||
    prior.blockHash !== priorBlockHash ||
    validation.state.throughBlockHeight !== priorHeight ||
    validation.state.throughBlockHash !== priorBlockHash
  ) {
    throw new Error(
      "Canonical AMO prior immutable block transition is unavailable.",
    );
  }
  const commitment =
    workAmoV5CanonicalStateCommitment(validation.state);
  const payloadCommitment =
    prior.payload?.closingStateCommitment;
  const transitionChainCommitment =
    exactWorkAmoV5RawTransitionChainCommitment(
      prior.payload?.transitionChainCommitment,
    );
  const blockDescriptorCommitment =
    exactWorkAmoV5RawBlockDescriptorCommitment(
      prior.payload?.blockDescriptorCommitment,
    );
  const blockTransactionCount = Number(
    prior.payload?.blockTransactionCount,
  );
  const bip141Witness = normalizedWorkAmoV5Bip141Witness(
    prior.payload?.bip141Witness,
    blockTransactionCount,
  );
  let closingTokenStateCommitment = null;
  let closingGenericTokenStateCommitment = null;
  let closingIdStateCommitment = null;
  try {
    const priorV7 =
      prior?.model ===
        "canonical-work-amo-full-position-block-sequencer-v3" &&
      (
        prior?.workTokenStateModel ??
        prior?.work_token_state_model
      ) ===
        "canonical-work-token-state-subatoms-v2";
    const priorV8 =
      prior?.model ===
        "canonical-work-amo-full-position-block-sequencer-v4" &&
      (
        prior?.workTokenStateModel ??
        prior?.work_token_state_model
      ) ===
        "canonical-work-token-state-subatoms-v3";
    closingTokenStateCommitment =
      priorV8
        ? workAmoV8CanonicalTokenStateCommitment(
            prior.payload?.closingTokenState,
          )
        : priorV7
          ? workAmoV7CanonicalTokenStateCommitment(
              prior.payload?.closingTokenState,
            )
        : workAmoV6CanonicalTokenStateCommitment(
            prior.payload?.closingTokenState,
          );
    closingGenericTokenStateCommitment =
      workAmoV5RawGenericStateCommitment(
        prior.payload?.closingGenericTokenState,
      );
    closingIdStateCommitment =
      workAmoV5RawIdStateCommitment(
        prior.payload?.closingIdState,
      );
  } catch {
    closingTokenStateCommitment = null;
    closingGenericTokenStateCommitment = null;
    closingIdStateCommitment = null;
  }
  if (
    prior.payload?.blockDescriptorModel !==
      WORK_AMO_V5_RAW_BLOCK_DESCRIPTOR_MODEL ||
    !blockDescriptorCommitment ||
    !Number.isSafeInteger(blockTransactionCount) ||
    blockTransactionCount < 1 ||
    !bip141Witness ||
    prior.payload?.transitionChainModel !==
      WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL ||
    !transitionChainCommitment ||
    commitment.sha256 !==
      String(prior?.closing_state_sha256 ?? "").trim().toLowerCase() ||
    commitment.payloadBytes !==
      Number(prior?.closing_state_payload_bytes) ||
    commitment.sha256 !==
      String(payloadCommitment?.sha256 ?? "").trim().toLowerCase() ||
    commitment.payloadBytes !==
      Number(payloadCommitment?.payloadBytes) ||
    !closingTokenStateCommitment ||
    closingTokenStateCommitment.sha256 !==
      validation.state.tokenStateCommitment.sha256 ||
    closingTokenStateCommitment.payloadBytes !==
      validation.state.tokenStateCommitment.payloadBytes ||
    !closingGenericTokenStateCommitment ||
    closingGenericTokenStateCommitment.sha256 !==
      validation.state.genericTokenStateCommitment.sha256 ||
    closingGenericTokenStateCommitment.payloadBytes !==
      validation.state.genericTokenStateCommitment.payloadBytes ||
    !closingIdStateCommitment ||
    closingIdStateCommitment.sha256 !==
      validation.state.idStateCommitment.sha256 ||
    closingIdStateCommitment.payloadBytes !==
      validation.state.idStateCommitment.payloadBytes ||
    validation.state.networkValueQ8 !==
      String(prior?.closing_network_value_q8 ?? "")
  ) {
    throw new Error(
      "Canonical AMO prior transition state commitment diverged.",
    );
  }
  const quoteHead = await proofIndexWorkUsdQuoteHead(network, {
      blockHeight: priorHeight + 1,
      blockIndex: 0,
      protocolVout: 0,
      recordOrdinal: 0,
    });
  const storedQuote =
    workAmoV5QuoteHeadCommitmentProjection(
      validation.state.quoteHead,
    );
  const relationalQuote =
    workAmoV5QuoteHeadCommitmentProjection(quoteHead);
  if (
    (storedQuote === null) !== (relationalQuote === null) ||
    (storedQuote &&
      workAmoV5CanonicalPayloadCommitment(storedQuote).sha256 !==
        workAmoV5CanonicalPayloadCommitment(relationalQuote).sha256)
  ) {
    throw new Error(
      "Canonical AMO prior transition does not match H-1 canonical quote state.",
    );
  }
  return {
    genericState: prior.payload.closingGenericTokenState,
    idState: prior.payload.closingIdState,
    priorTransition: prior,
    state: validation.state,
    workProjection:
      prior.payload.closingWorkProjection ?? null,
    workState: prior.payload.closingTokenState,
  };
}

async function workAmoV5OpeningAccumulatorState(
  network,
  priorHeight,
  priorBlockHash,
  persistedActivationSeed = null,
) {
  if (
    network !== "livenet" ||
    !Number.isSafeInteger(priorHeight) ||
    priorHeight < WORK_AMO_V5_DECLARATION_HEIGHT ||
    !/^[0-9a-f]{64}$/u.test(String(priorBlockHash ?? "").toLowerCase())
  ) {
    throw new Error("Canonical AMO opening checkpoint is invalid.");
  }
  if (priorHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT) {
    return workAmoV5OpeningAccumulatorFromPriorTransition(
      network,
      priorHeight,
      priorBlockHash,
    );
  }
  let validatedPersistedActivationSeed = null;
  if (persistedActivationSeed) {
    const validation = validateWorkAmoV5SufficientState(
      persistedActivationSeed.state,
    );
    const stateCommitment = validation.valid
      ? workAmoV5CanonicalStateCommitment(validation.state)
      : null;
    const declaredCommitment =
      persistedActivationSeed.stateCommitment;
    let genericState;
    let idState;
    let workProjection;
    let workState;
    let genericStateCommitment;
    let idStateCommitment;
    let workProjectionCommitment;
    let workStateCommitment;
    try {
      if (
        !workAmoV5JsonNumbersAreExact(
          persistedActivationSeed,
        )
      ) {
        throw new Error("unsafe persisted seed number");
      }
      genericState = normalizeWorkAmoV5RawGenericState(
        persistedActivationSeed.genericState,
      );
      idState = normalizeWorkAmoV5RawIdState(
        persistedActivationSeed.idState,
      );
      workProjection = normalizeWorkAmoV5RawWorkState(
        persistedActivationSeed.workProjection,
      );
      workState = normalizeWorkAmoV5RawWorkState(
        persistedActivationSeed.workState,
      );
      genericStateCommitment =
        workAmoV5RawGenericStateCommitment(genericState);
      idStateCommitment =
        workAmoV5RawIdStateCommitment(idState);
      workProjectionCommitment =
        workAmoV6CanonicalTokenStateCommitment(workProjection);
      workStateCommitment =
        workAmoV6CanonicalTokenStateCommitment(workState);
    } catch {
      genericStateCommitment = null;
      idStateCommitment = null;
      workProjectionCommitment = null;
      workStateCommitment = null;
    }
    if (
      !validation.valid ||
      validation.state.throughBlockHeight !== priorHeight ||
      validation.state.throughBlockHash !== priorBlockHash ||
      stateCommitment.sha256 !==
        String(declaredCommitment?.sha256 ?? "")
          .trim()
          .toLowerCase() ||
      stateCommitment.payloadBytes !==
        Number(declaredCommitment?.payloadBytes) ||
      !genericStateCommitment ||
      genericStateCommitment.sha256 !==
        validation.state.genericTokenStateCommitment.sha256 ||
      genericStateCommitment.payloadBytes !==
        validation.state.genericTokenStateCommitment.payloadBytes ||
      !idStateCommitment ||
      idStateCommitment.sha256 !==
        validation.state.idStateCommitment.sha256 ||
      idStateCommitment.payloadBytes !==
        validation.state.idStateCommitment.payloadBytes ||
      !workStateCommitment ||
      workStateCommitment.sha256 !==
        validation.state.tokenStateCommitment.sha256 ||
      workStateCommitment.payloadBytes !==
        validation.state.tokenStateCommitment.payloadBytes ||
      !workProjectionCommitment ||
      workProjectionCommitment.sha256 !==
        workStateCommitment.sha256 ||
      workProjectionCommitment.payloadBytes !==
        workStateCommitment.payloadBytes
    ) {
      throw new Error(
        "Canonical AMO persisted activation seed is invalid.",
      );
    }
    validatedPersistedActivationSeed = {
      commitment: stateCommitment,
      genericStateCommitment,
      idStateCommitment,
      state: validation.state,
      workProjectionCommitment,
      workStateCommitment,
    };
  }
  const [
    summary,
    rawTokenState,
    rawGenericState,
    rawIdState,
    quoteHead,
    openingStatusBefore,
  ] =
    await Promise.all([
    proofIndexCanonicalSummaryLedgerPayload(
      network,
      priorHeight,
      priorBlockHash,
    ),
    proofIndexTokenPayload(
      network,
      WORK_TOKEN_ID,
      new URLSearchParams(),
    ),
    proofIndexWorkAmoGenericTokenStatePreimage(network, {
      blockHash: priorBlockHash,
      blockHeight: priorHeight,
    }),
    proofIndexRegistryPayload(network, {
      allowIncompleteScan: true,
      expectedHash: priorBlockHash,
      expectedHeight: priorHeight,
      registryAddress: registryAddressForNetwork(network),
    }),
    proofIndexWorkUsdQuoteHead(network, {
      blockHeight: priorHeight + 1,
      blockIndex: 0,
      protocolVout: 0,
      recordOrdinal: 0,
    }),
    proofIndexOperationalStatusPayload(network),
  ]);
  const openingStatusAfter =
    await proofIndexOperationalStatusPayload(network);
  const tokenState =
    await workAmoV5WorkStateWithCanonicalListingWitnesses(
      rawTokenState,
      network,
    );
  const actual = summary?.workFloor?.actualValue;
  if (
    !summary ||
    Number(summary.indexedThroughBlock) !== priorHeight ||
    String(summary.indexedThroughBlockHash ?? "").trim().toLowerCase() !==
      priorBlockHash ||
    !actual ||
    Number(tokenState?.indexedThroughBlock) !== priorHeight ||
    rawGenericState?.complete !== true ||
    Number(rawGenericState?.indexedThroughBlock) !== priorHeight ||
    String(rawGenericState?.indexedThroughBlockHash ?? "")
      .trim()
      .toLowerCase() !== priorBlockHash ||
    !rawIdState ||
    Number(rawIdState?.indexedThroughBlock) !== priorHeight ||
    String(rawIdState?.indexedThroughBlockHash ?? "")
      .trim()
      .toLowerCase() !== priorBlockHash ||
    Number(openingStatusBefore?.indexedThroughBlock) !== priorHeight ||
    String(openingStatusBefore?.scan?.blockHash ?? "")
      .trim()
      .toLowerCase() !== priorBlockHash ||
    Number(openingStatusAfter?.indexedThroughBlock) !== priorHeight ||
    String(openingStatusAfter?.scan?.blockHash ?? "")
      .trim()
      .toLowerCase() !== priorBlockHash
  ) {
    throw new Error(
      "Canonical AMO H-1 summary or token state is unavailable.",
    );
  }
  const baseState = {};
  for (const field of WORK_AMO_V5_BASE_STATE_FIELDS) {
    const value = workAmoV5ExactInteger(actual[field]);
    if (value === null) {
      throw new Error(
        `Canonical AMO opening base field ${field} is unavailable.`,
      );
    }
    baseState[field] = value.toString();
  }
  const baseNetworkValueQ8 = workAmoV5ExactInteger(
    actual.baseNetworkValueQ8,
  );
  const creditEventFrozenValueQ8 = workAmoV5ExactInteger(
    actual.creditEventFrozenValueQ8,
  );
  const creditMovementFrozenValueQ8 = workAmoV5ExactInteger(
    actual.creditMovementFrozenValueQ8,
  );
  const expectedMovementLiveValueQ8 = workAmoV5ExactInteger(
    actual.creditMovementLiveValueQ8,
  );
  const expectedFrozenNetworkValueQ8 = workAmoV5ExactInteger(
    actual.frozenNetworkValueQ8,
  );
  const expectedNetworkValueQ8 = workAmoV5ExactInteger(
    actual.networkValueQ8,
    { positive: true },
  );
  if (
    baseNetworkValueQ8 === null ||
    creditEventFrozenValueQ8 === null ||
    creditMovementFrozenValueQ8 === null ||
    creditEventFrozenValueQ8 < creditMovementFrozenValueQ8 ||
    expectedMovementLiveValueQ8 === null ||
    expectedFrozenNetworkValueQ8 === null ||
    expectedNetworkValueQ8 === null
  ) {
    throw new Error("Canonical AMO opening exact Q8 fields are unavailable.");
  }
  const baseBigIntState = Object.fromEntries(
    Object.entries(baseState).map(([field, value]) => [field, BigInt(value)]),
  );
  if (
    growthActualBaseStateTotalQ8(baseBigIntState) !== baseNetworkValueQ8
  ) {
    throw new Error("Canonical AMO opening base vector does not match H-1.");
  }
  const movements = workAmoV5HistoricalMovements(tokenState, priorHeight).map(
    ({ amountAtoms, identity }) => ({ amountAtoms, identity }),
  );
  const openingGenericState =
    normalizeWorkAmoV5RawGenericState(
      rawGenericState,
    );
  if (
    openingGenericState.tokens.length !==
      rawGenericState.tokens.length ||
    openingGenericState.holders.length !==
      rawGenericState.holders.length ||
    openingGenericState.listings.length !==
      rawGenericState.listings.length
  ) {
    throw new Error(
      "Canonical AMO activation generic token preimage is inexact.",
    );
  }
  const openingIdState =
    normalizeWorkAmoV5RawIdState(rawIdState);
  const openingWorkState =
    normalizeWorkAmoV5RawWorkState(
      workAmoV5TokenStateCommitmentProjection(tokenState),
    );
  const indexedWorkState =
    normalizeWorkAmoV5RawWorkState(
      workAmoV5TokenStateCommitmentProjection(tokenState),
    );
  if (
    workAmoV5CanonicalPayloadCommitment(openingWorkState).sha256 !==
      workAmoV5CanonicalPayloadCommitment(indexedWorkState).sha256
  ) {
    throw new Error(
      "Canonical AMO activation WORK seed diverges from H-1.",
    );
  }
  const state = workAmoV5AccumulatorWithRecomputedValue({
    baseState,
    creditFixedQ8: (
      creditEventFrozenValueQ8 - creditMovementFrozenValueQ8
    ).toString(),
    creditMovementFrozenValueQ8:
      creditMovementFrozenValueQ8.toString(),
    model: WORK_AMO_V5_NETWORK_ACCUMULATOR_MODEL,
    movements,
    network,
    networkValueQ8: expectedNetworkValueQ8.toString(),
    quoteHead,
    throughBlockHash: priorBlockHash,
    throughBlockHeight: priorHeight,
    genericTokenStateCommitment:
      workAmoV5RawGenericStateCommitment(openingGenericState),
    idStateCommitment:
      workAmoV5RawIdStateCommitment(openingIdState),
    tokenStateCommitment: workAmoV6CanonicalTokenStateCommitment(
      openingWorkState,
    ),
  });
  const evaluated = workAmoV5AccumulatorNetworkValueQ8(state);
  if (
    evaluated.baseNetworkValueQ8 !== baseNetworkValueQ8 ||
    evaluated.creditMovementLiveValueQ8 !==
      expectedMovementLiveValueQ8 ||
    evaluated.frozenNetworkValueQ8 !== expectedFrozenNetworkValueQ8 ||
    evaluated.networkValueQ8 !== expectedNetworkValueQ8 ||
    !workAmoV5NetworkValueQ8FromSufficientState(state)
  ) {
    throw new Error(
      "Canonical AMO opening sufficient state does not reproduce H-1.",
    );
  }
  const opening = {
    genericState: openingGenericState,
    idState: openingIdState,
    state,
    summary,
    tokenState,
    workProjection: openingWorkState,
    workState: openingWorkState,
  };
  if (validatedPersistedActivationSeed) {
    const independentStateCommitment =
      workAmoV5CanonicalStateCommitment(state);
    const independentGenericStateCommitment =
      workAmoV5RawGenericStateCommitment(openingGenericState);
    const independentIdStateCommitment =
      workAmoV5RawIdStateCommitment(openingIdState);
    const independentWorkStateCommitment =
      workAmoV6CanonicalTokenStateCommitment(openingWorkState);
    const independentWorkProjectionCommitment =
      workAmoV6CanonicalTokenStateCommitment(
        normalizeWorkAmoV5RawWorkState(tokenState),
      );
    if (
      validatedPersistedActivationSeed.commitment.sha256 !==
        independentStateCommitment.sha256 ||
      validatedPersistedActivationSeed.commitment.payloadBytes !==
        independentStateCommitment.payloadBytes ||
      validatedPersistedActivationSeed.genericStateCommitment.sha256 !==
        independentGenericStateCommitment.sha256 ||
      validatedPersistedActivationSeed.genericStateCommitment.payloadBytes !==
        independentGenericStateCommitment.payloadBytes ||
      validatedPersistedActivationSeed.idStateCommitment.sha256 !==
        independentIdStateCommitment.sha256 ||
      validatedPersistedActivationSeed.idStateCommitment.payloadBytes !==
        independentIdStateCommitment.payloadBytes ||
      validatedPersistedActivationSeed.workStateCommitment.sha256 !==
        independentWorkStateCommitment.sha256 ||
      validatedPersistedActivationSeed.workStateCommitment.payloadBytes !==
        independentWorkStateCommitment.payloadBytes ||
      validatedPersistedActivationSeed.workProjectionCommitment.sha256 !==
        independentWorkProjectionCommitment.sha256 ||
      validatedPersistedActivationSeed.workProjectionCommitment.payloadBytes !==
        independentWorkProjectionCommitment.payloadBytes
    ) {
      throw new Error(
        "Canonical AMO persisted activation seed diverges from independent H-1 evidence.",
      );
    }
    opening.persistedActivationSeedVerified = true;
  }
  return opening;
}

async function workAmoV5HMinusOneSeedEvidencePayload(
  network,
  {
    blockHash,
    blockHeight,
  } = {},
) {
  const requiredBlockHeight = Number(blockHeight);
  const requiredBlockHash = String(blockHash ?? "").trim().toLowerCase();
  if (
    network !== "livenet" ||
    requiredBlockHeight !== WORK_AMO_V5_ACTIVATION_HEIGHT - 1 ||
    requiredBlockHash !== WORK_AMO_V5_DECLARATION_BLOCK_HASH
  ) {
    const error = new Error(
      "The AMO V5 seed-evidence producer requires the exact livenet H-1 declaration checkpoint.",
    );
    error.statusCode = 400;
    throw error;
  }
  const opening = await workAmoV5OpeningAccumulatorState(
    network,
    requiredBlockHeight,
    requiredBlockHash,
  );
  return canonicalWorkAmoV5HMinusOneSeedEvidence({
    canonicalSummary: {
      canonicalSummaryHash: opening.summary?.canonicalSummaryHash,
      networkValueQ8: opening.summary?.workNetworkValueQ8,
      snapshotId: opening.summary?.snapshotId,
    },
    indexedThroughBlock: requiredBlockHeight,
    indexedThroughBlockHash: requiredBlockHash,
    network,
    seedGenericTokenState: opening.genericState,
    seedIdState: opening.idState,
    seedSufficientState: opening.state,
    seedTokenState: opening.workState,
    seedWorkProjection: opening.workProjection,
  });
}

function workAmoV5ProtocolRecordsForCurrentBlock(
  transactions,
  blockHeight,
  blockHash,
) {
  const records = [];
  let rawProtocolCandidateCount = 0;
  for (const tx of tokenProtocolSortedTransactions(
    (Array.isArray(transactions) ? transactions : []).filter(
      (candidate) =>
        transactionConfirmed(candidate) &&
        transactionBlockHeight(candidate) === blockHeight &&
        transactionBlockHash(candidate) === blockHash,
    ),
  )) {
    const txid = transactionTxid(tx);
    const blockTransactionIndex = transactionBlockIndex(tx);
    if (
      !/^[0-9a-f]{64}$/u.test(txid) ||
      !Number.isSafeInteger(blockTransactionIndex) ||
      blockTransactionIndex < 0
    ) {
      throw new Error("Canonical AMO Core transaction position is invalid.");
    }
    const rawRecordSet =
      canonicalRawProtocolRecordSetFromTransaction(tx);
    rawProtocolCandidateCount +=
      rawRecordSet.rawProtocolCandidateCount;
    const txRecords = rawRecordSet.records;
    const minerFeeSatsText = canonicalNonNegativeIntegerText(
      transactionMinerFeeSats(tx),
    );
    if (!minerFeeSatsText) {
      throw new Error(
        `Canonical AMO transaction miner fee is unavailable for ${txid}.`,
      );
    }
    for (const record of txRecords) {
      records.push({
        ...record,
        position: {
          blockHash,
          blockHeight,
          blockTransactionIndex,
          protocolVout: record.protocolVout,
          recordOrdinal: record.recordOrdinal,
        },
        transactionMinerFeeSats: minerFeeSatsText,
        transactionProtocolRecordCount: txRecords.length,
        tx,
        txid,
      });
    }
  }
  return {
    rawProtocolCandidateCount,
    records: records.sort((left, right) =>
      compareCanonicalProtocolPositionForAmo(left.position, right.position),
    ),
  };
}

function compareCanonicalProtocolPositionForAmo(left, right) {
  const fields = [
    "blockHeight",
    "blockTransactionIndex",
    "protocolVout",
    "recordOrdinal",
  ];
  for (const [index, field] of fields.entries()) {
    const minimum = index === 0 ? 1 : 0;
    const leftValue = exactCanonicalAmoPositionInteger(
      left?.[field],
      minimum,
    );
    const rightValue = exactCanonicalAmoPositionInteger(
      right?.[field],
      minimum,
    );
    if (
      leftValue === null ||
      rightValue === null
    ) {
      throw new Error(
        "Canonical AMO V5 comparison position is incomplete.",
      );
    }
    const difference = leftValue - rightValue;
    if (difference !== 0) {
      return difference;
    }
  }
  return 0;
}

function workAmoV5RecordKey(txid, protocolVout, recordOrdinal) {
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  const normalizedProtocolVout =
    exactCanonicalAmoPositionInteger(protocolVout);
  const normalizedRecordOrdinal =
    exactCanonicalAmoPositionInteger(recordOrdinal);
  if (
    !/^[0-9a-f]{64}$/u.test(normalizedTxid) ||
    normalizedProtocolVout === null ||
    normalizedRecordOrdinal === null
  ) {
    throw new Error(
      "Canonical AMO V5 replay record key is incomplete.",
    );
  }
  return [
    normalizedTxid,
    normalizedProtocolVout,
    normalizedRecordOrdinal,
  ].join(":");
}

function workAmoV5RecordPositionKey(record) {
  return workAmoV5RecordKey(
    record?.txid,
    record?.position?.protocolVout ?? record?.protocolVout,
    record?.position?.recordOrdinal ?? record?.recordOrdinal,
  );
}

async function workAmoV6ReplayInputsForBlock(
  _records,
  requiredBlockHeight,
) {
  if (
    !WORK_AMO_V6_DECLARATION_PINS_CONFIGURED ||
    requiredBlockHeight < WORK_AMO_V6_ACTIVATION_HEIGHT
  ) {
    return {
      referenceBlockWitnesses: [],
      workAmoV6: null,
    };
  }
  const canonicalDeclarationHashResult = await bitcoinRpc(
    "getblockhash",
    [WORK_AMO_V6_DECLARATION_HEIGHT],
  );
  const canonicalDeclarationHash = String(
    canonicalDeclarationHashResult?.ok
      ? canonicalDeclarationHashResult.result
      : "",
  ).trim().toLowerCase();
  if (
    canonicalDeclarationHash !==
      WORK_AMO_V6_DECLARATION_BLOCK_HASH
  ) {
    throw new Error(
      "Canonical AMO V6 declaration anchor is unavailable.",
    );
  }
  const expectedDeclaration = configuredWorkAmoV6Declaration();
  const migrationReadiness =
    await proofIndexWorkAmoV6MigrationReadiness(
      "livenet",
      expectedDeclaration,
    ).catch(() => null);
  if (
    !expectedDeclaration ||
    migrationReadiness?.ready !== true ||
    migrationReadiness?.active !== true ||
    migrationReadiness?.canonical !== true ||
    migrationReadiness?.confirmed !== true ||
    migrationReadiness?.evidenceComplete !== true ||
    Number(migrationReadiness?.activationHeight) !==
      WORK_AMO_V6_ACTIVATION_HEIGHT
  ) {
    throw new Error(
      "Canonical AMO V6 declaration migration evidence is unavailable.",
    );
  }
  return {
    referenceBlockWitnesses: [],
    workAmoV6: {
      activationHeight: WORK_AMO_V6_ACTIVATION_HEIGHT,
    },
  };
}

function workAmoV8OpeningStateFromLegacy(legacyState) {
  const preimage =
    workAmoV6CanonicalTokenStatePreimage(legacyState);
  const scaled = {
    amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
    confirmedSupplySubatoms: (
      BigInt(preimage.confirmedSupplyAtoms) *
      WORK_SUBATOM_CONVERSION_FACTOR
    ).toString(),
    holders: preimage.holders.map((holder) => ({
      address: holder.address,
      balanceSubatoms: (
        BigInt(holder.balanceAtoms) *
        WORK_SUBATOM_CONVERSION_FACTOR
      ).toString(),
    })),
    listings: [],
  };
  return workAmoV8CanonicalTokenStatePreimage(scaled);
}

async function workAmoV8ReplayInputsForBlock(
  context,
  requiredBlockHeight,
) {
  const requiredHeight = Number(requiredBlockHeight);
  if (
    !Number.isSafeInteger(requiredHeight) ||
    requiredHeight < 1 ||
    Number(context?.coverageHeight) !== requiredHeight ||
    Number(context?.indexedThroughBlock) !== requiredHeight
  ) {
    throw new Error(
      "Canonical AMO V8 replay context does not match the required block height.",
    );
  }
  const configuredDeclaration =
    configuredWorkAmoV8Declaration();
  const latch =
    await proofIndexWorkAmoV8ActivationLatch(
      "livenet",
      configuredDeclaration,
    ).catch(() => null);
  if (latch?.reached !== true) {
    const discovery =
      await discoverExactWorkAmoV8Declaration(
        "livenet",
        {
          canonicalPrefix: context,
          force: true,
        },
      );
    if (discovery?.checked !== true) {
      throw new Error(
        "Canonical AMO V8 declaration discovery is unavailable during block replay.",
      );
    }
    const discoveredActivationHeight = Number(
      discovery?.declaration?.activationHeight,
    );
    if (
      discovery?.declaration &&
      Number.isSafeInteger(discoveredActivationHeight) &&
      requiredBlockHeight >= discoveredActivationHeight
    ) {
      throw new Error(
        "Canonical AMO V8 activated without a persistent Q16 migration latch.",
      );
    }
    return { workAmoV8: null };
  }
  const activationHeight = Number(
    latch?.pins?.activationHeight ??
      latch?.activationHeight ??
      configuredDeclaration?.activationHeight,
  );
  if (
    !Number.isSafeInteger(activationHeight) ||
    activationHeight < 2 ||
    requiredBlockHeight < activationHeight
  ) {
    return { workAmoV8: null };
  }
  if (
    latch?.markerReady !== true ||
    Number(latch?.activationHeight) !==
      activationHeight
  ) {
    throw new Error(
      "Canonical AMO V8 activation and Q16 migration evidence is unavailable.",
    );
  }
  return {
    workAmoV8: {
      activationHeight,
      amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
    },
  };
}

async function completeWorkAmoV5BlockProjection(
  context,
  network,
  requiredBlockHeight,
) {
  if (
    network !== "livenet" ||
    requiredBlockHeight < WORK_AMO_V5_ACTIVATION_HEIGHT
  ) {
    return null;
  }
  const priorHeight = requiredBlockHeight - 1;
  const blockHash = String(context?.blockHash ?? "").trim().toLowerCase();
  const previousBlockHash = String(context?.previousBlockHash ?? "")
    .trim()
    .toLowerCase();
  let persistedActivationSeed = null;
  if (requiredBlockHeight === WORK_AMO_V5_ACTIVATION_HEIGHT) {
    const stored = await proofIndexWorkAmoBlockTransition(
      network,
      requiredBlockHeight,
      blockHash,
    );
    if (stored) {
      if (
        stored.previousBlockHash !== previousBlockHash ||
        stored.payload?.previousBlockHash !== previousBlockHash ||
        stored.payload?.blockHash !== blockHash ||
        stored.payload?.blockHeight !== requiredBlockHeight ||
        !stored.payload?.seedGenericTokenState ||
        !stored.payload?.seedIdState ||
        !stored.payload?.seedTokenState ||
        !stored.payload?.seedWorkProjection ||
        !stored.payload?.seedSufficientState ||
        !stored.payload?.seedSufficientStateCommitment
      ) {
        throw new Error(
          "Canonical AMO stored activation transition seed is incomplete.",
        );
      }
      persistedActivationSeed = {
        genericState: stored.payload.seedGenericTokenState,
        idState: stored.payload.seedIdState,
        state: stored.payload.seedSufficientState,
        stateCommitment:
          stored.payload.seedSufficientStateCommitment,
        workProjection: stored.payload.seedWorkProjection,
        workState: stored.payload.seedTokenState,
      };
    }
  }
  let opening = await workAmoV5OpeningAccumulatorState(
    network,
    priorHeight,
    previousBlockHash,
    persistedActivationSeed,
  );
  const protocolEnvelope = workAmoV5ProtocolRecordsForCurrentBlock(
    context.transactions,
    requiredBlockHeight,
    blockHash,
  );
  const v6ReplayInputs = await workAmoV6ReplayInputsForBlock(
    protocolEnvelope.records,
    requiredBlockHeight,
  );
  const v7ReplayInputs =
    await workAmoV8ReplayInputsForBlock(
      context,
      requiredBlockHeight,
    );
  const v7ActivationHeight = Number(
    v7ReplayInputs.workAmoV8?.activationHeight,
  );
  if (
    v7ReplayInputs.workAmoV8 &&
    requiredBlockHeight === v7ActivationHeight
  ) {
    const q16OpeningWorkState =
      workAmoV8OpeningStateFromLegacy(opening.workState);
    const q16TokenStateCommitment =
      workAmoV8CanonicalTokenStateCommitment(
        q16OpeningWorkState,
      );
    const q16OpeningValidation =
      validateWorkAmoV5SufficientState({
        ...opening.state,
        tokenStateCommitment: q16TokenStateCommitment,
      });
    if (!q16OpeningValidation.valid) {
      throw new Error(
        "Canonical AMO V8 Q16 activation opening state is invalid.",
      );
    }
    opening = {
      ...opening,
      state: q16OpeningValidation.state,
      workState: q16OpeningWorkState,
    };
  }
  const replay = replayWorkAmoV5RawBlock({
    blockHeaderHex: context.blockHeaderHex,
    blockTransactions: context.blockTransactions,
    expectedBlockHash: blockHash,
    expectedBlockHeight: requiredBlockHeight,
    expectedPreviousBlockHash: previousBlockHash,
    openingEconomicState: opening.state,
    openingGenericState: opening.genericState,
    openingIdState: opening.idState,
    openingWorkState: opening.workState,
    referenceBlockWitnesses:
      v6ReplayInputs.referenceBlockWitnesses,
    records: protocolEnvelope.records,
    workAmoV6: v6ReplayInputs.workAmoV6,
    workAmoV8: v7ReplayInputs.workAmoV8,
  });
  const bip141Witness = normalizedWorkAmoV5Bip141Witness(
    replay.bip141Witness,
    replay.blockTransactionCount,
  );
  if (
    replay.protocolRecordCount !== protocolEnvelope.records.length ||
    replay.rawProtocolCandidateCount !==
      protocolEnvelope.rawProtocolCandidateCount ||
    replay.transitionChainModel !==
      WORK_AMO_V5_RAW_TRANSITION_CHAIN_MODEL ||
    replay.blockDescriptorModel !==
      WORK_AMO_V5_RAW_BLOCK_DESCRIPTOR_MODEL ||
    !exactWorkAmoV5RawBlockDescriptorCommitment(
      replay.blockDescriptorCommitment,
    ) ||
    replay.blockTransactionCount !==
      context.blockTransactions.length ||
    !bip141Witness ||
    !exactWorkAmoV5RawTransitionChainCommitment(
      replay.transitionChainCommitment,
    ) ||
    replay.events.some(
      (event) =>
        !exactWorkAmoV5RawTransitionChainCommitment(
          event?.transitionChainCommitmentAfter,
        ) ||
        (Array.isArray(event?.derived)
          ? event.derived
          : []
        ).some(
          (derived) =>
            !workAmoV5RawTransitionChainCommitmentsEqual(
              derived?.parentTransitionChainCommitmentAfter,
              event?.transitionChainCommitmentAfter,
            ),
        ),
    ) ||
    replay.feeTransitions.some(
      (fee) =>
        !exactWorkAmoV5RawTransitionChainCommitment(
          fee?.transitionChainCommitmentAfter,
        ),
    )
  ) {
    throw new Error(
      "Canonical AMO raw replay candidate or transition-chain accounting diverged.",
    );
  }
  const eventsByKey = new Map(
    replay.events.map((event) => [
      workAmoV5RecordKey(
        event.txid,
        event.position.protocolVout,
        event.position.recordOrdinal,
      ),
      event,
    ]),
  );
  const rawReplayRecords = replay.records.map((record) => {
    const event = eventsByKey.get(workAmoV5RecordPositionKey(record));
    if (!event) {
      throw new Error(
        "Canonical AMO raw replay descriptor is missing an outcome.",
      );
    }
    return {
      derived: event.derived,
      rawCandidate: true,
      outcome: {
        kind: workAmoV5ConsensusEventKind(
          record.protocol,
          event.valid,
        ),
        reasonCode: event.valid ? "" : event.reasonCode,
        semanticKind: event.semanticKind,
        valid: event.valid,
      },
      output: event.output,
      position: record.position,
      protocol: record.protocol,
      rawWitness: record.payload,
      stateDelta: event.stateDelta,
      transitionChainCommitmentAfter:
        event.transitionChainCommitmentAfter,
      transactionMinerFeeSats:
        record.transactionMinerFeeSats,
      transactionProtocolRecordCount:
        record.transactionProtocolRecordCount,
      txid: record.txid,
    };
  });
  const derivedReplayRecords = rawReplayRecords.flatMap((parent) =>
    (Array.isArray(parent.derived) ? parent.derived : []).map(
      (derived) => {
        const derivedProtocol = [
          "pwid1",
          "pwt1",
        ].includes(derived.protocol)
          ? derived.protocol
          : "pwt1";
        const projection = {
          ...derived,
          derived: true,
          kind: derived.kind,
          position: derived.projectionPosition,
          protocol: derivedProtocol,
          reasonCode: "",
          txid: parent.txid,
          valid: true,
        };
        return {
          chargesTransactionFee: false,
          derived: true,
          outcome: {
            kind: workAmoV5ConsensusEventKind(
              derivedProtocol,
              true,
            ),
            reasonCode: "",
            semanticKind: derived.kind,
            valid: true,
          },
          output: {
            projection,
          },
          parentPosition: parent.position,
          position: derived.projectionPosition,
          protocol: derivedProtocol,
          rawCandidate: false,
          rawWitness: {
            descriptor: derived,
            model: "canonical-work-amo-v5-derived-child-v1",
            parentPosition: parent.position,
            parentProtocol: parent.protocol,
          },
          parentTransitionChainCommitmentAfter:
            derived.parentTransitionChainCommitmentAfter,
          stateDelta: {
            baseContributions: [],
            creditFixedQ8: "0",
            creditFixedSats: "0",
            economicOutputs: [],
          },
          transactionMinerFeeSats:
            parent.transactionMinerFeeSats,
          transactionProtocolRecordCount:
            parent.transactionProtocolRecordCount,
          txid: parent.txid,
        };
      },
    ),
  );
  const replayRecords = [
    ...rawReplayRecords,
    ...derivedReplayRecords,
  ].sort((left, right) =>
    compareCanonicalProtocolPositionForAmo(
      left.position,
      right.position,
    ),
  );
  const replayDescriptorCommitment =
    workAmoV5CanonicalPayloadCommitment(replayRecords);
  const eventSetCommitment = workAmoV5EventSetCommitment(
    replayRecords.map((record) => ({
      kind: record.outcome.kind,
      outcome: record.outcome,
      payload: record.rawWitness,
      position: record.position,
      protocol: record.protocol,
      reasonCode: record.outcome.reasonCode,
      stateDelta: record.stateDelta,
      transactionMinerFeeSats:
        record.transactionMinerFeeSats,
      txid: record.txid,
      valid: record.outcome.valid,
    })),
  );
  const feeByTxid = new Map(
    replay.feeTransitions.map((trace) => [trace.txid, trace]),
  );
  const traces = [];
  for (let index = 0; index < rawReplayRecords.length; index += 1) {
    const record = rawReplayRecords[index];
    traces.push({
      bondContributionQ8:
        replay.outcomes.get(
          workAmoV5RecordPositionKey(record),
        )?.bondContributionQ8 ?? "0",
      kind: "protocol-record",
      networkValueAfterQ8:
        replay.outcomes.get(
          workAmoV5RecordPositionKey(record),
        )?.networkValueAfterQ8,
      networkValueBeforeQ8:
        replay.outcomes.get(
          workAmoV5RecordPositionKey(record),
        )?.networkValueBeforeQ8,
      output: record.output,
      position: record.position,
      rawWitness: record.rawWitness,
      reasonCode: record.outcome.reasonCode,
      stateDelta: record.stateDelta,
      transitionChainCommitmentAfter:
        record.transitionChainCommitmentAfter,
      txid: record.txid,
      valid: record.outcome.valid,
    });
    if (rawReplayRecords[index + 1]?.txid !== record.txid) {
      const fee = feeByTxid.get(record.txid);
      if (!fee) {
        throw new Error(
          "Canonical AMO raw replay fee trace is missing.",
        );
      }
      traces.push({
        ...fee,
        kind: "transaction-fee",
        reasonCode: fee.valid
          ? ""
          : "work-amo-v5-invalid-only-transaction",
      });
    }
  }
  const closingWorkProjection = projectWorkAmoV5RawEvents(
    opening.workProjection ?? opening.workState,
    replay.events,
    replay.workState,
  );
  const openingStateCommitment =
    workAmoV5CanonicalStateCommitment(opening.state);
  const transition = {
    bip141Witness,
    blockAtomic: true,
    blockDescriptorCommitment:
      replay.blockDescriptorCommitment,
    blockDescriptorModel: replay.blockDescriptorModel,
    blockHash,
    blockHeight: requiredBlockHeight,
    blockTransactionCount: replay.blockTransactionCount,
    closingGenericTokenState: replay.genericState,
    closingIdState: replay.idState,
    closingNetworkValueQ8: replay.economicState.networkValueQ8,
    closingStateCommitment: replay.stateCommitment,
    closingSufficientState: replay.economicState,
    closingTokenState: replay.workState,
    closingWorkProjection,
    complete: true,
    eventCount:
      replay.protocolRecordCount + replay.derivedEventCount,
    eventSetCommitment,
    feeOnce: true,
    invalidZero: true,
    model: v7ReplayInputs.workAmoV8
      ? "canonical-work-amo-full-position-block-sequencer-v4"
      : WORK_AMO_V5_BLOCK_SEQUENCER_MODEL,
    network,
    openingNetworkValueQ8: opening.state.networkValueQ8,
    openingStateCommitment,
    openingSufficientState: opening.state,
    previousBlockHash,
    protocolRecordCount: replay.protocolRecordCount,
    rawProtocolCandidateCount: replay.rawProtocolCandidateCount,
    replayDescriptorCommitment,
    replayRecords,
    ...(v6ReplayInputs.workAmoV6
      ? {
          referenceBlockWitnesses:
            replay.referenceBlockWitnesses,
          workAmoV6: v6ReplayInputs.workAmoV6,
        }
      : {}),
    ...(v7ReplayInputs.workAmoV8
      ? {
          precisionMigrationMarkerKey:
            "workPrecisionV2Migration:livenet",
          workAmoV8: v7ReplayInputs.workAmoV8,
          workTokenStateModel:
            "canonical-work-token-state-subatoms-v3",
          ...(requiredBlockHeight ===
          v7ActivationHeight
            ? {
                activationHeight:
                  v7ActivationHeight,
                precisionOpeningTokenStateCommitment:
                  workAmoV8CanonicalTokenStateCommitment(
                    opening.workState,
                  ),
              }
            : {}),
        }
      : {}),
    ...(requiredBlockHeight === WORK_AMO_V5_ACTIVATION_HEIGHT
      ? {
          seedGenericTokenState: opening.genericState,
          seedIdState: opening.idState,
          seedSufficientState: opening.state,
          seedSufficientStateCommitment:
            openingStateCommitment,
          seedTokenState: opening.workState,
          seedWorkProjection: opening.workProjection,
        }
      : {}),
    traces,
    transitionChainCommitment: replay.transitionChainCommitment,
    transitionChainModel: replay.transitionChainModel,
    transactionCount: replay.transactionCount,
  };
  return {
    closingState: replay.economicState,
    transition,
    workState: {
      ...closingWorkProjection,
      workAmoV5BlockTransition: transition,
    },
  };
}

function cachedWorkAmoV5BlockProjection(
  context,
  network,
  requiredBlockHeight,
) {
  const blockHash = String(context?.blockHash ?? "").trim().toLowerCase();
  const previousBlockHash = String(context?.previousBlockHash ?? "")
    .trim()
    .toLowerCase();
  return cachedInternalVerifierState(
    `work-amo-v5-block:${network}:h${requiredBlockHeight}:${previousBlockHash}:${blockHash}`,
    () =>
      completeWorkAmoV5BlockProjection(
        context,
        network,
        requiredBlockHeight,
      ),
  );
}

async function workAmoV5BlockVerifierPayload(
  network,
  {
    blockHash,
    blockHeight,
    previousBlockHash,
  } = {},
) {
  const requiredBlockHeight = Number(blockHeight);
  const requiredBlockHash = String(blockHash ?? "").trim().toLowerCase();
  const requiredPreviousBlockHash = String(previousBlockHash ?? "")
    .trim()
    .toLowerCase();
  if (
    network !== "livenet" ||
    !Number.isSafeInteger(requiredBlockHeight) ||
    requiredBlockHeight < WORK_AMO_V5_ACTIVATION_HEIGHT ||
    !/^[0-9a-f]{64}$/u.test(requiredBlockHash) ||
    !/^[0-9a-f]{64}$/u.test(requiredPreviousBlockHash)
  ) {
    const error = new Error(
      "The AMO V5 block verifier requires livenet, an activated height, and exact current/previous block hashes.",
    );
    error.statusCode = 400;
    throw error;
  }
  pruneInternalVerifierStateCache(requiredBlockHeight);
  const context = await canonicalVerifierContextFromCheckpoint(
    network,
    requiredBlockHeight,
    requiredBlockHash,
    requiredPreviousBlockHash,
  );
  const projection = await cachedWorkAmoV5BlockProjection(
    context,
    network,
    requiredBlockHeight,
  );
  if (
    !projection?.transition ||
    projection.transition.complete !== true ||
    projection.transition.blockHash !== requiredBlockHash ||
    projection.transition.previousBlockHash !== requiredPreviousBlockHash
  ) {
    const error = new Error(
      "The AMO V5 block verifier did not produce a complete atomic transition.",
    );
    error.statusCode = 503;
    error.details = {
      code: "WORK_AMO_V5_BLOCK_TRANSITION_UNAVAILABLE",
      requiredBlockHeight,
    };
    throw error;
  }
  return {
    ...projection.transition,
    closingState: projection.closingState,
    source: "canonical-block-scan-db-core-amo-v5-verifier",
    workAmoV5BlockTransition: projection.transition,
  };
}

function workAmoV5ProjectionEventBase(record) {
  const position = record?.position ?? {};
  const exactPositionInteger = (field, minimum) => {
    const value = position[field];
    if (value === undefined || value === null || value === "") {
      return null;
    }
    const parsed = Number(value);
    return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
  };
  const blockHeight = exactPositionInteger("blockHeight", 1);
  const blockIndex = exactPositionInteger("blockTransactionIndex", 0);
  const protocolVout = exactPositionInteger("protocolVout", 0);
  const recordOrdinal = exactPositionInteger("recordOrdinal", 0);
  if (
    blockHeight === null ||
    blockIndex === null ||
    protocolVout === null ||
    recordOrdinal === null
  ) {
    throw new Error(
      "Canonical AMO V5 projection record position is incomplete.",
    );
  }
  return {
    blockHash: position.blockHash,
    blockHeight,
    blockIndex,
    confirmed: true,
    protocol: record?.protocol,
    protocolVout,
    recordOrdinal,
    txid: String(record?.txid ?? "").trim().toLowerCase(),
    valid: record?.outcome?.valid === true,
  };
}

function workAmoV5GenericVerifierStateFromProjection(
  projection,
  scope,
) {
  const transition = projection?.transition ?? {};
  const closing = transition.closingGenericTokenState ?? {};
  const normalizedScope = String(scope ?? "").trim().toLowerCase();
  const tokenMatches = (tokenId) =>
    String(tokenId ?? "").trim().toLowerCase() === normalizedScope;
  const tokens = (Array.isArray(closing.tokens)
    ? closing.tokens
    : []
  )
    .filter((token) => tokenMatches(token?.tokenId))
    .map((token) => ({
      ...token,
      confirmed: true,
      confirmedSupply:
        token.confirmedSupplyAtoms,
      txid: token.tokenId,
    }));
  const holders = (Array.isArray(closing.holders)
    ? closing.holders
    : []
  )
    .filter((holder) => tokenMatches(holder?.tokenId))
    .map((holder) => ({
      ...holder,
      balance: holder.balance,
      confirmedBalance: holder.balance,
    }));
  const listings = (Array.isArray(closing.listings)
    ? closing.listings
    : []
  )
    .filter((listing) => tokenMatches(listing?.tokenId))
    .map((listing) => ({
      ...listing,
      amount: listing.amount,
      confirmed: true,
      tokenId: normalizedScope,
      txid: listing.listingId,
    }));
  const state = {
    closedListings: [],
    confirmedSupply:
      tokens[0]?.confirmedSupplyAtoms ?? "0",
    holders,
    invalidEvents: [],
    listings,
    mints: [],
    sales: [],
    tokens,
    transfers: [],
  };
  const listingById = new Map(
    state.listings.map((listing) => [
      String(listing.listingId).toLowerCase(),
      listing,
    ]),
  );
  const tokenIdByListingId = new Map(
    (Array.isArray(closing.listings) ? closing.listings : []).map(
      (listing) => [
        String(listing?.listingId ?? "").trim().toLowerCase(),
        String(listing?.tokenId ?? "").trim().toLowerCase(),
      ],
    ),
  );
  for (const record of Array.isArray(transition.replayRecords)
    ? transition.replayRecords
    : []) {
    if (record?.protocol !== "pwt1") {
      continue;
    }
    const event = record?.output?.projection ?? {};
    const parsed = event?.parsed ?? {};
    const eventTokenId = String(
      event?.tokenId ??
        event?.definition?.tokenId ??
        event?.listing?.tokenId ??
        event?.closedListing?.tokenId ??
        parsed?.tokenId ??
        parsed?.saleAuthorization?.tokenId ??
        (parsed?.kind === "create"
          ? record.txid
          : tokenIdByListingId.get(
              String(parsed?.listingId ?? "").trim().toLowerCase(),
            )) ??
        "",
    )
      .trim()
      .toLowerCase();
    if (!tokenMatches(eventTokenId)) {
      continue;
    }
    const base = workAmoV5ProjectionEventBase(record);
    if (record?.outcome?.valid !== true) {
      state.invalidEvents.push({
        ...base,
        attemptedKind: parsed.kind ?? event.kind,
        kind: "token-event-invalid",
        reasonCode: record?.outcome?.reasonCode,
        tokenId: normalizedScope,
      });
      continue;
    }
    if (event.kind === "token-create") {
      const definition = {
        ...event.definition,
        ...base,
        confirmedSupply:
          event.definition?.confirmedSupplyAtoms ?? "0",
        tokenId: normalizedScope,
      };
      const index = state.tokens.findIndex(
        (token) => token.tokenId === normalizedScope,
      );
      if (index < 0) {
        state.tokens.push(definition);
      } else {
        state.tokens[index] = {
          ...state.tokens[index],
          ...definition,
        };
      }
    } else if (event.kind === "token-mint") {
      state.mints.push({
        ...base,
        amount: event.amount,
        minterAddress: event.recipientAddress,
        tokenId: normalizedScope,
      });
    } else if (event.kind === "token-transfer") {
      state.transfers.push({
        ...base,
        amount: event.amount,
        recipientAddress: event.recipientAddress,
        senderAddress: event.senderAddress,
        tokenId: normalizedScope,
      });
    } else if (event.kind === "token-listing") {
      const listing = {
        ...event.listing,
        ...base,
        amount: event.listing?.amount,
        tokenId: normalizedScope,
      };
      listingById.set(
        String(listing.listingId ?? "").trim().toLowerCase(),
        listing,
      );
    } else if (event.kind === "token-listing-sealed") {
      const listingId = String(
        event.listing?.listingId ?? parsed.listingId ?? "",
      ).toLowerCase();
      const listing = listingById.get(listingId);
      if (listing) {
        Object.assign(listing, {
          saleAuthorization:
            event.listing?.saleAuthorization ??
            listing.saleAuthorization,
          sealBlockHeight: base.blockHeight,
          sealBlockIndex: base.blockIndex,
          sealConfirmed: true,
          sealProtocolVout: base.protocolVout,
          sealRecordOrdinal: base.recordOrdinal,
          sealTxid: base.txid,
        });
      }
    } else if (event.kind === "token-sale") {
      state.sales.push({
        ...event.listing,
        ...base,
        buyerAddress: event.buyerAddress,
        tokenId: normalizedScope,
      });
    } else if (event.kind === "token-listing-closed") {
      state.closedListings.push({
        ...(event.closedListing ?? event.listing ?? {}),
        ...base,
        closedBlockHeight: base.blockHeight,
        closedBlockIndex: base.blockIndex,
        closedConfirmed: true,
        closedProtocolVout: base.protocolVout,
        closedRecordOrdinal: base.recordOrdinal,
        closedTxid: base.txid,
        tokenId: normalizedScope,
      });
    }
  }
  state.listings = [...listingById.values()];
  return state;
}

function workAmoV5IdVerifierStateFromProjection(projection) {
  const transition = projection?.transition ?? {};
  const closing = transition.closingIdState ?? {};
  const state = {
    activity: [],
    listings: structuredClone(
      Array.isArray(closing.listings) ? closing.listings : [],
    ),
    records: structuredClone(
      Array.isArray(closing.records) ? closing.records : [],
    ),
    sales: [],
  };
  for (const record of Array.isArray(transition.replayRecords)
    ? transition.replayRecords
    : []) {
    if (record?.protocol !== "pwid1") {
      continue;
    }
    const event = record?.output?.projection ?? {};
    const parsed = event?.parsed ?? {};
    const base = workAmoV5ProjectionEventBase(record);
    state.activity.push({
      ...(event.listing ?? event.closedListing ?? {}),
      ...event,
      ...base,
      id:
        parsed.id ??
        event.listing?.id ??
        event.closedListing?.id,
      kind:
        record?.outcome?.valid === true
          ? event.kind
          : "id-event-invalid",
      reason:
        record?.outcome?.valid === true
          ? ""
          : record?.outcome?.reasonCode,
    });
    if (
      record?.outcome?.valid === true &&
      event.kind === "id-buy"
    ) {
      state.sales.push({
        ...(event.listing ?? {}),
        ...base,
        buyerAddress: event.ownerAddress,
        id: event.listing?.id,
        ownerAddress: event.ownerAddress,
        receiveAddress: event.receiveAddress,
      });
    }
  }
  return state;
}

async function completeTokenVerifierState(
  network,
  tokenScope,
  requiredBlockHeight,
  targetTxid = "",
  expectedBlockHash = "",
  expectedPreviousBlockHash = "",
  options = {},
) {
  const requestedScope = String(tokenScope ?? "").trim().toLowerCase() === "all"
    ? ""
    : normalizeTokenScope(tokenScope);
  const replayVerifierBinding =
    canonicalPwtReplayVerifierBindingDescriptor(
      options.replayVerifierBinding,
      network,
    );
  const context = await canonicalVerifierContextFromCheckpoint(
    network,
    requiredBlockHeight,
    expectedBlockHash,
    expectedPreviousBlockHash,
    replayVerifierBinding,
  );
  const scopeResolution = requestedScope
    ? { scope: requestedScope, status: "resolved" }
    : await confirmedTokenVerifierScopeFromContext(
        context,
        network,
        targetTxid,
      );
  if (scopeResolution.status === "unresolved") {
    const error = new Error(
      "The canonical credit verifier could not resolve an unambiguous token scope.",
    );
    error.statusCode = 503;
    error.details = {
      code: "TOKEN_VERIFIER_SCOPE_UNRESOLVED",
      reason: scopeResolution.reason,
      requiredBlockHeight,
      txid: String(targetTxid ?? "").trim().toLowerCase(),
    };
    throw error;
  }
  const scope = scopeResolution.scope ?? "";
  if (!scope) {
    return {
      ...emptyTokenState(),
      ...context,
      scopeResolution,
      source: "canonical-block-scan-db-core-verifier",
    };
  }
  if (requiredBlockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT) {
    const projection = await cachedWorkAmoV5BlockProjection(
      context,
      network,
      requiredBlockHeight,
    );
    const state =
      scope === WORK_TOKEN_ID
        ? projection.workState
        : workAmoV5GenericVerifierStateFromProjection(
            projection,
            scope,
          );
    return {
      ...state,
      ...context,
      scopeResolution,
      source: "canonical-block-scan-db-core-amo-v5-verifier",
      workAmoV5BlockTransition: projection.transition,
    };
  }
  let preRangeMintWitnesses = [];
  let boundWitnessDispositions = [];
  if (scope === INCB_TOKEN_ID && replayVerifierBinding) {
    const priorHeight = requiredBlockHeight - 1;
    const witnessPayload =
      await proofIndexCanonicalInceptionMintWitnessesPayload(
        network,
        priorHeight,
      );
    const witnessReplayState = canonicalInternalPwtRangeReplayState(
      witnessPayload?.rebuild,
      network,
    );
    const witnessBinding = canonicalInternalReplayVerifierBinding(
      witnessPayload?.rebuild,
      network,
    );
    const witnessEnvelope = canonicalBoundInceptionWitnessEnvelope(
      witnessPayload,
      replayVerifierBinding,
      network,
      priorHeight,
      context.previousBlockHash,
    );
    if (
      !["active", "complete"].includes(witnessReplayState) ||
      !canonicalPwtReplayVerifierBindingsEqual(
        witnessBinding,
        replayVerifierBinding,
      ) ||
      !witnessEnvelope
    ) {
      const error = new Error(
        "The canonical range replay cannot prove its immutable bound Inception witnesses.",
      );
      error.statusCode = 503;
      error.details = {
        code: "INCEPTION_BOUND_WITNESS_UNAVAILABLE",
        priorHeight,
        requiredBlockHeight,
        txid: String(targetTxid ?? "").trim().toLowerCase(),
      };
      throw error;
    }
    preRangeMintWitnesses = witnessEnvelope.mints;
    boundWitnessDispositions = witnessEnvelope.dispositions;
  }
  const indexAddress = tokenIndexAddressForNetwork(network);
  if (scope === WORK_TOKEN_ID) {
    if (requiredBlockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT) {
      const projection = await cachedWorkAmoV5BlockProjection(
        context,
        network,
        requiredBlockHeight,
      );
      return {
        ...projection.workState,
        ...context,
        scopeResolution,
        source: "canonical-block-scan-db-core-amo-v5-verifier",
      };
    }
    const workToken = canonicalWorkTokenDefinition(network);
    const workMarketV2OraclesByTxid =
      await canonicalWorkMarketV2OraclesForTransactions(
        context.transactions,
        network,
        {
          currentBlockHeight: requiredBlockHeight,
          currentPreviousBlockHash: context.previousBlockHash,
        },
      );
    return {
      ...tokenStateFromTransactions(
        [],
        new Map([[WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS, context.transactions]]),
        indexAddress,
        network,
        WORK_TOKEN_ID,
        [workToken],
        [],
        {
          workMarketV2OraclesByTxid,
        },
      ),
      ...context,
      source: "canonical-block-scan-db-core-verifier",
    };
  }

  const idRegistryAddress = registryAddressForNetwork(network);
  const idState = idRegistryStateFromTransactions(
    context.transactions,
    idRegistryAddress,
    network,
  );
  const { tokens } = tokenDefinitionsFromTransactions(
    context.transactions,
    indexAddress,
    network,
  );
  const bondActivity = mailActivityItemsFromTransactions(
    context.transactions,
    network,
  );
  let verifierBondActivity = bondActivity;
  if (scope === INCB_TOKEN_ID) {
    verifierBondActivity = inceptionVerifierBondActivity(
      bondActivity,
      { invalidEvents: context.priorInvalidEvents },
    );
  }
  const bondSeedTokens = [];
  const bondSeedMints = [];
  for (const config of BOND_TOKEN_CONFIGS) {
    const record = (Array.isArray(idState?.records) ? idState.records : []).find(
      (candidate) =>
        normalizePowId(candidate?.id) === normalizePowId(config.registryId),
    );
    const registryAddress = String(
      record?.receiveAddress ?? record?.ownerAddress ?? "",
    ).trim();
    if (!isValidBitcoinAddress(registryAddress, network)) {
      continue;
    }
    bondSeedTokens.push(
      canonicalBondTokenDefinition(config, network, registryAddress),
    );
    bondSeedMints.push(
      ...bondMintsFromActivity(
        verifierBondActivity,
        registryAddress,
        network,
        config,
      ),
    );
  }
  const canonicalWorkToken = canonicalWorkTokenDefinition(network);
  const allSeedTokens = [canonicalWorkToken, ...bondSeedTokens];
  const allTokens = [...tokens, ...allSeedTokens].filter(
    (token, index, items) =>
      items.findIndex((candidate) => candidate.tokenId === token.tokenId) ===
      index,
  );
  const scopedTokens = allTokens.filter((token) =>
    tokenMatchesScope(token, scope),
  );
  const verifierTokens = scope === INCB_TOKEN_ID ? allTokens : scopedTokens;
  const registryAddresses = [
    ...new Set(
      verifierTokens.map((token) => token.registryAddress).filter(Boolean),
    ),
  ];
  const verifierReplayArguments = [
    context.transactions,
    new Map(
      registryAddresses.map((registryAddress) => [
        registryAddress,
        context.transactions,
      ]),
    ),
    indexAddress,
    network,
    scope === INCB_TOKEN_ID ? "" : scope,
    allSeedTokens,
    bondSeedMints,
  ];
  const inceptionIssuanceOptions =
    scope === INCB_TOKEN_ID
      ? await canonicalInceptionIssuanceOptions(network, verifierBondActivity, {
          boundWitnessDispositions,
          preRangeMintWitnesses,
          previousBlockHashByBlockHash: new Map([
            [
              String(context.blockHash ?? "").trim().toLowerCase(),
              String(context.previousBlockHash ?? "").trim().toLowerCase(),
            ],
          ]),
          replayVerifierBinding,
        })
      : {};
  let state =
    scope === INCB_TOKEN_ID
      ? tokenStateFromTransactionsWithCanonicalInceptionIssuance(
          ...verifierReplayArguments,
          verifierBondActivity,
          {
            activity: [
              ...verifierBondActivity,
              ...(Array.isArray(idState?.activity) ? idState.activity : []),
            ],
            registryState: idState,
          },
          {
            ...inceptionIssuanceOptions,
            allowCurrentBlockInvalidAttachmentDisposition: true,
            currentBlockHash: context.blockHash,
            currentBlockHeight: requiredBlockHeight,
          },
        )
      : tokenStateFromTransactions(...verifierReplayArguments);
  if (scope === INCB_TOKEN_ID) {
    state = scopedTokenPayloadFromState(state, INCB_TOKEN_ID);
    const issuance = inceptionIssuanceMetadataFromMints(state.mints);
    const resolvedInvalidOnlyState =
      inceptionInvalidOnlyVerifierStateResolved(
        state,
        issuance,
        targetTxid,
      context,
      requiredBlockHeight,
    );
    const exactVerifierSupply =
      canonicalIntegerText(state.confirmedSupply, { allowZero: true }) || "0";
    if (
      !issuance.complete ||
      (issuance.confirmedMints === 0 && !resolvedInvalidOnlyState) ||
      issuance.confirmedIssuanceUnits !== exactVerifierSupply
    ) {
      const error = new Error(
        "The canonical Inception issuance verifier could not prove live-value issuance.",
      );
      error.statusCode = 503;
      error.details = {
        code: "INCEPTION_LIVE_ISSUANCE_UNAVAILABLE",
        confirmedIssuanceUnits: issuance.confirmedIssuanceUnits,
        confirmedMints: numericValue(issuance.confirmedMints),
        confirmedSupply: exactVerifierSupply,
        issuanceComplete: issuance.complete === true,
        mintCount: Array.isArray(state.mints) ? state.mints.length : 0,
        requiredBlockHeight,
        txid: String(targetTxid ?? "").trim().toLowerCase(),
      };
      throw error;
    }
  }
  return {
    ...state,
    ...context,
    source: "canonical-block-scan-db-core-verifier",
  };
}

async function completeIdVerifierStateBundle(
  network,
  requiredBlockHeight,
  expectedBlockHash = "",
  expectedPreviousBlockHash = "",
) {
  const registryAddress = registryAddressForNetwork(network);
  if (!registryAddress) {
    throw new Error("ProofOfWork ID registry is not configured.");
  }
  const context = await canonicalVerifierContextFromCheckpoint(
    network,
    requiredBlockHeight,
    expectedBlockHash,
    expectedPreviousBlockHash,
  );
  if (requiredBlockHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT) {
    const projection = await cachedWorkAmoV5BlockProjection(
      context,
      network,
      requiredBlockHeight,
    );
    return {
      blockHash: context.blockHash,
      canonicalCoverage: true,
      coverageHeight: context.coverageHeight,
      previousBlockHash: context.previousBlockHash,
      registryAddress,
      state: workAmoV5IdVerifierStateFromProjection(projection),
      transactions: context.transactions,
      workAmoV5BlockTransition: projection.transition,
    };
  }
  return {
    blockHash: context.blockHash,
    canonicalCoverage: true,
    coverageHeight: context.coverageHeight,
    previousBlockHash: context.previousBlockHash,
    registryAddress,
    state: idRegistryStateFromTransactions(
      context.transactions,
      registryAddress,
      network,
    ),
    transactions: context.transactions,
  };
}

function exactVerifierPositionInteger(item, field, minimum) {
  if (
    !item ||
    typeof item !== "object" ||
    Array.isArray(item) ||
    !Object.prototype.hasOwnProperty.call(item, field)
  ) {
    return null;
  }
  const value = item[field];
  if (value === undefined || value === null || value === "") {
    return null;
  }
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) && parsed >= minimum ? parsed : null;
}

function canonicalVerifierItemPosition(
  item,
  {
    blockHashField = "blockHash",
    blockHeightField = "blockHeight",
    blockIndexField = "blockIndex",
    confirmationField = "confirmed",
    protocolVoutField = "protocolVout",
    recordOrdinalField = "recordOrdinal",
  } = {},
  {
    requireConfirmed = false,
    requiredBlockHeight = 0,
  } = {},
) {
  const confirmed = item?.[confirmationField] === true;
  const selectedBlockHash = String(
    item?.[blockHashField] ?? item?.blockHash ?? "",
  )
    .trim()
    .toLowerCase();
  const blockHash = /^[0-9a-f]{64}$/u.test(selectedBlockHash)
    ? selectedBlockHash
    : "";
  if (!confirmed) {
    return {
      ...(blockHash ? { blockHash } : {}),
      blockHeight: item?.[blockHeightField] ?? item?.blockHeight,
      blockIndex: item?.[blockIndexField] ?? item?.blockIndex,
      confirmed: false,
      protocolVout: item?.[protocolVoutField] ?? item?.protocolVout,
      recordOrdinal: item?.[recordOrdinalField] ?? item?.recordOrdinal,
    };
  }
  const requestedHeight =
    requireConfirmed &&
    Number.isSafeInteger(requiredBlockHeight) &&
    requiredBlockHeight > 0
      ? requiredBlockHeight
      : null;
  const actionHeight = exactVerifierPositionInteger(
    item,
    blockHeightField,
    1,
  );
  const genericHeight = exactVerifierPositionInteger(item, "blockHeight", 1);
  const ruleHeight = requestedHeight ?? actionHeight ?? genericHeight;
  if (!Number.isSafeInteger(ruleHeight) || ruleHeight < 1) {
    throw new Error(
      "Confirmed verifier item block height is incomplete.",
    );
  }
  const requiresExactV5Position =
    ruleHeight >= WORK_AMO_V5_ACTIVATION_HEIGHT;
  const positionInteger = (field, fallbackField, minimum) => {
    const exact = exactVerifierPositionInteger(item, field, minimum);
    if (exact !== null) {
      return exact;
    }
    return requiresExactV5Position
      ? null
      : exactVerifierPositionInteger(item, fallbackField, minimum);
  };
  const blockHeight = positionInteger(
    blockHeightField,
    "blockHeight",
    1,
  );
  const blockIndex = positionInteger(
    blockIndexField,
    "blockIndex",
    0,
  );
  const protocolVout = positionInteger(
    protocolVoutField,
    "protocolVout",
    0,
  );
  const explicitRecordOrdinal = positionInteger(
    recordOrdinalField,
    "recordOrdinal",
    0,
  );
  const recordOrdinal =
    explicitRecordOrdinal ??
    (requiresExactV5Position ? null : 0);
  if (
    blockHeight === null ||
    blockIndex === null ||
    protocolVout === null ||
    recordOrdinal === null ||
    (requestedHeight !== null && blockHeight !== requestedHeight)
  ) {
    throw new Error(
      requiresExactV5Position
        ? "Canonical AMO V5 verifier item position is incomplete."
        : "Confirmed verifier item position is incomplete.",
    );
  }
  return {
    ...(blockHash ? { blockHash } : {}),
    blockHeight,
    blockIndex,
    confirmed: true,
    protocolVout,
    recordOrdinal,
  };
}

function tokenVerifierItemsFromState(state, txid, options = {}) {
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  const items = [];
  const add = (
    item,
    kind,
    valid = true,
    confirmationField = "confirmed",
    blockHeightField = "blockHeight",
    blockIndexField = "blockIndex",
    protocolVoutField = "protocolVout",
    recordOrdinalField = "recordOrdinal",
    blockHashField = "blockHash",
  ) => {
    if (!item || typeof item !== "object") {
      return;
    }
    const position = canonicalVerifierItemPosition(
      item,
      {
        blockHashField,
        blockHeightField,
        blockIndexField,
        confirmationField,
        protocolVoutField,
        recordOrdinalField,
      },
      options,
    );
    const canonicalBondMintWithoutProtocol =
      kind === "token-mint" &&
      !String(item?.protocol ?? "").trim() &&
      /^canonical-(?:powb|incb)-bond-projection$/u.test(
        String(item?.validationMode ?? "").trim(),
      ) &&
      String(item?.sourceBondTxid ?? "").trim().toLowerCase() ===
        normalizedTxid;
    items.push({
      ...item,
      ...(canonicalBondMintWithoutProtocol ? { protocol: "pwt1" } : {}),
      ...position,
      kind,
      txid: normalizedTxid,
      valid,
    });
  };
  for (const token of Array.isArray(state?.tokens) ? state.tokens : []) {
    if (
      [token?.txid, token?.tokenId].some(
        (value) => String(value ?? "").toLowerCase() === normalizedTxid,
      )
    ) {
      add(token, "token-create");
    }
  }
  for (const mint of Array.isArray(state?.mints) ? state.mints : []) {
    if (String(mint?.txid ?? "").toLowerCase() === normalizedTxid) {
      add(mint, "token-mint");
    }
  }
  for (const transfer of Array.isArray(state?.transfers) ? state.transfers : []) {
    if (String(transfer?.txid ?? "").toLowerCase() === normalizedTxid) {
      add(transfer, "token-transfer");
    }
  }
  for (const listing of Array.isArray(state?.listings) ? state.listings : []) {
    if (String(listing?.listingId ?? "").toLowerCase() === normalizedTxid) {
      add(listing, "token-listing");
    }
    if (String(listing?.sealTxid ?? "").toLowerCase() === normalizedTxid) {
      add(
        listing,
        "token-listing-sealed",
        true,
        "sealConfirmed",
        "sealBlockHeight",
        "sealBlockIndex",
        "sealProtocolVout",
        "sealRecordOrdinal",
        "sealBlockHash",
      );
    }
  }
  for (const listing of Array.isArray(state?.closedListings)
    ? state.closedListings
    : []) {
    if (String(listing?.listingId ?? "").toLowerCase() === normalizedTxid) {
      add(listing, "token-listing");
    }
    if (String(listing?.sealTxid ?? "").toLowerCase() === normalizedTxid) {
      add(
        listing,
        "token-listing-sealed",
        true,
        "sealConfirmed",
        "sealBlockHeight",
        "sealBlockIndex",
        "sealProtocolVout",
        "sealRecordOrdinal",
        "sealBlockHash",
      );
    }
    if (String(listing?.closedTxid ?? "").toLowerCase() === normalizedTxid) {
      add(
        listing,
        "token-listing-closed",
        true,
        "closedConfirmed",
        "closedBlockHeight",
        "closedBlockIndex",
        "closedProtocolVout",
        "closedRecordOrdinal",
        "closedBlockHash",
      );
    }
  }
  for (const sale of Array.isArray(state?.sales) ? state.sales : []) {
    if (String(sale?.txid ?? "").toLowerCase() === normalizedTxid) {
      add(sale, "token-sale");
    }
  }
  if (state?.canonicalCoverage === true) {
    for (const invalidEvent of Array.isArray(state?.invalidEvents)
      ? state.invalidEvents
      : []) {
      if (String(invalidEvent?.txid ?? "").toLowerCase() === normalizedTxid) {
        const attemptedKind = String(
          invalidEvent?.attemptedKind ?? invalidEvent?.kind ?? "",
        )
          .trim()
          .toLowerCase();
        add(
          {
            ...invalidEvent,
            ...(attemptedKind ? { attemptedKind } : {}),
          },
          "token-event-invalid",
          false,
        );
      }
    }
  }
  return items;
}

function verifierBalanceSnapshot(state, tokenId) {
  const normalizedTokenId = String(tokenId ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(normalizedTokenId)) {
    return null;
  }
  const workTokenDefinition = (Array.isArray(state?.tokens)
    ? state.tokens
    : []
  ).find((token) => isWorkTokenId(token?.tokenId));
  const workAmountStorageModel =
    isWorkTokenId(normalizedTokenId) &&
    (
      state?.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL ||
      state?.precisionModel === WORK_PRECISION_V2_MODEL ||
      workRecordUsesSubatoms(workTokenDefinition)
    )
      ? WORK_SUBATOM_PROJECTION_MODEL
      : WORK_ATOMIC_PROJECTION_MODEL;
  const holders = (Array.isArray(state?.holders) ? state.holders : []).flatMap(
    (holder) => {
      const address = String(holder?.address ?? "").trim();
      if (!isValidBitcoinAddress(address, "livenet")) {
        return [];
      }
      if (isWorkTokenId(normalizedTokenId)) {
        const balance = tokenLedgerAmountFromRecord(
          WORK_TOKEN_ID,
          {
            amount: holder?.balance ?? holder?.confirmedBalance,
            amountAtoms:
              holder?.balanceAtoms ?? holder?.confirmedBalanceAtoms,
            amountStorageModel: holder?.amountStorageModel,
            amountSubatoms:
              holder?.balanceSubatoms ??
              holder?.confirmedBalanceSubatoms,
            precisionModel: holder?.precisionModel,
          },
          { workAmountStorageModel },
        );
        return balance === null || balance < 1n
          ? []
          : [{
              address,
              ...tokenLedgerBalanceFields(
                WORK_TOKEN_ID,
                balance,
                { workAmountStorageModel },
              ),
            }];
      }
      if (isBondTokenId(normalizedTokenId)) {
        const balance = bondUnitsBigInt(
          holder?.balance ?? holder?.confirmedBalance ?? 0,
        );
        return balance === null || balance < 1n
          ? []
          : [{
              address,
              ...tokenLedgerBalanceFields(normalizedTokenId, balance),
            }];
      }
      const balance = Number(holder?.balance ?? holder?.confirmedBalance ?? 0);
      return Number.isSafeInteger(balance) && balance > 0
        ? [{ address, balance }]
        : [];
    },
  );
  return {
    holders,
    indexedThroughBlock: state?.indexedThroughBlock ?? null,
    tokenId: normalizedTokenId,
  };
}

function tokenListingForVerifier(state, listingId) {
  const normalizedListingId = String(listingId ?? "").trim().toLowerCase();
  return [
    ...(Array.isArray(state?.listings) ? state.listings : []),
    ...(Array.isArray(state?.closedListings) ? state.closedListings : []),
  ].find(
    (listing) =>
      String(listing?.listingId ?? "").toLowerCase() === normalizedListingId,
  );
}

async function pendingCoreWorkMarketplaceVerifierContext(
  network,
  txid,
) {
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  if (network !== "livenet" || !/^[0-9a-f]{64}$/u.test(normalizedTxid)) {
    return null;
  }

  const [targetTransaction, initialMempoolResponse] = await Promise.all([
    fetchTransactionFromBitcoinRpc(normalizedTxid, network, {
      requireCanonicalPrevouts: true,
    }),
    bitcoinRpc("getmempoolentry", [normalizedTxid]),
  ]);
  if (
    targetTransaction?._powCanonicalRpcHydration !== true ||
    transactionTxid(targetTransaction) !== normalizedTxid ||
    transactionConfirmed(targetTransaction) ||
    !transactionHasCompleteCanonicalPrevouts(targetTransaction) ||
    !coreMempoolEntryPresent(initialMempoolResponse)
  ) {
    return null;
  }

  const targetMessages = decodedProtocolMessages(
    targetTransaction.vout ?? [],
    TOKEN_PROTOCOL_PREFIX,
  );
  const parsedMessages = targetMessages.map((message) =>
    parseTokenPayload(message, network),
  );
  const marketplaceKinds = new Set(["buy", "delist", "list", "seal"]);
  if (
    parsedMessages.length === 0 ||
    parsedMessages.some(
      (parsed) => !parsed || !marketplaceKinds.has(parsed.kind),
    )
  ) {
    return null;
  }

  const tokenIds = new Set();
  const listingIds = new Set();
  const addTokenId = (value) => {
    const tokenId = String(value ?? "").trim().toLowerCase();
    if (/^[0-9a-f]{64}$/u.test(tokenId)) {
      tokenIds.add(tokenId);
    }
  };
  for (const parsed of parsedMessages) {
    if (parsed.kind === "list" || parsed.kind === "seal") {
      addTokenId(parsed.saleAuthorization?.tokenId);
    }
    if (["buy", "delist", "seal"].includes(parsed.kind)) {
      const listingId = String(parsed.listingId ?? "").trim().toLowerCase();
      if (!/^[0-9a-f]{64}$/u.test(listingId)) {
        return null;
      }
      listingIds.add(listingId);
    }
  }

  const supportingTransactions = [];
  for (const listingId of listingIds) {
    const listingTransaction = await fetchTransactionFromBitcoinRpc(
      listingId,
      network,
      { requireCanonicalPrevouts: true },
    );
    if (
      listingTransaction?._powCanonicalRpcHydration !== true ||
      transactionTxid(listingTransaction) !== listingId ||
      !transactionConfirmed(listingTransaction) ||
      !transactionHasCompleteCanonicalPrevouts(listingTransaction)
    ) {
      return null;
    }
    const listingTokenIds = new Set(
      decodedProtocolMessages(
        listingTransaction.vout ?? [],
        TOKEN_PROTOCOL_PREFIX,
      ).flatMap((message) => {
        const parsed = parseTokenPayload(message, network);
        const tokenId = String(parsed?.saleAuthorization?.tokenId ?? "")
          .trim()
          .toLowerCase();
        return parsed?.kind === "list" && /^[0-9a-f]{64}$/u.test(tokenId)
          ? [tokenId]
          : [];
      }),
    );
    if (listingTokenIds.size !== 1) {
      return null;
    }
    addTokenId([...listingTokenIds][0]);
    supportingTransactions.push(listingTransaction);
  }

  if (tokenIds.size !== 1 || !tokenIds.has(WORK_TOKEN_ID)) {
    return null;
  }
  const finalMempoolResponse = await bitcoinRpc("getmempoolentry", [
    normalizedTxid,
  ]);
  if (!coreMempoolEntryPresent(finalMempoolResponse)) {
    return null;
  }

  cachePendingTokenTransaction(
    targetTransaction,
    network,
    "core-pending-token-verifier",
  );
  return {
    scope: WORK_TOKEN_ID,
    supportingTransactions: dedupeTransactions(supportingTransactions),
    targetTransaction,
  };
}

function pendingWorkMintFromHydratedTransaction(tx, network, txid) {
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  const vin = Array.isArray(tx?.vin) ? tx.vin : [];
  const actorAddress = inputAddresses(vin)[0] ?? "";
  if (
    network !== "livenet" ||
    tx?._powCanonicalRpcHydration !== true ||
    transactionTxid(tx) !== normalizedTxid ||
    transactionConfirmed(tx) ||
    vin.length === 0 ||
    !transactionHasCompleteCanonicalPrevouts(tx) ||
    !isValidBitcoinAddress(actorAddress, network)
  ) {
    return null;
  }
  const vout = Array.isArray(tx.vout) ? tx.vout : [];
  const messages = decodedProtocolMessages(vout, TOKEN_PROTOCOL_PREFIX);
  if (messages.length !== 1) {
    return null;
  }
  const parsed = parseTokenPayload(messages[0], network);
  if (
    parsed?.kind !== "mint" ||
    parsed.tokenId !== WORK_TOKEN_ID ||
    parsed.amount !== WORK_TOKEN_MINT_AMOUNT ||
    tokenPaymentAmountBeforeProtocol(
        vout,
        WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
      ) !== WORK_TOKEN_MINT_PRICE_SATS
  ) {
    return null;
  }
  return { ...parsed, actorAddress };
}

function coreMempoolEntryPresent(response) {
  return (
    response?.ok === true &&
    response.result &&
    typeof response.result === "object" &&
    !Array.isArray(response.result)
  );
}

function exactCoreTipFromBlockchainInfo(response) {
  const info = response?.ok === true ? response.result : null;
  const height = Number(info?.blocks);
  const headers = Number(info?.headers);
  const verificationProgress = Number(info?.verificationprogress);
  const blockHash = String(info?.bestblockhash ?? "").trim().toLowerCase();
  if (
    info?.chain !== "main" ||
    info?.initialblockdownload !== false ||
    !Number.isSafeInteger(height) ||
    height <= 0 ||
    !Number.isSafeInteger(headers) ||
    headers !== height ||
    !Number.isFinite(verificationProgress) ||
    verificationProgress < 0.999 ||
    !/^[0-9a-f]{64}$/u.test(blockHash)
  ) {
    return null;
  }
  return { blockHash, height };
}

function exactCoreNodeAuthority(chainResponse, indexResponse) {
  const tip = exactCoreTipFromBlockchainInfo(chainResponse);
  const chain = chainResponse?.ok === true ? chainResponse.result : null;
  const txindex =
    indexResponse?.ok === true ? indexResponse.result?.txindex : null;
  const txindexHeight = Number(txindex?.best_block_height);
  if (
    !tip ||
    chain?.pruned !== false ||
    !txindex ||
    txindex.synced !== true ||
    !Number.isSafeInteger(txindexHeight) ||
    txindexHeight !== tip.height
  ) {
    return null;
  }
  return {
    ...tip,
    txindexHeight,
    verificationProgress: Number(chain.verificationprogress),
  };
}

function proofIndexExactlyCoversCoreTip(status, canonical, tip) {
  const scanHash = String(status?.scan?.blockHash ?? "").trim().toLowerCase();
  const fault = canonical?.fault;
  const rebuild = canonical?.rebuild;
  const rebuildTrustState = canonicalRebuildTrustState(rebuild, "livenet");
  return (
    status?.network === "livenet" &&
    status?.source === "proof-indexer-block-scan" &&
    status?.scan?.complete === true &&
    Number(status?.indexedThroughBlock) === tip?.height &&
    Number(status?.scan?.tipHeight) === tip?.height &&
    scanHash === tip?.blockHash &&
    (fault == null || fault?.active === false) &&
    rebuildTrustState === "complete"
  );
}

function pendingWorkVerifierStageError(code, message, details = {}) {
  const error = new Error(message);
  error.statusCode = 503;
  error.details = {
    code,
    ...details,
  };
  return error;
}

function pendingWorkVerifierStageExactObjectKeys(value, expectedKeys) {
  return Boolean(
    value &&
      typeof value === "object" &&
      !Array.isArray(value) &&
      Object.getPrototypeOf(value) === Object.prototype &&
      isDeepStrictEqual(
        Object.keys(value).sort(compareCanonicalUtf8),
        [...expectedKeys].sort(compareCanonicalUtf8),
      ),
  );
}

function pendingWorkVerifierStageTxidArray(value, label) {
  if (
    !Array.isArray(value) ||
    value.length > PENDING_WORK_VERIFIER_STAGE_MAX_TXIDS ||
    value.some(
      (txid, index) =>
        typeof txid !== "string" ||
        !/^[0-9a-f]{64}$/u.test(txid) ||
        (index > 0 &&
          compareCanonicalUtf8(value[index - 1], txid) >= 0),
    )
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_REQUEST_INVALID",
      `${label} must be a sorted unique array of at most ${PENDING_WORK_VERIFIER_STAGE_MAX_TXIDS} lowercase transaction ids.`,
      { field: label },
    );
  }
  return [...value];
}

function pendingWorkVerifierStageCanonicalIso(value) {
  if (typeof value !== "string") {
    return null;
  }
  const timeMs = Date.parse(value);
  return Number.isFinite(timeMs) && new Date(timeMs).toISOString() === value
    ? { timeMs, value }
    : null;
}

function pendingWorkVerifierStageAbsenceEvidence(value) {
  if (
    !pendingWorkVerifierStageExactObjectKeys(value, [
      "model",
      "observations",
    ]) ||
    value.model !== PENDING_WORK_ABSENCE_EVIDENCE_MODEL ||
    !Array.isArray(value.observations) ||
    value.observations.length > PENDING_WORK_VERIFIER_STAGE_MAX_TXIDS
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_ABSENCE_EVIDENCE_INVALID",
      "Pending WORK absence evidence has an invalid envelope.",
    );
  }
  const observations = value.observations.map((observation, index) => {
    const firstAbsentAt = pendingWorkVerifierStageCanonicalIso(
      observation?.firstAbsentAt,
    );
    const lastAbsentAt = pendingWorkVerifierStageCanonicalIso(
      observation?.lastAbsentAt,
    );
    if (
      !pendingWorkVerifierStageExactObjectKeys(observation, [
        "absenceCount",
        "absenceProven",
        "contract",
        "firstAbsentAt",
        "lastAbsentAt",
        "reason",
        "sources",
        "txid",
      ]) ||
      !/^[0-9a-f]{64}$/u.test(String(observation.txid ?? "")) ||
      (index > 0 &&
        compareCanonicalUtf8(
          value.observations[index - 1]?.txid,
          observation.txid,
        ) >= 0) ||
      observation.absenceProven !== true ||
      !Number.isSafeInteger(observation.absenceCount) ||
      observation.absenceCount < 1 ||
      !firstAbsentAt ||
      !lastAbsentAt ||
      lastAbsentAt.timeMs < firstAbsentAt.timeMs ||
      observation.contract !== PENDING_WORK_ABSENCE_CONTRACT ||
      observation.reason !== PENDING_WORK_ABSENCE_REASON ||
      !isDeepStrictEqual(
        observation.sources,
        PENDING_WORK_ABSENCE_SOURCES,
      )
    ) {
      throw pendingWorkVerifierStageError(
        "PENDING_WORK_STAGE_ABSENCE_EVIDENCE_INVALID",
        "Pending WORK absence evidence contains a malformed observation.",
        { observationIndex: index },
      );
    }
    return {
      absenceCount: observation.absenceCount,
      absenceProven: true,
      contract: PENDING_WORK_ABSENCE_CONTRACT,
      firstAbsentAt: firstAbsentAt.value,
      lastAbsentAt: lastAbsentAt.value,
      reason: PENDING_WORK_ABSENCE_REASON,
      sources: [...PENDING_WORK_ABSENCE_SOURCES],
      txid: observation.txid,
    };
  });
  return {
    model: PENDING_WORK_ABSENCE_EVIDENCE_MODEL,
    observations,
  };
}

function pendingWorkVerifierStageRequest(value) {
  if (
    !pendingWorkVerifierStageExactObjectKeys(value, [
      "absenceEvidence",
      "confirmedRemovalTxids",
      "model",
      "network",
      "parentWitnessSha256",
      "priorMembershipTxids",
      "removalTxids",
      "replayTxids",
    ]) ||
    value.model !== PENDING_WORK_VERIFIER_STAGE_REQUEST_MODEL ||
    value.network !== "livenet" ||
    !/^[0-9a-f]{64}$/u.test(String(value.parentWitnessSha256 ?? ""))
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_REQUEST_INVALID",
      "Pending WORK verifier stage request is malformed.",
    );
  }
  const priorMembershipTxids = pendingWorkVerifierStageTxidArray(
    value.priorMembershipTxids,
    "priorMembershipTxids",
  );
  const replayTxids = pendingWorkVerifierStageTxidArray(
    value.replayTxids,
    "replayTxids",
  );
  const confirmedRemovalTxids = pendingWorkVerifierStageTxidArray(
    value.confirmedRemovalTxids,
    "confirmedRemovalTxids",
  );
  const removalTxids = pendingWorkVerifierStageTxidArray(
    value.removalTxids,
    "removalTxids",
  );
  const priorMembership = new Set(priorMembershipTxids);
  const replay = new Set(replayTxids);
  const confirmedRemovals = new Set(confirmedRemovalTxids);
  if (
    confirmedRemovalTxids.some(
      (txid) => !priorMembership.has(txid) || replay.has(txid),
    ) ||
    removalTxids.some(
      (txid) =>
        !priorMembership.has(txid) ||
        replay.has(txid) ||
        confirmedRemovals.has(txid),
    )
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_REQUEST_INVALID",
      "Pending WORK confirmed and dropped removals must be disjoint prior members and cannot also be replayed.",
    );
  }
  const absenceEvidence = pendingWorkVerifierStageAbsenceEvidence(
    value.absenceEvidence,
  );
  const observedTxids = new Set();
  for (const observation of absenceEvidence.observations) {
    if (
      observedTxids.has(observation.txid) ||
      !priorMembership.has(observation.txid) ||
      replay.has(observation.txid) ||
      confirmedRemovals.has(observation.txid)
    ) {
      throw pendingWorkVerifierStageError(
        "PENDING_WORK_STAGE_ABSENCE_EVIDENCE_INVALID",
        "Pending WORK absence observations must be unique absent prior members disjoint from confirmed removals.",
        { txid: observation.txid },
      );
    }
    observedTxids.add(observation.txid);
  }
  const eligibleRemovalTxids = absenceEvidence.observations
    .filter((observation) => {
      const firstAbsentMs = Date.parse(observation.firstAbsentAt);
      const lastAbsentMs = Date.parse(observation.lastAbsentAt);
      return (
        observation.absenceCount >= 2 &&
        lastAbsentMs >= firstAbsentMs + PENDING_WORK_DROP_CONFIRMATION_MS
      );
    })
    .map((observation) => observation.txid);
  if (!isDeepStrictEqual(removalTxids, eligibleRemovalTxids)) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_REMOVAL_EVIDENCE_INSUFFICIENT",
      "Pending WORK removals must equal the exact eligible repeated-absence subset.",
      { eligibleRemovalTxids },
    );
  }
  const priorDepartureTxids = priorMembershipTxids.filter(
    (txid) => !replay.has(txid),
  );
  const declaredDepartureTxids = [
    ...confirmedRemovalTxids,
    ...observedTxids,
  ].sort(compareCanonicalUtf8);
  if (!isDeepStrictEqual(priorDepartureTxids, declaredDepartureTxids)) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_DEPARTURE_PARTITION_INVALID",
      "Every unreplayed prior WORK member must be declared exactly once as confirmed or authoritatively absent.",
      { declaredDepartureTxids, priorDepartureTxids },
    );
  }
  return {
    absenceEvidence,
    confirmedRemovalTxids,
    model: value.model,
    network: value.network,
    parentWitnessSha256: value.parentWitnessSha256,
    priorMembershipTxids,
    removalTxids,
    replayTxids,
  };
}

function pendingWorkVerifierStageCoreMempool(response) {
  if (response?.ok !== true || !Array.isArray(response.result)) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_CORE_MEMPOOL_UNAVAILABLE",
      "Bitcoin Core did not return an exact mempool membership snapshot.",
    );
  }
  const txids = response.result.map((txid) => String(txid ?? ""));
  if (
    txids.some((txid) => !/^[0-9a-f]{64}$/u.test(txid)) ||
    new Set(txids).size !== txids.length
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_CORE_MEMPOOL_INVALID",
      "Bitcoin Core returned a malformed mempool membership snapshot.",
    );
  }
  txids.sort(compareCanonicalUtf8);
  return { membership: new Set(txids), txids };
}

function pendingWorkVerifierStageValidateMembership(
  request,
  mempool,
) {
  const missingReplayTxids = request.replayTxids.filter(
    (txid) => !mempool.membership.has(txid),
  );
  const presentRemovalTxids = request.removalTxids.filter((txid) =>
    mempool.membership.has(txid),
  );
  const replay = new Set(request.replayTxids);
  const confirmedRemovals = new Set(request.confirmedRemovalTxids);
  const presentConfirmedRemovalTxids = request.confirmedRemovalTxids.filter(
    (txid) => mempool.membership.has(txid),
  );
  const unreplayedPresentPriorTxids = request.priorMembershipTxids.filter(
    (txid) => mempool.membership.has(txid) && !replay.has(txid),
  );
  const absentPriorTxids = request.priorMembershipTxids.filter(
    (txid) =>
      !mempool.membership.has(txid) && !confirmedRemovals.has(txid),
  );
  const observedTxids = request.absenceEvidence.observations.map(
    (observation) => observation.txid,
  );
  if (
    missingReplayTxids.length > 0 ||
    presentRemovalTxids.length > 0 ||
    presentConfirmedRemovalTxids.length > 0 ||
    unreplayedPresentPriorTxids.length > 0 ||
    !isDeepStrictEqual(absentPriorTxids, observedTxids)
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_MEMBERSHIP_CHANGED",
      "Pending WORK replay, removal, or absence membership does not match Bitcoin Core.",
      {
        missingReplayTxids,
        presentConfirmedRemovalTxids,
        presentRemovalTxids,
        unreplayedPresentPriorTxids,
      },
    );
  }
}

function pendingWorkVerifierStageJsonClone(value) {
  try {
    return JSON.parse(JSON.stringify(value));
  } catch (error) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_INVALID",
      "Canonical WORK state contains a non-JSON value.",
      { reason: errorSummary(error) },
    );
  }
}

function pendingWorkVerifierStageWithoutPendingFields(value) {
  const source =
    value && typeof value === "object" && !Array.isArray(value) ? value : {};
  return Object.fromEntries(
    Object.entries(source).filter(
      ([field]) => !field.toLowerCase().startsWith("pending"),
    ),
  );
}

function pendingWorkVerifierStageConfirmedItem(
  value,
  fieldMap = {},
) {
  const confirmationField = fieldMap.confirmationField ?? "confirmed";
  const blockHashField = fieldMap.blockHashField ?? "blockHash";
  const blockHeightField = fieldMap.blockHeightField ?? "blockHeight";
  const blockIndexField = fieldMap.blockIndexField ?? "blockIndex";
  const protocolVoutField = fieldMap.protocolVoutField ?? "protocolVout";
  const recordOrdinalField = fieldMap.recordOrdinalField ?? "recordOrdinal";
  if (value?.[confirmationField] !== true) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_INVALID",
      "Canonical WORK base contains an unconfirmed event.",
    );
  }
  if (!/^[0-9a-f]{64}$/u.test(String(value?.[blockHashField] ?? ""))) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_POSITION_INVALID",
      "Canonical WORK base event is missing its exact action block hash.",
    );
  }
  let position;
  try {
    position = canonicalVerifierItemPosition(
      value,
      fieldMap,
      { requireConfirmed: true },
    );
  } catch (error) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_POSITION_INVALID",
      "Canonical WORK base event position is incomplete.",
      { reason: errorSummary(error) },
    );
  }
  if (!/^[0-9a-f]{64}$/u.test(String(position.blockHash ?? ""))) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_POSITION_INVALID",
      "Canonical WORK base event is not bound to an exact block hash.",
    );
  }
  return pendingWorkVerifierStageJsonClone({
    ...pendingWorkVerifierStageWithoutPendingFields(value),
    [blockHashField]: position.blockHash,
    [blockHeightField]: position.blockHeight,
    [blockIndexField]: position.blockIndex,
    [confirmationField]: true,
    [protocolVoutField]: position.protocolVout,
    [recordOrdinalField]: position.recordOrdinal,
  });
}

function pendingWorkVerifierStageCanonicalOutpointClose(listing) {
  if (
    listing?.closedByCanonicalOutpointSpend !== true ||
    listing?.closedConfirmed !== true
  ) {
    return null;
  }
  const closedTxid = String(listing.closedTxid ?? "").trim().toLowerCase();
  const closedBlockHash = String(listing.closedBlockHash ?? "")
    .trim()
    .toLowerCase();
  const closedBlockHeight = exactVerifierPositionInteger(
    listing,
    "closedBlockHeight",
    1,
  );
  const closedBlockIndex = exactVerifierPositionInteger(
    listing,
    "closedBlockIndex",
    0,
  );
  if (
    !/^[0-9a-f]{64}$/u.test(closedTxid) ||
    !/^[0-9a-f]{64}$/u.test(closedBlockHash) ||
    closedBlockHeight === null ||
    closedBlockIndex === null
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_POSITION_INVALID",
      "Canonical WORK outpoint-spend close position is incomplete.",
      { listingId: String(listing?.listingId ?? "").trim().toLowerCase() || null },
    );
  }
  return pendingWorkVerifierStageJsonClone({
    ...pendingWorkVerifierStageWithoutPendingFields(listing),
    closeTransactionBlockHeight: closedBlockHeight,
    closedBlockHash,
    closedBlockHeight,
    closedBlockIndex,
    closedByCanonicalOutpointSpend: true,
    closedConfirmed: true,
    closedProtocolVout: undefined,
    closedRecordOrdinal: undefined,
    closedTxid,
    saleConfirmed: false,
    saleProtocolVout: undefined,
    saleRecordOrdinal: undefined,
    saleTxid: undefined,
  });
}

function pendingWorkVerifierStageSortUniqueItems(items, keyForItem) {
  const seen = new Set();
  for (const item of items) {
    const key = keyForItem(item);
    if (!key || seen.has(key)) {
      throw pendingWorkVerifierStageError(
        "PENDING_WORK_STAGE_BASE_INVALID",
        "Canonical WORK base contains a duplicate or unkeyed event.",
        { key: key || null },
      );
    }
    seen.add(key);
  }
  return items.sort(
    (left, right) =>
      Number(left.blockHeight ?? 0) - Number(right.blockHeight ?? 0) ||
      Number(left.blockIndex ?? 0) - Number(right.blockIndex ?? 0) ||
      Number(left.protocolVout ?? 0) - Number(right.protocolVout ?? 0) ||
      Number(left.recordOrdinal ?? 0) - Number(right.recordOrdinal ?? 0) ||
      compareCanonicalUtf8(keyForItem(left), keyForItem(right)),
  );
}

// Confirmed public audit history intentionally retains generic and specific
// invalid projections for some pre-V5 listing/seal records. Pending replay is
// one decision per raw record, so exact-position legacy generic siblings yield
// only when there is one matching specific listing audit row.
function pendingWorkVerifierStageCollapseExactLegacyInvalidSibling(items) {
  const groups = new Map();
  for (const [index, item] of items.entries()) {
    const txid = String(item?.txid ?? "");
    const protocolVout = Number(item?.protocolVout);
    const recordOrdinal = Number(item?.recordOrdinal);
    const key = /^[0-9a-f]{64}$/u.test(txid) &&
        Number.isSafeInteger(protocolVout) &&
        protocolVout >= 0 &&
        Number.isSafeInteger(recordOrdinal) &&
        recordOrdinal >= 0
      ? `${txid}:${protocolVout}:${recordOrdinal}`
      : `unkeyed:${index}`;
    groups.set(key, [...(groups.get(key) ?? []), item]);
  }
  const collapsed = [];
  for (const group of groups.values()) {
    if (group.length < 2) {
      collapsed.push(...group);
      continue;
    }
    const [first] = group;
    const identityFields = [
      "blockHash",
      "blockHeight",
      "blockIndex",
      "confirmed",
      "network",
      "protocol",
      "protocolVout",
      "recordOrdinal",
      "status",
      "tokenId",
      "txid",
      "valid",
    ];
    const aligned = group.every((item) =>
      identityFields.every((field) => item?.[field] === first?.[field])
    );
    const preV5 =
      Number.isSafeInteger(Number(first?.blockHeight)) &&
      Number(first.blockHeight) < WORK_AMO_V5_ACTIVATION_HEIGHT;
    const specificRows = group.filter(
      (item) =>
        ["token-listing-invalid", "token-listing-sealed-invalid"].includes(
          item?.kind,
        ) &&
        /^[0-9a-f]{64}$/u.test(String(item?.listingId ?? "")) &&
        item?.reason ===
          "The canonical first-party verifier rejected this protocol event." &&
        Array.isArray(item?.validationErrors) &&
        item.validationErrors.length === 1 &&
        item.validationErrors[0] ===
          "The canonical first-party verifier rejected this protocol event." &&
        ["pwt-sale-v1", "pwt-sale-v2"].includes(
          String(item?.saleAuthorization?.version ?? ""),
        ),
    );
    const specific = specificRows.length === 1 ? specificRows[0] : null;
    const genericRows = group.filter((item) => item !== specific);
    const genericOk =
      Boolean(specific) &&
      genericRows.length > 0 &&
      genericRows.every(
      (item) =>
        item?.kind === "token-event-invalid" &&
        item?.reason === "no-valid-token-event" &&
        Array.isArray(item?.validationErrors) &&
        item.validationErrors.length === 1 &&
        item.validationErrors[0] === "no-valid-token-event" &&
        (
          item?.listingId === undefined ||
          item?.listingId === null ||
          item?.listingId === "" ||
          item?.listingId === specific.listingId
        ) &&
        (
          item?.saleAuthorization === undefined ||
          item?.saleAuthorization === null ||
          String(item.saleAuthorization?.version ?? "") ===
            String(specific.saleAuthorization?.version ?? "")
        ),
    );
    if (aligned && preV5 && specific && genericOk) {
      collapsed.push(specific);
    } else {
      collapsed.push(...group);
    }
  }
  return collapsed;
}

const PENDING_WORK_STAGE_SEAL_FIELDS = Object.freeze([
  "sealAt",
  "sealBlockHash",
  "sealBlockHeight",
  "sealBlockIndex",
  "sealConfirmed",
  "sealDataBytes",
  "sealFrozenNetworkValueSats",
  "sealLiveNetworkValueSats",
  "sealMinerFeeCanonical",
  "sealMinerFeeSats",
  "sealMinerFeeSource",
  "sealProtocolVout",
  "sealRecordOrdinal",
  "sealTransactionBlockHeight",
  "sealTxid",
]);
const PENDING_WORK_STAGE_CLOSE_FIELDS = Object.freeze([
  "buyerAddress",
  "canonicalSaleEvidence",
  "closeAt",
  "closeTransactionBlockHeight",
  "closeTxid",
  "closedAt",
  "closedBlockHash",
  "closedBlockHeight",
  "closedBlockIndex",
  "closedByCanonicalOutpointSpend",
  "closedBySpendableOutspend",
  "closedConfirmed",
  "closedDataBytes",
  "closedFrozenNetworkValueSats",
  "closedLiveNetworkValueSats",
  "closedMinerFeeCanonical",
  "closedMinerFeeSats",
  "closedMinerFeeSource",
  "closedProtocolVout",
  "closedRecordOrdinal",
  "closedTxid",
  "closedVin",
  "lifecycleStatus",
  "saleAt",
  "saleBlockHash",
  "saleBlockHeight",
  "saleBlockIndex",
  "saleBuyerAddress",
  "saleConfirmed",
  "saleDataBytes",
  "saleMinerFeeSats",
  "salePaymentSats",
  "saleProtocolVout",
  "saleRecordOrdinal",
  "saleTransactionBlockHeight",
  "saleTxid",
]);

function pendingWorkVerifierStageDeleteFields(value, fields) {
  const next = { ...value };
  for (const field of fields) {
    delete next[field];
  }
  return next;
}

function pendingWorkVerifierStageCanonicalCutoverRelic(listing) {
  if (
    listing?.relic !== true ||
    listing?.confirmed !== true ||
    listing?.status !== "disabled"
  ) {
    return false;
  }
  const disabledAtBlockHeight = Number(listing.disabledAtBlockHeight);
  const disabledByTxid = String(listing.disabledByTxid ?? "");
  const disabledReason = String(listing.disabledReason ?? "");
  const exactCutovers = [
    {
      disabledAtBlockHeight: WORK_MARKET_V2_ACTIVATION_HEIGHT,
      disabledByTxid: WORK_MARKET_V2_DECLARATION_TXID,
      disabledReason: "work-market-v2-cutover",
    },
    {
      disabledAtBlockHeight: WORK_MARKET_V4_ACTIVATION_HEIGHT,
      disabledByTxid: WORK_MARKET_V4_DECLARATION_TXID,
      disabledReason: "work-market-v4-cutover",
    },
    {
      disabledAtBlockHeight: WORK_AMO_V5_ACTIVATION_HEIGHT,
      disabledByTxid: WORK_AMO_V5_DECLARATION_TXID,
      disabledReason: WORK_AMO_V5_PRE_UNIT_RELIC_DISABLED_REASON,
    },
    {
      disabledAtBlockHeight: WORK_AMO_V8_ACTIVATION_HEIGHT,
      disabledByTxid: WORK_AMO_V8_DECLARATION_TXID,
      disabledReason: "work-amo-v8-preactivation-relic",
      relicCutoverModel: WORK_AMO_V8_RELIC_CUTOVER_MODEL,
    },
  ];
  return exactCutovers.some(
    (cutover) =>
      disabledAtBlockHeight === cutover.disabledAtBlockHeight &&
      disabledByTxid === cutover.disabledByTxid &&
      disabledReason === cutover.disabledReason &&
      (
        !cutover.relicCutoverModel ||
        listing.relicCutoverModel === cutover.relicCutoverModel
      ),
  );
}

function pendingWorkVerifierStageConfirmedV8Listing(
  listing,
  staticAuthorization,
  listingId,
) {
  if (staticAuthorization.version !== TOKEN_SALE_AUTH_WORK_AMO_V8_VERSION) {
    return listing;
  }
  const staticValidation =
    validateWorkAmoV8StaticAuthorization(staticAuthorization);
  if (!staticValidation.valid) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_INVALID",
      "Canonical WORK listing static authorization is not valid AMO V8 state.",
      { listingId },
    );
  }
  const objectValue = (value) =>
    value && typeof value === "object" && !Array.isArray(value)
      ? value
      : null;
  const frozenCandidates = [
    listing.frozenTerms,
    listing.workAmoV8FrozenTerms,
    listing.workAmoFrozenTerms,
    objectValue(listing.workAmoPricing)?.frozenTerms,
    objectValue(listing.workMarketPricing)?.frozenTerms,
    listing.listingFrozenTerms,
  ];
  const listingPosition = {
    blockHash: listing.blockHash,
    blockHeight: listing.blockHeight,
    blockTransactionIndex: listing.blockIndex,
    protocolVout: listing.protocolVout,
    recordOrdinal: listing.recordOrdinal,
  };
  const frozenValidation = frozenCandidates
    .map((candidate) =>
      validateWorkAmoV8FrozenTerms(candidate, {
        authorization: staticValidation.authorization,
        listingPosition,
      }),
    )
    .find((validation) => validation.valid);
  if (!frozenValidation) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_INVALID",
      "Canonical WORK listing has no valid confirmed AMO V8 frozen terms.",
      { listingId },
    );
  }
  const frozenTerms = frozenValidation.frozenTerms;
  const amountSubatoms = canonicalWorkSubatomsText(
    listing.amountSubatoms,
  );
  const priceSats = canonicalNonNegativeIntegerText(listing.priceSats, {
    allowZero: false,
  });
  if (
    (
      listing.amountSubatoms !== undefined &&
      listing.amountSubatoms !== null &&
      listing.amountSubatoms !== "" &&
      amountSubatoms !== frozenTerms.unitAmountSubatoms
    ) ||
    (
      listing.priceSats !== undefined &&
      listing.priceSats !== null &&
      listing.priceSats !== "" &&
      priceSats !== frozenTerms.unitPriceSats
    )
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_INVALID",
      "Canonical WORK listing amount or price diverges from AMO V8 frozen terms.",
      { listingId },
    );
  }
  return {
    ...listing,
    amountSubatoms: frozenTerms.unitAmountSubatoms,
    frozenTerms,
    listingAuthorization: staticValidation.authorization,
    priceSats: frozenTerms.unitPriceSats,
    saleAuthorization: staticValidation.authorization,
  };
}

function pendingWorkVerifierStageConfirmedListing(value, { closed = false } = {}) {
  let listing = pendingWorkVerifierStageConfirmedItem(value);
  const listingId = String(listing.listingId ?? "").trim().toLowerCase();
  if (
    !/^[0-9a-f]{64}$/u.test(listingId) ||
    listing.tokenId !== WORK_TOKEN_ID ||
    listing.network !== "livenet" ||
    listing.registryAddress !== WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS ||
    !isValidBitcoinAddress(listing.sellerAddress, "livenet")
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_INVALID",
      "Canonical WORK base contains a malformed listing.",
      { listingId: listingId || null },
    );
  }
  listing.listingId = listingId;
  listing.status =
    closed && listing.relic === true ? listing.status : closed ? "closed" : "active";
  if (listing.sealConfirmed === true) {
    if (!/^[0-9a-f]{64}$/u.test(String(listing.sealTxid ?? ""))) {
      throw pendingWorkVerifierStageError(
        "PENDING_WORK_STAGE_BASE_INVALID",
        "Canonical WORK listing has confirmed seal state without an exact seal transaction id.",
        { listingId },
      );
    }
    listing = pendingWorkVerifierStageConfirmedItem(listing, {
      blockHashField: "sealBlockHash",
      blockHeightField: "sealBlockHeight",
      blockIndexField: "sealBlockIndex",
      confirmationField: "sealConfirmed",
      protocolVoutField: "sealProtocolVout",
      recordOrdinalField: "sealRecordOrdinal",
    });
    const sealedAuthorization = tokenSaleAuthorizationDraft(
      listing.saleAuthorization ?? listing.listingAuthorization,
    );
    if (sealedAuthorization.version === TOKEN_SALE_AUTH_WORK_AMO_V8_VERSION) {
      const sealedV8Validation =
        validateWorkAmoV8StaticAuthorization(sealedAuthorization);
      if (!sealedV8Validation.valid) {
        throw pendingWorkVerifierStageError(
          "PENDING_WORK_STAGE_BASE_INVALID",
          "Canonical sealed WORK listing static authorization is not valid AMO V8 state.",
          { listingId },
        );
      }
      listing.listingAuthorization = sealedV8Validation.authorization;
      listing.saleAuthorization = sealedV8Validation.authorization;
      listing = pendingWorkVerifierStageConfirmedV8Listing(
        listing,
        sealedV8Validation.authorization,
        listingId,
      );
    }
  } else {
    let staticAuthorization;
    try {
      staticAuthorization = tokenSaleAuthorizationDraft(
        listing.listingAuthorization ?? listing.saleAuthorization,
      );
    } catch (error) {
      throw pendingWorkVerifierStageError(
        "PENDING_WORK_STAGE_BASE_INVALID",
        "Canonical WORK listing has no valid confirmed static authorization.",
        { listingId, reason: errorSummary(error) },
      );
    }
    const v8StaticValidation =
      validateWorkAmoV8StaticAuthorization(staticAuthorization);
    if (
      (!closed ||
        staticAuthorization.version === TOKEN_SALE_AUTH_WORK_AMO_V8_VERSION) &&
      !v8StaticValidation.valid
    ) {
      throw pendingWorkVerifierStageError(
        "PENDING_WORK_STAGE_BASE_INVALID",
        "Canonical WORK listing static authorization is not valid AMO V8 state.",
        { listingId },
      );
    }
    listing = pendingWorkVerifierStageDeleteFields(
      listing,
      PENDING_WORK_STAGE_SEAL_FIELDS,
    );
    listing.listingAuthorization = staticAuthorization;
    listing.saleAuthorization = staticAuthorization;
    listing = pendingWorkVerifierStageConfirmedV8Listing(
      listing,
      v8StaticValidation.valid
        ? v8StaticValidation.authorization
        : staticAuthorization,
      listingId,
    );
  }
  if (closed) {
    const canonicalCutoverRelic =
      pendingWorkVerifierStageCanonicalCutoverRelic(listing);
    if (canonicalCutoverRelic) {
      listing = {
        ...pendingWorkVerifierStageDeleteFields(
          listing,
          PENDING_WORK_STAGE_CLOSE_FIELDS,
        ),
        closedConfirmed: true,
        closedTxid: "",
      };
    } else {
      const outpointClose =
        pendingWorkVerifierStageCanonicalOutpointClose(listing);
      if (outpointClose) {
        return outpointClose;
      }
      if (!/^[0-9a-f]{64}$/u.test(String(listing.closedTxid ?? ""))) {
        throw pendingWorkVerifierStageError(
          "PENDING_WORK_STAGE_BASE_INVALID",
          "Canonical WORK listing has confirmed close state without an exact close transaction id.",
          { listingId },
        );
      }
      listing = pendingWorkVerifierStageConfirmedItem(listing, {
        blockHashField: "closedBlockHash",
        blockHeightField: "closedBlockHeight",
        blockIndexField: "closedBlockIndex",
        confirmationField: "closedConfirmed",
        protocolVoutField: "closedProtocolVout",
        recordOrdinalField: "closedRecordOrdinal",
      });
    }
  } else {
    listing = pendingWorkVerifierStageDeleteFields(
      listing,
      PENDING_WORK_STAGE_CLOSE_FIELDS,
    );
  }
  return listing;
}

async function pendingWorkVerifierStageConfirmedTransitionCommitment(
  network,
  tip,
) {
  const transition = await proofIndexWorkAmoBlockTransition(
    network,
    tip.height,
    tip.blockHash,
  );
  let tokenStateCommitment = null;
  try {
    tokenStateCommitment = workAmoV8CanonicalTokenStateCommitment(
      transition?.payload?.closingTokenState,
    );
  } catch {
    tokenStateCommitment = null;
  }
  const sufficientCommitment =
    transition?.payload?.closingSufficientState?.tokenStateCommitment;
  if (
    network !== "livenet" ||
    !transition ||
    transition.blockHeight !== tip.height ||
    transition.blockHash !== tip.blockHash ||
    transition.model !== WORK_AMO_V8_BLOCK_SEQUENCER_MODEL ||
    transition.workTokenStateModel !==
      WORK_AMO_V8_TOKEN_STATE_PREIMAGE_MODEL ||
    transition.complete !== true ||
    !tokenStateCommitment ||
    tokenStateCommitment.model !==
      WORK_AMO_V5_PAYLOAD_COMMITMENT_MODEL ||
    tokenStateCommitment.sha256 !==
      String(sufficientCommitment?.sha256 ?? "").trim().toLowerCase() ||
    tokenStateCommitment.payloadBytes !==
      Number(sufficientCommitment?.payloadBytes)
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_UNAVAILABLE",
      "The canonical V8 transition closing token state is unavailable.",
    );
  }
  return tokenStateCommitment;
}

function pendingWorkVerifierStageConfirmedBase(
  payload,
  tip,
  tokenStateCommitment,
) {
  if (
    payload?.source !== "proof-indexer-token-state-tables" ||
    payload?.network !== "livenet" ||
    Number(payload.indexedThroughBlock) !== tip.height ||
    String(payload.indexedThroughBlockHash ?? "") !== tip.blockHash ||
    !workPrecisionV2CurrentPayloadIsExact(
      payload,
      WORK_AMO_V8_ACTIVATION_HEIGHT,
      { requireSupplyEnvelope: true },
    )
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_UNAVAILABLE",
      "The relational token tables do not provide an exact-tip Q16 WORK base.",
    );
  }
  const sourceWorkTokens = (Array.isArray(payload.tokens) ? payload.tokens : [])
    .filter((token) => isWorkTokenId(token?.tokenId));
  if (sourceWorkTokens.length !== 1) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_INVALID",
      "Canonical WORK base must contain exactly one WORK definition.",
    );
  }
  const sourceToken = sourceWorkTokens[0];
  const canonicalDefinition = canonicalWorkTokenDefinition(
    "livenet",
    WORK_SUBATOM_PROJECTION_MODEL,
  );
  for (const field of [
    "amountStorageModel",
    "decimals",
    "maxSupplySubatoms",
    "mintAmountSubatoms",
    "precisionModel",
    "registryAddress",
    "ticker",
    "tokenId",
    "unitScale",
  ]) {
    if (String(sourceToken?.[field] ?? "") !== String(canonicalDefinition[field])) {
      throw pendingWorkVerifierStageError(
        "PENDING_WORK_STAGE_BASE_INVALID",
        "Canonical WORK definition does not match the declared Q16 definition.",
        { field },
      );
    }
  }

  const holders = [];
  const holderAddresses = new Set();
  let confirmedSupplySubatoms = 0n;
  for (const holder of (Array.isArray(payload.holders) ? payload.holders : [])
    .filter((candidate) => isWorkTokenId(candidate?.tokenId))) {
    const address = String(holder.address ?? "").trim();
    const balanceSubatoms = canonicalWorkSubatomsText(
      holder.balanceSubatoms,
    );
    if (
      !isValidBitcoinAddress(address, "livenet") ||
      !balanceSubatoms ||
      BigInt(balanceSubatoms) <= 0n ||
      holderAddresses.has(address) ||
      holder.amountStorageModel !== WORK_SUBATOM_PROJECTION_MODEL ||
      holder.precisionModel !== WORK_PRECISION_V2_MODEL
    ) {
      throw pendingWorkVerifierStageError(
        "PENDING_WORK_STAGE_BASE_INVALID",
        "Canonical WORK base contains a malformed authoritative holder balance.",
        { address: address || null },
      );
    }
    holderAddresses.add(address);
    confirmedSupplySubatoms += BigInt(balanceSubatoms);
    holders.push({
      address,
      ...workBalanceFieldsFromSubatoms(balanceSubatoms),
      pendingDelta: formatWorkSubatoms(0n),
      pendingDeltaSubatoms: "0",
      registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
      ticker: WORK_TOKEN_TICKER,
      tokenId: WORK_TOKEN_ID,
    });
  }
  holders.sort((left, right) =>
    compareCanonicalUtf8(left.address, right.address),
  );
  if (
    holders.length === 0 ||
    confirmedSupplySubatoms <= 0n ||
    confirmedSupplySubatoms > WORK_TOKEN_MAX_SUPPLY_SUBATOMS
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_INVALID",
      "Canonical WORK base has no conserved authoritative holder supply.",
    );
  }

  const confirmedEvent = (item) => {
    const confirmed = pendingWorkVerifierStageConfirmedItem(item);
    if (!/^[0-9a-f]{64}$/u.test(String(confirmed.txid ?? ""))) {
      throw pendingWorkVerifierStageError(
        "PENDING_WORK_STAGE_BASE_INVALID",
        "Canonical WORK base event has no exact transaction id.",
      );
    }
    return {
      ...confirmed,
      network: "livenet",
      status: "confirmed",
      ticker: WORK_TOKEN_TICKER,
      tokenId: WORK_TOKEN_ID,
    };
  };
  const eventKey = (item) =>
    `${item.txid}:${item.protocolVout}:${item.recordOrdinal}`;
  const mints = pendingWorkVerifierStageSortUniqueItems(
    (Array.isArray(payload.mints) ? payload.mints : [])
      .filter(
        (item) => item?.confirmed === true && isWorkTokenId(item?.tokenId),
      )
      .map(confirmedEvent),
    eventKey,
  );
  const transfers = pendingWorkVerifierStageSortUniqueItems(
    (Array.isArray(payload.transfers) ? payload.transfers : [])
      .filter(
        (item) => item?.confirmed === true && isWorkTokenId(item?.tokenId),
      )
      .map(confirmedEvent),
    eventKey,
  );
  const invalidEvents = pendingWorkVerifierStageSortUniqueItems(
    pendingWorkVerifierStageCollapseExactLegacyInvalidSibling(
      (Array.isArray(payload.invalidEvents) ? payload.invalidEvents : [])
        .filter(
          (item) =>
            item?.confirmed === true &&
            item?.valid === false &&
            isWorkTokenId(item?.tokenId),
        )
        .map((item) => ({ ...confirmedEvent(item), valid: false })),
    ),
    eventKey,
  );
  const listings = pendingWorkVerifierStageSortUniqueItems(
    (Array.isArray(payload.listings) ? payload.listings : [])
      .filter(
        (item) => item?.confirmed === true && isWorkTokenId(item?.tokenId),
      )
      .map((item) => pendingWorkVerifierStageConfirmedListing(item)),
    (item) => item.listingId,
  );
  const closedListings = pendingWorkVerifierStageSortUniqueItems(
    (Array.isArray(payload.closedListings) ? payload.closedListings : [])
      .filter(
        (item) =>
          item?.confirmed === true &&
          item?.closedConfirmed === true &&
          isWorkTokenId(item?.tokenId),
      )
      .map((item) =>
        pendingWorkVerifierStageConfirmedListing(item, { closed: true }),
      ),
    (item) => `${item.listingId}:${item.closedTxid}`,
  );
  const sales = pendingWorkVerifierStageSortUniqueItems(
    (Array.isArray(payload.sales) ? payload.sales : [])
      .filter(
        (item) => item?.confirmed === true && isWorkTokenId(item?.tokenId),
      )
      .map(confirmedEvent),
    eventKey,
  );
  if (mints.length === 0) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_INVALID",
      "Canonical WORK base has no confirmed mint history.",
    );
  }
  const supplyText = confirmedSupplySubatoms.toString();
  const token = {
    ...canonicalDefinition,
    confirmedMints: mints.length,
    confirmedSupply: formatWorkSubatoms(confirmedSupplySubatoms),
    confirmedSupplySubatoms: supplyText,
    holderCount: holders.length,
    pendingMints: 0,
    pendingSupply: formatWorkSubatoms(0n),
    pendingSupplySubatoms: "0",
  };
  const state = pendingWorkVerifierStageJsonClone({
    amountStorageModel: WORK_SUBATOM_PROJECTION_MODEL,
    blockHash: tip.blockHash,
    canonicalCoverage: true,
    closedListings,
    confirmedSupply: formatWorkSubatoms(confirmedSupplySubatoms),
    confirmedSupplySubatoms: supplyText,
    coverageHeight: tip.height,
    decimals: WORK_SUBATOM_DECIMALS,
    holders,
    indexedThroughBlock: tip.height,
    indexedThroughBlockHash: tip.blockHash,
    invalidEvents,
    listings,
    mints,
    network: "livenet",
    pendingSupply: formatWorkSubatoms(0n),
    pendingSupplySubatoms: "0",
    precisionModel: WORK_PRECISION_V2_MODEL,
    sales,
    source: "proof-indexer-token-state-tables-confirmed-work-base",
    stats: {
      confirmedMints: mints.length,
      confirmedTokens: 1,
      confirmedTransfers: transfers.length,
      holders: holders.length,
      invalidEvents: invalidEvents.length,
      pendingMints: 0,
      pendingTokens: 0,
      pendingTransfers: 0,
    },
    tokens: [token],
    transfers,
    unitScale: WORK_SUBATOM_UNIT_SCALE_TEXT,
  });
  if (
    !workPrecisionV2CurrentPayloadIsExact(
      state,
      WORK_AMO_V8_ACTIVATION_HEIGHT,
      { requireSupplyEnvelope: true },
    ) ||
    !tokenTablePayloadHasConservedBalances(state)
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_CONSERVATION_INVALID",
      "Canonical WORK confirmed base failed Q16 supply conservation.",
    );
  }
  try {
    workAmoV8CanonicalTokenStateCommitment(state);
  } catch (error) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_COMMITMENT_INVALID",
      "Canonical WORK confirmed base failed the AMO V8 state commitment.",
      { reason: errorSummary(error) },
    );
  }
  const payloadCommitment = workAmoV5CanonicalPayloadCommitment({
    canonicalTip: { hash: tip.blockHash, height: tip.height },
    closedListings,
    confirmedSupplySubatoms: supplyText,
    holders,
    invalidEvents,
    listings,
    mints,
    model: "canonical-work-q16-confirmed-base-v1",
    network: "livenet",
    sales,
    token,
    transfers,
  });
  if (
    tokenStateCommitment?.model !==
      WORK_AMO_V5_PAYLOAD_COMMITMENT_MODEL ||
    !Number.isSafeInteger(tokenStateCommitment.payloadBytes) ||
    tokenStateCommitment.payloadBytes <= 0 ||
    !/^[0-9a-f]{64}$/u.test(String(tokenStateCommitment.sha256 ?? ""))
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BASE_COMMITMENT_INVALID",
      "Canonical WORK confirmed base requires the direct V8 transition token-state commitment.",
    );
  }
  return {
    commitment: {
      ...payloadCommitment,
      tokenStateCommitment,
    },
    state,
  };
}

function pendingWorkVerifierStageCoreAuthority(
  chainResponse,
  indexResponse,
  tip,
) {
  const chain = chainResponse?.ok === true ? chainResponse.result : null;
  const txindex =
    indexResponse?.ok === true ? indexResponse.result?.txindex : null;
  const verificationProgress = Number(chain?.verificationprogress);
  const txindexHeight = Number(txindex?.best_block_height);
  if (
    !chain ||
    chain.chain !== "main" ||
    chain.pruned !== false ||
    chain.initialblockdownload !== false ||
    !Number.isFinite(verificationProgress) ||
    verificationProgress < 0.999 ||
    !txindex ||
    txindex.synced !== true ||
    !Number.isSafeInteger(txindexHeight) ||
    txindexHeight !== tip?.height
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_CORE_AUTHORITY_UNAVAILABLE",
      "Bitcoin Core is not a synced, unpruned mainnet node with txindex at the exact tip.",
    );
  }
}

async function pendingWorkVerifierStageProveCoreAbsence(txids) {
  const failures = [];
  await mapWithConcurrency(
    txids,
    Math.min(8, Math.max(1, TX_FETCH_CONCURRENCY)),
    async (txid) => {
      const [transactionResponse, mempoolResponse] = await Promise.all([
        bitcoinRpc("getrawtransaction", [txid, true]).catch(() => null),
        bitcoinRpc("getmempoolentry", [txid]).catch(() => null),
      ]);
      if (
        !transactionResponse ||
        transactionResponse.ok === true ||
        Number(transactionResponse?.error?.code) !== -5 ||
        !mempoolResponse ||
        mempoolResponse.ok === true ||
        Number(mempoolResponse?.error?.code) !== -5
      ) {
        failures.push(txid);
      }
    },
  );
  if (failures.length > 0) {
    failures.sort(compareCanonicalUtf8);
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_ABSENCE_UNPROVEN",
      "Bitcoin Core could not prove every declared absent prior member absent from both txindex and mempool.",
      { txids: failures },
    );
  }
}

async function pendingWorkVerifierStageProveCoreConfirmedRemovals(
  txids,
  tip,
) {
  if (
    !tip ||
    !Number.isSafeInteger(tip.height) ||
    tip.height < 1 ||
    !/^[0-9a-f]{64}$/u.test(String(tip.blockHash ?? ""))
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_CONFIRMED_REMOVAL_UNPROVEN",
      "Pending WORK confirmed-removal proof requires one exact Core tip.",
    );
  }
  return mapWithConcurrency(
    txids,
    Math.min(8, Math.max(1, TX_FETCH_CONCURRENCY)),
    async (txid) => {
      let transactionResponse;
      try {
        transactionResponse = await bitcoinRpc("getrawtransaction", [
          txid,
          true,
        ]);
      } catch (error) {
        throw pendingWorkVerifierStageError(
          "PENDING_WORK_STAGE_CONFIRMED_REMOVAL_UNPROVEN",
          "Bitcoin Core confirmed-removal transaction lookup failed.",
          { reason: errorSummary(error), txid },
        );
      }
      const transaction = transactionResponse?.ok === true
        ? transactionResponse.result
        : null;
      const transactionTxid = String(transaction?.txid ?? "")
        .trim()
        .toLowerCase();
      const blockHash = String(transaction?.blockhash ?? "")
        .trim()
        .toLowerCase();
      const rawHex = String(transaction?.hex ?? "").trim().toLowerCase();
      let rawTransactionTxid = "";
      try {
        rawTransactionTxid = bitcoin.Transaction.fromHex(rawHex).getId();
      } catch {
        rawTransactionTxid = "";
      }
      if (
        !transaction ||
        transactionTxid !== txid ||
        rawTransactionTxid !== txid ||
        !/^[0-9a-f]{64}$/u.test(blockHash) ||
        !/^[0-9a-f]+$/u.test(rawHex) ||
        rawHex.length % 2 !== 0 ||
        Number(transaction.confirmations) <= 0
      ) {
        throw pendingWorkVerifierStageError(
          "PENDING_WORK_STAGE_CONFIRMED_REMOVAL_UNPROVEN",
          "Bitcoin Core did not return exact confirmed raw transaction evidence for a prior WORK member.",
          { txid },
        );
      }

      let headerResponse;
      try {
        headerResponse = await bitcoinRpc("getblockheader", [blockHash, true]);
      } catch (error) {
        throw pendingWorkVerifierStageError(
          "PENDING_WORK_STAGE_CONFIRMED_REMOVAL_UNPROVEN",
          "Bitcoin Core confirmed-removal block-header lookup failed.",
          { reason: errorSummary(error), txid },
        );
      }
      const header = headerResponse?.ok === true ? headerResponse.result : null;
      const blockHeight = Number(header?.height);
      const expectedConfirmations = Number.isSafeInteger(blockHeight)
        ? tip.height - blockHeight + 1
        : 0;
      if (
        !header ||
        String(header.hash ?? "").trim().toLowerCase() !== blockHash ||
        !Number.isSafeInteger(blockHeight) ||
        blockHeight < 1 ||
        blockHeight > tip.height ||
        expectedConfirmations < 1 ||
        Number(header.confirmations) !== expectedConfirmations ||
        Number(transaction.confirmations) !== expectedConfirmations
      ) {
        throw pendingWorkVerifierStageError(
          "PENDING_WORK_STAGE_CONFIRMED_REMOVAL_UNPROVEN",
          "Bitcoin Core confirmed-removal evidence is not bound to the staged tip.",
          { blockHash, blockHeight, txid },
        );
      }

      let canonicalHashResponse;
      try {
        canonicalHashResponse = await bitcoinRpc("getblockhash", [blockHeight]);
      } catch (error) {
        throw pendingWorkVerifierStageError(
          "PENDING_WORK_STAGE_CONFIRMED_REMOVAL_UNPROVEN",
          "Bitcoin Core confirmed-removal canonical-height lookup failed.",
          { blockHeight, reason: errorSummary(error), txid },
        );
      }
      if (
        canonicalHashResponse?.ok !== true ||
        String(canonicalHashResponse.result ?? "").trim().toLowerCase() !==
          blockHash
      ) {
        throw pendingWorkVerifierStageError(
          "PENDING_WORK_STAGE_CONFIRMED_REMOVAL_UNPROVEN",
          "Bitcoin Core did not prove the confirmed-removal block canonical at its height.",
          { blockHash, blockHeight, txid },
        );
      }
      return {
        blockHash,
        blockHeight,
        confirmations: expectedConfirmations,
        txid,
      };
    },
  );
}

function pendingWorkVerifierStageRawTransaction(tx, txid, network) {
  const mempoolTime = Number(tx?.status?.mempool_time);
  const txHex = String(tx?.hex ?? "").trim().toLowerCase();
  let rawHexTxid = "";
  try {
    rawHexTxid = bitcoin.Transaction.fromHex(txHex).getId();
  } catch {
    rawHexTxid = "";
  }
  if (
    tx?._powCanonicalRpcHydration !== true ||
    transactionTxid(tx) !== txid ||
    !/^[0-9a-f]+$/u.test(txHex) ||
    txHex.length % 2 !== 0 ||
    rawHexTxid !== txid ||
    transactionConfirmed(tx) ||
    !transactionHasCompleteCanonicalPrevouts(tx) ||
    !Number.isSafeInteger(mempoolTime) ||
    mempoolTime * 1000 < Date.UTC(2009, 0, 3, 18, 15, 5) ||
    mempoolTime * 1000 > Date.now() + 5 * 60_000
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_TRANSACTION_HYDRATION_INVALID",
      "Bitcoin Core did not provide a complete canonical pending transaction with prevouts and a stable mempool epoch.",
      { txid },
    );
  }
  let recordSet;
  try {
    recordSet = canonicalRawProtocolRecordSetFromTransaction(tx);
  } catch (error) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_RAW_PROTOCOL_INVALID",
      "Pending WORK transaction has invalid raw protocol evidence.",
      { reason: errorSummary(error), txid },
    );
  }
  const records = recordSet.records.filter(
    (record) => record?.protocol === "pwt1",
  );
  const decodedMessages = decodedProtocolMessages(
    tx.vout ?? [],
    TOKEN_PROTOCOL_PREFIX,
  );
  if (
    records.length === 0 ||
    records.some((record) => record?.rawDecodeValid !== true) ||
    !isDeepStrictEqual(
      decodedMessages,
      records.map((record) => record.message),
    )
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_RAW_PROTOCOL_INVALID",
      "Pending WORK transaction raw pwt1 bytes do not exactly match its replay messages.",
      { txid },
    );
  }
  const parsedMessages = records.map((record) =>
    pendingWorkVerifierStageParsedMessage(record.message, network),
  );
  if (parsedMessages.some((parsed) => !parsed)) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_SCOPE_INVALID",
      "Pending WORK transaction contains a pwt1 record whose WORK scope cannot be proven.",
      { txid },
    );
  }
  return {
    mempoolCreatedAt: new Date(mempoolTime * 1000).toISOString(),
    mempoolTime,
    parsedMessages,
    records,
    transaction: tx,
    txid,
  };
}

function pendingWorkVerifierStageDecodedObject(value) {
  return decodeWorkAmoV5CanonicalBase64UrlJsonObject(value);
}

function pendingWorkVerifierStageParsedMessage(message, network) {
  const parsed = parseTokenPayload(message, network);
  if (parsed) {
    return parsed;
  }
  if (!String(message ?? "").startsWith(TOKEN_PROTOCOL_PREFIX)) {
    return null;
  }
  const parts = String(message)
    .slice(TOKEN_PROTOCOL_PREFIX.length)
    .split(":");
  const action = String(parts[0] ?? "").trim().toLowerCase();
  if (
    [
      TOKEN_MINT_ACTION,
      TOKEN_SEND_ACTION,
      TOKEN_SEND_ATOMS_ACTION,
      TOKEN_SEND_SUBATOMS_ACTION,
    ].includes(action)
  ) {
    const tokenId = String(parts[1] ?? "").trim().toLowerCase();
    return tokenId === WORK_TOKEN_ID
      ? {
          kind:
            action === TOKEN_MINT_ACTION ? "mint" : "send",
          pendingWorkStageMalformed: true,
          rawAction: action,
          tokenId,
        }
      : null;
  }
  if (action === TOKEN_LIST_ACTION) {
    const saleAuthorization = pendingWorkVerifierStageDecodedObject(parts[1]);
    return String(saleAuthorization?.tokenId ?? "").trim().toLowerCase() ===
        WORK_TOKEN_ID
      ? {
          kind: "list",
          pendingWorkStageMalformed: true,
          rawAction: action,
          saleAuthorization,
        }
      : null;
  }
  if (action === TOKEN_SEAL_ACTION) {
    const saleAuthorization = pendingWorkVerifierStageDecodedObject(parts[2]);
    return String(saleAuthorization?.tokenId ?? "").trim().toLowerCase() ===
        WORK_TOKEN_ID
      ? {
          kind: "seal",
          listingId: String(parts[1] ?? "").trim().toLowerCase(),
          pendingWorkStageMalformed: true,
          rawAction: action,
          saleAuthorization,
        }
      : null;
  }
  if ([TOKEN_BUY_ACTION, TOKEN_DELIST_ACTION].includes(action)) {
    const listingId = String(parts[1] ?? "").trim().toLowerCase();
    return /^[0-9a-f]{64}$/u.test(listingId)
      ? {
          kind: action === TOKEN_BUY_ACTION ? "buy" : "delist",
          listingId,
          pendingWorkStageMalformed: true,
          rawAction: action,
        }
      : null;
  }
  return null;
}

async function pendingWorkVerifierStageRecheckMempoolEpochs(
  transactionRecords,
) {
  await mapWithConcurrency(
    transactionRecords,
    Math.min(8, Math.max(1, TX_FETCH_CONCURRENCY)),
    async (record) => {
      const response = await bitcoinRpc("getmempoolentry", [record.txid])
        .catch(() => null);
      if (
        response?.ok !== true ||
        Number(response.result?.time) !== record.mempoolTime
      ) {
        throw pendingWorkVerifierStageError(
          "PENDING_WORK_STAGE_BINDING_CHANGED",
          "A pending WORK transaction changed mempool acceptance epoch during staged replay.",
          { txid: record.txid },
        );
      }
    },
  );
}

function pendingWorkVerifierStageHistoricalListingScope(value) {
  const scope = value && typeof value === "object" && !Array.isArray(value)
    ? value
    : null;
  const listingId = String(scope?.listingId ?? "").trim().toLowerCase();
  const tokenId = String(scope?.tokenId ?? "").trim().toLowerCase();
  const authorizationVersion = String(scope?.authorizationVersion ?? "")
    .trim()
    .toLowerCase();
  const blockHash = String(scope?.blockHash ?? "").trim().toLowerCase();
  const rawPayloadSha256 = String(scope?.rawPayloadSha256 ?? "")
    .trim()
    .toLowerCase();
  const blockHeight = Number(scope?.blockHeight);
  const blockIndex = Number(scope?.blockIndex);
  const protocolVout = Number(scope?.protocolVout);
  const recordOrdinal = Number(scope?.recordOrdinal);
  if (
    !pendingWorkVerifierStageExactObjectKeys(scope, [
      "authorizationVersion",
      "blockHash",
      "blockHeight",
      "blockIndex",
      "listingId",
      "model",
      "network",
      "protocolVout",
      "rawPayloadSha256",
      "recordOrdinal",
      "tokenId",
    ]) ||
    scope.model !== PENDING_WORK_HISTORICAL_LISTING_SCOPE_MODEL ||
    scope.network !== "livenet" ||
    !/^[0-9a-f]{64}$/u.test(listingId) ||
    tokenId !== WORK_TOKEN_ID ||
    !PENDING_WORK_HISTORICAL_LISTING_AUTH_VERSIONS.includes(
      authorizationVersion,
    ) ||
    !/^[0-9a-f]{64}$/u.test(blockHash) ||
    !/^[0-9a-f]{64}$/u.test(rawPayloadSha256) ||
    !Number.isSafeInteger(blockHeight) ||
    blockHeight <= 0 ||
    blockHeight >= WORK_AMO_V8_ACTIVATION_HEIGHT ||
    !Number.isSafeInteger(blockIndex) ||
    blockIndex < 0 ||
    !Number.isSafeInteger(protocolVout) ||
    protocolVout < 0 ||
    !Number.isSafeInteger(recordOrdinal) ||
    recordOrdinal < 0
  ) {
    return null;
  }
  return {
    authorizationVersion,
    blockHash,
    blockHeight,
    blockIndex,
    listingId,
    model: PENDING_WORK_HISTORICAL_LISTING_SCOPE_MODEL,
    network: "livenet",
    protocolVout,
    rawPayloadSha256,
    recordOrdinal,
    tokenId: WORK_TOKEN_ID,
  };
}

function pendingWorkVerifierStageHistoricalListingScopeMap(scopes) {
  const result = new Map();
  for (const value of Array.isArray(scopes) ? scopes : []) {
    const scope = pendingWorkVerifierStageHistoricalListingScope(value);
    if (!scope || result.has(scope.listingId)) {
      throw pendingWorkVerifierStageError(
        "PENDING_WORK_STAGE_LISTING_PARENT_UNPROVEN",
        "Canonical historical WORK listing scope evidence is malformed or ambiguous.",
        { listingId: scope?.listingId ?? null },
      );
    }
    result.set(scope.listingId, scope);
  }
  return result;
}

function pendingWorkVerifierStageConfirmedListingIds(baseState) {
  return new Set(
    [
      ...(Array.isArray(baseState?.listings) ? baseState.listings : []),
      ...(Array.isArray(baseState?.closedListings)
        ? baseState.closedListings
        : []),
    ].flatMap((listing) => {
      const listingId = String(listing?.listingId ?? "").trim().toLowerCase();
      return /^[0-9a-f]{64}$/u.test(listingId) ? [listingId] : [];
    }),
  );
}

function pendingWorkVerifierStageMissingListingIds(
  transactionRecords,
  baseState,
  mempool,
) {
  const confirmedListingIds =
    pendingWorkVerifierStageConfirmedListingIds(baseState);
  const listingIds = new Set();
  for (const record of transactionRecords) {
    for (const parsed of record.parsedMessages) {
      if (!["buy", "delist", "seal"].includes(parsed?.kind)) {
        continue;
      }
      const listingId = String(parsed?.listingId ?? "").trim().toLowerCase();
      if (
        /^[0-9a-f]{64}$/u.test(listingId) &&
        !confirmedListingIds.has(listingId) &&
        !mempool.membership.has(listingId)
      ) {
        listingIds.add(listingId);
      }
    }
  }
  return [...listingIds].sort(compareCanonicalUtf8);
}

async function pendingWorkVerifierStageHistoricalListingScopeFromCore(
  value,
  tip,
) {
  const scope = pendingWorkVerifierStageHistoricalListingScope(value);
  const fail = (reason) => {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_LISTING_PARENT_UNPROVEN",
      "A historical WORK listing scope witness could not be rebound to exact canonical Bitcoin Core evidence.",
      { listingId: scope?.listingId ?? null, reason },
    );
  };
  if (
    !scope ||
    !tip ||
    tip.height < WORK_AMO_V8_ACTIVATION_HEIGHT ||
    scope.blockHeight >= tip.height
  ) {
    return fail("historical-listing-scope-envelope-invalid");
  }
  let transaction;
  try {
    transaction = await fetchTransactionFromBitcoinRpc(
      scope.listingId,
      scope.network,
      {
        bypassCache: true,
        cacheResult: false,
        includePrevouts: false,
        includeRawHex: true,
      },
    );
  } catch (error) {
    return fail(`historical-listing-transaction:${errorSummary(error)}`);
  }
  if (
    !transaction ||
    transactionTxid(transaction) !== scope.listingId ||
    !transactionConfirmed(transaction) ||
    transactionBlockHash(transaction) !== scope.blockHash ||
    !/^[0-9a-f]+$/u.test(String(transaction.hex ?? ""))
  ) {
    return fail("historical-listing-transaction-binding-invalid");
  }
  const [canonicalHashResponse, blockResponse] = await Promise.all([
    bitcoinRpc("getblockhash", [scope.blockHeight]),
    bitcoinRpc("getblock", [scope.blockHash, 1]),
  ]);
  const block = blockResponse?.ok === true ? blockResponse.result : null;
  const blockTxids = Array.isArray(block?.tx)
    ? block.tx.map((txid) => String(txid ?? "").trim().toLowerCase())
    : [];
  if (
    canonicalHashResponse?.ok !== true ||
    String(canonicalHashResponse.result ?? "").trim().toLowerCase() !==
      scope.blockHash ||
    !block ||
    Number(block.height) !== scope.blockHeight ||
    String(block.hash ?? "").trim().toLowerCase() !== scope.blockHash ||
    Number(block.nTx) !== blockTxids.length ||
    blockTxids[scope.blockIndex] !== scope.listingId
  ) {
    return fail("historical-listing-canonical-block-binding-invalid");
  }
  let records;
  try {
    records = canonicalRawProtocolRecordSetFromTransaction(transaction).records;
  } catch (error) {
    return fail(`historical-listing-raw-records:${errorSummary(error)}`);
  }
  const listingRecords = records.flatMap((record) => {
    if (record?.protocol !== "pwt1" || record?.rawDecodeValid !== true) {
      return [];
    }
    const parsed = parseTokenPayload(record.message, scope.network);
    return parsed?.kind === "list" ? [{ parsed, record }] : [];
  });
  if (listingRecords.length !== 1) {
    return fail("historical-listing-record-cardinality-invalid");
  }
  const { parsed, record } = listingRecords[0];
  const authorization = parsed?.saleAuthorization ??
    parsed?.listingAuthorization;
  const rawPayloadSha256 = createHash("sha256")
    .update(Buffer.from(String(record.message ?? ""), "utf8"))
    .digest("hex");
  if (
    Number(record.protocolVout) !== scope.protocolVout ||
    Number(record.recordOrdinal) !== scope.recordOrdinal ||
    rawPayloadSha256 !== scope.rawPayloadSha256 ||
    String(authorization?.tokenId ?? "").trim().toLowerCase() !==
      WORK_TOKEN_ID ||
    String(authorization?.version ?? "").trim().toLowerCase() !==
      scope.authorizationVersion
  ) {
    return fail("historical-listing-raw-scope-binding-invalid");
  }
  return scope;
}

async function pendingWorkVerifierStageHistoricalListingScopes(
  transactionRecords,
  baseState,
  mempool,
  tip,
) {
  const listingIds = pendingWorkVerifierStageMissingListingIds(
    transactionRecords,
    baseState,
    mempool,
  );
  if (listingIds.length === 0) {
    return [];
  }
  let relationalScopes;
  try {
    relationalScopes = await proofIndexCanonicalHistoricalWorkListingScopes(
      "livenet",
      listingIds,
      WORK_AMO_V8_ACTIVATION_HEIGHT,
    );
  } catch (error) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_LISTING_PARENT_UNPROVEN",
      "Canonical historical WORK listing scope evidence is unavailable.",
      { reason: errorSummary(error) },
    );
  }
  const requested = new Set(listingIds);
  const relationalMap = pendingWorkVerifierStageHistoricalListingScopeMap(
    relationalScopes,
  );
  if ([...relationalMap.keys()].some((listingId) => !requested.has(listingId))) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_LISTING_PARENT_UNPROVEN",
      "Canonical historical WORK listing scope evidence escaped the requested set.",
    );
  }
  return mapWithConcurrency(
    [...relationalMap.values()].sort((left, right) =>
      compareCanonicalUtf8(left.listingId, right.listingId)
    ),
    Math.min(4, Math.max(1, TX_FETCH_CONCURRENCY)),
    (scope) =>
      pendingWorkVerifierStageHistoricalListingScopeFromCore(scope, tip),
  );
}

function pendingWorkVerifierStageProveWorkScope(
  transactionRecords,
  baseState,
  mempool,
  historicalScopes = [],
) {
  const historicalListings =
    pendingWorkVerifierStageHistoricalListingScopeMap(historicalScopes);
  const confirmedListings = new Map();
  for (const listing of [
    ...(Array.isArray(baseState?.listings) ? baseState.listings : []),
    ...(Array.isArray(baseState?.closedListings)
      ? baseState.closedListings
      : []),
  ]) {
    const listingId = String(listing?.listingId ?? "").trim().toLowerCase();
    if (/^[0-9a-f]{64}$/u.test(listingId)) {
      confirmedListings.set(listingId, listing);
    }
  }
  for (const record of transactionRecords) {
    for (const parsed of record.parsedMessages) {
      let tokenId = "";
      if (parsed.kind === "mint" || parsed.kind === "send") {
        tokenId = String(parsed.tokenId ?? "").trim().toLowerCase();
      } else if (parsed.kind === "list" || parsed.kind === "seal") {
        tokenId = String(parsed.saleAuthorization?.tokenId ?? "")
          .trim()
          .toLowerCase();
      } else if (parsed.kind === "buy" || parsed.kind === "delist") {
        const listingId = String(parsed.listingId ?? "").trim().toLowerCase();
        const listing = confirmedListings.get(listingId);
        const historicalListing = historicalListings.get(listingId);
        if (!listing && mempool.membership.has(listingId)) {
          throw pendingWorkVerifierStageError(
            "PENDING_WORK_STAGE_UNCONFIRMED_LISTING_PARENT",
            "A pending WORK marketplace action references an unconfirmed mempool listing parent.",
            { listingId, txid: record.txid },
          );
        }
        if (!listing && !historicalListing) {
          throw pendingWorkVerifierStageError(
            "PENDING_WORK_STAGE_LISTING_PARENT_UNPROVEN",
            "A pending marketplace action cannot be proven to reference a confirmed WORK listing.",
            { listingId: listingId || null, txid: record.txid },
          );
        }
        tokenId = String(
          listing?.tokenId ?? historicalListing?.tokenId ?? "",
        )
          .trim()
          .toLowerCase();
      } else {
        throw pendingWorkVerifierStageError(
          "PENDING_WORK_STAGE_SCOPE_INVALID",
          "Pending verifier stage accepts only declared WORK mint, transfer, and marketplace pwt1 actions.",
          { kind: parsed.kind ?? null, txid: record.txid },
        );
      }
      if (tokenId !== WORK_TOKEN_ID) {
        throw pendingWorkVerifierStageError(
          "PENDING_WORK_STAGE_SCOPE_INVALID",
          "Pending verifier stage transaction is not exclusively WORK-scoped.",
          { tokenId: tokenId || null, txid: record.txid },
        );
      }
      if (parsed.pendingWorkStageMalformed === true) {
        continue;
      }
      if (parsed.kind === "seal") {
        const listingId = String(parsed.listingId ?? "").trim().toLowerCase();
        if (
          !confirmedListings.has(listingId) &&
          !historicalListings.has(listingId)
        ) {
          throw pendingWorkVerifierStageError(
            mempool.membership.has(listingId)
              ? "PENDING_WORK_STAGE_UNCONFIRMED_LISTING_PARENT"
              : "PENDING_WORK_STAGE_LISTING_PARENT_UNPROVEN",
            mempool.membership.has(listingId)
              ? "A pending WORK seal references an unconfirmed mempool listing parent."
              : "A pending WORK seal cannot prove its confirmed listing parent.",
            { listingId: listingId || null, txid: record.txid },
          );
        }
      }
    }
  }
}

function pendingWorkVerifierStageReplayState(state, transaction, network) {
  const replayed = workTokenStateWithDeltaTransactions(
    state,
    [transaction],
    network,
    workTokenStateWithDeltaTransactions,
  );
  return {
    ...replayed,
    canonicalCoverage: true,
    holders: (Array.isArray(replayed?.holders) ? replayed.holders : []).map(
      (holder) => ({
        ...holder,
        pendingDelta: formatWorkSubatoms(0n),
        pendingDeltaSubatoms: "0",
        registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
        ticker: WORK_TOKEN_TICKER,
        tokenId: WORK_TOKEN_ID,
      }),
    ),
  };
}

function pendingWorkVerifierStageOrderConflictReason(state, parsedMessages) {
  for (const parsed of parsedMessages) {
    if (!["buy", "delist", "seal"].includes(parsed?.kind)) {
      continue;
    }
    const listingId = String(parsed.listingId ?? "").trim().toLowerCase();
    const closedListing = (Array.isArray(state?.closedListings)
      ? state.closedListings
      : []
    ).find(
      (listing) =>
        String(listing?.listingId ?? "").trim().toLowerCase() === listingId,
    );
    if (closedListing?.closedConfirmed === false) {
      return (
        "Referenced ProofOfWork credit listing was already closed by an " +
        "earlier pending WORK transaction in declared lexicographic order."
      );
    }
  }
  return (
    "No valid WORK event was produced for this raw pwt1 record in the " +
    "declared pending replay order."
  );
}

function pendingWorkVerifierStageActorAddress(transaction) {
  return inputAddresses(Array.isArray(transaction?.vin) ? transaction.vin : [])[0] ?? "";
}

function pendingWorkVerifierStageListing(state, listingId) {
  const normalizedListingId = String(listingId ?? "").trim().toLowerCase();
  return [
    ...(Array.isArray(state?.listings) ? state.listings : []),
    ...(Array.isArray(state?.closedListings) ? state.closedListings : []),
  ].find(
    (listing) =>
      String(listing?.listingId ?? "").trim().toLowerCase() ===
        normalizedListingId,
  ) ?? null;
}

function pendingWorkVerifierStageRecordHistoricalListingScopes(
  record,
  historicalListings,
) {
  const scopes = new Map();
  for (const parsed of Array.isArray(record?.parsedMessages)
    ? record.parsedMessages
    : []) {
    if (!["buy", "delist", "seal"].includes(parsed?.kind)) {
      continue;
    }
    const listingId = String(parsed?.listingId ?? "").trim().toLowerCase();
    const scope = historicalListings.get(listingId);
    if (scope) {
      scopes.set(listingId, scope);
    }
  }
  return [...scopes.values()].sort((left, right) =>
    compareCanonicalUtf8(left.listingId, right.listingId)
  );
}

function pendingWorkVerifierStageInvalidEvidence(
  state,
  transaction,
  parsed,
  rawRecord,
  historicalListingScopes = [],
) {
  const actor = pendingWorkVerifierStageActorAddress(transaction);
  const authorization = parsed?.saleAuthorization &&
      typeof parsed.saleAuthorization === "object" &&
      !Array.isArray(parsed.saleAuthorization)
    ? parsed.saleAuthorization
    : null;
  const listing = pendingWorkVerifierStageListing(
    state,
    parsed?.listingId,
  );
  const recipientAddress = String(parsed?.recipientAddress ?? "").trim();
  const sellerAddress = String(
    authorization?.sellerAddress ?? listing?.sellerAddress ?? "",
  ).trim();
  const buyerAddress = String(
    authorization?.buyerAddress ?? listing?.buyerAddress ?? "",
  ).trim();
  const participants = [...new Set([
    actor,
    recipientAddress,
    sellerAddress,
    buyerAddress,
  ].filter(Boolean))];
  const evidence = {
    ...(actor ? { actor, senderAddress: actor } : {}),
    ...(buyerAddress ? { buyerAddress } : {}),
    dataBytes: Buffer.byteLength(String(rawRecord?.message ?? ""), "utf8"),
    ...(parsed?.listingId ? { listingId: parsed.listingId } : {}),
    ...(parsed?.kind === "mint" && actor ? { minterAddress: actor } : {}),
    ...(participants.length > 0 ? { participants } : {}),
    ...(recipientAddress ? { recipientAddress } : {}),
    ...(authorization ? { saleAuthorization: authorization } : {}),
    ...(sellerAddress ? { sellerAddress } : {}),
    ...(historicalListingScopes.length > 0
      ? {
          historicalListingScopes,
          reasonCode: PENDING_WORK_HISTORICAL_LISTING_REASON_CODE,
        }
      : {}),
  };
  for (const field of [
    "amount",
    "amountAtoms",
    "amountStorageModel",
    "amountSubatoms",
    "amountVersion",
    "decimals",
    "precisionModel",
    "rawAction",
    "unitScale",
  ]) {
    if (
      parsed?.[field] !== undefined &&
      parsed?.[field] !== null &&
      parsed?.[field] !== ""
    ) {
      evidence[field] = parsed[field];
    }
  }
  return evidence;
}

async function pendingWorkVerifierStageTransactionInvalidReason(
  state,
  record,
  network,
  tipHeight,
) {
  let admissionDeferredToReplay = false;
  try {
    const shape = workAmoV8SignedMutationShape(
      record.transaction.hex,
      network,
    );
    const actions = await signedWorkMarketplaceWriteActions(
      record.transaction.hex,
      network,
    );
    const decision = workAmoV8ActiveMutationDecision(
      shape,
      actions,
      {
        metadata: {
          activation: {
            activationHeight: WORK_AMO_V8_ACTIVATION_HEIGHT,
          },
          activationHeight: WORK_AMO_V8_ACTIVATION_HEIGHT,
          tipHeight,
        },
        network,
        requireWorkMutation: true,
      },
    );
    if (!decision.allowed) {
      return decision.message ?? "Active WORK transaction shape is invalid.";
    }
  } catch (error) {
    if (
      error?.details?.code ===
        "WORK_MARKETPLACE_LISTING_RESOLUTION_UNAVAILABLE"
    ) {
      // Pending replay already proved the listing scope from Core/index state.
      // A transient UI write-action read miss should not block the canonical
      // pending witness when the token verifier can still decide the tx.
      admissionDeferredToReplay = true;
    } else {
      const statusCode = Number(error?.statusCode);
      if (
        Number.isSafeInteger(statusCode) &&
        statusCode >= 400 &&
        statusCode < 500
      ) {
        return error?.message ?? "Active WORK transaction shape is invalid.";
      }
      throw pendingWorkVerifierStageError(
        "PENDING_WORK_STAGE_ADMISSION_UNAVAILABLE",
        "The active WORK transaction-shape validator could not resolve a staged transaction.",
        { reason: errorSummary(error), txid: record.txid },
      );
    }
  }
  const deterministicReason = await tokenVerifierDeterministicInvalidReason(
    network,
    state,
    record.txid,
    false,
    {
      exactPendingCoreState: true,
      transaction: record.transaction,
    },
  );
  if (admissionDeferredToReplay && !deterministicReason) {
    return "";
  }
  return deterministicReason;
}

function pendingWorkVerifierStageStableDecisionItem(
  item,
  mempoolCreatedAt,
) {
  const stable = { ...item };
  for (const field of [
    "checkedAt",
    "fetchedAt",
    "generatedAt",
    "indexedAt",
    "observedAt",
    "updatedAt",
  ]) {
    delete stable[field];
  }
  if (stable.kind === "token-listing-sealed") {
    stable.sealAt = mempoolCreatedAt;
  } else if (stable.kind === "token-listing-closed") {
    stable.closedAt = mempoolCreatedAt;
  } else {
    stable.createdAt = mempoolCreatedAt;
  }
  return stable;
}

function pendingWorkVerifierStageCanonicalItem(
  item,
  txid,
  records,
  mempoolCreatedAt,
) {
  const tokenId = String(item?.tokenId ?? "").trim().toLowerCase();
  const protocolVout = Number(item?.protocolVout);
  const recordOrdinal = Number(item?.recordOrdinal);
  const stableMempoolCreatedAt = pendingWorkVerifierStageCanonicalIso(
    mempoolCreatedAt,
  );
  if (
    tokenId !== WORK_TOKEN_ID ||
    typeof item?.valid !== "boolean" ||
    !stableMempoolCreatedAt ||
    !Number.isSafeInteger(protocolVout) ||
    protocolVout < 0 ||
    !Number.isSafeInteger(recordOrdinal) ||
    recordOrdinal < 0 ||
    !records.some(
      (record) =>
        record.protocolVout === protocolVout &&
        record.recordOrdinal === recordOrdinal,
    )
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_DECISION_INVALID",
      "Pending WORK replay produced a noncanonical verifier item.",
      { txid },
    );
  }
  return pendingWorkVerifierStageJsonClone({
    ...pendingWorkVerifierStageStableDecisionItem(
      item,
      stableMempoolCreatedAt.value,
    ),
    confirmed: false,
    network: "livenet",
    payload: records.find(
      (record) =>
        record.protocolVout === protocolVout &&
        record.recordOrdinal === recordOrdinal,
    )?.message,
    protocol: "pwt1",
    status: "pending",
    tokenId: WORK_TOKEN_ID,
    txid,
    valid: item.valid,
  });
}

function pendingWorkVerifierStageRecordPositionKey(value) {
  const protocolVout = Number(value?.protocolVout);
  const recordOrdinal = Number(value?.recordOrdinal);
  return Number.isSafeInteger(protocolVout) &&
      protocolVout >= 0 &&
      Number.isSafeInteger(recordOrdinal) &&
      recordOrdinal >= 0
    ? `${protocolVout}:${recordOrdinal}`
    : "";
}

function pendingWorkVerifierStageDecisionOutcomes(decisions) {
  const outcomes = (Array.isArray(decisions) ? decisions : []).flatMap(
    (decision) =>
      (Array.isArray(decision?.items) ? decision.items : []).map((item) => {
        return {
          kind: String(item?.kind ?? "").trim().toLowerCase(),
          protocolVout: Number(item?.protocolVout),
          rawPayloadSha256: createHash("sha256")
            .update(Buffer.from(String(item?.payload ?? ""), "utf8"))
            .digest("hex"),
          recordOrdinal: Number(item?.recordOrdinal),
          txid: String(decision?.txid ?? "").trim().toLowerCase(),
          valid: item?.valid === true,
        };
      }),
  );
  if (
    outcomes.some(
      (outcome) =>
        !outcome.kind ||
        !/^[0-9a-f]{64}$/u.test(outcome.txid) ||
        !Number.isSafeInteger(outcome.protocolVout) ||
        outcome.protocolVout < 0 ||
        !Number.isSafeInteger(outcome.recordOrdinal) ||
        outcome.recordOrdinal < 0,
    )
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_DECISION_INVALID",
      "Pending WORK decision outcomes contain an invalid protocol position.",
    );
  }
  outcomes.sort(
    (left, right) =>
      compareCanonicalUtf8(left.txid, right.txid) ||
      left.protocolVout - right.protocolVout ||
      left.recordOrdinal - right.recordOrdinal ||
      compareCanonicalUtf8(left.kind, right.kind) ||
      Number(left.valid) - Number(right.valid),
  );
  if (
    outcomes.some(
      (outcome, index) =>
        index > 0 &&
        isDeepStrictEqual(outcome, outcomes[index - 1]),
    )
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_DECISION_INVALID",
      "Pending WORK decision outcomes contain a duplicate event identity.",
    );
  }
  return outcomes;
}

async function pendingWorkVerifierStageDecisions(
  baseState,
  transactionRecords,
  network,
  tipHeight,
  historicalScopes = [],
) {
  let state = baseState;
  const decisions = [];
  const historicalListings =
    pendingWorkVerifierStageHistoricalListingScopeMap(historicalScopes);
  for (const record of transactionRecords) {
    const priorState = state;
    const recordHistoricalListingScopes =
      pendingWorkVerifierStageRecordHistoricalListingScopes(
        record,
        historicalListings,
      );
    const transactionInvalidReason =
      recordHistoricalListingScopes.length > 0
        ? PENDING_WORK_HISTORICAL_LISTING_REASON
        : await pendingWorkVerifierStageTransactionInvalidReason(
            priorState,
            record,
            network,
            tipHeight,
          );
    const nextState = transactionInvalidReason
      ? priorState
      : pendingWorkVerifierStageReplayState(
          priorState,
          record.transaction,
          network,
        );
    const items = (transactionInvalidReason
      ? []
      : tokenVerifierItemsFromState(nextState, record.txid))
      .map((item) =>
        pendingWorkVerifierStageCanonicalItem(
          item,
          record.txid,
          record.records,
          record.mempoolCreatedAt,
        ),
      );
    const coveredPositions = new Set(
      items.map(pendingWorkVerifierStageRecordPositionKey),
    );
    const uncoveredRecords = record.records.filter(
      (rawRecord) =>
        !coveredPositions.has(
          pendingWorkVerifierStageRecordPositionKey(rawRecord),
        ),
    );
    if (uncoveredRecords.length > 0) {
      const deterministicReason = transactionInvalidReason ||
        (uncoveredRecords.length === 1
        ? await tokenVerifierDeterministicInvalidReason(
            network,
            priorState,
            record.txid,
            false,
            {
              exactPendingCoreState: true,
              transaction: record.transaction,
            },
          )
        : "");
      for (const rawRecord of uncoveredRecords) {
        const recordIndex = record.records.indexOf(rawRecord);
        const parsedMessage = record.parsedMessages[recordIndex];
        items.push(pendingWorkVerifierStageJsonClone({
          ...pendingWorkVerifierStageInvalidEvidence(
            priorState,
            record.transaction,
            parsedMessage,
            rawRecord,
            recordHistoricalListingScopes,
          ),
          attemptedKind: String(
            parsedMessage?.kind ?? "unknown",
          )
            .trim()
            .toLowerCase(),
          confirmed: false,
          createdAt: record.mempoolCreatedAt,
          kind: "token-event-invalid",
          network,
          payload: rawRecord.message,
          protocol: "pwt1",
          protocolVout: rawRecord.protocolVout,
          reason:
            (parsedMessage?.pendingWorkStageMalformed === true
              ? `Malformed WORK-scoped ${
                  String(parsedMessage.rawAction ?? "pwt1")
                } record.`
              : "") ||
            (uncoveredRecords.length === 1 ? deterministicReason : "") ||
            pendingWorkVerifierStageOrderConflictReason(
              priorState,
              [parsedMessage],
            ),
          recordOrdinal: rawRecord.recordOrdinal,
          status: "pending",
          ticker: WORK_TOKEN_TICKER,
          tokenId: WORK_TOKEN_ID,
          txid: record.txid,
          valid: false,
        }));
      }
    }
    items.sort((left, right) =>
      Number(left.protocolVout) - Number(right.protocolVout) ||
      Number(left.recordOrdinal) - Number(right.recordOrdinal) ||
      compareCanonicalUtf8(String(left.kind ?? ""), String(right.kind ?? "")) ||
      compareCanonicalUtf8(
        workAmoV5CanonicalPayloadCommitment(left).sha256,
        workAmoV5CanonicalPayloadCommitment(right).sha256,
      )
    );
    decisions.push({ items, txid: record.txid });
    state = nextState;
  }
  return decisions;
}

function pendingWorkVerifierStageCommitmentSha256(label, value) {
  return workAmoV5CanonicalPayloadCommitment({ label, value }).sha256;
}

async function pendingWorkVerifierStagePayload(value) {
  const request = pendingWorkVerifierStageRequest(value);
  const [initialChain, initialIndex, initialMempoolResponse, initialStatus, initialCanonical, initialReadinessEpoch] =
    await Promise.all([
      bitcoinRpc("getblockchaininfo", []),
      bitcoinRpc("getindexinfo", ["txindex"]),
      bitcoinRpc("getrawmempool", [false]),
      proofIndexOperationalStatusPayload(request.network),
      proofIndexCanonicalStateMetaPayload(request.network),
      proofIndexReadinessEpochCheckpoint(request.network),
    ]);
  const initialTip = exactCoreTipFromBlockchainInfo(initialChain);
  if (
    !initialTip ||
    !initialReadinessEpoch ||
    !proofIndexExactlyCoversCoreTip(
      initialStatus,
      initialCanonical,
      initialTip,
    )
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_EXACT_TIP_UNAVAILABLE",
      "The proof index does not exactly cover the current Bitcoin Core tip.",
    );
  }
  pendingWorkVerifierStageCoreAuthority(
    initialChain,
    initialIndex,
    initialTip,
  );
  const initialMempool = pendingWorkVerifierStageCoreMempool(
    initialMempoolResponse,
  );
  pendingWorkVerifierStageValidateMembership(request, initialMempool);
  const absenceTxids = request.absenceEvidence.observations.map(
    (observation) => observation.txid,
  );
  const [, initialConfirmedRemovalProof] = await Promise.all([
    pendingWorkVerifierStageProveCoreAbsence(absenceTxids),
    pendingWorkVerifierStageProveCoreConfirmedRemovals(
      request.confirmedRemovalTxids,
      initialTip,
    ),
  ]);

  const [
    initialTokenPayload,
    initialTransitionCommitment,
    transactions,
  ] = await Promise.all([
    proofIndexCanonicalSummaryTokenTablePayload(request.network, {
      exactHash: initialTip.blockHash,
      exactHeight: initialTip.height,
    }),
    pendingWorkVerifierStageConfirmedTransitionCommitment(
      request.network,
      initialTip,
    ),
    mapWithConcurrency(
      request.replayTxids,
      Math.min(8, Math.max(1, TX_FETCH_CONCURRENCY)),
      async (txid) => {
        try {
          return await fetchTransactionFromBitcoinRpc(
            txid,
            request.network,
            {
              bypassCache: true,
              cacheResult: false,
              includeRawHex: true,
              requireCanonicalPrevouts: true,
            },
          );
        } catch (error) {
          throw pendingWorkVerifierStageError(
            "PENDING_WORK_STAGE_TRANSACTION_HYDRATION_INVALID",
            "Bitcoin Core could not bind a pending transaction's raw bytes, verbose fields, and canonical prevouts.",
            { reason: errorSummary(error), txid },
          );
        }
      },
    ),
  ]);
  const initialBase = pendingWorkVerifierStageConfirmedBase(
    initialTokenPayload,
    initialTip,
    initialTransitionCommitment,
  );
  const transactionRecords = transactions.map((transaction, index) =>
    pendingWorkVerifierStageRawTransaction(
      transaction,
      request.replayTxids[index],
      request.network,
    ),
  );
  const initialHistoricalListingScopes =
    await pendingWorkVerifierStageHistoricalListingScopes(
      transactionRecords,
      initialBase.state,
      initialMempool,
      initialTip,
    );
  pendingWorkVerifierStageProveWorkScope(
    transactionRecords,
    initialBase.state,
    initialMempool,
    initialHistoricalListingScopes,
  );
  const decisions = await pendingWorkVerifierStageDecisions(
    initialBase.state,
    transactionRecords,
    request.network,
    initialTip.height,
    initialHistoricalListingScopes,
  );
  if (
    decisions.length !== request.replayTxids.length ||
    decisions.some(
      (decision, index) => {
        if (
          decision.txid !== request.replayTxids[index] ||
          !Array.isArray(decision.items) ||
          decision.items.length === 0
        ) {
          return true;
        }
        const coveredPositions = new Set(
          decision.items.map(pendingWorkVerifierStageRecordPositionKey),
        );
        return transactionRecords[index].records.some(
          (record) =>
            !coveredPositions.has(
              pendingWorkVerifierStageRecordPositionKey(record),
            ),
        );
      },
    )
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_DECISION_INVALID",
      "Pending WORK replay did not produce a position-complete decision for every raw pwt1 record.",
    );
  }

  const [
    finalTokenPayload,
    finalTransitionCommitment,
  ] = await Promise.all([
    proofIndexCanonicalSummaryTokenTablePayload(request.network, {
      exactHash: initialTip.blockHash,
      exactHeight: initialTip.height,
    }),
    pendingWorkVerifierStageConfirmedTransitionCommitment(
      request.network,
      initialTip,
    ),
  ]);
  const [finalChain, finalIndex, finalMempoolResponse, finalStatus, finalCanonical] =
    await Promise.all([
      bitcoinRpc("getblockchaininfo", []),
      bitcoinRpc("getindexinfo", ["txindex"]),
      bitcoinRpc("getrawmempool", [false]),
      proofIndexOperationalStatusPayload(request.network),
      proofIndexCanonicalStateMetaPayload(request.network),
    ]);
  const finalTip = exactCoreTipFromBlockchainInfo(finalChain);
  if (
    !finalTip ||
    finalTip.height !== initialTip.height ||
    finalTip.blockHash !== initialTip.blockHash ||
    !proofIndexExactlyCoversCoreTip(finalStatus, finalCanonical, finalTip)
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BINDING_CHANGED",
      "Bitcoin Core or the proof index tip changed while the pending WORK stage was built.",
    );
  }
  pendingWorkVerifierStageCoreAuthority(finalChain, finalIndex, finalTip);
  const finalMempool = pendingWorkVerifierStageCoreMempool(
    finalMempoolResponse,
  );
  pendingWorkVerifierStageValidateMembership(request, finalMempool);
  const [, finalConfirmedRemovalProof] = await Promise.all([
    pendingWorkVerifierStageProveCoreAbsence(absenceTxids),
    pendingWorkVerifierStageProveCoreConfirmedRemovals(
      request.confirmedRemovalTxids,
      finalTip,
    ),
    pendingWorkVerifierStageRecheckMempoolEpochs(transactionRecords),
  ]);
  if (
    !isDeepStrictEqual(
      finalConfirmedRemovalProof,
      initialConfirmedRemovalProof,
    )
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BINDING_CHANGED",
      "Confirmed WORK departure evidence changed while the pending stage was built.",
    );
  }
  const finalBase = pendingWorkVerifierStageConfirmedBase(
    finalTokenPayload,
    finalTip,
    finalTransitionCommitment,
  );
  const finalHistoricalListingScopes =
    await pendingWorkVerifierStageHistoricalListingScopes(
      transactionRecords,
      finalBase.state,
      finalMempool,
      finalTip,
    );
  pendingWorkVerifierStageProveWorkScope(
    transactionRecords,
    finalBase.state,
    finalMempool,
    finalHistoricalListingScopes,
  );
  const finalReadinessEpoch =
    await proofIndexReadinessEpochCheckpoint(request.network);
  if (
    !finalReadinessEpoch ||
    !isDeepStrictEqual(finalReadinessEpoch, initialReadinessEpoch) ||
    !isDeepStrictEqual(finalBase.commitment, initialBase.commitment) ||
    !isDeepStrictEqual(
      finalHistoricalListingScopes,
      initialHistoricalListingScopes,
    )
  ) {
    throw pendingWorkVerifierStageError(
      "PENDING_WORK_STAGE_BINDING_CHANGED",
      "The confirmed WORK base, historical listing scope, or readiness epoch changed while the pending stage was built.",
    );
  }

  const priorMembershipSha256 = pendingWorkVerifierStageCommitmentSha256(
    "PRIOR-MEMBERSHIP",
    request.priorMembershipTxids,
  );
  const orderedReplaySha256 = pendingWorkVerifierStageCommitmentSha256(
    "ORDERED-REPLAY",
    request.replayTxids,
  );
  const confirmedRemovalSha256 = pendingWorkVerifierStageCommitmentSha256(
    "CONFIRMED-REMOVALS",
    request.confirmedRemovalTxids,
  );
  const removalSha256 = pendingWorkVerifierStageCommitmentSha256(
    "REMOVALS",
    request.removalTxids,
  );
  const absenceEvidenceSha256 = pendingWorkVerifierStageCommitmentSha256(
    "ABSENCE-EVIDENCE",
    request.absenceEvidence,
  );
  const decisionsSha256 = pendingWorkVerifierStageCommitmentSha256(
    "DECISIONS",
    decisions,
  );
  const decisionOutcomes = pendingWorkVerifierStageDecisionOutcomes(decisions);
  const decisionOutcomesSha256 = pendingWorkVerifierStageCommitmentSha256(
    "DECISION-OUTCOMES",
    decisionOutcomes,
  );
  const stageCore = {
    absenceEvidence: request.absenceEvidence,
    absenceEvidenceSha256,
    canonicalTip: {
      hash: finalTip.blockHash,
      height: finalTip.height,
    },
    codeVersion: PENDING_WORK_VERIFIER_STAGE_CODE_VERSION,
    confirmedBaseCommitment: finalBase.commitment,
    confirmedRemovalCount: request.confirmedRemovalTxids.length,
    confirmedRemovalSha256,
    confirmedRemovalTxids: request.confirmedRemovalTxids,
    decisionCount: decisions.length,
    decisionOutcomeCount: decisionOutcomes.length,
    decisionOutcomesSha256,
    decisionsSha256,
    model: PENDING_WORK_VERIFIER_STAGE_MODEL,
    network: request.network,
    orderedReplayCount: request.replayTxids.length,
    orderedReplaySha256,
    parentWitnessSha256: request.parentWitnessSha256,
    pendingDropConfirmationMs: PENDING_WORK_DROP_CONFIRMATION_MS,
    priorMembershipCount: request.priorMembershipTxids.length,
    priorMembershipSha256,
    priorMembershipTxids: request.priorMembershipTxids,
    readinessEpochCheckpoint: finalReadinessEpoch,
    removalCount: request.removalTxids.length,
    removalSha256,
    removalTxids: request.removalTxids,
    replayTxids: request.replayTxids,
    requestModel: request.model,
  };
  const stageCommitment = workAmoV5CanonicalPayloadCommitment(stageCore);
  return {
    decisions,
    model: PENDING_WORK_VERIFIER_STAGE_MODEL,
    stage: {
      ...stageCore,
      stagePayloadBytes: stageCommitment.payloadBytes,
      stageSha256: stageCommitment.sha256,
    },
  };
}

function exactPendingWorkMintStats(stats, txid) {
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  const workAmountStorageModel = String(
    stats?.amountStorageModel ?? "",
  );
  const q16 =
    workAmountStorageModel === WORK_SUBATOM_PROJECTION_MODEL;
  const q8 =
    workAmountStorageModel === WORK_ATOMIC_PROJECTION_MODEL;
  const confirmedMints = Number(stats?.confirmedMints);
  const confirmedSupply = Number(stats?.confirmedSupply);
  const pendingCandidateCount = Number(stats?.pendingCandidateCount);
  const pendingCandidateSupply = Number(stats?.pendingCandidateSupply);
  const pendingCandidates = Array.isArray(stats?.pendingCandidates)
    ? stats.pendingCandidates
    : [];
  const pendingMints = Number(stats?.pendingMints);
  const pendingSupply = Number(stats?.pendingSupply);
  const pendingWitnessLimit = Number(stats?.pendingWitnessLimit);
  const totalMints = Number(stats?.totalMints);
  const target = stats?.targetMintStats;
  const targetConfirmedMints = Number(target?.confirmedMints);
  const targetPendingMints = Number(target?.pendingMints);
  const targetTotalMints = Number(target?.totalMints);
  const exactNonNegativeInteger = (value) =>
    Number.isSafeInteger(value) && value >= 0;
  const exactAtomicSupply = (value, { subatoms = false } = {}) => {
    const normalized = subatoms
      ? canonicalWorkSubatomsText(value, { allowZero: true })
      : canonicalWorkAtomsText(value, { allowZero: true });
    return normalized ? BigInt(normalized) : null;
  };
  const confirmedAtomicSupply = q16
    ? exactAtomicSupply(stats?.confirmedSupplySubatoms, {
        subatoms: true,
      })
    : q8
      ? exactAtomicSupply(stats?.confirmedSupplyAtoms)
      : null;
  const pendingAtomicSupply = q16
    ? exactAtomicSupply(stats?.pendingSupplySubatoms, {
        subatoms: true,
      })
    : q8
      ? exactAtomicSupply(stats?.pendingSupplyAtoms)
      : null;
  const pendingCandidateAtomicSupply = q16
    ? exactAtomicSupply(stats?.pendingCandidateSupplySubatoms, {
        subatoms: true,
      })
    : q8
      ? exactAtomicSupply(stats?.pendingCandidateSupplyAtoms)
      : null;
  const mintAtomicAmount = q16
    ? WORK_TOKEN_MINT_AMOUNT_SUBATOMS
    : WORK_TOKEN_MINT_AMOUNT_ATOMS;
  const maxAtomicSupply = q16
    ? WORK_TOKEN_MAX_SUPPLY_SUBATOMS
    : WORK_TOKEN_MAX_SUPPLY_ATOMS;
  const precisionMetadataReady =
    (q16 &&
      Number(stats?.decimals) === WORK_SUBATOM_DECIMALS &&
      stats?.precisionModel === WORK_PRECISION_V2_MODEL &&
      String(stats?.unitScale ?? "") ===
        WORK_SUBATOM_UNIT_SCALE_TEXT) ||
    (q8 &&
      Number(stats?.decimals) === WORK_DECIMALS &&
      String(stats?.unitScale ?? "") === WORK_UNIT_SCALE_TEXT);
  if (
    stats?.network !== "livenet" ||
    stats?.source !== "proof-indexer-token-mint-events" ||
    String(stats?.tokenId ?? "").trim().toLowerCase() !== WORK_TOKEN_ID ||
    !precisionMetadataReady ||
    confirmedAtomicSupply === null ||
    pendingAtomicSupply === null ||
    pendingCandidateAtomicSupply === null ||
    ![
      confirmedMints,
      confirmedSupply,
      pendingCandidateCount,
      pendingCandidateSupply,
      pendingMints,
      pendingSupply,
      pendingWitnessLimit,
      totalMints,
      targetConfirmedMints,
      targetPendingMints,
      targetTotalMints,
    ].every(exactNonNegativeInteger) ||
    totalMints !== confirmedMints + pendingMints ||
    confirmedSupply !== confirmedMints * WORK_TOKEN_MINT_AMOUNT ||
    pendingSupply !== pendingMints * WORK_TOKEN_MINT_AMOUNT ||
    pendingWitnessLimit !== PENDING_WORK_MINT_WITNESS_LIMIT ||
    stats?.pendingCandidatesComplete !== true ||
    pendingCandidateCount !== pendingMints ||
    pendingCandidates.length !== pendingCandidateCount ||
    pendingCandidateSupply !== pendingSupply ||
    confirmedAtomicSupply !==
      BigInt(confirmedMints) * mintAtomicAmount ||
    pendingAtomicSupply !==
      BigInt(pendingMints) * mintAtomicAmount ||
    pendingCandidateAtomicSupply !== pendingAtomicSupply ||
    confirmedAtomicSupply > maxAtomicSupply ||
    String(target?.txid ?? "").trim().toLowerCase() !== normalizedTxid ||
    targetTotalMints !== targetConfirmedMints + targetPendingMints ||
    targetConfirmedMints !== 0 ||
    ![0, 1].includes(targetPendingMints)
  ) {
    return null;
  }
  const seenCandidateTxids = new Set();
  let candidateSupply = 0;
  let previousTxid = "";
  const exactCandidates = [];
  for (const candidate of pendingCandidates) {
    const candidateTxid = String(candidate?.txid ?? "").trim().toLowerCase();
    const amount = Number(candidate?.amount);
    const candidateAtomicAmount = q16
      ? exactAtomicSupply(candidate?.amountSubatoms, {
          subatoms: true,
        })
      : exactAtomicSupply(candidate?.amountAtoms);
    if (
      !/^[0-9a-f]{64}$/u.test(candidateTxid) ||
      amount !== WORK_TOKEN_MINT_AMOUNT ||
      candidate?.amountStorageModel !== workAmountStorageModel ||
      Number(candidate?.decimals) !==
        (q16 ? WORK_SUBATOM_DECIMALS : WORK_DECIMALS) ||
      String(candidate?.unitScale ?? "") !==
        (q16
          ? WORK_SUBATOM_UNIT_SCALE_TEXT
          : WORK_UNIT_SCALE_TEXT) ||
      (q16 &&
        candidate?.precisionModel !== WORK_PRECISION_V2_MODEL) ||
      candidateAtomicAmount !== mintAtomicAmount ||
      seenCandidateTxids.has(candidateTxid) ||
      (previousTxid &&
        compareCanonicalUtf8(previousTxid, candidateTxid) >= 0)
    ) {
      return null;
    }
    candidateSupply += amount;
    if (!Number.isSafeInteger(candidateSupply)) {
      return null;
    }
    seenCandidateTxids.add(candidateTxid);
    previousTxid = candidateTxid;
    exactCandidates.push({ amount, txid: candidateTxid });
  }
  if (
    candidateSupply !== pendingCandidateSupply ||
    (targetPendingMints === 1 &&
      !seenCandidateTxids.has(normalizedTxid)) ||
    (targetPendingMints === 0 &&
      seenCandidateTxids.has(normalizedTxid)) ||
    confirmedSupply < 0 ||
    confirmedSupply > WORK_TOKEN_MAX_SUPPLY
  ) {
    return null;
  }
  const targetPendingSupply =
    targetPendingMints * WORK_TOKEN_MINT_AMOUNT;
  const adjustedPendingSupply = pendingSupply - targetPendingSupply;
  const adjustedCandidates = exactCandidates.filter(
    (candidate) => candidate.txid !== normalizedTxid,
  );
  if (
    !Number.isSafeInteger(adjustedPendingSupply) ||
    adjustedPendingSupply < 0 ||
    adjustedCandidates.reduce(
      (total, candidate) => total + candidate.amount,
      0,
    ) !== adjustedPendingSupply
  ) {
    return null;
  }
  return {
    confirmedSupply,
    pendingCandidates: adjustedCandidates,
    pendingSupply: adjustedPendingSupply,
    targetPendingMints,
  };
}

function pendingWorkMintWitnessProof(supply, targetTxid, targetAmount) {
  const normalizedTargetTxid = String(targetTxid ?? "").trim().toLowerCase();
  const amount = Number(targetAmount);
  if (
    !supply ||
    !/^[0-9a-f]{64}$/u.test(normalizedTargetTxid) ||
    amount !== WORK_TOKEN_MINT_AMOUNT ||
    !Number.isSafeInteger(Number(supply.confirmedSupply))
  ) {
    return null;
  }
  let witnessSupply = 0;
  const witnesses = [];
  if (supply.confirmedSupply + amount > WORK_TOKEN_MAX_SUPPLY) {
    return { witnessSupply, witnesses };
  }
  for (const candidate of supply.pendingCandidates) {
    if (
      compareCanonicalUtf8(
        candidate.txid,
        normalizedTargetTxid,
      ) >= 0
    ) {
      break;
    }
    witnesses.push(candidate);
    witnessSupply += candidate.amount;
    if (
      Number.isSafeInteger(witnessSupply) &&
      supply.confirmedSupply + witnessSupply + amount > WORK_TOKEN_MAX_SUPPLY
    ) {
      return { witnessSupply, witnesses };
    }
  }
  return null;
}

async function pendingWorkMintSupplyCapVerifierPayload(
  network,
  tokenScope,
  txid,
  options = {},
) {
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  if (
    network !== "livenet" ||
    options.requireConfirmed === true ||
    tokenScope !== WORK_TOKEN_ID ||
    !/^[0-9a-f]{64}$/u.test(normalizedTxid)
  ) {
    return null;
  }

  const [transaction, mempoolResponse] = await Promise.all([
    fetchTransactionFromBitcoinRpc(normalizedTxid, network, {
      requireCanonicalPrevouts: true,
    }),
    bitcoinRpc("getmempoolentry", [normalizedTxid]),
  ]);
  const mint = pendingWorkMintFromHydratedTransaction(
    transaction,
    network,
    normalizedTxid,
  );
  if (
    !mint ||
    !coreMempoolEntryPresent(mempoolResponse)
  ) {
    return null;
  }

  const [tipResponse, status, canonical, mintStats] = await Promise.all([
    bitcoinRpc("getblockchaininfo", []),
    proofIndexOperationalStatusPayload(network),
    proofIndexCanonicalStateMetaPayload(network),
    proofIndexTokenMintStatsPayload(network, WORK_TOKEN_ID, {
      targetTxid: normalizedTxid,
    }),
  ]);
  const tip = exactCoreTipFromBlockchainInfo(tipResponse);
  const supply = exactPendingWorkMintStats(mintStats, normalizedTxid);
  const witnessProof = pendingWorkMintWitnessProof(
    supply,
    normalizedTxid,
    mint.amount,
  );
  if (
    !tip ||
    !proofIndexExactlyCoversCoreTip(status, canonical, tip) ||
    !supply ||
    !witnessProof
  ) {
    return null;
  }

  const validatedWitnesses = await mapWithConcurrency(
    witnessProof.witnesses,
    4,
    async (candidate) => {
      const [witnessTransaction, witnessMempoolResponse] =
        await Promise.all([
          fetchTransactionFromBitcoinRpc(candidate.txid, network, {
            requireCanonicalPrevouts: true,
          }),
          bitcoinRpc("getmempoolentry", [candidate.txid]),
        ]);
      const witnessMint = pendingWorkMintFromHydratedTransaction(
        witnessTransaction,
        network,
        candidate.txid,
      );
      return witnessMint?.amount === candidate.amount &&
          coreMempoolEntryPresent(witnessMempoolResponse)
        ? candidate
        : null;
    },
  );
  const validatedWitnessSupply = validatedWitnesses.reduce(
    (total, witness) => total + Number(witness?.amount ?? 0),
    0,
  );
  if (
    validatedWitnesses.some((witness) => !witness) ||
    !Number.isSafeInteger(validatedWitnessSupply) ||
    validatedWitnessSupply !== witnessProof.witnessSupply ||
    supply.confirmedSupply + validatedWitnessSupply + mint.amount <=
      WORK_TOKEN_MAX_SUPPLY
  ) {
    return null;
  }

  const [
    finalTipResponse,
    finalStatus,
    finalCanonical,
    finalMintStats,
    finalMempoolMembership,
  ] = await Promise.all([
    bitcoinRpc("getblockchaininfo", []),
    proofIndexOperationalStatusPayload(network),
    proofIndexCanonicalStateMetaPayload(network),
    proofIndexTokenMintStatsPayload(network, WORK_TOKEN_ID, {
      targetTxid: normalizedTxid,
    }),
    mapWithConcurrency(
      [normalizedTxid, ...validatedWitnesses.map((witness) => witness.txid)],
      4,
      async (memberTxid) =>
        coreMempoolEntryPresent(
          await bitcoinRpc("getmempoolentry", [memberTxid]),
        ),
    ),
  ]);
  const finalTip = exactCoreTipFromBlockchainInfo(finalTipResponse);
  const finalSupply = exactPendingWorkMintStats(
    finalMintStats,
    normalizedTxid,
  );
  const finalWitnessProof = pendingWorkMintWitnessProof(
    finalSupply,
    normalizedTxid,
    mint.amount,
  );
  if (
    !finalTip ||
    finalTip.height !== tip.height ||
    finalTip.blockHash !== tip.blockHash ||
    !proofIndexExactlyCoversCoreTip(finalStatus, finalCanonical, finalTip) ||
    !finalSupply ||
    finalSupply.confirmedSupply !== supply.confirmedSupply ||
    finalSupply.targetPendingMints !== supply.targetPendingMints ||
    !finalWitnessProof ||
    finalWitnessProof.witnessSupply !== validatedWitnessSupply ||
    finalWitnessProof.witnesses.length !== validatedWitnesses.length ||
    finalWitnessProof.witnesses.some(
      (witness, index) =>
        witness.txid !== validatedWitnesses[index]?.txid ||
        witness.amount !== validatedWitnesses[index]?.amount,
    ) ||
    finalMempoolMembership.length !== validatedWitnesses.length + 1 ||
    finalMempoolMembership.some((present) => present !== true)
  ) {
    return null;
  }

  const reason =
    `WORK mint exceeds max supply: ` +
    `${supply.confirmedSupply.toLocaleString("en-US")} confirmed + ` +
    `${validatedWitnessSupply.toLocaleString("en-US")} earlier pending + ` +
    `${mint.amount.toLocaleString("en-US")} requested > ` +
    `${WORK_TOKEN_MAX_SUPPLY.toLocaleString("en-US")} max.`;
  return {
    classification: "supply-cap",
    indexedAt:
      finalStatus.indexedAt ??
      finalMintStats.indexedAt ??
      new Date().toISOString(),
    indexedThroughBlock: tip.height,
    items: [{
      amount: mint.amount,
      blockHeight: null,
      confirmed: false,
      kind: "token-event-invalid",
      network,
      provisional: true,
      provisionalReason: "supply-cap",
      reason,
      registryAddress: WORK_TOKEN_DEFAULT_REGISTRY_ADDRESS,
      status: "pending",
      ticker: WORK_TOKEN_TICKER,
      tokenId: WORK_TOKEN_ID,
      txid: normalizedTxid,
      valid: false,
    }],
    network,
    provisional: true,
    source: "proof-indexer-pending-work-supply-cap-verifier",
    supplyCapWitnessTxids: validatedWitnesses.map((witness) => witness.txid),
    tokenScope: WORK_TOKEN_ID,
    txid: normalizedTxid,
  };
}

async function tokenVerifierDeterministicInvalidReason(
  network,
  state,
  txid,
  requireConfirmed,
  options = {},
) {
  const providedTransaction = options?.transaction;
  const tx = requireConfirmed
    ? state?.canonicalCoverage === true
      ? (Array.isArray(state.transactions) ? state.transactions : []).find(
          (candidate) =>
            transactionTxid(candidate) === txid &&
            transactionBlockHeight(candidate) ===
              Number(state?.coverageHeight ?? 0),
        )
      : null
    : providedTransaction &&
        transactionTxid(providedTransaction) === txid &&
        !transactionConfirmed(providedTransaction)
      ? providedTransaction
      : await fetchTransactionFromBitcoinRpc(txid, network).catch(() => null);
  if (!tx || (requireConfirmed && !transactionConfirmed(tx))) {
    return "";
  }
  const messages = decodedProtocolMessages(tx.vout ?? [], TOKEN_PROTOCOL_PREFIX);
  if (messages.length === 0) {
    return "";
  }
  const parsedMessages = messages.map((message) => parseTokenPayload(message, network));
  if (parsedMessages.some((parsed) => !parsed)) {
    return "Malformed ProofOfWork credit protocol payload.";
  }
  const exactBalanceState = requireConfirmed
    ? state?.canonicalCoverage === true
    : options?.exactPendingCoreState === true;
  const tokenById = new Map(
    (Array.isArray(state?.tokens) ? state.tokens : []).map((token) => [
      String(token?.tokenId ?? "").toLowerCase(),
      token,
    ]),
  );
  const indexAddress = tokenIndexAddressForNetwork(network);
  for (const parsed of parsedMessages) {
    let registryAddress = "";
    let minimumPayment = TOKEN_MIN_MUTATION_PRICE_SATS;
    let mintedToken = null;
    let pendingListBalance = null;
    if (parsed.kind === "create") {
      registryAddress = indexAddress;
      minimumPayment = TOKEN_CREATION_PRICE_SATS;
    } else if (parsed.kind === "mint" || parsed.kind === "send") {
      const token = tokenById.get(parsed.tokenId);
      if (!token?.registryAddress) {
        return "";
      }
      registryAddress = token.registryAddress;
      minimumPayment =
        parsed.kind === "mint"
          ? numericValue(token.mintPriceSats)
          : TOKEN_MIN_MUTATION_PRICE_SATS;
      if (parsed.kind === "mint") {
        mintedToken = token;
      }
    } else if (parsed.kind === "list") {
      const authorization = parsed.saleAuthorization;
      registryAddress = authorization?.registryAddress ?? "";
      const actorAddress = inputAddresses(tx.vin ?? [])[0] ?? "";
      const tokenId = String(authorization?.tokenId ?? "")
        .trim()
        .toLowerCase();
      const token = tokenById.get(tokenId);
      const workAmountStorageModel =
        isWorkTokenId(tokenId) &&
        (
          state?.amountStorageModel === WORK_SUBATOM_PROJECTION_MODEL ||
          state?.precisionModel === WORK_PRECISION_V2_MODEL ||
          workRecordUsesSubatoms(token)
        )
          ? WORK_SUBATOM_PROJECTION_MODEL
          : WORK_ATOMIC_PROJECTION_MODEL;
      const amount = isWorkTokenId(tokenId)
        ? tokenLedgerAmountFromRecord(tokenId, authorization, {
            workAmountStorageModel,
          })
        : tokenSaleAuthorizationLedgerAmount(authorization);
      if (
        exactBalanceState &&
        authorization?.sellerAddress === actorAddress &&
        /^[0-9a-f]{64}$/u.test(tokenId) &&
        amount !== null
      ) {
        const holder = (Array.isArray(state?.holders) ? state.holders : [])
          .find(
            (candidate) =>
              candidate?.address === actorAddress &&
              String(candidate?.tokenId ?? "").trim().toLowerCase() === tokenId,
          );
        const confirmedBalance = isWorkTokenId(tokenId)
          ? tokenLedgerAmountFromRecord(
              tokenId,
              {
                amount: holder?.balance ?? holder?.confirmedBalance,
                amountAtoms:
                  holder?.balanceAtoms ??
                  holder?.confirmedBalanceAtoms,
                amountStorageModel: holder?.amountStorageModel,
                amountSubatoms:
                  holder?.balanceSubatoms ??
                  holder?.confirmedBalanceSubatoms,
                precisionModel: holder?.precisionModel,
              },
              { allowZero: true, workAmountStorageModel },
            ) ?? 0n
          : isBondTokenId(tokenId)
            ? bondUnitsBigInt(
                holder?.balance ?? holder?.confirmedBalance ?? 0,
                { allowZero: true },
              ) ?? 0n
            : Number(holder?.balance ?? holder?.confirmedBalance ?? 0);
        const reservedBalance = (Array.isArray(state?.listings)
          ? state.listings
          : []
        )
          .filter(
            (listing) =>
              listing?.sellerAddress === actorAddress &&
              String(listing?.tokenId ?? "").trim().toLowerCase() === tokenId &&
              !tokenListingIsExpired(listing),
          )
          .reduce((total, listing) => {
            const listedAmount = tokenLedgerAmountFromRecord(
              tokenId,
              listing,
              isWorkTokenId(tokenId)
                ? { workAmountStorageModel }
                : {},
            );
            return listedAmount === null ? total : total + listedAmount;
          }, tokenLedgerZero(tokenId));
        if (
          (isWorkTokenId(tokenId) ||
            isBondTokenId(tokenId) ||
            (Number.isSafeInteger(confirmedBalance) &&
              Number.isSafeInteger(reservedBalance))) &&
          confirmedBalance >= tokenLedgerZero(tokenId) &&
          reservedBalance >= tokenLedgerZero(tokenId)
        ) {
          pendingListBalance = {
            actorAddress,
            amount,
            confirmedBalance,
            reservedBalance,
            ticker: String(
              authorization?.ticker ?? tokenById.get(tokenId)?.ticker ?? "credit",
            ).trim() || "credit",
            tokenId,
            workAmountStorageModel,
          };
        }
      }
    } else {
      const normalizedListingId = String(parsed.listingId ?? "")
        .trim()
        .toLowerCase();
      const listing = (Array.isArray(state?.listings) ? state.listings : [])
        .find(
          (candidate) =>
            String(candidate?.listingId ?? "").trim().toLowerCase() ===
            normalizedListingId,
        );
      const confirmedClosedListing = (Array.isArray(state?.closedListings)
        ? state.closedListings
        : []
      ).find(
        (candidate) =>
          candidate?.closedConfirmed === true &&
          String(candidate?.listingId ?? "").trim().toLowerCase() ===
            normalizedListingId,
      );
      if (!listing && confirmedClosedListing) {
        return "Referenced ProofOfWork credit listing is already closed.";
      }
      if (!listing?.registryAddress) {
        return "";
      }
      registryAddress = listing.registryAddress;
    }
    if (
      registryAddress &&
      tokenPaymentAmountBeforeProtocol(tx.vout ?? [], registryAddress) <
        minimumPayment
    ) {
      return "Required ProofOfWork credit registry payment is missing or misplaced.";
    }
    if (
      pendingListBalance &&
      pendingListBalance.confirmedBalance - pendingListBalance.reservedBalance <
        pendingListBalance.amount
    ) {
      return insufficientTokenBalanceInvalidEvent({
        ...pendingListBalance,
        recipientAddress: "",
      }).reason;
    }
    if (mintedToken && mintedToken.uncapped !== true) {
      const maxSupply = Number(mintedToken.maxSupply);
      const acceptedMints = (Array.isArray(state?.mints) ? state.mints : [])
        .filter(
          (mint) =>
            String(mint?.tokenId ?? "").trim().toLowerCase() ===
              parsed.tokenId &&
            Number.isSafeInteger(Number(mint?.amount)) &&
            Number(mint.amount) > 0,
        );
      const confirmedSupply = acceptedMints
        .filter((mint) => mint?.confirmed === true)
        .reduce((total, mint) => total + Number(mint.amount), 0);
      const pendingSupply = acceptedMints
        .filter((mint) => mint?.confirmed !== true)
        .reduce((total, mint) => total + Number(mint.amount), 0);
      if (
        Number.isSafeInteger(maxSupply) &&
        maxSupply > 0 &&
        Number.isSafeInteger(confirmedSupply) &&
        Number.isSafeInteger(pendingSupply) &&
        confirmedSupply + pendingSupply + parsed.amount > maxSupply
      ) {
        const ticker =
          String(mintedToken.ticker ?? "credit").trim() || "credit";
        return (
          `${ticker} mint exceeds max supply: ` +
          `${confirmedSupply.toLocaleString("en-US")} confirmed + ` +
          `${pendingSupply.toLocaleString("en-US")} pending + ` +
          `${parsed.amount.toLocaleString("en-US")} requested > ` +
          `${maxSupply.toLocaleString("en-US")} max.`
        );
      }
    }
  }
  return "";
}

function canonicalConfirmedInvalidVerifierItems(
  transactions,
  txid,
  requiredBlockHeight,
  {
    kind,
    network,
    protocol,
    reason,
  },
) {
  const transaction = (Array.isArray(transactions) ? transactions : []).find(
    (candidate) =>
      transactionTxid(candidate) === txid &&
      transactionBlockHeight(candidate) === requiredBlockHeight,
  );
  if (!transaction || !transactionConfirmed(transaction)) {
    return [];
  }
  const blockIndex = transactionBlockIndex(transaction);
  if (!Number.isSafeInteger(blockIndex) || blockIndex < 0) {
    return [];
  }
  let records;
  try {
    records =
      canonicalRawProtocolRecordSetFromTransaction(transaction).records;
  } catch {
    return [];
  }
  return records
    .filter((record) => record?.protocol === protocol)
    .map((record) => ({
      blockHash: transactionBlockHash(transaction),
      blockHeight: requiredBlockHeight,
      blockIndex,
      confirmed: true,
      kind,
      network,
      protocol,
      protocolVout: record.protocolVout,
      reason,
      recordOrdinal: record.recordOrdinal,
      txid,
      valid: false,
    }));
}

async function tokenVerifierPayload(network, tokenScope, txid, options = {}) {
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(normalizedTxid)) {
    const error = new Error("Invalid verifier txid.");
    error.statusCode = 400;
    throw error;
  }
  const requireConfirmed = options.requireConfirmed === true;
  const requiredBlockHeight = Number(options.blockHeight) || 0;
  const requiredBlockHash = String(options.blockHash ?? "").trim().toLowerCase();
  const requiredPreviousBlockHash = String(options.previousBlockHash ?? "")
    .trim()
    .toLowerCase();
  const replayVerifierBinding = requireConfirmed
    ? canonicalPwtReplayVerifierBindingDescriptor(
        options.replayVerifierBinding,
        network,
      )
    : null;
  if (
    requireConfirmed &&
    (!Number.isSafeInteger(requiredBlockHeight) ||
      requiredBlockHeight <= 0 ||
      !/^[0-9a-f]{64}$/u.test(requiredBlockHash) ||
      !/^[0-9a-f]{64}$/u.test(requiredPreviousBlockHash))
  ) {
    const error = new Error(
      "A confirmed verifier request needs an exact height and current/previous block hashes.",
    );
    error.statusCode = 400;
    throw error;
  }
  const scope = String(tokenScope ?? "").trim().toLowerCase() === "all"
    ? ""
    : normalizeTokenScope(tokenScope);
  const provisionalSupplyCapPayload = await pendingWorkMintSupplyCapVerifierPayload(
    network,
    scope,
    normalizedTxid,
    { requireConfirmed },
  ).catch((error) => {
    console.error(
      `Pending WORK supply-cap verifier fell back to ordered replay for ${normalizedTxid}: ${errorSummary(error)}`,
    );
    return null;
  });
  if (provisionalSupplyCapPayload) {
    return provisionalSupplyCapPayload;
  }
  const pendingCoreContext = requireConfirmed
    ? null
    : await pendingCoreWorkMarketplaceVerifierContext(
        network,
        normalizedTxid,
      ).catch((error) => {
        console.error(
          `Pending Core WORK marketplace verifier deferred for ${normalizedTxid}: ${errorSummary(error)}`,
        );
        return null;
      });
  const usePendingCoreWorkState =
    !requireConfirmed &&
    pendingCoreContext?.scope === WORK_TOKEN_ID &&
    (!scope || scope === WORK_TOKEN_ID);
  const confirmedStateScope = scope || `tx:${normalizedTxid}`;
  const replayBindingCacheKey =
    canonicalPwtReplayVerifierBindingCacheKey(
      replayVerifierBinding,
      network,
    );
  const stateKey = requireConfirmed
    ? `token-complete:${network}:${confirmedStateScope}:h${requiredBlockHeight}:${requiredPreviousBlockHash}:${requiredBlockHash}${replayBindingCacheKey}`
    : usePendingCoreWorkState
      ? `token-pending-core:${network}:${WORK_TOKEN_ID}:${normalizedTxid}`
      : `token:${network}:${scope || "all"}`;
  if (requireConfirmed) {
    pruneInternalVerifierStateCache(requiredBlockHeight);
  }
  const stateLoader = () =>
    requireConfirmed
      ? completeTokenVerifierState(
          network,
          scope,
          requiredBlockHeight,
          normalizedTxid,
          requiredBlockHash,
          requiredPreviousBlockHash,
          { replayVerifierBinding },
        )
      : usePendingCoreWorkState
        ? cachedInternalVerifierState(
            `token-indexed-current:${network}:${WORK_TOKEN_ID}`,
            async () => {
              const indexedState = await currentProofIndexTokenPayloadForRead(
                network,
                WORK_TOKEN_ID,
                "pending-core-work-marketplace-verifier",
                10_000,
              );
              if (!indexedState) {
                const error = new Error(
                  "The pending WORK marketplace verifier has no exact-tip indexed base state.",
                );
                error.statusCode = 503;
                error.details = {
                  code: "PENDING_WORK_MARKETPLACE_BASE_UNAVAILABLE",
                  tokenScope: WORK_TOKEN_ID,
                  txid: normalizedTxid,
                };
                throw error;
              }
              return indexedState;
            },
          ).then((baseWorkState) =>
            workTokenStateWithDeltaTransactions(
              baseWorkState,
              [
                ...pendingCoreContext.supportingTransactions,
                pendingCoreContext.targetTransaction,
              ],
              network,
            ),
          )
        : scope === WORK_TOKEN_ID
          ? workTokenPayload(network, null)
          : tokenPayload(network, scope);
  let state = await cachedInternalVerifierState(stateKey, stateLoader);
  if (
    requireConfirmed &&
    (Number(state?.coverageHeight ?? state?.indexedThroughBlock ?? 0) !==
      requiredBlockHeight ||
      String(state?.blockHash ?? "").trim().toLowerCase() !== requiredBlockHash ||
      String(state?.previousBlockHash ?? "").trim().toLowerCase() !==
        requiredPreviousBlockHash)
  ) {
    INTERNAL_VERIFIER_STATE_CACHE.delete(stateKey);
    state = await cachedInternalVerifierState(stateKey, stateLoader);
  }
  if (
    requireConfirmed &&
    (Number(state?.coverageHeight ?? state?.indexedThroughBlock ?? 0) !==
      requiredBlockHeight ||
      String(state?.blockHash ?? "").trim().toLowerCase() !== requiredBlockHash ||
      String(state?.previousBlockHash ?? "").trim().toLowerCase() !==
        requiredPreviousBlockHash)
  ) {
    const error = new Error(
      "The ordered credit verifier has not proven coverage through this block.",
    );
    error.statusCode = 503;
    error.details = {
      code: "TOKEN_VERIFIER_COVERAGE_UNPROVEN",
      coverageHeight: Number(
        state?.coverageHeight ?? state?.indexedThroughBlock ?? 0,
      ) || null,
      requiredBlockHeight,
      tokenScope: scope || "all",
      txid: normalizedTxid,
    };
    throw error;
  }
  const items = tokenVerifierItemsFromState(
    state,
    normalizedTxid,
    { requireConfirmed, requiredBlockHeight },
  ).filter(
    (item) =>
      !requireConfirmed ||
      (item.confirmed === true &&
        Number(item?.blockHeight ?? 0) === requiredBlockHeight),
  );
  if (items.length === 0) {
    const invalidReason = await tokenVerifierDeterministicInvalidReason(
      network,
      state,
      normalizedTxid,
      requireConfirmed,
      {
        exactPendingCoreState: usePendingCoreWorkState,
        transaction: pendingCoreContext?.targetTransaction,
      },
    );
    if (invalidReason) {
      const exactConfirmedItems = requireConfirmed
        ? canonicalConfirmedInvalidVerifierItems(
            state.transactions,
            normalizedTxid,
            requiredBlockHeight,
            {
              kind: "token-event-invalid",
              network,
              protocol: "pwt1",
              reason: invalidReason,
            },
          )
        : [];
      if (exactConfirmedItems.length > 0) {
        items.push(...exactConfirmedItems);
      } else if (
        !requireConfirmed ||
        requiredBlockHeight < WORK_AMO_V5_ACTIVATION_HEIGHT
      ) {
        items.push({
          blockHeight: requiredBlockHeight || null,
          confirmed: requireConfirmed,
          kind: "token-event-invalid",
          network,
          reason: invalidReason,
          txid: normalizedTxid,
          valid: false,
        });
      }
    }
  }
  if (
    items.length === 0 &&
    requireConfirmed &&
    state?.canonicalCoverage === true &&
    (Array.isArray(state.transactions) ? state.transactions : []).some(
      (tx) =>
        transactionTxid(tx) === normalizedTxid &&
        transactionBlockHeight(tx) === requiredBlockHeight &&
        decodedProtocolMessages(tx?.vout ?? [], TOKEN_PROTOCOL_PREFIX).length > 0,
    )
  ) {
    const exactConfirmedItems = canonicalConfirmedInvalidVerifierItems(
      state.transactions,
      normalizedTxid,
      requiredBlockHeight,
      {
        kind: "token-event-invalid",
        network,
        protocol: "pwt1",
        reason: "no-valid-token-event",
      },
    );
    if (exactConfirmedItems.length > 0) {
      items.push(...exactConfirmedItems);
    } else if (requiredBlockHeight < WORK_AMO_V5_ACTIVATION_HEIGHT) {
      items.push({
        blockHeight: requiredBlockHeight,
        confirmed: true,
        kind: "token-event-invalid",
        network,
        reason: "no-valid-token-event",
        txid: normalizedTxid,
        valid: false,
      });
    }
  }
  if (items.length === 0) {
    const error = new Error(
      "The ordered credit verifier has not resolved this transaction.",
    );
    error.statusCode = 503;
    error.details = {
      code: "TOKEN_VERIFIER_UNRESOLVED",
      indexedAt: state?.indexedAt ?? null,
      indexedThroughBlock: state?.indexedThroughBlock ?? null,
      requiredBlockHeight: requiredBlockHeight || null,
      tokenScope: scope || "all",
      txid: normalizedTxid,
    };
    throw error;
  }
  const acceptedTokenIds = [
    ...new Set(
      items
        .filter((item) => item?.valid !== false)
        .map((item) => String(item?.tokenId ?? "").trim().toLowerCase())
        .filter((tokenId) => /^[0-9a-f]{64}$/u.test(tokenId)),
    ),
  ];
  const balanceTokenId = /^[0-9a-f]{64}$/u.test(scope)
    ? scope
    : acceptedTokenIds.length === 1
      ? acceptedTokenIds[0]
      : "";
  let balanceSnapshot = null;
  if (!requireConfirmed && balanceTokenId) {
    const balanceState =
      scope === balanceTokenId ||
      (usePendingCoreWorkState && balanceTokenId === WORK_TOKEN_ID)
        ? state
        : await cachedInternalVerifierState(
            `token:${network}:${balanceTokenId}`,
            () =>
              balanceTokenId === WORK_TOKEN_ID
                ? workTokenPayload(network, null)
                : tokenPayload(network, balanceTokenId),
          );
    balanceSnapshot = verifierBalanceSnapshot(balanceState, balanceTokenId);
  }
  return {
    ...(balanceSnapshot ? { balanceSnapshot } : {}),
    ...(requireConfirmed && state?.workAmoV5BlockTransition
      ? {
          workAmoV5BlockTransition:
            state.workAmoV5BlockTransition,
        }
      : {}),
    ...(requireConfirmed
      ? {
          blockHash: String(state?.blockHash ?? "").trim().toLowerCase(),
          previousBlockHash: String(state?.previousBlockHash ?? "")
            .trim()
            .toLowerCase(),
        }
      : {}),
    indexedAt: state?.indexedAt ?? new Date().toISOString(),
    indexedThroughBlock: state?.indexedThroughBlock ?? null,
    items,
    network,
    source: requireConfirmed
      ? "canonical-block-scan-db-core-credit-verifier"
      : "full-ordered-credit-verifier",
    tokenScope: scope || "all",
    txid: normalizedTxid,
  };
}

async function idVerifierStateBundle(network) {
  const registryAddress = registryAddressForNetwork(network);
  if (!registryAddress) {
    throw new Error("ProofOfWork ID registry is not configured.");
  }
  const transactions = await fetchRegistryTransactions(registryAddress, network);
  return {
    registryAddress,
    state: idRegistryStateFromTransactions(
      transactions,
      registryAddress,
      network,
    ),
    transactions,
  };
}

function idVerifierItemsFromState(state, txid, options = {}) {
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  const activity = (Array.isArray(state?.activity) ? state.activity : []).filter(
    (item) =>
      [
        item?.txid,
        item?.eventTxid,
        item?.listingId,
        item?.sealTxid,
        item?.closedTxid,
        item?.saleTxid,
      ].some(
        (value) =>
          String(value ?? "").trim().toLowerCase() === normalizedTxid,
      ),
  );
  return activity.map((item) => {
    const listingId = String(item?.listingId ?? "").toLowerCase();
    const itemPosition = canonicalVerifierItemPosition(item, {}, options);
    const exactV5Item =
      itemPosition.confirmed === true &&
      Number(itemPosition.blockHeight) >= WORK_AMO_V5_ACTIVATION_HEIGHT;
    const sale =
      String(item?.kind ?? "").trim().toLowerCase() === "id-buy"
        ? (Array.isArray(state?.sales) ? state.sales : []).find((candidate) => {
            if (
              String(candidate?.txid ?? "").toLowerCase() !== normalizedTxid
            ) {
              return false;
            }
            if (!exactV5Item) {
              return true;
            }
            const candidatePosition = canonicalVerifierItemPosition(
              candidate,
              {},
              options,
            );
            const candidateListingId = String(
              candidate?.listingId ?? "",
            ).toLowerCase();
            const candidateId = String(candidate?.id ?? "")
              .trim()
              .toLowerCase();
            const itemId = String(item?.id ?? "").trim().toLowerCase();
            return (
              candidatePosition.confirmed === true &&
              candidatePosition.blockHeight === itemPosition.blockHeight &&
              candidatePosition.blockIndex === itemPosition.blockIndex &&
              candidatePosition.protocolVout === itemPosition.protocolVout &&
              candidatePosition.recordOrdinal === itemPosition.recordOrdinal &&
              (!listingId ||
                !candidateListingId ||
                candidateListingId === listingId) &&
              (!itemId || !candidateId || candidateId === itemId)
            );
          })
        : undefined;
    const listing = [
      ...(Array.isArray(state?.listings) ? state.listings : []),
      ...(Array.isArray(state?.activity) ? state.activity : []).filter(
        (candidate) => candidate?.kind === "id-list",
      ),
    ].find(
      (candidate) =>
        String(candidate?.listingId ?? candidate?.txid ?? "").toLowerCase() ===
        listingId,
    );
    const merged = {
      ...(listing ?? {}),
      ...(sale ?? {}),
      ...item,
      id: item?.id ?? sale?.id ?? listing?.id,
      ownerAddress:
        item?.ownerAddress ?? sale?.buyerAddress ?? sale?.ownerAddress,
      receiveAddress:
        item?.receiveAddress ?? sale?.receiveAddress ?? sale?.buyerAddress,
      sellerAddress: item?.sellerAddress ?? sale?.sellerAddress,
    };
    return {
      ...merged,
      ...canonicalVerifierItemPosition(merged, {}, options),
    };
  });
}

async function idVerifierDeterministicInvalidReason(
  network,
  bundle,
  txid,
  requireConfirmed,
) {
  const tx = requireConfirmed
    ? bundle?.canonicalCoverage === true
      ? (Array.isArray(bundle.transactions) ? bundle.transactions : []).find(
          (candidate) =>
            transactionTxid(candidate) === txid &&
            transactionBlockHeight(candidate) ===
              Number(bundle?.coverageHeight ?? 0),
        )
      : null
    : await fetchTransactionFromBitcoinRpc(txid, network).catch(() => null);
  if (!tx || (requireConfirmed && !transactionConfirmed(tx))) {
    return "";
  }
  const messages = decodedProtocolMessages(tx.vout ?? [], ID_PROTOCOL_PREFIX);
  if (messages.length === 0) {
    return "";
  }
  const parsed = messages.map((message) => parseIdEventPayload(message, network));
  if (parsed.some((item) => !item)) {
    return "Malformed ProofOfWork ID protocol payload.";
  }
  const registryAddress = registryAddressForNetwork(network);
  const requiredPayment = parsed.reduce(
    (total, item) =>
      total +
      (item.kind === "register"
        ? ID_REGISTRATION_PRICE_SATS
        : ID_MUTATION_PRICE_SATS),
    0,
  );
  if (
    !registryAddress ||
    paymentAmountBeforeIdProtocol(tx.vout ?? [], registryAddress) <
      requiredPayment
  ) {
    return "Required ProofOfWork ID registry payment is missing or misplaced.";
  }
  return "";
}

async function idVerifierPayload(network, txid, options = {}) {
  const normalizedTxid = String(txid ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(normalizedTxid)) {
    const error = new Error("Invalid verifier txid.");
    error.statusCode = 400;
    throw error;
  }
  const requireConfirmed = options.requireConfirmed === true;
  const requiredBlockHeight = Number(options.blockHeight) || 0;
  const requiredBlockHash = String(options.blockHash ?? "").trim().toLowerCase();
  const requiredPreviousBlockHash = String(options.previousBlockHash ?? "")
    .trim()
    .toLowerCase();
  if (
    requireConfirmed &&
    (!Number.isSafeInteger(requiredBlockHeight) ||
      requiredBlockHeight <= 0 ||
      !/^[0-9a-f]{64}$/u.test(requiredBlockHash) ||
      !/^[0-9a-f]{64}$/u.test(requiredPreviousBlockHash))
  ) {
    const error = new Error(
      "A confirmed verifier request needs an exact height and current/previous block hashes.",
    );
    error.statusCode = 400;
    throw error;
  }
  const stateKey = requireConfirmed
    ? `id-complete:${network}:h${requiredBlockHeight}:${requiredPreviousBlockHash}:${requiredBlockHash}`
    : `id:${network}`;
  if (requireConfirmed) {
    pruneInternalVerifierStateCache(requiredBlockHeight);
  }
  const stateLoader = () =>
    requireConfirmed
      ? completeIdVerifierStateBundle(
          network,
          requiredBlockHeight,
          requiredBlockHash,
          requiredPreviousBlockHash,
        )
      : idVerifierStateBundle(network);
  let bundle = await cachedInternalVerifierState(stateKey, stateLoader);
  if (
    requireConfirmed &&
    (Number(bundle?.coverageHeight ?? 0) !== requiredBlockHeight ||
      String(bundle?.blockHash ?? "").trim().toLowerCase() !==
        requiredBlockHash ||
      String(bundle?.previousBlockHash ?? "").trim().toLowerCase() !==
        requiredPreviousBlockHash)
  ) {
    INTERNAL_VERIFIER_STATE_CACHE.delete(stateKey);
    bundle = await cachedInternalVerifierState(stateKey, stateLoader);
  }
  if (
    requireConfirmed &&
    (Number(bundle?.coverageHeight ?? 0) !== requiredBlockHeight ||
      String(bundle?.blockHash ?? "").trim().toLowerCase() !==
        requiredBlockHash ||
      String(bundle?.previousBlockHash ?? "").trim().toLowerCase() !==
        requiredPreviousBlockHash)
  ) {
    const error = new Error(
      "The ordered ID verifier has not proven coverage through this block.",
    );
    error.statusCode = 503;
    error.details = {
      code: "ID_VERIFIER_COVERAGE_UNPROVEN",
      coverageHeight: Number(bundle?.coverageHeight ?? 0) || null,
      requiredBlockHeight,
      txid: normalizedTxid,
    };
    throw error;
  }
  const items = idVerifierItemsFromState(
    bundle.state,
    normalizedTxid,
    { requireConfirmed, requiredBlockHeight },
  ).filter(
    (item) =>
      !requireConfirmed ||
      (item.confirmed === true &&
        Number(item?.blockHeight ?? 0) === requiredBlockHeight),
  );
  if (items.length === 0) {
    const invalidReason = await idVerifierDeterministicInvalidReason(
      network,
      bundle,
      normalizedTxid,
      requireConfirmed,
    );
    if (invalidReason) {
      const exactConfirmedItems = requireConfirmed
        ? canonicalConfirmedInvalidVerifierItems(
            bundle.transactions,
            normalizedTxid,
            requiredBlockHeight,
            {
              kind: "id-event-invalid",
              network,
              protocol: "pwid1",
              reason: invalidReason,
            },
          )
        : [];
      if (exactConfirmedItems.length > 0) {
        items.push(...exactConfirmedItems);
      } else if (
        !requireConfirmed ||
        requiredBlockHeight < WORK_AMO_V5_ACTIVATION_HEIGHT
      ) {
        items.push({
          blockHeight: requiredBlockHeight || null,
          confirmed: requireConfirmed,
          kind: "id-event-invalid",
          network,
          reason: invalidReason,
          txid: normalizedTxid,
          valid: false,
        });
      }
    }
  }
  if (
    items.length === 0 &&
    requireConfirmed &&
    bundle?.canonicalCoverage === true &&
    (Array.isArray(bundle.transactions) ? bundle.transactions : []).some(
      (tx) =>
        transactionTxid(tx) === normalizedTxid &&
        transactionBlockHeight(tx) === requiredBlockHeight &&
        decodedProtocolMessages(tx?.vout ?? [], ID_PROTOCOL_PREFIX).length > 0,
    )
  ) {
    const exactConfirmedItems = canonicalConfirmedInvalidVerifierItems(
      bundle.transactions,
      normalizedTxid,
      requiredBlockHeight,
      {
        kind: "id-event-invalid",
        network,
        protocol: "pwid1",
        reason: "no-valid-id-event",
      },
    );
    if (exactConfirmedItems.length > 0) {
      items.push(...exactConfirmedItems);
    } else if (requiredBlockHeight < WORK_AMO_V5_ACTIVATION_HEIGHT) {
      items.push({
        blockHeight: requiredBlockHeight,
        confirmed: true,
        kind: "id-event-invalid",
        network,
        reason: "no-valid-id-event",
        txid: normalizedTxid,
        valid: false,
      });
    }
  }
  if (items.length === 0) {
    const error = new Error("The ID verifier has not resolved this transaction.");
    error.statusCode = 503;
    error.details = {
      code: "ID_VERIFIER_UNRESOLVED",
      requiredBlockHeight: requiredBlockHeight || null,
      txid: normalizedTxid,
    };
    throw error;
  }
  return {
    ...(requireConfirmed
      ? {
          blockHash: String(bundle?.blockHash ?? "").trim().toLowerCase(),
          previousBlockHash: String(bundle?.previousBlockHash ?? "")
            .trim()
            .toLowerCase(),
        }
      : {}),
    indexedAt: new Date().toISOString(),
    indexedThroughBlock: requireConfirmed
      ? Number(bundle.coverageHeight) || null
      : indexedThroughBlockFromTransactions(bundle.transactions) ?? null,
    items,
    network,
    source: requireConfirmed
      ? "canonical-block-scan-db-core-id-verifier"
      : "full-ordered-id-verifier",
    txid: normalizedTxid,
  };
}

function canonicalPwtRangeReplayVerificationIsValid(rebuild, network) {
  const source =
    rebuild && typeof rebuild === "object" && !Array.isArray(rebuild)
      ? rebuild
      : {};
  const verification =
    source.incbRangeReplayVerification &&
    typeof source.incbRangeReplayVerification === "object" &&
    !Array.isArray(source.incbRangeReplayVerification)
      ? source.incbRangeReplayVerification
      : {};
  const verifierBinding = canonicalPwtReplayVerifierBindingDescriptor(
    source.verifierBinding,
    network,
  );
  const rangeReplayFromHeight = Number(source.rangeReplayFromHeight);
  const coreFacts = Array.isArray(verification.coreFacts)
    ? verification.coreFacts
    : [];
  const targets = Array.isArray(verification.targets)
    ? verification.targets
    : [];
  const preservedWitnesses = Array.isArray(verification.preservedWitnesses)
    ? verification.preservedWitnesses
    : [];
  const rederivedWitnesses = Array.isArray(verification.rederivedWitnesses)
    ? verification.rederivedWitnesses
    : [];
  const expectedRederivedWitnessCount = verifierBinding
    ? verifierBinding.witnessCount - verifierBinding.witnessPreserveCount
    : -1;
  if (
    source.network !== network ||
    !Number.isSafeInteger(rangeReplayFromHeight) ||
    rangeReplayFromHeight <= 0 ||
    !verifierBinding ||
    verifierBinding.rangeReplayFromHeight !== rangeReplayFromHeight ||
    verification.verified !== true ||
    verification.accountingModel !== INCEPTION_ISSUANCE_ACCOUNTING_MODEL ||
    Number(verification.rangeReplayFromHeight) !== rangeReplayFromHeight ||
    String(verification.witnessSetHash ?? "").trim().toLowerCase() !==
      verifierBinding.witnessSetHash ||
    Number(verification.witnessCount) !== verifierBinding.witnessCount ||
    Number(verification.witnessPreserveCount) !==
      verifierBinding.witnessPreserveCount ||
    Number(verification.consumedPreserveCount) !==
      verifierBinding.witnessPreserveCount ||
    Number(verification.rederivedWitnessCount) !==
      expectedRederivedWitnessCount ||
    Number(verification.witnessedThroughBlock) !==
      verifierBinding.witnessedThroughBlock ||
    String(verification.witnessedThroughBlockHash ?? "")
      .trim()
      .toLowerCase() !== verifierBinding.witnessedThroughBlockHash ||
    preservedWitnesses.length !== verifierBinding.witnessPreserveCount ||
    preservedWitnesses.length !==
      Number(verification.consumedPreserveCount) ||
    rederivedWitnesses.length !== expectedRederivedWitnessCount ||
    coreFacts.length === 0 ||
    coreFacts.length !== targets.length
  ) {
    return false;
  }

  const preservedIdentities = new Set();
  let priorPreservedIdentity = "";
  for (const item of preservedWitnesses) {
    const txid = String(item?.txid ?? "").trim().toLowerCase();
    const bondRecipientVout = Number(item?.bondRecipientVout);
    const identity = String(item?.identity ?? "").trim().toLowerCase();
    const expectedIdentity = `${txid}:${bondRecipientVout}`;
    const mintPayloadHash = String(item?.mintPayloadHash ?? "")
      .trim()
      .toLowerCase();
    const snapshotId = String(item?.snapshotId ?? "").trim();
    const snapshotFingerprint = String(item?.snapshotFingerprint ?? "")
      .trim()
      .toLowerCase();
    if (
      !/^[0-9a-f]{64}$/u.test(txid) ||
      !Number.isSafeInteger(bondRecipientVout) ||
      bondRecipientVout < 0 ||
      identity !== expectedIdentity ||
      preservedIdentities.has(identity) ||
      (priorPreservedIdentity &&
        compareCanonicalUtf8(
          identity,
          priorPreservedIdentity,
        ) <= 0) ||
      !/^[0-9a-f]{64}$/u.test(mintPayloadHash) ||
      !snapshotId ||
      !/^[0-9a-f]{64}$/u.test(snapshotFingerprint)
    ) {
      return false;
    }
    preservedIdentities.add(identity);
    priorPreservedIdentity = identity;
  }

  const witnessedIdentities = new Set(preservedIdentities);
  let priorRederivedIdentity = "";
  for (const item of rederivedWitnesses) {
    const txid = String(item?.txid ?? "").trim().toLowerCase();
    const bondRecipientVout = Number(item?.bondRecipientVout);
    const identity = String(item?.identity ?? "").trim().toLowerCase();
    const expectedIdentity = `${txid}:${bondRecipientVout}`;
    const disposition = String(item?.disposition ?? "").trim().toLowerCase();
    const mintPayloadHash = String(item?.mintPayloadHash ?? "")
      .trim()
      .toLowerCase();
    const snapshotId = String(item?.snapshotId ?? "").trim();
    const snapshotFingerprint = String(item?.snapshotFingerprint ?? "")
      .trim()
      .toLowerCase();
    const invalidPayloadHash = String(item?.invalidPayloadHash ?? "")
      .trim()
      .toLowerCase();
    const mintDispositionIsValid =
      disposition === "mint" &&
      /^[0-9a-f]{64}$/u.test(mintPayloadHash) &&
      Boolean(snapshotId) &&
      /^[0-9a-f]{64}$/u.test(snapshotFingerprint) &&
      !invalidPayloadHash;
    const invalidDispositionIsValid =
      disposition === "invalid" &&
      /^[0-9a-f]{64}$/u.test(invalidPayloadHash) &&
      !mintPayloadHash &&
      !snapshotId &&
      !snapshotFingerprint;
    if (
      !/^[0-9a-f]{64}$/u.test(txid) ||
      !Number.isSafeInteger(bondRecipientVout) ||
      bondRecipientVout < 0 ||
      identity !== expectedIdentity ||
      witnessedIdentities.has(identity) ||
      (priorRederivedIdentity &&
        compareCanonicalUtf8(
          identity,
          priorRederivedIdentity,
        ) <= 0) ||
      (!mintDispositionIsValid && !invalidDispositionIsValid)
    ) {
      return false;
    }
    witnessedIdentities.add(identity);
    priorRederivedIdentity = identity;
  }
  if (witnessedIdentities.size !== verifierBinding.witnessCount) {
    return false;
  }

  const positiveIntegerText = (value) => {
    const text = String(value ?? "").trim();
    return /^[1-9][0-9]*$/u.test(text) ? BigInt(text).toString() : "";
  };
  const coreByTxid = new Map();
  for (const item of coreFacts) {
    const txid = String(item?.txid ?? "").trim().toLowerCase();
    const blockHash = String(item?.blockHash ?? "").trim().toLowerCase();
    const blockHeight = Number(item?.blockHeight);
    const blockIndex = Number(item?.blockIndex);
    const workAmountAtoms = positiveIntegerText(item?.workAmountAtoms);
    if (
      !/^[0-9a-f]{64}$/u.test(txid) ||
      !/^[0-9a-f]{64}$/u.test(blockHash) ||
      !Number.isSafeInteger(blockHeight) ||
      blockHeight < rangeReplayFromHeight ||
      !Number.isSafeInteger(blockIndex) ||
      blockIndex < 0 ||
      !workAmountAtoms ||
      coreByTxid.has(txid)
    ) {
      return false;
    }
    coreByTxid.set(txid, {
      blockHash,
      blockHeight,
      blockIndex,
      workAmountAtoms,
    });
  }

  const targetTxids = new Set();
  for (const item of targets) {
    const txid = String(item?.txid ?? "").trim().toLowerCase();
    const workAmountAtoms = positiveIntegerText(item?.workAmountAtoms);
    const confirmedIssuanceUnits = positiveIntegerText(
      item?.confirmedIssuanceUnits,
    );
    const issuanceNetworkValueQ8 = positiveIntegerText(
      item?.issuanceNetworkValueQ8,
    );
    if (
      !coreByTxid.has(txid) ||
      targetTxids.has(txid) ||
      !workAmountAtoms ||
      coreByTxid.get(txid).workAmountAtoms !== workAmountAtoms ||
      !confirmedIssuanceUnits ||
      !issuanceNetworkValueQ8 ||
      BigInt(issuanceNetworkValueQ8) / BOND_VALUE_Q8_SCALE !==
        BigInt(confirmedIssuanceUnits)
    ) {
      return false;
    }
    targetTxids.add(txid);
  }
  if (
    rangeReplayFromHeight !== CANONICAL_INCB_PWT_RANGE_REPLAY_FROM_HEIGHT ||
    targetTxids.size !== coreByTxid.size ||
    targetTxids.size !== CANONICAL_INCB_PWT_RANGE_REPLAY_TARGETS.length
  ) {
    return false;
  }
  return CANONICAL_INCB_PWT_RANGE_REPLAY_TARGETS.every((expected) => {
    const core = coreByTxid.get(expected.txid);
    return (
      targetTxids.has(expected.txid) &&
      core?.blockHash === expected.blockHash &&
      core?.blockHeight === expected.blockHeight &&
      core?.blockIndex === expected.blockIndex &&
      core?.workAmountAtoms === expected.workAmountAtoms
    );
  });
}

function canonicalInternalPwtRangeReplayState(rebuild, network) {
  const source =
    rebuild && typeof rebuild === "object" && !Array.isArray(rebuild)
      ? rebuild
      : {};
  if (source.mode !== "pwt-range-replay") {
    return null;
  }
  const commonStateIsValid =
    source.network === network &&
    Number.isSafeInteger(Number(source.rangeReplayFromHeight)) &&
    Number(source.rangeReplayFromHeight) > 0;
  if (
    commonStateIsValid &&
    source.status === "active" &&
    source.active === true &&
    source.complete === false &&
    source.completedAt == null &&
    source.incbRangeReplayVerification == null &&
    canonicalPwtReplayVerifierBindingDescriptor(
      source.verifierBinding,
      network,
    )
  ) {
    return "active";
  }
  if (
    commonStateIsValid &&
    source.status === "complete" &&
    source.active === false &&
    source.complete === true &&
    String(source.completedAt ?? "").trim().length > 0 &&
    Number.isFinite(Date.parse(String(source.completedAt).trim())) &&
    canonicalPwtRangeReplayVerificationIsValid(source, network)
  ) {
    return "complete";
  }
  return "invalid";
}

function canonicalRebuildTrustState(rebuild, network) {
  const source =
    rebuild && typeof rebuild === "object" && !Array.isArray(rebuild)
      ? rebuild
      : {};
  const rangeReplayState = canonicalInternalPwtRangeReplayState(
    source,
    network,
  );
  if (rangeReplayState !== null) {
    return rangeReplayState;
  }
  if (
    source.network === network &&
    source.status === "active" &&
    source.active === true &&
    source.complete === false
  ) {
    return "active";
  }
  if (
    source.network === network &&
    source.status === "complete" &&
    source.active === false &&
    source.complete === true
  ) {
    return "complete";
  }
  return "invalid";
}

function canonicalInternalReplayVerifierBinding(rebuild, network) {
  const source =
    rebuild && typeof rebuild === "object" && !Array.isArray(rebuild)
      ? rebuild
      : {};
  const replayState = canonicalInternalPwtRangeReplayState(source, network);
  if (!replayState || replayState === "invalid") {
    return null;
  }
  const candidate =
    source.verifierBinding &&
    typeof source.verifierBinding === "object" &&
    !Array.isArray(source.verifierBinding)
      ? source.verifierBinding
      : {};
  const binding = canonicalPwtReplayVerifierBindingDescriptor(
    candidate,
    network,
  );
  if (
    !binding ||
    binding.rangeReplayFromHeight !== Number(source.rangeReplayFromHeight)
  ) {
    return null;
  }
  return binding;
}

function internalReplayVerifierBindingError(message, details = {}) {
  const error = new Error(message);
  error.statusCode = 503;
  error.details = {
    code: "PWT_RANGE_REPLAY_DATABASE_BINDING_MISMATCH",
    ...details,
  };
  return error;
}

async function internalReplayVerifierBinding(network, requestedBindingId = "") {
  const requested = String(requestedBindingId ?? "").trim().toLowerCase();
  const canonical = await proofIndexCanonicalStateMetaPayload(network);
  const rebuild = canonical?.rebuild ?? null;
  const replayState = canonicalInternalPwtRangeReplayState(rebuild, network);
  if (replayState === "invalid") {
    throw internalReplayVerifierBindingError(
      "PWT range replay metadata is malformed; internal verifier access is disabled.",
    );
  }
  const binding = canonicalInternalReplayVerifierBinding(rebuild, network);
  const replayActive = replayState === "active";
  const replayComplete = replayState === "complete";
  if (requested) {
    if (!/^[0-9a-f]{64}$/u.test(requested) || !binding) {
      throw internalReplayVerifierBindingError(
        "The internal verifier is not connected to the requested replay database.",
        { requestedBindingId: requested || null },
      );
    }
    const expectedBytes = Buffer.from(binding.bindingId, "hex");
    const requestedBytes = Buffer.from(requested, "hex");
    if (
      expectedBytes.length !== requestedBytes.length ||
      !timingSafeEqual(expectedBytes, requestedBytes)
    ) {
      throw internalReplayVerifierBindingError(
        "The internal verifier is connected to a different replay database.",
        { requestedBindingId: requested },
      );
    }
    return binding;
  }
  if (replayActive) {
    throw internalReplayVerifierBindingError(
      "Active PWT range replay requires its database binding on every internal verifier request.",
      { requiredBindingId: binding?.bindingId ?? null },
    );
  }
  return replayComplete ? binding : null;
}

async function internalReplayBoundPayload(
  network,
  requestedBindingId,
  payload,
  initialBinding,
) {
  const confirmedBinding = await internalReplayVerifierBinding(
    network,
    requestedBindingId,
  );
  const bindingChanged =
    Boolean(initialBinding) !== Boolean(confirmedBinding) ||
    (initialBinding &&
      !canonicalPwtReplayVerifierBindingsEqual(
        initialBinding,
        confirmedBinding,
      ));
  if (bindingChanged) {
    throw internalReplayVerifierBindingError(
      "The replay database binding changed while the internal verifier response was being built.",
    );
  }
  return confirmedBinding
    ? { ...payload, replayVerifierBinding: confirmedBinding }
    : payload;
}

function internalVerifierRequestAllowed(request) {
  const hostHeader = String(request.headers.host ?? "").toLowerCase();
  const closingBracket = hostHeader.indexOf("]");
  const requestHost = hostHeader.startsWith("[") && closingBracket > 1
    ? hostHeader.slice(1, closingBracket)
    : hostHeader.split(":")[0];
  const remoteAddress = String(request.socket.remoteAddress ?? "").toLowerCase();
  const presentedToken = String(
    request.headers["x-pow-internal-verifier"] ?? "",
  ).trim();
  const expectedBytes = Buffer.from(INTERNAL_VERIFIER_TOKEN);
  const presentedBytes = Buffer.from(presentedToken);
  const tokenMatches =
    expectedBytes.length >= 32 &&
    expectedBytes.length === presentedBytes.length &&
    timingSafeEqual(expectedBytes, presentedBytes);
  return (
    tokenMatches &&
    ["127.0.0.1", "::1", "::ffff:127.0.0.1"].includes(remoteAddress) &&
    ["127.0.0.1", "localhost", "::1"].includes(requestHost)
  );
}

function txidSetSha256(txids) {
  return createHash("sha256")
    .update(
      [...txids]
        .map((txid) => String(txid).toLowerCase())
        .sort(compareCanonicalUtf8)
        .join("\n"),
      "utf8",
    )
    .digest("hex");
}

function registryAuditTransactionTouchesAddress(transaction, address) {
  return (
    (Array.isArray(transaction?.vout) ? transaction.vout : []).some(
      (output) => output?.scriptpubkey_address === address,
    ) ||
    (Array.isArray(transaction?.vin) ? transaction.vin : []).some(
      (input) => input?.prevout?.scriptpubkey_address === address,
    )
  );
}

function registryAuditCanonicalJson(value) {
  if (value === null || typeof value === "string" || typeof value === "boolean") {
    return JSON.stringify(value);
  }
  if (typeof value === "number") {
    if (!Number.isSafeInteger(value)) {
      throw new Error("ID registry audit projection contains an inexact number.");
    }
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(registryAuditCanonicalJson).join(",")}]`;
  }
  if (value && typeof value === "object") {
    return `{${Object.keys(value)
      .filter((key) => value[key] !== undefined)
      .sort(compareCanonicalUtf8)
      .map(
        (key) =>
          `${JSON.stringify(key)}:${registryAuditCanonicalJson(value[key])}`,
      )
      .join(",")}}`;
  }
  throw new Error("ID registry audit projection contains an unsupported value.");
}

function registryAuditProjectionSha256(value) {
  return createHash("sha256")
    .update(registryAuditCanonicalJson(value), "utf8")
    .digest("hex");
}

function registryAuditProjectionPreview(value) {
  const text = registryAuditCanonicalJson(value);
  return text.length > 240 ? `${text.slice(0, 240)}...` : text;
}

function registryAuditProjectionSectionSummary(projection) {
  const source =
    projection && typeof projection === "object" && !Array.isArray(projection)
      ? projection
      : {};
  return [
    "confirmedRecords",
    "events",
    "listings",
    "pendingEvents",
    "pendingRecords",
    "sales",
  ].reduce((summary, key) => {
    const value = Array.isArray(source[key]) ? source[key] : [];
    summary[key] = {
      count: value.length,
      sha256: registryAuditProjectionSha256(value),
    };
    return summary;
  }, {});
}

function registryAuditFirstProjectionDiff(left, right, path = "$") {
  const leftArray = Array.isArray(left);
  const rightArray = Array.isArray(right);
  if (leftArray || rightArray) {
    if (!leftArray || !rightArray) {
      return {
        path,
        chain: registryAuditProjectionPreview(left),
        relational: registryAuditProjectionPreview(right),
      };
    }
    const length = Math.min(left.length, right.length);
    for (let index = 0; index < length; index += 1) {
      const diff = registryAuditFirstProjectionDiff(
        left[index],
        right[index],
        `${path}[${index}]`,
      );
      if (diff) {
        return diff;
      }
    }
    if (left.length !== right.length) {
      return {
        path: `${path}.length`,
        chain: String(left.length),
        relational: String(right.length),
      };
    }
    return null;
  }
  const leftObject = left && typeof left === "object";
  const rightObject = right && typeof right === "object";
  if (leftObject || rightObject) {
    if (!leftObject || !rightObject) {
      return {
        path,
        chain: registryAuditProjectionPreview(left),
        relational: registryAuditProjectionPreview(right),
      };
    }
    const keys = [...new Set([
      ...Object.keys(left).filter((key) => left[key] !== undefined),
      ...Object.keys(right).filter((key) => right[key] !== undefined),
    ])].sort(compareCanonicalUtf8);
    for (const key of keys) {
      if (
        (left[key] === undefined) !==
        (right[key] === undefined)
      ) {
        return {
          path: `${path}.${key}`,
          chain: registryAuditProjectionPreview(left[key]),
          relational: registryAuditProjectionPreview(right[key]),
        };
      }
      const diff = registryAuditFirstProjectionDiff(
        left[key],
        right[key],
        `${path}.${key}`,
      );
      if (diff) {
        return diff;
      }
    }
    return null;
  }
  if (Object.is(left, right)) {
    return null;
  }
  return {
    path,
    chain: registryAuditProjectionPreview(left),
    relational: registryAuditProjectionPreview(right),
  };
}

function registryAuditTxid(value, label) {
  const txid = String(value ?? "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/u.test(txid)) {
    throw new Error(`${label} has no exact transaction identity.`);
  }
  return txid;
}

function registryAuditId(value, label) {
  const id = String(value ?? "").trim().toLowerCase();
  if (!id) {
    throw new Error(`${label} has no exact ProofOfWork ID identity.`);
  }
  return id;
}

function registryAuditAddress(value, label) {
  const address = String(value ?? "").trim();
  if (!address || !isValidBitcoinAddress(address, "livenet")) {
    throw new Error(`${label} has no exact address identity.`);
  }
  return address;
}

function registryAuditPendingEventEntry(event) {
  const txid = registryAuditTxid(event?.txid, "Pending ID mutation");
  const kind = String(event?.kind ?? "").trim();
  const id = String(event?.id ?? "").trim().toLowerCase();
  const listingId = String(event?.listingId ?? "").trim().toLowerCase();
  const allowedKinds = new Set([
    "delist",
    "list",
    "marketTransfer",
    "seal",
    "transfer",
    "update",
  ]);
  if (!allowedKinds.has(kind) || !id) {
    throw new Error(`Pending ID mutation ${txid} has no exact semantic identity.`);
  }
  if (listingId && !/^[0-9a-f]{64}$/u.test(listingId)) {
    throw new Error(`Pending ID mutation ${txid} has an invalid listing identity.`);
  }
  const priceSats = event?.priceSats;
  if (
    priceSats !== undefined &&
    (!Number.isSafeInteger(Number(priceSats)) || Number(priceSats) < 0)
  ) {
    throw new Error(`Pending ID mutation ${txid} has an inexact price.`);
  }
  const addresses = {
    buyerAddress: String(event?.buyerAddress ?? ""),
    currentOwnerAddress: String(event?.currentOwnerAddress ?? ""),
    currentReceiveAddress: String(event?.currentReceiveAddress ?? ""),
    ownerAddress: String(event?.ownerAddress ?? ""),
    receiveAddress: String(event?.receiveAddress ?? ""),
    sellerAddress: String(event?.sellerAddress ?? ""),
  };
  if (
    Object.values(addresses).some(
      (address) => address && !isValidBitcoinAddress(address, "livenet"),
    )
  ) {
    throw new Error(`Pending ID mutation ${txid} has an invalid address identity.`);
  }
  return {
    ...addresses,
    id,
    kind,
    listingId,
    priceSats: priceSats === undefined ? null : Number(priceSats),
    transferVersion: String(event?.transferVersion ?? ""),
    txid,
  };
}

function registryAuditCanonicalClone(value) {
  return JSON.parse(registryAuditCanonicalJson(value));
}

function registryAuditInteger(value, label, minimum = 0) {
  const integer = Number(value);
  if (!Number.isSafeInteger(integer) || integer < minimum) {
    throw new Error(`${label} is not an exact integer.`);
  }
  return integer;
}

function registryAuditOptionalAddress(value, label) {
  const address = String(value ?? "").trim();
  if (address && !isValidBitcoinAddress(address, "livenet")) {
    throw new Error(`${label} has an invalid address.`);
  }
  return address;
}

function registryAuditEventKind(value) {
  const kind = String(value ?? "").trim();
  const aliases = {
    delist: "id-delist",
    list: "id-list",
    marketTransfer: "id-buy",
    register: "id-register",
    seal: "id-seal",
    transfer: "id-transfer",
    update: "id-update",
  };
  const normalized = aliases[kind] ?? kind.toLowerCase();
  if (
    ![
      "id-buy",
      "id-delist",
      "id-list",
      "id-register",
      "id-seal",
      "id-transfer",
      "id-update",
    ].includes(normalized)
  ) {
    throw new Error(`Unsupported ID registry event kind ${kind || "(empty)"}.`);
  }
  return normalized;
}

function registryAuditPaymentOutputs(item, label) {
  const values = Array.isArray(item?.auditPaymentOutputs)
    ? item.auditPaymentOutputs
    : Array.isArray(item?.paymentOutputs)
      ? item.paymentOutputs
      : Array.isArray(item?.recipients)
        ? item.recipients
        : [];
  return values
    .map((output, index) => ({
      address: registryAuditOptionalAddress(
        output?.address,
        `${label} payment output`,
      ),
      amountSats: registryAuditInteger(
        output?.amountSats,
        `${label} payment amount`,
        1,
      ),
      vout: registryAuditInteger(
        output?.vout ?? index,
        `${label} payment vout`,
      ),
    }))
    .sort(
      (left, right) =>
        left.vout - right.vout ||
        compareCanonicalUtf8(left.address, right.address),
    );
}

function registryAuditLifecycleEventEntry(item, checkpoint, source) {
  const kind = registryAuditEventKind(item?.kind);
  const txid = registryAuditTxid(item?.txid, `${source} ${kind}`);
  const confirmed = item?.confirmed === true;
  const expectedFee = kind === "id-register" ? 1_000 : 546;
  const blockHash = confirmed
    ? registryAuditTxid(item?.blockHash, `${source} ${kind} block`)
    : "";
  const blockHeight = confirmed
    ? registryAuditInteger(
        item?.blockHeight,
        `${source} ${kind} block height`,
        1,
      )
    : 0;
  const blockIndex = confirmed
    ? registryAuditInteger(item?.blockIndex, `${source} ${kind} block index`)
    : 0;
  if (blockHeight > checkpoint.height) {
    throw new Error(`${source} ${kind} is above the exact Core checkpoint.`);
  }
  const protocolVout = registryAuditInteger(
    item?.protocolVout,
    `${source} ${kind} protocol vout`,
  );
  const recordOrdinal = registryAuditInteger(
    item?.recordOrdinal ?? 0,
    `${source} ${kind} record ordinal`,
  );
  const createdAt = new Date(item?.createdAt ?? item?.blockTime ?? item?.timestamp)
    .toISOString();
  if (!Number.isFinite(Date.parse(createdAt))) {
    throw new Error(`${source} ${kind} has no exact event time.`);
  }
  const payments = registryAuditPaymentOutputs(item, `${source} ${kind}`);
  const registryPaymentSats = payments.reduce(
    (total, output) =>
      total + (output.address === registryAddressForNetwork("livenet")
        ? output.amountSats
        : 0),
    0,
  );
  if (registryPaymentSats < expectedFee) {
    throw new Error(`${source} ${kind} has insufficient registry payment.`);
  }
  const recordedAmountSats = registryAuditInteger(
    item?.amountSats,
    `${source} ${kind} attributed registry fee`,
    1,
  );
  if (
    (source === "relational" && recordedAmountSats !== expectedFee) ||
    (source !== "relational" && recordedAmountSats < expectedFee)
  ) {
    throw new Error(`${source} ${kind} has an inexact attributed registry fee.`);
  }
  const protocolPayload = String(
    item?.protocolPayload ?? item?.payload ?? "",
  );
  if (!protocolPayload.startsWith(ID_PROTOCOL_PREFIX)) {
    throw new Error(`${source} ${kind} has no exact raw protocol payload.`);
  }
  const saleAuthorization = item?.saleAuthorization
    ? registryAuditCanonicalClone(item.saleAuthorization)
    : null;
  const firstAddressCandidate = (...values) =>
    values
      .map((value) => String(value ?? "").trim())
      .find(Boolean) ?? "";
  const transferVersion = String(item?.transferVersion ?? "");
  const legacyUnanchoredBuy =
    kind === "id-buy" && transferVersion.toLowerCase() === "buy2";
  const addresses = {
    buyerAddress: registryAuditOptionalAddress(
      kind === "id-buy"
        ? firstAddressCandidate(
            item?.buyerAddress,
            item?.ownerAddress,
            item?.actor,
            saleAuthorization?.buyerAddress,
          )
        : (item?.buyerAddress ?? saleAuthorization?.buyerAddress),
      `${source} ${kind} buyer`,
    ),
    ownerAddress: registryAuditOptionalAddress(
      kind === "id-update" ? "" : item?.ownerAddress,
      `${source} ${kind} owner`,
    ),
    receiveAddress: registryAuditOptionalAddress(
      item?.receiveAddress ?? saleAuthorization?.receiveAddress,
      `${source} ${kind} receiver`,
    ),
    sellerAddress: registryAuditOptionalAddress(
      item?.sellerAddress ?? saleAuthorization?.sellerAddress,
      `${source} ${kind} seller`,
    ),
    senderAddress: registryAuditOptionalAddress(
      item?.senderAddress ?? item?.actor ?? item?.inputAddresses?.[0],
      `${source} ${kind} sender`,
    ),
  };
  const participants = [...new Set([
    ...(Array.isArray(item?.inputAddresses) ? item.inputAddresses : []),
    ...(Array.isArray(item?.participants) ? item.participants : []),
    ...payments.map((output) => output.address),
    ...Object.values(addresses),
    saleAuthorization?.buyerAddress,
    saleAuthorization?.receiveAddress,
    saleAuthorization?.sellerAddress,
  ].filter(Boolean))]
    .map((address) =>
      registryAuditOptionalAddress(address, `${source} ${kind} participant`),
    )
    .sort(compareCanonicalUtf8);
  const listingIdCandidate = String(
    legacyUnanchoredBuy
      ? ""
      : (item?.listingId ?? (kind === "id-list" ? txid : "")),
  )
    .trim()
    .toLowerCase();
  const listingId = listingIdCandidate
    ? registryAuditTxid(listingIdCandidate, `${source} ${kind} listing`)
    : "";
  const id = String(item?.id ?? "").trim().toLowerCase();
  if (
    ["id-buy", "id-list", "id-register", "id-transfer", "id-update"].includes(kind) &&
    !id
  ) {
    throw new Error(`${source} ${kind} has no exact ID.`);
  }
  const dataBytes = registryAuditInteger(
    item?.protocolDataBytes ?? item?.dataBytes,
    `${source} ${kind} protocol bytes`,
    1,
  );
  if (Buffer.byteLength(protocolPayload, "utf8") !== dataBytes) {
    throw new Error(`${source} ${kind} raw protocol byte count diverges.`);
  }
  const priceSats = item?.priceSats === undefined
    ? null
    : registryAuditInteger(item.priceSats, `${source} ${kind} price`);
  return {
    ...addresses,
    amountSats: expectedFee,
    blockHash,
    blockHeight,
    blockIndex,
    confirmed,
    createdAt,
    dataBytes,
    id,
    kind,
    listingId,
    listingVersion: legacyUnanchoredBuy
      ? ""
      : String(item?.listingVersion ?? ""),
    participants,
    paymentOutputs: payments,
    pgpKey: String(item?.pgpKey ?? item?.pgpPublicKey ?? ""),
    priceSats,
    protocolVout,
    protocolPayloadSha256: createHash("sha256")
      .update(protocolPayload, "utf8")
      .digest("hex"),
    recordOrdinal,
    registryPaymentSats,
    saleAuthorization,
    transferVersion: String(item?.transferVersion ?? ""),
    txid,
  };
}

const REGISTRY_AUDIT_LISTING_FIELDS = [
  "anchorSigHashType",
  "anchorSignature",
  "anchorScriptPubKey",
  "anchorTxid",
  "anchorType",
  "anchorValueSats",
  "anchorVout",
  "blockHash",
  "blockHeight",
  "blockIndex",
  "buyerAddress",
  "confirmed",
  "createdAt",
  "expiresAt",
  "id",
  "listingId",
  "listingVersion",
  "priceSats",
  "protocolVout",
  "receiveAddress",
  "recordOrdinal",
  "saleAuthorization",
  "sealTxid",
  "sellerAddress",
  "sellerPublicKey",
  "txid",
];

const REGISTRY_AUDIT_SALE_FIELDS = [
  "blockHash",
  "blockHeight",
  "blockIndex",
  "buyerAddress",
  "confirmed",
  "createdAt",
  "id",
  "listingId",
  "priceSats",
  "protocolVout",
  "receiveAddress",
  "recordOrdinal",
  "sellerAddress",
  "transferVersion",
  "txid",
];

function registryAuditStateItemEntry(item, fields, label) {
  const result = {};
  for (const field of fields) {
    let value = item?.[field];
    if (value === undefined && field === "listingId") {
      value = item?.txid;
    }
    if (value === undefined) {
      value = null;
    }
    result[field] = registryAuditCanonicalClone(value);
  }
  const txid = registryAuditTxid(result.txid, `${label} txid`);
  result.txid = txid;
  if (result.listingId) {
    result.listingId = registryAuditTxid(result.listingId, `${label} listing`);
  }
  for (const addressField of [
    "buyerAddress",
    "receiveAddress",
    "sellerAddress",
  ]) {
    if (result[addressField]) {
      result[addressField] = registryAuditOptionalAddress(
        result[addressField],
        `${label} ${addressField}`,
      );
    }
  }
  return result;
}

function registryAuditProjection(payload, checkpoint) {
  if (
    !payload ||
    payload.network !== "livenet" ||
    Number(payload.indexedThroughBlock) !== checkpoint.height ||
    String(payload.indexedThroughBlockHash ?? "").trim().toLowerCase() !==
      checkpoint.blockHash
  ) {
    throw new Error(
      "The relational ID registry projection is not bound to the exact Core tip.",
    );
  }

  const records = Array.isArray(payload.records) ? payload.records : [];
  const confirmedRecords = records
    .filter((record) => record?.confirmed === true)
    .map((record) => {
      const id = registryAuditId(record.id, "Confirmed ID record");
      const blockHeight = Number(record.blockHeight);
      const blockIndex = Number(record.blockIndex);
      if (
        !Number.isSafeInteger(blockHeight) ||
        blockHeight < 1 ||
        !Number.isSafeInteger(blockIndex) ||
        blockIndex < 0
      ) {
        throw new Error(`Confirmed ID record ${id} has no exact block position.`);
      }
      const updatedHeight = Number(record.updatedHeight);
      if (
        !Number.isSafeInteger(updatedHeight) ||
        updatedHeight < blockHeight ||
        updatedHeight > checkpoint.height
      ) {
        throw new Error(`Confirmed ID record ${id} has no exact update height.`);
      }
      return {
        blockHeight,
        blockIndex,
        id,
        lastEventTxid: registryAuditTxid(
          record.lastEventTxid,
          `Confirmed ID record ${id} last event`,
        ),
        ownerAddress: registryAuditAddress(
          record.ownerAddress,
          `Confirmed ID record ${id}`,
        ),
        pgpKey: String(record.pgpKey ?? ""),
        receiveAddress: registryAuditAddress(
          record.receiveAddress,
          `Confirmed ID record ${id}`,
        ),
        txid: registryAuditTxid(record.txid, `Confirmed ID record ${id}`),
        updatedHeight,
      };
    })
    .sort(
      (left, right) =>
        compareCanonicalUtf8(left.id, right.id) ||
        compareCanonicalUtf8(left.txid, right.txid),
    );
  const pendingRecords = records
    .filter((record) => record?.confirmed !== true)
    .map((record) => {
      const id = registryAuditId(record.id, "Pending ID record");
      return {
        id,
        ownerAddress: registryAuditAddress(
          record.ownerAddress,
          `Pending ID record ${id}`,
        ),
        pgpKey: String(record.pgpKey ?? ""),
        receiveAddress: registryAuditAddress(
          record.receiveAddress,
          `Pending ID record ${id}`,
        ),
        txid: registryAuditTxid(record.txid, `Pending ID record ${id}`),
      };
    })
    .sort(
      (left, right) =>
        compareCanonicalUtf8(left.id, right.id) ||
        compareCanonicalUtf8(left.txid, right.txid),
    );
  const pendingEvents = (Array.isArray(payload.pendingEvents)
    ? payload.pendingEvents
    : []
  )
    .map(registryAuditPendingEventEntry)
    .sort(
      (left, right) =>
        compareCanonicalUtf8(left.txid, right.txid) ||
        compareCanonicalUtf8(left.kind, right.kind) ||
        compareCanonicalUtf8(left.id, right.id) ||
        compareCanonicalUtf8(left.listingId, right.listingId),
    );
  const events = (Array.isArray(payload.activity) ? payload.activity : [])
    .filter((item) => item?.confirmed === true)
    .map((item) =>
      registryAuditLifecycleEventEntry(item, checkpoint, "relational"),
    )
    .sort(
      (left, right) =>
        left.blockHeight - right.blockHeight ||
        left.blockIndex - right.blockIndex ||
        left.protocolVout - right.protocolVout ||
        left.recordOrdinal - right.recordOrdinal ||
        compareCanonicalUtf8(left.txid, right.txid) ||
        compareCanonicalUtf8(left.kind, right.kind),
    );
  const listings = (Array.isArray(payload.listings) ? payload.listings : [])
    .map((item) =>
      registryAuditStateItemEntry(
        item,
        REGISTRY_AUDIT_LISTING_FIELDS,
        "Relational ID listing",
      ),
    )
    .sort(
      (left, right) =>
        compareCanonicalUtf8(left.listingId, right.listingId) ||
        compareCanonicalUtf8(left.txid, right.txid),
    );
  const sales = (Array.isArray(payload.sales) ? payload.sales : [])
    .map((item) =>
      registryAuditStateItemEntry(
        item,
        REGISTRY_AUDIT_SALE_FIELDS,
        "Relational ID sale",
      ),
    )
    .sort(
      (left, right) =>
        compareCanonicalUtf8(left.txid, right.txid) ||
        compareCanonicalUtf8(String(left.listingId ?? ""), String(right.listingId ?? "")),
    );

  for (const [label, entries] of [
    ["confirmed record", confirmedRecords],
    ["pending record", pendingRecords],
  ]) {
    const ids = entries.map((entry) => entry.id);
    if (new Set(ids).size !== ids.length) {
      throw new Error(`The relational registry repeats a ${label} identity.`);
    }
  }

  const confirmed = Number(payload?.stats?.confirmed);
  const pendingRecordCount = Number(payload?.stats?.pendingRecords);
  const pendingChangeCount = Number(payload?.stats?.pendingChanges);
  if (
    !Number.isSafeInteger(confirmed) ||
    confirmed < 1 ||
    confirmed !== confirmedRecords.length ||
    !Number.isSafeInteger(pendingRecordCount) ||
    pendingRecordCount !== pendingRecords.length ||
    !Number.isSafeInteger(pendingChangeCount) ||
    pendingChangeCount !== pendingEvents.length
  ) {
    throw new Error(
      "The exact relational ID registry projection has inconsistent statistics.",
    );
  }

  const projection = {
    checkpoint: {
      blockHash: checkpoint.blockHash,
      height: checkpoint.height,
    },
    confirmedRecords,
    events,
    listings,
    pendingEvents,
    pendingRecords,
    sales,
  };
  return {
    ...projection,
    projectionSha256: registryAuditProjectionSha256(projection),
  };
}

async function hydrateExactPendingRegistryTransaction(txid, network) {
  const transaction = await fetchTransactionFromBitcoinRpc(txid, network, {
    bypassCache: true,
    cacheResult: false,
    requireCanonicalPrevouts: true,
  });
  const mempoolEntry = await bitcoinRpc("getmempoolentry", [txid]);
  const mempoolTime = Number(mempoolEntry?.result?.time);
  if (
    !transaction ||
    transactionTxid(transaction) !== txid ||
    transactionConfirmed(transaction) ||
    !transactionHasCompleteCanonicalPrevouts(transaction) ||
    !mempoolEntry?.ok ||
    !mempoolEntry.result ||
    typeof mempoolEntry.result !== "object" ||
    !Number.isSafeInteger(mempoolTime) ||
    mempoolTime < 1 ||
    !registryAuditTransactionTouchesAddress(transaction, registryAddressForNetwork(network))
  ) {
    throw new Error(
      `Bitcoin Core did not prove pending registry transaction ${txid}.`,
    );
  }

  return {
    ...transaction,
    status: {
      ...(transaction.status ?? {}),
      confirmed: false,
      mempool_time: mempoolTime,
    },
  };
}

async function hydrateExactConfirmedRegistryHistory(
  entries,
  network,
  options = {},
) {
  const confirmedEntries = (Array.isArray(entries) ? entries : []).filter(
    (entry) =>
      Number(entry?.height) > 0 &&
      (options.allHeights === true ||
        Number(entry?.height) < PWID_RAW_REPLAY_ACTIVATION_HEIGHT),
  );
  const byHeight = new Map();
  for (const entry of confirmedEntries) {
    const group = byHeight.get(entry.height) ?? [];
    group.push(entry);
    byHeight.set(entry.height, group);
  }
  const groups = [...byHeight.entries()].sort(
    (left, right) => left[0] - right[0],
  );
  const hydratedGroups = await mapWithConcurrency(
    groups,
    2,
    async ([height, group]) => {
      const block = await fetchCanonicalAddressHistoryBlock(height, network);
      const indexByTxid = new Map(
        block.txids.map((txid, blockIndex) => [txid, blockIndex]),
      );
      return mapWithConcurrency(
        group,
        Math.min(4, Math.max(1, TX_FETCH_CONCURRENCY)),
        async (entry) => {
          const blockIndex = indexByTxid.get(entry.txid);
          const transaction = await hydrateCanonicalAddressHistoryTransaction(
            {
              blockHash: block.blockHash,
              blockHeight: height,
              blockIndex,
              txid: entry.txid,
            },
            network,
            {
              bypassCache: options.bypassCache === true,
              cacheResult: options.cacheResult !== false,
            },
          );
          if (
            !Number.isSafeInteger(blockIndex) ||
            transaction?._powCanonicalRpcHydration !== true ||
            transactionTxid(transaction) !== entry.txid ||
            !transactionConfirmed(transaction) ||
            transactionBlockHash(transaction) !== block.blockHash ||
            !Number.isSafeInteger(Number(transaction.status?.block_time)) ||
            Number(transaction.status.block_time) < 1 ||
            !registryAuditTransactionTouchesAddress(
              transaction,
              registryAddressForNetwork(network),
            )
          ) {
            throw new Error(
              `Bitcoin Core did not prove confirmed registry transaction ${entry.txid}.`,
            );
          }
          return {
            ...transaction,
            _powBlockIndex: blockIndex,
            _powPreviousBlockHash: block.previousBlockHash,
            status: {
              ...transaction.status,
              block_hash: block.blockHash,
              block_height: height,
              block_index: blockIndex,
              confirmed: true,
            },
          };
        },
      );
    },
  );
  return hydratedGroups.flat();
}

function registryAuditListingVersion(authorization) {
  return {
    "pwid-sale-v1": "list2",
    "pwid-sale-v2": "list3",
    "pwid-sale-v3": "list4",
    "pwid-sale-v4": "list5",
  }[String(authorization?.version ?? "").trim().toLowerCase()] ?? "";
}

function registryAuditExactSafeSats(value, label) {
  const text = String(value ?? "").trim();
  if (!/^(?:0|[1-9][0-9]*)$/u.test(text)) {
    throw new Error(`${label} is not an exact proof amount.`);
  }
  const amount = BigInt(text);
  if (amount > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new Error(`${label} exceeds the exact JSON proof range.`);
  }
  return Number(amount);
}

function registryAuditRawReplayAcceptedEvent(record, transaction, checkpoint) {
  const position = record?.position ?? {};
  const projection = record?.output?.projection ?? {};
  const parsed = projection?.parsed ?? {};
  const listing = projection?.listing ?? projection?.closedListing ?? null;
  const kind = registryAuditEventKind(
    projection?.kind ?? record?.outcome?.semanticKind,
  );
  const txid = registryAuditTxid(record?.txid, "Canonical raw ID replay");
  const blockHash = registryAuditTxid(
    position?.blockHash,
    `Canonical raw ID replay ${txid} block`,
  );
  const blockHeight = registryAuditInteger(
    position?.blockHeight,
    `Canonical raw ID replay ${txid} height`,
    1,
  );
  const blockIndex = registryAuditInteger(
    position?.blockTransactionIndex,
    `Canonical raw ID replay ${txid} block index`,
  );
  const protocolVout = registryAuditInteger(
    position?.protocolVout,
    `Canonical raw ID replay ${txid} protocol vout`,
  );
  const recordOrdinal = registryAuditInteger(
    position?.recordOrdinal,
    `Canonical raw ID replay ${txid} record ordinal`,
  );
  const transactionVout = Array.isArray(transaction?.vout)
    ? transaction.vout
    : [];
  const protocolPayload = decodedOpReturnAt(transactionVout, protocolVout);
  const blockTime = Number(transaction?.status?.block_time);
  if (
    record?.rawCandidate !== true ||
    record?.outcome?.valid !== true ||
    transactionTxid(transaction) !== txid ||
    transactionBlockHash(transaction) !== blockHash ||
    transactionBlockHeight(transaction) !== blockHeight ||
    transactionBlockIndex(transaction) !== blockIndex ||
    blockHeight > checkpoint.height ||
    !protocolPayload.startsWith(ID_PROTOCOL_PREFIX) ||
    !Number.isSafeInteger(blockTime) ||
    blockTime < 1
  ) {
    throw new Error(
      `Canonical raw ID replay ${txid}:${protocolVout}:${recordOrdinal} is not bound to exact Core evidence.`,
    );
  }

  const expectedFee = kind === "id-register" ? 1_000 : 546;
  const economicOutputs = Array.isArray(record?.stateDelta?.economicOutputs)
    ? record.stateDelta.economicOutputs
    : [];
  const registryClaims = economicOutputs
    .filter((output) => output?.role === "pwid-registry")
    .map((output) => {
      const vout = registryAuditInteger(
        output?.vout,
        `Canonical raw ID replay ${txid} registry claim`,
      );
      const physical = transactionVout[vout];
      const outputSats = registryAuditExactSafeSats(
        output?.outputSats,
        `Canonical raw ID replay ${txid} registry output`,
      );
      const attributedSats = registryAuditExactSafeSats(
        output?.attributedSats,
        `Canonical raw ID replay ${txid} registry attribution`,
      );
      if (
        physical?.scriptpubkey_address !==
          registryAddressForNetwork("livenet") ||
        Number(physical?.value) !== outputSats ||
        vout >= protocolVout
      ) {
        throw new Error(
          `Canonical raw ID replay ${txid} registry claim diverges from Core.`,
        );
      }
      return { attributedSats, outputSats, vout };
    });
  if (
    registryClaims.length < 1 ||
    registryClaims.reduce(
      (total, output) => total + output.attributedSats,
      0,
    ) !== expectedFee
  ) {
    throw new Error(
      `Canonical raw ID replay ${txid} has an inexact registry attribution.`,
    );
  }

  const saleAuthorization =
    projection?.saleAuthorization ??
    listing?.saleAuthorization ??
    parsed?.saleAuthorization ??
    null;
  const listingId = String(
    listing?.listingId ??
      parsed?.listingId ??
      (kind === "id-list" ? txid : ""),
  )
    .trim()
    .toLowerCase();
  const priceSats = listing?.priceSats === undefined
    ? undefined
    : registryAuditExactSafeSats(
        listing.priceSats,
        `Canonical raw ID replay ${txid} listing price`,
      );
  const registryPhysicalSats = paymentOutputsBeforeVout(
    transactionVout,
    protocolVout,
  ).reduce(
    (total, output) =>
      total +
      (output.address === registryAddressForNetwork("livenet")
        ? output.amountSats
        : 0),
    0,
  );
  return {
    amountSats: registryPhysicalSats,
    blockHash,
    blockHeight,
    blockIndex,
    confirmed: true,
    createdAt: new Date(blockTime * 1_000).toISOString(),
    dataBytes: Buffer.byteLength(protocolPayload, "utf8"),
    id: String(parsed?.id ?? listing?.id ?? "").trim().toLowerCase(),
    inputAddresses: inputAddresses(transaction?.vin ?? []),
    kind,
    listingId,
    listingVersion: registryAuditListingVersion(saleAuthorization),
    ownerAddress: String(
      projection?.ownerAddress ?? parsed?.ownerAddress ?? "",
    ).trim(),
    auditPaymentOutputs: paymentOutputsBeforeVout(
      transactionVout,
      protocolVout,
    ),
    pgpKey: String(parsed?.pgpKey ?? ""),
    priceSats,
    protocolDataBytes: Buffer.byteLength(protocolPayload, "utf8"),
    protocolPayload,
    protocolPayloadSha256: createHash("sha256")
      .update(protocolPayload, "utf8")
      .digest("hex"),
    protocolVout,
    rawRegistryClaims: registryClaims,
    receiveAddress: String(
      projection?.receiveAddress ?? parsed?.receiveAddress ?? "",
    ).trim(),
    recordOrdinal,
    saleAuthorization,
    sellerAddress: String(
      listing?.sellerAddress ?? saleAuthorization?.sellerAddress ?? "",
    ).trim(),
    spentOutpoints: spentOutpoints(transaction?.vin ?? []),
    transferVersion: kind === "id-buy" ? "buy5" : "",
    txid,
  };
}

function registryAuditRawReplayOutcome(record, checkpoint) {
  const position = record?.position ?? {};
  const txid = registryAuditTxid(record?.txid, "Canonical raw PWID outcome");
  const blockHash = registryAuditTxid(
    position?.blockHash,
    `Canonical raw PWID outcome ${txid} block`,
  );
  const blockHeight = registryAuditInteger(
    position?.blockHeight,
    `Canonical raw PWID outcome ${txid} height`,
    PWID_RAW_REPLAY_ACTIVATION_HEIGHT,
  );
  const blockIndex = registryAuditInteger(
    position?.blockTransactionIndex,
    `Canonical raw PWID outcome ${txid} block index`,
  );
  const protocolVout = registryAuditInteger(
    position?.protocolVout,
    `Canonical raw PWID outcome ${txid} vout`,
  );
  const recordOrdinal = registryAuditInteger(
    position?.recordOrdinal,
    `Canonical raw PWID outcome ${txid} ordinal`,
  );
  const rawPart = Array.isArray(record?.rawWitness?.rawRecordParts)
    ? record.rawWitness.rawRecordParts[0]
    : null;
  const evidence = registryAuditCanonicalPwidRecordEvidence(
    {
      message: rawPart?.text,
      protocol: record?.protocol,
      protocolVout,
      rawDecodeReasonCode: rawPart?.reasonCode,
      rawDecodeValid: rawPart?.decodeValid === true,
      rawRecordParts: record?.rawWitness?.rawRecordParts,
      recordOrdinal,
    },
    `Canonical raw PWID outcome ${txid}:${protocolVout}:${recordOrdinal}`,
  );
  const valid = record?.outcome?.valid;
  const consensusKind = String(record?.outcome?.kind ?? "").trim();
  const reasonCode = String(record?.outcome?.reasonCode ?? "").trim();
  const attributedRegistrySats = (Array.isArray(
    record?.stateDelta?.economicOutputs,
  ) ? record.stateDelta.economicOutputs : [])
    .filter((output) => output?.role === "pwid-registry")
    .reduce(
      (total, output) =>
        total + registryAuditExactSafeSats(
          output?.attributedSats,
          `Canonical raw PWID outcome ${txid} registry attribution`,
        ),
      0,
    );
  const rawSemanticKind = String(
    record?.outcome?.semanticKind ?? "",
  ).trim().toLowerCase();
  const rawProjectionKind = String(
    record?.output?.projection?.kind ?? "",
  ).trim().toLowerCase();
  const semanticKind = valid === true
    ? registryAuditEventKind(rawSemanticKind)
    : rawSemanticKind;
  const projectionKind = valid === true
    ? registryAuditEventKind(rawProjectionKind)
    : rawProjectionKind;
  if (
    record?.rawCandidate !== true ||
    typeof valid !== "boolean" ||
    consensusKind !== workAmoV5ConsensusEventKind("pwid1", valid) ||
    !semanticKind ||
    projectionKind !== semanticKind ||
    (valid ? reasonCode !== "" : !reasonCode) ||
    blockHeight > checkpoint.height ||
    (evidence.rawDecodeValid === false &&
      reasonCode !== evidence.rawDecodeReasonCode)
  ) {
    throw new Error(
      `Canonical raw PWID outcome ${txid}:${protocolVout}:${recordOrdinal} is incomplete.`,
    );
  }
  return {
    ...evidence,
    blockHash,
    blockHeight,
    blockIndex,
    attributedRegistrySats,
    consensusKind,
    projectionKind,
    rawCandidate: true,
    reasonCode,
    semanticKind,
    txid,
    valid,
  };
}

function registryAuditRelationalPagePayload(rows, checkpoint) {
  const values = Array.isArray(rows) ? rows : [];
  const positions = new Set(values.map(registryAuditPhysicalPositionKey));
  const mixedPositions = new Set(
    values
      .filter(
        (row) => row.positionOutcomeClass === "mixed-valid-and-invalid",
      )
      .map(registryAuditPhysicalPositionKey),
  );
  return {
    checkpoint: {
      blockHash: checkpoint.blockHash,
      height: checkpoint.height,
    },
    indexScanComplete: true,
    network: "livenet",
    rows: values,
    source: "proof-indexer-paged-pwid-transition-audit",
    stats: {
      invalidCount: values.filter((row) => row.valid !== true).length,
      maxCarrierPayloadBytes: values.reduce(
        (maximum, row) =>
          Math.max(maximum, String(row?.carrierPayloadHex ?? "").length / 2),
        0,
      ),
      mixedOutcomePositionCount: mixedPositions.size,
      positionCount: positions.size,
      rowCount: values.length,
      validCount: values.filter((row) => row.valid === true).length,
    },
  };
}

function createRegistryAuditParityAccumulator() {
  return {
    acceptedPositionCount: 0,
    canonicalOutcome: createIdRegistryAuditRollingHash(
      "canonical-pwid-outcome-pages",
    ),
    canonicalReplayOutcome: createIdRegistryAuditRollingHash(
      "canonical-pwid-replay-outcome-pages",
    ),
    coreBoundRelationalRows: createIdRegistryAuditRollingHash(
      "core-bound-relational-pwid-row-pages",
    ),
    diagnostic: createIdRegistryAuditRollingHash(
      "qualified-legacy-pwid-diagnostic-pages",
    ),
    diagnosticRowCount: 0,
    invalidCount: 0,
    legacyPositionCount: 0,
    maxCarrierPayloadBytes: 0,
    mixedOutcomePositionCount: 0,
    positionCount: 0,
    postActivationPositionCount: 0,
    rowCount: 0,
    segmentCount: 0,
    transactionCount: 0,
    transactionTxids: createIdRegistryAuditRollingHash(
      "canonical-pwid-transaction-pages",
    ),
    validCount: 0,
  };
}

function appendRegistryAuditParity(accumulator, parity, range) {
  const next = accumulator;
  const descriptor = {
    rangeEnd: range.rangeEnd,
    rangeKind: range.rangeKind,
    rangeStart: range.rangeStart,
  };
  next.acceptedPositionCount += parity.acceptedPositionCount;
  next.canonicalOutcome = advanceIdRegistryAuditRollingHash(
    next.canonicalOutcome,
    { ...descriptor, sha256: parity.canonicalOutcomeSha256 },
  );
  next.canonicalReplayOutcome = advanceIdRegistryAuditRollingHash(
    next.canonicalReplayOutcome,
    {
      ...descriptor,
      count: parity.canonicalReplayOutcomeCount,
      sha256: parity.canonicalReplayOutcomeSha256,
    },
  );
  next.coreBoundRelationalRows = advanceIdRegistryAuditRollingHash(
    next.coreBoundRelationalRows,
    { ...descriptor, sha256: parity.coreBoundRelationalRowsSha256 },
  );
  next.diagnostic = advanceIdRegistryAuditRollingHash(next.diagnostic, {
    ...descriptor,
    count: parity.diagnosticRowCount,
    sha256: parity.diagnosticSha256,
  });
  next.transactionTxids = advanceIdRegistryAuditRollingHash(
    next.transactionTxids,
    {
      ...descriptor,
      count: parity.transactionCount,
      sha256: parity.transactionTxidsSha256,
    },
  );
  for (const key of [
    "diagnosticRowCount",
    "invalidCount",
    "legacyPositionCount",
    "mixedOutcomePositionCount",
    "positionCount",
    "postActivationPositionCount",
    "rowCount",
    "transactionCount",
    "validCount",
  ]) {
    next[key] += Number(parity[key] ?? 0);
  }
  next.maxCarrierPayloadBytes = Math.max(
    next.maxCarrierPayloadBytes,
    Number(parity.maxCarrierPayloadBytes ?? 0),
  );
  next.segmentCount += 1;
  return next;
}

function finalizedRegistryAuditParity(accumulator, relationalRowsFence) {
  return {
    acceptedPositionCount: accumulator.acceptedPositionCount,
    canonicalOutcomeHashModel: accumulator.canonicalOutcome.model,
    canonicalOutcomeSha256: accumulator.canonicalOutcome.sha256,
    canonicalReplayOutcomeCount: accumulator.postActivationPositionCount,
    canonicalReplayOutcomeHashModel:
      accumulator.canonicalReplayOutcome.model,
    canonicalReplayOutcomeSha256:
      accumulator.canonicalReplayOutcome.sha256,
    coreBoundRelationalRowsHashModel:
      accumulator.coreBoundRelationalRows.model,
    coreBoundRelationalRowsSha256:
      accumulator.coreBoundRelationalRows.sha256,
    diagnosticRowCount: accumulator.diagnosticRowCount,
    diagnosticSha256: accumulator.diagnostic.sha256,
    invalidCount: accumulator.invalidCount,
    legacyPositionCount: accumulator.legacyPositionCount,
    maxCarrierPayloadBytes: accumulator.maxCarrierPayloadBytes,
    mixedOutcomePositionCount: accumulator.mixedOutcomePositionCount,
    physicalCarrierComplete: true,
    positionCount: accumulator.positionCount,
    postActivationPositionCount: accumulator.postActivationPositionCount,
    relationalRowsHashModel: relationalRowsFence.model,
    relationalRowsSha256: relationalRowsFence.sha256,
    rowCount: accumulator.rowCount,
    segmentCount: accumulator.segmentCount,
    transactionCount: accumulator.transactionCount,
    transactionTxidsHashModel: accumulator.transactionTxids.model,
    transactionTxidsSha256: accumulator.transactionTxids.sha256,
    validCount: accumulator.validCount,
  };
}

async function registryAuditCanonicalRawReplay(network, checkpoint) {
  const acceptedEvents = [];
  const legacyRows = [];
  const parity = createRegistryAuditParityAccumulator();
  let descriptorRolling = createIdRegistryAuditRollingHash(
    "canonical-pwid-replay-block-descriptors",
  );
  let replayBlockCount = 0;
  let currentRange = null;
  let tipTransition = null;

  const indexAudit = await proofIndexIdRegistryAuditStream(network, {
    expectedHash: checkpoint.blockHash,
    expectedHeight: checkpoint.height,
    verifyFinalFence: false,
    onPage: async (page) => {
      if (page.kind === "rows" && page.rangeKind === "pre-activation") {
        legacyRows.push(...page.rows);
        return;
      }
      if (page.kind === "transitions") {
        if (currentRange) {
          throw new Error("ID audit transition ranges overlapped.");
        }
        currentRange = {
          acceptedEvents: [],
          outcomes: [],
          rangeEnd: page.rangeEnd,
          rangeKind: page.rangeKind,
          rangeStart: page.rangeStart,
          rows: [],
          transactions: [],
        };
        tipTransition = page.transitions.at(-1) ?? tipTransition;
        const pwidTransitions = page.transitions.filter((stored) =>
          (Array.isArray(stored?.payload?.replayRecords)
            ? stored.payload.replayRecords
            : []
          ).some(
            (record) =>
              record?.protocol === "pwid1" && record?.rawCandidate === true,
          ),
        );
        const verified = await mapWithConcurrency(
          pwidTransitions,
          2,
          async (stored) => {
            const bundle = await completeIdVerifierStateBundle(
              network,
              stored.blockHeight,
              stored.blockHash,
              stored.previousBlockHash,
            );
            const transition = bundle?.workAmoV5BlockTransition;
            if (
              bundle?.canonicalCoverage !== true ||
              bundle?.coverageHeight !== stored.blockHeight ||
              bundle?.blockHash !== stored.blockHash ||
              bundle?.previousBlockHash !== stored.previousBlockHash ||
              transition?.complete !== true ||
              registryAuditProjectionSha256(stored.payload) !==
                registryAuditProjectionSha256(transition)
            ) {
              throw new Error(
                `Stored ID transition ${stored.blockHeight}:${stored.blockHash} disagrees with fresh Core replay.`,
              );
            }
            const pwidRecords = transition.replayRecords.filter(
              (record) =>
                record?.protocol === "pwid1" &&
                record?.rawCandidate === true,
            );
            const txids = new Set(
              pwidRecords.map((record) =>
                registryAuditTxid(record?.txid, "Canonical raw PWID record"),
              ),
            );
            const transactions = (Array.isArray(bundle.transactions)
              ? bundle.transactions
              : []
            ).filter((transaction) => txids.has(transactionTxid(transaction)));
            if (
              new Set(transactions.map(transactionTxid)).size !== txids.size
            ) {
              throw new Error(
                `Fresh Core replay at ${stored.blockHeight} omitted a PWID transaction.`,
              );
            }
            const transactionByTxid = new Map(
              transactions.map((transaction) => [
                transactionTxid(transaction),
                transaction,
              ]),
            );
            const outcomes = [];
            const accepted = [];
            for (const record of pwidRecords) {
              outcomes.push(registryAuditRawReplayOutcome(record, checkpoint));
              if (record?.outcome?.valid !== true) {
                continue;
              }
              const transaction = transactionByTxid.get(
                String(record?.txid ?? "").trim().toLowerCase(),
              );
              if (!transaction) {
                throw new Error(
                  `Fresh Core replay omitted accepted ID transaction ${record?.txid ?? "(unknown)"}.`,
                );
              }
              accepted.push(
                registryAuditRawReplayAcceptedEvent(
                  record,
                  transaction,
                  checkpoint,
                ),
              );
            }
            return {
              accepted,
              descriptor: {
                blockHash: stored.blockHash,
                blockHeight: stored.blockHeight,
                eventSetCommitment: transition.eventSetCommitment,
                replayDescriptorCommitment:
                  transition.replayDescriptorCommitment,
                transitionChainCommitment:
                  transition.transitionChainCommitment,
              },
              outcomes,
              transactions,
            };
          },
        );
        verified.sort(
          (left, right) =>
            left.descriptor.blockHeight - right.descriptor.blockHeight,
        );
        for (const item of verified) {
          currentRange.acceptedEvents.push(...item.accepted);
          currentRange.outcomes.push(...item.outcomes);
          currentRange.transactions.push(...item.transactions);
          acceptedEvents.push(...item.accepted);
          descriptorRolling = advanceIdRegistryAuditRollingHash(
            descriptorRolling,
            item.descriptor,
          );
          replayBlockCount += 1;
        }
        return;
      }
      if (page.kind === "rows" && page.rangeKind === "post-activation") {
        if (
          !currentRange ||
          currentRange.rangeStart !== page.rangeStart ||
          currentRange.rangeEnd !== page.rangeEnd
        ) {
          throw new Error("ID audit relational page escaped its transition range.");
        }
        currentRange.rows.push(...page.rows);
        return;
      }
      if (page.kind === "range-complete" && page.rangeKind === "post-activation") {
        if (
          !currentRange ||
          currentRange.rangeStart !== page.rangeStart ||
          currentRange.rangeEnd !== page.rangeEnd
        ) {
          throw new Error("ID audit transition range completion drifted.");
        }
        assertIdRegistryAuditAttemptPositionCoverage(
          currentRange.outcomes,
          currentRange.rows,
        );
        const relational = registryAuditRelationalAttemptRows(
          registryAuditRelationalPagePayload(currentRange.rows, checkpoint),
          checkpoint,
        );
        const rangeParity = registryAuditAttemptParity(
          relational,
          currentRange.transactions,
          currentRange.acceptedEvents,
          currentRange.outcomes,
          checkpoint,
        );
        appendRegistryAuditParity(parity, rangeParity, currentRange);
        currentRange = null;
      }
    },
  });
  if (!indexAudit || currentRange || !tipTransition) {
    throw new Error("The paged ID transition audit did not reach its checkpoint.");
  }
  const tipBundle = await completeIdVerifierStateBundle(
    network,
    checkpoint.height,
    checkpoint.blockHash,
    tipTransition.previousBlockHash,
  );
  if (
    tipBundle?.canonicalCoverage !== true ||
    tipBundle?.coverageHeight !== checkpoint.height ||
    tipBundle?.blockHash !== checkpoint.blockHash
  ) {
    throw new Error("Canonical ID replay tip changed before closing-state proof.");
  }
  const closingRecords = (Array.isArray(tipBundle?.state?.records)
    ? tipBundle.state.records
    : [])
    .map((record) => ({
      id: registryAuditId(record?.id, "Canonical raw closing ID record"),
      ownerAddress: registryAuditAddress(
        record?.ownerAddress,
        "Canonical raw closing ID record",
      ),
      pgpKey: String(record?.pgpKey ?? ""),
      receiveAddress: registryAuditAddress(
        record?.receiveAddress,
        "Canonical raw closing ID record",
      ),
    }))
    .sort((left, right) => compareCanonicalUtf8(left.id, right.id));
  const closingListings = (Array.isArray(tipBundle?.state?.listings)
    ? tipBundle.state.listings
    : [])
    .map((listing) => ({
      id: registryAuditId(listing?.id, "Canonical raw closing ID listing"),
      listingId: registryAuditTxid(
        listing?.listingId,
        "Canonical raw closing ID listing",
      ),
      priceSats: registryAuditExactSafeSats(
        listing?.priceSats,
        "Canonical raw closing ID listing price",
      ),
      saleAuthorization: registryAuditCanonicalClone(
        listing?.saleAuthorization,
      ),
      sellerAddress: registryAuditAddress(
        listing?.sellerAddress,
        "Canonical raw closing ID listing",
      ),
    }))
    .sort((left, right) =>
      compareCanonicalUtf8(left.listingId, right.listingId),
    );
  const closingState = { listings: closingListings, records: closingRecords };
  return {
    acceptedEvents,
    closingState,
    closingStateSha256: registryAuditProjectionSha256(closingState),
    descriptorFingerprint:
      idRegistryAuditRollingHashFingerprint(descriptorRolling),
    indexAudit,
    legacyRows,
    parity,
    replayBlockCount,
    replayDescriptorSha256: descriptorRolling.sha256,
  };
}

function registryAuditProjectionFromCanonicalState(
  state,
  checkpoint,
  rawReplay = null,
) {
  const legacyEvents = (Array.isArray(state?._powAuditEvents)
    ? state._powAuditEvents
    : []
  ).filter(
    (item) =>
      item?.confirmed === true &&
      Number(item?.blockHeight) < WORK_AMO_V5_ACTIVATION_HEIGHT,
  );
  const events = [
    ...legacyEvents.map((item) =>
      registryAuditLifecycleEventEntry(item, checkpoint, "chain"),
    ),
    ...(Array.isArray(rawReplay?.acceptedEvents)
      ? rawReplay.acceptedEvents.map((item) =>
          registryAuditLifecycleEventEntry(
            item,
            checkpoint,
            "canonical-raw",
          ),
        )
      : []),
  ]
    .sort(
      (left, right) =>
        left.blockHeight - right.blockHeight ||
        left.blockIndex - right.blockIndex ||
        left.protocolVout - right.protocolVout ||
        left.recordOrdinal - right.recordOrdinal ||
        compareCanonicalUtf8(left.txid, right.txid) ||
        compareCanonicalUtf8(left.kind, right.kind),
    );
  const registrationById = new Map();
  const lastMutationById = new Map();
  for (const item of events) {
    if (item.kind === "id-register") {
      if (registrationById.has(item.id)) {
        throw new Error(`Chain-derived ID registration repeats ${item.id}.`);
      }
      registrationById.set(item.id, item);
    }
    if (
      !["id-register", "id-update", "id-transfer", "id-buy"].includes(
        item.kind,
      ) ||
      !item.id
    ) {
      continue;
    }
    lastMutationById.set(item.id, item);
  }

  const rawClosingRecords = Array.isArray(rawReplay?.closingState?.records)
    ? rawReplay.closingState.records
    : null;
  const records = rawClosingRecords ??
    (Array.isArray(state?.records) ? state.records : []);
  const confirmedRecords = records
    .filter((record) => rawClosingRecords || record?.confirmed === true)
    .map((record) => {
      const id = registryAuditId(record.id, "Chain-derived ID record");
      const registration = registrationById.get(id);
      const lastMutation = lastMutationById.get(id);
      const blockHeight = Number(registration?.blockHeight);
      const blockIndex = Number(registration?.blockIndex);
      const updatedHeight = Number(
        rawClosingRecords ? lastMutation?.blockHeight : record?.blockHeight,
      );
      if (
        !registration ||
        !Number.isSafeInteger(blockHeight) ||
        blockHeight < 1 ||
        !Number.isSafeInteger(blockIndex) ||
        blockIndex < 0 ||
        !Number.isSafeInteger(updatedHeight) ||
        updatedHeight < blockHeight ||
        updatedHeight > checkpoint.height
      ) {
        throw new Error(`Chain-derived ID record ${id} has no exact lifecycle position.`);
      }
      return {
        blockHeight,
        blockIndex,
        id,
        lastEventTxid: registryAuditTxid(
          rawClosingRecords ? lastMutation?.txid : record.txid,
          `Chain-derived ID record ${id} last event`,
        ),
        ownerAddress: registryAuditAddress(
          record.ownerAddress,
          `Chain-derived ID record ${id}`,
        ),
        pgpKey: String(record.pgpKey ?? ""),
        receiveAddress: registryAuditAddress(
          record.receiveAddress,
          `Chain-derived ID record ${id}`,
        ),
        txid: registryAuditTxid(
          registration.txid,
          `Chain-derived ID registration ${id}`,
        ),
        updatedHeight,
      };
    })
    .sort(
      (left, right) =>
        compareCanonicalUtf8(left.id, right.id) ||
        compareCanonicalUtf8(left.txid, right.txid),
    );
  const pendingRecords = (Array.isArray(state?.records) ? state.records : [])
    .filter((record) => record?.confirmed !== true)
    .map((record) => {
      const id = registryAuditId(record.id, "Chain-derived pending ID record");
      return {
        id,
        ownerAddress: registryAuditAddress(
          record.ownerAddress,
          `Chain-derived pending ID record ${id}`,
        ),
        pgpKey: String(record.pgpKey ?? ""),
        receiveAddress: registryAuditAddress(
          record.receiveAddress,
          `Chain-derived pending ID record ${id}`,
        ),
        txid: registryAuditTxid(
          record.txid,
          `Chain-derived pending ID record ${id}`,
        ),
      };
    })
    .sort(
      (left, right) =>
        compareCanonicalUtf8(left.id, right.id) ||
        compareCanonicalUtf8(left.txid, right.txid),
    );
  const pendingEvents = (Array.isArray(state?.pendingEvents)
    ? state.pendingEvents
    : []
  )
    .map(registryAuditPendingEventEntry)
    .sort(
      (left, right) =>
        compareCanonicalUtf8(left.txid, right.txid) ||
        compareCanonicalUtf8(left.kind, right.kind) ||
        compareCanonicalUtf8(left.id, right.id) ||
        compareCanonicalUtf8(left.listingId, right.listingId),
    );
  const rawClosingListings = Array.isArray(rawReplay?.closingState?.listings)
    ? rawReplay.closingState.listings
    : null;
  const listingSource = rawClosingListings
    ? rawClosingListings.map((listing) => {
        const listingId = registryAuditTxid(
          listing?.listingId,
          "Canonical raw closing ID listing",
        );
        const listEvent = events.find(
          (event) =>
            event.kind === "id-list" &&
            event.txid === listingId &&
            event.listingId === listingId,
        );
        const sealEvents = events.filter(
          (event) =>
            event.kind === "id-seal" && event.listingId === listingId,
        );
        const sealEvent = sealEvents.at(-1) ?? null;
        const saleAuthorization = registryAuditCanonicalClone(
          listing?.saleAuthorization,
        );
        const listingVersion = registryAuditListingVersion(saleAuthorization);
        const id = registryAuditId(
          listing?.id,
          `Canonical raw closing ID listing ${listingId}`,
        );
        const priceSats = registryAuditExactSafeSats(
          listing?.priceSats,
          `Canonical raw closing ID listing ${listingId} price`,
        );
        const sellerAddress = registryAuditAddress(
          listing?.sellerAddress,
          `Canonical raw closing ID listing ${listingId} seller`,
        );
        if (
          !listEvent ||
          !listingVersion ||
          listEvent.id !== id ||
          listEvent.priceSats !== priceSats ||
          listEvent.sellerAddress !== sellerAddress ||
          listEvent.listingVersion !== listingVersion ||
          !saleAuthorizationTermsMatchIgnoringSeal(
            listEvent.saleAuthorization,
            saleAuthorization,
          ) ||
          (sealEvent &&
            !saleAuthorizationTermsMatchIgnoringSeal(
              sealEvent.saleAuthorization,
              saleAuthorization,
            ))
        ) {
          throw new Error(
            `Canonical raw closing ID listing ${listingId} has no exact accepted lifecycle.`,
          );
        }
        return {
          anchorSigHashType: saleAuthorization.anchorSigHashType,
          anchorSignature: saleAuthorization.anchorSignature,
          anchorScriptPubKey: saleAuthorization.anchorScriptPubKey,
          anchorTxid: saleAuthorization.anchorTxid,
          anchorType: saleAuthorization.anchorType,
          anchorValueSats: saleAuthorization.anchorValueSats,
          anchorVout: saleAuthorization.anchorVout,
          blockHash: listEvent.blockHash,
          blockHeight: listEvent.blockHeight,
          blockIndex: listEvent.blockIndex,
          buyerAddress: saleAuthorization.buyerAddress,
          confirmed: true,
          createdAt: listEvent.createdAt,
          expiresAt: saleAuthorization.expiresAt,
          id,
          listingId,
          listingVersion,
          priceSats,
          protocolVout: listEvent.protocolVout,
          receiveAddress: saleAuthorization.receiveAddress,
          recordOrdinal: listEvent.recordOrdinal,
          saleAuthorization,
          sealTxid: sealEvent?.txid ?? null,
          sellerAddress,
          sellerPublicKey: saleAuthorization.sellerPublicKey,
          txid: listingId,
        };
      })
    : (Array.isArray(state?.listings) ? state.listings : []);
  const listings = listingSource
    .map((item) =>
      registryAuditStateItemEntry(
        item,
        REGISTRY_AUDIT_LISTING_FIELDS,
        "Chain-derived ID listing",
      ),
    )
    .sort(
      (left, right) =>
        compareCanonicalUtf8(left.listingId, right.listingId) ||
        compareCanonicalUtf8(left.txid, right.txid),
    );
  const legacySales = rawReplay
    ? (Array.isArray(state?.sales) ? state.sales : []).filter(
        (sale) =>
          sale?.confirmed !== true ||
          (Number.isSafeInteger(Number(sale?.blockHeight)) &&
            Number(sale.blockHeight) < PWID_RAW_REPLAY_ACTIVATION_HEIGHT),
      )
    : (Array.isArray(state?.sales) ? state.sales : []);
  const rawSales = rawReplay
    ? events
        .filter(
          (event) =>
            event.kind === "id-buy" &&
            event.blockHeight >= PWID_RAW_REPLAY_ACTIVATION_HEIGHT,
        )
        .map((event) => {
          const id = registryAuditId(
            event.id,
            `Canonical raw ID sale ${event.txid}`,
          );
          const buyerAddress = registryAuditAddress(
            event.ownerAddress,
            `Canonical raw ID sale ${event.txid} buyer`,
          );
          const receiveAddress = registryAuditAddress(
            event.receiveAddress,
            `Canonical raw ID sale ${event.txid} receiver`,
          );
          const sellerAddress = registryAuditAddress(
            event.sellerAddress,
            `Canonical raw ID sale ${event.txid} seller`,
          );
          const priceSats = registryAuditExactSafeSats(
            event.priceSats,
            `Canonical raw ID sale ${event.txid} price`,
          );
          if (event.transferVersion !== "buy5") {
            throw new Error(
              `Canonical raw ID sale ${event.txid} has no exact transfer version.`,
            );
          }
          return {
            blockHash: event.blockHash,
            blockHeight: event.blockHeight,
            blockIndex: event.blockIndex,
            buyerAddress,
            confirmed: true,
            createdAt: event.createdAt,
            id,
            listingId: event.listingId || null,
            priceSats,
            protocolVout: event.protocolVout,
            receiveAddress,
            recordOrdinal: event.recordOrdinal,
            sellerAddress,
            transferVersion: event.transferVersion,
            txid: event.txid,
          };
        })
    : [];
  const sales = [...legacySales, ...rawSales]
    .map((item) =>
      registryAuditStateItemEntry(
        item,
        REGISTRY_AUDIT_SALE_FIELDS,
        "Chain-derived ID sale",
      ),
    )
    .sort(
      (left, right) =>
        compareCanonicalUtf8(left.txid, right.txid) ||
        compareCanonicalUtf8(String(left.listingId ?? ""), String(right.listingId ?? "")),
    );
  const projection = {
    checkpoint: {
      blockHash: checkpoint.blockHash,
      height: checkpoint.height,
    },
    confirmedRecords,
    events,
    listings,
    pendingEvents,
    pendingRecords,
    sales,
  };
  return {
    ...projection,
    projectionSha256: registryAuditProjectionSha256(projection),
  };
}

function registryAuditRelationalRawClosingState(projection) {
  const records = (Array.isArray(projection?.confirmedRecords)
    ? projection.confirmedRecords
    : [])
    .map((record) => ({
      id: record.id,
      ownerAddress: record.ownerAddress,
      pgpKey: String(record.pgpKey ?? ""),
      receiveAddress: record.receiveAddress,
    }))
    .sort((left, right) => compareCanonicalUtf8(left.id, right.id));
  const listings = (Array.isArray(projection?.listings)
    ? projection.listings
    : [])
    .filter((listing) => listing?.confirmed === true)
    .map((listing) => ({
      id: registryAuditId(listing?.id, "Relational closing ID listing"),
      listingId: registryAuditTxid(
        listing?.listingId,
        "Relational closing ID listing",
      ),
      priceSats: registryAuditExactSafeSats(
        listing?.priceSats,
        "Relational closing ID listing price",
      ),
      saleAuthorization: registryAuditCanonicalClone(
        listing?.saleAuthorization,
      ),
      sellerAddress: registryAuditAddress(
        listing?.sellerAddress,
        "Relational closing ID listing",
      ),
    }))
    .sort((left, right) =>
      compareCanonicalUtf8(left.listingId, right.listingId),
    );
  return { listings, records };
}

async function registryAuditRawReplayWithSpendableListings(
  rawReplay,
  network,
  checkpoint,
) {
  const closingState =
    rawReplay?.closingState &&
    typeof rawReplay.closingState === "object" &&
    !Array.isArray(rawReplay.closingState)
      ? rawReplay.closingState
      : { listings: [], records: [] };
  const sourceListings = Array.isArray(closingState.listings)
    ? closingState.listings
    : [];
  const checked = await mapWithConcurrency(
    sourceListings,
    Math.min(4, Math.max(1, TX_FETCH_CONCURRENCY)),
    async (listing) => {
      if (!registryListingUsesCoreAnchor(listing)) {
        return { listing, status: "legacy-unanchored" };
      }
      const anchor = listingAnchorOutpoint(listing);
      if (!anchor) {
        throw registryAuthorityUnavailable(
          `Raw replay ID listing ${String(listing?.listingId ?? "unknown")} has no exact Core anchor.`,
        );
      }
      const outpoint = `${anchor.txid}:${anchor.vout}`;
      let outspend;
      try {
        outspend = await txOutspendPayload(anchor.txid, anchor.vout, network);
      } catch (error) {
        throw registryAuthorityUnavailable(
          `Outspend lookup failed for raw replay ID listing ${outpoint}.`,
          { reason: errorSummary(error) },
        );
      }
      if (outspend?.spent === true) {
        if (outspendHasConfirmedSpender(outspend)) {
          const spenderHeight = registryAuditInteger(
            outspend.status.block_height,
            `Raw replay ID listing ${outpoint} spender height`,
            1,
          );
          const spenderTxid = registryAuditTxid(
            outspend.txid,
            `Raw replay ID listing ${outpoint} spender`,
          );
          return {
            listing,
            outpoint,
            spenderHeight,
            spenderTxid,
            status:
              spenderHeight <= checkpoint.height
                ? "spent-confirmed"
                : "spent-after-checkpoint",
          };
        }
        return { listing, outpoint, status: "spent-unconfirmed" };
      }
      if (outspend?.spent === false) {
        return {
          listing,
          outpoint,
          status: outspend.unknown === true ? "unspent-unknown" : "unspent",
        };
      }
      throw registryAuthorityUnavailable(
        `Outspend lookup returned no exact status for raw replay ID listing ${outpoint}.`,
      );
    },
  );
  const spendableClosingListings = checked
    .filter(
      (entry) =>
        entry.status !== "spent-confirmed" &&
        entry.status !== "spent-unconfirmed",
    )
    .map((entry) => entry.listing)
    .map((listing) => ({
      id: registryAuditId(listing?.id, "Spendable raw closing ID listing"),
      listingId: registryAuditTxid(
        listing?.listingId,
        "Spendable raw closing ID listing",
      ),
      priceSats: registryAuditExactSafeSats(
        listing?.priceSats,
        "Spendable raw closing ID listing price",
      ),
      saleAuthorization: registryAuditCanonicalClone(
        listing?.saleAuthorization,
      ),
      sellerAddress: registryAuditAddress(
        listing?.sellerAddress,
        "Spendable raw closing ID listing",
      ),
    }))
    .sort((left, right) =>
      compareCanonicalUtf8(left.listingId, right.listingId),
    );
  const spendableClosingState = {
    listings: spendableClosingListings,
    records: Array.isArray(closingState.records)
      ? closingState.records
      : [],
  };
  return {
    ...rawReplay,
    closingState: spendableClosingState,
    closingStateSha256: registryAuditProjectionSha256(spendableClosingState),
    listingReconciliation: {
      anchoredListingCount: checked.filter((entry) => entry.outpoint).length,
      checkedOutpointsSha256: registryAuditProjectionSha256(
        checked
          .filter((entry) => entry.outpoint)
          .map((entry) => ({
            outpoint: entry.outpoint,
            spenderHeight: entry.spenderHeight ?? null,
            spenderTxid: entry.spenderTxid ?? "",
            status: entry.status,
          }))
          .sort((left, right) =>
            compareCanonicalUtf8(left.outpoint, right.outpoint),
          ),
      ),
      checkpoint: { ...checkpoint },
      inputListingCount: sourceListings.length,
      legacyUnanchoredListingCount: checked.filter((entry) => !entry.outpoint)
        .length,
      model: "proof-registry-audit-historical-outspend-v1",
      outputListingCount: spendableClosingListings.length,
      spentListingCount: checked.filter(
        (entry) =>
          entry.status === "spent-confirmed" ||
          entry.status === "spent-unconfirmed",
      ).length,
      unspentListingCount: checked.filter(
        (entry) =>
          entry.status === "unspent" ||
          entry.status === "unspent-unknown" ||
          entry.status === "spent-after-checkpoint",
      ).length,
    },
  };
}

function assertUnambiguousRegistryAuditEvents(transactions) {
  for (const transaction of Array.isArray(transactions) ? transactions : []) {
    if (transactionConfirmed(transaction)) {
      // Confirmed post-activation transactions are resolved by the canonical
      // raw-block sequencer at every protocol vout/ordinal below.
      continue;
    }
    const txid = transactionTxid(transaction);
    const messages = decodedProtocolMessages(
      transaction?.vout ?? [],
      ID_PROTOCOL_PREFIX,
    );
    if (messages.length > 1) {
      throw new Error(
        `Registry transaction ${txid || "(unknown)"} contains multiple ID protocol records; exact lifecycle parity is ambiguous.`,
      );
    }
  }
}

function registryAuditPhysicalPositionKey(value) {
  return [
    value.txid,
    value.blockHeight,
    value.blockIndex,
    value.protocolVout,
    value.recordOrdinal,
  ].join(":");
}

function compareRegistryAuditPhysicalPositions(left, right) {
  return (
    left.blockHeight - right.blockHeight ||
    left.blockIndex - right.blockIndex ||
    left.protocolVout - right.protocolVout ||
    left.recordOrdinal - right.recordOrdinal ||
    compareCanonicalUtf8(left.txid, right.txid)
  );
}

function registryAuditCanonicalPwidRecordEvidence(record, label) {
  const protocolVout = registryAuditInteger(
    record?.protocolVout,
    `${label} vout`,
  );
  const recordOrdinal = registryAuditInteger(
    record?.recordOrdinal,
    `${label} ordinal`,
  );
  const parts = Array.isArray(record?.rawRecordParts)
    ? record.rawRecordParts
    : [];
  const part = parts[0];
  const rawPayloadHex = String(part?.payloadHex ?? "")
    .trim()
    .toLowerCase();
  const scriptPubKeyHex = String(part?.scriptPubKeyHex ?? "")
    .trim()
    .toLowerCase();
  const rawPayloadBytes = /^(?:[0-9a-f]{2})+$/u.test(rawPayloadHex)
    ? Buffer.from(rawPayloadHex, "hex")
    : null;
  const prefixBytes = Buffer.from(ID_PROTOCOL_PREFIX, "ascii");
  const rawDecodeValid = part?.decodeValid === true;
  const rawDecodeDetail = String(part?.decodeDetail ?? "");
  const rawDecodeReasonCode = String(part?.reasonCode ?? "").trim();
  if (
    record?.protocol !== "pwid1" ||
    recordOrdinal !== 0 ||
    parts.length !== 1 ||
    Number(part?.protocolVout) !== protocolVout ||
    part?.prefix !== ID_PROTOCOL_PREFIX ||
    record?.rawDecodeValid !== rawDecodeValid ||
    String(record?.rawDecodeReasonCode ?? "") !== rawDecodeReasonCode ||
    !rawPayloadBytes ||
    rawPayloadBytes.length < prefixBytes.length ||
    !rawPayloadBytes.subarray(0, prefixBytes.length).equals(prefixBytes) ||
    !/^(?:[0-9a-f]{2})+$/u.test(scriptPubKeyHex)
  ) {
    throw new Error(`${label} has incomplete byte-first PWID evidence.`);
  }

  let rawPayload = "";
  if (rawDecodeValid) {
    try {
      rawPayload = new TextDecoder("utf-8", { fatal: true }).decode(
        rawPayloadBytes,
      );
    } catch {
      rawPayload = "";
    }
    if (
      rawDecodeReasonCode ||
      !rawPayload.startsWith(ID_PROTOCOL_PREFIX) ||
      rawPayload !== String(record?.message ?? "") ||
      !Buffer.from(rawPayload, "utf8").equals(rawPayloadBytes)
    ) {
      throw new Error(`${label} lost its fatal UTF-8 round trip.`);
    }
  } else if (
    ![
      CANONICAL_OP_RETURN_SCRIPT_MALFORMED,
      CANONICAL_OP_RETURN_TEXT_STORAGE_INVALID,
      CANONICAL_OP_RETURN_UTF8_INVALID,
    ].includes(rawDecodeReasonCode) ||
    String(record?.message ?? "") !== ID_PROTOCOL_PREFIX
  ) {
    throw new Error(`${label} has an unsupported raw decode rejection.`);
  }

  return {
    dataBytes: rawPayloadBytes.length,
    protocolVout,
    rawDecodeDetail,
    rawDecodeReasonCode,
    rawDecodeValid,
    rawPayload,
    rawPayloadHex,
    rawPayloadSha256: createHash("sha256")
      .update(rawPayloadBytes)
      .digest("hex"),
    recordOrdinal,
    scriptPubKeyHex,
    scriptPubKeySha256: createHash("sha256")
      .update(Buffer.from(scriptPubKeyHex, "hex"))
      .digest("hex"),
  };
}

function registryAuditCanonicalPwidCarriers(transactions, checkpoint) {
  const carriers = [];
  const seen = new Set();
  for (const transaction of Array.isArray(transactions) ? transactions : []) {
    if (!transactionConfirmed(transaction)) {
      continue;
    }
    const txid = registryAuditTxid(
      transactionTxid(transaction),
      "Canonical PWID carrier transaction",
    );
    const blockHash = registryAuditTxid(
      transactionBlockHash(transaction),
      `Canonical PWID carrier ${txid} block`,
    );
    const blockHeight = registryAuditInteger(
      transactionBlockHeight(transaction),
      `Canonical PWID carrier ${txid} height`,
      1,
    );
    const blockIndex = registryAuditInteger(
      transactionBlockIndex(transaction),
      `Canonical PWID carrier ${txid} block index`,
    );
    const blockTimeSeconds = registryAuditInteger(
      transaction?.status?.block_time,
      `Canonical PWID carrier ${txid} block time`,
      1,
    );
    if (blockHeight > checkpoint.height) {
      throw new Error(`Canonical PWID carrier ${txid} is above the checkpoint.`);
    }
    let records;
    try {
      records = canonicalRawProtocolRecordSetFromTransaction(transaction).records;
    } catch (error) {
      throw new Error(
        `Canonical PWID carrier decoding failed for ${txid}: ${errorSummary(error)}`,
      );
    }
    const pwidRecords = records.filter((record) => record?.protocol === "pwid1");
    if (
      blockHeight < PWID_RAW_REPLAY_ACTIVATION_HEIGHT &&
      pwidRecords.length > 1
    ) {
      throw new Error(
        `Pre-activation PWID transaction ${txid} has multiple records and cannot be replay-qualified.`,
      );
    }
    for (const record of pwidRecords) {
      const evidence = registryAuditCanonicalPwidRecordEvidence(
        record,
        `Canonical PWID carrier ${txid}`,
      );
      const carrier = {
        blockHash,
        blockHeight,
        blockIndex,
        blockTime: new Date(blockTimeSeconds * 1_000).toISOString(),
        ...evidence,
        txid,
      };
      const key = registryAuditPhysicalPositionKey(carrier);
      if (seen.has(key)) {
        throw new Error(`Canonical PWID carrier position ${key} is duplicated.`);
      }
      seen.add(key);
      carriers.push(carrier);
    }
  }
  return carriers.sort(compareRegistryAuditPhysicalPositions);
}

function registryAuditRelationalAttemptRows(payload, checkpoint) {
  if (
    !payload ||
    payload.network !== "livenet" ||
    ![
      "proof-indexer-confirmed-pwid-audit-rows",
      "proof-indexer-paged-pwid-transition-audit",
    ].includes(payload.source) ||
    payload.indexScanComplete !== true ||
    payload.checkpoint?.height !== checkpoint.height ||
    payload.checkpoint?.blockHash !== checkpoint.blockHash ||
    !Array.isArray(payload.rows)
  ) {
    throw new Error("The relational PWID audit-row projection is incomplete.");
  }
  const seenEventIds = new Set();
  const rows = payload.rows.map((row) => {
    const eventId = registryAuditInteger(
      row?.eventId,
      "Relational PWID audit event ID",
      1,
    );
    if (seenEventIds.has(eventId)) {
      throw new Error(`Relational PWID audit event ${eventId} is duplicated.`);
    }
    seenEventIds.add(eventId);
    const txid = registryAuditTxid(row?.txid, `Relational PWID event ${eventId}`);
    const blockHash = registryAuditTxid(
      row?.blockHash,
      `Relational PWID event ${eventId} block`,
    );
    const blockHeight = registryAuditInteger(
      row?.blockHeight,
      `Relational PWID event ${eventId} height`,
      1,
    );
    const blockIndex = registryAuditInteger(
      row?.blockIndex,
      `Relational PWID event ${eventId} block index`,
    );
    const protocolVout = registryAuditInteger(
      row?.protocolVout,
      `Relational PWID event ${eventId} vout`,
    );
    const recordOrdinal = registryAuditInteger(
      row?.recordOrdinal,
      `Relational PWID event ${eventId} ordinal`,
    );
    const dataBytes = registryAuditInteger(
      row?.dataBytes,
      `Relational PWID event ${eventId} byte count`,
      1,
    );
    const amountSats = registryAuditExactSafeSats(
      row?.amountSats,
      `Relational PWID event ${eventId} attributed amount`,
    );
    const carrierPayload = String(row?.carrierPayload ?? "");
    const carrierPayloadHex = String(row?.carrierPayloadHex ?? "")
      .trim()
      .toLowerCase();
    const blockTime = new Date(row?.blockTime).toISOString();
    if (
      blockHeight > checkpoint.height ||
      row?.protocol !== "pwid1" ||
      row?.status !== "confirmed" ||
      !Number.isFinite(Date.parse(blockTime)) ||
      typeof row?.valid !== "boolean" ||
      typeof row?.replayMetadataPresent !== "boolean" ||
      typeof row?.rawScriptWitnessPresent !== "boolean" ||
      typeof row?.storedRawPayloadPresent !== "boolean" ||
      typeof row?.payloadRawPayloadPresent !== "boolean"
    ) {
      throw new Error(
        `Relational PWID event ${eventId} has incomplete physical evidence.`,
      );
    }
    const valid = row.valid;
    const storedRawPayload = String(row?.storedRawPayload ?? "");
    const payloadRawPayload = String(row?.payloadRawPayload ?? "");
    const rawKind = String(row?.kind ?? "").trim().toLowerCase();
    if (!rawKind || rawKind.length > 128) {
      throw new Error(`Relational PWID event ${eventId} has no bounded kind.`);
    }
    return {
      amountSats,
      attemptedKind: String(row?.attemptedKind ?? ""),
      blockHash,
      blockHeight,
      blockIndex,
      blockTime,
      carrierPayload,
      carrierPayloadHex,
      carrierProtocol: String(row?.carrierProtocol ?? "")
        .trim()
        .toLowerCase(),
      dataBytes,
      eventId,
      eventKey: String(row?.eventKey ?? ""),
      kind: valid ? registryAuditEventKind(rawKind) : rawKind,
      payloadSource: String(row?.payloadSource ?? ""),
      payloadRawPayload,
      payloadRawPayloadPresent: row?.payloadRawPayloadPresent === true,
      payloadRawPayloadSha256: row?.payloadRawPayloadPresent === true
        ? createHash("sha256").update(payloadRawPayload, "utf8").digest("hex")
        : "",
      payloadReason: String(row?.payloadReason ?? ""),
      payloadReasonCode: String(row?.payloadReasonCode ?? ""),
      positionOutcomeClass: String(row?.positionOutcomeClass ?? ""),
      protocolVout,
      rawDecodeReasonCode: String(row?.rawDecodeReasonCode ?? ""),
      rawDecodeValid: row?.rawDecodeValid,
      rawScriptDecodeDetail: String(row?.rawScriptDecodeDetail ?? ""),
      rawScriptDecodeValid: row?.rawScriptDecodeValid,
      rawScriptPayloadHex: String(row?.rawScriptPayloadHex ?? "")
        .trim()
        .toLowerCase(),
      rawScriptPubKeyHex: String(row?.rawScriptPubKeyHex ?? "")
        .trim()
        .toLowerCase(),
      rawScriptReasonCode: String(row?.rawScriptReasonCode ?? ""),
      rawScriptWitnessPresent: row?.rawScriptWitnessPresent === true,
      reasonCode: String(row?.reasonCode ?? ""),
      recordOrdinal,
      replayBound: row?.replayBound === true,
      replayMetadataPresent: row?.replayMetadataPresent === true,
      replayOutcomeKind: String(row?.replayOutcomeKind ?? ""),
      replayOutcomeReasonCode: String(
        row?.replayOutcomeReasonCode ?? "",
      ),
      replayOutcomeValid: row?.replayOutcomeValid,
      replayRawCandidate: row?.replayRawCandidate,
      rowClassification: String(row?.rowClassification ?? ""),
      storedRawPayload,
      storedRawPayloadPresent: row?.storedRawPayloadPresent === true,
      storedRawPayloadSha256: row?.storedRawPayloadPresent === true
        ? createHash("sha256").update(storedRawPayload, "utf8").digest("hex")
        : "",
      txid,
      valid,
      validationMode: String(row?.validationMode ?? ""),
      validationErrors: Array.isArray(row?.validationErrors)
        ? row.validationErrors.map((value) => String(value ?? ""))
        : [],
    };
  });
  const stats = payload.stats ?? {};
  const validCount = rows.filter((row) => row.valid).length;
  const invalidCount = rows.length - validCount;
  const positionCount = new Set(
    rows.map(registryAuditPhysicalPositionKey),
  ).size;
  const mixedOutcomePositionCount = new Set(
    rows
      .filter((row) => row.positionOutcomeClass === "mixed-valid-and-invalid")
      .map(registryAuditPhysicalPositionKey),
  ).size;
  if (
    stats.rowCount !== rows.length ||
    stats.validCount !== validCount ||
    stats.invalidCount !== invalidCount ||
    stats.positionCount !== positionCount ||
    stats.mixedOutcomePositionCount !== mixedOutcomePositionCount ||
    !Number.isSafeInteger(stats.maxCarrierPayloadBytes) ||
    stats.maxCarrierPayloadBytes < 0 ||
    stats.maxCarrierPayloadBytes > 4 * 1024 * 1024
  ) {
    throw new Error("The relational PWID audit-row bounds are inconsistent.");
  }
  return { rows, stats: { ...stats } };
}

function registryAuditAttemptParity(
  relational,
  confirmedTransactions,
  acceptedEvents,
  replayOutcomes,
  checkpoint,
) {
  const carriers = registryAuditCanonicalPwidCarriers(
    confirmedTransactions,
    checkpoint,
  );
  const carrierByKey = new Map(
    carriers.map((carrier) => [registryAuditPhysicalPositionKey(carrier), carrier]),
  );
  const rowsByKey = new Map();
  for (const row of relational.rows) {
    const key = registryAuditPhysicalPositionKey(row);
    const values = rowsByKey.get(key) ?? [];
    values.push(row);
    rowsByKey.set(key, values);
  }
  const outcomeByKey = new Map();
  const normalizedReplayOutcomes = (
    Array.isArray(replayOutcomes) ? replayOutcomes : []
  ).sort(compareRegistryAuditPhysicalPositions);
  for (const outcome of normalizedReplayOutcomes) {
    const key = registryAuditPhysicalPositionKey(outcome);
    if (
      outcome.blockHeight < PWID_RAW_REPLAY_ACTIVATION_HEIGHT ||
      outcomeByKey.has(key)
    ) {
      throw new Error(`Canonical PWID replay outcome ${key} is duplicated or pre-activation.`);
    }
    outcomeByKey.set(key, outcome);
  }
  if (
    carrierByKey.size !== rowsByKey.size ||
    [...carrierByKey.keys()].some((key) => !rowsByKey.has(key)) ||
    [...rowsByKey.keys()].some((key) => !carrierByKey.has(key))
  ) {
    throw new Error(
      "Canonical Core PWID carrier positions disagree with relational PWID positions.",
    );
  }
  const acceptedByKey = new Map();
  for (const event of Array.isArray(acceptedEvents) ? acceptedEvents : []) {
    const key = registryAuditPhysicalPositionKey(event);
    if (acceptedByKey.has(key)) {
      throw new Error(`Accepted ID lifecycle position ${key} is duplicated.`);
    }
    acceptedByKey.set(key, event);
  }
  const canonicalOutcomes = [];
  const diagnosticRows = [];
  const canonicalRelationalRows = [];
  for (const carrier of carriers) {
    const key = registryAuditPhysicalPositionKey(carrier);
    const rows = rowsByKey.get(key);
    const validRows = rows.filter((row) => row.valid);
    const invalidRows = rows.filter((row) => !row.valid);
    const postActivation =
      carrier.blockHeight >= PWID_RAW_REPLAY_ACTIVATION_HEIGHT;
    if (
      validRows.length > 1 ||
      invalidRows.length > 1 ||
      (validRows.length === 0 && invalidRows.length !== 1) ||
      (postActivation && rows.length !== 1)
    ) {
      throw new Error(`Relational PWID position ${key} has ambiguous outcomes.`);
    }
    if (
      validRows.some(
        (row) =>
          row.rowClassification !== "accepted-candidate" ||
          !["valid-only", "mixed-valid-and-invalid"].includes(
            row.positionOutcomeClass,
          ),
      ) ||
      invalidRows.some((row) =>
        validRows.length === 1
          ? row.rowClassification !== "mixed-outcome-invalid-candidate" ||
            row.positionOutcomeClass !== "mixed-valid-and-invalid"
          : row.rowClassification !== "rejected-candidate" ||
            row.positionOutcomeClass !== "invalid-only",
      )
    ) {
      throw new Error(`Relational PWID position ${key} has unqualified row outcomes.`);
    }
    for (const row of rows) {
      if (
        row.blockHash !== carrier.blockHash ||
        row.blockTime !== carrier.blockTime ||
        row.dataBytes !== carrier.dataBytes ||
        (row.carrierPayloadHex &&
          row.carrierPayloadHex !== carrier.rawPayloadHex) ||
        (row.carrierProtocol && row.carrierProtocol !== "pwid1") ||
        (row.carrierPayload &&
          (!carrier.rawDecodeValid || row.carrierPayload !== carrier.rawPayload))
      ) {
        throw new Error(`Relational PWID position ${key} diverges from Core bytes.`);
      }
      canonicalRelationalRows.push({
        ...row,
        coreRawPayloadHex: carrier.rawPayloadHex,
        coreRawPayloadSha256: carrier.rawPayloadSha256,
        coreScriptPubKeyHex: carrier.scriptPubKeyHex,
        coreScriptPubKeySha256: carrier.scriptPubKeySha256,
      });
    }
    const accepted = acceptedByKey.get(key);
    if (postActivation) {
      const outcome = outcomeByKey.get(key);
      const row = rows[0];
      if (!outcome) {
        throw new Error(`Post-activation PWID carrier ${key} has no replay outcome.`);
      }
      if (
        outcome.blockHash !== carrier.blockHash ||
        outcome.blockIndex !== carrier.blockIndex ||
        outcome.dataBytes !== carrier.dataBytes
      ) {
        throw new Error(`Post-activation PWID replay outcome ${key} diverges from Core.`);
      }
      if (outcome.valid) {
        if (
          !accepted ||
          accepted.blockHash !== carrier.blockHash ||
          accepted.createdAt !== carrier.blockTime ||
          accepted.dataBytes !== carrier.dataBytes ||
          accepted.protocolPayloadSha256 !== carrier.rawPayloadSha256
        ) {
          throw new Error(
            `Accepted post-activation ID lifecycle event at ${key} diverges from Core.`,
          );
        }
      }
      qualifiedPostActivationPwidOutcome({
        acceptedEvent: accepted,
        carrier,
        outcome,
        row,
      });
      canonicalOutcomes.push({
        ...carrier,
        accepted: outcome.valid,
        consensusKind: outcome.consensusKind,
        eventId: row.eventId,
        kind: row.kind,
        reasonCode: outcome.reasonCode,
        semanticKind: outcome.semanticKind,
      });
      continue;
    }

    if (outcomeByKey.has(key)) {
      throw new Error(`Pre-activation PWID carrier ${key} unexpectedly has a raw replay outcome.`);
    }
    if (validRows.length === 1) {
      const validRow = validRows[0];
      if (
        !accepted ||
        validRow.kind !== accepted.kind ||
        accepted.blockHash !== carrier.blockHash ||
        accepted.createdAt !== carrier.blockTime ||
        accepted.dataBytes !== carrier.dataBytes ||
        accepted.protocolPayloadSha256 !== carrier.rawPayloadSha256
      ) {
        throw new Error(
          `Accepted ID lifecycle event at ${key} disagrees with its Core carrier or relational outcome.`,
        );
      }
      for (const row of invalidRows) {
        qualifiedLegacyPwidOutcome({
          accepted: true,
          blockHeight: carrier.blockHeight,
          invalidRow: row,
          parsedAttempt: null,
        });
        diagnosticRows.push(row);
      }
    } else {
      const rejectedRow = invalidRows[0];
      const parsedAttempt = parseIdEventPayload(
        carrier.rawPayload.slice(ID_PROTOCOL_PREFIX.length),
        "livenet",
      );
      if (accepted) {
        throw new Error(`Rejected PWID position ${key} appears as accepted lifecycle state.`);
      }
      qualifiedLegacyPwidOutcome({
        accepted: false,
        blockHeight: carrier.blockHeight,
        expectedRegistrySats: parsedAttempt
          ? idEventMinimumPaymentSats(parsedAttempt.kind)
          : null,
        invalidRow: rejectedRow,
        parsedAttempt,
      });
    }
    canonicalOutcomes.push({
      ...carrier,
      accepted: validRows.length === 1,
      eventId: validRows[0]?.eventId ?? invalidRows[0].eventId,
      kind: validRows[0]?.kind ?? invalidRows[0].kind,
      reasonCode: validRows.length === 0 ? invalidRows[0].reasonCode : "",
    });
  }
  if (
    outcomeByKey.size !== normalizedReplayOutcomes.length ||
    [...outcomeByKey.keys()].some(
      (key) => !carrierByKey.has(key) || !rowsByKey.has(key),
    )
  ) {
    throw new Error(
      "Canonical post-activation PWID replay outcomes lack exact Core or relational coverage.",
    );
  }
  if (
    acceptedByKey.size !== canonicalOutcomes.filter((item) => item.accepted).length ||
    [...acceptedByKey.keys()].some((key) => !carrierByKey.has(key))
  ) {
    throw new Error("Accepted ID lifecycle event coverage is incomplete.");
  }
  const projection = {
    canonicalOutcomes,
    diagnosticRows: diagnosticRows
      .map((row) => ({
        eventId: row.eventId,
        kind: row.kind,
        payloadSource: row.payloadSource,
        reasonCode: row.reasonCode,
        replayBound: row.replayBound,
        replayOutcomeKind: row.replayOutcomeKind,
        replayOutcomeValid: row.replayOutcomeValid,
        rowClassification: row.rowClassification,
        txid: row.txid,
        validationErrors: row.validationErrors,
      }))
      .sort((left, right) => left.eventId - right.eventId),
  };
  return {
    ...relational.stats,
    acceptedPositionCount: canonicalOutcomes.filter((item) => item.accepted).length,
    canonicalReplayOutcomeCount: normalizedReplayOutcomes.length,
    canonicalReplayOutcomeSha256:
      registryAuditProjectionSha256(normalizedReplayOutcomes),
    canonicalOutcomeSha256: registryAuditProjectionSha256(canonicalOutcomes),
    coreBoundRelationalRowsSha256: registryAuditProjectionSha256(
      canonicalRelationalRows.sort((left, right) => left.eventId - right.eventId),
    ),
    diagnosticRowCount: diagnosticRows.length,
    diagnosticSha256: registryAuditProjectionSha256(projection.diagnosticRows),
    legacyPositionCount: carriers.filter(
      (carrier) => carrier.blockHeight < PWID_RAW_REPLAY_ACTIVATION_HEIGHT,
    ).length,
    physicalCarrierComplete: true,
    postActivationPositionCount: carriers.filter(
      (carrier) => carrier.blockHeight >= PWID_RAW_REPLAY_ACTIVATION_HEIGHT,
    ).length,
    relationalRowsSha256: registryAuditProjectionSha256(relational.rows),
    transactionCount: new Set(carriers.map((carrier) => carrier.txid)).size,
    transactionTxidsSha256: txidSetSha256(
      [...new Set(carriers.map((carrier) => carrier.txid))],
    ),
  };
}

async function registryAuditElectrumCheckpoint(checkpoint) {
  const height = registryAuditInteger(
    checkpoint?.height,
    "ID registry audit Electrum checkpoint height",
    1,
  );
  const blockHash = registryAuditTxid(
    checkpoint?.blockHash,
    "ID registry audit Electrum checkpoint hash",
  );
  const headerHex = String(
    await electrumRequest(
      "blockchain.block.header",
      [height],
      ADDRESS_ELECTRUM_HISTORY_TIMEOUT_MS,
    ),
  )
    .trim()
    .toLowerCase();
  const electrumBlockHash = /^[0-9a-f]{160}$/u.test(headerHex)
    ? Buffer.from(bitcoin.crypto.hash256(Buffer.from(headerHex, "hex")))
        .reverse()
        .toString("hex")
    : "";
  if (electrumBlockHash !== blockHash) {
    throw new Error(
      `Electrum is not bound to Bitcoin Core checkpoint ${height}:${blockHash}.`,
    );
  }
  return {
    blockHash,
    headerSha256: createHash("sha256")
      .update(headerHex, "hex")
      .digest("hex"),
    height,
  };
}

function registryAuditReadFence({
  checkpoint,
  coverage,
  electrumCheckpoint,
  indexAuditFence,
  pendingMempoolTimeSha256,
  registryProjectionSha256,
  relationalRowsSha256,
}) {
  const indexScanSnapshotId = String(
    indexAuditFence?.indexScanSnapshotId ?? "",
  ).trim();
  const indexScanStatus = String(
    indexAuditFence?.indexScanStatus ?? "",
  ).trim();
  if (!indexScanSnapshotId || indexScanStatus !== "block-scan-current") {
    throw new Error("The ID registry audit index scan fence is incomplete.");
  }
  const readFence = {
    checkpointHash: registryAuditTxid(
      checkpoint?.blockHash,
      "ID registry audit read fence checkpoint",
    ),
    checkpointHeight: registryAuditInteger(
      checkpoint?.height,
      "ID registry audit read fence height",
      1,
    ),
    confirmedTxidCount: coverage.confirmedTxids.length,
    confirmedTxidsSha256: txidSetSha256(coverage.confirmedTxids),
    electrumCheckpointHash: registryAuditTxid(
      electrumCheckpoint?.blockHash,
      "ID registry audit Electrum checkpoint fence",
    ),
    electrumCheckpointHeight: registryAuditInteger(
      electrumCheckpoint?.height,
      "ID registry audit Electrum checkpoint fence height",
      1,
    ),
    electrumHeaderSha256: registryAuditTxid(
      electrumCheckpoint?.headerSha256,
      "ID registry audit Electrum header fingerprint",
    ),
    pendingMempoolTimeSha256: registryAuditTxid(
      pendingMempoolTimeSha256,
      "ID registry audit pending-time fence",
    ),
    pendingTxidCount: coverage.pendingTxids.length,
    pendingTxidsSha256: txidSetSha256(coverage.pendingTxids),
    registryProjectionSha256: registryAuditTxid(
      registryProjectionSha256,
      "ID registry audit relational projection fence",
    ),
    relationalRowsSha256: registryAuditTxid(
      relationalRowsSha256,
      "ID registry audit relational row fence",
    ),
    transitionCount: registryAuditInteger(
      indexAuditFence?.transitions?.transitionCount,
      "ID registry audit transition fence count",
      1,
    ),
    transitionSha256: registryAuditTxid(
      indexAuditFence?.transitions?.transitionSha256,
      "ID registry audit transition fence",
    ),
    indexScanSnapshotId,
    indexScanStatus,
    snapshotSha256: registryAuditTxid(
      coverage.snapshotSha256,
      "ID registry audit Electrum snapshot fence",
    ),
  };
  return {
    ...readFence,
    fenceSha256: registryAuditProjectionSha256(readFence),
  };
}

async function buildInternalIdRegistryAuditPayload(network) {
  const registryAddress = registryAddressForNetwork(network);
  if (network !== "livenet" || !registryAddress) {
    const error = new Error(
      "Exact ID registry audit coverage is available only for livenet.",
    );
    error.statusCode = 400;
    throw error;
  }

  const initialTip = exactCoreTipFromBlockchainInfo(
    await bitcoinRpc("getblockchaininfo", []),
  );
  if (!initialTip) {
    throw new Error("Bitcoin Core exact tip is unavailable for the ID audit.");
  }
  const initialElectrumCheckpoint = await registryAuditElectrumCheckpoint(
    initialTip,
  );
  const before = electrumAddressHistoryCoverage(
    await fetchExactAddressHistoryFromElectrum(registryAddress, network),
  );
  if (before.pendingTxids.length > ID_REGISTRY_AUDIT_MAX_PENDING_TXS) {
    const error = new Error(
      `Exact ID registry audit pending coverage exceeds the configured limit of ${ID_REGISTRY_AUDIT_MAX_PENDING_TXS}.`,
    );
    error.statusCode = 503;
    throw error;
  }

  const [
    legacyConfirmedTransactions,
    pendingTransactions,
    registryPayload,
  ] = await Promise.all([
    hydrateExactConfirmedRegistryHistory(before.entries, network),
    mapWithConcurrency(
      before.pendingTxids,
      Math.min(2, Math.max(1, TX_FETCH_CONCURRENCY)),
      (txid) => hydrateExactPendingRegistryTransaction(txid, network),
    ),
    proofIndexRegistryPayload(network, {
      expectedHash: initialTip.blockHash,
      expectedHeight: initialTip.height,
      registryAddress,
    }),
  ]);
  const registryProjection = registryAuditProjection(
    registryPayload,
    initialTip,
  );
  const exactTransactions = dedupeTransactions([
    ...legacyConfirmedTransactions,
    ...pendingTransactions,
  ]);
  assertUnambiguousRegistryAuditEvents(exactTransactions);
  const rawReplay = await registryAuditRawReplayWithSpendableListings(
    await registryAuditCanonicalRawReplay(network, initialTip),
    network,
    initialTip,
  );
  const legacyState = idRegistryStateFromTransactions(
    legacyConfirmedTransactions,
    registryAddress,
    network,
    { includeAuditEvents: true },
  );
  const pendingState = idRegistryStateFromTransactions(
    pendingTransactions,
    registryAddress,
    network,
    {
      includeAuditEvents: true,
      initialConfirmedState: rawReplay.closingState,
    },
  );
  const chainProjection = registryAuditProjectionFromCanonicalState(
    {
      ...pendingState,
      _powAuditEvents: legacyState._powAuditEvents,
      sales: [
        ...(Array.isArray(legacyState.sales) ? legacyState.sales : []),
        ...(Array.isArray(pendingState.sales) ? pendingState.sales : []),
      ],
    },
    initialTip,
    rawReplay,
  );
  if (
    chainProjection.projectionSha256 !==
    registryProjection.projectionSha256
  ) {
    const error = new Error(
      "The chain-derived ID lifecycle projection disagrees with the exact relational projection.",
    );
    error.statusCode = 503;
    error.details = {
      chainProjectionSha256: chainProjection.projectionSha256,
      checkpoint: {
        blockHash: initialTip.blockHash,
        height: initialTip.height,
      },
      code: "ID_REGISTRY_LIFECYCLE_PROJECTION_MISMATCH",
      firstDiff: registryAuditFirstProjectionDiff(
        chainProjection,
        registryProjection,
      ),
      registryProjectionSha256: registryProjection.projectionSha256,
      sections: {
        chain: registryAuditProjectionSectionSummary(chainProjection),
        relational: registryAuditProjectionSectionSummary(registryProjection),
      },
    };
    throw error;
  }
  const legacyRelational = registryAuditRelationalAttemptRows(
    registryAuditRelationalPagePayload(rawReplay.legacyRows, initialTip),
    initialTip,
  );
  const legacyParity = registryAuditAttemptParity(
    legacyRelational,
    legacyConfirmedTransactions,
    chainProjection.events.filter(
      (event) =>
        event.blockHeight < PWID_RAW_REPLAY_ACTIVATION_HEIGHT,
    ),
    [],
    initialTip,
  );
  appendRegistryAuditParity(rawReplay.parity, legacyParity, {
    rangeEnd: PWID_RAW_REPLAY_ACTIVATION_HEIGHT - 1,
    rangeKind: "pre-activation",
    rangeStart: 1,
  });
  const attemptParity = finalizedRegistryAuditParity(
    rawReplay.parity,
    rawReplay.indexAudit.fence.relationalRows,
  );
  for (const key of [
    "invalidCount",
    "mixedOutcomePositionCount",
    "positionCount",
    "rowCount",
    "validCount",
  ]) {
    if (attemptParity[key] !== rawReplay.indexAudit.stats[key]) {
      throw new Error(
        `Paged ID attempt parity disagrees with the index ${key} fence.`,
      );
    }
  }
  const relationalClosingState =
    registryAuditRelationalRawClosingState(registryProjection);
  const relationalClosingStateSha256 = registryAuditProjectionSha256(
    relationalClosingState,
  );
  if (
    rawReplay.closingStateSha256 &&
    rawReplay.closingStateSha256 !== relationalClosingStateSha256
  ) {
    const error = new Error(
      "The canonical raw replay closing ID state disagrees with the exact relational projection.",
    );
    error.statusCode = 503;
    throw error;
  }
  const pendingMempoolTimes = pendingTransactions
    .map((transaction) => ({
      mempoolTime: registryAuditInteger(
        transaction?.status?.mempool_time,
        `Observed pending transaction ${transactionTxid(transaction)} mempool time`,
        1,
      ),
      txid: registryAuditTxid(
        transactionTxid(transaction),
        "Observed pending transaction",
      ),
    }))
    .sort((left, right) => compareCanonicalUtf8(left.txid, right.txid));
  const pendingMempoolTimeSha256 = registryAuditProjectionSha256(
    pendingMempoolTimes,
  );
  const finalPendingMembership = await mapWithConcurrency(
    before.pendingTxids,
    Math.min(2, Math.max(1, TX_FETCH_CONCURRENCY)),
    async (txid) => {
      const entry = await bitcoinRpc("getmempoolentry", [txid]);
      if (!entry?.ok || !entry.result || typeof entry.result !== "object") {
        throw new Error(
          `Bitcoin Core no longer contains observed pending registry transaction ${txid}.`,
        );
      }
      return {
        mempoolTime: registryAuditInteger(
          entry.result.time,
          `Final pending transaction ${txid} mempool time`,
          1,
        ),
        txid,
      };
    },
  );
  finalPendingMembership.sort((left, right) =>
    compareCanonicalUtf8(left.txid, right.txid),
  );
  if (
    registryAuditProjectionSha256(finalPendingMembership) !==
      pendingMempoolTimeSha256
  ) {
    throw new Error(
      "Final Core pending registry membership or mempool-time proof changed.",
    );
  }
  const finalIndexAudit = await proofIndexIdRegistryAuditStream(network, {
    expectedHash: initialTip.blockHash,
    expectedHeight: initialTip.height,
    verifyFinalFence: false,
  });
  if (!finalIndexAudit) {
    throw new Error("The final ID relational fence is unavailable.");
  }
  assertIdRegistryAuditFinalFence(
    rawReplay.indexAudit.fence,
    finalIndexAudit.fence,
  );
  // The final Electrum/Core fence is deliberately sampled after every block,
  // transaction, lifecycle, pending-membership, and relational proof above.
  const after = electrumAddressHistoryCoverage(
    await fetchExactAddressHistoryFromElectrum(registryAddress, network),
  );
  const finalTip = exactCoreTipFromBlockchainInfo(
    await bitcoinRpc("getblockchaininfo", []),
  );
  const finalElectrumCheckpoint = await registryAuditElectrumCheckpoint(
    initialTip,
  );
  if (
    before.snapshotSha256 !== after.snapshotSha256 ||
    !finalTip ||
    finalTip.height !== initialTip.height ||
    finalTip.blockHash !== initialTip.blockHash ||
    registryAuditProjectionSha256(finalElectrumCheckpoint) !==
      registryAuditProjectionSha256(initialElectrumCheckpoint)
  ) {
    const error = new Error(
      "The Core checkpoint or Electrum registry history changed while audit coverage was being built.",
    );
    error.statusCode = 503;
    throw error;
  }

  const hydratedPendingTxids = pendingTransactions
    .map(transactionTxid)
    .filter(Boolean)
    .sort();
  if (
    hydratedPendingTxids.length !== before.pendingTxids.length ||
    txidSetSha256(hydratedPendingTxids) !==
      txidSetSha256(before.pendingTxids)
  ) {
    const error = new Error(
      "Exact ID registry pending transaction hydration was partial.",
    );
    error.statusCode = 503;
    throw error;
  }

  const confirmedHistory = new Set(before.confirmedTxids);
  const observedPending = new Set(before.pendingTxids);
  if (
    registryProjection.confirmedRecords.some(
      (record) =>
        !confirmedHistory.has(record.txid) ||
        !confirmedHistory.has(record.lastEventTxid),
    ) ||
    chainProjection.events.some(
      (event) => !confirmedHistory.has(event.txid),
    ) ||
    [...registryProjection.pendingRecords, ...registryProjection.pendingEvents]
      .some((item) => !observedPending.has(item.txid))
  ) {
    const error = new Error(
      "The exact relational ID projection is not a subset of the stable Electrum registry observation.",
    );
    error.statusCode = 503;
    throw error;
  }
  const readFence = registryAuditReadFence({
    checkpoint: initialTip,
    coverage: before,
    electrumCheckpoint: initialElectrumCheckpoint,
    indexAuditFence: rawReplay.indexAudit.fence,
    pendingMempoolTimeSha256,
    registryProjectionSha256: registryProjection.projectionSha256,
    relationalRowsSha256: attemptParity.relationalRowsSha256,
  });

  return {
    auditedAt: new Date().toISOString(),
    coverage: {
      confirmedComplete: true,
      confirmedTxidCount: before.confirmedTxids.length,
      confirmedTxids: before.confirmedTxids,
      confirmedTxidsSha256: txidSetSha256(before.confirmedTxids),
      electrumHistoryEntryCount: before.entries.length,
      lifecycleParity: {
        canonicalRawClosingStateSha256:
          rawReplay.closingStateSha256 || null,
        canonicalRawReplayBlockCount: rawReplay.replayBlockCount,
        canonicalRawReplayBlockPaging:
          "all-transition-discovered-pwid-blocks;bounded-page-recompute",
        canonicalRawReplayDescriptorSha256:
          rawReplay.replayDescriptorSha256 || null,
        canonicalRawListingReconciliation:
          rawReplay.listingReconciliation ?? null,
        canonicalSemantics:
          "legacy-idRegistryStateFromTransactions+post-activation-raw-block-sequencer",
        chainReplayVerified: true,
        projectionSha256: chainProjection.projectionSha256,
        relationalClosingStateSha256:
          rawReplay.closingStateSha256
            ? relationalClosingStateSha256
            : null,
      },
      pwidAttemptParity: {
        ...attemptParity,
        invalidOutcomeSemantics:
          "post-activation-canonical-raw-replay-rejection;pre-activation-qualified-legacy",
        mixedOutcomeRowsQualifiedAs:
          "pre-activation-same-carrier-contradictory-diagnostic-rows-only",
      },
      readFence,
      pendingObservation: {
        completeWithinScope: true,
        coreMembershipProven: true,
        coreMempoolTimeCount: pendingMempoolTimes.length,
        coreMempoolTimeSha256: pendingMempoolTimeSha256,
        fenced: true,
        scope: "registry-address-touching-electrum-observation",
        source: "electrum-address-history+bitcoin-core-membership",
        wholeMempoolComplete: false,
      },
      pendingTxidCount: before.pendingTxids.length,
      pendingTxids: before.pendingTxids,
      pendingTxidsSha256: txidSetSha256(before.pendingTxids),
      snapshotSha256: before.snapshotSha256,
    },
    network,
    pendingTransactions,
    registryAddress,
    registryProjection,
    source: `electrum://${ELECTRUM_HOST}:${ELECTRUM_PORT}+bitcoin-core`,
  };
}

async function registryAuditCorePendingTimeProjection(txids, label) {
  const values = await mapWithConcurrency(
    txids,
    Math.min(2, Math.max(1, TX_FETCH_CONCURRENCY)),
    async (txid) => {
      const entry = await bitcoinRpc("getmempoolentry", [txid]);
      if (!entry?.ok || !entry.result || typeof entry.result !== "object") {
        throw new Error(`${label} lost pending registry transaction ${txid}.`);
      }
      return {
        mempoolTime: registryAuditInteger(
          entry.result.time,
          `${label} transaction ${txid} mempool time`,
          1,
        ),
        txid: registryAuditTxid(txid, `${label} pending transaction`),
      };
    },
  );
  return values.sort((left, right) =>
    compareCanonicalUtf8(left.txid, right.txid),
  );
}

function assertExactRegistryHydration(observedTxids, transactions, label) {
  const observed = [...observedTxids].sort(compareCanonicalUtf8);
  const hydrated = transactions
    .map(transactionTxid)
    .filter(Boolean)
    .sort(compareCanonicalUtf8);
  const observedSha256 = txidSetSha256(observed);
  const hydratedSha256 = txidSetSha256(hydrated);
  if (
    hydrated.length !== observed.length ||
    new Set(hydrated).size !== hydrated.length ||
    hydratedSha256 !== observedSha256
  ) {
    throw registryAuthorityUnavailable(
      `The first-party ${label} registry hydration was partial.`,
      {
        hydratedCount: hydrated.length,
        hydratedSha256,
        observedCount: observed.length,
        observedSha256,
      },
    );
  }
  return {
    hydratedCount: hydrated.length,
    hydratedSha256,
    observedCount: observed.length,
    observedSha256,
  };
}

async function buildInternalRegistryParityPayload(network) {
  const registryAddress = registryAddressForNetwork(network);
  if (network !== "livenet" || !registryAddress) {
    const error = new Error(
      "Strict first-party registry parity is available only for livenet.",
    );
    error.statusCode = 400;
    throw error;
  }

  const initialTip = exactCoreTipFromBlockchainInfo(
    await bitcoinRpc("getblockchaininfo", []),
  );
  if (!initialTip) {
    throw registryAuthorityUnavailable(
      "Bitcoin Core exact tip is unavailable for registry parity.",
    );
  }
  const initialElectrumCheckpoint = await registryAuditElectrumCheckpoint(
    initialTip,
  );
  const before = electrumAddressHistoryCoverage(
    await fetchExactAddressHistoryFromElectrum(registryAddress, network),
  );
  if (before.confirmedTxids.length === 0) {
    throw registryAuthorityUnavailable(
      "Electrum returned no confirmed livenet registry history.",
    );
  }
  if (before.pendingTxids.length > ID_REGISTRY_AUDIT_MAX_PENDING_TXS) {
    throw registryAuthorityUnavailable(
      "Strict registry parity pending coverage exceeds its live bound.",
      {
        limit: ID_REGISTRY_AUDIT_MAX_PENDING_TXS,
        pendingCount: before.pendingTxids.length,
      },
    );
  }
  const initialPendingTimes = await registryAuditCorePendingTimeProjection(
    before.pendingTxids,
    "Initial registry parity fence",
  );
  const [confirmedTransactions, pendingTransactions] = await Promise.all([
    hydrateExactConfirmedRegistryHistory(before.entries, network, {
      allHeights: true,
      bypassCache: true,
      cacheResult: false,
    }),
    mapWithConcurrency(
      before.pendingTxids,
      Math.min(2, Math.max(1, TX_FETCH_CONCURRENCY)),
      (txid) => hydrateExactPendingRegistryTransaction(txid, network),
    ),
  ]);
  const confirmedHydration = assertExactRegistryHydration(
    before.confirmedTxids,
    confirmedTransactions,
    "confirmed",
  );
  const pendingHydration = assertExactRegistryHydration(
    before.pendingTxids,
    pendingTransactions,
    "pending",
  );
  const transactions = dedupeTransactions([
    ...confirmedTransactions,
    ...pendingTransactions,
  ]);
  if (transactions.length !== before.entries.length) {
    throw registryAuthorityUnavailable(
      "The first-party registry transaction set is incomplete.",
      {
        hydratedCount: transactions.length,
        observedCount: before.entries.length,
      },
    );
  }

  const generatedAt = new Date().toISOString();
  const state = idRegistryStateFromTransactions(
    transactions,
    registryAddress,
    network,
    { includeAuditEvents: true },
  );
  const unresolvedPayload = registryPayloadFromState(state, {
    indexedAt: generatedAt,
    indexedThroughBlock: initialTip.height,
    indexedThroughBlockHash: initialTip.blockHash,
    listings: state.listings,
    network,
    registryAddress,
    source: `electrum://${ELECTRUM_HOST}:${ELECTRUM_PORT}+bitcoin-core`,
    transactionCount: transactions.length,
  });
  const listingReconciliation = await strictCoreRegistryListingReconciliation(
    unresolvedPayload,
    network,
    { checkpoint: initialTip, verifyFinalTip: false },
  );

  const finalPendingTimes = await registryAuditCorePendingTimeProjection(
    before.pendingTxids,
    "Final registry parity fence",
  );
  const after = electrumAddressHistoryCoverage(
    await fetchExactAddressHistoryFromElectrum(registryAddress, network),
  );
  const finalTip = exactCoreTipFromBlockchainInfo(
    await bitcoinRpc("getblockchaininfo", []),
  );
  if (
    !finalTip ||
    finalTip.height !== initialTip.height ||
    finalTip.blockHash !== initialTip.blockHash
  ) {
    throw registryAuthorityUnavailable(
      "Bitcoin Core changed while strict registry parity was built.",
    );
  }
  const finalElectrumCheckpoint = await registryAuditElectrumCheckpoint(
    finalTip,
  );
  const initialPendingSha256 = registryAuditProjectionSha256(
    initialPendingTimes,
  );
  const finalPendingSha256 = registryAuditProjectionSha256(finalPendingTimes);
  if (
    before.snapshotSha256 !== after.snapshotSha256 ||
    initialPendingSha256 !== finalPendingSha256 ||
    registryAuditProjectionSha256(initialElectrumCheckpoint) !==
      registryAuditProjectionSha256(finalElectrumCheckpoint)
  ) {
    throw registryAuthorityUnavailable(
      "The Electrum/Core registry observation changed during strict parity.",
    );
  }

  const source = String(listingReconciliation.payload.source ?? "");
  return {
    ...listingReconciliation.payload,
    _powRegistryParityAuthority: {
      core: {
        after: { ...finalTip },
        before: { ...initialTip },
      },
      electrum: {
        after: {
          ...finalElectrumCheckpoint,
          confirmedTxidCount: after.confirmedTxids.length,
          confirmedTxidsSha256: txidSetSha256(after.confirmedTxids),
          historyEntryCount: after.entries.length,
          pendingTxidCount: after.pendingTxids.length,
          pendingTxidsSha256: txidSetSha256(after.pendingTxids),
          snapshotSha256: after.snapshotSha256,
        },
        before: {
          ...initialElectrumCheckpoint,
          confirmedTxidCount: before.confirmedTxids.length,
          confirmedTxidsSha256: txidSetSha256(before.confirmedTxids),
          historyEntryCount: before.entries.length,
          pendingTxidCount: before.pendingTxids.length,
          pendingTxidsSha256: txidSetSha256(before.pendingTxids),
          snapshotSha256: before.snapshotSha256,
        },
      },
      generatedAt,
      hydration: {
        confirmed: confirmedHydration,
        pending: pendingHydration,
        totalHydrated: transactions.length,
        totalObserved: before.entries.length,
      },
      listingReconciliation: listingReconciliation.evidence,
      model: "proof-registry-first-party-fenced-v1",
      network,
      pendingMempoolTime: {
        afterSha256: finalPendingSha256,
        beforeSha256: initialPendingSha256,
        count: initialPendingTimes.length,
      },
      source,
    },
  };
}

async function buildInternalIdRegistryAuditFencePayload(network) {
  const registryAddress = registryAddressForNetwork(network);
  if (network !== "livenet" || !registryAddress) {
    const error = new Error(
      "Exact ID registry audit fencing is available only for livenet.",
    );
    error.statusCode = 400;
    throw error;
  }
  const initialTip = exactCoreTipFromBlockchainInfo(
    await bitcoinRpc("getblockchaininfo", []),
  );
  if (!initialTip) {
    throw new Error("Bitcoin Core exact tip is unavailable for the ID audit fence.");
  }
  const initialElectrumCheckpoint = await registryAuditElectrumCheckpoint(
    initialTip,
  );
  const before = electrumAddressHistoryCoverage(
    await fetchExactAddressHistoryFromElectrum(registryAddress, network),
  );
  if (before.pendingTxids.length > ID_REGISTRY_AUDIT_MAX_PENDING_TXS) {
    throw new Error("ID registry audit pending fence exceeds its live bound.");
  }
  const initialPendingTimes = await registryAuditCorePendingTimeProjection(
    before.pendingTxids,
    "Initial ID audit fence",
  );
  const [registryPayload, indexAudit] = await Promise.all([
    proofIndexRegistryPayload(network, {
      expectedHash: initialTip.blockHash,
      expectedHeight: initialTip.height,
      registryAddress,
    }),
    proofIndexIdRegistryAuditStream(network, {
      expectedHash: initialTip.blockHash,
      expectedHeight: initialTip.height,
      verifyFinalFence: false,
    }),
  ]);
  const registryProjection = registryAuditProjection(
    registryPayload,
    initialTip,
  );
  if (!indexAudit) {
    throw new Error("The lightweight ID relational fence is unavailable.");
  }
  const finalIndexAudit = await proofIndexIdRegistryAuditStream(network, {
    expectedHash: initialTip.blockHash,
    expectedHeight: initialTip.height,
    verifyFinalFence: false,
  });
  if (!finalIndexAudit) {
    throw new Error("The final lightweight ID relational fence is unavailable.");
  }
  assertIdRegistryAuditFinalFence(indexAudit.fence, finalIndexAudit.fence);
  const finalPendingTimes = await registryAuditCorePendingTimeProjection(
    before.pendingTxids,
    "Final ID audit fence",
  );
  const after = electrumAddressHistoryCoverage(
    await fetchExactAddressHistoryFromElectrum(registryAddress, network),
  );
  const finalTip = exactCoreTipFromBlockchainInfo(
    await bitcoinRpc("getblockchaininfo", []),
  );
  const finalElectrumCheckpoint = await registryAuditElectrumCheckpoint(
    initialTip,
  );
  const pendingMempoolTimeSha256 = registryAuditProjectionSha256(
    initialPendingTimes,
  );
  if (
    registryAuditProjectionSha256(finalPendingTimes) !==
      pendingMempoolTimeSha256 ||
    before.snapshotSha256 !== after.snapshotSha256 ||
    !finalTip ||
    finalTip.height !== initialTip.height ||
    finalTip.blockHash !== initialTip.blockHash ||
    registryAuditProjectionSha256(finalElectrumCheckpoint) !==
      registryAuditProjectionSha256(initialElectrumCheckpoint)
  ) {
    const error = new Error(
      "The Core/Electrum state changed while the lightweight ID audit fence was sampled.",
    );
    error.statusCode = 503;
    throw error;
  }
  return {
    network,
    readFence: registryAuditReadFence({
      checkpoint: initialTip,
      coverage: before,
      electrumCheckpoint: initialElectrumCheckpoint,
      indexAuditFence: indexAudit.fence,
      pendingMempoolTimeSha256,
      registryProjectionSha256: registryProjection.projectionSha256,
      relationalRowsSha256: indexAudit.fence.relationalRows.sha256,
    }),
    source:
      "electrum+bitcoin-core+proof-indexer-lightweight-id-registry-fence",
  };
}

const ID_REGISTRY_AUDIT_INFLIGHT = new Map();
const ID_REGISTRY_AUDIT_FENCE_INFLIGHT = new Map();
const REGISTRY_PARITY_INFLIGHT = new Map();

async function internalRegistryParityPayload(network) {
  if (REGISTRY_PARITY_INFLIGHT.has(network)) {
    return REGISTRY_PARITY_INFLIGHT.get(network);
  }
  const promise = buildInternalRegistryParityPayload(network)
    .catch((error) => {
      if (!Number.isSafeInteger(error?.statusCode)) {
        error.statusCode = 503;
      }
      throw error;
    })
    .finally(() => {
      REGISTRY_PARITY_INFLIGHT.delete(network);
    });
  REGISTRY_PARITY_INFLIGHT.set(network, promise);
  return promise;
}

async function internalIdRegistryAuditPayload(network) {
  if (ID_REGISTRY_AUDIT_INFLIGHT.has(network)) {
    return ID_REGISTRY_AUDIT_INFLIGHT.get(network);
  }
  const promise = buildInternalIdRegistryAuditPayload(network)
    .catch((error) => {
      if (!Number.isSafeInteger(error?.statusCode)) {
        error.statusCode = 503;
      }
      throw error;
    })
    .finally(() => {
      ID_REGISTRY_AUDIT_INFLIGHT.delete(network);
    });
  ID_REGISTRY_AUDIT_INFLIGHT.set(network, promise);
  return promise;
}

async function internalIdRegistryAuditFencePayload(network) {
  if (ID_REGISTRY_AUDIT_FENCE_INFLIGHT.has(network)) {
    return ID_REGISTRY_AUDIT_FENCE_INFLIGHT.get(network);
  }
  const promise = buildInternalIdRegistryAuditFencePayload(network)
    .catch((error) => {
      if (!Number.isSafeInteger(error?.statusCode)) {
        error.statusCode = 503;
      }
      throw error;
    })
    .finally(() => {
      ID_REGISTRY_AUDIT_FENCE_INFLIGHT.delete(network);
    });
  ID_REGISTRY_AUDIT_FENCE_INFLIGHT.set(network, promise);
  return promise;
}

async function electrumPendingScripthashEntries(scriptHash) {
  try {
    const entries = await electrumRequest(
      "blockchain.scripthash.get_mempool",
      [scriptHash],
      HEALTH_CHECK_TIMEOUT_MS,
    );
    if (!Array.isArray(entries)) {
      throw new Error("Electrum returned an invalid pending response.");
    }
    return entries;
  } catch (error) {
    if (!/method not found/iu.test(errorSummary(error))) {
      throw error;
    }
    const history = await electrumRequest(
      "blockchain.scripthash.get_history",
      [scriptHash],
      HEALTH_CHECK_TIMEOUT_MS,
    );
    if (!Array.isArray(history)) {
      throw new Error("Electrum returned an invalid address history response.");
    }
    return history.filter((entry) => Number(entry?.height) <= 0);
  }
}

async function livePendingRegistryPayload(network) {
  const registryAddress = registryAddressForNetwork(network);
  if (!registryAddress) {
    throw new Error("ProofOfWork ID registry is not configured.");
  }
  let transactions = null;
  let source = "";
  for (const baseUrl of firstPartyAddressReadBases(network)) {
    try {
      transactions = await fetchAddressTransactionsPageFromBase(
        baseUrl,
        registryAddress,
        "txs/mempool",
        { timeoutMs: HEALTH_CHECK_TIMEOUT_MS },
      );
      source = baseUrl;
      break;
    } catch {
      // Try the next first-party reader before the local Electrum fallback.
    }
  }
  if (
    transactions === null &&
    network === "livenet" &&
    String(ELECTRUM_HOST).trim() &&
    ELECTRUM_PORT > 0
  ) {
    const entries = await electrumPendingScripthashEntries(
      scriptHashForAddress(registryAddress, network),
    );
    const txids = [
      ...new Set(
        entries
          .map((entry) => String(entry?.tx_hash ?? "").toLowerCase())
          .filter((txid) => /^[0-9a-f]{64}$/u.test(txid)),
      ),
    ];
    transactions = await mapWithConcurrency(
      txids,
      Math.min(4, Math.max(1, TX_FETCH_CONCURRENCY)),
      (txid) => fetchTransactionWithSourceFallback(txid, network),
    );
    if (transactions.some((tx) => !tx)) {
      throw new Error("A pending registry transaction could not be loaded.");
    }
    source = `electrum://${ELECTRUM_HOST}:${ELECTRUM_PORT}`;
  }
  if (transactions === null) {
    throw new Error("No healthy first-party pending registry reader is available.");
  }
  const state = idRegistryStateFromTransactions(
    dedupeTransactions(transactions),
    registryAddress,
    network,
  );
  return {
    ...state,
    indexedAt: new Date().toISOString(),
    network,
    registryAddress,
    source,
  };
}

async function proveCurrentIdAbsence(network) {
  const [scan, tipResponse, pending] = await Promise.all([
    proofIndexOperationalStatusPayload(network),
    bitcoinRpc("getblockchaininfo", []),
    livePendingRegistryPayload(network),
  ]);
  const tip = exactCoreTipFromBlockchainInfo(tipResponse);
  const tipHeight = tip?.height;
  const indexedThroughBlock = Number(scan?.indexedThroughBlock) || 0;
  const workerReadiness = proofIndexWorkerExactTipReadiness(scan, {
    network,
    tipHash: tip?.blockHash,
    tipHeight,
  });
  const current =
    Boolean(scan) &&
    scan?.scan?.complete === true &&
    Boolean(String(scan?.scan?.blockHash ?? "")) &&
    Number.isSafeInteger(tipHeight) &&
    indexedThroughBlock === tipHeight &&
    workerReadiness.ready === true &&
    Number(scan?.readModels?.confirmedIds?.count) > 0;
  if (!current) {
    const error = new Error(
      "ProofOfWork ID availability cannot be proven until the confirmed index reaches the node tip.",
    );
    error.statusCode = 503;
    error.details = {
      code: "ID_AVAILABILITY_UNPROVEN",
      indexedThroughBlock: indexedThroughBlock || null,
      tipHeight: Number.isSafeInteger(tipHeight) ? tipHeight : null,
    };
    throw error;
  }
  return pending;
}

function promiseOutcomeWithin(promise, timeoutMs) {
  let timer;
  const timeout = Math.max(1, Number(timeoutMs) || 1);
  return Promise.race([
    Promise.resolve(promise).then(
      (value) => ({ ok: true, timedOut: false, value }),
      (error) => ({ error, ok: false, timedOut: false, value: null }),
    ),
    new Promise((resolve) => {
      timer = setTimeout(
        () => resolve({ ok: false, timedOut: true, value: null }),
        timeout,
      );
    }),
  ]).finally(() => clearTimeout(timer));
}

async function healthNodeTipHeight() {
  const rpc = await bitcoinRpc("getblockcount", []).catch(() => null);
  const rpcHeight = Number(rpc?.result);
  if (rpc?.ok && Number.isSafeInteger(rpcHeight) && rpcHeight > 0) {
    return rpcHeight;
  }
  return ledgerTipHeight("livenet");
}

async function addressIndexHealthPayload(timeoutMs = HEALTH_CHECK_TIMEOUT_MS) {
  const registryAddress = registryAddressForNetwork("livenet");
  if (!registryAddress) {
    return { error: "Registry address is not configured.", ok: false };
  }
  const requestTimeoutMs = Math.max(
    1,
    Math.min(HEALTH_CHECK_TIMEOUT_MS, Number(timeoutMs) || 1),
  );
  if (String(ELECTRUM_HOST).trim() && ELECTRUM_PORT > 0) {
    const balanceOutcome = await promiseOutcomeWithin(
      interactiveElectrumRequest(
        "blockchain.scripthash.get_balance",
        [ELECTRUM_HEALTH_SCRIPTHASH],
        requestTimeoutMs,
      ),
      requestTimeoutMs,
    );
    const confirmedSats = balanceOutcome.value?.confirmed;
    const unconfirmedSats = balanceOutcome.value?.unconfirmed;
    const valid =
      balanceOutcome.ok &&
      Number.isSafeInteger(confirmedSats) &&
      confirmedSats === 0 &&
      Number.isSafeInteger(unconfirmedSats) &&
      unconfirmedSats === 0;
    return {
      canary: {
        confirmedSats: Number.isSafeInteger(confirmedSats)
          ? confirmedSats
          : null,
        scripthash: ELECTRUM_HEALTH_SCRIPTHASH,
        unconfirmedSats: Number.isSafeInteger(unconfirmedSats)
          ? unconfirmedSats
          : null,
      },
      error: valid
        ? ""
        : errorSummary(
            balanceOutcome.error ??
              new Error("Electrum returned an invalid balance response."),
          ),
      ok: valid,
      source: `electrum://${ELECTRUM_HOST}:${ELECTRUM_PORT}`,
      timedOut: balanceOutcome.timedOut === true,
    };
  }
  for (const baseUrl of firstPartyAddressReadBases("livenet")) {
    const outcome = await promiseOutcomeWithin(
      fetchAddressTransactionsPageFromBase(
        baseUrl,
        registryAddress,
        "txs/mempool",
        { timeoutMs: requestTimeoutMs },
      ),
      requestTimeoutMs,
    );
    if (outcome.ok) {
      return {
        itemCount: Array.isArray(outcome.value) ? outcome.value.length : 0,
        ok: true,
        source: baseUrl,
      };
    }
  }
  return { error: "No first-party address index is configured.", ok: false };
}

async function electrumHealthPayload(
  expectedHeight,
  expectedHash,
  timeoutMs = HEALTH_CHECK_TIMEOUT_MS,
) {
  if (!String(ELECTRUM_HOST).trim() || ELECTRUM_PORT <= 0) {
    return { configured: false, ok: true };
  }
  const height = Number(expectedHeight);
  const coreHash = String(expectedHash ?? "").trim().toLowerCase();
  if (
    !Number.isSafeInteger(height) ||
    height <= 0 ||
    !/^[0-9a-f]{64}$/u.test(coreHash)
  ) {
    return {
      configured: true,
      error: "Bitcoin Core tip is unavailable for the Electrum health proof.",
      headerHash: null,
      headerHeight: Number.isSafeInteger(height) ? height : null,
      ok: false,
      timedOut: false,
    };
  }
  const headerOutcome = await promiseOutcomeWithin(
    interactiveElectrumRequest(
      "blockchain.block.header",
      [height],
      Math.max(1, Math.min(HEALTH_CHECK_TIMEOUT_MS, Number(timeoutMs) || 1)),
    ),
    Math.max(1, Math.min(HEALTH_CHECK_TIMEOUT_MS, Number(timeoutMs) || 1)),
  );
  const headerHex =
    typeof headerOutcome.value === "string"
      ? headerOutcome.value.trim().toLowerCase()
      : "";
  const headerHash = /^[0-9a-f]{160}$/u.test(headerHex)
    ? Buffer.from(
        bitcoin.crypto.hash256(Buffer.from(headerHex, "hex")),
      )
        .reverse()
        .toString("hex")
    : "";
  const ok = headerOutcome.ok && headerHash === coreHash;
  const mismatchError = headerHash
    ? `Electrum block header does not match Bitcoin Core at height ${height}.`
    : "Electrum returned an invalid block header.";
  return {
    configured: true,
    error: ok
      ? ""
      : errorSummary(headerOutcome.error ?? new Error(mismatchError)),
    headerHash: headerHash || null,
    headerHeight: height,
    ok,
    timedOut: headerOutcome.timedOut === true,
  };
}

async function boundedHealthElectrumPayload(
  addressIndex,
  expectedHeight,
  expectedHash,
  deadlineMs,
) {
  if (!String(ELECTRUM_HOST).trim() || ELECTRUM_PORT <= 0) {
    return electrumHealthPayload(expectedHeight, expectedHash);
  }
  if (addressIndex?.ok !== true) {
    return {
      configured: true,
      error:
        "Electrum tip proof was skipped because the bounded address-index canary failed.",
      headerHash: null,
      headerHeight: Number.isSafeInteger(Number(expectedHeight))
        ? Number(expectedHeight)
        : null,
      ok: false,
      timedOut: addressIndex?.timedOut === true,
    };
  }
  const remainingMs = Math.floor(Number(deadlineMs) - Date.now());
  const headerTimeoutMs = Math.max(
    1,
    Math.min(
      HEALTH_CHECK_TIMEOUT_MS,
      Math.max(
        Number.isSafeInteger(remainingMs) ? remainingMs : 0,
        HEALTH_ELECTRUM_TIP_PROOF_TIMEOUT_MS,
      ),
    ),
  );
  return electrumHealthPayload(
    expectedHeight,
    expectedHash,
    headerTimeoutMs,
  );
}

async function filesystemHealthPayload(targetPath) {
  let probePath = path.resolve(targetPath);
  let stats;
  while (true) {
    try {
      stats = await fs.statfs(probePath);
      break;
    } catch (error) {
      const parent = path.dirname(probePath);
      if (error?.code !== "ENOENT" || parent === probePath) {
        return { error: errorSummary(error), ok: false, path: targetPath };
      }
      probePath = parent;
    }
  }
  const blockSize = Number(stats.bsize ?? 0);
  const totalBytes = Number(stats.blocks ?? 0) * blockSize;
  const availableBytes = Number(stats.bavail ?? 0) * blockSize;
  const usedPercent =
    totalBytes > 0 ? ((totalBytes - availableBytes) / totalBytes) * 100 : null;
  const ok =
    totalBytes > 0 &&
    availableBytes >= HEALTH_DISK_MIN_FREE_BYTES &&
    usedPercent !== null &&
    usedPercent <= HEALTH_DISK_MAX_USED_PERCENT;
  return {
    availableBytes,
    maxUsedPercent: HEALTH_DISK_MAX_USED_PERCENT,
    minFreeBytes: HEALTH_DISK_MIN_FREE_BYTES,
    ok,
    path: targetPath,
    probePath,
    totalBytes,
    usedPercent,
  };
}

async function loadHealthPayload() {
  const electrumHealthDeadlineMs =
    Date.now() + Math.max(1, HEALTH_CHECK_TIMEOUT_MS - 250);
  const [
    databaseOutcome,
    canonicalOutcome,
    tipOutcome,
    txindexOutcome,
    backendOutcome,
    addressIndex,
    rootDisk,
    cacheDisk,
  ] = await Promise.all([
    promiseOutcomeWithin(
      proofIndexOperationalStatusPayload("livenet"),
      HEALTH_CHECK_TIMEOUT_MS,
    ),
    promiseOutcomeWithin(
      proofIndexCanonicalStateMetaPayload("livenet"),
      HEALTH_CHECK_TIMEOUT_MS,
    ),
    promiseOutcomeWithin(
      bitcoinRpc("getblockchaininfo", []),
      HEALTH_CHECK_TIMEOUT_MS,
    ),
    promiseOutcomeWithin(
      bitcoinRpc("getindexinfo", ["txindex"]),
      HEALTH_CHECK_TIMEOUT_MS,
    ),
    promiseOutcomeWithin(
      fetchJson(`${MEMPOOL_BASE_MAINNET}/api/v1/backend-info`, {
        signal: AbortSignal.timeout(HEALTH_CHECK_TIMEOUT_MS),
      }),
      HEALTH_CHECK_TIMEOUT_MS,
    ),
    addressIndexHealthPayload(
      Math.max(1, electrumHealthDeadlineMs - Date.now()),
    ),
    filesystemHealthPayload("/"),
    filesystemHealthPayload(PERSISTED_CACHE_DIR),
  ]);
  const database = databaseOutcome.ok ? databaseOutcome.value : null;
  const canonical = canonicalOutcome.ok ? canonicalOutcome.value : null;
  const chainInfo = tipOutcome.value?.ok ? tipOutcome.value.result : null;
  const txindexInfo = txindexOutcome.value?.ok
    ? txindexOutcome.value.result?.txindex
    : null;
  const coreAuthority = exactCoreNodeAuthority(
    tipOutcome.ok ? tipOutcome.value : null,
    txindexOutcome.ok ? txindexOutcome.value : null,
  );
  const tipHeight = Number(chainInfo?.blocks);
  const sampledBestBlockHash = String(chainInfo?.bestblockhash ?? "")
    .trim()
    .toLowerCase();
  const electrum = await boundedHealthElectrumPayload(
    addressIndex,
    tipHeight,
    sampledBestBlockHash,
    electrumHealthDeadlineMs,
  );
  const indexedThroughBlock = Number(database?.indexedThroughBlock) || 0;
  const checkpointOutcome =
    indexedThroughBlock > 0 && indexedThroughBlock !== tipHeight
      ? await promiseOutcomeWithin(
          bitcoinRpc("getblockhash", [indexedThroughBlock]),
          HEALTH_CHECK_TIMEOUT_MS,
        )
      : { ok: indexedThroughBlock === tipHeight, value: null };
  const canonicalCheckpointHash = String(
    indexedThroughBlock === tipHeight
      ? sampledBestBlockHash
      : checkpointOutcome.value?.ok
        ? checkpointOutcome.value.result
        : "",
  )
    .trim()
    .toLowerCase();
  const storedCheckpointHash = String(database?.scan?.blockHash ?? "")
    .trim()
    .toLowerCase();
  const checkpointCanonical =
    /^[0-9a-f]{64}$/u.test(storedCheckpointHash) &&
    canonicalCheckpointHash === storedCheckpointHash;
  const lagBlocks =
    Number.isSafeInteger(tipHeight) && indexedThroughBlock > 0
      ? Math.max(0, tipHeight - indexedThroughBlock)
      : null;
  const aheadBlocks =
    Number.isSafeInteger(tipHeight) && indexedThroughBlock > 0
      ? Math.max(0, indexedThroughBlock - tipHeight)
      : null;
  const workerReadiness = proofIndexWorkerExactTipReadiness(database, {
    network: "livenet",
    tipHash: sampledBestBlockHash,
    tipHeight,
  });
  const workerAgeMs = workerReadiness.ageMs;
  const workerFresh = workerReadiness.fresh;
  const workerNoProgress =
    database?.worker?.noProgress &&
    typeof database.worker.noProgress === "object" &&
    !Array.isArray(database.worker.noProgress) &&
    database.worker.network === "livenet" &&
    database.worker.noProgress.network === "livenet"
      ? database.worker.noProgress
      : null;
  const workerContainmentActive = workerNoProgress?.active === true;
  const workerOk = workerReadiness.ready === true;
  const pendingHealthEnvelope = workerReadiness.q16Required
    ? database?.worker?.lastSuccess
    : database?.worker;
  const pendingEventHealth =
    pendingHealthEnvelope?.pendingEventHealth &&
    typeof pendingHealthEnvelope.pendingEventHealth === "object" &&
    !Array.isArray(pendingHealthEnvelope.pendingEventHealth)
      ? pendingHealthEnvelope.pendingEventHealth
      : null;
  const pendingStatus =
    pendingHealthEnvelope?.pendingStatus &&
    typeof pendingHealthEnvelope.pendingStatus === "object" &&
    !Array.isArray(pendingHealthEnvelope.pendingStatus)
      ? pendingHealthEnvelope.pendingStatus
      : null;
  const pendingEventHealthRequired = workerReadiness.q16Required;
  const pendingGlobalUnresolved = pendingEventHealth?.globalUnresolved;
  const pendingQ16Unresolved = pendingEventHealth?.q16PendingUnresolved;
  const pendingEventHealthOk =
    !pendingEventHealthRequired ||
    (pendingEventHealth?.model ===
      "bounded-best-effort-pending-event-health-v1" &&
      pendingEventHealth?.required === true &&
      pendingEventHealth?.scope ===
        "all-observed-pending-protocol-events" &&
      Number.isSafeInteger(pendingGlobalUnresolved) &&
      pendingGlobalUnresolved === 0 &&
      Number.isSafeInteger(pendingQ16Unresolved) &&
      pendingQ16Unresolved === 0 &&
      pendingEventHealth?.ok === true);
  const pendingStatusErrors = pendingStatus?.errors;
  const pendingStatusChecked = pendingStatus?.checked;
  const pendingStatusDeferred = pendingStatus?.deferred;
  const pendingStatusQ16ParentDeferred = pendingStatus?.q16ParentDeferred;
  const pendingStatusStaleCandidates = pendingStatus?.staleCandidates;
  const pendingStatusUnavailable = pendingStatus?.unavailable === true;
  const pendingStatusUnavailableValid =
    pendingStatus?.unavailable === undefined ||
    pendingStatus?.unavailable === false;
  const pendingStatusQ16ParentDeferredOk =
    pendingStatusQ16ParentDeferred === undefined ||
    (Number.isSafeInteger(pendingStatusQ16ParentDeferred) &&
      pendingStatusQ16ParentDeferred >= 0);
  const pendingStatusOk =
    !pendingEventHealthRequired ||
    (Number.isSafeInteger(pendingStatusChecked) &&
      pendingStatusChecked >= 0 &&
      Number.isSafeInteger(pendingStatusDeferred) &&
      pendingStatusDeferred === 0 &&
      Number.isSafeInteger(pendingStatusStaleCandidates) &&
      pendingStatusStaleCandidates >= 0 &&
      pendingStatusChecked === pendingStatusStaleCandidates &&
      Number.isSafeInteger(pendingStatusErrors) &&
      pendingStatusErrors === 0 &&
      pendingStatusQ16ParentDeferredOk &&
      pendingStatusUnavailableValid);
  const pendingAccuracyOk = pendingEventHealthOk && pendingStatusOk;
  const canonicalFault = canonical?.fault ?? {};
  const canonicalRebuild = canonical?.rebuild ?? {};
  const rebuildTrustState = canonicalRebuildTrustState(
    canonicalRebuild,
    "livenet",
  );
  const canonicalStateOk =
    Boolean(canonical) &&
    Boolean(canonical?.rebuild) &&
    canonicalFault?.active !== true &&
    rebuildTrustState === "complete";
  const electrumAtTip =
    electrum.configured !== true ||
    (Number.isSafeInteger(tipHeight) && electrum.headerHeight === tipHeight);
  const readModelsOk =
    Number(database?.readModels?.confirmedIds?.count) > 0 &&
    Number(database?.readModels?.confirmedTransfers?.count) > 0;
  const summarySnapshotOk =
    summarySnapshotCoversCanonicalReadModels(database);
  const indexOk =
    Boolean(database) &&
    database?.scan?.complete === true &&
    checkpointCanonical &&
    lagBlocks === 0 &&
    aheadBlocks === 0 &&
    canonicalStateOk &&
    workerOk &&
    pendingAccuracyOk &&
    readModelsOk &&
    summarySnapshotOk;
  const indexAvailable =
    Boolean(database) &&
    database?.scan?.complete === true &&
    checkpointCanonical &&
    aheadBlocks === 0 &&
    canonicalStateOk &&
    readModelsOk;
  const diskOk = rootDisk.ok && cacheDisk.ok;
  const available =
    coreAuthority !== null &&
    backendOutcome.ok &&
    addressIndex.ok &&
    electrum.ok &&
    electrumAtTip &&
    diskOk &&
    (PROOF_INDEX_REQUIRED ? indexAvailable : true);
  const ok = available && (PROOF_INDEX_REQUIRED ? indexOk : true);

  return {
    available,
    backend: backendOutcome.ok ? backendOutcome.value?.backend ?? null : null,
    checks: {
      addressIndex,
      backend: { ok: backendOutcome.ok, timedOut: backendOutcome.timedOut },
      database: {
        canonicalMetaOk: canonicalOutcome.ok && Boolean(canonical),
        ok:
          databaseOutcome.ok &&
          Boolean(database) &&
          canonicalOutcome.ok &&
          Boolean(canonical),
        required: PROOF_INDEX_REQUIRED,
        timedOut: databaseOutcome.timedOut,
      },
      disk: { cache: cacheDisk, ok: diskOk, root: rootDisk },
      electrum: {
        ...electrum,
        atTip: electrumAtTip,
        ok: electrum.ok && electrumAtTip,
      },
      index: {
        aheadBlocks,
        checkpointHash: database?.scan?.blockHash ?? "",
        complete: database?.scan?.complete === true,
        canonicalState: {
          fault: canonicalFault,
          ok: canonicalStateOk,
          rebuild: canonicalRebuild,
        },
        checkpointCanonical,
        canonicalCheckpointHash,
        indexedThroughBlock,
        lagBlocks,
        available: indexAvailable,
        ok: indexOk,
        readModels: database?.readModels ?? null,
        summarySnapshot: {
          ...(database?.summarySnapshot ?? {}),
          ok: summarySnapshotOk,
        },
        scanTipHeight: database?.scan?.tipHeight ?? null,
        stopReason: database?.scan?.stopReason ?? "",
      },
      node: {
        bestBlockHash: sampledBestBlockHash || null,
        chain: String(chainInfo?.chain ?? ""),
        headers: Number.isSafeInteger(Number(chainInfo?.headers))
          ? Number(chainInfo.headers)
          : null,
        initialBlockDownload: chainInfo?.initialblockdownload === true,
        ok: coreAuthority !== null,
        pruned:
          typeof chainInfo?.pruned === "boolean" ? chainInfo.pruned : null,
        tipHeight,
        txindexHeight: Number.isSafeInteger(Number(txindexInfo?.best_block_height))
          ? Number(txindexInfo.best_block_height)
          : null,
        txindexSynced: txindexInfo?.synced === true,
        verificationProgress: Number.isFinite(
            Number(chainInfo?.verificationprogress),
          )
          ? Number(chainInfo.verificationprogress)
          : null,
      },
      worker: {
        ageMs: workerAgeMs,
        containment: {
          active: workerContainmentActive,
          checkpointHash: String(workerNoProgress?.checkpointHash ?? ""),
          checkpointHeight:
            workerNoProgress?.checkpointHeight !== null &&
            workerNoProgress?.checkpointHeight !== undefined &&
            Number.isSafeInteger(Number(workerNoProgress.checkpointHeight))
            ? Number(workerNoProgress.checkpointHeight)
            : null,
          failingBlockHeight:
            workerNoProgress?.failingBlockHeight !== null &&
            workerNoProgress?.failingBlockHeight !== undefined &&
            Number.isSafeInteger(Number(workerNoProgress.failingBlockHeight))
            ? Number(workerNoProgress.failingBlockHeight)
            : null,
          fingerprint: String(workerNoProgress?.fingerprint ?? ""),
          network: String(workerNoProgress?.network ?? ""),
          nextRetryAt: workerNoProgress
            ? String(
                database?.worker?.nextRetryAt ??
                  workerNoProgress?.nextRetryAt ??
                  "",
              ) || null
            : null,
          reason: String(workerNoProgress?.reason ?? ""),
          repeatCount: Number(workerNoProgress?.repeatCount ?? 0),
          txid: String(workerNoProgress?.txid ?? ""),
        },
        consecutiveFailures: Number(
          database?.worker?.consecutiveFailures ?? 0,
        ),
        error: String(database?.worker?.error ?? ""),
        lastSuccessAt: workerReadiness.lastSuccessAt,
        maxAgeMs: PROOF_INDEX_HEALTH_MAX_AGE_MS,
        ok: workerOk && pendingAccuracyOk,
        proofReady: workerReadiness.proofReady,
        proofSource: workerReadiness.proofSource,
        pendingEvents: {
          globalUnresolved:
            Number.isSafeInteger(pendingGlobalUnresolved)
              ? pendingGlobalUnresolved
              : null,
          model: String(pendingEventHealth?.model ?? ""),
          ok: pendingEventHealthOk,
          q16PendingUnresolved:
            Number.isSafeInteger(pendingQ16Unresolved)
              ? pendingQ16Unresolved
              : null,
          required: pendingEventHealthRequired,
          scope: String(pendingEventHealth?.scope ?? ""),
          status: {
            checked: Number.isSafeInteger(pendingStatus?.checked)
              ? pendingStatus.checked
              : null,
            deferred: Number.isSafeInteger(pendingStatus?.deferred)
              ? pendingStatus.deferred
              : null,
            errors: Number.isSafeInteger(pendingStatusErrors)
              ? pendingStatusErrors
              : null,
            ok: pendingStatusOk,
            q16ParentDeferred: Number.isSafeInteger(
              pendingStatusQ16ParentDeferred,
            )
              ? pendingStatusQ16ParentDeferred
              : null,
            staleCandidates: Number.isSafeInteger(
              pendingStatusStaleCandidates,
            )
              ? pendingStatusStaleCandidates
              : null,
            unavailable: pendingStatusUnavailable,
            unavailableValid: pendingStatusUnavailableValid,
          },
        },
        phase: database?.worker?.phase ?? database?.worker?.state ?? null,
      },
    },
    indexedAt: new Date().toISOString(),
    indexedThroughBlock,
    lagBlocks,
    mempoolBase: MEMPOOL_BASE_MAINNET,
    ok,
    ready: ok,
    service: "proofofwork-op-return-api",
    tipHeight: Number.isSafeInteger(tipHeight) ? tipHeight : null,
  };
}

let healthPayloadCache = null;

async function healthPayload(options = {}) {
  if (options.force === true) {
    return loadHealthPayload();
  }
  const now = Date.now();
  if (
    healthPayloadCache &&
    (!healthPayloadCache.settled || healthPayloadCache.expiresAt > now)
  ) {
    return healthPayloadCache.promise;
  }
  const entry = {
    expiresAt: Number.POSITIVE_INFINITY,
    promise: null,
    settled: false,
  };
  entry.promise = loadHealthPayload();
  healthPayloadCache = entry;
  try {
    const payload = await entry.promise;
    entry.expiresAt = Date.now() + HEALTH_PAYLOAD_CACHE_TTL_MS;
    entry.settled = true;
    return payload;
  } catch (error) {
    if (healthPayloadCache === entry) {
      healthPayloadCache = null;
    }
    throw error;
  } finally {
    if (!entry.settled && healthPayloadCache === entry) {
      healthPayloadCache = null;
    }
  }
}

const CANONICAL_PUBLIC_READ_GATE_TTL_MS = 2_000;
const CANONICAL_PUBLIC_READ_GATE_TIMEOUT_MS = Math.min(
  30_000,
  Math.max(
    HEALTH_CHECK_TIMEOUT_MS,
    Number(process.env.POW_API_CANONICAL_GATE_TIMEOUT_MS ?? 15_000) || 15_000,
  ),
);
const CANONICAL_PUBLIC_READ_GATE_TIMEOUT_TTL_MS = Math.min(
  10_000,
  Math.max(
    1_000,
    Number(process.env.POW_API_CANONICAL_GATE_TIMEOUT_TTL_MS ?? 2_000) || 2_000,
  ),
);
const CANONICAL_PUBLIC_READ_GATE_TIP_ATTEMPTS = Math.min(
  4,
  Math.max(
    1,
    Math.floor(Number(process.env.POW_API_CANONICAL_GATE_TIP_ATTEMPTS ?? 3) || 3),
  ),
);
const CANONICAL_PUBLIC_READ_GATE_TIP_RETRY_DELAY_MS = Math.min(
  2_000,
  Math.max(
    0,
    Number(process.env.POW_API_CANONICAL_GATE_TIP_RETRY_DELAY_MS ?? 250) || 250,
  ),
);
const canonicalPublicReadGateCache = new Map();
const CANONICAL_FRESH_LAST_GOOD_MAX_LAG_BLOCKS = Math.min(
  6,
  Math.max(
    0,
    Math.floor(
      Number(process.env.POW_API_FRESH_LAST_GOOD_MAX_LAG_BLOCKS ?? 1) || 1,
    ),
  ),
);

function canonicalPublicReadGateApplies(pathname) {
  const path = String(pathname ?? "");
  if (!path.startsWith("/api/v1/")) {
    return false;
  }
  if (/^\/api\/v1\/address\/[^/]+\/(?:utxo|txs(?:\/.*)?)$/u.test(path)) {
    return false;
  }
  return ![
    "/api/v1/internal/",
    "/api/v1/broadcast/",
    "/api/v1/block/",
    "/api/v1/prices/",
    "/api/v1/tx/",
  ].some((prefix) => path.startsWith(prefix));
}

function canonicalSummarySnapshotReadGateApplies(pathname) {
  return new Set([
    "/api/v1/activity-summary",
    "/api/v1/consistency",
    "/api/v1/growth-summary",
    "/api/v1/inception-summary",
    "/api/v1/infinity-summary",
    "/api/v1/ledger-consistency",
    "/api/v1/log-summary",
    "/api/v1/marketplace-summary",
    "/api/v1/work-floor",
    "/api/v1/work-summary",
  ]).has(String(pathname ?? ""));
}

function canonicalFreshReadCanUseLastGood(url, gate) {
  const pathname = String(url?.pathname ?? "");
  if (!canonicalGateCanUseBoundedLastGood(gate)) {
    return false;
  }
  if (canonicalSummarySnapshotReadGateApplies(pathname)) {
    return gate.summarySnapshotOk === true;
  }
  if (pathname !== "/api/v1/token") {
    return false;
  }
  const params = url.searchParams;
  const tokenScope = normalizeTokenScope(
    params.get("asset") ?? params.get("tokenId") ?? params.get("ticker") ?? "",
  );
  const walletReadRequested = /^(?:1|true|yes)$/iu.test(
    String(params.get("wallet") ?? "").trim(),
  );
  const walletScopedRead =
    walletReadRequested &&
    (params.has("address") || params.has("addresses"));
  const unaddressedPublicRead =
    !walletReadRequested &&
    !params.has("address") &&
    !params.has("addresses");
  return (
    unaddressedPublicRead ||
    (tokenScope === WORK_TOKEN_ID && walletScopedRead)
  );
}

function summarySnapshotCoversCanonicalReadModels(status) {
  const summaryIndexedThroughBlock = Number(
    status?.summarySnapshot?.indexedThroughBlock ?? 0,
  );
  const indexedThroughBlock = Number(status?.indexedThroughBlock ?? 0);
  const scanTipHeight = Number(status?.scan?.tipHeight ?? 0);
  const summaryBlockHash = String(status?.summarySnapshot?.blockHash ?? "")
    .trim()
    .toLowerCase();
  const scanBlockHash = String(status?.scan?.blockHash ?? "")
    .trim()
    .toLowerCase();
  return (
    status?.summarySnapshot?.eligible === true &&
    Number.isSafeInteger(summaryIndexedThroughBlock) &&
    summaryIndexedThroughBlock > 0 &&
    summaryIndexedThroughBlock === indexedThroughBlock &&
    indexedThroughBlock === scanTipHeight &&
    /^[0-9a-f]{64}$/u.test(summaryBlockHash) &&
    summaryBlockHash === scanBlockHash
  );
}

function proofIndexWorkerExactTipReadiness(
  status,
  { network, nowMs = Date.now(), tipHash, tipHeight },
) {
  const worker = status?.worker && typeof status.worker === "object"
    ? status.worker
    : {};
  const lastSuccessAt = String(worker.lastSuccessAt ?? "");
  const lastSuccessMs = Date.parse(lastSuccessAt);
  const ageMs = Number.isFinite(lastSuccessMs)
    ? Math.max(0, Number(nowMs) - lastSuccessMs)
    : null;
  const fresh =
    ageMs !== null &&
    Number.isFinite(Number(nowMs)) &&
    ageMs <= PROOF_INDEX_HEALTH_MAX_AGE_MS;
  const normalizedTipHash = String(tipHash ?? "").trim().toLowerCase();
  const storedHash = String(status?.scan?.blockHash ?? "")
    .trim()
    .toLowerCase();
  const exactTip =
    status?.network === network &&
    status?.scan?.complete === true &&
    Number.isSafeInteger(tipHeight) &&
    Number(status?.indexedThroughBlock) === tipHeight &&
    Number(status?.scan?.tipHeight) === tipHeight &&
    /^[0-9a-f]{64}$/u.test(normalizedTipHash) &&
    storedHash === normalizedTipHash;
  const q16Required =
    worker?.workPrecision?.era === "q16" ||
    worker?.lastSuccess?.workPrecision?.era === "q16" ||
    !Number.isSafeInteger(WORK_AMO_V8_ACTIVATION_HEIGHT) ||
    (Number.isSafeInteger(tipHeight) &&
      tipHeight >= WORK_AMO_V8_ACTIVATION_HEIGHT);
  const durable = exactWorkAmoV8WorkerLastSuccessReadiness(status, {
    network,
    tipHash: normalizedTipHash,
    tipHeight,
  });
  const proofReady = q16Required
    ? durable.ready === true
    : worker.network === network &&
      worker.ok === true &&
      durable.failureActive !== true;
  return {
    ageMs,
    failureActive: durable.failureActive === true,
    fresh,
    lastSuccessAt: Number.isFinite(lastSuccessMs) ? lastSuccessAt : null,
    proofReady,
    proofSource: q16Required
      ? String(durable.proofSource ?? "")
      : "current-worker",
    q16Required,
    ready: exactTip && fresh && proofReady,
  };
}

async function loadCanonicalPublicReadGate(network) {
  if (network !== "livenet" || !PROOF_INDEX_REQUIRED) {
    return { ok: true };
  }
  const [status, canonical, tipProbe] = await Promise.all([
    proofIndexOperationalStatusPayload(network),
    proofIndexCanonicalStateMetaPayload(network),
    (async () => {
      let lastError = null;
      let tipResponse = null;
      for (
        let attempt = 0;
        attempt < CANONICAL_PUBLIC_READ_GATE_TIP_ATTEMPTS;
        attempt += 1
      ) {
        if (
          attempt > 0 &&
          CANONICAL_PUBLIC_READ_GATE_TIP_RETRY_DELAY_MS > 0
        ) {
          await new Promise((resolve) =>
            setTimeout(
              resolve,
              CANONICAL_PUBLIC_READ_GATE_TIP_RETRY_DELAY_MS * attempt,
            )
          );
        }
        try {
          tipResponse = await bitcoinRpc("getblockchaininfo", []);
          const exactCoreTip = exactCoreTipFromBlockchainInfo(tipResponse);
          if (exactCoreTip) {
            return {
              attempts: attempt + 1,
              exactCoreTip,
              tipError: "",
              tipResponse,
            };
          }
          if (tipResponse?.ok === true) {
            break;
          }
        } catch (error) {
          lastError = error;
          tipResponse = null;
        }
      }
      return {
        attempts: CANONICAL_PUBLIC_READ_GATE_TIP_ATTEMPTS,
        exactCoreTip: null,
        tipError: String(lastError?.message ?? lastError ?? ""),
        tipResponse,
      };
    })(),
  ]);
  const indexedThroughBlock = Number(status?.indexedThroughBlock) || 0;
  const tipResponse = tipProbe.tipResponse;
  const exactCoreTip = exactCoreTipFromBlockchainInfo(tipResponse);
  const tipHeight = exactCoreTip?.height;
  const bestBlockHash = exactCoreTip?.blockHash ?? "";
  const storedHash = String(status?.scan?.blockHash ?? "").toLowerCase();
  const indexedHashResponse =
    Number.isSafeInteger(indexedThroughBlock) &&
    indexedThroughBlock > 0 &&
    indexedThroughBlock !== tipHeight
      ? await bitcoinRpc("getblockhash", [indexedThroughBlock]).catch(() => null)
      : null;
  const canonicalHash = String(
    indexedThroughBlock === tipHeight
      ? bestBlockHash
      : indexedHashResponse?.ok
        ? indexedHashResponse.result
        : "",
  )
    .trim()
    .toLowerCase();
  const rebuild = canonical?.rebuild ?? {};
  const fault = canonical?.fault ?? {};
  const rebuildTrustState = canonicalRebuildTrustState(rebuild, network);
  const workerReadiness = proofIndexWorkerExactTipReadiness(status, {
    network,
    tipHash: bestBlockHash,
    tipHeight,
  });
  const workerFresh = workerReadiness.fresh;
  const readModelsOk =
    Number(status?.readModels?.confirmedIds?.count) > 0 &&
    Number(status?.readModels?.confirmedTransfers?.count) > 0;
  const summarySnapshotOk =
    summarySnapshotCoversCanonicalReadModels(status);
  const available =
    Boolean(status) &&
    Boolean(canonical) &&
    status?.scan?.complete === true &&
    Number.isSafeInteger(tipHeight) &&
    indexedThroughBlock > 0 &&
    indexedThroughBlock <= tipHeight &&
    /^[0-9a-f]{64}$/u.test(storedHash) &&
    canonicalHash === storedHash &&
    fault?.active !== true &&
    Boolean(canonical?.rebuild) &&
    rebuildTrustState === "complete" &&
    readModelsOk;
  const atTip =
    available &&
    indexedThroughBlock === tipHeight;
  const broadcastReady = atTip;
  const ready =
    broadcastReady &&
    workerReadiness.ready === true;
  return {
    atTip,
    available,
    canonicalHash: canonicalHash || null,
    fault,
    indexedThroughBlock: indexedThroughBlock || null,
    lagBlocks:
      Number.isSafeInteger(tipHeight) && indexedThroughBlock > 0
        ? Math.max(0, tipHeight - indexedThroughBlock)
        : null,
    ok: available,
    ready,
    broadcastReady,
    rebuild,
    storedHash: storedHash || null,
    tipHeight: Number.isSafeInteger(tipHeight) ? tipHeight : null,
    workerFresh,
    workerOk: workerReadiness.proofReady,
    workerProofSource: workerReadiness.proofSource,
    readModelsOk,
    summarySnapshot: status?.summarySnapshot ?? null,
    summarySnapshotOk,
  };
}

async function canonicalPublicReadGate(network, options = {}) {
  if (options.force === true) {
    const outcome = await promiseOutcomeWithin(
      loadCanonicalPublicReadGate(network),
      CANONICAL_PUBLIC_READ_GATE_TIMEOUT_MS,
    );
    return outcome.ok
      ? outcome.value
      : {
          error: outcome.timedOut
            ? "Canonical read gate timed out."
            : errorSummary(outcome.error),
          ok: false,
          timedOut: outcome.timedOut === true,
        };
  }
  const now = Date.now();
  const cached = canonicalPublicReadGateCache.get(network);
  if (
    cached &&
    (!cached.settled || cached.expiresAt > now)
  ) {
    return cached.promise;
  }
  const entry = {
    expiresAt: Number.POSITIVE_INFINITY,
    network,
    promise: null,
    settled: false,
  };
  const promise = promiseOutcomeWithin(
    loadCanonicalPublicReadGate(network),
    CANONICAL_PUBLIC_READ_GATE_TIMEOUT_MS,
  )
    .then((outcome) => {
      entry.expiresAt =
        Date.now() +
        (outcome.timedOut
          ? CANONICAL_PUBLIC_READ_GATE_TIMEOUT_TTL_MS
          : CANONICAL_PUBLIC_READ_GATE_TTL_MS);
      entry.settled = true;
      return outcome.ok
        ? outcome.value
        : {
            error: outcome.timedOut
              ? "Canonical read gate timed out."
              : errorSummary(outcome.error),
            ok: false,
            timedOut: outcome.timedOut === true,
          };
    })
    .catch((error) => {
      entry.expiresAt = Date.now() + CANONICAL_PUBLIC_READ_GATE_TTL_MS;
      entry.settled = true;
      return { error: errorSummary(error), ok: false };
  });
  entry.promise = promise;
  canonicalPublicReadGateCache.set(network, entry);
  return promise;
}

async function handleRequest(request, response) {
  if (request.method === "OPTIONS") {
    optionsResponse(response);
    return;
  }

  const url = new URL(
    request.url ?? "/",
    `http://${request.headers.host ?? "localhost"}`,
  );
  const pathParts = url.pathname.split("/").filter(Boolean);

  try {
    if (
      request.method === "POST" &&
      url.pathname === "/api/v1/broadcast/slipstream"
    ) {
      jsonResponse(
        response,
        200,
        await withBroadcastAdmission(
          request,
          "livenet",
          (admission) => broadcastSlipstreamPayload(request, admission),
          { requireCanonical: true },
        ),
        "no-store",
      );
      return;
    }

    if (
      request.method === "POST" &&
      url.pathname === "/api/v1/broadcast/tx"
    ) {
      const broadcastNetwork = networkFromSearch(url.searchParams);
      jsonResponse(
        response,
        200,
        await withBroadcastAdmission(
          request,
          broadcastNetwork,
          (admission) =>
            broadcastNodePayload(request, broadcastNetwork, admission),
          { requireCanonical: true },
        ),
        "no-store",
      );
      return;
    }

    if (
      request.method === "POST" &&
      url.pathname ===
        "/api/v1/internal/work-amo-v5-seed-evidence"
    ) {
      if (!internalVerifierRequestAllowed(request)) {
        errorResponse(response, 404, "Not found.");
        return;
      }
      const payload = await readJsonRequestBody(request, 64_000, {
        label: "AMO V5 H-1 seed-evidence body",
        timeoutMs: 15_000,
      });
      const requestedNetwork = String(payload?.network ?? "")
        .trim()
        .toLowerCase();
      const requestedReplayBindingId =
        url.searchParams.get("replayBindingId") ?? "";
      const replayVerifierBinding = await internalReplayVerifierBinding(
        requestedNetwork,
        requestedReplayBindingId,
      );
      jsonResponse(
        response,
        200,
        await internalReplayBoundPayload(
          requestedNetwork,
          requestedReplayBindingId,
          await workAmoV5HMinusOneSeedEvidencePayload(
            requestedNetwork,
            payload,
          ),
          replayVerifierBinding,
        ),
        "no-store",
      );
      return;
    }

    if (
      request.method === "POST" &&
      url.pathname ===
        "/api/v1/internal/work-amo-v5-block-verifier"
    ) {
      if (!internalVerifierRequestAllowed(request)) {
        errorResponse(response, 404, "Not found.");
        return;
      }
      const payload = await readJsonRequestBody(request, 64_000, {
        label: "AMO V5 block verifier body",
        timeoutMs: 15_000,
      });
      const requestedNetwork = String(payload?.network ?? "")
        .trim()
        .toLowerCase();
      const requestedReplayBindingId =
        url.searchParams.get("replayBindingId") ?? "";
      const replayVerifierBinding = await internalReplayVerifierBinding(
        requestedNetwork,
        requestedReplayBindingId,
      );
      jsonResponse(
        response,
        200,
        await internalReplayBoundPayload(
          requestedNetwork,
          requestedReplayBindingId,
          await workAmoV5BlockVerifierPayload(
            requestedNetwork,
            payload,
          ),
          replayVerifierBinding,
        ),
        "no-store",
      );
      return;
    }

    if (
      request.method === "POST" &&
      url.pathname ===
        "/api/v1/internal/pending-work-verifier-stage"
    ) {
      if (!internalVerifierRequestAllowed(request)) {
        errorResponse(response, 404, "Not found.");
        return;
      }
      try {
        const payload = await readJsonRequestBody(request, 1_000_000, {
          label: "pending WORK verifier stage body",
          timeoutMs: 15_000,
        });
        jsonResponse(
          response,
          200,
          await pendingWorkVerifierStagePayload(payload),
          "no-store",
        );
      } catch (error) {
        if (error?.statusCode === 503) {
          throw error;
        }
        throw pendingWorkVerifierStageError(
          "PENDING_WORK_STAGE_UNAVAILABLE",
          "Pending WORK verifier stage could not be built.",
          { reason: errorSummary(error) },
        );
      }
      return;
    }

    if (request.method !== "GET") {
      errorResponse(response, 405, "Method not allowed.");
      return;
    }

    if (url.pathname === "/api/v1/broadcast/slipstream/status") {
      jsonResponse(response, 200, slipstreamStatusPayload(), "no-store");
      return;
    }

    if (
      url.pathname === "/health" ||
      url.pathname === "/api/v1/health" ||
      url.pathname === "/health/live" ||
      url.pathname === "/api/v1/health/live"
    ) {
      const livenessRead = url.pathname.endsWith("/live");
      const payload = await healthPayload({ force: !livenessRead });
      jsonResponse(
        response,
        (livenessRead ? payload.available : payload.ready) ? 200 : 503,
        {
          ...payload,
          mode: livenessRead ? "availability" : "readiness",
        },
        "no-store",
      );
      return;
    }

    const network = networkFromSearch(url.searchParams);
    const freshRead = freshReadRequested(url.searchParams);

    const authenticatedLoopbackRead = internalVerifierRequestAllowed(request);
    let canonicalReadGate = null;
    let serveFreshLastGood = false;
    if (
      canonicalPublicReadGateApplies(url.pathname) &&
      !authenticatedLoopbackRead
    ) {
      const gate = await canonicalPublicReadGate(network, { force: freshRead });
      canonicalReadGate = gate;
      if (!gate.ok) {
        errorResponse(
          response,
          503,
          "The canonical ProofOfWork index is rebuilding or no longer matches Bitcoin Core.",
          { code: "CANONICAL_INDEX_UNAVAILABLE", ...gate },
        );
        return;
      }
      serveFreshLastGood =
        freshRead && canonicalFreshReadCanUseLastGood(url, gate);
      if (freshRead && gate.atTip !== true && !serveFreshLastGood) {
        errorResponse(
          response,
          503,
          "The canonical ProofOfWork index is catching up to the Bitcoin Core tip.",
          { code: "CANONICAL_INDEX_CATCHING_UP", ...gate },
        );
        return;
      }
      if (
        freshRead &&
        canonicalSummarySnapshotReadGateApplies(url.pathname) &&
        !gate.summarySnapshotOk
      ) {
        errorResponse(
          response,
          503,
          "The canonical ProofOfWork summary snapshot is catching up.",
          { code: "CANONICAL_SUMMARY_UNAVAILABLE", ...gate },
        );
        return;
      }
    }

    if (url.pathname === "/api/v1/internal/registry-parity") {
      if (!internalVerifierRequestAllowed(request)) {
        errorResponse(response, 404, "Not found.");
        return;
      }
      jsonResponse(
        response,
        200,
        await internalRegistryParityPayload(network),
        "no-store",
      );
      return;
    }

    if (url.pathname === "/api/v1/internal/token-verifier") {
      if (!internalVerifierRequestAllowed(request)) {
        errorResponse(response, 404, "Not found.");
        return;
      }
      const requestedReplayBindingId =
        url.searchParams.get("replayBindingId") ?? "";
      const replayVerifierBinding = await internalReplayVerifierBinding(
        network,
        requestedReplayBindingId,
      );
      jsonResponse(
        response,
        200,
        await internalReplayBoundPayload(
          network,
          requestedReplayBindingId,
          await tokenVerifierPayload(
            network,
            url.searchParams.get("asset") ?? "",
            url.searchParams.get("txid") ?? "",
            {
              blockHash: url.searchParams.get("blockHash") ?? "",
              blockHeight: Number(url.searchParams.get("blockHeight") ?? 0),
              previousBlockHash:
                url.searchParams.get("previousBlockHash") ?? "",
              requireConfirmed: /^(?:1|true|yes)$/iu.test(
                String(url.searchParams.get("confirmed") ?? ""),
              ),
              replayVerifierBinding,
            },
          ),
          replayVerifierBinding,
        ),
        "no-store",
      );
      return;
    }

    if (url.pathname === "/api/v1/internal/canonical-summary") {
      if (!internalVerifierRequestAllowed(request)) {
        errorResponse(response, 404, "Not found.");
        return;
      }
      const storedExact =
        String(url.searchParams.get("storedExact") ?? "") === "1";
      const checkpointHeight = Number(
        url.searchParams.get("checkpointHeight") ?? 0,
      );
      const checkpointHash = String(
        url.searchParams.get("checkpointHash") ?? "",
      )
        .trim()
        .toLowerCase();
      const exactCheckpointValid =
        Number.isSafeInteger(checkpointHeight) &&
        checkpointHeight > 0 &&
        /^[0-9a-f]{64}$/u.test(checkpointHash);
      const requestedReplayBindingId =
        url.searchParams.get("replayBindingId") ?? "";
      const replayVerifierBinding = await internalReplayVerifierBinding(
        network,
        requestedReplayBindingId,
      );
      const exactRead = storedExact
        ? exactCheckpointValid
          ? await proofIndexCanonicalSummaryLedgerPayload(
              network,
              checkpointHeight,
              checkpointHash,
              { exactStatus: true },
            )
          : {
              eligibleSnapshotCount: 0,
              exactSnapshot: null,
              status: "invalid-request",
            }
        : null;
      const payload = storedExact
        ? {
            eligibleSnapshotCount:
              exactRead?.eligibleSnapshotCount ?? 0,
            exactSnapshot: exactRead?.exactSnapshot ?? null,
            exactSnapshotStatus:
              exactRead?.status ?? "unavailable",
            network,
            source: "proof-indexer-exact-canonical-summary-snapshot",
          }
        : await internalCanonicalSummaryPayload(network, {
            checkpointHash,
            checkpointHeight,
          });
      jsonResponse(
        response,
        200,
        await internalReplayBoundPayload(
          network,
          requestedReplayBindingId,
          payload,
          replayVerifierBinding,
        ),
        "no-store",
      );
      return;
    }

    if (url.pathname === "/api/v1/internal/id-registry-audit-fence") {
      if (!internalVerifierRequestAllowed(request)) {
        errorResponse(response, 404, "Not found.");
        return;
      }
      jsonResponse(
        response,
        200,
        await internalIdRegistryAuditFencePayload(network),
        "no-store",
      );
      return;
    }

    if (url.pathname === "/api/v1/internal/id-registry-audit") {
      if (!internalVerifierRequestAllowed(request)) {
        errorResponse(response, 404, "Not found.");
        return;
      }
      jsonResponse(
        response,
        200,
        await internalIdRegistryAuditPayload(network),
        "no-store",
      );
      return;
    }

    if (url.pathname === "/api/v1/internal/id-verifier") {
      if (!internalVerifierRequestAllowed(request)) {
        errorResponse(response, 404, "Not found.");
        return;
      }
      const requestedReplayBindingId =
        url.searchParams.get("replayBindingId") ?? "";
      const replayVerifierBinding = await internalReplayVerifierBinding(
        network,
        requestedReplayBindingId,
      );
      jsonResponse(
        response,
        200,
        await internalReplayBoundPayload(
          network,
          requestedReplayBindingId,
          await idVerifierPayload(
            network,
            url.searchParams.get("txid") ?? "",
            {
              blockHash: url.searchParams.get("blockHash") ?? "",
              blockHeight: Number(url.searchParams.get("blockHeight") ?? 0),
              previousBlockHash:
                url.searchParams.get("previousBlockHash") ?? "",
              requireConfirmed: /^(?:1|true|yes)$/iu.test(
                String(url.searchParams.get("confirmed") ?? ""),
              ),
            },
          ),
          replayVerifierBinding,
        ),
        "no-store",
      );
      return;
    }

    if (url.pathname === "/api/v1/prices/btc-usd") {
      jsonResponse(
        response,
        200,
        await btcUsdPricePayload(network, { fresh: freshRead }),
        freshRead ? FRESH_READ_CACHE_CONTROL : "public, max-age=60",
      );
      return;
    }

    if (
      pathParts.length === 5 &&
      pathParts[0] === "api" &&
      pathParts[1] === "v1" &&
      pathParts[2] === "block" &&
      pathParts[4] === "txids"
    ) {
      const blockHash = pathParts[3].toLowerCase();
      if (!/^[0-9a-f]{64}$/u.test(blockHash)) {
        errorResponse(response, 400, "Invalid block hash.");
        return;
      }

      jsonResponse(
        response,
        200,
        await fetchBlockTxids(blockHash, network),
        "public, max-age=300",
      );
      return;
    }

    if (
      url.pathname === "/api/v1/registry-summary" ||
      url.pathname === "/api/v1/ids-summary"
    ) {
      jsonResponse(
        response,
        200,
        await registrySummaryPayload(network, freshRead),
        freshRead ? FRESH_READ_CACHE_CONTROL : EXPENSIVE_READ_CACHE_CONTROL,
      );
      return;
    }

    if (url.pathname === "/api/v1/registry" || url.pathname === "/api/v1/ids") {
      jsonResponse(
        response,
        200,
        await strictPublicRegistryPayload(network, { fresh: freshRead }),
        network === "livenet"
          ? FRESH_READ_CACHE_CONTROL
          : freshRead
            ? FRESH_READ_CACHE_CONTROL
            : EXPENSIVE_READ_CACHE_CONTROL,
      );
      return;
    }

    if (
      url.pathname === "/api/v1/registry-history" ||
      url.pathname === "/api/v1/ids-history"
    ) {
      const historyKind = String(url.searchParams.get("kind") ?? "records")
        .trim()
        .toLowerCase();
      jsonResponse(
        response,
        200,
        await registryHistoryPayload(
          network,
          historyKind,
          url.searchParams,
          freshRead,
        ),
        freshRead ? FRESH_READ_CACHE_CONTROL : EXPENSIVE_READ_CACHE_CONTROL,
      );
      return;
    }

    if (
      url.pathname === "/api/v1/activity-summary" ||
      url.pathname === "/api/v1/log-summary"
    ) {
      jsonResponse(
        response,
        200,
        await summaryPayloadWithCanonicalProvenance(
          await activitySummaryPayload(network, freshRead),
          network,
          freshRead,
          "log-summary",
        ),
        freshRead ? FRESH_READ_CACHE_CONTROL : EXPENSIVE_READ_CACHE_CONTROL,
      );
      return;
    }

    if (
      url.pathname === "/api/v1/consistency" ||
      url.pathname === "/api/v1/ledger-consistency"
    ) {
      jsonResponse(
        response,
        200,
        await ledgerConsistencyPayload(network, freshRead),
        freshRead ? FRESH_READ_CACHE_CONTROL : READ_CACHE_CONTROL,
      );
      return;
    }

    if (
      url.pathname === "/api/v1/events" ||
      url.pathname === "/api/v1/event-history" ||
      url.pathname === "/api/v1/protocol-events"
    ) {
      if (proofIndexReadFeatureEnabled("event-history,events")) {
        const indexedPayload = await proofIndexEventHistoryPayload(
          network,
          url.searchParams,
        );
        if (indexedPayload) {
          jsonResponse(
            response,
            200,
            indexedPayload,
            EXPENSIVE_READ_CACHE_CONTROL,
          );
          return;
        }
      }
      errorResponse(response, 404, "Database event history is not available.");
      return;
    }

    if (url.pathname === "/api/v1/boost") {
      jsonResponse(
        response,
        200,
        await boostFeedPayload(network, url.searchParams, freshRead),
        freshRead ? FRESH_READ_CACHE_CONTROL : EXPENSIVE_READ_CACHE_CONTROL,
      );
      return;
    }

    if (url.pathname === "/api/v1/activity" || url.pathname === "/api/v1/log") {
      const logHistoryLikeRequest =
        url.pathname === "/api/v1/log" &&
        [
          "kind",
          "q",
          "search",
          "txid",
          "transaction",
          "transactionId",
          "cursor",
          "limit",
          "offset",
          "page",
        ].some((key) => url.searchParams.has(key));
      if (logHistoryLikeRequest) {
        const historyKind = String(url.searchParams.get("kind") ?? "")
          .trim()
          .toLowerCase();
        const logHistoryEligibility = proofIndexLogHistoryReadEligibility(
          historyKind,
          url.searchParams,
        );
        const exactLogQueryTxid = /^[0-9a-f]{64}$/u.test(
          logHistoryEligibility.pagination.query,
        )
          ? logHistoryEligibility.pagination.query
          : "";
        const indexedPayload =
          network === "livenet" && !freshRead
            ? await stableProofIndexLogHistoryPayload(
                network,
                historyKind,
                url.searchParams,
              )
            : freshRead && !exactLogQueryTxid
            ? await freshProofIndexLogHistoryPayload(
                network,
                historyKind,
                url.searchParams,
              )
            : await proofIndexLogHistoryPayload(
                network,
                historyKind,
                url.searchParams,
              ).catch((error) => {
                console.error(
                  `Proof index filtered log read failed: ${errorSummary(error)}`,
                );
                return null;
              });
        if (indexedPayload) {
          const indexedTotal = Number(
            indexedPayload.totalCount ?? indexedPayload.items?.length ?? 0,
          );
          const definitiveEmpty = definitivePinnedLogQueryDisposition(
            indexedPayload.queryDisposition,
          );
          const responsePayload =
            exactLogQueryTxid && indexedTotal === 0 && !definitiveEmpty
              ? await exactLogHistoryMissPayload(
                  indexedPayload,
                  network,
                  exactLogQueryTxid,
                  url.searchParams,
                )
              : indexedPayload;
          jsonResponse(
            response,
            200,
            responsePayload,
            freshRead
              ? FRESH_READ_CACHE_CONTROL
              : EXPENSIVE_READ_CACHE_CONTROL,
          );
          return;
        }
        if (exactLogQueryTxid) {
          throw freshDataUnavailableError(
            "The indexed exact Log lookup is temporarily unavailable.",
          );
        }
        const fallbackPayload = await activityHistoryPayload(
          network,
          historyKind,
          url.searchParams,
          freshRead,
        );
        jsonResponse(
          response,
          200,
          fallbackPayload,
          freshRead
            ? FRESH_READ_CACHE_CONTROL
            : EXPENSIVE_READ_CACHE_CONTROL,
        );
        return;
      }
      if (freshRead) {
        jsonResponse(
          response,
          200,
          await freshProofIndexLogPayload(network),
          FRESH_READ_CACHE_CONTROL,
        );
        return;
      }

      jsonResponse(
        response,
        200,
        await mergedLogActivityPayload(network),
        EXPENSIVE_READ_CACHE_CONTROL,
      );
      return;
    }

    if (
      url.pathname === "/api/v1/activity-history" ||
      url.pathname === "/api/v1/log-history"
    ) {
      const historyKind = String(url.searchParams.get("kind") ?? "")
        .trim()
        .toLowerCase();
      const logHistoryEligibility = proofIndexLogHistoryReadEligibility(
        historyKind,
        url.searchParams,
      );
      const exactLogQueryTxid = /^[0-9a-f]{64}$/u.test(
        logHistoryEligibility.pagination.query,
      )
        ? logHistoryEligibility.pagination.query
        : "";
      if (
        proofIndexReadFeatureEnabled("log-history,activity-history,log") &&
        (network === "livenet" ||
          logHistoryEligibility.eligible ||
          (freshRead && !exactLogQueryTxid))
      ) {
        const indexedPayload =
          network === "livenet" && !freshRead
            ? await stableProofIndexLogHistoryPayload(
                network,
                historyKind,
                url.searchParams,
              )
            : freshRead && !exactLogQueryTxid
            ? await freshProofIndexLogHistoryPayload(
                network,
                historyKind,
                url.searchParams,
              )
            : await proofIndexLogHistoryPayload(
                network,
                historyKind,
                url.searchParams,
              ).catch((error) => {
                console.error(
                  `Proof index log-history read failed: ${errorSummary(error)}`,
                );
                return null;
              });
        if (indexedPayload) {
          const indexedTotal = Number(
            indexedPayload.totalCount ?? indexedPayload.items?.length ?? 0,
          );
          const definitiveEmpty = definitivePinnedLogQueryDisposition(
            indexedPayload.queryDisposition,
          );
          const responsePayload =
            exactLogQueryTxid && indexedTotal === 0 && !definitiveEmpty
              ? await exactLogHistoryMissPayload(
                  indexedPayload,
                  network,
                  exactLogQueryTxid,
                  url.searchParams,
                )
              : indexedPayload;
          jsonResponse(
            response,
            200,
            responsePayload,
            freshRead
              ? FRESH_READ_CACHE_CONTROL
              : EXPENSIVE_READ_CACHE_CONTROL,
          );
          return;
        }
      }
      if (exactLogQueryTxid) {
        throw freshDataUnavailableError(
          "The indexed exact Log lookup is temporarily unavailable.",
        );
      }
      const payload = await activityHistoryPayload(
        network,
        historyKind,
        url.searchParams,
        freshRead,
      );
      shadowProofIndexLogHistory(payload, network, historyKind, url.searchParams);
      jsonResponse(
        response,
        200,
        payload,
        freshRead ? FRESH_READ_CACHE_CONTROL : EXPENSIVE_READ_CACHE_CONTROL,
      );
      return;
    }

    if (url.pathname === "/api/v1/token") {
      const tokenScope = normalizeTokenScope(
        url.searchParams.get("asset") ??
          url.searchParams.get("tokenId") ??
          url.searchParams.get("ticker") ??
          "",
      );
      const strictRecoveryAddresses = recoveryAddressesFromSearchParams(
        url.searchParams,
        network,
      );
      const recoveryAddresses =
        strictRecoveryAddresses.length > 0
          ? strictRecoveryAddresses
          : recoveryAddressHintsFromSearchParams(url.searchParams, network);
      const walletReadRequested = /^(?:1|true|yes)$/iu.test(
        String(url.searchParams.get("wallet") ?? "").trim(),
      );
      const walletScoped =
        recoveryAddresses.length > 0 && walletReadRequested;
      if (walletReadRequested && recoveryAddresses.length === 0) {
        errorResponse(
          response,
          400,
          "Wallet-scoped credit read requires a valid address.",
        );
        return;
      }
      if (!walletScoped && recoveryAddresses.length === 0) {
        const cachedPayload = await currentExactTipTokenPayloadForRead(
          network,
          tokenScope,
          freshRead
            ? "token-state-fresh-exact-tip-memory"
            : "token-state-exact-tip-memory",
          canonicalReadGate,
        );
        if (cachedPayload) {
          const responsePayload = await tokenReadResponsePayload(
            cachedPayload,
            network,
            tokenScope,
            { requireWorkListingAuthority: freshRead },
          );
          jsonResponse(
            response,
            200,
            responsePayload,
            TOKEN_READ_CACHE_CONTROL,
          );
          return;
        }
      }
      if (!walletScoped && recoveryAddresses.length === 0 && freshRead) {
        const canonicalSummaryPayload =
          await currentCanonicalTokenSummaryPayloadForFreshRead(
            network,
            tokenScope,
            canonicalReadGate,
          );
        if (canonicalSummaryPayload) {
          const responsePayload = await tokenReadResponsePayload(
            canonicalSummaryPayload,
            network,
            tokenScope,
            { requireWorkListingAuthority: true },
          );
          jsonResponse(
            response,
            200,
            responsePayload,
            TOKEN_READ_CACHE_CONTROL,
          );
          return;
        }
      }
      if (
        !walletScoped &&
        recoveryAddresses.length === 0 &&
        proofIndexReadFeatureEnabled("token-state,token-default,token") &&
        proofIndexTokenReadEligibility(tokenScope, url.searchParams).eligible
      ) {
        const indexedPayload = await currentProofIndexTokenPayloadForRead(
          network,
          tokenScope,
          "token-state",
          freshRead ? TOKEN_SCOPED_FRESH_WAIT_MS : 10_000,
        );
        const indexedPayloadExact = tokenPayloadMatchesCanonicalGate(
          indexedPayload,
          canonicalReadGate,
        );
        if (indexedPayload && (!freshRead || indexedPayloadExact)) {
          const responsePayload = await tokenReadResponsePayload(
            indexedPayload,
            network,
            tokenScope,
            { requireWorkListingAuthority: freshRead },
          );
          cacheTokenPayload(network, tokenScope, responsePayload, {
            exactTipValidated: indexedPayloadExact,
          });
          jsonResponse(
            response,
            200,
            responsePayload,
            TOKEN_READ_CACHE_CONTROL,
          );
          return;
        }
      }
      if (!walletScoped && recoveryAddresses.length === 0 && freshRead) {
        const cachedPayload = await currentMemoryTokenPayloadForRead(
          network,
          tokenScope,
          "token-state-fresh-memory",
        );
        if (
          cachedPayload &&
          tokenPayloadMatchesCanonicalGate(cachedPayload, canonicalReadGate)
        ) {
          const responsePayload = await tokenReadResponsePayload(
            cachedPayload,
            network,
            tokenScope,
            { requireWorkListingAuthority: true },
          );
          jsonResponse(
            response,
            200,
            responsePayload,
            TOKEN_READ_CACHE_CONTROL,
          );
          return;
        }
      }
      if (!walletScoped && recoveryAddresses.length === 0 && freshRead) {
        const fallbackPayload = await cachedTokenPayloadFallbackForRead(
          network,
          tokenScope,
          "token-state-fresh-cache",
        );
        if (
          fallbackPayload &&
          tokenPayloadMatchesCanonicalGate(fallbackPayload, canonicalReadGate)
        ) {
          const responsePayload = await tokenReadResponsePayload(
            fallbackPayload,
            network,
            tokenScope,
            { requireWorkListingAuthority: true },
          );
          jsonResponse(
            response,
            200,
            responsePayload,
            TOKEN_READ_CACHE_CONTROL,
          );
          return;
        }
        throw freshDataUnavailableError(
          `Fresh credit state is still catching up for ${tokenScope || "all"}.`,
        );
      }
      if (walletScoped) {
        const walletPayload = await walletScopedTokenPayload(
          network,
          tokenScope,
          recoveryAddresses,
          {
            allowLastGood: freshRead && serveFreshLastGood,
            canonicalReadGate,
            requireCurrent: freshRead,
          },
        );
        jsonResponse(
          response,
          200,
          await tokenReadResponsePayload(
            walletPayload,
            network,
            tokenScope,
          ),
          freshRead ? FRESH_READ_CACHE_CONTROL : TOKEN_READ_CACHE_CONTROL,
        );
        return;
      }
      const tokenFreshRead = walletScoped ? false : freshRead;
      const reconcileTokenListings = tokenFreshRead && !walletScoped;
      const payload = await tokenPayloadForRead(network, tokenScope, tokenFreshRead, {
        reconcileListingStatus: reconcileTokenListings,
        reconcileSpendable: reconcileTokenListings,
        recoveryAddresses,
        liveWorkWaitMs:
          walletScoped && tokenScope === WORK_TOKEN_ID
            ? WORK_TOKEN_LIVE_RECOVERY_WAIT_MS
            : recoveryAddresses.length > 0
            ? TOKEN_ADDRESS_HINT_LIVE_WAIT_MS
            : undefined,
        recoverWorkSalesOnly: walletScoped && tokenScope === WORK_TOKEN_ID,
      });
      jsonResponse(
        response,
        200,
        await tokenReadResponsePayload(payload, network, tokenScope, {
          requireWorkListingAuthority: tokenFreshRead,
        }),
        tokenFreshRead ? FRESH_READ_CACHE_CONTROL : TOKEN_READ_CACHE_CONTROL,
      );
      return;
    }

    if (url.pathname === "/api/v1/token-summary") {
      const tokenScope = normalizeTokenScope(
        url.searchParams.get("asset") ??
          url.searchParams.get("tokenId") ??
          url.searchParams.get("ticker") ??
          "",
      );
      const strictRecoveryAddresses = recoveryAddressesFromSearchParams(
        url.searchParams,
        network,
      );
      const recoveryAddresses =
        strictRecoveryAddresses.length > 0
          ? strictRecoveryAddresses
          : recoveryAddressHintsFromSearchParams(url.searchParams, network);
      const walletReadRequested = /^(?:1|true|yes)$/iu.test(
        String(url.searchParams.get("wallet") ?? "").trim(),
      );
      const walletScoped =
        recoveryAddresses.length > 0 && walletReadRequested;
      const compactRead = booleanSearchParam(url.searchParams, "compact");
      if (walletReadRequested && recoveryAddresses.length === 0) {
        errorResponse(
          response,
          400,
          "Wallet-scoped credit summary requires a valid address.",
        );
        return;
      }
      const rawTokenSummary = walletScoped
        ? await walletScopedTokenSummaryPayload(
            network,
            tokenScope,
            recoveryAddresses,
            {
              allowLastGood: freshRead && serveFreshLastGood,
              canonicalReadGate,
              requireCurrent: freshRead,
            },
          )
        : await tokenSummaryPayload(network, tokenScope, freshRead, {
            recoveryAddresses,
          });
      const tokenSummary =
        !walletScoped && compactRead
          ? compactTokenSummaryPayload(rawTokenSummary, tokenScope, {
              includeAllScopedListings: false,
              compactMarketRecords: true,
            })
          : rawTokenSummary;
      jsonResponse(
        response,
        200,
        walletScoped
          ? tokenSummary
          : await summaryPayloadWithCanonicalProvenance(
              tokenSummary,
              network,
              freshRead,
              `token-summary:${tokenScope || "all"}`,
            ),
        freshRead ? FRESH_READ_CACHE_CONTROL : TOKEN_READ_CACHE_CONTROL,
      );
      return;
    }

    if (url.pathname === "/api/v1/token-history") {
      const tokenScope = normalizeTokenScope(
        url.searchParams.get("asset") ??
          url.searchParams.get("tokenId") ??
          url.searchParams.get("ticker") ??
          "",
      );
      const historyKind = String(url.searchParams.get("kind") ?? "mints")
        .trim()
        .toLowerCase();
      if (network === "livenet" && historyKind === "listings") {
        const payload = await completeTokenListingHistoryPayload(
          network, tokenScope, url.searchParams,
        );
        jsonResponse(
          response, 200, payload,
          freshRead ? FRESH_READ_CACHE_CONTROL : TOKEN_READ_CACHE_CONTROL,
        );
        return;
      }
      const exactProofIndexTxids = recoveryTxidsFromSearchParams(
        url.searchParams,
      );
      const proofIndexTokenHistoryEligibility =
        proofIndexTokenHistoryReadEligibility(
          tokenScope,
          historyKind,
          url.searchParams,
        );
      const exactProofIndexHistoryRead =
        exactProofIndexTxids.length > 0 &&
        proofIndexTokenHistoryEligibility.eligible;
      const proofIndexMintHistoryRead =
        historyKind === "mints" &&
        proofIndexTokenHistoryEligibility.eligible;
      const freshProofIndexTokenHistoryRead =
        freshRead &&
        !exactProofIndexHistoryRead &&
        !proofIndexMintHistoryRead &&
        proofIndexTokenHistoryEligibility.eligible;
      const tokenHistoryRecoveryTxids =
        exactProofIndexHistoryRead ? [] : exactProofIndexTxids;
      const needsCreditNetworkValueOverlay =
        network === "livenet" &&
        Boolean(tokenScope) &&
        !BOND_TOKEN_IDS.has(tokenScope) &&
        tokenHistoryKindNeedsCreditNetworkValueOverlay(historyKind);
      const addressScopedMarketHistory =
        [
          "closedlistings",
          "closed-listings",
          "closed_listing",
          "closed-listing",
          "listings",
          "market-listings",
          "market-seals",
          "market-sales",
          "marketlog",
          "market-log",
          "market_log",
          "tokenmarketlog",
          "token-market-log",
          "sales",
        ].includes(historyKind) &&
        recoveryAddressHintsFromSearchParams(url.searchParams, network).length > 0;
      const pendingWorkMarketFastPage =
        tokenScope === WORK_TOKEN_ID &&
        network === "livenet" &&
        (exactProofIndexTxids.length > 0 || addressScopedMarketHistory)
          ? await pendingWorkMarketHistoryPage(
              network,
              tokenScope,
              historyKind,
              url.searchParams,
            ).catch((error) => {
              console.error(
                `Pending WORK market token-history fast recovery failed: ${errorSummary(error)}`,
              );
              return null;
            })
          : null;
      if (pendingWorkMarketFastPage) {
        const responsePayload = tokenMarketActivityHistoryPageWithAuthority(
          await tokenHistoryPageWithCanonicalWorkAmoV8ListingWitnesses(
            pendingWorkMarketFastPage,
            network,
            tokenScope,
            historyKind,
          ),
          historyKind,
          false,
        );
        jsonResponse(
          response,
          200,
          responsePayload,
          freshRead ? FRESH_READ_CACHE_CONTROL : TOKEN_READ_CACHE_CONTROL,
        );
        return;
      }
      if (
        (!freshRead ||
          exactProofIndexHistoryRead ||
          proofIndexMintHistoryRead ||
          freshProofIndexTokenHistoryRead) &&
        !(network === "livenet" && historyKind === "listings") &&
        tokenHistoryRecoveryTxids.length === 0 &&
        !addressScopedMarketHistory &&
        proofIndexReadFeatureEnabled("token-history,token") &&
        proofIndexTokenHistoryEligibility.eligible
      ) {
        const indexedPayload = await payloadWithFallbackAfterMs(
          proofIndexTokenHistoryPayload(
            network,
            tokenScope,
            historyKind,
            url.searchParams,
          ).catch((error) => {
            console.error(
              `Proof index token-history read failed: ${errorSummary(error)}`,
            );
            return null;
          }),
          null,
          SUMMARY_PROOF_INDEX_READ_WAIT_MS,
        );
        if (indexedPayload) {
          const canonicalValuePayload =
            needsCreditNetworkValueOverlay
            ? await tokenHistoryPageWithCanonicalCreditValueOverlay(
                indexedPayload,
                network,
                tokenScope,
                historyKind,
                url.searchParams,
              )
            : indexedPayload;
          const proofIndexHistoryFreshEnough =
            !freshProofIndexTokenHistoryRead ||
            (await payloadWithFallbackAfterMs(
              proofIndexPayloadCoversConfirmedTip(
                canonicalValuePayload,
                network,
                `token-history:${tokenScope || "all"}:${historyKind}`,
              ),
              false,
              2_500,
            ));
          if (
            proofIndexHistoryFreshEnough &&
            !exactTransferHistoryNeedsCanonicalRecovery(
              canonicalValuePayload,
              tokenScope,
              historyKind,
              url.searchParams,
            )
          ) {
            const responsePayload = tokenMarketActivityHistoryPageWithAuthority(
              await tokenHistoryPageWithCanonicalWorkAmoV8ListingWitnesses(
                canonicalValuePayload,
                network,
                tokenScope,
                historyKind,
              ),
              historyKind,
              canonicalValuePayload.complete !== false &&
                canonicalValuePayload.preview !== true,
            );
            jsonResponse(
              response,
              200,
              responsePayload,
              freshProofIndexTokenHistoryRead
                ? FRESH_READ_CACHE_CONTROL
                : TOKEN_READ_CACHE_CONTROL,
            );
            return;
          }
        }
      }
      const payload = await tokenHistoryPayload(
        network,
        tokenScope,
        historyKind,
        url.searchParams,
        freshRead,
      );
      const responsePayload =
        await tokenHistoryPageWithCanonicalWorkAmoV8ListingWitnesses(
          payload,
          network,
          tokenScope,
          historyKind,
        );
      shadowProofIndexTokenHistory(
        responsePayload,
        network,
        tokenScope,
        historyKind,
        url.searchParams,
      );
      jsonResponse(
        response,
        200,
        responsePayload,
        freshRead ? FRESH_READ_CACHE_CONTROL : TOKEN_READ_CACHE_CONTROL,
      );
      return;
    }

    if (url.pathname === "/api/v1/work-floor") {
      if (freshRead) {
        jsonResponse(
          response,
          200,
          await withWorkMarketplaceV4Metadata(
            await summaryPayloadWithCanonicalProvenance(
              await cachedWorkFloorPayload(network, true),
              network,
              true,
              "work-floor",
            ),
            network,
          ),
          FRESH_READ_CACHE_CONTROL,
        );
      } else {
        jsonResponse(
          response,
          200,
          await withWorkMarketplaceV4Metadata(
            await summaryPayloadWithCanonicalProvenance(
              await cachedWorkFloorPayload(network, false),
              network,
              false,
              "work-floor",
            ),
            network,
          ),
          READ_CACHE_CONTROL,
        );
      }
      return;
    }

    if (url.pathname === "/api/v1/work-summary") {
      const compactRead = booleanSearchParam(url.searchParams, "compact");
      if (
        !freshRead &&
        network !== "livenet" &&
        proofIndexReadFeatureEnabled("work-summary,summary,summaries")
      ) {
        const indexedPayload = await currentProofIndexSummarySnapshotPayload(
          network,
          "workSummary",
          "work-summary",
        );
        if (indexedPayload) {
          const responsePayload = await workSummaryWithCurrentBtcUsd(
            {
              ...indexedPayload,
              floor: await workFloorWithSummaryMarketOverlay(
                indexedPayload.floor,
                network,
                false,
                indexedPayload.token,
              ),
            },
            network,
            false,
          );
          jsonResponse(
            response,
            200,
            compactRead
              ? compactWorkSummaryPayload(responsePayload)
              : responsePayload,
            READ_CACHE_CONTROL,
          );
          return;
        }
      }
      const rawWorkSummary = await workSummaryPayload(network, freshRead);
      const workSummary = compactRead
        ? compactWorkSummaryPayload(rawWorkSummary)
        : rawWorkSummary;
      jsonResponse(
        response,
        200,
        await withWorkMarketplaceV4Metadata(
          await summaryPayloadWithCanonicalProvenance(
            workSummary,
            network,
            freshRead,
            "work-summary",
          ),
          network,
        ),
        freshRead ? FRESH_READ_CACHE_CONTROL : READ_CACHE_CONTROL,
      );
      return;
    }

    if (url.pathname === "/api/v1/marketplace-summary") {
      const compactRead = booleanSearchParam(url.searchParams, "compact");
      const rawMarketplaceSummary =
        await marketplaceSummaryPayload(network, freshRead);
      const marketplaceSummary = compactRead
        ? compactMarketplaceSummaryReadPayload(rawMarketplaceSummary)
        : rawMarketplaceSummary;
      jsonResponse(
        response,
        200,
        await withWorkMarketplaceV4Metadata(
          await summaryPayloadWithCanonicalProvenance(
            marketplaceSummary,
            network,
            freshRead,
            "marketplace-summary",
          ),
          network,
        ),
        freshRead ? FRESH_READ_CACHE_CONTROL : READ_CACHE_CONTROL,
      );
      return;
    }

    if (url.pathname === "/api/v1/infinity-summary") {
      jsonResponse(
        response,
        200,
        await summaryPayloadWithCanonicalProvenance(
          await infinitySummaryPayload(network, freshRead),
          network,
          freshRead,
          "infinity-summary",
        ),
        freshRead ? FRESH_READ_CACHE_CONTROL : READ_CACHE_CONTROL,
      );
      return;
    }

    if (url.pathname === "/api/v1/inception-summary") {
      jsonResponse(
        response,
        200,
        await summaryPayloadWithCanonicalProvenance(
          await inceptionSummaryPayload(network, freshRead),
          network,
          freshRead,
          "inception-summary",
        ),
        freshRead ? FRESH_READ_CACHE_CONTROL : READ_CACHE_CONTROL,
      );
      return;
    }

    if (url.pathname === "/api/v1/growth-summary") {
      if (
        !freshRead &&
        network !== "livenet" &&
        proofIndexReadFeatureEnabled("growth-summary,summary,summaries")
      ) {
        const indexedPayload = await currentProofIndexSummarySnapshotPayload(
          network,
          "growthSummary",
          "growth-summary",
        );
        if (indexedPayload) {
          jsonResponse(
            response,
            200,
            await growthSummaryWithCurrentBtcUsd(
              indexedPayload,
              network,
              false,
            ),
            READ_CACHE_CONTROL,
          );
          return;
        }
      }
      jsonResponse(
        response,
        200,
        await summaryPayloadWithCanonicalProvenance(
          await growthSummaryPayload(network, freshRead),
          network,
          freshRead,
          "growth-summary",
        ),
        freshRead ? FRESH_READ_CACHE_CONTROL : READ_CACHE_CONTROL,
      );
      return;
    }

    if (
      pathParts.length === 4 &&
      pathParts[0] === "api" &&
      pathParts[1] === "v1" &&
      pathParts[2] === "ids"
    ) {
      const id = normalizePowId(decodeURIComponent(pathParts[3]));
      if (!id) {
        errorResponse(response, 400, "Invalid ProofOfWork ID.");
        return;
      }
      let indexedIdRecord;
      try {
        indexedIdRecord = await proofIndexIdRecordPayload(network, id);
      } catch (error) {
        const unavailable = new Error(
          "ProofOfWork ID availability cannot be proven while the index is unavailable.",
        );
        unavailable.statusCode = 503;
        unavailable.details = {
          cause: errorSummary(error),
          code: "ID_AVAILABILITY_UNPROVEN",
          id,
        };
        throw unavailable;
      }
      const requireCurrent = /^(?:1|true|yes)$/iu.test(
        String(url.searchParams.get("current") ?? ""),
      );
      const currentProof = requireCurrent
        ? await proveCurrentIdAbsence(network)
        : null;
      let registry =
        indexedIdRecord ?? {
          indexedAt: new Date().toISOString(),
          listings: [],
          network,
          pendingEvents: [],
          records: [],
          sales: [],
          source: "proof-index:registry-id",
        };
      // Livenet availability is proven by the canonical Core block scan plus
      // the separate live pending check. A cached address-registry fallback
      // must never turn a confirmed DB absence into a green availability claim.
      if (!indexedIdRecord && network !== "livenet") {
        try {
          registry = await safeRegistryPayload(network);
        } catch (error) {
          const unavailable = new Error(
            "ProofOfWork ID availability could not be verified against the live registry.",
          );
          unavailable.statusCode = 503;
          unavailable.details = {
            cause: errorSummary(error),
            code: "ID_AVAILABILITY_UNPROVEN",
            id,
          };
          throw unavailable;
        }
      }
      let records = exactIdRecordsWithIndexedConfirmation(
        registry,
        indexedIdRecord,
        id,
      );
      if (indexedIdRecord) {
        registry = {
          ...registry,
          records,
          source: mergedSourceLabel(registry?.source, indexedIdRecord?.source),
        };
      }
      if (!records.some((record) => record.confirmed === true)) {
        const pendingRegistry =
          currentProof ?? (await proveCurrentIdAbsence(network));
        const livePendingRecords = (Array.isArray(pendingRegistry?.records)
          ? pendingRegistry.records
          : []
        ).filter(
          (record) =>
            record?.confirmed !== true &&
            normalizePowId(String(record?.id ?? "")) === id,
        );
        records = [
          ...records.filter((record) => record?.confirmed === true),
          ...livePendingRecords,
        ];
        registry = {
          ...registry,
          pendingEvents: pendingRegistry?.pendingEvents ?? [],
          records,
          source: mergedSourceLabel(registry?.source, pendingRegistry?.source),
        };
      }
      if (currentProof) {
        registry = {
          ...registry,
          pendingEvents: currentProof.pendingEvents ?? [],
          source: mergedSourceLabel(registry?.source, currentProof?.source),
        };
      }
      const confirmed = records.find((record) => record.confirmed);
      const pending = records.find((record) => !record.confirmed);
      const listings = (Array.isArray(registry.listings) ? registry.listings : [])
        .filter(
          (listing) => normalizePowId(String(listing?.id ?? "")) === id,
        );
      const exactListingIds = new Set(
        listings
          .map((listing) => String(listing?.listingId ?? "").toLowerCase())
          .filter((listingId) => /^[0-9a-f]{64}$/u.test(listingId)),
      );
      const pendingEvents = (Array.isArray(registry.pendingEvents)
        ? registry.pendingEvents
        : []
      ).filter(
        (event) =>
          normalizePowId(String(event?.id ?? "")) === id ||
          exactListingIds.has(String(event?.listingId ?? "").toLowerCase()),
      );
      const sales = (Array.isArray(registry.sales) ? registry.sales : []).filter(
        (sale) => normalizePowId(String(sale?.id ?? "")) === id,
      );
      const lifecycleTxids = new Set([
        ...listings.map((listing) => String(listing?.listingId ?? "").toLowerCase()),
        ...sales.map((sale) => String(sale?.txid ?? "").toLowerCase()),
      ]);
      const activity = (Array.isArray(registry.activity)
        ? registry.activity
        : []
      ).filter(
        (item) =>
          normalizePowId(String(item?.id ?? "")) === id ||
          lifecycleTxids.has(String(item?.txid ?? "").toLowerCase()) ||
          exactListingIds.has(String(item?.listingId ?? "").toLowerCase()),
      );
      jsonResponse(response, 200, {
        activity,
        id,
        indexedAt: registry.indexedAt,
        listings,
        network,
        pendingEvents,
        record: confirmed ?? pending ?? null,
        records,
        routable: Boolean(confirmed),
        sales,
        source:
          indexedIdRecord && !requireCurrent
            ? "proof-index:registry-id"
            : registry.source,
        status: confirmed ? "confirmed" : pending ? "pending" : "available",
      });
      return;
    }

    if (
      pathParts.length === 5 &&
      pathParts[0] === "api" &&
      pathParts[1] === "v1" &&
      pathParts[2] === "address" &&
      pathParts[4] === "utxo"
    ) {
      const address = decodeURIComponent(pathParts[3]);
      if (!isValidBitcoinAddress(address, network)) {
        errorResponse(response, 400, "Invalid address for network.");
        return;
      }

      jsonResponse(
        response,
        200,
        await addressUtxoPayload(address, network),
        "no-store",
      );
      return;
    }

    if (
      pathParts.length >= 5 &&
      pathParts.length <= 7 &&
      pathParts[0] === "api" &&
      pathParts[1] === "v1" &&
      pathParts[2] === "address" &&
      pathParts[4] === "txs"
    ) {
      const address = decodeURIComponent(pathParts[3]);
      const addressPath = pathParts.slice(4).join("/");
      if (!isValidBitcoinAddress(address, network)) {
        errorResponse(response, 400, "Invalid address for network.");
        return;
      }
      if (
        !/^txs(?:\/(?:mempool|chain(?:\/[0-9a-f]{64})?))?$/iu.test(
          addressPath,
        )
      ) {
        errorResponse(response, 400, "Invalid address transaction path.");
        return;
      }

      jsonResponse(
        response,
        200,
        addressPath === "txs/mempool"
          ? await fetchAddressMempoolTransactions(address, network)
          : await fetchAddressTransactionsPage(address, network, addressPath, {
              allowCanonicalFallback: authenticatedLoopbackRead,
              forceCanonicalFallback: authenticatedLoopbackRead,
            }),
        "no-store",
      );
      return;
    }

    if (
      pathParts.length === 5 &&
      pathParts[0] === "api" &&
      pathParts[1] === "v1" &&
      pathParts[2] === "address" &&
      pathParts[4] === "mail"
    ) {
      const address = decodeURIComponent(pathParts[3]);
      if (!isValidBitcoinAddress(address, network)) {
        errorResponse(response, 400, "Invalid address for network.");
        return;
      }

      jsonResponse(
        response,
        200,
        await mailPayload(address, network, { fresh: freshRead }),
        "public, max-age=10",
      );
      return;
    }

    if (
      pathParts.length === 5 &&
      pathParts[0] === "api" &&
      pathParts[1] === "v1" &&
      pathParts[2] === "tx" &&
      pathParts[4] === "hex"
    ) {
      const txid = pathParts[3].toLowerCase();
      if (!/^[0-9a-f]{64}$/u.test(txid)) {
        errorResponse(response, 400, "Invalid txid.");
        return;
      }

      jsonResponse(
        response,
        200,
        await txHexPayload(txid, network),
        "no-store",
      );
      return;
    }

    if (
      pathParts.length === 5 &&
      pathParts[0] === "api" &&
      pathParts[1] === "v1" &&
      pathParts[2] === "tx" &&
      pathParts[4] === "status"
    ) {
      const txid = pathParts[3].toLowerCase();
      if (!/^[0-9a-f]{64}$/u.test(txid)) {
        errorResponse(response, 400, "Invalid txid.");
        return;
      }

      jsonResponse(
        response,
        200,
        await txStatusPayload(txid, network),
        "no-store",
      );
      return;
    }

    if (
      pathParts.length === 6 &&
      pathParts[0] === "api" &&
      pathParts[1] === "v1" &&
      pathParts[2] === "tx" &&
      pathParts[4] === "outspend"
    ) {
      const txid = pathParts[3].toLowerCase();
      const vout = Number(pathParts[5]);
      if (!/^[0-9a-f]{64}$/u.test(txid)) {
        errorResponse(response, 400, "Invalid txid.");
        return;
      }
      if (!Number.isSafeInteger(vout) || vout < 0) {
        errorResponse(response, 400, "Invalid output index.");
        return;
      }

      jsonResponse(
        response,
        200,
        await txOutspendPayload(txid, vout, network),
        "no-store",
      );
      return;
    }

    if (
      pathParts.length === 4 &&
      pathParts[0] === "api" &&
      pathParts[1] === "v1" &&
      pathParts[2] === "tx"
    ) {
      const txid = pathParts[3].toLowerCase();
      if (!/^[0-9a-f]{64}$/u.test(txid)) {
        errorResponse(response, 400, "Invalid txid.");
        return;
      }

      const payload = await txPayload(txid, network);
      if (!payload.tx) {
        errorResponse(response, 404, "Transaction not found.");
        return;
      }

      jsonResponse(response, 200, payload, "no-store");
      return;
    }

    errorResponse(response, 404, "Not found.");
  } catch (error) {
    const statusCode =
      error && typeof error === "object" && Number.isInteger(error.statusCode)
        ? error.statusCode
        : 500;
    if (statusCode === 429) {
      response.setHeader(
        "Retry-After",
        String(Math.max(1, Math.ceil(BROADCAST_RATE_WINDOW_MS / 1000))),
      );
    }
    if (statusCode >= 500) {
      console.error(
        `${request.method ?? "GET"} ${url.pathname} failed:`,
        error instanceof Error ? error.stack ?? error.message : error,
      );
    }
    errorResponse(
      response,
      statusCode,
      error instanceof Error ? error.message : "Unexpected server error.",
      error && typeof error === "object" ? error.details : undefined,
    );
  }
}

const server = http.createServer((request, response) => {
  void handleRequest(request, response);
});
server.headersTimeout = HTTP_HEADERS_TIMEOUT_MS;
server.requestTimeout = HTTP_REQUEST_TIMEOUT_MS;

function scheduleWarmJsonCache(cacheKey, producer, ttlMs, staleMs, delayMs) {
  const delay = Math.max(0, Number(delayMs) || 0);
  setTimeout(() => {
    warmJsonCache(cacheKey, producer, ttlMs, staleMs);
  }, delay);
}

function prewarmExpensiveReadCaches() {
  if (!ENABLE_STARTUP_EXPENSIVE_PREWARM) {
    return;
  }

  BACKGROUND_REFRESH_LAST_STARTED.set("token:livenet:", Date.now());
  BACKGROUND_REFRESH_LAST_STARTED.set(
    `token:livenet:${WORK_TOKEN_ID}`,
    Date.now(),
  );
  setTimeout(() => {
    refreshCanonicalLedgerPayloadInBackground("livenet", false);
  }, BACKGROUND_STARTUP_REFRESH_DELAY_MS);
}

server.listen(PORT, HOST, () => {
  console.log(`ProofOfWork OP_RETURN API listening on http://${HOST}:${PORT}`);
  console.log(`Mainnet mempool source: ${MEMPOOL_BASE_MAINNET}`);
  void pruneGeneratedPersistedCacheTemps();
  prewarmExpensiveReadCaches();
});
